(window.QUESTIONS_PARTS = window.QUESTIONS_PARTS || {})["md6"] = [{"id":"md6-105-1-1","subject":"md6","topic":"麻醉-呼吸道與監視","meta":"105年第1次第1題","year":105,"session":1,"number":1,"question":"下列關於心電圖（electrocardiogram,ECG or EKG）監測的敘述，何者錯誤？","options":["(A) 手術麻醉中病患心電圖的監測是必要項目，也是標準監測中的一項","(B) 心電圖監測的主要目的是要偵測出會影響心臟機械性功能的電氣性障礙（electrical disturbances）","(C) 對於心律不整和心肌缺血的正確診斷，有助於正確有效的臨床處置之擬定與執行","(D) 由於電導（ECG leads）的簡化，大部分的心律不整和心肌缺血無法由心電圖監測器診斷發現"],"answer":3,"image":""},{"id":"md6-105-1-2","subject":"md6","topic":"麻醉-呼吸道與監視","meta":"105年第1次第2題","year":105,"session":1,"number":2,"question":"記錄標準心電圖電位時，導程（leads）放在身體的正確位置為何？","options":["(A) Lead I：left arm-left leg","(B) Lead II：left leg-right arm","(C) Lead III：right leg-left arm","(D) aVF：right arm-left arm"],"answer":1,"image":""},{"id":"md6-105-1-3","subject":"md6","topic":"麻醉-麻醉藥理","meta":"105年第1次第3題","year":105,"session":1,"number":3,"question":"局部麻醉藥物lidocaine主要經由阻斷何種離子進入細胞以抑制神經傳導？","options":["(A) 鈉","(B) 鈣","(C) 鉀","(D) 氯"],"answer":0,"image":""},{"id":"md6-105-1-4","subject":"md6","topic":"麻醉-麻醉藥理","meta":"105年第1次第4題","year":105,"session":1,"number":4,"question":"下列有關isoflurane可造成病人不動（immobility）的藥理機制之敘述，何者錯誤？","options":["(A) 主要是作用於脊髓（spinal cord），不是作用於大腦","(B) 需要比引起失去意識狀態還高的isoflurane濃度才能引起immobility","(C) 主要透過作用於GABA接受器達到immobility的作用","(D) 與isoflurane抑制nocifensive withdrawal reflex arc有關"],"answer":2,"image":""},{"id":"md6-105-1-5","subject":"md6","topic":"麻醉-呼吸道與監視","meta":"105年第1次第5題","year":105,"session":1,"number":5,"question":"四十五歲肺功能正常男性患者，因右中肺葉腫瘤預計接受肺葉切除手術，有關麻醉評估及考慮之敘述，下列何者正確？","options":["(A) 影響術後FEV1（forced expiratory volume in first second）最多的就是右肺中葉","(B) 預計術後FEV1如大於原有的40%，應可在手術室拔除氣管內管","(C) 術中或術後少見心律不整現象","(D) 單肺呼吸（one lung ventilation）時使用較大潮氣量（tidal volume），能增加血中含氧量並減少呼吸傷害"],"answer":1,"image":""},{"id":"md6-105-1-6","subject":"md6","topic":"麻醉-呼吸道與監視","meta":"105年第1次第6題","year":105,"session":1,"number":6,"question":"有關二尖瓣置換手術（mitral valve replacement）麻醉之敘述，下列何者正確？","options":["(A) 手術中須以葉克膜（ECMO：extracoporal membrane oxygenator）維持體外循環，方可打開心臟進行手術","(B) 氣體麻醉劑會抑制心肌收縮，臨床上不使用於開心手術麻醉","(C) 脫離體外循環之後，如欲處理右心室衰竭，宜調高呼吸氧氣濃度，並調整動脈血液中二氧化碳分壓約25～30 mmHg，防止肺動脈收縮","(D) 術前腎功能已經異常的心臟手術病人，其死亡率為腎功能正常病人的兩倍"],"answer":2,"image":""},{"id":"md6-105-1-7","subject":"md6","topic":"麻醉-特殊麻醉與疼痛","meta":"105年第1次第7題","year":105,"session":1,"number":7,"question":"下列有關慢性非癌症疼痛的多重治療方式之敘述，何者錯誤？","options":["(A) 心理醫師的行為治療可幫助下背痛病患","(B) 復健對慢性非癌症疼痛而言，主動運動較被動按摩效果較佳","(C) 職能治療對疼痛治療也有幫助","(D) 麻醉醫師就只是利用神經阻斷與藥物來治療病人"],"answer":3,"image":""},{"id":"md6-105-1-8","subject":"md6","topic":"麻醉-呼吸道與監視","meta":"105年第1次第8題","year":105,"session":1,"number":8,"question":"一位60歲男性過去有心臟病史，因發燒及休克被送至加護病房。心電圖監測顯示心跳為每分鐘160下，呈現窄且規則的QRS波的型態（regular narrow QRS complex），經給予adenosine 6 mg快速靜脈注射。注射後5秒，心電圖監測器上顯示QRS波暫時減少或消失，但p波未曾間斷，仍規則以每分鐘160的速度出現，再過5秒，心電圖又回到如同注射adenosine前一樣每分鐘160下regular narrow QRS complex狀態。則下列過速心律中，此患者的心律最可能為：","options":["(A) ventricular tachycardia","(B) atrial fibrillation with rapid ventricular response","(C) atrial tachycardia","(D) paroxysmal supra-ventricular tachycardia"],"answer":3,"image":""},{"id":"md6-105-1-9","subject":"md6","topic":"眼科-視網膜葡萄膜","meta":"105年第1次第9題","year":105,"session":1,"number":9,"question":"有關糖尿病視網膜病變（diabetic retinopathy）之組織病理變化，下列何者錯誤？","options":["(A) 微血管基底膜變薄（thinning of the basement membrane）","(B) 微小血管阻塞（microvascular occlusion）","(C) 微血管外被細胞喪失（loss of pericyte）","(D) 血管新生（neovascularization）"],"answer":0,"image":""},{"id":"md6-105-1-10","subject":"md6","topic":"眼科-視網膜葡萄膜","meta":"105年第1次第10題","year":105,"session":1,"number":10,"question":"後天免疫缺乏症候群（AIDS）的病人，眼部最常見的伺機性感染（opportunistic infection）為何？","options":["(A) 卡波西氏肉瘤（Kaposi’s sarcoma）","(B) 巨細胞病毒網膜炎（cytomegalovirus retinitis）","(C) 隱球菌脈絡膜炎（cryptococcal choroiditis）","(D) 肺囊蟲脈絡膜炎（pneumocystis choroiditis）"],"answer":1,"image":""},{"id":"md6-105-1-11","subject":"md6","topic":"眼科-角膜結膜眼瞼眼窩","meta":"105年第1次第11題","year":105,"session":1,"number":11,"question":"18歲男性平時配戴長戴型隱形眼鏡。某假日去魚池釣魚，遭濺出之池水潑及右眼，該君不以為意，也沒有更換隱形眼鏡。兩天後右眼開始有異物感，到西藥房買眼藥水點用未見改善。該君遂到附近診所就醫，由於懷疑感染，眼科醫師給予諾氟沙星（Norfloxacin）抗生素眼藥水。然而治療效果並不顯著，右眼視力開始下降，且眼睛非常痛。數周後病患至某院急診就醫，細隙燈生體顯微鏡檢查可見角膜有環狀浸潤（ring infiltrates）如下圖，最有可能之致病原為：","options":["(A) 麴菌（Aspergillus）","(B) 白色念珠菌（Candida albicans）","(C) 棘口阿米巴（Acanthamoeba）","(D) 微孢子蟲（Microsporidia）"],"answer":2,"image":"md6-105-1-11.jpeg"},{"id":"md6-105-1-12","subject":"md6","topic":"眼科-水晶體青光眼","meta":"105年第1次第12題","year":105,"session":1,"number":12,"question":"下列何種全身性疾病較不會導致白內障？","options":["(A) 糖尿病（diabetes mellitus）","(B) 高血壓（hypertension）","(C) 副甲狀腺機能不足（hypoparathyroidism）","(D) 異位性皮膚炎（atopic dermatitis）"],"answer":1,"image":""},{"id":"md6-105-1-13","subject":"md6","topic":"眼科-屈光斜弱視","meta":"105年第1次第13題","year":105,"session":1,"number":13,"question":"史奈倫（Snellen）氏E字視力表20/20視標的字體大小，相對於六公尺遠眼睛的視角（visual angle）約為多少？","options":["(A) 一分角","(B) 五分角","(C) 二十分角","(D) 六十分角"],"answer":1,"image":""},{"id":"md6-105-1-14","subject":"md6","topic":"眼科-屈光斜弱視","meta":"105年第1次第14題","year":105,"session":1,"number":14,"question":"下列有關光波物理性質之敘述，何者錯誤？","options":["(A) 各種顏色不同波長之光波在真空中的速度是一樣的","(B) 不同波長之色光在一般介質的速度是不一樣的","(C) 光線在一般介質的折射係數（index of refraction）均大於1","(D) ＋1D（屈光度，diopter）透鏡的焦距（focal length）定為一公尺，則＋2D鏡片的焦距為兩公尺"],"answer":3,"image":""},{"id":"md6-105-1-15","subject":"md6","topic":"眼科-角膜結膜眼瞼眼窩","meta":"105年第1次第15題","year":105,"session":1,"number":15,"question":"下列敘述何者為使用肥大細胞安定劑（mast cell stabilizer）眼藥水治療過敏性結膜炎的缺點？","options":["(A) 必須在全然發作前就開始使用","(B) 每小時要點一次","(C) 容易引起氣喘發作","(D) 容易引起青光眼發作"],"answer":0,"image":""},{"id":"md6-105-1-16","subject":"md6","topic":"眼科-角膜結膜眼瞼眼窩","meta":"105年第1次第16題","year":105,"session":1,"number":16,"question":"下列有關眼翳（pterygium）之敘述，何者正確？①侵入角膜之眼翳前緣，有時可見iron（stocker）line ②切除後復發之眼翳，有時比原發病灶更具侵入性 ③眼翳之成因，與高溫及過度暴露於紫外線有關 ④眼翳侵犯顳側角膜多於鼻側角膜","options":["(A) ①④","(B) 僅①②","(C) ①②③","(D) 僅②③"],"answer":2,"image":""},{"id":"md6-105-1-17","subject":"md6","topic":"耳科學","meta":"105年第1次第17題","year":105,"session":1,"number":17,"question":"60歲女性患者，主訴左耳耳塞感2個月，說話時左耳有回音。她感覺躺下來時耳塞感會完全消失。詢問病史，患者最近2個月因肺癌在做化療，體重降了5公斤。耳鏡檢查發現她的左側耳膜會隨著呼吸有規律之震動。最有可能的診斷為何？","options":["(A) 中耳肌陣攣（middle ear myoclonus）","(B) 歐氏管阻塞（blocked eustachian tube）","(C) 美尼爾氏症（Ménière’s disease）","(D) 歐氏管開放症（patulous eustachian tube）"],"answer":3,"image":""},{"id":"md6-105-1-18","subject":"md6","topic":"耳科學","meta":"105年第1次第18題","year":105,"session":1,"number":18,"question":"35歲男性病患，主訴右耳最近幾天聽力下降，且有閉脹感覺，下列何者是應立即先做的檢查？","options":["(A) 耳鏡檢查（otoscopic examination）","(B) 音叉檢查（tuning fork evaluation）","(C) 鼓室圖檢查（tympanometric examination）","(D) 聽力檢查（audiometry）"],"answer":0,"image":""},{"id":"md6-105-1-19","subject":"md6","topic":"鼻科學","meta":"105年第1次第19題","year":105,"session":1,"number":19,"question":"鼻竇感染最常經由下列那一靜脈擴散引起海綿竇栓塞（cavernous thrombosis）？","options":["(A) 角靜脈（angular vein）","(B) 後顏面靜脈（posterior facial vein）","(C) 乙狀竇（sigmoid sinus）","(D) 淺顳靜脈（superficial temporal vein）"],"answer":0,"image":""},{"id":"md6-105-1-20","subject":"md6","topic":"鼻科學","meta":"105年第1次第20題","year":105,"session":1,"number":20,"question":"倒生性乳頭瘤（inverted papilloma）最常發生於鼻腔之何處？","options":["(A) 鼻中隔","(B) 鼻前庭","(C) 鼻側壁","(D) 鼻底部"],"answer":2,"image":""},{"id":"md6-105-1-21","subject":"md6","topic":"喉科學與頭頸腫瘤","meta":"105年第1次第21題","year":105,"session":1,"number":21,"question":"下咽癌患者接受直接喉鏡檢查時發現腫瘤侵犯左側梨形窩（pyriform sinus）及環狀軟骨後區（postcricoid region），並往下延伸至頸部食道，磁核共振掃描呈現甲狀軟骨與環狀軟骨被腫瘤侵犯，但其他檢查並無發現遠端轉移情形，心肺功能無特殊異常；針對此病例，目前最常採用的治療方式為何？","options":["(A) 以器官保留方式給予放射治療後，再給予輔助性化學治療","(B) 以器官保留方式給予同步化學治療與放射治療","(C) 咽喉切除手術後，再給予輔助性標靶治療","(D) 咽喉切除手術後，再給予輔助性化學治療與放射治療"],"answer":3,"image":""},{"id":"md6-105-1-22","subject":"md6","topic":"喉科學與頭頸腫瘤","meta":"105年第1次第22題","year":105,"session":1,"number":22,"question":"60歲男性病患於右側頸部上緣腫塊處接受細針抽取細胞學檢查，結果顯示為轉移性鱗狀上皮細胞癌（metastatic squamous cell carcinoma）。接下去為病患優先安排的檢查最適宜的是：","options":["(A) 耳鼻喉局部檢查","(B) 胃鏡檢查","(C) 胸部電腦斷層檢查","(D) 腹部超音波檢查"],"answer":0,"image":""},{"id":"md6-105-1-23","subject":"md6","topic":"喉科學與頭頸腫瘤","meta":"105年第1次第23題","year":105,"session":1,"number":23,"question":"王小姐平日聲音正常，但常有喉嚨異物感，一個月前接受全身麻醉施行子宮肌瘤切除手術，近一星期喉嚨異物感加重，並有輕微喉嚨痛及聲音沙啞情形，王小姐自訴最近並無感冒症狀，她最可能罹患何種疾病？","options":["(A) 聲帶結節（vocal cord nodules）","(B) 聲帶肉芽腫（vocal cord granulomas）","(C) 聲帶麻痺（vocal cord paralysis）","(D) 瘜肉性聲帶炎（polypoid corditis）"],"answer":1,"image":""},{"id":"md6-105-1-24","subject":"md6","topic":"喉科學與頭頸腫瘤","meta":"105年第1次第24題","year":105,"session":1,"number":24,"question":"承上題，你會優先建議王小姐接受何種檢查或治療？","options":["(A) 直接喉鏡檢查及切片以排除惡性腫瘤可能","(B) 顯微手術切除病變，以免復發或惡化","(C) 使用制酸劑以免加重其症狀","(D) 給予音聲治療，通常在數日內即可獲得療效"],"answer":2,"image":""},{"id":"md6-105-1-25","subject":"md6","topic":"產科-高危險妊娠","meta":"105年第1次第25題","year":105,"session":1,"number":25,"question":"胎兒腹水的嚴重程度與下列何者呈現正相關？","options":["(A) 胎兒貧血的嚴重程度（degree and severity of anemia）","(B) 胎兒的心輸出量（cardiac output）","(C) 胎兒的低蛋白血症（hypoproteinemia）","(D) 胎兒的門脈高壓症（portal hypertension）"],"answer":0,"image":""},{"id":"md6-105-1-26","subject":"md6","topic":"產科-一般產科","meta":"105年第1次第26題","year":105,"session":1,"number":26,"question":"正常懷孕36週內之性生活是：","options":["(A) 妊娠第一個月禁慾","(B) 妊娠最後八週不要有任何性行為","(C) 妊娠中期後不要有任何性行為","(D) 沒有特殊限制"],"answer":3,"image":""},{"id":"md6-105-1-27","subject":"md6","topic":"婦科-生殖內分泌","meta":"105年第1次第27題","year":105,"session":1,"number":27,"question":"一位初產婦妊娠35週，發現血中泌乳激素為180 ng/mL，下列那項措施最適當？","options":["(A) 甲狀腺釋放激素（TRH）試驗","(B) 胸部X光檢查","(C) 血中雌激素檢查","(D) 臨床上觀察追蹤"],"answer":3,"image":""},{"id":"md6-105-1-28","subject":"md6","topic":"產科-高危險妊娠","meta":"105年第1次第28題","year":105,"session":1,"number":28,"question":"於第二或是第三孕期的胎兒觀察到有囊狀水瘤（cystic hygroma）時，應懷疑最可能與下列何種染色體異常有相關性？","options":["(A) triploidy","(B) trisomy 18","(C) trisomy 21","(D) monosomy"],"answer":[2,3],"image":"","answer_note":"更正:第28題答Ｃ、Ｄ給分"},{"id":"md6-105-1-29","subject":"md6","topic":"婦科-手術學與診斷技術","meta":"105年第1次第29題","year":105,"session":1,"number":29,"question":"一位26歲生過三胎之年輕婦女因不正常陰道出血而就醫，其婦科史有裝置子宮避孕器三年。理學檢查經陰道診視發現子宮頸表面平滑，血液自子宮頸口處流出，子宮頸口未見有子宮避孕器之尾巴線；觸診發現子宮大小正常且無觸壓痛之情形。經陰道超音波掃描子宮之情形如下圖，箭頭所指之最適合診斷為：","options":["(A) 子宮內膜增殖（endometrial hyperplasia）","(B) 子宮內膜息肉（endometrial polyp）","(C) 子宮腔內血腫（hematometra）","(D) 子宮內避孕器（intrauterine device）"],"answer":3,"image":"md6-105-1-29.jpeg"},{"id":"md6-105-1-30","subject":"md6","topic":"婦科-尿失禁與骨盆腔脫垂","meta":"105年第1次第30題","year":105,"session":1,"number":30,"question":"一位52歲停經後的婦女，除了主訴頻尿、尿急和急迫性尿失禁外，看起來身體狀況還算健康，針對她的主訴你會建議她接受何種治療最適合？","options":["(A) 放鬆的技巧（relaxation techniques）","(B) 抗乙醯膽鹼藥物（anticholinergic medication）","(C) 白天每小時解小便一次","(D) 膀胱訓練（bladder training）"],"answer":3,"image":""},{"id":"md6-105-1-31","subject":"md6","topic":"婦科-尿失禁與骨盆腔脫垂","meta":"105年第1次第31題","year":105,"session":1,"number":31,"question":"關於肛門失禁（anal incontinence）的敘述，下列何者正確？","options":["(A) 屬於直腸功能失調（disorders of rectal function），不常發生於婦女","(B) 單指表示大便由陰道排出","(C) 是指肛門會不自主的（involuntary）排氣或排便","(D) 大部分的患者會積極尋求醫治"],"answer":2,"image":""},{"id":"md6-105-1-32","subject":"md6","topic":"婦科-生殖道感染與先天異常","meta":"105年第1次第32題","year":105,"session":1,"number":32,"question":"10歲女生被媽媽帶來門診，她媽媽陳述此小女生自小即常尿濕褲子，而自出生後即持續的包尿布，但此小女生卻很健康快樂，在學校也表現的不錯。此一小女生最有可能罹患什麼病？","options":["(A) 應力性尿失禁（stress incontinence）","(B) 尿道憩室（urethral diverticula）","(C) 膀胱陰道瘻管（vesico vaginal fistula）","(D) 輸尿管異位（ectopic ureter）"],"answer":3,"image":""},{"id":"md6-105-1-33","subject":"md6","topic":"婦科-尿失禁與骨盆腔脫垂","meta":"105年第1次第33題","year":105,"session":1,"number":33,"question":"一位68歲的婦女，4年前曾因有脫垂及尿失禁接受過子宮全切除及尿失禁治療手術（burch operation），現在已無尿失禁但主訴有腫塊於陰道口膨出，她認為此一症狀可能與她的下背痛有關聯，因為背痛的症狀在早上最輕微，但隨著時間的變化越來越嚴重。若你為這位婦女行理學檢查時，最可能會發現：","options":["(A) cystocele","(B) rectocele","(C) enterocele","(D) vaginal vault prolapse"],"answer":3,"image":""},{"id":"md6-105-1-34","subject":"md6","topic":"婦科-腫瘤","meta":"105年第1次第34題","year":105,"session":1,"number":34,"question":"52歲更年期婦女，G2P2，體重60公斤，陰道超音波檢查有3公分的右側卵巢單純囊腫（simple cyst），血中CA 125濃度為19 IU/mL。她本人不抽煙。直系家屬中無乳癌或卵巢癌的病人。進一步何者為最恰當的處置？","options":["(A) 做腹部或骨盆腔的電腦斷層檢查","(B) 腹腔鏡手術","(C) 三個月內再做一次陰道超音波","(D) 服用口服避孕藥"],"answer":2,"image":""},{"id":"md6-105-1-35","subject":"md6","topic":"婦科-生殖內分泌","meta":"105年第1次第35題","year":105,"session":1,"number":35,"question":"不孕症婦女接受試管嬰兒治療，打human chorionic gonadotropin（hCG）誘導排卵後，多久進行取卵最適當？","options":["(A) 12至14小時","(B) 24至26小時","(C) 34至36小時","(D) 50至56小時"],"answer":2,"image":""},{"id":"md6-105-1-36","subject":"md6","topic":"婦科-生殖內分泌","meta":"105年第1次第36題","year":105,"session":1,"number":36,"question":"關於卵巢過度刺激症候群（ovarian hyperstimulation syndrome）之敘述，下列何者正確？","options":["(A) 注射human chorionic gonadotropin時，血液中的動情素濃度愈高者，愈不會發生卵巢過度刺激症候群","(B) 為降低卵巢過度刺激症候群的發生，可考慮將胚胎冷凍","(C) 卵巢過度刺激症候群會有腹脹、呼吸困難、腹水等症狀，不會有生命危險","(D) 多囊性卵巢婦女較不會產生卵巢過度刺激症候群"],"answer":1,"image":""},{"id":"md6-105-1-37","subject":"md6","topic":"婦科-生殖內分泌","meta":"105年第1次第37題","year":105,"session":1,"number":37,"question":"50歲婦女，6年前因子宮肌瘤切除子宮，主訴心悸、熱潮紅、失眠，血液中FSH濃度50 mIU/mL，最適當的藥物治療為：","options":["(A) 雌激素","(B) 黃體素","(C) 雌激素合併黃體素","(D) 雄性素"],"answer":0,"image":""},{"id":"md6-105-1-38","subject":"md6","topic":"婦科-生殖內分泌","meta":"105年第1次第38題","year":105,"session":1,"number":38,"question":"32歲陳太太，主訴痛經，性交疼痛且不孕已四年，腹腔鏡下發現如下圖所示，下列何者正確？","options":["(A) 為良性腫瘤，手術後不易復發","(B) 術後用短療程（short protocol）刺激排卵，比長療程受孕率佳","(C) 施行人工授精（IUI）受孕率比試管嬰兒受孕（IVF）率佳","(D) 施行IVF著床率比其他原因不孕者低"],"answer":3,"image":"md6-105-1-38.jpeg"},{"id":"md6-105-1-39","subject":"md6","topic":"婦科-生殖內分泌","meta":"105年第1次第39題","year":105,"session":1,"number":39,"question":"胎盤是內分泌器官，能合成不同的類固醇激素，但胎盤缺乏何種酶，在合成動情素或黃體素時，其前置物（precusors）必經由胎兒或母親提供？","options":["(A) P450 aromatase","(B) 3-β-OH dehydrogenase","(C) P450c 17（17-hydroxylation & 17～20 desmolase）","(D) 21α-hydroxylase"],"answer":2,"image":""},{"id":"md6-105-1-40","subject":"md6","topic":"婦科-生殖內分泌","meta":"105年第1次第40題","year":105,"session":1,"number":40,"question":"想要受孕，下列何者是推算同房時間最好的方法？","options":["(A) 基礎體溫表溫度改變的時間","(B) 尿液測LH（luteinizing hormone）","(C) 血清中progesterone濃度","(D) 子宮頸分泌物變多，變稀時"],"answer":1,"image":""},{"id":"md6-105-1-41","subject":"md6","topic":"婦科-腫瘤","meta":"105年第1次第41題","year":105,"session":1,"number":41,"question":"下列何者不是人類乳突病毒（HPV）的主要高危險型病毒？","options":["(A) HPV 16","(B) HPV 18","(C) HPV 11","(D) HPV 52"],"answer":2,"image":""},{"id":"md6-105-1-42","subject":"md6","topic":"婦科-腫瘤","meta":"105年第1次第42題","year":105,"session":1,"number":42,"question":"關於卵巢癌的敘述，下列何者最不適當？","options":["(A) 最常見的病理型態是卵巢上皮細胞癌（ovarian epithelial carcinoma）","(B) 低惡性度卵巢癌（borderline adenocarcinoma）預後比黏液性卵巢癌（mucinous adenocarcinoma）預後好","(C) 卵巢癌減積手術包含子宮卵巢輸卵管全切除，淋巴結清除，網膜切除則不需要","(D) 理想的卵巢癌減積手術（debulking surgery）是盡量切除原發與轉移的腫瘤"],"answer":2,"image":""},{"id":"md6-105-1-43","subject":"md6","topic":"婦科-腫瘤","meta":"105年第1次第43題","year":105,"session":1,"number":43,"question":"張小姐，32歲，過去未曾懷孕或特殊疾病史，因漿液性卵巢癌接受全子宮及雙側卵巢輸卵管切除、骨盆腔及主動脈旁淋巴結摘除、網膜切除手術，術後病理報告發現右側卵巢、骨盆腔淋巴結、主動脈旁淋巴結腫瘤侵犯，網膜有大於兩公分的腫瘤轉移，但子宮及左側卵巢皆無腫瘤侵犯，肺部電腦斷層未顯示有腫瘤，下列何者敘述正確?","options":["(A) 患者為第IV期卵巢癌患者","(B) 患者為第IIc期","(C) 患者術後應接受化學治療，治療藥物以紫杉醇及含鉑化學治療藥物為首選","(D) 患者術後應接受化學治療，再加上腹部放射治療"],"answer":2,"image":""},{"id":"md6-105-1-44","subject":"md6","topic":"婦科-腫瘤","meta":"105年第1次第44題","year":105,"session":1,"number":44,"question":"一位65歲女性，子宮頸腫瘤大小約5公分，切片證實為鱗狀上皮細胞癌，內診發現骨盆腔組織變硬，攝影檢查顯示輸尿管水腫現象，病人也有坐骨神經痛情形，但一連串之檢查並未發現骨盆腔外轉移之情形，下列何者治療較恰當？","options":["(A) radical hysterectomy+ pelvic lymph node dissection","(B) pelvic exenteration","(C) concurrent chemoradiation therapy（CCRT）","(D) debulking surgry"],"answer":2,"image":""},{"id":"md6-105-1-45","subject":"md6","topic":"婦科-腫瘤","meta":"105年第1次第45題","year":105,"session":1,"number":45,"question":"子宮頸癌病人接受手術後，下列何者不是接受手術後放射線治療的適應症？","options":["(A) 數個淋巴腺轉移","(B) 侵犯子宮頸旁組織（paracervical tissue）","(C) positive surgical margins","(D) 子宮頸腫瘤2 cm"],"answer":3,"image":""},{"id":"md6-105-1-46","subject":"md6","topic":"婦科-腫瘤","meta":"105年第1次第46題","year":105,"session":1,"number":46,"question":"50歲女性，診斷為子宮內膜癌，接受手術，術後病理報告發現癌細胞在子宮肌肉層的侵犯少於1/2，其他部分的病理標本，包含子宮頸、兩側卵巢輸卵管、骨盆腔淋巴結等都沒有發現癌細胞，則依據FIGO（International Federation of Gynecology and Obstetrics）子宮內膜癌分期法，是屬於第幾期？","options":["(A) stage Ia","(B) stage Ib","(C) stage Ic","(D) stage IIa"],"answer":0,"image":""},{"id":"md6-105-1-47","subject":"md6","topic":"產科-一般產科","meta":"105年第1次第47題","year":105,"session":1,"number":47,"question":"一位34歲，懷孕36週婦女，因陰道大量出血前來求診，血壓90/60 mmHg，脈搏120/min，體溫37℃，超音波顯示胎盤位於子宮頸位置。請依此回答下列3題：下列處置何者為佳？","options":["(A) 給予安胎藥","(B) 催生終止妊娠","(C) 指診檢查子宮張開及病變程度","(D) 剖腹生產"],"answer":3,"image":""},{"id":"md6-105-1-48","subject":"md6","topic":"產科-一般產科","meta":"105年第1次第48題","year":105,"session":1,"number":48,"question":"病人最可能之診斷為何？","options":["(A) 胎盤早期剝離","(B) 前置胎盤","(C) 子宮破裂","(D) 早產徵兆"],"answer":1,"image":""},{"id":"md6-105-1-49","subject":"md6","topic":"產科-一般產科","meta":"105年第1次第49題","year":105,"session":1,"number":49,"question":"此時胎兒監測器（fetal monitor）呈現子宮收縮情況，下列何者為最常見？","options":["(A) 子宮持續收縮（tetanus contraction）","(B) 子宮規則收縮","(C) 子宮無收縮","(D) 子宮偶發性收縮"],"answer":1,"image":""},{"id":"md6-105-1-50","subject":"md6","topic":"產科-高危險妊娠","meta":"105年第1次第50題","year":105,"session":1,"number":50,"question":"小穎目前懷孕26週，沒有任何疾病家族史或重大疾病，體重90公斤，身高150公分，例行產檢時發現50克糖水測試（oral glucose challenge test）為151 mg/dL，經醫師建議下又做了一次三小時的100克糖水耐性測試（oral glucose tolerance test），結果分別是空腹105 mg/dL、1小時195 mg/dL、2小時170 mg/dL、3小時145 mg/dL。依此回答下列3題：下列敘述何者錯誤？","options":["(A) 根據第5次世界工作坊會議（fifth international workshop conference）的標準，小穎已符合妊娠糖尿病的診斷","(B) 兩種測試（50g GCT and 100g OGTT）皆不需要空腹就可以執行","(C) 妊娠糖尿病的產婦在生產後20年有超過一半的女性可能發展成糖尿病（overt DM）","(D) 妊娠糖尿病或母親體重過胖的胎兒死產率（unexplained stillbirth rate）都較一般孕婦為高"],"answer":1,"image":""},{"id":"md6-105-1-51","subject":"md6","topic":"產科-高危險妊娠","meta":"105年第1次第51題","year":105,"session":1,"number":51,"question":"小穎在醫師建議下適當安排運動及接受營養師的飲食衛教，下列敘述何者正確？","options":["(A) 根據2002美國婦產科醫學會（ACOG）建議，飯前血糖應控制在110 mg/dL以下，飯後兩小時140 mg/dL以下為佳","(B) 根據2000美國糖尿病醫學會（ADA）建議，因小穎BMI超過30，每日建議攝取熱量為體重（kg）乘以40大卡再減掉30到33%","(C) 根據小穎的理想體重計算，每日飲食應給予1740大卡","(D) 小穎每日飲食應給予2500大卡"],"answer":2,"image":""},{"id":"md6-105-1-52","subject":"md6","topic":"產科-高危險妊娠","meta":"105年第1次第52題","year":105,"session":1,"number":52,"question":"小穎雖然接受飲食衛教，但因為她實在難以抵擋食物當前的誘惑，所以平時空腹血糖都維持在110 mg/dL，糖化血色素（HbA1C）是7.3%，下列的事實何者錯誤？","options":["(A) 根據1999美國糖尿病醫學會（ADA）統計，空腹血糖過高會提高預產期前兩個月的胎兒死亡率（fetal death rate）","(B) 生產時胎兒過大（macrosomia）及肩難產（shoulder dystocia）機會都會增加","(C) 胎兒出生後會因為媽媽本身胰島素過高（hyperinsulinemia）而造成血糖過低（hypoglycemia）的情形","(D) 小穎下胎發生妊娠糖尿病的機會比起一般孕婦高30～50%"],"answer":2,"image":"","answer_note":"更正:第52題答Ｃ給分 (原公告答案 D)"},{"id":"md6-105-1-53","subject":"md6","topic":"產科-一般產科","meta":"105年第1次第53題","year":105,"session":1,"number":53,"question":"32歲孕婦，G5P4，妊娠41週，待產中接受胎兒監視器檢查，結果如下圖：其判讀為何？","options":["(A) early deceleration","(B) late deceleration","(C) variable decelerations","(D) sinusoid pattern"],"answer":2,"image":"md6-105-1-53.jpeg"},{"id":"md6-105-1-54","subject":"md6","topic":"產科-一般產科","meta":"105年第1次第54題","year":105,"session":1,"number":54,"question":"承上題，下列四者中最可能之臨床意義為何？","options":["(A) cord compression","(B) head compression","(C) utero-placental insufficiency","(D) respiration"],"answer":0,"image":""},{"id":"md6-105-1-55","subject":"md6","topic":"復健-神經復健","meta":"105年第1次第55題","year":105,"session":1,"number":55,"question":"下列何者不是人類腦部額葉（frontal lobe）病變常發生的症狀？","options":["(A) 原始反射（primitive reflex）的出現","(B) 語言表達失常","(C) 無方向感（right-left disorientation）","(D) 失去動作的起始性（initiation）"],"answer":2,"image":""},{"id":"md6-105-1-56","subject":"md6","topic":"復健-神經復健","meta":"105年第1次第56題","year":105,"session":1,"number":56,"question":"下列何種指標與腦傷（traumatic brain injury）病人的預後關聯性最低？","options":["(A) 腦傷後癲癇（seizure）發生頻率","(B) 格拉司哥昏迷指數（Glasgow coma scale）","(C) 腦傷後失憶症（amnesia）時間的長短","(D) 腦傷造成意識失常（comatose）時間的長短"],"answer":0,"image":""},{"id":"md6-105-1-57","subject":"md6","topic":"復健-神經復健","meta":"105年第1次第57題","year":105,"session":1,"number":57,"question":"一位病人於理學檢查時被發現有肩膀外展（abduction）無力，下列那一部分的神經損傷不會造成此種現象？","options":["(A) 腋窩神經（axillary nerve）","(B) 臂神經叢上幹（upper trunk）","(C) 肌皮神經（musculocutaneous nerve）","(D) 臂神經叢後索（posterior cord）"],"answer":2,"image":""},{"id":"md6-105-1-58","subject":"md6","topic":"復健-神經復健","meta":"105年第1次第58題","year":105,"session":1,"number":58,"question":"若腦中風病人出現認知（cognition）功能失常，行為改變，其病變位置最常發生在下列何部位？","options":["(A) 額（frontal）葉","(B) 頂（parietal）葉","(C) 顳（temporal）葉","(D) 枕（occipital）葉"],"answer":0,"image":""},{"id":"md6-105-1-59","subject":"md6","topic":"復健-神經復健","meta":"105年第1次第59題","year":105,"session":1,"number":59,"question":"中腦動脈（middle cerebral artery）梗塞引起的腦中風病人，最常造成下列何種視野障礙？","options":["(A) 兩顳側邊偏盲（bitemporal hemianopia）","(B) 兩同側邊偏盲（homonymous hemianopia）","(C) 視野中心缺損（central scotoma）","(D) 單眼盲（one-eye blindness）"],"answer":1,"image":""},{"id":"md6-105-1-60","subject":"md6","topic":"復健-骨骼肌肉損傷與疾患","meta":"105年第1次第60題","year":105,"session":1,"number":60,"question":"下列有關膝前十字韌帶（anterior cruciate ligament）斷裂的敘述，何者錯誤？","options":["(A) 疼痛是急性期最常見的症狀","(B) 冰敷、抬高、壓迫是急性期重要的處理方法","(C) 拉赫曼試驗（Lachman’s test）比前拉試驗（anterior drawer test）敏感","(D) 對於運動選手，建議在受傷1～2週後才進行重建手術"],"answer":[0,1,2,3],"image":"","answer_note":"送分:第60題一律給分。 (原公告答案 A)"},{"id":"md6-105-1-61","subject":"md6","topic":"復健-骨骼肌肉損傷與疾患","meta":"105年第1次第61題","year":105,"session":1,"number":61,"question":"下列那一種輔具最常用來矯正類風濕性關節炎（rheumatoid arthritis）病人的鈕扣孔變形（boutonnière deformities）？","options":["(A) 豎腕副木（cock-up splint）","(B) 環形輔具（ring orthosis）","(C) 拖位輔具（resting orthosis）","(D) C形（C-bar）夾"],"answer":1,"image":""},{"id":"md6-105-1-62","subject":"md6","topic":"復健-截肢與義肢輔具","meta":"105年第1次第62題","year":105,"session":1,"number":62,"question":"Lisfranc截肢病患的殘肢不會留有下列那一塊骨頭？","options":["(A) 蹠骨（metatarsus）","(B) 楔骨（cuneiform）","(C) 跟骨（calcaneus）","(D) 距骨（talus）"],"answer":0,"image":""},{"id":"md6-105-1-63","subject":"md6","topic":"復健-截肢與義肢輔具","meta":"105年第1次第63題","year":105,"session":1,"number":63,"question":"下列何者是最理想的膝下經脛骨（trans-tibial）截肢殘肢長度為原脛骨長度的百分比？","options":["(A) 80%","(B) 60%","(C) 40%","(D) 20%"],"answer":2,"image":""},{"id":"md6-105-1-64","subject":"md6","topic":"復健-心肺復健與運動處方","meta":"105年第1次第64題","year":105,"session":1,"number":64,"question":"有關肺部復健的功效，下列何者效果最不能期待？","options":["(A) 可增加運動耐力","(B) 改善患者健康相關生活品質","(C) 減少病患呼吸困難的不適感","(D) 使病患的肺功能檢查數據（如FEV1）回復正常"],"answer":3,"image":""},{"id":"md6-105-1-65","subject":"md6","topic":"復健-心肺復健與運動處方","meta":"105年第1次第65題","year":105,"session":1,"number":65,"question":"如未經運動測試，以臨床狀況訂定運動強度時，下列敘述何者錯誤？","options":["(A) 心肌梗塞後，以休息心跳加20次以內為限","(B) 繞道手術後，以休息心跳加30次以內為限","(C) 穩定性心絞痛病患，無接受手術或心導管計畫者，若胸悶出現，應立即停止運動","(D) 下肢動脈阻塞（peripheral arterial occlusive disease）病患，下肢開始出現疼痛時，應立即停止運動"],"answer":3,"image":""},{"id":"md6-105-1-66","subject":"md6","topic":"復健-神經復健","meta":"105年第1次第66題","year":105,"session":1,"number":66,"question":"下列有關腦性麻痺之敘述，何者錯誤？","options":["(A) 是一種症候群（syndrome）","(B) 主要以智能障礙為主","(C) 常合併其他神經功能障礙","(D) 在發展未成熟之腦部出現非進行性之病變或損傷"],"answer":1,"image":""},{"id":"md6-105-1-67","subject":"md6","topic":"復健-兒童與一般復健","meta":"105年第1次第67題","year":105,"session":1,"number":67,"question":"對於先天性小兒下肢缺損的患者，什麼年紀是開始裝配義肢的最適當時機？","options":["(A) 6至8個月","(B) 9至12個月","(C) 13至18個月","(D) 19至24個月"],"answer":1,"image":""},{"id":"md6-105-1-68","subject":"md6","topic":"復健-神經復健","meta":"105年第1次第68題","year":105,"session":1,"number":68,"question":"下列那一類失語症之流暢（fluency）、理解（comprehension）、覆誦（repetition）能力大致正常？","options":["(A) 命名型失語症（anomic aphasia）","(B) 傳導型失語症（conduction aphasia）","(C) 渥尼克失語症（Wernicke’s aphasia）","(D) 布洛卡失語症（Broca’s aphasia）"],"answer":0,"image":""},{"id":"md6-105-1-69","subject":"md6","topic":"復健-神經復健","meta":"105年第1次第69題","year":105,"session":1,"number":69,"question":"脊髓刺激（spinal cord stimulation）可以有效降低慢性神經性疼痛，下列何者並非常見的適應症？","options":["(A) 脊椎術後症候群（failed back syndrome）","(B) 脊髓損傷相關疼痛（pain associated spinal cord injury）","(C) 癌症痛（cancer pain）","(D) 截肢後疼痛（postamputation limb pain）"],"answer":2,"image":""},{"id":"md6-105-1-70","subject":"md6","topic":"復健-兒童與一般復健","meta":"105年第1次第70題","year":105,"session":1,"number":70,"question":"吞嚥過程並不包含下列何者？","options":["(A) 口腔期（oral phase）","(B) 咽期（pharyngeal phase）","(C) 喉期（laryngeal phase）","(D) 食道期（esophageal phase）"],"answer":2,"image":""},{"id":"md6-105-1-71","subject":"md6","topic":"復健-兒童與一般復健","meta":"105年第1次第71題","year":105,"session":1,"number":71,"question":"1歲以上正常小孩應仍保有下列那一種反應或反射？","options":["(A) palmar grasp reflex","(B) parachute reaction","(C) rooting reflex","(D) symmetric tonic neck reflex（STNR）"],"answer":1,"image":""},{"id":"md6-105-1-72","subject":"md6","topic":"婦科-良性腫瘤與內膜異位","meta":"105年第1次第72題","year":105,"session":1,"number":72,"question":"一位65歲女性病患，無症狀。腹部X光片意外發現一個高度鈣化的陰影（如上圖）。超音波檢查如下圖。其診斷為何：","options":["(A) 子宮肌瘤（uterine myoma）","(B) 卵巢癌（ovarian cancer）","(C) 子宮頸癌（cervical cancer）","(D) 輸卵管卵巢膿瘍（tubo-ovarian abscess）"],"answer":0,"image":"md6-105-1-72.jpeg"},{"id":"md6-105-1-73","subject":"md6","topic":"鼻科學","meta":"105年第1次第73題","year":105,"session":1,"number":73,"question":"關於鼻竇黏液囊腫（mucocele），下列敘述何者錯誤？","options":["(A) 最好發於上頷竇（maxillary sinus）","(B) 注射對比劑的電腦斷層檢查，多不會顯影","(C) 可造成病灶處鼻竇擴張（expansion）","(D) 可影響眼眶而造成複視"],"answer":0,"image":""},{"id":"md6-105-1-74","subject":"md6","topic":"復健-骨骼肌肉損傷與疾患","meta":"105年第1次第74題","year":105,"session":1,"number":74,"question":"11歲男童，主訴右膝疼痛，膝蓋前側之灰階及彩色杜卜勒超音波檢查如圖，最可能的診斷為何？","options":["(A) 骨髓炎（osteomyelitis）","(B) 骨肉瘤（osteosarcoma）","(C) 奧斯戈德氏病（Osgood-Schlatter syndrome）","(D) 髕韌帶肌腱炎（patella tendinitis）"],"answer":2,"image":"md6-105-1-74.jpeg"},{"id":"md6-105-1-75","subject":"md6","topic":"婦科-良性腫瘤與內膜異位","meta":"105年第1次第75題","year":105,"session":1,"number":75,"question":"65歲女性，下腹部磁振造影檢查呈現如圖，箭號所指最可能為何？","options":["(A) 子宮肌瘤","(B) 子宮內膜癌","(C) 子宮腺肌症","(D) 子宮頸癌"],"answer":3,"image":"md6-105-1-75.jpeg"},{"id":"md6-105-1-76","subject":"md6","topic":"麻醉-呼吸道與監視","meta":"105年第1次第76題","year":105,"session":1,"number":76,"question":"25歲頭部外傷男性病患，至急診時昏迷指數（Glasgow Coma Scale, GCS）7分，經放置氣管內管之後，確認氣管內管是否置於氣管內的方式，可依2010年American Heart Assoication（AHA）出版之Emergency Cardiovascular Care的建議，除了：","options":["(A) 五點聽診","(B) 照胸部X光","(C) 潮氣末二氧化碳分壓（End-Tidal CO2，ETCO2）做二氧化碳濃度監測","(D) 直接目測氣管內管通過聲帶"],"answer":1,"image":""},{"id":"md6-105-1-77","subject":"md6","topic":"麻醉-麻醉藥理","meta":"105年第1次第77題","year":105,"session":1,"number":77,"question":"40歲男性病人，因急性雙眼視力降低、腹痛、嘔吐、腹瀉、頭痛、暈眩、全身虛弱、步態不穩等，被家人送至急診，有意識混亂、呼吸急促、以及視野縮小的情形。理學檢查及實驗室檢查發現心跳加速、深肌腱反射增強、併有陰離子間隙（anion gap）增加及滲透間隙（osmolar gap）上升之代謝性酸中毒、高血糖、白血球升高、低血鉀、低血鎂、急性腎衰竭等現象，眼底檢查出現視神經盤充血、視網膜水腫的情形。下列治療何者較不適當？","options":["(A) Fomepizole藥物","(B) 透析（dialysis）","(C) 乙醇（ethanol）","(D) 類固醇（steroid）"],"answer":3,"image":""},{"id":"md6-105-1-78","subject":"md6","topic":"耳科學","meta":"105年第1次第78題","year":105,"session":1,"number":78,"question":"一位43歲女性病人有頭暈和嘔吐的現象已經三日，經檢查懷疑是良性陣發性眩暈（benign paroxysmal positional vertigo），下列何種檢查最適合用來確定診斷？","options":["(A) Dix-Hallpike position test檢查","(B) 腦波檢查（electroencephalography）","(C) 腦部電腦斷層（brain CT scan）","(D) 頸動脈超音波（carotid ultrasound）"],"answer":0,"image":""},{"id":"md6-105-1-79","subject":"md6","topic":"醫學倫理與法規","meta":"105年第1次第79題","year":105,"session":1,"number":79,"question":"林先生為鼻咽癌症末期病人，因呼吸困難被家人送到醫院急診室，林先生意識不清，醫護人員認為病患死亡已無法避免，不應予以急救，下列作法的優先次序為何？①詢問有無本人之DNR意願書 ②解釋、徵求家屬的同意並簽署同意書 ③詢問是否有醫療委任代理人","options":["(A) ①→③→②","(B) ①→②→③","(C) ②→①→③","(D) ③→①→②"],"answer":0,"image":""},{"id":"md6-105-1-80","subject":"md6","topic":"醫學倫理與法規","meta":"105年第1次第80題","year":105,"session":1,"number":80,"question":"52歲無過去病史的公務員趙先生，因為深頸部嚴重感染引起敗血性休克，他的喉部因膿瘍壓迫而造成呼吸困難，被送到急診時已意識不清，醫師判斷必須立即進行氣管切開及頸部膿瘍引流以搶救生命，下列各項考量何者最適當？","options":["(A) 病人無法親自簽字以安排手術，可按壓病人指印替代","(B) 因病人無法簽名，需等候家屬到再請家屬代理簽署","(C) 緊急狀態，應逕行手術搶救","(D) 先了解病人是否曾簽署DNR再做手術與否的決定"],"answer":2,"image":""},{"id":"md6-105-2-1","subject":"md6","topic":"麻醉-呼吸道與監視","meta":"105年第2次第1題","year":105,"session":2,"number":1,"question":"氣管內管插管（endotracheal tube intubation）過程往往容易有併發症的發生，學界提出了處置過程中應該遵循的四大原則，以減少氣管內管插管相關併發症的發生或是降低其嚴重程度。此四大原則，何者的優先性被列為最高？","options":["(A) 預防外傷原則（prevent trauma）／插管前必須將所有預防外傷的條件最佳化（optimization），避免插管所導致的外傷","(B) 充分充氧原則（oxygenation）／插管前必須進行前給氧（preoxygenation），插管之間應以面罩通氣方式給氧","(C) 備份計畫原則（backup plans）／開始插管之前就應準備好應變的備份計畫，包括終止插管與取消手術在內","(D) 儘速求救原則（call for help）／插管過程若遇到任何處置上的困難，就應該立即尋求所有可能的協助"],"answer":1,"image":""},{"id":"md6-105-2-2","subject":"md6","topic":"麻醉-呼吸道與監視","meta":"105年第2次第2題","year":105,"session":2,"number":2,"question":"潮氣末二氧化碳分壓（End-tidal CO2, PETCO2）測量儀可以偵測病患吐氣末端氣體中二氧化碳分壓來進行呼吸監測。下列何者最不可能是手術麻醉期間突發性潮氣末二氧化碳分壓銳減的病因？","options":["(A) 呼吸管脫落（circuit disconnection）","(B) 過度換氣（hyperventilation）","(C) 心輸出量突減（abrupt decrease in cardiac output）","(D) 呼吸道阻塞（airway obstruction）"],"answer":1,"image":""},{"id":"md6-105-2-3","subject":"md6","topic":"麻醉-呼吸道與監視","meta":"105年第2次第3題","year":105,"session":2,"number":3,"question":"在病人接受全身麻醉施行胸腰脊椎側彎（scoliosis）矯正手術時，下列何方法對脊椎神經功能監測最可靠？","options":["(A) motor evoked potentials","(B) somato-sensory evoked potentials","(C) electromyography","(D) wake-up test"],"answer":[0,1,2,3],"image":"","answer_note":"送分:第3題答Ａ、Ｂ、Ｃ、Ｄ給分 (原公告答案 D)"},{"id":"md6-105-2-4","subject":"md6","topic":"麻醉-麻醉藥理","meta":"105年第2次第4題","year":105,"session":2,"number":4,"question":"下列何者無法加速麻醉的攝取（uptake）？","options":["(A) 使用脂溶性較高的吸入性麻醉劑","(B) 增加病患心輸出量","(C) 增加肺泡與靜脈的吸入性麻醉劑分壓差","(D) 增高病人體溫"],"answer":3,"image":""},{"id":"md6-105-2-5","subject":"md6","topic":"麻醉-麻醉藥理","meta":"105年第2次第5題","year":105,"session":2,"number":5,"question":"下列有關使用吸入性麻醉劑時，因血中腎上腺素增加而引起心律不整的敘述，何者錯誤？","options":["(A) 目前halothane仍然是腎上腺素敏感閾值（threshold）最低的藥物","(B) sevoflurane和desflurane所需引發心律不整的血中最低腎上腺素濃度是差不多的","(C) isoflurane比sevoflurane更容易引發這類的心律不整","(D) 主要機制與心肌上的甲乙型腎上腺接受器（α1Aand β adrenoreceptor）無關"],"answer":3,"image":""},{"id":"md6-105-2-6","subject":"md6","topic":"產科-一般產科","meta":"105年第2次第6題","year":105,"session":2,"number":6,"question":"少子化是國人明顯的趨勢，而國人對生產的要求也愈來愈高，下列有關自然產止痛的敘述，何者錯誤？","options":["(A) 可靜脈給予類鴉片類止痛藥","(B) 可硬脊膜外給予類鴉片類止痛藥與局部麻醉藥","(C) 可合併使用硬脊膜與脊椎內止痛術","(D) 絕對不會使用到全身麻醉"],"answer":3,"image":""},{"id":"md6-105-2-7","subject":"md6","topic":"麻醉-特殊麻醉與疼痛","meta":"105年第2次第7題","year":105,"session":2,"number":7,"question":"雖然當日手術（ambulatory surgery）不須住院，可以減少許多醫療支出費用；不過麻醉、開刀後一旦發生下列何狀況，應考慮延遲出院或住院？①嚴重的噁心、嘔吐 ②不穩定的血壓 ③嚴重疼痛尚未獲得控制 ④預期外的手術後遺症","options":["(A) 僅②④","(B) 僅②③","(C) ①②③④","(D) 僅③④"],"answer":2,"image":""},{"id":"md6-105-2-8","subject":"md6","topic":"麻醉-特殊麻醉與疼痛","meta":"105年第2次第8題","year":105,"session":2,"number":8,"question":"根據2006年美國麻醉醫師學會操作指引（The American Society of Anesthesiologists Practice Guidelines，2006），建議病人需要輸血操作條件之敘述，何者錯誤？","options":["(A) 病人血色素小於6 g/dL的病人，特別是急性貧血情況，幾乎是所有病人都達到需要進行緊急輸血的條件","(B) 病人血色素大於10 g/dL時，原則幾乎不必考慮輸血","(C) 當病人血色素介於6～10 g/dL之間，應由病人發生缺氧併發症的風險，決定是否輸紅血球","(D) 病人在使用異體輸血（allogeneic RBCs）為病人輸血所設定的適應症，應較使用自體輸血（autologous RBCs）時更有寬鬆且自由，因為前者異體輸血的安全性較高"],"answer":3,"image":""},{"id":"md6-105-2-9","subject":"md6","topic":"眼科-視網膜葡萄膜","meta":"105年第2次第9題","year":105,"session":2,"number":9,"question":"眼底檢查發現牛眼狀黃斑病變（bull’s eye maculopathy），常與下列何種疾病相關？","options":["(A) 氯奎寧視網膜病變（chloroquine retinopathy）","(B) 囊狀黃斑部水腫（cystoid macular edema）","(C) 中央視網膜動脈阻塞（central retinal artery occlusion）","(D) 老年性黃斑病變（age-related macular degeneration）"],"answer":[0,3],"image":"","answer_note":"更正:第9題答Ａ、Ｄ給分"},{"id":"md6-105-2-10","subject":"md6","topic":"眼科-角膜結膜眼瞼眼窩","meta":"105年第2次第10題","year":105,"session":2,"number":10,"question":"下列那一種眼藥可用來鑑別結節狀上鞏膜炎（nodular episcleritis）與結節狀鞏膜炎（nodular scleritis）？","options":["(A) 副交感神經抑制劑（如tropicamide）","(B) 乙型交感神經抑制劑（如timolol）","(C) 副交感神經興奮劑（如pilocarpine）","(D) 交感神經興奮劑（如phenylephrine）"],"answer":3,"image":""},{"id":"md6-105-2-11","subject":"md6","topic":"眼科-水晶體青光眼","meta":"105年第2次第11題","year":105,"session":2,"number":11,"question":"Beta-adrenergic blocking agents眼藥水如0.5% Timolol maleate，可抑制房水的產生，為降低眼壓之藥物，但病人有下列何種疾病時絕對不能使用（major contraindication）？","options":["(A) 腦中風（stroke）","(B) 氣喘（asthma）","(C) 高血壓（hypertension）","(D) 糖尿病（diabetes mellitus）"],"answer":1,"image":""},{"id":"md6-105-2-12","subject":"md6","topic":"眼科-屈光斜弱視","meta":"105年第2次第12題","year":105,"session":2,"number":12,"question":"下列何者不應該是兒童調視性內斜視（refractive accommodative esotropia）的治療原則？","options":["(A) 儘早戴上度數完全矯正的遠視眼鏡","(B) 看近物時，還可加配雙光（bifocals）眼鏡矯正","(C) 若併有斜視性弱視，則最好再加上遮閉療法（occlusion therapy）","(D) 儘早開刀矯正，一勞永逸，並免得造成弱視"],"answer":3,"image":""},{"id":"md6-105-2-13","subject":"md6","topic":"眼科-屈光斜弱視","meta":"105年第2次第13題","year":105,"session":2,"number":13,"question":"下列何種方式對弱視的治療較無效？","options":["(A) 遮閉（occlusion）療法（遮住好眼）","(B) 禁制（penalization）療法（好眼點atropine眼藥水）","(C) 屈光配鏡（optical devices）","(D) 注射肉毒桿菌素（botulinum toxin）於弱視眼"],"answer":3,"image":""},{"id":"md6-105-2-14","subject":"md6","topic":"眼科-角膜結膜眼瞼眼窩","meta":"105年第2次第14題","year":105,"session":2,"number":14,"question":"下列有關眼外肌（extraocular muscles）之敘述，何者錯誤？","options":["(A) 四條直肌（rectus muscles）的起始點（origins）均在眼窩尖（orbital apex）之Zinn氏環（annulus）","(B) 四條直肌的終止點（insertions）均在眼球赤道部（equator）之前","(C) 兩條斜肌（oblique muscles）的終止點均在眼球赤道部之後","(D) 上斜肌（superior oblique muscle）使眼球看斜上、下斜肌（inferior oblique muscle）使眼球看斜下"],"answer":3,"image":""},{"id":"md6-105-2-15","subject":"md6","topic":"眼科-視網膜葡萄膜","meta":"105年第2次第15題","year":105,"session":2,"number":15,"question":"下列關於糖尿病視網膜病變（diabetic retinopathy）何者錯誤？","options":["(A) 漸進性的微小血管變化（microangiopathy）","(B) 點狀出血、棉絮狀斑點（cotton wool spot）及視網膜新生血管皆為非增殖型糖尿病視網膜病變（Non-proliferative diabetic retinopathy）的眼底變化","(C) 合併黃斑部水腫會造成視力喪失","(D) 罹患糖尿病時間越久，併發糖尿病視網膜病變的機率越高"],"answer":1,"image":""},{"id":"md6-105-2-16","subject":"md6","topic":"眼科-角膜結膜眼瞼眼窩","meta":"105年第2次第16題","year":105,"session":2,"number":16,"question":"一位七十歲女性，左側下眼瞼紅腫疼痛三天，最明顯壓痛點在左鼻側及內眥間有一堅硬紅腫突起，下列敘述何者錯誤？","options":["(A) 最有可能的診斷為急性淚囊炎（acute dacryocystitis）","(B) 造成此疾病最常見的病原菌為放射菌（Actinomyces israelii）","(C) 若未及時以抗生素治療，可能會導致眼窩蜂窩性組織炎","(D) 此疾病若反覆發作，須考慮於緩解期做淚囊鼻腔吻合術（dacryocystorhinostomy）"],"answer":1,"image":""},{"id":"md6-105-2-17","subject":"md6","topic":"耳科學","meta":"105年第2次第17題","year":105,"session":2,"number":17,"question":"媽媽抱著1個月的嬰兒前來就診，男嬰的右耳耳廓發育不良比正常小很多，且無外耳道。左耳外觀及耳膜均正常，這時接下來的處置，何者最適當？","options":["(A) 耳部高解析度電腦斷層檢查","(B) 耳道及外耳整型手術","(C) 選配骨導式助聽器","(D) 聽性腦幹誘發電位檢查評估聽力"],"answer":3,"image":""},{"id":"md6-105-2-18","subject":"md6","topic":"耳科學","meta":"105年第2次第18題","year":105,"session":2,"number":18,"question":"一個18歲女孩穿耳環在耳廓上部，引起耳廓化膿性軟骨膜炎（perichondritis of auricle），下列何者為最可能致病的菌種？","options":["(A) Streptococcus pneumoniae","(B) Haemophilus influenzae","(C) Pseudomonas aeruginosa","(D) Klebsiella pneumoniae"],"answer":2,"image":""},{"id":"md6-105-2-19","subject":"md6","topic":"鼻科學","meta":"105年第2次第19題","year":105,"session":2,"number":19,"question":"鼻竇炎引起眼球併發症中，下列何者是最常培養出來的菌種？","options":["(A) 綠膿桿菌（Pseudomonas aeruginosa）","(B) 白黴菌（mucormycosis）","(C) 葡萄球菌（Staphylococcus）","(D) 流行感冒嗜血桿菌（Haemophilus influenzae）"],"answer":3,"image":""},{"id":"md6-105-2-20","subject":"md6","topic":"鼻科學","meta":"105年第2次第20題","year":105,"session":2,"number":20,"question":"一位70歲女性病人，因糖尿病控制不好，住院治療中，她過去10年內曾接受子宮肌瘤切除手術及雙側慢性鼻竇炎之內視鏡手術，2天前突感右鼻孔腫脹，鼻塞，右眼視力模糊，眼後脹痛及眼球移動會痛，體溫38.5℃，無牙痛及臉頰腫痛。最可能之病因為何？","options":["(A) 上頜竇炎","(B) 篩竇炎","(C) 篩動脈栓塞","(D) 篩竇癌"],"answer":1,"image":""},{"id":"md6-105-2-21","subject":"md6","topic":"喉科學與頭頸腫瘤","meta":"105年第2次第21題","year":105,"session":2,"number":21,"question":"急診室接到救護車送來的一名年輕婦女，伴隨人員陳述該婦女因情感因素，一小時前在家中吞食通樂（內含氫氧化鈉、氨水等強鹼），下列緊急處置何者為宜？","options":["(A) 口腔黏膜損傷情形如果輕微，就不必安排食道檢查","(B) 應立即給予催吐劑或酸性中和劑與洗胃","(C) 靜脈輸液及鼻胃管進食","(D) 應立即安排內視鏡檢查損傷範圍與程度"],"answer":2,"image":""},{"id":"md6-105-2-22","subject":"md6","topic":"喉科學與頭頸腫瘤","meta":"105年第2次第22題","year":105,"session":2,"number":22,"question":"60歲之男性，抽菸數十年，平均一天一包以上。有一年多聲音沙啞的病史。近1至2週有呼吸困難的症狀。內科醫師證實無心臟或肺部的疾病，他最有可能患下列那種病？","options":["(A) 喉腫瘤","(B) 聲帶息肉","(C) 甲狀腺腫瘤","(D) 氣道異物"],"answer":0,"image":""},{"id":"md6-105-2-23","subject":"md6","topic":"喉科學與頭頸腫瘤","meta":"105年第2次第23題","year":105,"session":2,"number":23,"question":"有關Warthin tumor的描述，何者錯誤？","options":["(A) 是唾腺腫瘤中第二常見之良性腫瘤","(B) 多發生於較年長有吸菸習慣之男性","(C) 好發位置為腮腺之上端","(D) 腮腺淺葉切除術是適當的治療方式"],"answer":2,"image":""},{"id":"md6-105-2-24","subject":"md6","topic":"喉科學與頭頸腫瘤","meta":"105年第2次第24題","year":105,"session":2,"number":24,"question":"下列有關於舌甲狀腺（lingual thyroid）之敘述，何者錯誤？","options":["(A) 女性居多","(B) 甲狀腺功能大多正常","(C) 甲狀腺掃描是治療前的必要檢查項目","(D) 有症狀才需手術切除"],"answer":[0,1,2,3],"image":"","answer_note":"送分:第24題一律給分 (原公告答案 B)"},{"id":"md6-105-2-25","subject":"md6","topic":"產科-高危險妊娠","meta":"105年第2次第25題","year":105,"session":2,"number":25,"question":"對於接受抗癲癎藥物治療的癲癎婦女患者，可建議在受孕期前後（periconceptional period）補充下列何種維生素，來降低胎兒發育異常（如：唇顎裂、神經管缺損、先天性心臟缺損等）的發生機會？","options":["(A) 維生素B6","(B) 維生素C","(C) 葉酸（folic acid）","(D) 維生素B1"],"answer":2,"image":""},{"id":"md6-105-2-26","subject":"md6","topic":"產科-高危險妊娠","meta":"105年第2次第26題","year":105,"session":2,"number":26,"question":"為避免早產兒於出生後發生玻璃腺樣病（hyaline membrane disease），可於產前給予孕婦下列何種藥物？","options":["(A) aspirin","(B) glucocorticoids","(C) magnesium sulfate","(D) thyrotropin"],"answer":1,"image":""},{"id":"md6-105-2-27","subject":"md6","topic":"產科-高危險妊娠","meta":"105年第2次第27題","year":105,"session":2,"number":27,"question":"Atosiban屬於何種機轉的安胎藥物？","options":["(A) 前列腺素抑制劑（prostaglandin inhibitor）","(B) 鈣通道阻斷劑（calcium-channel blocker）","(C) 催產素類似物（oxytocin analog）","(D) 腎上腺素接受器促效藥（β-adrenergic receptor agonist）"],"answer":2,"image":""},{"id":"md6-105-2-28","subject":"md6","topic":"產科-一般產科","meta":"105年第2次第28題","year":105,"session":2,"number":28,"question":"胎盤早期剝離（placental abruption）潛在較常見的合併症是下列何者？","options":["(A) 子宮內翻","(B) 凝血障礙","(C) 產褥感染","(D) 子宮乏力"],"answer":1,"image":""},{"id":"md6-105-2-29","subject":"md6","topic":"婦科-生殖內分泌","meta":"105年第2次第29題","year":105,"session":2,"number":29,"question":"一個青春期少女，月經從初經開始週期即不正常，最近因二個週期月經不來而求診，最優先的處置是：","options":["(A) 懷孕試驗","(B) 給予黃體素（progestin）","(C) 觀察","(D) 給予動情激素（estrogen）"],"answer":0,"image":""},{"id":"md6-105-2-30","subject":"md6","topic":"產科-一般產科","meta":"105年第2次第30題","year":105,"session":2,"number":30,"question":"有關肩難產的發生，多與母體或胎兒的客觀條件相關。下列何者為與母親相關的肩難產危險因子（maternal risk factor）？","options":["(A) nulliparity","(B) obesity","(C) advanced maternal age","(D) chronic hypertension"],"answer":[1,2],"image":"","answer_note":"更正:第30題答Ｂ、Ｃ給分"},{"id":"md6-105-2-31","subject":"md6","topic":"婦科-良性腫瘤與內膜異位","meta":"105年第2次第31題","year":105,"session":2,"number":31,"question":"慢性骨盆腔疼痛的鑑別診斷中Mittelschmerz表示：","options":["(A) 痛經","(B) 排卵痛","(C) 發炎痛","(D) 痔瘡痛"],"answer":1,"image":""},{"id":"md6-105-2-32","subject":"md6","topic":"婦科-手術學與診斷技術","meta":"105年第2次第32題","year":105,"session":2,"number":32,"question":"40歲已婚߯性，因子宮內膜息肉接受子宮鏡手術，子宮鏡使用單極電燒（monopolar）。手術時畫面清晰良好但發現電燒無法作用，經流動護士檢查電燒機功能正常，且電源接觸良好，下列何種子宮腔擴張介質（distention media）為造成無法電燒之可能原因？","options":["(A) 蒸餾水（distilled water）","(B) 葡萄聚糖（dextran 70）","(C) 生理食鹽水（normal saline）","(D) 氨基乙酸（glycine）"],"answer":2,"image":""},{"id":"md6-105-2-33","subject":"md6","topic":"婦科-手術學與診斷技術","meta":"105年第2次第33題","year":105,"session":2,"number":33,"question":"46歲生過四胎之婦女，於第四胎生產時接受輸卵管結紮手術。現因不正常陰道出血而就醫，經陰道診視發現子宮頸表面平滑，血液自子宮頸口處流出，觸診發現子宮大小正常無觸痛之情形。經陰道超音波掃瞄子宮大小正常無內膜增生之情形，然而於子宮附屬物區發現有香腸般水囊狀物，最長部位為9.5公分而最寬部位為3.9公分，此水囊狀物最適合之診斷為：","options":["(A) 尿道憩室（urethral diverticulum）","(B) 盲腸炎（appendicitis）","(C) 輸尿管水腫（hydroureter）","(D) 輸卵管水腫（hydrosalpinx）"],"answer":3,"image":"md6-105-2-33.jpeg"},{"id":"md6-105-2-34","subject":"md6","topic":"婦科-生殖內分泌","meta":"105年第2次第34題","year":105,"session":2,"number":34,"question":"子宮輸卵管攝影（hysterosalpingography）是用來評估女性不孕症的一項檢查，下列檢查日期何者最好？","options":["(A) 月經週期第3天","(B) 月經週期第8天","(C) 月經週期第14天","(D) 月經週期第21天"],"answer":1,"image":""},{"id":"md6-105-2-35","subject":"md6","topic":"婦科-生殖內分泌","meta":"105年第2次第35題","year":105,"session":2,"number":35,"question":"34歲婦女，不孕症5年，經檢查發現雙側輸卵管水腫（hydrosalpinx），卵巢功能正常，先生精液檢查正常，下一步應建議她做何治療？","options":["(A) 人工授精","(B) 打排卵針增加懷孕機會","(C) 吃排卵藥增加懷孕機會","(D) 腹腔鏡輸卵管整型、造口或切除手術"],"answer":3,"image":""},{"id":"md6-105-2-36","subject":"md6","topic":"婦科-生殖內分泌","meta":"105年第2次第36題","year":105,"session":2,"number":36,"question":"停經後，婦女體內何種荷爾蒙不再合成及分泌？","options":["(A) 雌激素（estrogen）","(B) 雄性素（androgen）","(C) 黃體素（progesterone）","(D) 黃體化激素（LH）"],"answer":2,"image":""},{"id":"md6-105-2-37","subject":"md6","topic":"婦科-生殖內分泌","meta":"105年第2次第37題","year":105,"session":2,"number":37,"question":"58歲婦女，停經2年，無婦科開刀病史，無熱潮紅，心悸症狀，但會有陰部乾澀，性交疼痛的困擾，其最適當的治療為：","options":["(A) 口服大豆異黃酮","(B) 口服雌激素與黃體素","(C) 口服雌激素","(D) 陰部雌激素局部使用"],"answer":3,"image":""},{"id":"md6-105-2-38","subject":"md6","topic":"婦科-生殖內分泌","meta":"105年第2次第38題","year":105,"session":2,"number":38,"question":"25歲女性，3天前胚胎植入，因呼吸不適至急診求診，超音波下可見雙側卵巢皆大於8公分，大量腹水，病患主訴尿量減少。下列敘述何者最不正確？","options":["(A) 應趕快給予利尿劑","(B) 在輸液選擇方面，saline優於lactated Ringer's solution","(C) 臥床可降低卵巢扭轉的風險","(D) 若病患成功懷孕，症狀可能加重"],"answer":0,"image":""},{"id":"md6-105-2-39","subject":"md6","topic":"婦科-生殖內分泌","meta":"105年第2次第39題","year":105,"session":2,"number":39,"question":"24歲女性，主訴半年無月經，雙側乳房有白色分泌物，病患主訴無性經驗。下列檢查何者最不適當？","options":["(A) TSH（thyroid stimulating hormone）","(B) prolactin","(C) 詳細的藥物史","(D) FSH（follicle stimulating hormone）"],"answer":3,"image":""},{"id":"md6-105-2-40","subject":"md6","topic":"婦科-生殖內分泌","meta":"105年第2次第40題","year":105,"session":2,"number":40,"question":"先天性腎上腺增生症（congenital adrenal hyperplasia, CAH）的遺傳模式為：","options":["(A) 體染色體顯性遺傳","(B) 體染色體隱性遺傳","(C) 性聯遺傳","(D) 性染色體異常"],"answer":1,"image":""},{"id":"md6-105-2-41","subject":"md6","topic":"婦科-腫瘤","meta":"105年第2次第41題","year":105,"session":2,"number":41,"question":"48歲婦女，做抹片檢查，報告為high-grade squamous intraepithelial lesion（HSIL），下一步處置何者最適當？","options":["(A) 半年抹片追蹤一次","(B) 考慮HPV檢查並施打HPV疫苗","(C) 建議陰道鏡下切片檢查","(D) 安排fractional D&C檢查"],"answer":2,"image":""},{"id":"md6-105-2-42","subject":"md6","topic":"婦科-腫瘤","meta":"105年第2次第42題","year":105,"session":2,"number":42,"question":"在已開發國家大多數的子宮內膜癌診斷時，都是第幾期？","options":["(A) 第一期","(B) 第二期","(C) 第三期","(D) 第四期"],"answer":0,"image":""},{"id":"md6-105-2-43","subject":"md6","topic":"婦科-良性腫瘤與內膜異位","meta":"105年第2次第43題","year":105,"session":2,"number":43,"question":"70歲女性，因停經後陰道出血至門診求診，最常見的原因為何？","options":["(A) 子宮內膜癌","(B) 子宮內膜增生","(C) 子宮肌瘤","(D) 萎縮性子宮內膜"],"answer":3,"image":""},{"id":"md6-105-2-44","subject":"md6","topic":"婦科-腫瘤","meta":"105年第2次第44題","year":105,"session":2,"number":44,"question":"下列何者不適合接受人類乳突病毒疫苗？","options":["(A) 25歲曾有5個性伴侶上班族","(B) 12歲未有性經驗國小女生","(C) 46歲子宮頸癌患者","(D) 23歲抹片曾有輕度子宮頸上皮內贅瘤（CIN 1）研究生"],"answer":2,"image":""},{"id":"md6-105-2-45","subject":"md6","topic":"婦科-腫瘤","meta":"105年第2次第45題","year":105,"session":2,"number":45,"question":"60歲婦女，被診斷為外陰癌，病灶約有1.5公分大，基質侵犯約為1.5 mm，檢查發現單側的鼠蹊部淋巴結轉移，此婦女疾病之分期為第幾期？","options":["(A) 第一期（stage I）","(B) 第二期（stage II）","(C) 第三期（stage III）","(D) 第四期（stage IV）"],"answer":2,"image":""},{"id":"md6-105-2-46","subject":"md6","topic":"婦科-腫瘤","meta":"105年第2次第46題","year":105,"session":2,"number":46,"question":"關於顆粒細胞腫瘤（granulosa cell tumor）之敘述，下列何者錯誤？","options":["(A) 會分泌estrogen，且易在停經後不正常出血","(B) 多為兩側性發生，大約只有2%的病例為單側性","(C) 大多數的病例中，在病理切片下可見granulosa cell排列成團聚狀（cluster）或是玫瑰花環狀（rosette），像primordial follicles","(D) 大多數病例是在stage I被發現且診斷的"],"answer":1,"image":""},{"id":"md6-105-2-47","subject":"md6","topic":"產科-高危險妊娠","meta":"105年第2次第47題","year":105,"session":2,"number":47,"question":"21歲孕婦，G1P0，妊娠38週，接受杜卜勒超音波檢查，結果如圖所示，其檢查名稱為下列何者？","options":["(A) 臍動脈血流速度波形","(B) 胎兒上行主動脈血流速度波形","(C) 胎兒主動脈彎血流速度波形","(D) 胎兒降主動脈血流速度波形"],"answer":0,"image":"md6-105-2-47.jpeg"},{"id":"md6-105-2-48","subject":"md6","topic":"產科-高危險妊娠","meta":"105年第2次第48題","year":105,"session":2,"number":48,"question":"承上題，S/D ratio為2.5，檢查結果為何？","options":["(A) absent end diastolic velocity","(B) reversed end diastolic velocity","(C) non-reactive","(D) normal"],"answer":3,"image":""},{"id":"md6-105-2-49","subject":"md6","topic":"產科-一般產科","meta":"105年第2次第49題","year":105,"session":2,"number":49,"question":"37歲孕婦，G1P0，妊娠39週，生產後如圖所示：下列四者中最可能的診斷為何？","options":["(A) first-degree laceration","(B) second-degree laceration","(C) third-degree laceration","(D) fourth-degree laceration"],"answer":3,"image":"md6-105-2-49.jpeg"},{"id":"md6-105-2-50","subject":"md6","topic":"產科-一般產科","meta":"105年第2次第50題","year":105,"session":2,"number":50,"question":"承上題，正在縫合的組織為何？","options":["(A) vaginal mucosa","(B) vaginal submucosa","(C) anal sphincter","(D) rectal mucosa"],"answer":3,"image":""},{"id":"md6-105-2-51","subject":"md6","topic":"產科-高危險妊娠","meta":"105年第2次第51題","year":105,"session":2,"number":51,"question":"40歲孕婦，G3P2，妊娠22週，接受檢查，結果如圖所示，則檢查之胎兒部位名稱為何？","options":["(A) abdomen","(B) chest","(C) head","(D) neck"],"answer":2,"image":"md6-105-2-51.jpeg"},{"id":"md6-105-2-52","subject":"md6","topic":"產科-高危險妊娠","meta":"105年第2次第52題","year":105,"session":2,"number":52,"question":"承上題，下列四者中最可能的診斷為何？","options":["(A) cystic adenomatoid malformation of lung","(B) choroid plexus cyst","(C) cystic hygroma","(D) multicystic dysplastic kidney"],"answer":1,"image":""},{"id":"md6-105-2-53","subject":"md6","topic":"婦科-生殖內分泌","meta":"105年第2次第53題","year":105,"session":2,"number":53,"question":"34歲女性，身高152公分，體重96公斤，未曾有過性經驗，因陰道出血半年前來求診，據她敘述出血量時多時少，曾看過幾家醫院和診所，並接受荷爾蒙治療，未見效。初經11歲，頭幾年月經規則且正常，往後體重逐漸增加，月經不規則，常數月來一次，每次經量多，經期長。經檢查血壓90/60 mmHg，脈搏90下/min，體溫37℃，臉色蒼白，Hb 5.5 g/dL，腹部超音波顯示子宮稍大，子宮內膜增厚不規則約3.2 cm，雙側附屬物未看到，欲內診（骨盆腔檢查）時，發現處女膜完整，此時下列處置何者為佳？","options":["(A) 給予高劑量雌激素（estrogen）以達止血效果","(B) 給予高劑量黃體素（progesterone）以達止血效果","(C) 建議接受子宮內膜切片","(D) 給予GnRH agonist以達止血效果"],"answer":2,"image":""},{"id":"md6-105-2-54","subject":"md6","topic":"婦科-生殖內分泌","meta":"105年第2次第54題","year":105,"session":2,"number":54,"question":"承上題，下列何者是較不可能之診斷？","options":["(A) 子宮內膜增生（endometrial hyperplasia）","(B) 子宮內膜異位症（endometriosis）","(C) 子宮內膜癌（endometrial cancer）","(D) 子宮黏膜下肌瘤（submucous myoma）或息肉（polyp）"],"answer":1,"image":""},{"id":"md6-105-2-55","subject":"md6","topic":"復健-神經復健","meta":"105年第2次第55題","year":105,"session":2,"number":55,"question":"捏擠龜頭誘發肛門括約肌收縮的反射是經由下列何神經所傳導？","options":["(A) 腹下神經（hypogastric nerve）","(B) 骨盆神經（pelvic nerve）","(C) 內臟薦神經（sacral splanchnic nerve）","(D) 會陰神經（pudendal nerve）"],"answer":3,"image":""},{"id":"md6-105-2-56","subject":"md6","topic":"復健-神經復健","meta":"105年第2次第56題","year":105,"session":2,"number":56,"question":"下列何者與急性頭部外傷（traumatic brain injury）之預後無關？","options":["(A) 年齡（age）","(B) 昏迷的時間長短（duration of coma）","(C) 記憶缺失的時間長短（duration of posttraumatic amnesia）","(D) 身體質量指數（body mass index, BMI）"],"answer":3,"image":""},{"id":"md6-105-2-57","subject":"md6","topic":"復健-骨骼肌肉損傷與疾患","meta":"105年第2次第57題","year":105,"session":2,"number":57,"question":"下列有關冰凍肩（frozen shoulder）之復健治療，何者敘述最為正確？","options":["(A) 物理治療以熱療和關節活動治療為主","(B) 需在麻醉下做關節活動治療","(C) 復健治療需靠醫院設備器材才可實施","(D) 復健治療可達到百分之百治癒的效果，不會再發"],"answer":0,"image":""},{"id":"md6-105-2-58","subject":"md6","topic":"復健-截肢與義肢輔具","meta":"105年第2次第58題","year":105,"session":2,"number":58,"question":"下列何種人類的行走輔具（ambulation aids）可提供最大的身體承重（weight bearing）？","options":["(A) 手杖（cane）","(B) 腋下柺杖（axillary crutch）","(C) 上臂柺杖（forearm crutch）","(D) 助行器（walker）"],"answer":1,"image":""},{"id":"md6-105-2-59","subject":"md6","topic":"復健-心肺復健與運動處方","meta":"105年第2次第59題","year":105,"session":2,"number":59,"question":"下列何者不是病人長期臥床不動（immobilization）之後的生理機能反應？","options":["(A) 肌肉萎縮","(B) 肌力減退","(C) 韌帶鬆弛，延展性增加","(D) 動作協調性變差"],"answer":2,"image":""},{"id":"md6-105-2-60","subject":"md6","topic":"復健-截肢與義肢輔具","meta":"105年第2次第60題","year":105,"session":2,"number":60,"question":"利用支架（orthosis）來協助股四頭肌無力（quadriceps weakness）伴隨膝退化性關節炎（knee OA）之病人站立完全伸展時，下列何者最不合適？","options":["(A) 膝裝具（knee orthosis）","(B) 膝踝足裝具（KAFO）","(C) 思奇膝踝足裝具（Scott-Craig KAFO）","(D) 髖膝踝足裝具（HKAFO）"],"answer":3,"image":""},{"id":"md6-105-2-61","subject":"md6","topic":"復健-截肢與義肢輔具","meta":"105年第2次第61題","year":105,"session":2,"number":61,"question":"脊椎側彎在胸椎第六節以上，需使用下列何種背架矯正？","options":["(A) 波士頓背架（Boston brace）","(B) 米華基背架（Milwaukee brace）","(C) 泰勒背架（Taylor brace）","(D) 奈特背架（Knight brace）"],"answer":1,"image":""},{"id":"md6-105-2-62","subject":"md6","topic":"復健-心肺復健與運動處方","meta":"105年第2次第62題","year":105,"session":2,"number":62,"question":"腹式呼吸通常要配合節奏性的呼吸速率（paced breathing），下列何者是最理想的呼吸節奏？","options":["(A) 吐氣：吸氣＝4秒：2秒","(B) 吐氣：吸氣＝1秒：2秒","(C) 吐氣：吸氣＝1秒：1秒","(D) 吐氣：吸氣＝2秒：4秒"],"answer":0,"image":""},{"id":"md6-105-2-63","subject":"md6","topic":"復健-心肺復健與運動處方","meta":"105年第2次第63題","year":105,"session":2,"number":63,"question":"運動起始瞬間會發生氧缺現象（oxygen deficit），最初10秒肌肉收縮能源主要來自：","options":["(A) 游離脂肪酸（free fatty acid）","(B) 磷酸肌酸（phosphocreatine）","(C) 肝醣（glycogen）","(D) 乳酸（lactate）"],"answer":1,"image":""},{"id":"md6-105-2-64","subject":"md6","topic":"復健-兒童與一般復健","meta":"105年第2次第64題","year":105,"session":2,"number":64,"question":"有關腰椎脊柱裂併脊髓膨出症（myelomeningocele）之敘述，下列何者最為完整？①是胚胎期神經管的缺陷，隨著年齡增長會有可能增加嚴重度 ②患者會出現感覺缺損 ③患者會出現運動功能缺損 ④患者會出現大小便功能缺損","options":["(A) 僅①②","(B) 僅①③","(C) 僅①②③","(D) ①②③④"],"answer":3,"image":""},{"id":"md6-105-2-65","subject":"md6","topic":"復健-兒童與一般復健","meta":"105年第2次第65題","year":105,"session":2,"number":65,"question":"下列有關腦性麻痺的敘述，何者最為正確？","options":["(A) 多數腦性麻痺兒童臨床上呈現長期低張（hypotonia）","(B) 徐動型（athetoid）腦性麻痺常是因為高黃疸或缺氧後造成基底核（basal ganglion）的傷害","(C) 雙側麻痺（diplegia）指的是運動功能四肢受到相同的影響程度","(D) 偏癱型（hemiplegic）腦性麻痺病童大多數無法行走"],"answer":1,"image":""},{"id":"md6-105-2-66","subject":"md6","topic":"復健-神經復健","meta":"105年第2次第66題","year":105,"session":2,"number":66,"question":"腦中風病人單側咽部無力（pharyngeal weakness）的患者，最常使用下列何種姿勢進行吞嚥？","options":["(A) 頭轉向患側","(B) 頭轉向健側","(C) 仰頭進食","(D) 低頭進食"],"answer":0,"image":""},{"id":"md6-105-2-67","subject":"md6","topic":"復健-神經復健","meta":"105年第2次第67題","year":105,"session":2,"number":67,"question":"腦性麻痺患者說話常出現母音扭曲（distorted vowels）、嗓音停頓（voice stoppages），此屬於下列何種構音障礙？","options":["(A) 運動過強型構音障礙（hyperkinetic dysarthria）","(B) 弛緩型構音障礙（flaccid dysarthria）","(C) 運動失調型構音障礙（ataxic dysarthria）","(D) 痙攣型構音障礙（spastic dysarthria）"],"answer":0,"image":""},{"id":"md6-105-2-68","subject":"md6","topic":"復健-兒童與一般復健","meta":"105年第2次第68題","year":105,"session":2,"number":68,"question":"下列有關認知行為治療（cognitive-behavior therapy）的敘述，何者錯誤？","options":["(A) 個人的情緒反應常會受到對某事件的認知所影響","(B) 認知行為治療常用於急性疼痛（acute pain）的治療","(C) 認知行為治療常用於憂鬱症（depressive disorders）的治療","(D) 認知行為治療可強化個人的適應（adjustment）"],"answer":1,"image":""},{"id":"md6-105-2-69","subject":"md6","topic":"復健-兒童與一般復健","meta":"105年第2次第69題","year":105,"session":2,"number":69,"question":"下列何者不包括在基本日常生活自理（activity of daily living，ADL）的項目？","options":["(A) 如廁","(B) 煮飯","(C) 穿脫衣服","(D) 洗澡"],"answer":1,"image":""},{"id":"md6-105-2-70","subject":"md6","topic":"復健-骨骼肌肉損傷與疾患","meta":"105年第2次第70題","year":105,"session":2,"number":70,"question":"一位30歲女性，生產完兩個月，目前正在餵母乳。主訴為雙手麻痺，理學檢查發現雙手指第一指至第三指指尖感覺較遲鈍，Tinel’s sign在雙手腕處呈陽性，Phalen’s test亦為陽性，這位病人的臨床診斷最有可能為何？","options":["(A) 橈神經病變","(B) 尺神經病變","(C) 正中神經病變","(D) 頸神經根病變"],"answer":2,"image":""},{"id":"md6-105-2-71","subject":"md6","topic":"復健-骨骼肌肉損傷與疾患","meta":"105年第2次第71題","year":105,"session":2,"number":71,"question":"承上題，這位病患，下列何項治療最適合？","options":["(A) 口服消炎止痛劑","(B) 頸部牽引治療","(C) 腕部副木治療","(D) 充氣式壓迫療法（pneumatic compression）"],"answer":2,"image":""},{"id":"md6-105-2-72","subject":"md6","topic":"喉科學與頭頸腫瘤","meta":"105年第2次第72題","year":105,"session":2,"number":72,"question":"30歲女性患者，主訴咽喉有腫脹（fullness）的感覺，接受電腦斷層檢查，圖A為未注射顯影劑的影像，圖B則為注射顯影劑後的影像，下列何者是最可能的診斷？","options":["(A) 舌根癌（tongue base cancer）","(B) 血管瘤（hemangioma）","(C) 舌甲狀腺（lingual thyroid）","(D) 轉移（metastasis）"],"answer":2,"image":"md6-105-2-72.jpeg"},{"id":"md6-105-2-73","subject":"md6","topic":"婦科-生殖道感染與先天異常","meta":"105年第2次第73題","year":105,"session":2,"number":73,"question":"13歲女性病患，月經未來且下腹痛，故接受電腦斷層檢查，結果如下圖。其最有可能的診斷為何？","options":["(A) 子宮肌瘤（uterine myoma）","(B) 子宮內膜癌（endometrial cancer）","(C) 輸卵管卵巢膿瘍（tubo-ovarian abscess）","(D) 子宮融合異常合併處女膜未穿孔（uterine fusion abnormality with imperforated hymen）"],"answer":3,"image":"md6-105-2-73.jpeg"},{"id":"md6-105-2-74","subject":"md6","topic":"喉科學與頭頸腫瘤","meta":"105年第2次第74題","year":105,"session":2,"number":74,"question":"關於頭顱的骨纖維發育不良症（fibrous dysplasia），下列何者錯誤？","options":["(A) 可能是McCune-Albright syndrome的一部分","(B) 電腦斷層檢查可看見頭骨上出現ground glass matrix的影像表徵","(C) 核醫檢查，如PET，是確定診斷的最佳工具","(D) 臨床上多不會有疼痛的症狀"],"answer":2,"image":""},{"id":"md6-105-2-75","subject":"md6","topic":"喉科學與頭頸腫瘤","meta":"105年第2次第75題","year":105,"session":2,"number":75,"question":"60歲的李先生，抽菸數十年，8年前因鼻咽癌而接受放射治療，定期追蹤均無腫瘤復發，最近一年來有頭暈現象，三天前出現左手及左腳突然無力，持續30分鐘才恢復，下列處置何者為最優先？","options":["(A) 頸部聽診及杜卜勒超音波檢查","(B) 電腦斷層檢查頸椎是否有壓迫","(C) 臨床檢查是否有鼻咽腫瘤局部復發","(D) 全身核醫檢查及排除是否有其他轉移"],"answer":0,"image":""},{"id":"md6-105-2-76","subject":"md6","topic":"麻醉-呼吸道與監視","meta":"105年第2次第76題","year":105,"session":2,"number":76,"question":"關於程序性鎮靜和止痛（procedural sedation and analgesia），下列敘述何者不適當？","options":["(A) Midazolam可使用於輕度技術鎮靜和止痛","(B) Ketamine可使用於中度技術鎮靜和止痛","(C) Etomidate可使用於輕度技術鎮靜和止痛","(D) Propofol可使用於中度技術鎮靜和止痛"],"answer":[0,2,3],"image":"","answer_note":"更正:第76題答Ａ、Ｃ、Ｄ給分。"},{"id":"md6-105-2-77","subject":"md6","topic":"鼻科學","meta":"105年第2次第77題","year":105,"session":2,"number":77,"question":"下列有關急性鼻竇炎的敘述，何者錯誤？","options":["(A) 可使用類固醇鼻內噴劑以減輕症狀","(B) 病毒感染或過敏性鼻炎為常見的誘發因素","(C) 必須使用抗生素治療","(D) 診斷主要是靠病史及理學檢查"],"answer":2,"image":""},{"id":"md6-105-2-78","subject":"md6","topic":"產科-高危險妊娠","meta":"105年第2次第78題","year":105,"session":2,"number":78,"question":"關於懷孕婦女的膀胱炎或急性腎盂腎炎的敘述，下列何者錯誤？","options":["(A) 因為尿滯留，使得泌尿道是懷孕婦女最常見的感染位置","(B) 發生的單純膀胱炎（simple cystitis），給予單一劑量之抗生素，通常都可治療","(C) 泌尿道感染的最常見致病菌與非懷孕期婦女相同，為Escherichia coli","(D) 發生腎盂腎炎，由於產生合併症的機會大，通常須較非懷孕時予以更積極的治療"],"answer":1,"image":""},{"id":"md6-105-2-79","subject":"md6","topic":"醫學倫理與法規","meta":"105年第2次第79題","year":105,"session":2,"number":79,"question":"Ә施予及撤除維生治ऋ的措施必須有條件施行，才符合醫學৩਺，下列那一項不適當？","options":["(A) 無效醫ऋ","(B) 生命品質過差","(C) 無心智能ࠄ之病人拒絕治ऋ","(D) 治ऋ效果極差且耗用醫療資源極大"],"answer":2,"image":""},{"id":"md6-105-2-80","subject":"md6","topic":"醫學倫理與法規","meta":"105年第2次第80題","year":105,"session":2,"number":80,"question":"知情同意（informed consent）的實踐，是在落實那一項醫學倫理原則？","options":["(A) 行善原則（beneficence）","(B) 不傷害原則（non-maleficence）","(C) 正義原則（justice）","(D) 尊重自主原則（respect for autonomy）"],"answer":3,"image":""},{"id":"md6-106-1-1","subject":"md6","topic":"麻醉-呼吸道與監視","meta":"106年第1次第1題","year":106,"session":1,"number":1,"question":"呼吸道處置上潛在性的困難，下列何者的關係性最為薄弱？","options":["(A) 舌前緣的病灶（lesions at the anterior margin of the tongue）","(B) 新近發生的聲音沙啞（recent onset of hoarseness）","(C) 上呼吸道阻塞（upper airway obstruction）","(D) 睡眠呼吸中止症候（obstructive sleep apnea, OSA）"],"answer":0,"image":""},{"id":"md6-106-1-2","subject":"md6","topic":"麻醉-麻醉藥理","meta":"106年第1次第2題","year":106,"session":1,"number":2,"question":"麻醉藥物的效應可以大致分為催眠（hypnotic）以及止痛（analgesic）兩大方面來獨立考量，前者是麻醉深度監測（monitoring of the depth of anesthesia）的主要範疇。下列關於麻醉深度監測的敘述，何者錯誤？","options":["(A) 麻醉的深度可以用腦波圖（electroencephalogram, EEG）或由腦波圖計算出來的相關指標進行監測，主要是因為這些指標和麻醉藥物所導致的鎮靜、失憶（amnesia）、意識喪失、以及腦部代謝率降低相關性很高","(B) 手術過程中麻醉深度不足，可能導致病患術中清醒（intraoperative awareness），低體溫時，其發生率較高","(C) 越來越多的證據顯示，術中進行麻醉深度監測，有助於降低病患術中清醒的發生率。但是，進行此項監測，並不能保證病患完全不會發生術中清醒","(D) 在病患可以承受的範圍內，儘量維持適當而且穩定的吸入性麻醉氣體濃度，有助於減少病患術中清醒的發生"],"answer":1,"image":""},{"id":"md6-106-1-3","subject":"md6","topic":"麻醉-呼吸道與監視","meta":"106年第1次第3題","year":106,"session":1,"number":3,"question":"下列那些麻醉相關監視器對靜脈空氣栓塞（venous air embolism）偵測之敏感度（sensitivity），由高至低排列順序為何？ ①capnometer ②precordial doppler ③oximeter ④transesophageal echocardiograph","options":["(A) ①②③④","(B) ②①③④","(C) ②③①④","(D) ④②①③"],"answer":3,"image":""},{"id":"md6-106-1-4","subject":"md6","topic":"麻醉-麻醉藥理","meta":"106年第1次第4題","year":106,"session":1,"number":4,"question":"巴比妥類藥物，如thiopental，其主要作用機轉為何，使其可產生良好的鎮靜作用？","options":["(A) 阻斷鈉離子通道（sodium channel blocker）","(B) 加強γ-aminobutyric acid receptor作用","(C) 抑制N-methyl-D-aspartate receptor作用","(D) 加強α2 adrenergic receptor作用"],"answer":1,"image":""},{"id":"md6-106-1-5","subject":"md6","topic":"麻醉-麻醉藥理","meta":"106年第1次第5題","year":106,"session":1,"number":5,"question":"下列何者不影響最小肺泡濃度（minimum alveolar concentration）值？","options":["(A) 高血壓","(B) 肌肉鬆弛拮抗劑","(C) 缺氧（PaO2 < 40 mmHg）","(D) 使用reserpine"],"answer":0,"image":""},{"id":"md6-106-1-6","subject":"md6","topic":"麻醉-特殊麻醉與疼痛","meta":"106年第1次第6題","year":106,"session":1,"number":6,"question":"臺灣地區已邁入老年社會，下列有關老人常見的良性攝護腺肥大所進行的經尿道攝護腺切除（TURP）之麻醉的考量，何者錯誤？","options":["(A) 架腳（lithotomy）的姿勢會影響肺FRC（functional residual capacity）","(B) 通常實施半身麻醉，但術前評估心肺功能仍是必要","(C) 術中發生意識變化時，應抽血檢查血氧與血中鈉離子濃度","(D) 經尿道攝護腺切除症候群（TURP syndrome），因屬體液太多，血壓一定下降"],"answer":3,"image":""},{"id":"md6-106-1-7","subject":"md6","topic":"麻醉-呼吸道與監視","meta":"106年第1次第7題","year":106,"session":1,"number":7,"question":"下列何者不是氧氣治療（oxygen therapy）引起的併發症？","options":["(A) absorption atelectasis","(B) 在COPD的病人容易引起hyperventilation","(C) bronchopulmonary dysplasia","(D) 在新生兒常引起retinopathy of prematurity（ROP）"],"answer":1,"image":""},{"id":"md6-106-1-8","subject":"md6","topic":"麻醉-特殊麻醉與疼痛","meta":"106年第1次第8題","year":106,"session":1,"number":8,"question":"針對創傷病人進行早期復甦治療目標（goal of early resuscitation）的要求敘述，下列何者錯誤？","options":["(A) 維持hematocrit於25～30%間","(B) 維持中心體溫35℃以上","(C) 維持血小板50000/cumm以上","(D) 維持收縮血壓100～140 mmHg"],"answer":3,"image":""},{"id":"md6-106-1-9","subject":"md6","topic":"眼科-視網膜葡萄膜","meta":"106年第1次第9題","year":106,"session":1,"number":9,"question":"下列關於視網膜胚細胞瘤（retinoblastoma）之敘述，何者錯誤？","options":["(A) 是小兒最常見的眼內原發惡性腫瘤","(B) 最常出現的症狀為白色瞳孔（leukocoria）","(C) 與致病相關之基因（RB1）位於染色體13q14位置","(D) 治療選擇與腫瘤大小無關"],"answer":3,"image":""},{"id":"md6-106-1-10","subject":"md6","topic":"眼科-角膜結膜眼瞼眼窩","meta":"106年第1次第10題","year":106,"session":1,"number":10,"question":"下列有關棘狀阿米巴角膜炎（acanthamoeba keratitis）的敘述，何者錯誤？","options":["(A) 配戴隱形眼鏡為其主要危險因子","(B) 相較於單純疱疹角膜炎（herpes simplex keratitis），病人會有更明顯的眼睛疼痛","(C) 角膜典型表現為環狀角膜浸潤（ring-shape infiltration）","(D) 及時給與適當的藥物，一般約一星期左右可痊癒而停藥"],"answer":3,"image":""},{"id":"md6-106-1-11","subject":"md6","topic":"眼科-水晶體青光眼","meta":"106年第1次第11題","year":106,"session":1,"number":11,"question":"下列那個部位的水晶體由較老的晶體纖維（older lens fibers）堆積形成？","options":["(A) 小帶纖維（zonular fiber）","(B) 水晶體皮質（cortex）","(C) 水晶體核（nucleus）","(D) 晶囊（lens capsule）"],"answer":2,"image":""},{"id":"md6-106-1-12","subject":"md6","topic":"眼科-水晶體青光眼","meta":"106年第1次第12題","year":106,"session":1,"number":12,"question":"下列有關隅角（anterior chamber angle）的敘述，何者錯誤？","options":["(A) 隅角鏡（gonioscopy）可用來觀察隅角","(B) 小樑網（trabecular meshwork），鞏膜棘（scleral spur），虹膜突（iris process）都可看到時隅角是開放的（open）","(C) 近視眼的眼球隅角通常較窄","(D) 有些隅角閉鎖性青光眼是因老年性白內障時水晶體變厚導致"],"answer":2,"image":""},{"id":"md6-106-1-13","subject":"md6","topic":"眼科-屈光斜弱視","meta":"106年第1次第13題","year":106,"session":1,"number":13,"question":"內斜視眼在做交替遮蓋測驗（alternate cover test）時，遮蓋物由右眼移至左眼時，右眼會呈現何種移動？","options":["(A) 內展（adduction）","(B) 外展（abduction）","(C) 向下（downword movement）","(D) 向上（upward movement）"],"answer":1,"image":""},{"id":"md6-106-1-14","subject":"md6","topic":"眼科-屈光斜弱視","meta":"106年第1次第14題","year":106,"session":1,"number":14,"question":"下列何者之兩條外眼肌肉不是共軛肌（yoke muscle）？","options":["(A) 右眼外直肌（right lateral rectus muscle）和左眼內直肌（left medial rectus muscle）","(B) 右眼上直肌（right superior rectus muscle）和左眼上斜肌（left superior oblique muscle）","(C) 右眼上直肌（right superior rectus muscle）和左眼下斜肌（left inferior oblique muscle）","(D) 右眼內直肌（right medial rectus muscle）和左眼外直肌（left lateral rectus muscle）"],"answer":1,"image":""},{"id":"md6-106-1-15","subject":"md6","topic":"眼科-屈光斜弱視","meta":"106年第1次第15題","year":106,"session":1,"number":15,"question":"由遠看近時，所產生的近反射反應（near reflex）不包括下列何者？","options":["(A) 調節（accommodation）","(B) 會聚（convergence）","(C) 瞳孔收縮（constriction of the pupil）","(D) 虹彩血管收縮（iris vessel constriction）"],"answer":3,"image":""},{"id":"md6-106-1-16","subject":"md6","topic":"眼科-角膜結膜眼瞼眼窩","meta":"106年第1次第16題","year":106,"session":1,"number":16,"question":"下列何種病原最容易導致急性出血性結膜炎（acute hemorrhagic conjunctivitis）？","options":["(A) 單純疱疹病毒（Herpes simplex virus）","(B) 腸病毒（Enterovirus）","(C) 砂眼披衣菌（Chlamydia trachomatis）","(D) 淋球菌（Neisseria gonorrhoeae）"],"answer":1,"image":""},{"id":"md6-106-1-17","subject":"md6","topic":"耳科學","meta":"106年第1次第17題","year":106,"session":1,"number":17,"question":"良性陣發性姿勢性眩暈（benign paroxysmal positional vertigo, BPPV）是橢圓囊或球囊中的耳石（otolith）脫落，掉入半規管中，耳石脫落最常見是掉入：","options":["(A) 側半規管（lateral semicircular canal）","(B) 後半規管（posterior semicircular canal）","(C) 上半規管（superior semicircular canal）","(D) 水平半規管（horizontal semicircular canal）"],"answer":1,"image":""},{"id":"md6-106-1-18","subject":"md6","topic":"耳科學","meta":"106年第1次第18題","year":106,"session":1,"number":18,"question":"4歲女童，因感冒來就診，右耳耳鏡檢查發現耳膜完整，前下方有一白色腫塊（mass，如下圖），最有可能之診斷為何？","options":["(A) 聽神經瘤（acoustic neuroma）","(B) 膽固醇肉芽腫（cholesterol granuloma）","(C) 先天性膽脂瘤（congenital cholesteatoma）","(D) 後天性膽脂瘤（acquired cholesteatoma）"],"answer":2,"image":"md6-106-1-18.jpeg"},{"id":"md6-106-1-19","subject":"md6","topic":"鼻科學","meta":"106年第1次第19題","year":106,"session":1,"number":19,"question":"一個50歲臺灣男性病人患有單側右耳積液性中耳炎，合併右側上頸部4公分大無痛性淋巴結腫大，須高度懷疑可能有下列那一種癌症？","options":["(A) 喉癌","(B) 下咽癌","(C) 鼻咽癌","(D) 腮腺癌"],"answer":2,"image":""},{"id":"md6-106-1-20","subject":"md6","topic":"鼻科學","meta":"106年第1次第20題","year":106,"session":1,"number":20,"question":"一位55歲女性病人，無糖尿病或高血壓病史，在游泳後突然覺得稍有鼻塞、疲勞、頭痛，但無發燒，白血球數目亦正常，經過3天，她覺得每天早上剛起床不頭痛，1～2小時後才頭痛起來（持續約3～4小時），到下午又漸漸好轉，最可能診斷為何？","options":["(A) 急性額竇炎","(B) 急性蝶竇炎","(C) 海綿竇栓塞","(D) 急性上頜竇炎"],"answer":0,"image":""},{"id":"md6-106-1-21","subject":"md6","topic":"鼻科學","meta":"106年第1次第21題","year":106,"session":1,"number":21,"question":"檢查病患時，聞到鼻腔內有臭味，下列何者最不可能？","options":["(A) 萎縮性鼻炎","(B) 鼻癌或鼻竇癌","(C) 下鼻甲肥厚","(D) 鼻道內異物"],"answer":2,"image":""},{"id":"md6-106-1-22","subject":"md6","topic":"喉科學與頭頸腫瘤","meta":"106年第1次第22題","year":106,"session":1,"number":22,"question":"有關學齡前兒童有構音障礙之敘述，下列何者錯誤？","options":["(A) 舌繫帶較短的小孩，約有15％會有構音障礙，應及早手術","(B) 純音聽力檢查是重要的檢查","(C) 言語復健治療，有助於改正構音障礙","(D) 黏膜下腭裂是可能的原因之一"],"answer":0,"image":""},{"id":"md6-106-1-23","subject":"md6","topic":"喉科學與頭頸腫瘤","meta":"106年第1次第23題","year":106,"session":1,"number":23,"question":"有關於鼻咽癌之敘述，下列何者正確？","options":["(A) 頸部淋巴腫大是最常見之初始病徵","(B) 鼻咽腫瘤大小通常與淋巴轉移程度成正比","(C) 遠端轉移好發處依次為肺、腦、骨","(D) 病理學分類以WHO type I最多"],"answer":0,"image":""},{"id":"md6-106-1-24","subject":"md6","topic":"喉科學與頭頸腫瘤","meta":"106年第1次第24題","year":106,"session":1,"number":24,"question":"請參閱附圖回答本題。胡先生是一位25歲的研究所學生，臉部因車禍嚴重撞擊，造成右側上顎骨開放性骨折。因持續出血、收縮壓降低至50 mmHg，於手術室中進行止血失敗，主刀醫師當機立斷，於右側頸部打開一約10公分傷口，暴露頸動脈竇附近大血管構造，打算阻斷顏面血液供應，以達到止血的目的。於圖中何處血管進行結繫最適當？","options":["(A) 1","(B) 2","(C) 3","(D) 4"],"answer":2,"image":"md6-106-1-24.jpeg"},{"id":"md6-106-1-25","subject":"md6","topic":"產科-高危險妊娠","meta":"106年第1次第25題","year":106,"session":1,"number":25,"question":"下列何者並非新生兒呼吸窘迫（neonatal respiratory distress syndrome）的危險因子之一？","options":["(A) 新生兒性別為男性（male gender）","(B) 母親於產前有使用類固醇藥物（glucocorticoids）","(C) 早產","(D) 新生兒種族為白人（white race）"],"answer":1,"image":""},{"id":"md6-106-1-26","subject":"md6","topic":"產科-一般產科","meta":"106年第1次第26題","year":106,"session":1,"number":26,"question":"下列何者為使用真空吸引器（vacuum extraction）的禁忌症？","options":["(A) 胎兒為面產式（face presentation）","(B) 妊娠35週","(C) 羊膜絨毛膜發炎（chorioamnionitis）","(D) 過期妊娠（post-term pregnancy）"],"answer":0,"image":""},{"id":"md6-106-1-27","subject":"md6","topic":"產科-一般產科","meta":"106年第1次第27題","year":106,"session":1,"number":27,"question":"30歲孕婦，妊娠42週，欲予引產，根據Bishop score評分其子宮頸成熟度，若子宮頸閉合，Effacement 10%，Station：-3，子宮頸硬度為堅硬（firm），並且子宮頸位於後方。Bishop score為幾分？","options":["(A) 0","(B) 3","(C) 6","(D) 9"],"answer":0,"image":""},{"id":"md6-106-1-28","subject":"md6","topic":"婦科-良性腫瘤與內膜異位","meta":"106年第1次第28題","year":106,"session":1,"number":28,"question":"23歲女性主訴7天前有陰道出血之情形，量如月經來第4天之量，近2日常感覺右下腹疼痛，今日則因疼痛加劇而就醫。經陰道指診發現子宮有觸壓疼痛的情形，同時右邊亦有觸壓疼痛的情形。超音波掃描發現右邊子宮附屬物有腫塊，大小約3.5×3.8公分，尿液懷孕試驗呈現陽性反應。由於右下腹痛加劇，因此接受腹腔鏡檢查，腹腔鏡檢查發現有下圖之情形，依據圖示此患者最適合之診斷為：","options":["(A) 卵巢腫瘤合併扭轉（ovarian tumor with torsion）","(B) 輸卵管外孕（tubal pregnancy）","(C) 急性盲腸炎（appendicitis）","(D) 輸尿管結石（ureteral stone）"],"answer":1,"image":"md6-106-1-28.jpeg"},{"id":"md6-106-1-29","subject":"md6","topic":"婦科-手術學與診斷技術","meta":"106年第1次第29題","year":106,"session":1,"number":29,"question":"下列何者為手術後發燒（febrile morbidity）的定義？","options":["(A) 術後24小時後，有任2次至少間隔4小時的體溫高於38℃","(B) 術後24小時後，有任2次至少間隔4小時的體溫高於39.5℃","(C) 術後24小時內，體溫有1次高於38.3℃","(D) 術後24小時內，體溫有1次高於39.5℃"],"answer":0,"image":""},{"id":"md6-106-1-30","subject":"md6","topic":"婦科-生殖內分泌","meta":"106年第1次第30題","year":106,"session":1,"number":30,"question":"52歲女性，身高160公分，體重58公斤，主訴失眠、熱潮紅及焦慮，骨質密度掃描呈現骨質稀少（osteopenia），最近的一次月經為兩年前，之前沒有手術史或是內科病史。給與此病患荷爾蒙治療最適合的理由為下列何者？","options":["(A) 降低阿茲海默症之風險","(B) 降低靜脈栓塞疾病之風險","(C) 降低骨質疏鬆之風險","(D) 降低子宮內膜癌之風險"],"answer":2,"image":""},{"id":"md6-106-1-31","subject":"md6","topic":"婦科-良性腫瘤與內膜異位","meta":"106年第1次第31題","year":106,"session":1,"number":31,"question":"根據American Society for Reproductive Medicine Revised Classification of Endometriosis，若病患手術中評估之score為28分，其子宮內膜異位嚴重度為那一個stage？","options":["(A) Stage I","(B) Stage II","(C) Stage III","(D) Stage IV"],"answer":2,"image":""},{"id":"md6-106-1-32","subject":"md6","topic":"婦科-腫瘤","meta":"106年第1次第32題","year":106,"session":1,"number":32,"question":"有關人類乳突病毒（human papilloma virus, HPV）的敘述，下列何者最正確？","options":["(A) 有性經驗的女性，約有20%曾被感染","(B) 大部分被HPV感染的人都會產生生殖器官疣、子宮頸上皮病變及癌症","(C) 高危險HPV有多型，其中最常引致子宮頸癌的是第16型","(D) HPV疫苗可有效預防子宮頸癌，施打之後就不需要抹片檢查"],"answer":2,"image":""},{"id":"md6-106-1-33","subject":"md6","topic":"婦科-腫瘤","meta":"106年第1次第33題","year":106,"session":1,"number":33,"question":"子宮內膜腺癌病患求診，身高160公分，體重82公斤，經詳細追蹤其病史，發現初經年齡為10歲，停經年齡為55歲，結婚初期曾因不想生育，服用過口服避孕藥有3～5年，後抹片異常經診斷為cervical intraepithelial neoplasia 2（CIN 2），曾接受局部治療。病患之子宮內膜癌的高危險因子中，不包括下列何者？","options":["(A) 肥胖","(B) 初經早","(C) 停經晚","(D) 服用口服避孕藥"],"answer":3,"image":""},{"id":"md6-106-1-34","subject":"md6","topic":"產科-一般產科","meta":"106年第1次第34題","year":106,"session":1,"number":34,"question":"有關misoprostol之敘述，下列何者正確？","options":["(A) Misoprostol為E2前列腺素（prostaglandin）","(B) Misoprostol比催產素（oxytocin）更能有效預防產後大出血","(C) 用於預防產後大出血的劑量為單次口服600 µg","(D) 最有效之給予方式為肌肉注射"],"answer":2,"image":""},{"id":"md6-106-1-35","subject":"md6","topic":"產科-高危險妊娠","meta":"106年第1次第35題","year":106,"session":1,"number":35,"question":"關於慢性高血壓孕婦併發子癇前症（pre-eclampsia），下列敘述何者錯誤？","options":["(A) 在有慢性高血壓的孕婦中，大約有20%～30%的孕婦會發生子癇前症","(B) 慢性高血壓孕婦併發子癇前症的週數，約有50%發生在37週之前","(C) 有慢性高血壓的孕婦之前血壓能控制在130/85 mmHg左右，若近期血壓使用先前藥物仍然不能控制在140/90 mmHg以下時，建議安排生產","(D) 若有慢性高血壓的孕婦在懷孕前沒有腎臟疾病，懷孕後肌酸酐（creatinine）若大於1.1 mg/dL則可診斷為子癇前症"],"answer":2,"image":""},{"id":"md6-106-1-36","subject":"md6","topic":"產科-高危險妊娠","meta":"106年第1次第36題","year":106,"session":1,"number":36,"question":"孕婦因大量出血而導致急性呼吸窘迫症候群時，下列處置何者最能增加組織的血氧量？","options":["(A) 輸血","(B) 分娩","(C) 增加動脈氧分壓至200 mmHg","(D) 置入肺動脈導管"],"answer":0,"image":""},{"id":"md6-106-1-37","subject":"md6","topic":"產科-一般產科","meta":"106年第1次第37題","year":106,"session":1,"number":37,"question":"如圖所示，為真空吸引輔助陰道生產，最適合放置真空吸引器之胎兒頭部位置。下列敘述何者不是放置於該處之優點？","options":["(A) 提供最大的吸引力道","(B) 幫助頭部伸展（extension）","(C) 讓胎兒頭部的最小徑經過骨盆腔出口","(D) 降低真空吸引器於輔助生產時，與胎兒頭部脫開之機會"],"answer":1,"image":"md6-106-1-37.jpeg"},{"id":"md6-106-1-38","subject":"md6","topic":"產科-高危險妊娠","meta":"106年第1次第38題","year":106,"session":1,"number":38,"question":"下列那一種狀況與羊水栓塞症（amniotic fluid embolism）的發生最無相關？","options":["(A) 急產（rapid labor）","(B) 羊水胎便染色（meconium-stained amniotic fluid）","(C) 子宮靜脈裂傷（tears into uterine veins）","(D) 早產（preterm delivery）"],"answer":3,"image":""},{"id":"md6-106-1-39","subject":"md6","topic":"產科-高危險妊娠","meta":"106年第1次第39題","year":106,"session":1,"number":39,"question":"下列何者不是肥胖症（obesity）孕婦容易發生的孕期母胎合併症（complications）？","options":["(A) 妊娠糖尿病（gestational diabetes mellitus）","(B) 子癇前症（preeclampsia）","(C) 過期妊娠（postterm pregnancy）","(D) 早期破水（preterm rupture of membranes）"],"answer":3,"image":""},{"id":"md6-106-1-40","subject":"md6","topic":"產科-一般產科","meta":"106年第1次第40題","year":106,"session":1,"number":40,"question":"胎兒娩出後，胎盤無法自行娩出，並出現子宮大出血狀況，應優先採取下列那一項處置方式？","options":["(A) 以紗布填塞子宮及陰道","(B) 等待胎盤自行子宮剝離","(C) 子宮按摩並用人工剝離胎盤","(D) 以胎盤鉗夾取出子宮內胎盤"],"answer":2,"image":""},{"id":"md6-106-1-41","subject":"md6","topic":"婦科-尿失禁與骨盆腔脫垂","meta":"106年第1次第41題","year":106,"session":1,"number":41,"question":"下列何種骨盆腔脫垂，在病理生理及解剖構造上較符合疝氣（hernia）的定義？","options":["(A) 尿道膨出（urethrocele）","(B) 膀胱膨出（cystocele）","(C) 小腸膨出（enterocele）","(D) 直腸膨出（rectocele）"],"answer":2,"image":""},{"id":"md6-106-1-42","subject":"md6","topic":"婦科-尿失禁與骨盆腔脫垂","meta":"106年第1次第42題","year":106,"session":1,"number":42,"question":"依照International Continence Society所提出Pelvic Organ Prolapse Quantification system（POP-Q）不同部位缺陷之定量測量，其數值之呈現可用另一種方式：以一條直線數字串方式來表示，如-3, -4, -8, -10, -3, -3, 11, 4, 3。但是，此列數值於何測量部位是不合情理？","options":["(A) Point Aa","(B) Point Ba","(C) Point C","(D) Point D"],"answer":1,"image":""},{"id":"md6-106-1-43","subject":"md6","topic":"婦科-腫瘤","meta":"106年第1次第43題","year":106,"session":1,"number":43,"question":"40歲病患，因子宮頸抹片結果為高危險鱗狀上皮內細胞病變（HSIL），下一步診療何者正確？","options":["(A) 追蹤","(B) 陰道鏡檢查及子宮頸切片","(C) 子宮頸錐狀切除","(D) 子宮切除"],"answer":[1,2],"image":"","answer_note":"更正:第43題答Ｂ、Ｃ給分"},{"id":"md6-106-1-44","subject":"md6","topic":"婦科-腫瘤","meta":"106年第1次第44題","year":106,"session":1,"number":44,"question":"關於卵巢上皮癌所用的抗癌藥物中，最常引起手足症候群（hand-foot syndrome），是下列那一種化學藥物製劑？","options":["(A) Taxanes","(B) Topotecan","(C) Liposomal doxorubicin","(D) Gemcitabine"],"answer":2,"image":""},{"id":"md6-106-1-45","subject":"md6","topic":"婦科-腫瘤","meta":"106年第1次第45題","year":106,"session":1,"number":45,"question":"關於妊娠滋養細胞疾病（gestational trophoblastic disease-GTD；gestational trophoblastic tumor-GTT；gestational trophoblastic neoplasm-GTN），下列何者敘述婦癌醫師較有一致的看法？","options":["(A) GTT或GTN中要依手術病理之期別後，開始化學治療","(B) 轉移到肺部為第三期，治療後之緩解率將近50%","(C) 均對單劑化學藥物的治療有反應","(D) 葡萄胎（complete hydatidiform mole）比部分葡萄胎（partial hydatidiform mole）少見"],"answer":3,"image":""},{"id":"md6-106-1-46","subject":"md6","topic":"婦科-生殖內分泌","meta":"106年第1次第46題","year":106,"session":1,"number":46,"question":"關於卵巢濾泡雙細胞雙性腺刺激素系統（two-cell，two-gonadotropin system）之敘述，下列何者錯誤？","options":["(A) 濾泡中顆粒細胞（granulosa cells）的細胞膜上有FSH受體（receptor）","(B) 顆粒細胞中的芳香環轉化酶（aromatase）活性是受FSH的刺激才活化","(C) 卵巢濾泡在排卵之後，黃體化的顆粒細胞之細胞膜上會同時出現FSH受體與LH受體","(D) 卵巢濾泡周圍的卵囊膜細胞（theca cells）只有LH受體"],"answer":2,"image":""},{"id":"md6-106-1-47","subject":"md6","topic":"婦科-生殖內分泌","meta":"106年第1次第47題","year":106,"session":1,"number":47,"question":"下列何者不是由α-subunit與β-subunit組合而成的激素？","options":["(A) GnRH（gonadotropin releasing hormone）","(B) TSH（thyroid stimulating hormone）","(C) FSH（follicle stimulating hormone）","(D) LH（luteinizing hormone）"],"answer":0,"image":""},{"id":"md6-106-1-48","subject":"md6","topic":"婦科-生殖內分泌","meta":"106年第1次第48題","year":106,"session":1,"number":48,"question":"關於激素（hormone）的激動劑（agonist）與抑制劑（antagonist）之敘述，下列何者錯誤？","options":["(A) 激動劑（agonist）與抑制劑（antagonist）都須先與受體結合，才能啟動後續之作用","(B) 抑制劑（antagonist）與受體結合後，會阻斷受體訊息的傳遞","(C) Clomiphene是雌激素的抑制劑（antagonist），會抑制子宮內膜的生長","(D) Tamoxifen是雌激素的抑制劑（antagonist），會抑制子宮內膜的生長"],"answer":3,"image":""},{"id":"md6-106-1-49","subject":"md6","topic":"婦科-生殖內分泌","meta":"106年第1次第49題","year":106,"session":1,"number":49,"question":"35歲女性，因為月經1年沒來前來求診，1年半前自然產下第三胎，產後未哺餵母乳，至今也仍無月經來潮。進一步問診後，得知生產時因大量出血合併休克曾接受緊急輸血。下列何項檢驗項目最無法幫助確診？","options":["(A) LH","(B) FSH","(C) Prolactin","(D) CBC"],"answer":3,"image":""},{"id":"md6-106-1-50","subject":"md6","topic":"婦科-生殖內分泌","meta":"106年第1次第50題","year":106,"session":1,"number":50,"question":"有關排卵藥clomiphene citrate敘述，下列何者錯誤？","options":["(A) 主要可以治療促性腺激素低下型低性腺功能症（hypogonadotropic hypogonadism WHO group I）患者的無排卵現象","(B) 選擇性雌激素接受器調節劑，可以影響雌激素負回饋反應，刺激濾泡發育","(C) 治療的副作用可能包括子宮頸黏液分泌減少、子宮內膜生長受損以及多胞胎妊娠","(D) 某些病患治療後仍然無法排卵時，可以結合胰島素增敏劑metformin，增加排卵的機會"],"answer":0,"image":""},{"id":"md6-106-1-51","subject":"md6","topic":"婦科-生殖內分泌","meta":"106年第1次第51題","year":106,"session":1,"number":51,"question":"下列何者非為透納氏症候群Turner syndrome之特徵？","options":["(A) 身材短小","(B) 無月經","(C) 不孕症","(D) 青春痘增生"],"answer":3,"image":""},{"id":"md6-106-1-52","subject":"md6","topic":"婦科-手術學與診斷技術","meta":"106年第1次第52題","year":106,"session":1,"number":52,"question":"下列何者並非口服避孕藥（oral contraceptive pills）之絕對禁忌症？","options":["(A) 原因尚不明之陰道出血","(B) 長期每天抽2包菸的40歲女性","(C) 過去健檢時肝指數曾經稍高，後續門診追蹤皆正常，也無肝臟疾病","(D) 過去曾有肺栓塞"],"answer":2,"image":""},{"id":"md6-106-1-53","subject":"md6","topic":"產科-一般產科","meta":"106年第1次第53題","year":106,"session":1,"number":53,"question":"29歲孕婦，G3P2，妊娠18週，接受超音波檢查，結果如圖所示，圖中箭頭所指之胎兒異常器官名稱與特徵（sign）為何？","options":["(A) cerebrum，frog sign","(B) cerebellum，banana sign","(C) skull，lemon sign","(D) ventricle，keyhole sign"],"answer":1,"image":"md6-106-1-53.jpeg"},{"id":"md6-106-1-54","subject":"md6","topic":"產科-一般產科","meta":"106年第1次第54題","year":106,"session":1,"number":54,"question":"承上題，檢查結果最可能合併的畸形為下列何者？","options":["(A) Down syndrome","(B) Trisomy 13","(C) Trisomy 18","(D) Neural tube defect"],"answer":3,"image":""},{"id":"md6-106-1-55","subject":"md6","topic":"復健-神經復健","meta":"106年第1次第55題","year":106,"session":1,"number":55,"question":"下列何種指標最不常用於臨床上評估腦傷（traumatic brain injury）病人的預後？","options":["(A) 腦傷後癲癇（seizure）的發生頻率","(B) 昏迷（duration of coma）時間的長短","(C) 格拉司哥氏昏迷指數（Glasgow coma scale）","(D) 腦傷後失憶（amnesia）時間的長短"],"answer":0,"image":""},{"id":"md6-106-1-56","subject":"md6","topic":"復健-神經復健","meta":"106年第1次第56題","year":106,"session":1,"number":56,"question":"下列何者為急性期中風病人最常發生的併發症？","options":["(A) 肺炎","(B) 褥瘡","(C) 靜脈栓塞","(D) 癲癇發作"],"answer":0,"image":""},{"id":"md6-106-1-57","subject":"md6","topic":"復健-神經復健","meta":"106年第1次第57題","year":106,"session":1,"number":57,"question":"捏擠龜頭或者摩擦陰蒂可以引起肛門外括約肌收縮的是什麼反射？","options":["(A) 肛門反射（anal reflex）","(B) 球海綿體肌反射（bulbocavernosus reflex）","(C) 提睪肌反射（cremasteric reflex）","(D) 逼尿肌反射（detrusor reflex）"],"answer":1,"image":""},{"id":"md6-106-1-58","subject":"md6","topic":"復健-神經復健","meta":"106年第1次第58題","year":106,"session":1,"number":58,"question":"下列有關人類的神經傳導速度檢查（nerve conduction study）之敘述，何者錯誤？","options":["(A) 常用於分辨肌肉病變與神經病變","(B) 神經傳導速度在出生的嬰兒只有成人的一半","(C) 常用於分辨急性與慢性神經病變","(D) 神經傳導速度與體溫成正相關"],"answer":2,"image":""},{"id":"md6-106-1-59","subject":"md6","topic":"復健-骨骼肌肉損傷與疾患","meta":"106年第1次第59題","year":106,"session":1,"number":59,"question":"下列那一種疾病最容易造成遠端指關節（distal inter-phalangeal joint）發炎？","options":["(A) 骨性（osteoarthritis）關節炎","(B) 類風濕（rheumatoid）關節炎","(C) 血友病（hemophilic）關節炎","(D) 痛風性（gouty）關節炎"],"answer":0,"image":""},{"id":"md6-106-1-60","subject":"md6","topic":"復健-骨骼肌肉損傷與疾患","meta":"106年第1次第60題","year":106,"session":1,"number":60,"question":"骨折手術後，下列那一種運動最能避免骨關節受到不恰當的受力？","options":["(A) 等長性收縮（isometric contraction）","(B) 向心性等張式收縮（concentric isotonic contraction）","(C) 離心性等張式收縮（eccentric isotonic contraction）","(D) 等速性收縮（isokinetic contraction）"],"answer":0,"image":""},{"id":"md6-106-1-61","subject":"md6","topic":"復健-骨骼肌肉損傷與疾患","meta":"106年第1次第61題","year":106,"session":1,"number":61,"question":"下一列那一條韌帶在踝關節扭傷發生率最高？","options":["(A) 三角韌帶（deltoid ligament）","(B) 前脛腓骨韌帶（anterior tibiofibular ligament）","(C) 後距腓骨韌帶（posterior talofibular ligament）","(D) 前距腓骨韌帶（anterior talofibular ligament）"],"answer":3,"image":""},{"id":"md6-106-1-62","subject":"md6","topic":"復健-截肢與義肢輔具","meta":"106年第1次第62題","year":106,"session":1,"number":62,"question":"下列那一種裝具對頭頸椎活動度的限制效果最差？","options":["(A) 費城支架（Philadelphia collar）","(B) 軟式頸圈（soft collar）","(C) 四柱式支架（4-poster brace）","(D) 暈輪式背心（halo vest）"],"answer":1,"image":""},{"id":"md6-106-1-63","subject":"md6","topic":"復健-心肺復健與運動處方","meta":"106年第1次第63題","year":106,"session":1,"number":63,"question":"下列何者是不可改善的心臟疾病危險因子？","options":["(A) 高血壓","(B) 家族史","(C) 吸煙","(D) 靜態（sedentary）生活"],"answer":1,"image":""},{"id":"md6-106-1-64","subject":"md6","topic":"復健-心肺復健與運動處方","meta":"106年第1次第64題","year":106,"session":1,"number":64,"question":"下列何者不可作為處方心臟病患者運動時運動強度的指標？","options":["(A) 血氧濃度","(B) 最大心跳率的百分比","(C) 運動自覺量表","(D) 代謝當量（MET）"],"answer":0,"image":""},{"id":"md6-106-1-65","subject":"md6","topic":"復健-心肺復健與運動處方","meta":"106年第1次第65題","year":106,"session":1,"number":65,"question":"心肌梗塞（myocardial infarction）的病人急性期（第一期）的復健原則不包含下列那一項？","options":["(A) 儘早活動（early mobilization）","(B) 可以下二層樓梯","(C) 從事身體活動2～3 METS以內的運動","(D) 運動中需要監控血壓上升或下降不可超過20mmHg"],"answer":3,"image":""},{"id":"md6-106-1-66","subject":"md6","topic":"復健-兒童與一般復健","meta":"106年第1次第66題","year":106,"session":1,"number":66,"question":"下列有關腦性麻痺之敘述，何者錯誤？","options":["(A) 腦性麻痺兒童臨床之評估包含肌張力、反射、姿勢及不正常的運動表現","(B) 一歲以前提早出現明顯的慣用手，需仔細評估是否可能係偏癱性腦性麻痺或是其他周邊神經損傷","(C) 痙攣型單肢偏癱（spastic monoplegia）腦性麻痺臨床上最常見","(D) 痙攣型四肢麻痺（spastic quadriplegia）病童常合併吞嚥困難"],"answer":2,"image":""},{"id":"md6-106-1-67","subject":"md6","topic":"復健-骨骼肌肉損傷與疾患","meta":"106年第1次第67題","year":106,"session":1,"number":67,"question":"下列何者之膝部疼痛，最可能是歐氏病（Osgood-Schlatter disease）所引起？","options":["(A) 15歲男性排球選手","(B) 20歲女性芭蕾舞者","(C) 15歲女性游泳選手","(D) 20歲男性自由車選手"],"answer":0,"image":""},{"id":"md6-106-1-68","subject":"md6","topic":"復健-神經復健","meta":"106年第1次第68題","year":106,"session":1,"number":68,"question":"下列有關腦中風後中樞痛（central pain）之敘述，何者最為正確？","options":["(A) 中樞痛多發生在大腦中樞神經系統病灶之對側","(B) 小的中風病灶不會引發中樞痛","(C) 中樞痛在病發後一年內發生的比率非常高","(D) 大部分中樞痛病人之溫覺（temperature perception）不受影響"],"answer":[0,2],"image":"","answer_note":"更正:第68題答Ａ、Ｃ給分。"},{"id":"md6-106-1-69","subject":"md6","topic":"醫學倫理與法規","meta":"106年第1次第69題","year":106,"session":1,"number":69,"question":"依現行身心障礙者權益保護法，下列敘述何者錯誤？","options":["(A) 各級政府機關及公營事業機構員工總人數在34人以上者，進用具有就業能力之身心障礙者人數，不得低於員工總人數3%","(B) 公共停車場應保留2%停車位，作為行動不便之身心障礙者專用停車位","(C) 身心障礙者進入收費之公營風景區、康樂場所或文教設施，憑身心障礙證明應予半價優待","(D) 各級政府應至少每五年舉辦身心障礙者之生活狀況、保健醫療、特殊教育、就業與訓練等需求評估及服務調查研究"],"answer":2,"image":""},{"id":"md6-106-1-70","subject":"md6","topic":"復健-神經復健","meta":"106年第1次第70題","year":106,"session":1,"number":70,"question":"在脊髓損傷急性期，最容易發生壓瘡（pressure ulcer）之部位為何？","options":["(A) 坐骨（ischium）","(B) 薦骨（sacrum）","(C) 股骨大轉子（greater trochanter）","(D) 足跟（heel）"],"answer":1,"image":""},{"id":"md6-106-1-71","subject":"md6","topic":"復健-兒童與一般復健","meta":"106年第1次第71題","year":106,"session":1,"number":71,"question":"下列何者最不常用於吞嚥功能的評估？","options":["(A) 理學檢查（physical examination）","(B) 動態吞嚥攝影（videofluorographic swallowing study）","(C) 電腦斷層咽喉掃描（CT scan of pharynx）","(D) 纖維內視鏡吞嚥檢查（fiberoptic endoscopic examination of swallowing）"],"answer":2,"image":""},{"id":"md6-106-1-72","subject":"md6","topic":"復健-骨骼肌肉損傷與疾患","meta":"106年第1次第72題","year":106,"session":1,"number":72,"question":"85歲女性患者，主訴左肩疼痛超過6個月，有局部壓痛，無肌肉萎縮現象，圖為左肩部超音波檢查，上圖為旋轉環帶長軸切面，下圖為短軸切面，最可能之診斷為何？","options":["(A) 風濕性關節炎（rheumatoid arthritis）","(B) 棘上肌腱斷裂（supraspinatus tendon tear）","(C) 化膿性關節炎（pyogenic arthritis）","(D) 肩三角肌撕裂（deltoid muscle tear）"],"answer":1,"image":"md6-106-1-72.jpeg"},{"id":"md6-106-1-73","subject":"md6","topic":"復健-骨骼肌肉損傷與疾患","meta":"106年第1次第73題","year":106,"session":1,"number":73,"question":"51歲男性病人，右側肩膀疼痛，且轉動受限。超音波及X光片檢查如圖，最可能的診斷為何？","options":["(A) 旋轉環帶斷裂（rotator cuff tear）","(B) 退化性關節炎（degenerative arthritis）","(C) 肩峰及三角肌下滑膜炎（subacromial-subdeltoid bursitis）","(D) 鈣化性肌腱變性（calcific tendinosis）"],"answer":2,"image":"md6-106-1-73.jpeg"},{"id":"md6-106-1-74","subject":"md6","topic":"復健-神經復健","meta":"106年第1次第74題","year":106,"session":1,"number":74,"question":"關於動脈粥樣硬化之頸動脈狹窄（carotid stenosis）的敘述，下列何者錯誤？","options":["(A) 導管血管攝影檢查是篩選高風險病患最安全的方法","(B) 與抽菸及高血壓有關","(C) 頭頸部癌症病患接受放射治療，也會增加其發生率","(D) 可以藥物、外科手術或支架置放治療"],"answer":0,"image":""},{"id":"md6-106-1-75","subject":"md6","topic":"婦科-生殖道感染與先天異常","meta":"106年第1次第75題","year":106,"session":1,"number":75,"question":"32歲女性，子宮輸卵管攝影檢查呈現如圖，箭號所指之敘述何者最正確？","options":["(A) 子宮肌瘤","(B) 單角子宮","(C) 子宮內膜異位","(D) 子宮（輸卵管）外孕"],"answer":1,"image":"md6-106-1-75.jpeg"},{"id":"md6-106-1-76","subject":"md6","topic":"麻醉-呼吸道與監視","meta":"106年第1次第76題","year":106,"session":1,"number":76,"question":"下列何者為使用rapid sequence intubation（RSI）的禁忌？","options":["(A) 躁動","(B) 癲癇發作","(C) 藥物過量","(D) 嚴重臉部外傷"],"answer":3,"image":""},{"id":"md6-106-1-77","subject":"md6","topic":"眼科-角膜結膜眼瞼眼窩","meta":"106年第1次第77題","year":106,"session":1,"number":77,"question":"一位50歲女性因右眼紅、疼痛至急診室就診，下列敘述何者不恰當？","options":["(A) 若上眼瞼（eyelid）處發現小水皰，則須照會眼科醫師觀察角膜是否有病變","(B) 若鼻尖發現小水皰，則表示鼻睫神經（nasociliary nerve）受到侵犯","(C) 眼睛疼痛嚴重度是治療成效的指標，故不宜使用眼睛局部止痛劑","(D) 若懷疑皰疹病毒感染，可使用紅黴素（erythromycin）預防二次細菌性感染"],"answer":2,"image":""},{"id":"md6-106-1-78","subject":"md6","topic":"產科-一般產科","meta":"106年第1次第78題","year":106,"session":1,"number":78,"question":"下列何者不是妊娠劇吐症（hyperemesis gravidarum）的典型表現？","options":["(A) 腹痛","(B) 體重減輕","(C) 酮血症（ketonemia）","(D) 低血鉀"],"answer":0,"image":""},{"id":"md6-106-1-79","subject":"md6","topic":"醫學倫理與法規","meta":"106年第1次第79題","year":106,"session":1,"number":79,"question":"王醫師工作一向相當繁忙，因此將他的醫師職章交由專科護理師幫忙書寫病歷、開立例行性醫囑。依照現行法規以及衛生福利部的解釋函，下列敘述何者正確？","options":["(A) 這些醫療行為屬於醫療輔助行為，由專科護理師來進行並無不當","(B) 只要專科護理師在進行病歷書寫及開立醫囑後，確實蓋上負責醫師的職章，即符合相關法律規定","(C) 這些醫療行為雖能由專科護理師輔助醫師為之，但不能由專科護理師代為之","(D) 這些醫療行為屬於常態性的醫療慣行，並無不當"],"answer":2,"image":""},{"id":"md6-106-1-80","subject":"md6","topic":"醫學倫理與法規","meta":"106年第1次第80題","year":106,"session":1,"number":80,"question":"依據赫爾辛基宣言（Declaration of Helsinki），當使用可辨識之人體組織或資料進行研究時，須遵守的規定。下列何者錯誤？","options":["(A) 通常醫師必須取得同意後，方可收集、分析、儲存和再利用","(B) 在不可能或無法取得同意之情況，或取得同意後將造成研究無效時，可在免除同意書之情況下進行","(C) 在不可能或無法取得同意之情況，或取得同意後將造成研究無效時，此種研究需經研究倫理委員會審議和批准後，方可在免除同意書之情況下進行","(D) 醫師應避免受試者在壓力或脅迫下取得同意"],"answer":1,"image":""},{"id":"md6-106-2-1","subject":"md6","topic":"麻醉-呼吸道與監視","meta":"106年第2次第1題","year":106,"session":2,"number":1,"question":"置放中央靜脈導管（central venous cannulation）時，最不可能發生下列那些併發症？","options":["(A) 選用right internal jugular vein時，發生pneumothorax","(B) 選用left internal jugular vein時，發生chylothorax","(C) 選用left subclavian vein時，發生pneumothorax","(D) 選用antecubital vein時，發生brachial plexus損傷"],"answer":3,"image":""},{"id":"md6-106-2-2","subject":"md6","topic":"麻醉-呼吸道與監視","meta":"106年第2次第2題","year":106,"session":2,"number":2,"question":"全身麻醉期間使用氣管內管（endotracheal tube），應以壓力計測量其cuff pressure，並應保持下列何者合理壓力，以預防病人吸入胃液與附近組織缺血？","options":["(A) 18 cmH2O","(B) 28 cmH2O","(C) 38 cmH2O","(D) 48 cmH2O"],"answer":[0,1,2],"image":"","answer_note":"更正:第2題答Ａ、Ｂ、Ｃ給分"},{"id":"md6-106-2-3","subject":"md6","topic":"麻醉-麻醉藥理","meta":"106年第2次第3題","year":106,"session":2,"number":3,"question":"一位28歲產婦進行剖腹產，接受硬脊膜外麻醉。給予15 mL 2% lidocaine後，產婦覺得有點舌頭麻麻、頭暈現象。則下列何者正確：","options":["(A) 硬脊膜外麻醉藥物的區域麻醉範圍過高","(B) 局部麻醉藥物被血管吸收產生","(C) 靜脈注射血管升壓劑可改善此現象","(D) 左側斜躺可改善"],"answer":1,"image":""},{"id":"md6-106-2-4","subject":"md6","topic":"麻醉-麻醉藥理","meta":"106年第2次第4題","year":106,"session":2,"number":4,"question":"下列何種吸入性麻醉劑會增加腦部的代謝率？","options":["(A) halothane","(B) nitrous oxide","(C) desflurane","(D) sevoflurane"],"answer":1,"image":""},{"id":"md6-106-2-5","subject":"md6","topic":"麻醉-麻醉藥理","meta":"106年第2次第5題","year":106,"session":2,"number":5,"question":"下列有關sevoflurane的敘述，何者錯誤？","options":["(A) 遇到瓶子或麻醉機管路中的雜質會降解出HCl，也叫做路易士酸","(B) 需要特殊塑膠瓶來包裝","(C) 如果降解出酸性物質，則有可能灼傷病患的呼吸黏膜","(D) 通常製造的成品中會加一些水以防降解"],"answer":[0,1],"image":"","answer_note":"更正:第5題答Ａ、Ｂ給分"},{"id":"md6-106-2-6","subject":"md6","topic":"麻醉-特殊麻醉與疼痛","meta":"106年第2次第6題","year":106,"session":2,"number":6,"question":"55歲肝硬化患者，欲接受兒子捐肝進行移植手術，術前已知有大於3公升的腹水、腎功能不良及出血傾向，下列有關麻醉處置的敘述，何者錯誤？","options":["(A) 大量腹水可能增加吸入胃液風險，可以採取快速麻醉誘導（rapid sequence induction）","(B) 肌肉鬆弛劑選取cisatracurium或atracurium，比vecuronium恰當","(C) 吸入性麻醉劑（inhalational anesthetics）不適合用於這個病人","(D) 可以輸注新鮮冷凍血漿（fresh frozen plasma）、血小板或冷凍沉澱品（cryoprecipitate）等來改善凝血功能；並做凝血功能監測"],"answer":2,"image":""},{"id":"md6-106-2-7","subject":"md6","topic":"麻醉-特殊麻醉與疼痛","meta":"106年第2次第7題","year":106,"session":2,"number":7,"question":"一名三十七歲男性，遭車禍導致大量失血休克，送至開刀房進行止血，麻醉醫師處理病人時，除了麻醉深度之外，下列何者也必須一併考慮？①腸道系統很容易受到休克的影響，產生「no-reflow」現象，為多重器官系統衰竭（MOSF：multiple organ system failure）的重要一環 ②腎臟在休克初期仍能保持腎絲球過濾率（GFR：glomerular filtration rate），但血流會傾向分佈至表層皮質區域（superficial cortical area） ③肺部可能出現急性呼吸窘迫症候（ARDS：acute respiratory distress syndrome），主要源自於炎性反應而不是出血反應 ④給予足夠的麻醉深度，收縮壓維持70～100 mmHg為目標即可，進行輸液治療","options":["(A) ①③④","(B) ①②④","(C) ②③④","(D) ①②③"],"answer":[0,1,2,3],"image":"","answer_note":"送分:第7題一律給分 (原公告答案 A)"},{"id":"md6-106-2-8","subject":"md6","topic":"麻醉-特殊麻醉與疼痛","meta":"106年第2次第8題","year":106,"session":2,"number":8,"question":"控制疼痛的非藥物方法，不包括下列何者？","options":["(A) transcutaneous electrical nerve stimulation（TENS）","(B) acupuncture","(C) behavioral modification","(D) celiac plexus block"],"answer":3,"image":""},{"id":"md6-106-2-9","subject":"md6","topic":"眼科-視網膜葡萄膜","meta":"106年第2次第9題","year":106,"session":2,"number":9,"question":"滲出性視網膜剝離（exudative retinal detachment）最具診斷價值的特徵為何？","options":["(A) 視網膜表面凹陷（concave surface）","(B) 視網膜下液體移位（shifting fluid）","(C) 視網膜牽扯皺褶（traction fold）","(D) 視網膜剝離與未剝離之交界線（demarcation lines）"],"answer":1,"image":""},{"id":"md6-106-2-10","subject":"md6","topic":"眼科-角膜結膜眼瞼眼窩","meta":"106年第2次第10題","year":106,"session":2,"number":10,"question":"有關圓錐角膜（keratoconus）的敘述，下列何者錯誤？","options":["(A) 通常於青春期發病，而後緩慢進行","(B) 近視及散光會逐漸增加","(C) 角膜厚度逐漸變厚，導致角膜弧度變凸","(D) 唐氏症（Down Syndrome）可伴隨圓錐角膜"],"answer":2,"image":""},{"id":"md6-106-2-11","subject":"md6","topic":"眼科-水晶體青光眼","meta":"106年第2次第11題","year":106,"session":2,"number":11,"question":"水晶體異位(ectopic lentis）是下列那種疾病之表徵？","options":["(A) 馬凡氏症候群（Marfan syndrome）","(B) 早產兒視網膜病變（retinopathy of prematurity）","(C) 威爾遜氏症（Wilson’s disease）","(D) 第一型糖尿病（幼年型糖尿病）"],"answer":0,"image":""},{"id":"md6-106-2-12","subject":"md6","topic":"眼科-水晶體青光眼","meta":"106年第2次第12題","year":106,"session":2,"number":12,"question":"下列有關房水（aqueous humour）的敘述，何者錯誤？","options":["(A) 充滿眼前房及眼後房，體積大約為250 µL","(B) 形成速度大約為2.5 µL/min","(C) 滲透壓（osmotic pressure）稍低於血漿（plasma）的滲透壓","(D) 成分與血漿類似，但是抗壞血酸（ascorbate），丙酮酸鹽（pyruvate）及乳酸鹽（lactate）之濃度比血漿高"],"answer":2,"image":""},{"id":"md6-106-2-13","subject":"md6","topic":"眼科-屈光斜弱視","meta":"106年第2次第13題","year":106,"session":2,"number":13,"question":"使用下列何種儀器或檢查，較無法得知眼球的屈光狀態（refractive status）？","options":["(A) 直接眼底鏡（direct ophthalmoscope）","(B) 視網膜鏡（retinoscope）","(C) 眼球突出計（exophthalmometer）","(D) 電腦驗光儀（auto-refractor）"],"answer":2,"image":""},{"id":"md6-106-2-14","subject":"md6","topic":"眼科-屈光斜弱視","meta":"106年第2次第14題","year":106,"session":2,"number":14,"question":"史奈倫（Snellen）氏E字視力表20/20視標的字體大小，相對於六公尺遠的眼睛視角（visual angle）約為：","options":["(A) 一分角","(B) 五分角","(C) 二十分角","(D) 六十分角"],"answer":1,"image":""},{"id":"md6-106-2-15","subject":"md6","topic":"眼科-角膜結膜眼瞼眼窩","meta":"106年第2次第15題","year":106,"session":2,"number":15,"question":"下列有關淚液排泄系統（tear excretory system）之敘述，何者錯誤？","options":["(A) 淚液在眼睛表面的分布主要靠眼瞼的眨眼動作（blinking）","(B) 眼瞼閉合不良的病患，常伴隨淚溢（epiphora）症狀","(C) 鼻淚管的開口位於中鼻甲（middle nasal meatus）","(D) 先天性鼻淚管阻塞最常見的原因是Hasner氏瓣膜未開通"],"answer":2,"image":""},{"id":"md6-106-2-16","subject":"md6","topic":"眼科-角膜結膜眼瞼眼窩","meta":"106年第2次第16題","year":106,"session":2,"number":16,"question":"有關配戴隱形眼鏡不當，引起之缺氧性角膜炎（hypoxic keratitis）之敘述，下列何者錯誤？","options":["(A) 最常見者為表淺性點狀角膜炎（superficial punctate keratitis）","(B) 慢性缺氧會造成脂質（lipid）沈積","(C) 通常不會伴隨角膜破皮","(D) 通常伴隨虹彩炎"],"answer":3,"image":""},{"id":"md6-106-2-17","subject":"md6","topic":"耳科學","meta":"106年第2次第17題","year":106,"session":2,"number":17,"question":"在先天性聽力損失的症候群中，下列那一種會伴有心電圖上prolonged Q-T interval而可能造成幼兒猝死？","options":["(A) Jervell and Lange-Nielsen syndrome","(B) Pendred syndrome","(C) Usher syndrome","(D) Waardenburg syndrome"],"answer":0,"image":""},{"id":"md6-106-2-18","subject":"md6","topic":"耳科學","meta":"106年第2次第18題","year":106,"session":2,"number":18,"question":"下列眼振圖所代表的臨床意義，最可能的診斷是：","options":["(A) 右側美尼爾病（Ménière’s disease）","(B) 左側美尼爾病（Ménière’s disease）","(C) 右側小腦橋腦角腫瘤（cerebellopontine angle tumor）","(D) 左側小腦橋腦角腫瘤（cerebellopontine angle tumor）"],"answer":2,"image":"md6-106-2-18.jpeg"},{"id":"md6-106-2-19","subject":"md6","topic":"鼻科學","meta":"106年第2次第19題","year":106,"session":2,"number":19,"question":"黴菌感染之鼻竇炎引發併發症的病例中，下列何者為最典型之徵象？","options":["(A) 血管破裂","(B) 血管栓塞","(C) 骨髓侵犯","(D) 肌肉溶解"],"answer":1,"image":""},{"id":"md6-106-2-20","subject":"md6","topic":"鼻科學","meta":"106年第2次第20題","year":106,"session":2,"number":20,"question":"下列何者是新生兒剛出生時發育早且具有臨床上相當重要性之鼻竇？","options":["(A) 上頜竇","(B) 篩竇","(C) 蝶竇","(D) 額竇"],"answer":[0,1],"image":"","answer_note":"更正:第20題答Ａ、Ｂ給分"},{"id":"md6-106-2-21","subject":"md6","topic":"喉科學與頭頸腫瘤","meta":"106年第2次第21題","year":106,"session":2,"number":21,"question":"一位三歲小男生被帶至急診，家屬陳述早晨起床時抱怨喉嚨痛與全身倦怠，傍晚即出現聲音異常，頸部伸直、呼吸急促、流涎，診斷為急性會厭炎（epiglottitis），下列何者正確？","options":["(A) 立即以壓舌板檢查喉嚨是否有感染","(B) 胸部X光片可見氣管影像成尖塔狀（steeple sign）","(C) 可能須給予氣管內插管","(D) 可能為病毒感染，不需立即使用抗生素"],"answer":2,"image":""},{"id":"md6-106-2-22","subject":"md6","topic":"喉科學與頭頸腫瘤","meta":"106年第2次第22題","year":106,"session":2,"number":22,"question":"有關喉部血管性水腫（laryngeal angioedema）之敘述，下列何者錯誤？","options":["(A) 組織血管擴張，血管通透性增加組織水腫，可能致命","(B) 可由注射藥物，食物或昆蟲咬傷等所引起","(C) 治療須迅速使用腎上腺素（epinephrine）、氧氣、抗組織胺（antihistamine）及類固醇（steroid）","(D) 此疾病僅局限於喉部"],"answer":3,"image":""},{"id":"md6-106-2-23","subject":"md6","topic":"喉科學與頭頸腫瘤","meta":"106年第2次第23題","year":106,"session":2,"number":23,"question":"下咽癌病患接受根除性手術治療後，下列何者不是常使用之音聲復健方式？","options":["(A) 氣動式人造喉（pneumatic artificial larynges）","(B) 食道語（esophageal voice）","(C) 腹語（abdominal voice）","(D) 氣管食道語（tracheo-esophageal speech）"],"answer":2,"image":""},{"id":"md6-106-2-24","subject":"md6","topic":"喉科學與頭頸腫瘤","meta":"106年第2次第24題","year":106,"session":2,"number":24,"question":"有一位60歲男性病人發現僅右側鎖骨上窩有一個4公分之硬塊，下列何者是最有可能的原發病灶？","options":["(A) 鼻咽癌","(B) 口腔癌","(C) 攝護腺癌","(D) 鼻竇癌"],"answer":[0,1,2,3],"image":"","answer_note":"送分:第24題一律給分 (原公告答案 C)"},{"id":"md6-106-2-25","subject":"md6","topic":"產科-一般產科","meta":"106年第2次第25題","year":106,"session":2,"number":25,"question":"下列何者為最常造成胎兒子宮內肢體缺損（intrauterine amputation）的原因？","options":["(A) 羊膜帶症候群（amniotic band syndrome）","(B) 臍帶纏繞（cord entanglement）","(C) 產婦創傷病史（maternal trauma）","(D) 血管阻塞（vascular occlusion）"],"answer":0,"image":""},{"id":"md6-106-2-26","subject":"md6","topic":"產科-高危險妊娠","meta":"106年第2次第26題","year":106,"session":2,"number":26,"question":"心臟病的孕婦生產，下列何種麻醉方法最佳？","options":["(A) 局部麻醉","(B) 硬脊膜外麻醉","(C) 腰椎麻醉","(D) 全身麻醉"],"answer":1,"image":""},{"id":"md6-106-2-27","subject":"md6","topic":"產科-一般產科","meta":"106年第2次第27題","year":106,"session":2,"number":27,"question":"胎兒small for gestational age（SGA）之定義為何？","options":["(A) 體重小於10th percentile","(B) 體重小於20th percentile","(C) 體重小於30th percentile","(D) 體重小於40th percentile"],"answer":0,"image":""},{"id":"md6-106-2-28","subject":"md6","topic":"產科-一般產科","meta":"106年第2次第28題","year":106,"session":2,"number":28,"question":"以病理組織來分，葡萄胎可區分為完全性與部分性葡萄胎（complete/partial mole）兩大類。下列何者為部分性葡萄胎（partial mole）最可能的染色體型態（karyotype）？","options":["(A) 45, XO","(B) 46, XY","(C) 46, XX","(D) 69, XXY"],"answer":3,"image":""},{"id":"md6-106-2-29","subject":"md6","topic":"產科-一般產科","meta":"106年第2次第29題","year":106,"session":2,"number":29,"question":"下列何者為最常造成胎兒心跳呈現變異型減速（variable decelerations）的原因？","options":["(A) 胎兒缺氧","(B) 胎兒酸血症","(C) 臍帶受壓迫（cord compression）","(D) 胎頭受壓迫（head compression）"],"answer":2,"image":""},{"id":"md6-106-2-30","subject":"md6","topic":"產科-一般產科","meta":"106年第2次第30題","year":106,"session":2,"number":30,"question":"27歲女性，G2P1，妊娠40週，胎兒超音波臍動脈血流速度波形縮舒比（systolic-diastolic ratio, S/D ratio），下列何者為正常？","options":["(A) 2","(B) 6","(C) 8","(D) 10"],"answer":0,"image":""},{"id":"md6-106-2-31","subject":"md6","topic":"產科-高危險妊娠","meta":"106年第2次第31題","year":106,"session":2,"number":31,"question":"懷孕20週婦女，到婦產科門診接受產前檢查，胎兒二維（two-dimentional）超音波檢查發現胎兒腹部有腹壁缺損，初步判斷為omphalocele。下列處理何者錯誤？","options":["(A) 建議終止懷孕","(B) 建議使用胎兒三維（three-dimentional）超音波檢查確定診斷","(C) 建議使用MRI確定診斷","(D) 告知胎兒染色體異常機會較高，可接受羊膜腔穿刺檢查"],"answer":0,"image":""},{"id":"md6-106-2-32","subject":"md6","topic":"婦科-良性腫瘤與內膜異位","meta":"106年第2次第32題","year":106,"session":2,"number":32,"question":"痛經婦女的經血中，下列何者含量較多？","options":["(A) 前列腺素（prostaglandin）","(B) 黃體素（progesterone）","(C) 血管加壓素（vasopressin）","(D) 動情激素（estrogen）"],"answer":0,"image":""},{"id":"md6-106-2-33","subject":"md6","topic":"婦科-良性腫瘤與內膜異位","meta":"106年第2次第33題","year":106,"session":2,"number":33,"question":"24歲的婦女，在門診時被發現大陰唇有一小於1公分但突起的小腫瘤，經切片檢查後，最有可能的診斷為：","options":["(A) 原位癌（carcinoma in situ）","(B) 黑色素腫瘤（melanoma）","(C) 上皮內包性囊腫（epidermal inclusion cyst）","(D) 汗管腺瘤（hidradenoma）"],"answer":2,"image":""},{"id":"md6-106-2-34","subject":"md6","topic":"婦科-生殖內分泌","meta":"106年第2次第34題","year":106,"session":2,"number":34,"question":"下列那一種方法無法確定是否排卵？","options":["(A) 基礎體溫","(B) 血液黃體素","(C) 超音波","(D) 血液雌激素"],"answer":3,"image":""},{"id":"md6-106-2-35","subject":"md6","topic":"婦科-腫瘤","meta":"106年第2次第35題","year":106,"session":2,"number":35,"question":"58歲停經後出血的婦女，經子宮內膜切片診斷為子宮內膜癌，接受了全子宮切除、雙側卵巢輸卵管切除、骨盆腔及主動脈旁淋巴結摘除手術，病理報告發現癌細胞侵犯深層子宮肌肉層，淋巴結沒有癌細胞轉移，依據目前國際婦產科聯盟（international federation of gynecology and obstetrics, FIGO）這位患者的腫瘤分期應為：","options":["(A) Stage I","(B) Stage IIa","(C) Stage IIb","(D) Stage III"],"answer":0,"image":""},{"id":"md6-106-2-36","subject":"md6","topic":"婦科-腫瘤","meta":"106年第2次第36題","year":106,"session":2,"number":36,"question":"下列何者不是陰道癌（vaginal cancer）常見的特徵？","options":["(A) 常發生於陰道後壁","(B) 常見於陰道上部","(C) 常伴隨陰道疼痛","(D) 陰道上皮贅瘤（vaginal intraepithelial neoplasia）有進展成侵襲陰道癌（invasive vaginal cancer）的可能性"],"answer":2,"image":""},{"id":"md6-106-2-37","subject":"md6","topic":"婦科-腫瘤","meta":"106年第2次第37題","year":106,"session":2,"number":37,"question":"下列何者有助於減少卵巢癌的發生？","options":["(A) 口服避孕藥","(B) 素食","(C) 裝置子宮內避孕器","(D) 初經早（early menarche）"],"answer":0,"image":""},{"id":"md6-106-2-38","subject":"md6","topic":"婦科-生殖內分泌","meta":"106年第2次第38題","year":106,"session":2,"number":38,"question":"關於X染色體脆折症（fragile X syndrome）的敘述，下列何者錯誤？","options":["(A) 發病原因為FMR1（fragile-X mental retardation）基因發生突變，位於Xq27","(B) 造成突變的原因為基因出現三核甘酸CGG重複（trinucleotide repeat）次數有異常擴增的現象","(C) CGG重複（trinucleotide repeat）次數達44次即會出現智能障礙等臨床症狀","(D) 2010年美國婦產科醫學會對於有不明原因智能障礙、發育遲緩、自閉症者或有家族史者，以及卵巢早衰（premature ovarian insufficiency）者，建議產前進行母血篩檢"],"answer":2,"image":""},{"id":"md6-106-2-39","subject":"md6","topic":"產科-高危險妊娠","meta":"106年第2次第39題","year":106,"session":2,"number":39,"question":"33歲女性，G2P1，前胎因胎位不正接受剖腹產；此次懷孕，於妊娠35週時發現陰道大量出血，接受緊急剖腹產，於術中發現前置胎盤併植入性胎盤，接受子宮全切除術。相較於術前已確診並計畫接受剖腹產併子宮全切除之病患，此產婦手術中發生，下列何種併發症的機會較高？","options":["(A) 膀胱損傷（bladder injury）","(B) 腸損傷（bowel injury）","(C) 靜脈血管栓塞（venous thromboembolism）","(D) 羊水栓塞（amniotic fluid embolism）"],"answer":0,"image":""},{"id":"md6-106-2-40","subject":"md6","topic":"產科-一般產科","meta":"106年第2次第40題","year":106,"session":2,"number":40,"question":"有關母體子宮螺旋動脈（spiral artery），因受絨毛膜外滋養層細胞（extravillous trophoblast）侵犯改變，而成功建立子宮胎盤血循環系統，此循環系統第二波建立形成時期為妊娠：","options":["(A) 第6週","(B) 第7～11週","(C) 第12～16週","(D) 第17週後"],"answer":[2,3],"image":"","answer_note":"更正:第40題答Ｃ、Ｄ給分"},{"id":"md6-106-2-41","subject":"md6","topic":"產科-一般產科","meta":"106年第2次第41題","year":106,"session":2,"number":41,"question":"27歲初產婦，懷孕35週，至產房就診，主訴陰道出血與腹痛，血壓96/58 mmHg，無尿蛋白反應，腹部超音波無特殊發現，因胎心監視器（tococardiography）呈現延遲性胎心減速（late deceleration）現象，緊急施予剖腹生產，手術中發現，子宮表面呈藍色變化（Couvelaire uterus），同時合併子宮收縮不良及產後出血，是何種產科急症？","options":["(A) 胎盤剝離（placental abruption）","(B) 植入性胎盤（placenta accreta）","(C) 子宮破裂（uterine rupture）","(D) 不明原因凝血功能異常（idiopathic coagulation disorder）"],"answer":0,"image":""},{"id":"md6-106-2-42","subject":"md6","topic":"產科-高危險妊娠","meta":"106年第2次第42題","year":106,"session":2,"number":42,"question":"28歲G1P0孕婦，妊娠28週時，經診斷為子宮內胎兒生長遲滯（intrauterine fetel growth restriction, IUGR），爾後即於門診接受規律性產前檢查。目前妊娠38週，產前檢查安排之胎心率監測呈現良好反應（reactive），無規律性子宮收縮；超音波檢查羊水指數（amniotic fluid index）3.2 cm，預估胎兒體重1900公克，陰道內診子宮頸未開，破水測試（nitrazine test）呈現陰性反應。此時的最適當處置為：","options":["(A) 安排產前檢查門診追蹤觀察","(B) 進一步安排臍動脈都卜勒測量檢查（umbilical arterial Doppler velocimetry）","(C) 進一步安排催產素激發試驗（oxytocin challenge test）","(D) 安排住院引產"],"answer":3,"image":""},{"id":"md6-106-2-43","subject":"md6","topic":"婦科-手術學與診斷技術","meta":"106年第2次第43題","year":106,"session":2,"number":43,"question":"在腹腔鏡骨盆手術中常會使用子宮托（uterine manipulator）來調整子宮位置，子宮托由陰道置放於子宮腔內，由坐在患者屁股端的助手來操弄以調整子宮位置，讓手術能夠順利執行。如欲使下列腹腔鏡圖中Ａ之構造能夠明顯呈現，則助手應如何操控子宮托？","options":["(A) 移動子宮托讓子宮長軸方向朝向患者腹部及頭部之方向","(B) 移動子宮托讓子宮長軸方向朝向患者右側壁及背部之方向","(C) 移動子宮托讓子宮長軸方向朝向患者左側壁及背部之方向","(D) 將子宮托回拉（使子宮朝助手方向移動）並讓子宮長軸方向朝向患者背部之方向"],"answer":0,"image":"md6-106-2-43.jpeg"},{"id":"md6-106-2-44","subject":"md6","topic":"婦科-尿失禁與骨盆腔脫垂","meta":"106年第2次第44題","year":106,"session":2,"number":44,"question":"38歲女性，到婦產門診就診，主訴有下列典型症狀dysuria、dribbling、dyspareunia，同時臨床骨盆檢查發現前陰道壁有一腫塊，下列何者被公認為最佳診斷之影像工具？","options":["(A) 靜脈腎盂攝影（intravenous pyelography）","(B) 解尿膀胱尿道攝影（voiding cystourethrography）","(C) 腎臟輸尿管膀胱攝影（kidney, ureter, bladder, KUB）","(D) 核磁共振（magnetic resonance imaging）"],"answer":3,"image":""},{"id":"md6-106-2-45","subject":"md6","topic":"婦科-良性腫瘤與內膜異位","meta":"106年第2次第45題","year":106,"session":2,"number":45,"question":"21歲女性，月經來之後兩週，突然下腹疼痛，下列何者為最有可能的原因？","options":["(A) 子宮內膜異位","(B) 子宮外孕","(C) 盲腸炎","(D) 排卵"],"answer":3,"image":""},{"id":"md6-106-2-46","subject":"md6","topic":"婦科-腫瘤","meta":"106年第2次第46題","year":106,"session":2,"number":46,"question":"關於外陰扁平上皮癌（squamous cell carcinoma of the vulva）T1a的深度侵犯，有一個最重要的臨界點，只要侵犯深度不超過這個臨界值，幾乎不會有腹股溝淋巴的轉移，臨界值深度為何？","options":["(A) 1 mm（1毫米）","(B) 2 mm（2毫米）","(C) 3 mm（3毫米）","(D) 5 mm（5毫米）"],"answer":0,"image":""},{"id":"md6-106-2-47","subject":"md6","topic":"婦科-腫瘤","meta":"106年第2次第47題","year":106,"session":2,"number":47,"question":"已經生育過的54歲婦女，因為停經後出血，如果臨床懷疑有子宮內膜病變的可能，下列何處置最能正確診斷病灶？","options":["(A) 陰道及子宮頸抹片（Pap smear）","(B) 經陰道超音波（transvaginal ultrasound）","(C) 門診子宮內膜吸取取樣（office endometrial aspiration biopsy）","(D) 子宮頸擴張及刮搔術或子宮鏡（dilation and curettage or hysteroscopy）"],"answer":3,"image":""},{"id":"md6-106-2-48","subject":"md6","topic":"婦科-腫瘤","meta":"106年第2次第48題","year":106,"session":2,"number":48,"question":"關於妊娠滋養細胞腫瘤（gestational trophoblastic disease）的敘述，下列何者最不適當？","options":["(A) 一般分為良性的葡萄胎及侵襲性葡萄胎（hydatidiform mole and invasive mole）和惡性的胎盤處滋養細胞腫瘤及絨毛腺癌（placental-site trophoblastic tumor and choriocarcinoma）","(B) 葡萄胎（complete hydatidiform mole）最常見的染色體型態（karyotype）是46,XX、但是也可見到少數的46,XY karyotype","(C) 部分葡萄胎（partial hydatidiform mole）的典型特徵，包括明顯的間質滋養細胞包含體（stromal trophoblastic inclusions），明顯的絨毛扇形樣（villous scalloping），以及可以見到胎兒組織","(D) 對於第一期胎盤處滋養細胞腫瘤（stage I placental-site trophoblastic tumor）的治療，應該做全子宮切除，才是適當的處理方式"],"answer":0,"image":""},{"id":"md6-106-2-49","subject":"md6","topic":"婦科-生殖內分泌","meta":"106年第2次第49題","year":106,"session":2,"number":49,"question":"關於腦下垂體泌乳激素腺瘤（pituitary prolactin adenoma）在懷孕期間的追蹤之敘述，下列何者錯誤？","options":["(A) 腺瘤在懷孕期間，可以檢查血中泌乳激素值來追蹤","(B) 可利用視野檢查來評估","(C) 可利用MRI影像檢查來評估","(D) 在懷孕期間若有頭痛與視覺障礙等症狀，須進一步小心評估"],"answer":[0,1,2,3],"image":"","answer_note":"送分:第49題一律給分 (原公告答案 A)"},{"id":"md6-106-2-50","subject":"md6","topic":"婦科-生殖內分泌","meta":"106年第2次第50題","year":106,"session":2,"number":50,"question":"關於人類絨毛膜性腺刺激素（human chorionic gonadotropin, hCG）之敘述，下列何者錯誤？","options":["(A) 作用於黃體細胞的LH受體上","(B) 由已經著床之胚胎的滋養層細胞（trophoblasts）所製造與分泌","(C) 在體內代謝的半衰期比LH短","(D) 黃體救援（luteal rescue）最主要的激素"],"answer":2,"image":""},{"id":"md6-106-2-51","subject":"md6","topic":"婦科-生殖內分泌","meta":"106年第2次第51題","year":106,"session":2,"number":51,"question":"有關評估子宮異常造成習慣性流產的敘述，下列何者正確？","options":["(A) 中膈子宮（septate uterus）為最常見與習慣性流產有關的先天性穆勒氏管異常","(B) 穆勒氏管異常常伴隨泌尿道異常，特別是婦女有中膈子宮異常時","(C) 漿膜下（subserous）子宮肌瘤，常與習慣性流產有關","(D) Kallmann's syndrome造成的子宮內病變，與習慣性流產有關"],"answer":0,"image":""},{"id":"md6-106-2-52","subject":"md6","topic":"婦科-生殖內分泌","meta":"106年第2次第52題","year":106,"session":2,"number":52,"question":"35歲習慣性流產女性G3P0SA3，因為不孕症合併月經異常至門診求診，月經週期第3天賀爾蒙指數濾泡刺激激素（FSH）5.4 IU/L，黃體化激素（LH）3.0 IU/L，甲狀腺刺激激素（TSH）5.87 mIU/L以及泌乳激素（PRL）15 ng/mL，其他檢查包括抗甲狀腺抗體陽性以及甲狀腺素free T4正常。下列何者是首先建議的治療方法？","options":["(A) 人工授精（IUI）","(B) 試管嬰兒（IVF）合併植入前胚胎鑑定","(C) 甲狀腺素levothyroxine治療","(D) Bromocriptine減少泌乳激素合成"],"answer":2,"image":""},{"id":"md6-106-2-53","subject":"md6","topic":"婦科-生殖內分泌","meta":"106年第2次第53題","year":106,"session":2,"number":53,"question":"下列何者最不可能是卵巢過度刺激症候群（ovarian hyperstimulation syndrome）的危險因子？","options":["(A) 年輕病患","(B) BMI小於18.5","(C) Antral follicle count小於4","(D) 當次週期成功懷孕"],"answer":2,"image":""},{"id":"md6-106-2-54","subject":"md6","topic":"婦科-生殖內分泌","meta":"106年第2次第54題","year":106,"session":2,"number":54,"question":"若一位女性的生理月經週期是28天，著床窗期（implantation window）最有可能是在月經來潮後的第幾天？","options":["(A) 12～15天","(B) 16～19天","(C) 20～24天","(D) 25～27天"],"answer":2,"image":""},{"id":"md6-106-2-55","subject":"md6","topic":"復健-神經復健","meta":"106年第2次第55題","year":106,"session":2,"number":55,"question":"下列何者生理因素，最不會影響人類神經傳導（nerve conduction）的反應時間？","options":["(A) 身高","(B) 受檢時的姿勢","(C) 年齡","(D) 體溫"],"answer":1,"image":""},{"id":"md6-106-2-56","subject":"md6","topic":"復健-神經復健","meta":"106年第2次第56題","year":106,"session":2,"number":56,"question":"一位腦中風病人造成患側上下肢與顏面有異常感覺（dysesthesia）與疼痛現象，但運動功能正常，病變最有可能位於下列何處？","options":["(A) 小腦（cerebellum）","(B) 視丘（thalamus）","(C) 橋腦（pons）","(D) 延腦（medulla）"],"answer":1,"image":""},{"id":"md6-106-2-57","subject":"md6","topic":"復健-神經復健","meta":"106年第2次第57題","year":106,"session":2,"number":57,"question":"在診斷人類脊椎神經根病變（radiculopathy）的發生部位上，下列何種電學診斷方法最有臨床診斷價值？","options":["(A) 神經傳導（nerve conduction）檢查","(B) 肌電圖（electromyography）檢查","(C) F波檢查","(D) Hoffmann反射檢查"],"answer":1,"image":""},{"id":"md6-106-2-58","subject":"md6","topic":"復健-神經復健","meta":"106年第2次第58題","year":106,"session":2,"number":58,"question":"腦中風發病6個月後的病人，他的右側肢體目前可以稍微對抗地心引力移動，但是會有明顯肌肉緊張及協同（synergy）動作出現。依據Brunnstrom的運動功能分級屬於那一階段？","options":["(A) stage1","(B) stage2","(C) stage3","(D) stage5"],"answer":2,"image":""},{"id":"md6-106-2-59","subject":"md6","topic":"復健-神經復健","meta":"106年第2次第59題","year":106,"session":2,"number":59,"question":"如圖所示，捏擠龜頭會引起肛門括約肌收縮，這是何種反射？","options":["(A) 肛門（anal）反射","(B) 球海綿體肌（bulbocavernosus）反射","(C) 提睪肌（cremasteric）反射","(D) 會陰（pudendal）反射"],"answer":1,"image":"md6-106-2-59.jpeg"},{"id":"md6-106-2-60","subject":"md6","topic":"復健-心肺復健與運動處方","meta":"106年第2次第60題","year":106,"session":2,"number":60,"question":"有氧運動的訓練（aerobic exercise training）後，於次強度運動（submaximal exercise）時之生理變化，下列何者錯誤？","options":["(A) 心輸出量（cardiac output）增加","(B) 心跳率（heart rate）降低","(C) 動靜脈血氧差（arteriovenous O2 difference）上升","(D) 收縮壓（systolic blood pressure）下降"],"answer":0,"image":""},{"id":"md6-106-2-61","subject":"md6","topic":"復健-骨骼肌肉損傷與疾患","meta":"106年第2次第61題","year":106,"session":2,"number":61,"question":"下列何者是運動傷害造成的足踝扭傷（ankle sprain）最常見的韌帶受傷？","options":["(A) 後距腓骨（posterior talofibular）韌帶","(B) 前距腓骨（anterior talofibular）韌帶","(C) 側距腓骨（lateral talofibular）韌帶","(D) 三角（deltoid）韌帶"],"answer":1,"image":""},{"id":"md6-106-2-62","subject":"md6","topic":"復健-骨骼肌肉損傷與疾患","meta":"106年第2次第62題","year":106,"session":2,"number":62,"question":"一位病人發生右側脛骨（tibia）骨折以石膏固定期間，在復健醫療上下列何者處置最適當？","options":["(A) 右小腿肌肉等張運動（isotonic exercise）","(B) 限制右小腿肌肉活動","(C) 右小腿肌肉等長運動（isometric exercise）","(D) 儘量做踝關節全關節運動（full range exercise）"],"answer":2,"image":""},{"id":"md6-106-2-63","subject":"md6","topic":"復健-骨骼肌肉損傷與疾患","meta":"106年第2次第63題","year":106,"session":2,"number":63,"question":"下列那一種疾病最常發生遠端指間關節（distal interphalangeal joint）發炎或病變？","options":["(A) 血友病出血性關節病變（hemoarthropathy）","(B) 乾癬性關節炎（psoriatic arthritis）","(C) 類風濕性關節炎（rheumatoid arthritis）","(D) 風濕性關節炎（rheumatic arthritis）"],"answer":1,"image":""},{"id":"md6-106-2-64","subject":"md6","topic":"復健-心肺復健與運動處方","meta":"106年第2次第64題","year":106,"session":2,"number":64,"question":"有關心臟移植病人在運動時的心跳反應，下列何者錯誤？","options":["(A) 在運動開始後，心跳率不會馬上增加","(B) 其基礎心跳率較正常人為低","(C) 其最大心跳率較正常人為低","(D) 運動停止後，心跳率仍會繼續上升達一至二分鐘"],"answer":1,"image":""},{"id":"md6-106-2-65","subject":"md6","topic":"復健-心肺復健與運動處方","meta":"106年第2次第65題","year":106,"session":2,"number":65,"question":"下列何者不是心臟復健運動所造成生理上的變化？","options":["(A) 增加預估最大心跳率（estimated maximum heart rate）","(B) 增加最大耗氧量（VO2 max）","(C) 減少病人在運動時之最大心肌耗氧量（maximal myocardial oxygen capacity）","(D) 降低血管周邊阻力（peripheral resistance）"],"answer":0,"image":""},{"id":"md6-106-2-66","subject":"md6","topic":"復健-心肺復健與運動處方","meta":"106年第2次第66題","year":106,"session":2,"number":66,"question":"下列何者是心臟病患參加運動訓練的禁忌症？","options":["(A) 服用乙型阻斷劑之降血壓藥物","(B) 嚴重主動脈狹窄","(C) 第一級房室傳導障礙","(D) 曾接受心臟移植的病患"],"answer":1,"image":""},{"id":"md6-106-2-67","subject":"md6","topic":"復健-神經復健","meta":"106年第2次第67題","year":106,"session":2,"number":67,"question":"下列有關腦性麻痺的敘述，何者最為正確？","options":["(A) 腦性麻痺兒童一定會合併智能障礙","(B) 最常見的為低張力型（hypotonia）","(C) 大多數偏癱性腦性麻痺（hemiplegic type）的兒童無法走路","(D) 由高膽紅質血症所造成徐動型（athetoid type）的病患較易合併聽力障礙的問題"],"answer":3,"image":""},{"id":"md6-106-2-68","subject":"md6","topic":"復健-神經復健","meta":"106年第2次第68題","year":106,"session":2,"number":68,"question":"對大多數人而言，腦部左側中大腦動脈（middle cerebral artery）嚴重阻塞，最容易發生下列何種失語症？","options":["(A) 全失語症（global aphasia）","(B) 傳導型失語症（conduction aphasia）","(C) 渥尼克失語症（Wernicke’s aphasia）","(D) 布洛卡失語症（Broca’s aphasia）"],"answer":[0,2,3],"image":"","answer_note":"更正:第68題答Ａ、Ｃ、Ｄ給分"},{"id":"md6-106-2-69","subject":"md6","topic":"復健-神經復健","meta":"106年第2次第69題","year":106,"session":2,"number":69,"question":"有關重度失能病患復健上常見心理問題的敘述，下列何者錯誤？","options":["(A) 否認（denial）是復健常見心理問題，但非單一現象","(B) 憂鬱（depression）與焦慮（anxiety）都是復健常見心理問題","(C) 脊髓損傷病人的憂鬱問題比焦慮問題更為常見","(D) 中風病人的憂鬱問題比焦慮問題更為常見"],"answer":[0,1,2,3],"image":"","answer_note":"送分:第69題一律給分 (原公告答案 C)"},{"id":"md6-106-2-70","subject":"md6","topic":"復健-兒童與一般復健","meta":"106年第2次第70題","year":106,"session":2,"number":70,"question":"下列何種病人不適用小型鍵盤（smaller keyboards）？","options":["(A) 上肢關節活動受限者","(B) 上肢顫抖（tremor）者","(C) 以口含筆（mouth stick）鍵字者","(D) 以單手鍵字者"],"answer":1,"image":""},{"id":"md6-106-2-71","subject":"md6","topic":"復健-神經復健","meta":"106年第2次第71題","year":106,"session":2,"number":71,"question":"一般吞嚥困難的病人在嘗試餵食時，下列方法何者錯誤？","options":["(A) 要選在病人比較清醒的時刻","(B) 讓病人平躺","(C) 以小口餵食","(D) 請病人略微低頭進食"],"answer":1,"image":""},{"id":"md6-106-2-72","subject":"md6","topic":"婦科-腫瘤","meta":"106年第2次第72題","year":106,"session":2,"number":72,"question":"已停經的56歲女性病患，主訴不正常陰道出血，磁振造影檢查（T2WI）如下圖。其診斷為何？","options":["(A) 子宮肌瘤（uterine myoma）","(B) 子宮內膜癌（endometrial cancer）","(C) 子宮頸癌（cervical cancer）","(D) 子宮腔內積血（hematometra）"],"answer":1,"image":"md6-106-2-72.jpeg"},{"id":"md6-106-2-73","subject":"md6","topic":"復健-神經復健","meta":"106年第2次第73題","year":106,"session":2,"number":73,"question":"下列神經系統疾病的好發位置，何者錯誤？","options":["(A) Langerhans cell histiocytosis好發於suprasellar region and skull bones","(B) germ cell tumor好發於suprasellar and pineal regions","(C) mycotic aneurysm好發於branches of middle and posterior cerebral arteries","(D) dissecting aneurysm好發於anterior communicating artery and basilar tip"],"answer":3,"image":""},{"id":"md6-106-2-74","subject":"md6","topic":"婦科-良性腫瘤與內膜異位","meta":"106年第2次第74題","year":106,"session":2,"number":74,"question":"59歲女性，下腹部磁振造影檢查（T2WI）如圖，有關箭號所指之處，何者敘述最正確？","options":["(A) 子宮肌瘤","(B) 子宮腺肌病","(C) 子宮內膜息肉","(D) 子宮頸瘤"],"answer":3,"image":"md6-106-2-74.jpeg"},{"id":"md6-106-2-75","subject":"md6","topic":"婦科-生殖內分泌","meta":"106年第2次第75題","year":106,"session":2,"number":75,"question":"不孕症女性，子宮輸卵管攝影檢查呈現如圖，下列敘述何者最正確？","options":["(A) 子宮頸狹窄","(B) 兩側輸卵管暢通","(C) 先天性雙子宮","(D) 子宮內粘連"],"answer":1,"image":"md6-106-2-75.jpeg"},{"id":"md6-106-2-76","subject":"md6","topic":"復健-神經復健","meta":"106年第2次第76題","year":106,"session":2,"number":76,"question":"中風病人復健的目的為盡可能地恢復病人的自我獨立生活能力，下列敘述何者錯誤？","options":["(A) 在病情穩定的前提下，越早進行復健對長期預後越有幫助","(B) 在病情穩定的前提下，利用輔具讓病人能下床活動（mobility training），以避免褥瘡、深層靜脈栓塞等併發症","(C) 即使在臥床的情況之下，及早進行活動範圍訓練（range of motion training），可以避免肌肉痙攣、關節攣縮","(D) 約束治療（restraint therapy）意指約束中風患側肢體，訓練健側肢體儘快適應一般日常活動的進行"],"answer":3,"image":""},{"id":"md6-106-2-77","subject":"md6","topic":"喉科學與頭頸腫瘤","meta":"106年第2次第77題","year":106,"session":2,"number":77,"question":"一位45歲男性病人，無藥物過敏史。昨天開始發燒、喉嚨疼痛，自行服用止痛藥後完全沒有緩解。今日甚至出現吞嚥與呼吸困難的現象因而來急診求診，你觀察到此病人張著口呼吸有喘鳴音（stridor），嘴角有流口水，下列處置何者最不恰當？","options":["(A) 給予氧氣","(B) 靜脈輸液（fluid hydration）","(C) 讓病人平躺休息","(D) 給予抗生素（antibiotics）"],"answer":2,"image":""},{"id":"md6-106-2-78","subject":"md6","topic":"喉科學與頭頸腫瘤","meta":"106年第2次第78題","year":106,"session":2,"number":78,"question":"承上題，你給病人照了一張C-spine lateral view X-ray檢查，結果發現在會厭處有thumb-shaped的樣子，下列何者是此病人最可能之診斷？","options":["(A) 急性扁桃腺炎（acute tonsillitis）","(B) 咽後膿瘍（retropharyngeal abscess）","(C) 急性會厭炎（acute epiglottitis）","(D) 急性血管性水腫（acute angioedema）"],"answer":2,"image":""},{"id":"md6-106-2-79","subject":"md6","topic":"醫學倫理與法規","meta":"106年第2次第79題","year":106,"session":2,"number":79,"question":"依據優生保健法的規定，懷孕婦女經診斷或證明有下列情事之一者，得依其自願，施行人工流產。下列何者正確？①本人或其配偶患有礙優生之遺傳性、傳染性疾病或精神疾病者 ②有醫學上理由，足以認定懷孕或分娩有招致生命危險或危害身體或精神健康者 ③有醫學上理由，足以認定胎兒有畸型發育之虞者 ④因懷孕或生產將影響其心理健康或家庭生活者","options":["(A) 僅①②③","(B) 僅①③","(C) 僅②④","(D) ①②③④"],"answer":[0,3],"image":"","answer_note":"更正:第79題答Ａ、Ｄ給分。"},{"id":"md6-106-2-80","subject":"md6","topic":"醫學倫理與法規","meta":"106年第2次第80題","year":106,"session":2,"number":80,"question":"病人車禍瀕臨死亡，他已簽署器官捐贈同意書，其所捐贈的器官該分配給那位受贈者，是應依據下列何醫學倫理原則？","options":["(A) 行善原則（beneficence）","(B) 尊重自主原則（respect for autonomy）","(C) 不傷害原則（non-maleficence）","(D) 正義原則（justice）"],"answer":3,"image":""},{"id":"md6-107-1-1","subject":"md6","topic":"麻醉-呼吸道與監視","meta":"107年第1次第1題","year":107,"session":1,"number":1,"question":"手術前的「核心呼吸道評估（core of airway assessment）」中，最能預測潛在性困難呼吸道的三個理學檢查項目，不包括下列何者？","options":["(A) 嘴巴打開的程度（mouth opening）","(B) 頭圍大小（circumference of the head）","(C) 下顎前挺程度（jaw protrusion）","(D) 頭部伸展程度（head extension）"],"answer":1,"image":""},{"id":"md6-107-1-2","subject":"md6","topic":"麻醉-麻醉藥理","meta":"107年第1次第2題","year":107,"session":1,"number":2,"question":"如何避免手術後殘存的神經肌肉阻斷作用（neuromuscular blockade）？","options":["(A) 儘量使用長效型的肌肉鬆弛劑（muscle relaxants），以避免手術中重複追加肌肉鬆弛劑，導致劑量累積以及術後的神經肌肉阻斷殘存作用","(B) 手術麻醉期間儘量將所有四連刺激（train of four, TOF）所引發的肌肉抽動都阻斷（total twitch suppression），以達足夠的神經肌肉阻斷作用","(C) 術後要以擷抗劑（antagonists）進行阻斷作用的反轉（reversal），但是擷抗劑的投予，必須在四連刺激至少有兩個以上的肌肉抽動以後才可給藥","(D) 臨床人員必須謹記，唯有四連刺激監測的結果，沒有明顯的消退作用（fade），才能保證不會發生明顯的手術後神經肌肉阻斷殘存作用"],"answer":2,"image":""},{"id":"md6-107-1-3","subject":"md6","topic":"麻醉-呼吸道與監視","meta":"107年第1次第3題","year":107,"session":1,"number":3,"question":"下列何者有實證（evidence-based）說明，病人在加護病房（intensive care units）中使用中央靜脈導管時可預防發生感染？①在sterile barrier precautions環境中放置 ②使用chlorhexidine solution做皮膚消毒 ③使用antibiotic-impregnated中央靜脈導管 ④以超音波導引技術放置中央靜脈導管","options":["(A) ①②③","(B) ②③④","(C) ①③④","(D) ①②④"],"answer":0,"image":""},{"id":"md6-107-1-4","subject":"md6","topic":"麻醉-麻醉藥理","meta":"107年第1次第4題","year":107,"session":1,"number":4,"question":"下列有關局部麻醉藥物過敏反應的敘述，何者錯誤？","options":["(A) 局部麻醉藥物引起的過敏反應非常少見，主要是與immunoglobulin E及cellular immunity反應有關","(B) ester系列的局部麻醉藥物較易引起過敏","(C) amide系列的局部麻醉藥物較易引起過敏","(D) 若局部麻醉溶液中添加保存劑methyl-paraben與meta-bisulfite，會誘導過敏反應發生"],"answer":2,"image":""},{"id":"md6-107-1-5","subject":"md6","topic":"麻醉-麻醉藥理","meta":"107年第1次第5題","year":107,"session":1,"number":5,"question":"下列何種藥物可能有腎上腺功能的抑制作用，面對腎上腺功能障礙的病人，應特別小心使用？","options":["(A) thiopental","(B) etomidate","(C) dexmedetomidine","(D) ketamine"],"answer":1,"image":""},{"id":"md6-107-1-6","subject":"md6","topic":"麻醉-麻醉藥理","meta":"107年第1次第6題","year":107,"session":1,"number":6,"question":"下列何者不是吸入性麻醉劑引起肝功能損傷的危險因素？","options":["(A) 肥胖","(B) 年齡","(C) 身高","(D) 基因遺傳"],"answer":2,"image":""},{"id":"md6-107-1-7","subject":"md6","topic":"麻醉-特殊麻醉與疼痛","meta":"107年第1次第7題","year":107,"session":1,"number":7,"question":"心臟手術中，心肌常承受缺血-再灌流（ischemia-reperfusion）的傷害，導致心肌處於能量供應失常的狀況，則下列何者正確？① 臨床上常呈現低心輸出症候群（LCOS:low cardiac output syndrome），cardiac index小2於2.4L/min/m②可藉肺動脈導管測得的血紅素氧氣飽和度（SvO:mixed venous oxygen saturation），呈2現心輸出量和全身氧氣消耗量的平衡 ③麻醉醫師須以生理變化做基礎，多方調整心室前後負荷及心室收縮力 ④為降低全身氧氣消耗量，心臟手術術後照顧需要術後鎮靜及降低體溫","options":["(A) ①②③","(B) ①②④","(C) ①③④","(D) ②③④"],"answer":0,"image":""},{"id":"md6-107-1-8","subject":"md6","topic":"麻醉-特殊麻醉與疼痛","meta":"107年第1次第8題","year":107,"session":1,"number":8,"question":"55歲男性病患因肝癌而進行上腹部剖腹手術，下列有關此種急性手術疼痛的敘述，何者錯誤？","options":["(A) 急性手術疼痛本身不會引起胃腸道的壓力反應","(B) 上腹部剖腹手術是屬於中重度疼痛","(C) 急性手術疼痛會引起心肺功能異常","(D) 急性手術疼痛會引起白血球上升"],"answer":0,"image":""},{"id":"md6-107-1-9","subject":"md6","topic":"眼科-視網膜葡萄膜","meta":"107年第1次第9題","year":107,"session":1,"number":9,"question":"下列有關中心漿液性脈絡視網膜病變（central serous chorioretinopathy, CSCR）之敘述，何者錯誤？","options":["(A) 視網膜感覺層（sensory retina）之漿液性剝離（serous detachment）","(B) 症狀包括視物變大（macropsia）、視物顏色改變（dyschromatopsia）","(C) 有可能反覆發生","(D) 大多數病患會自行好轉"],"answer":1,"image":""},{"id":"md6-107-1-10","subject":"md6","topic":"眼科-角膜結膜眼瞼眼窩","meta":"107年第1次第10題","year":107,"session":1,"number":10,"question":"角膜化學性灼傷之病患，下列何者與視力預後較無關聯？","options":["(A) 化學藥品的酸鹼特性","(B) 眼角膜接觸化學藥品的時間","(C) 輪部缺血或壞死之程度與範圍","(D) 眼瞼紅腫的程度"],"answer":3,"image":""},{"id":"md6-107-1-11","subject":"md6","topic":"眼科-水晶體青光眼","meta":"107年第1次第11題","year":107,"session":1,"number":11,"question":"林先生主訴看東西影像會晃動，經檢查為雙側對稱性水晶體上顳側脫位（supero-temporal subluxation），會建議他作何種遺傳性疾病檢查？","options":["(A) 半乳糖血症（galactosemia）","(B) 威爾遜氏病（Wilson’s disease）","(C) 馬凡氏症候群（Marfan syndrome）","(D) 愛伯氏症候群（Alport syndrome）"],"answer":2,"image":""},{"id":"md6-107-1-12","subject":"md6","topic":"眼科-屈光斜弱視","meta":"107年第1次第12題","year":107,"session":1,"number":12,"question":"下列那種病人比較不會有弱視（amblyopia）？","options":["(A) 右眼內斜視（esotropia）","(B) 遠視性兩眼不等視（anisometropia）","(C) 單眼先天性白內障（congenital cataract）","(D) 間歇性外斜視（intermittent exotropia）"],"answer":3,"image":""},{"id":"md6-107-1-13","subject":"md6","topic":"眼科-屈光斜弱視","meta":"107年第1次第13題","year":107,"session":1,"number":13,"question":"上斜肌（superior oblique muscle）本身的作用，並不會使眼球做下列何種運動（或稱轉動）？","options":["(A) 看下（depression）","(B) 內旋（intorsion）","(C) 內轉（adduction）","(D) 外轉（abduction）"],"answer":2,"image":""},{"id":"md6-107-1-14","subject":"md6","topic":"眼科-屈光斜弱視","meta":"107年第1次第14題","year":107,"session":1,"number":14,"question":"散光鏡片度數的記載＋2.0D sphere with cylinder -3.0D axis 90°與下列何者是相當的？","options":["(A) -2.0D sphere with cylinder＋3.0D axis 180°","(B) -2.0D sphere with cylinder -3.0D axis 90°","(C) -1.0D sphere with cylinder＋3.0D axis 180°","(D) -1.0D sphere with cylinder＋3.0D axis 90°"],"answer":2,"image":""},{"id":"md6-107-1-15","subject":"md6","topic":"眼科-角膜結膜眼瞼眼窩","meta":"107年第1次第15題","year":107,"session":1,"number":15,"question":"關於乾眼症的敘述，下列何者正確？","options":["(A) 淚膜裂解時間（tear film break-up time）主要是測淚水的穩定度，高於10秒屬異常","(B) 淚水層缺少之乾眼症病患，若有角膜點狀上皮糜爛（punctate epithelial erosion），容易出現在位於瞼間裂（interpalpebral fissure）部位的角膜","(C) 乾眼症會造成眼睛不舒適感，但並不會對視覺品質造成影響","(D) 當乾眼症伴隨嚴重發炎時，最好使用淚點栓塞（punctum plug）減少淚水的流失，不可使用類固醇藥水"],"answer":1,"image":""},{"id":"md6-107-1-16","subject":"md6","topic":"眼科-角膜結膜眼瞼眼窩","meta":"107年第1次第16題","year":107,"session":1,"number":16,"question":"眼皮下垂（blepharoptosis）較不常見於下列何種疾病？","options":["(A) 甲狀腺眼病變（thyroid eye disease）","(B) 霍納氏症候群（Horner’s syndrome）","(C) 重症肌無力（myasthenia gravis）","(D) 第三對腦神經麻痺"],"answer":0,"image":""},{"id":"md6-107-1-17","subject":"md6","topic":"耳科學","meta":"107年第1次第17題","year":107,"session":1,"number":17,"question":"40歲的女性病患主訴反覆眩暈發作數年，病史中得知每次發作都有懼光（photophobia）或懼音（phonophobia），且常常發作都與月經期有關。當食用乳製品（dairy products如起司等）過量時也會眩暈發作，由此病史，她最有可能的診斷為何？","options":["(A) 前庭性偏頭痛（vestibular migraine）","(B) 前庭神經炎（vestibular neuritis）","(C) 美尼爾氏症（Ménière’s disease）","(D) 良性陣發性姿勢型眩暈（BPPV）"],"answer":0,"image":""},{"id":"md6-107-1-18","subject":"md6","topic":"耳科學","meta":"107年第1次第18題","year":107,"session":1,"number":18,"question":"50歲男性主訴左耳反覆耳漏及聽力損失超過10年，局部檢查後，安排高解析度電腦斷層攝影，結果如下：在上鼓室有一軟組織包圍聽小骨（如下圖），最有可能之診斷為何？","options":["(A) 積液性中耳炎","(B) 乳突炎","(C) 聽神經瘤","(D) 膽脂瘤"],"answer":3,"image":"md6-107-1-18.jpeg"},{"id":"md6-107-1-19","subject":"md6","topic":"耳科學","meta":"107年第1次第19題","year":107,"session":1,"number":19,"question":"有關聽神經瘤（acoustic neuroma）的臨床敘述，下列何者錯誤？","options":["(A) 比較正確的名稱應為前庭神經鞘瘤、許旺氏細胞瘤（vestibular schwannoma）","(B) 最常見的臨床症狀是單側或非對稱型的感音型聽損","(C) 顏面神經麻痺是常見的臨床症狀","(D) 純音及語音聽力檢查（pure tone and speech audiometry）為臨床上的篩檢工具"],"answer":2,"image":""},{"id":"md6-107-1-20","subject":"md6","topic":"鼻科學","meta":"107年第1次第20題","year":107,"session":1,"number":20,"question":"一位25歲愛滋病患，一週前上呼吸道感染，併有膿性鼻涕、鼻塞等鼻竇炎症狀，以及發燒（38℃）、喉嚨痛，2天前突然畏寒、高燒（39℃）、頭劇痛、眼後痛；理學檢查發現第3、4、6對腦神經麻痺，最可能診斷為何？","options":["(A) 眼球膿瘍","(B) 腦膿瘍","(C) 眼球蜂窩組織炎","(D) 海綿竇栓塞"],"answer":3,"image":""},{"id":"md6-107-1-21","subject":"md6","topic":"鼻科學","meta":"107年第1次第21題","year":107,"session":1,"number":21,"question":"下列何種X光片攝影，上頜竇可能部分會被顳骨岩脊（petrous ridge）遮住而判讀不易？","options":["(A) Waters view","(B) Caldwell view","(C) skull lateral view","(D) submental view"],"answer":1,"image":""},{"id":"md6-107-1-22","subject":"md6","topic":"喉科學與頭頸腫瘤","meta":"107年第1次第22題","year":107,"session":1,"number":22,"question":"一位兩歲男孩被帶至門診，媽媽陳述小男孩四天前與其它小朋友嬉戲時，突然有短暫發紺情形但隨即又恢復，這四天來常有陣發性咳嗽及喘鳴，但並無其他鼻塞、流鼻涕等感冒症狀，肺部X光檢查結果正常，下列那一處置是必須優先考慮的？","options":["(A) 不需治療，觀察即可","(B) 點滴輸液","(C) 支氣管鏡檢查","(D) 給予抗生素"],"answer":2,"image":""},{"id":"md6-107-1-23","subject":"md6","topic":"喉科學與頭頸腫瘤","meta":"107年第1次第23題","year":107,"session":1,"number":23,"question":"下列何者為喉癌（laryngeal cancer）最常見之症狀？","options":["(A) 吞嚥疼痛（odynophagia）","(B) 聲音沙啞（hoarseness）","(C) 喘鳴（stridor）","(D) 呼吸困難（dyspnea）"],"answer":1,"image":""},{"id":"md6-107-1-24","subject":"md6","topic":"婦科-手術學與診斷技術","meta":"107年第1次第24題","year":107,"session":1,"number":24,"question":"當上頸部發現有三公分以上之硬塊時，下列處置何者優先考慮？","options":["(A) 針吸檢查","(B) 頸部切片檢查","(C) 開刀切除","(D) 檢查鼻咽腔、鼻腔、口腔與喉部"],"answer":3,"image":""},{"id":"md6-107-1-25","subject":"md6","topic":"產科-一般產科","meta":"107年第1次第25題","year":107,"session":1,"number":25,"question":"下列何者不是Bishop score的評分項目之一？","options":["(A) 生產次數（parity）","(B) 子宮頸擴張程度（dilatation）","(C) 子宮頸軟化程度（effacement）","(D) 胎頭於骨盆的位置（station）"],"answer":0,"image":""},{"id":"md6-107-1-26","subject":"md6","topic":"產科-一般產科","meta":"107年第1次第26題","year":107,"session":1,"number":26,"question":"28歲孕婦，G2P1，妊娠16週，接受超音波檢查如圖所示，下列何者為最可能的診斷？","options":["(A) anencephaly","(B) holoprosencephaly","(C) choroid plexus cyst","(D) Dandy-Walker malformation"],"answer":1,"image":"md6-107-1-26.jpeg"},{"id":"md6-107-1-27","subject":"md6","topic":"產科-一般產科","meta":"107年第1次第27題","year":107,"session":1,"number":27,"question":"關於產後發燒的敘述，下列何者錯誤？","options":["(A) 產褥熱定義為產後期測得體溫在38℃以上","(B) 乳腺炎大部分是兩側同時感染","(C) 產後持續性發燒最常見的原因是生殖道感染","(D) 乳腺炎最常見的細菌是Staphylococcus aureus"],"answer":1,"image":""},{"id":"md6-107-1-28","subject":"md6","topic":"產科-高危險妊娠","meta":"107年第1次第28題","year":107,"session":1,"number":28,"question":"下列何者為最常見造成異卵雙胞（dizygotic twins）的原因？","options":["(A) 高齡產婦（advanced maternal age）","(B) 人工生殖技術（assisted reproductive technology）","(C) 多產次的婦女（high parity）","(D) 種族（racial predisposition）"],"answer":1,"image":""},{"id":"md6-107-1-29","subject":"md6","topic":"婦科-尿失禁與骨盆腔脫垂","meta":"107年第1次第29題","year":107,"session":1,"number":29,"question":"凱格爾運動（Kegel exercises）最主要的目的是：","options":["(A) 加強生產後腹部肌肉的力量","(B) 增強膀胱及近端尿道的肌肉力量","(C) 預防生產後骨盆肌肉的神經受傷","(D) 降低老化產生之肌肉萎縮現象"],"answer":1,"image":""},{"id":"md6-107-1-30","subject":"md6","topic":"婦科-良性腫瘤與內膜異位","meta":"107年第1次第30題","year":107,"session":1,"number":30,"question":"20歲女性，在月經來前一個禮拜，因於性行為中突然發生劇烈下腹痛，至急診室求診。懷孕測試為陰性，觸診下腹有廣泛性壓痛點，陰道超音波發現右側卵巢有一6公分回音不均勻腫塊且有腹腔積液約180 mL，血壓脈搏穩定，實驗室檢查血紅素為10.5 g/dL，CA-125為38 U/mL；下列診斷何者較為適當？","options":["(A) 子宮外孕破裂","(B) 輸卵管卵巢膿瘍","(C) 卵巢黃體囊腫出血","(D) 卵巢畸胎瘤"],"answer":2,"image":""},{"id":"md6-107-1-31","subject":"md6","topic":"婦科-腫瘤","meta":"107年第1次第31題","year":107,"session":1,"number":31,"question":"下列何者為最常見的子宮頸癌的人類乳突病毒型？","options":["(A) 16、18","(B) 6、11","(C) 45、56","(D) 31、33"],"answer":0,"image":""},{"id":"md6-107-1-32","subject":"md6","topic":"婦科-腫瘤","meta":"107年第1次第32題","year":107,"session":1,"number":32,"question":"16歲年輕女性，因下腹疼痛及腹圍增加至門診求診，月經週期約28天，最近兩個月有異常出血，超音波顯示左側卵巢複雜性腫瘤，抽血檢查發現beta-hCG，CA-125及LDH都在正常值，但AFP值為1,236 ng/mL。下列敘述何者正確？","options":["(A) 患者最可能是上皮性卵巢癌，須子宮及雙側卵巢輸卵管全切除","(B) 患者最可能是卵巢內胚層竇瘤（endodermal sinus tumors），對化學治療很敏感","(C) 此腫瘤對放射線治療很敏感，術後往往要加做放射線合併化學治療","(D) 在年輕女性惡性卵巢腫瘤中很少見"],"answer":1,"image":""},{"id":"md6-107-1-33","subject":"md6","topic":"婦科-腫瘤","meta":"107年第1次第33題","year":107,"session":1,"number":33,"question":"下列何者不屬於卵巢癌的危險因子？","options":["(A) 從未生育","(B) 長期使用避孕藥物","(C) 一等親有卵巢癌病史","(D) 本身有乳癌病史"],"answer":1,"image":""},{"id":"md6-107-1-34","subject":"md6","topic":"產科-高危險妊娠","meta":"107年第1次第34題","year":107,"session":1,"number":34,"question":"關於妊娠糖尿病（gestational diabetes）的敘述，下列何者錯誤？","options":["(A) 除了胰島素（insulin）之外，口服降血糖藥物metformin及glyburide在懷孕中也可以使用","(B) 妊娠糖尿病對母親的影響包括較容易高血壓及較高的剖腹產率","(C) 妊娠糖尿病對胎兒的影響包括較容易發生巨嬰及新生兒高血糖","(D) 針對妊娠糖尿病高危險族群（例如肥胖，家族糖尿病史等），應於第一次產檢就進行妊娠糖尿病的篩檢"],"answer":2,"image":""},{"id":"md6-107-1-35","subject":"md6","topic":"產科-一般產科","meta":"107年第1次第35題","year":107,"session":1,"number":35,"question":"有關剖腹產孕婦之預防性抗生素之給予，若孕婦對penicillin或cephalosporin嚴重過敏，下列何者為最適合之預防性抗生素？","options":["(A) clindamycin","(B) levofloxacin","(C) clindamycin加上gentamicin","(D) clindamycin加上metronidazole"],"answer":2,"image":""},{"id":"md6-107-1-36","subject":"md6","topic":"產科-高危險妊娠","meta":"107年第1次第36題","year":107,"session":1,"number":36,"question":"28歲G3P1孕婦，第一胎曾經被診斷為妊娠糖尿病（gestational diabetes mellitus, GDM），胎兒出生體重為4,280公克；求診時為妊娠12週，體重50 kg，身高163 cm。此次懷孕對於妊娠血糖評估的最適當處置為：","options":["(A) 等同於妊娠糖尿病，立即採取治療方案","(B) 立即安排妊娠糖尿病篩檢","(C) 安排於妊娠24～28週常規妊娠糖尿病篩檢","(D) 立即安排胎兒的健康評估"],"answer":1,"image":""},{"id":"md6-107-1-37","subject":"md6","topic":"產科-高危險妊娠","meta":"107年第1次第37題","year":107,"session":1,"number":37,"question":"妊娠期肝內膽汁淤積症（intrahepatic cholestasis of pregnancy, ICP）導致胎兒不良結局，最主要因素為：","options":["(A) 孕婦血清膽酸（bile acids）","(B) 孕婦血清直接膽紅素（direct bilirubin）","(C) 孕婦血清膽固醇（cholesterol）","(D) 孕婦血清穀草轉氨酶（AST）"],"answer":0,"image":""},{"id":"md6-107-1-38","subject":"md6","topic":"婦科-尿失禁與骨盆腔脫垂","meta":"107年第1次第38題","year":107,"session":1,"number":38,"question":"對於夜尿量（nocturnal urinary volume）及夜間多尿症（nocturnal polyuria）的定義，下列何者正確？ ① 計算夜尿量應該包含睡前最後一次排尿量（the last void before going to bed） ②計算夜尿量應該包含早上起床第一次排尿量（the first void after rising in the morning） ③在65歲以上之婦女如果夜尿量大於24小時尿量的33%，則可定義為夜間多尿症 ④在65歲以上之婦女如果夜尿量大於24小時尿量的22%，則可定義為夜間多尿症","options":["(A) 僅①③","(B) 僅②③","(C) ①②③","(D) ①②④"],"answer":1,"image":""},{"id":"md6-107-1-39","subject":"md6","topic":"婦科-尿失禁與骨盆腔脫垂","meta":"107年第1次第39題","year":107,"session":1,"number":39,"question":"下列那項因子目前不被認為是壓力性尿失禁（stress urinary incontinence）的女性患者，在接受恥骨後尿道固定術（retropubic urethropexy）會是手術失敗的危險因子？","options":["(A) 低Valsalva leak-point pressure","(B) 低maximal urethral closure pressure","(C) 膀胱鏡（cystoscopy）或螢光透視（fluoroscopy）檢查下發現有張開的膀胱頸（open bladder neck）","(D) 高移動尿道（urethral hypermobility）"],"answer":3,"image":""},{"id":"md6-107-1-40","subject":"md6","topic":"婦科-手術學與診斷技術","meta":"107年第1次第40題","year":107,"session":1,"number":40,"question":"子宮鏡手術可能產生的併發症的敘述，下列何者錯誤？","options":["(A) 術前須建立測血液中的電解質當作基準","(B) 最好每5分鐘計算灌入液與流出液的差別","(C) 灌入與流出差異未達兩公升以上，無須給與利尿劑","(D) 灌注壓力70～80 mmHg是適合的"],"answer":2,"image":""},{"id":"md6-107-1-41","subject":"md6","topic":"婦科-生殖道感染與先天異常","meta":"107年第1次第41題","year":107,"session":1,"number":41,"question":"40歲女性，主訴陰道有量多惡臭的膿狀分泌物，檢查時發現陰道充血，子宮頸呈現如圖所示，下列敘述何者錯誤？","options":["(A) 最可能是披衣菌感染","(B) 陰道pH值通常大於5","(C) 常伴隨陰部搔癢","(D) Whiff test可能成陽性"],"answer":0,"image":"md6-107-1-41.jpeg"},{"id":"md6-107-1-42","subject":"md6","topic":"婦科-腫瘤","meta":"107年第1次第42題","year":107,"session":1,"number":42,"question":"38歲婦女，經診斷為子宮頸鱗狀上皮癌，接受根除性子宮切除術及骨盆腔淋巴結廓清術（radical hysterectomy and bilateral pelvic lymph node dissection），根據Berek & Novak's Gynecology 15版2012年出版教科書的危險因子說明，下列何者非屬復發有關的高風險的因子？","options":["(A) 靠近邊緣，或切端邊緣有腫瘤（positive or close margins）","(B) 大腫瘤（large tumor size）","(C) 淋巴結有轉移（positive lymph nodes）","(D) 顯微鏡檢下有子宮旁結締組織侵犯（microscopic parametrial involvement）"],"answer":1,"image":""},{"id":"md6-107-1-43","subject":"md6","topic":"婦科-腫瘤","meta":"107年第1次第43題","year":107,"session":1,"number":43,"question":"有關卵巢生殖細胞索或間質細胞瘤（ovarian sex cord-stromal tumors）的病理或臨床特徵，下列何者錯誤？","options":["(A) Call-Exner bodies是卵巢支持間質細胞瘤（Sertoli-Leydig cell tumor）的特徵","(B) 咖啡豆溝痕的核仁（coffee-bean grooved nuclei）是卵巢顆粒細胞瘤（granulosa cell tumor）的特徵","(C) 成人型卵巢顆粒細胞瘤（adult-type granulosa cell tumor）可能伴隨有子宮內膜增生或子宮內膜癌的發生","(D) 與男性化有關的腫瘤是卵巢支持間質細胞瘤（Sertoli-Leydig cell tumor）"],"answer":0,"image":""},{"id":"md6-107-1-44","subject":"md6","topic":"婦科-良性腫瘤與內膜異位","meta":"107年第1次第44題","year":107,"session":1,"number":44,"question":"關於子宮腺肌症（adenomyosis）之敘述，下列何者錯誤？","options":["(A) 子宮內膜腺體組織直接侵入子宮的肌層","(B) 子宮腺肌症的症狀主要是痛經與月經過多","(C) 使用促排卵藥治療時，子宮腺肌症會萎縮變小","(D) 以aromatase inhibitors治療可以使之縮小"],"answer":2,"image":""},{"id":"md6-107-1-45","subject":"md6","topic":"復健-骨骼肌肉損傷與疾患","meta":"107年第1次第45題","year":107,"session":1,"number":45,"question":"關於骨質密度之敘述，下列何者錯誤？","options":["(A) 約於35～40歲時達到最強最硬，之後逐漸流失","(B) 停經後2～3年，流失最快最多","(C) 70歲以上，骨質流失速率女性比男性快","(D) 抗地心引力之運動，可以增加骨質密度"],"answer":[0,2],"image":"","answer_note":"更正:第45題答Ａ、Ｃ給分。"},{"id":"md6-107-1-46","subject":"md6","topic":"婦科-生殖內分泌","meta":"107年第1次第46題","year":107,"session":1,"number":46,"question":"關於泌乳激素（prolactin）血中濃度與臨床症狀關係之敘述，下列何者錯誤？","options":["(A) 血中濃度為2～30 ng/mL時，若無其他機能異常者會正常排卵","(B) 隨著血中濃度逐漸升高，可能造成不排卵、無月經及黃體機能不足","(C) 泌乳激素（prolactin）的血中濃度會有晝夜節律變化，在晚上10時至凌晨2時達到最低點","(D) 血中濃度為100 ng/mL以上時，臨床上會出現無月經"],"answer":2,"image":""},{"id":"md6-107-1-47","subject":"md6","topic":"婦科-生殖內分泌","meta":"107年第1次第47題","year":107,"session":1,"number":47,"question":"施行人工輔助生殖技術（ART）時，發生黃體功能不足（Luteal phase defect）的原因不包含：","options":["(A) 排卵期間無法產生足夠的促性腺激素和黃體素","(B) 取卵手術時，破壞卵巢顆粒細胞","(C) 使用陰道黃體素治療取代肌肉注射","(D) 使用的藥物抑制內生性黃體生成激素（LH）的生成"],"answer":2,"image":""},{"id":"md6-107-1-48","subject":"md6","topic":"婦科-生殖道感染與先天異常","meta":"107年第1次第48題","year":107,"session":1,"number":48,"question":"28歲G3P0的女性，因長期為經痛、經血過多（heavy menstrual bleeding）和性交疼痛所困擾，自述前三次懷孕都在12週內就自然流產，子宮輸卵管攝影（hysterosalpingography）影像如圖所示。建議接受子宮鏡（hysteroscope）中膈切除手術，下列何者是手術後最可能改善的情況？","options":["(A) 經痛","(B) 經血過多","(C) 習慣性流產","(D) 性交疼痛"],"answer":2,"image":"md6-107-1-48.jpeg"},{"id":"md6-107-1-49","subject":"md6","topic":"婦科-生殖內分泌","meta":"107年第1次第49題","year":107,"session":1,"number":49,"question":"30歲G0P0的女性，因為結婚三年皆沒有避孕，和丈夫想進行不孕症諮詢。自從11歲初經之後，月經皆規則28天一次，每次經期持續5天且沒有經痛。抽血檢查及輸卵管攝影（hysterosalpingography）結果皆正常，量測的antral follicle count為10。丈夫的精液分析（semen analysis）結果為：semen volume 3 ml，sperm concentration 11,000,000/ml，total motility 38%，normal forms 6%。建議他們優先接受那一種醫療輔助生殖（assisted reproductive technologies）最為合理？","options":["(A) 試管嬰兒（in vitro fertilization）","(B) 卵子捐贈","(C) 人工授精（intrauterine insemination）","(D) clomiphene citrate"],"answer":2,"image":""},{"id":"md6-107-1-50","subject":"md6","topic":"產科-高危險妊娠","meta":"107年第1次第50題","year":107,"session":1,"number":50,"question":"30歲G3P0A3的女性，因為三次小於10週的習慣性流產，和丈夫一同前來求診。她之前做過唯一一次的檢查是自體抗體：lupus anticoagulant陰性，anti-β2-glycoprotein 1 Ab陰性，anticaridiolipin IgG high positive。這對夫妻想知道習慣性流產的原因。下列何項建議最不適合？","options":["(A) 告知太太有抗磷脂質症候群（antiphospholipid syndrome），應立即開始服用aspirin","(B) 安排經陰道超音波、子宮輸卵管攝影或子宮腔鏡","(C) 抽血檢查甲狀腺功能","(D) 12週後再追蹤一次自體抗體濃度"],"answer":0,"image":""},{"id":"md6-107-1-51","subject":"md6","topic":"產科-一般產科","meta":"107年第1次第51題","year":107,"session":1,"number":51,"question":"33歲孕婦，G2P0SA1，妊娠40週，入院待產中接受胎兒監視器檢查，結果如圖所示，其判讀為何？","options":["(A) early deceleration","(B) late deceleration","(C) variable decelerations","(D) sinusoid pattern"],"answer":1,"image":"md6-107-1-51.jpeg"},{"id":"md6-107-1-52","subject":"md6","topic":"產科-一般產科","meta":"107年第1次第52題","year":107,"session":1,"number":52,"question":"承上題，下列四者中最可能的臨床意義為何？","options":["(A) Cord compression","(B) Head compression","(C) Utero-placental insufficiency","(D) Respiration"],"answer":2,"image":""},{"id":"md6-107-1-53","subject":"md6","topic":"婦科-生殖內分泌","meta":"107年第1次第53題","year":107,"session":1,"number":53,"question":"王小姐，30歲，最近發現聲音變粗，陰蒂變大，且愈來愈嚴重。下列疾病何者最不可能？","options":["(A) 分泌男性素的卵巢腫瘤","(B) 多囊性卵巢囊腫","(C) 腎上腺腫瘤","(D) 庫欣氏症（Cushing syndrome）"],"answer":1,"image":""},{"id":"md6-107-1-54","subject":"md6","topic":"婦科-生殖內分泌","meta":"107年第1次第54題","year":107,"session":1,"number":54,"question":"承上題，電腦斷層顯示如下圖，抽血檢驗睪固酮（testosterone）為250 ng/dL，DHEAS為800 µg/dL，則診斷最有可能為：","options":["(A) 分泌男性素的卵巢腫瘤","(B) 多囊性卵巢腫瘤","(C) 腎上腺腫瘤","(D) 庫欣氏症（Cushing syndrome）"],"answer":2,"image":"md6-107-1-54.jpeg"},{"id":"md6-107-1-55","subject":"md6","topic":"復健-物理因子治療與評估","meta":"107年第1次第55題","year":107,"session":1,"number":55,"question":"下列那一種疾病的症狀，最不適合用功能性電刺激治療？","options":["(A) 婦女的應力尿失禁（stress urine incontinence）","(B) 脊髓損傷病患的骨質流失（bone loss）","(C) 常期臥床的病人防止深部靜脈栓塞（deep vein thrombosis）","(D) 治療貝克氏肌肉失養症（Becker muscular dystrophy）疾病的肌肉萎縮"],"answer":3,"image":""},{"id":"md6-107-1-56","subject":"md6","topic":"復健-神經復健","meta":"107年第1次第56題","year":107,"session":1,"number":56,"question":"關於半邊忽略現象（hemispatial neglect）之常見評估方法，下列何者最不常使用？","options":["(A) 線二等分測驗（line bisection test）","(B) 仿畫測試（copy test）","(C) 方向測試（direction test）","(D) 刪除測驗（cancellation test）"],"answer":2,"image":""},{"id":"md6-107-1-57","subject":"md6","topic":"復健-神經復健","meta":"107年第1次第57題","year":107,"session":1,"number":57,"question":"有關神經電生理的神經傳導測試H-反射（H-reflex）及F-波（F-wave）敘述，何者正確？","options":["(A) H-反射是一種單突觸反射（monosynaptic reflex）","(B) F-波常出現在M-波前面","(C) F-波振幅常比H-反射大","(D) 因F-波必須用超強度（supramaximal）的電流刺激，所以出現的時間較H-反射固定"],"answer":0,"image":""},{"id":"md6-107-1-58","subject":"md6","topic":"復健-神經復健","meta":"107年第1次第58題","year":107,"session":1,"number":58,"question":"下列何種感染症最不會造成末梢神經病變（peripheral neuropathy）？","options":["(A) B型肝炎（hepatitis B）","(B) 愛滋病（AIDS）","(C) 痲瘋病（leprosy）","(D) 白喉病（diphtheria）"],"answer":0,"image":""},{"id":"md6-107-1-59","subject":"md6","topic":"復健-神經復健","meta":"107年第1次第59題","year":107,"session":1,"number":59,"question":"下列何種病變不會造成手指伸展（extension）無力？","options":["(A) 橈神經（radial nerve）受傷","(B) 骨間前神經病變（anterior interosseous neuropathy）","(C) 骨間後神經症候群（posterior interosseous syndrome）","(D) 臂神經叢（brachial plexus）後索（posterior cord）受傷"],"answer":1,"image":""},{"id":"md6-107-1-60","subject":"md6","topic":"復健-兒童與一般復健","meta":"107年第1次第60題","year":107,"session":1,"number":60,"question":"有關處方上肢裝具（upper limb orthotics），下列何者不是常見的目的？","options":["(A) 提供因疾病造成無力肌肉的肌力訓練（strengthen for weak or absent muscles）","(B) 藉由限制活動或受力來保護受傷的區段（protect damaged or diseased segments by limiting load or motion）","(C) 避免變形或矯正攣縮（prevention of deformity or correction of contracture）","(D) 可連接其他輔具，輔助日常生活功能"],"answer":0,"image":""},{"id":"md6-107-1-61","subject":"md6","topic":"復健-截肢與義肢輔具","meta":"107年第1次第61題","year":107,"session":1,"number":61,"question":"有關處方脊椎裝具（spinal orthotics）的常見適應症（indications），以下何者不適當？","options":["(A) 穩固因骨折或手術後的脊柱不穩定（stabilize the spine after fracture and postsurgical stabilization）","(B) 限制脊椎的活動度來減緩疼痛（limit spinal motion in cases of pain or sprain）","(C) 強化腹肌和背肌的核心肌肉力量（strengthen the core muscle）","(D) 支撐患者的脊柱及避免脊椎變形（support posture and prevent deformity）"],"answer":2,"image":""},{"id":"md6-107-1-62","subject":"md6","topic":"復健-心肺復健與運動處方","meta":"107年第1次第62題","year":107,"session":1,"number":62,"question":"馬拉松選手剛跑完全程後突然暈倒，其原因以下列何者最常見？","options":["(A) 心律不整","(B) 血壓降低","(C) 血液中鈉離子濃度太低","(D) 血糖太低"],"answer":1,"image":""},{"id":"md6-107-1-63","subject":"md6","topic":"復健-骨骼肌肉損傷與疾患","meta":"107年第1次第63題","year":107,"session":1,"number":63,"question":"關於僵直性脊椎炎與脊椎骨折的關係，下列敘述何者正確？","options":["(A) 僵直性脊椎炎的脊椎較僵硬，故較一般人不易發生骨折","(B) 僵直性脊椎炎的病人若發生脊椎骨折，因而產生脊髓損傷的比率較一般人低","(C) 僵直性脊椎炎病人的脊椎骨折，其原因以車禍最常見","(D) 僵直性脊椎炎病人的脊椎骨折以頸椎最常見"],"answer":3,"image":""},{"id":"md6-107-1-64","subject":"md6","topic":"復健-骨骼肌肉損傷與疾患","meta":"107年第1次第64題","year":107,"session":1,"number":64,"question":"王太太為61歲的家庭主婦，近幾個月來覺得手指僵硬、疼痛，但無麻木感。醫師診察發現她雙側的遠端指間關節及近端指間關節均有腫脹現象，有些關節合併有小硬塊，有些關節有壓痛感，請問王太太最可能的診斷是下列何者？","options":["(A) 類風濕性關節炎","(B) 痛風性關節炎","(C) 退化性關節炎","(D) 假痛風性關節炎"],"answer":2,"image":""},{"id":"md6-107-1-65","subject":"md6","topic":"復健-骨骼肌肉損傷與疾患","meta":"107年第1次第65題","year":107,"session":1,"number":65,"question":"有關於人體骨骼肌（skeletal muscle）的描述，何者正確？","options":["(A) 肌肉是人體中最大的組織，約占體重的70%","(B) 肌肉韌帶單元（muscle-tendon unit）通常橫跨一個或多個關節，它的附著點大部分在骨頭上","(C) 單關節肌肉（one-joint muscle）通常參與較快的肌肉收縮，產生較小的力氣","(D) 雙關節肌肉（two-joint muscles）通常位於較表前淺的位置，能產生較慢的收縮，和較大的力氣"],"answer":1,"image":""},{"id":"md6-107-1-66","subject":"md6","topic":"復健-心肺復健與運動處方","meta":"107年第1次第66題","year":107,"session":1,"number":66,"question":"有氧訓練（aerobic training）對正常人之心臟功能，最不可能增加者為：","options":["(A) 最大心博量（maximal stroke volume）","(B) 休息心搏量（resting stroke volume）","(C) 預估最大心跳率（estimated maximum heart rate）","(D) 最大心臟輸出量（maximal cardiac output）"],"answer":2,"image":""},{"id":"md6-107-1-67","subject":"md6","topic":"復健-兒童與一般復健","meta":"107年第1次第67題","year":107,"session":1,"number":67,"question":"A型肉毒桿菌毒素（botulinum neurotoxin type A）應用於治療痙攣症（spasticity），何者錯誤？","options":["(A) 可以用來治療腦性麻痺（cerebral palsy）兒童的痙攣症（spasticity）","(B) 治療途徑是肌肉注射（intramuscular injection）","(C) 機轉是肉毒桿菌毒素抑制神經肌肉交接處（neuromuscular junction）的乙醯膽鹼（acetylcholine）的釋放","(D) 注射效果會立即出現（immediate effect）"],"answer":3,"image":""},{"id":"md6-107-1-68","subject":"md6","topic":"復健-兒童與一般復健","meta":"107年第1次第68題","year":107,"session":1,"number":68,"question":"腦性麻痺（cerebral palsy）患者的骨關節併發症中，何種類群的腦性麻痺患者最容易產生髖關節脫位（hip joint displacement）？","options":["(A) 半邊癱瘓型（hemiplegic）腦性麻痺患者","(B) 四肢癱瘓型（quadriplegic）腦性麻痺患者","(C) 運動困難型（dyskinetic）腦性麻痺患者","(D) 雙邊癱瘓型（diplegic）腦性麻痺患者"],"answer":1,"image":""},{"id":"md6-107-1-69","subject":"md6","topic":"復健-神經復健","meta":"107年第1次第69題","year":107,"session":1,"number":69,"question":"病人說話時，第一個字很難發出來，而且說話過程有延長、重複，甚至中斷的現象，這種症狀最有可能的問題是：","options":["(A) 口吃（stuttering）","(B) 吶吃（dysarthria）","(C) 失語症（aphasia）","(D) 失用症（apraxia）"],"answer":0,"image":""},{"id":"md6-107-1-70","subject":"md6","topic":"復健-神經復健","meta":"107年第1次第70題","year":107,"session":1,"number":70,"question":"腦中風病人在臥床擺位上，長時間側躺（side lying）最常發生壓瘡（pressure sore）的位置在下列何部位？","options":["(A) 腳跟（heel）","(B) 肩峰（acromion）","(C) 股骨大粗隆（greater trochanter）","(D) 腸骨突（iliac crest）"],"answer":2,"image":""},{"id":"md6-107-1-71","subject":"md6","topic":"復健-骨骼肌肉損傷與疾患","meta":"107年第1次第71題","year":107,"session":1,"number":71,"question":"下列關於糖尿病足瘡（diabetic foot ulcer）的敘述，何者最正確？","options":["(A) 曾有足瘡但傷口已經癒合者，復發機會較其他糖尿病患者少","(B) 血管病變引起者比神經病變引起者之預後好","(C) 糖尿病患者應自我照顧潰爛傷口，不必就醫，以減少醫療資源浪費","(D) 處理糖尿病足的最終目標在於降低截肢的發生率"],"answer":3,"image":""},{"id":"md6-107-1-72","subject":"md6","topic":"復健-骨骼肌肉損傷與疾患","meta":"107年第1次第72題","year":107,"session":1,"number":72,"question":"71歲男性不慎跌倒之後，頸部異常疼痛，合併有上肢酸麻感覺；磁振掃描橫向T2加權影像如附圖。其最可能的診斷為何？","options":["(A) 後縱行韌帶骨化","(B) 肌肉筋膜疼痛","(C) 後骨刺生成","(D) 椎間盤突出"],"answer":0,"image":"md6-107-1-72.jpeg"},{"id":"md6-107-1-73","subject":"md6","topic":"婦科-腫瘤","meta":"107年第1次第73題","year":107,"session":1,"number":73,"question":"33歲女性病患因腹痛接受電腦斷層檢查，發現下腹部有一病灶，內有鈣化成分如圖。其診斷為何：","options":["(A) 子宮肌瘤（uterine myoma）","(B) 卵巢癌（ovarian cancer）","(C) 輸卵管卵巢膿瘍（tubo-ovarian abscess）","(D) 畸胎瘤（teratoma）"],"answer":3,"image":"md6-107-1-73.jpeg"},{"id":"md6-107-1-74","subject":"md6","topic":"婦科-手術學與診斷技術","meta":"107年第1次第74題","year":107,"session":1,"number":74,"question":"有關治療產後大量出血之血管內栓塞術的敘述，下列何者最正確？","options":["(A) 血管內栓塞術是唯一的治療方法","(B) 栓塞的目標是止血並盡量保存子宮","(C) 栓塞兩側子宮靜脈對止血的效果最好","(D) 栓塞兩側子宮動脈的後遺症是會造成卵巢壞死"],"answer":1,"image":""},{"id":"md6-107-1-75","subject":"md6","topic":"產科-一般產科","meta":"107年第1次第75題","year":107,"session":1,"number":75,"question":"一位新生兒出生後有一巨大的頭皮血腫塊，臨床醫師安排電腦斷層以確定其病因，檢查發現該血腫塊侷限於左側頂骨（parietal bone）的範圍（如圖），而三個月後再追蹤的電腦斷層也見到吸收後的血腫塊出現鈣化，其最可能診斷是：","options":["(A) Caput succedaneum","(B) Subgaleal hematoma","(C) Cephalohematoma","(D) Subdural hematoma"],"answer":2,"image":"md6-107-1-75.jpeg"},{"id":"md6-107-1-76","subject":"md6","topic":"喉科學與頭頸腫瘤","meta":"107年第1次第76題","year":107,"session":1,"number":76,"question":"有關扁桃腺周圍膿瘍（peritonsillar abscess）的敘述，下列何者錯誤？","options":["(A) 是頭頸部深部感染最常見的疾病之一","(B) 有使用抗生素治療的病人，仍會發生扁桃腺周圍膿瘍","(C) 可以利用針吸（needle aspiration）進行引流治療","(D) 緊急扁桃腺切除術，是經常採用的治療方式"],"answer":3,"image":""},{"id":"md6-107-1-77","subject":"md6","topic":"產科-高危險妊娠","meta":"107年第1次第77題","year":107,"session":1,"number":77,"question":"一位30歲女性，懷孕32週，心跳停止（cardiac arrest）接受急救，依據最新美國心臟醫學會(American Heart Association)急救指引，下列敘述何者錯誤？","options":["(A) 插管時，選用比沒懷孕婦女口徑小0.5~1.0 mm的氣管內管","(B) 電擊劑量應減半以免影響胎兒","(C) 急救藥物的使用與一般成人急救相同","(D) 可考慮緊急剖腹產"],"answer":1,"image":""},{"id":"md6-107-1-78","subject":"md6","topic":"產科-高危險妊娠","meta":"107年第1次第78題","year":107,"session":1,"number":78,"question":"承上題，若急救無效，最好能於心跳停止後多久內實施剖腹產？","options":["(A) 5分鐘","(B) 10分鐘","(C) 15分鐘","(D) 30分鐘"],"answer":0,"image":""},{"id":"md6-107-1-79","subject":"md6","topic":"醫學倫理與法規","meta":"107年第1次第79題","year":107,"session":1,"number":79,"question":"關於人體試驗之研究倫理，第一份明確主張「自願參與」和「知情同意」的國際文獻為何？","options":["(A) 希波克拉底誓詞（Hippocratic Oath）","(B) 紐倫堡守則（the Nuremburg Code）","(C) 貝爾蒙報告書（Belmont Report）","(D) 赫爾辛基宣言（the Declaration of Helsinki）"],"answer":1,"image":""},{"id":"md6-107-1-80","subject":"md6","topic":"醫學倫理與法規","meta":"107年第1次第80題","year":107,"session":1,"number":80,"question":"一位年輕人因車禍受傷被送到急診，病人意識不清但亟需立即開刀，不過一時之間又找不到他的家人來簽同意書，醫師應該如何處理？","options":["(A) 沒有病人同意、因此醫師不應開刀","(B) 先找一找有沒有護理人員願意代理決定，再進行開刀","(C) 雖然沒有病人同意，醫師仍應進行開刀","(D) 通報警局再決定是否開刀"],"answer":2,"image":""},{"id":"md6-107-2-1","subject":"md6","topic":"麻醉-呼吸道與監視","meta":"107年第2次第1題","year":107,"session":2,"number":1,"question":"下列那些麻醉相關設備，在核磁共振攝影室內進行全身麻醉時可以安全使用？①blood pressure cuff ②Macintosh laryngoscope ③cardiac defibrillator ④oximeter probe","options":["(A) 僅①②③","(B) ①②③④","(C) 僅①④","(D) 僅②③④"],"answer":[0,1,2,3],"image":"","answer_note":"送分:第1題一律給分 (原公告答案 C)"},{"id":"md6-107-2-2","subject":"md6","topic":"麻醉-呼吸道與監視","meta":"107年第2次第2題","year":107,"session":2,"number":2,"question":"下列何項因素不會使動脈血中二氧化碳（arterial carbon dioxide）分壓與吐氣末端二氧化碳（end-tidal carbon dioxide）分壓的梯度差異（gradient difference）增加？","options":["(A) fresh gas flow rates由4 L/min增加至8 L/min","(B) air embolism","(C) ventilation/perfusion mismatched","(D) cardiac output由4 L/min增加至8 L/min"],"answer":3,"image":""},{"id":"md6-107-2-3","subject":"md6","topic":"麻醉-呼吸道與監視","meta":"107年第2次第3題","year":107,"session":2,"number":3,"question":"下列那些原因是判讀脈動式血氧飽和監測儀（pulse oximeter）時，產生錯誤性低估（false low readings）？ ①blue nail polish ②hyperbilirubinemia ③methylene blue administration ④high altitude","options":["(A) 僅①②③","(B) 僅①③","(C) 僅②④","(D) 僅④"],"answer":1,"image":""},{"id":"md6-107-2-4","subject":"md6","topic":"麻醉-麻醉藥理","meta":"107年第2次第4題","year":107,"session":2,"number":4,"question":"下列局部麻醉藥物，何者不屬於ester type？","options":["(A) lidocaine","(B) cocaine","(C) tetracaine","(D) procaine"],"answer":0,"image":""},{"id":"md6-107-2-5","subject":"md6","topic":"麻醉-特殊麻醉與疼痛","meta":"107年第2次第5題","year":107,"session":2,"number":5,"question":"70歲男性病患腦中風合併腦壓上升，預行傳統開顱減壓手術，下列有關麻醉中降腦壓治療的敘述，何者錯誤？","options":["(A) 降動脈血中二氧化碳至30～33 mmHg","(B) Mannitol（0.25～0.5 g/kg）降腦壓是因為改變血中滲透壓","(C) 利尿劑（furosemide）有幫忙是因為減少腦組織水分及腦脊液產生","(D) 動脈血中二氧化碳維持愈低愈好"],"answer":3,"image":""},{"id":"md6-107-2-6","subject":"md6","topic":"麻醉-特殊麻醉與疼痛","meta":"107年第2次第6題","year":107,"session":2,"number":6,"question":"下列有關高齡病人接受麻醉比較容易發生術後譫妄（post-operative delirium）現象之敘述，何者錯誤？","options":["(A) 原有視覺或聽覺障礙者發生比例較高","(B) 接受骨科或大手術者發生率較高","(C) 疼痛控制不良者發生率較高","(D) 女性發生率較高"],"answer":3,"image":""},{"id":"md6-107-2-7","subject":"md6","topic":"醫學倫理與法規","meta":"107年第2次第7題","year":107,"session":2,"number":7,"question":"關於病患的疼痛解除原則，下列何者正確？","options":["(A) 非癌症疼痛的病人若有慢性疼痛，醫師絕對不可以使用opioids來控制其疼痛","(B) 疼痛的解除是病人的基本人權","(C) 有藥物濫用病史的病人若有疼痛需先照會精神科醫師後，才可處理","(D) 癌症病人若有需要使用opioids來緩解疼痛，劑量應愈少愈好，以免病人上癮"],"answer":1,"image":""},{"id":"md6-107-2-8","subject":"md6","topic":"麻醉-特殊麻醉與疼痛","meta":"107年第2次第8題","year":107,"session":2,"number":8,"question":"38歲女性病患手術後因四連刺激監測（train of four）顯示肌肉抽動都阻斷（total twitch suppression），並須進住加護病房進行呼吸照護。初步排除其它術後併發症，病人在第2天後逐步恢復，並脫離呼吸器而拔管，病人最可能的診斷為何？","options":["(A) spinal cord injury","(B) Guillain-Barre syndrome","(C) myasthenia gravis","(D) meningitis"],"answer":2,"image":""},{"id":"md6-107-2-9","subject":"md6","topic":"眼科-視網膜葡萄膜","meta":"107年第2次第9題","year":107,"session":2,"number":9,"question":"一名眼部鈍性挫傷（blunt trauma）病患接受眼底檢查，何種發現與此次受傷較無關？","options":["(A) 黃斑部裂孔（macular hole）","(B) 視網膜震傷（commotio retinae）","(C) 黃斑部隱結（drusen）","(D) 玻璃體出血（vitreous hemorrhage）"],"answer":2,"image":""},{"id":"md6-107-2-10","subject":"md6","topic":"眼科-角膜結膜眼瞼眼窩","meta":"107年第2次第10題","year":107,"session":2,"number":10,"question":"有關腺病毒結膜炎（adenoviral keratoconjunctivitis）的敘述，下列何者錯誤？","options":["(A) 腺病毒可存活於乾燥表面，而導致結膜炎之流行","(B) 可伴隨耳前淋巴結腫大（pre-auricular lymphadenopathy）","(C) 局部點用類固醇眼藥水可縮短角膜炎之持續時間","(D) 一般會兩眼發病"],"answer":2,"image":""},{"id":"md6-107-2-11","subject":"md6","topic":"眼科-水晶體青光眼","meta":"107年第2次第11題","year":107,"session":2,"number":11,"question":"下列有關房水（aqueous humour）之敘述，何者錯誤？","options":["(A) 房水是血漿在睫狀體（cilicary body）處分泌（secretion）形成","(B) 大約90%的房水經小樑網（trabecular meshwork）排出眼睛","(C) 大約10%的房水經葡萄膜鞏膜路徑（uveoscleral route）排出眼睛","(D) 房水在前房形成，經瞳孔，流入後房排出"],"answer":3,"image":""},{"id":"md6-107-2-12","subject":"md6","topic":"眼科-水晶體青光眼","meta":"107年第2次第12題","year":107,"session":2,"number":12,"question":"一般藥理學上，下列何種點眼藥物，並不具降眼壓的效果？","options":["(A) atropine","(B) betaxolol","(C) carteolol","(D) dorzolamide"],"answer":0,"image":""},{"id":"md6-107-2-13","subject":"md6","topic":"眼科-屈光斜弱視","meta":"107年第2次第13題","year":107,"session":2,"number":13,"question":"內斜視（esotropia）常與下列何種屈光異常有關？","options":["(A) 近視（myopia）","(B) 遠視（hypermetropia）","(C) 老花（presbyopia）","(D) 散光（astigmatism）"],"answer":1,"image":""},{"id":"md6-107-2-14","subject":"md6","topic":"眼科-屈光斜弱視","meta":"107年第2次第14題","year":107,"session":2,"number":14,"question":"右眼外展神經（abducens nerve）麻痺病人，以右眼固視（fixation）時，斜視角度會呈現下列何種情況？","options":["(A) 內斜視角度大於用左眼固視","(B) 內斜視角度小於用左眼固視","(C) 外斜視角度大於用左眼固視","(D) 外斜視角度小於用左眼固視"],"answer":0,"image":""},{"id":"md6-107-2-15","subject":"md6","topic":"眼科-角膜結膜眼瞼眼窩","meta":"107年第2次第15題","year":107,"session":2,"number":15,"question":"下列關於甲狀腺眼病變的敘述，何者錯誤？","options":["(A) 好發於中年女性","(B) 上直肌（superior rectus muscle）比其他眼外肌較早出現發炎及纖維化","(C) 抽菸為甲狀腺眼病變的危險因子，故治療上也須要求病人戒煙","(D) 是造成成人單眼凸眼症最常見的原因"],"answer":1,"image":""},{"id":"md6-107-2-16","subject":"md6","topic":"眼科-角膜結膜眼瞼眼窩","meta":"107年第2次第16題","year":107,"session":2,"number":16,"question":"一位六十歲女性在接受右側聽神經瘤（acoustic neuroma）切除手術後，出現同側眼睛逐漸紅眼及流淚症狀，檢查時發現病患右側眼瞼閉合不良（lagophthalmos），下列何者錯誤？","options":["(A) 流淚症狀可能導因於淚點（lacrimal punctum）外翻","(B) 病患可能同時伴有暴露性角膜炎（exposure keratopathy）","(C) 可以肉毒桿菌素（botulinum toxin）注射在提眼瞼肌（levator palpebrae muscle）內，造成暫時性眼瞼下垂，保護眼角膜","(D) 此種情形造成的眼瞼外翻，因屬麻痺性外翻（paralytic ectropion），無法以手術改善"],"answer":3,"image":""},{"id":"md6-107-2-17","subject":"md6","topic":"喉科學與頭頸腫瘤","meta":"107年第2次第17題","year":107,"session":2,"number":17,"question":"有關於鼻咽血管纖維瘤（angiofibroma）之敘述，下列何者正確？","options":["(A) 是鼻咽部最常見之良性腫瘤","(B) 男女發生率差不多","(C) 以中老年者居多","(D) 放射治療是主要治療方式"],"answer":0,"image":""},{"id":"md6-107-2-18","subject":"md6","topic":"鼻科學","meta":"107年第2次第18題","year":107,"session":2,"number":18,"question":"非過敏性鼻炎的治療，以下那一項效果最差？","options":["(A) 類固醇鼻噴劑","(B) 口服第一代抗組織胺","(C) 口服第二代抗組織胺","(D) 抗組織胺鼻噴劑"],"answer":2,"image":""},{"id":"md6-107-2-19","subject":"md6","topic":"鼻科學","meta":"107年第2次第19題","year":107,"session":2,"number":19,"question":"鼻及鼻竇疾病所謂的“Pott puffy tumor”指的是：","options":["(A) 額骨骨髓炎（frontal bone osteomyelitis）","(B) 篩竇腫瘤（ethmoid tumor）","(C) 眼眶骨膜下膿瘍（orbital subperiosteal abscess）","(D) 鼻唇囊腫（nasolabial cyst）"],"answer":0,"image":""},{"id":"md6-107-2-20","subject":"md6","topic":"喉科學與頭頸腫瘤","meta":"107年第2次第20題","year":107,"session":2,"number":20,"question":"有關下咽癌的敘述，下列何者正確？","options":["(A) 主要的致病原因是人類乳突瘤病毒感染","(B) 最常發生的次部位是下咽後壁（posterior pharyngeal wall）","(C) 檢查時需注意是否有第二原發食道癌","(D) 因症狀明顯，發現時大多數為早期（stage I, II）"],"answer":2,"image":""},{"id":"md6-107-2-21","subject":"md6","topic":"耳科學","meta":"107年第2次第21題","year":107,"session":2,"number":21,"question":"病人因單耳聽力不佳，到耳鼻喉科看診，耳鏡檢查如下圖，最可能之診斷為：","options":["(A) 先天性膽脂瘤（congenital cholesteatoma）","(B) 原發性後天性膽脂瘤（primary acquired cholesteatoma）","(C) 繼發性後天性膽脂瘤（secondary acquired cholesteatoma）","(D) 耳道膽脂瘤（ear canal cholesteatoma）"],"answer":0,"image":"md6-107-2-21.jpeg"},{"id":"md6-107-2-22","subject":"md6","topic":"耳科學","meta":"107年第2次第22題","year":107,"session":2,"number":22,"question":"承上題，此病人接受純音聽力檢查（pure tone audiometry），最可能的結果為下列何者？","options":["(A) ","(B) ","(C) ","(D) "],"answer":0,"image":"md6-107-2-22.jpeg"},{"id":"md6-107-2-23","subject":"md6","topic":"喉科學與頭頸腫瘤","meta":"107年第2次第23題","year":107,"session":2,"number":23,"question":"病人因聲音沙啞與嗆咳而就診，經詢問過往無重大內外科疾病或手術之病史，局部檢查頸部觸診無明顯腫塊，喉內視鏡檢查發現左側聲帶不活動，後續應安排何種檢查最為適當？","options":["(A) 頸部X光攝影","(B) 病毒血清學檢查","(C) 上消化道內視鏡","(D) 頭頸胸部斷層掃瞄"],"answer":3,"image":""},{"id":"md6-107-2-24","subject":"md6","topic":"喉科學與頭頸腫瘤","meta":"107年第2次第24題","year":107,"session":2,"number":24,"question":"承上題，下列何種治療對於改善該病人之臨床症狀最無幫助？","options":["(A) 聲帶注射填充（injection augmentation）","(B) 內移式甲狀軟骨成型術（medialization thyroplasty）","(C) 懸雍垂軟腭咽喉成型術（uvulopalatopharyngoplasty）","(D) 喉返神經接合（reinnervation of recurrent laryngeal nerve）"],"answer":2,"image":""},{"id":"md6-107-2-25","subject":"md6","topic":"復健-神經復健","meta":"107年第2次第25題","year":107,"session":2,"number":25,"question":"肩難產最容易發生的問題是：","options":["(A) 膈神經受傷","(B) 臂神經叢受傷","(C) 鎖骨骨折","(D) 肱骨骨折"],"answer":1,"image":""},{"id":"md6-107-2-26","subject":"md6","topic":"產科-一般產科","meta":"107年第2次第26題","year":107,"session":2,"number":26,"question":"如果子宮頸位置向前（anterior），其硬度中等（medium），薄度（effacement）40～50%，開口3～4公分，胎頭位於-1，其Bishop score是多少？","options":["(A) 4","(B) 6","(C) 8","(D) 10"],"answer":2,"image":""},{"id":"md6-107-2-27","subject":"md6","topic":"婦科-生殖道感染與先天異常","meta":"107年第2次第27題","year":107,"session":2,"number":27,"question":"20歲苗勒氏管不發育（müllerian agenesis）的女性患者接受腹腔鏡闌尾切除時，外科醫師在骨盆腔發現疑似子宮內膜異位症的病灶，下列何項敘述能合理解釋此情況？","options":["(A) 不可能發生子宮內膜異位症，因為沒有子宮的緣故","(B) 常常伴隨子宮內膜異位症，因為經血無法排出（menstrual outflow obstruction）的緣故","(C) 可能會有子宮內膜異位症，因為經血逆流（retrograde menstruation）的緣故","(D) 可能會有子宮內膜異位症，因為體腔上皮異常化生（coelomic metaplasia）的緣故"],"answer":3,"image":""},{"id":"md6-107-2-28","subject":"md6","topic":"婦科-生殖道感染與先天異常","meta":"107年第2次第28題","year":107,"session":2,"number":28,"question":"25歲婦女，有兩胎經陰道生產的產科史，第二胎由於巨嬰及產程遲滯藉由產鉗娩出，生產時有會陰四度撕裂傷但立即做修補手術，術後卻發生會陰傷口感染的情況。會陰傷口感染改善後，患者常覺得有黃色屎狀分泌物經由陰道排出，而且放屁時無法控制，常會感覺有氣體由陰道排出之情形。理學檢查施行陰道肛門指診時，發現如圖所示之情形，依據圖示此患者最適合之診斷為：","options":["(A) 膀胱陰道瘻管（vesicovaginal fistula）","(B) 尿道陰道瘻管（urethrovaginal fistula）","(C) 直腸陰道瘻管（rectovaginal fistula）","(D) 子宮膀胱瘻管（uterovesical fistula）"],"answer":2,"image":"md6-107-2-28.jpeg"},{"id":"md6-107-2-29","subject":"md6","topic":"婦科-生殖內分泌","meta":"107年第2次第29題","year":107,"session":2,"number":29,"question":"子宮內膜會受荷爾蒙之影響而於超音波掃描下有所變化，下圖中那個超音波圖形，其內膜之變化顯示患者目前之生理情況，最接近於排卵日？","options":["(A) ","(B) ","(C) ","(D) "],"answer":2,"image":"md6-107-2-29.jpeg"},{"id":"md6-107-2-30","subject":"md6","topic":"婦科-生殖內分泌","meta":"107年第2次第30題","year":107,"session":2,"number":30,"question":"一對不孕的夫婦，在初診時，第一步該做的是：","options":["(A) 了解夫婦的病史包括：婚姻生活、性生活、月經病史及以前做過的檢查","(B) 分析夫婦血液中的性荷爾蒙","(C) 女性不孕的最大原因是輸卵管阻塞，所以安排子宮輸卵管攝影","(D) 男性不孕的最大原因是精蟲製造過程異常，所以安排精液檢查"],"answer":0,"image":""},{"id":"md6-107-2-31","subject":"md6","topic":"婦科-良性腫瘤與內膜異位","meta":"107年第2次第31題","year":107,"session":2,"number":31,"question":"32歲女性，主訴近年來經痛越來越嚴重，並有性交疼痛及非經期的腹痛。超音波的檢查如圖所示。下列何者對於確認診斷最有幫助？","options":["(A) 腹腔鏡","(B) 比較經期中與非經期的血中CA-125濃度","(C) 詳細的病史及理學檢查","(D) 子宮輸卵管攝影"],"answer":0,"image":"md6-107-2-31.jpeg"},{"id":"md6-107-2-32","subject":"md6","topic":"婦科-生殖內分泌","meta":"107年第2次第32題","year":107,"session":2,"number":32,"question":"25歲女大學生，主訴半年無月經，病患主訴課業壓力大，外觀體毛細，皮膚偏黃，身高162公分，體重35公斤，關於此病患，下列敘述何者錯誤？","options":["(A) 血中FSH及E可見hypogonadotropic hypogonadism 2","(B) 必要時可照會精神科","(C) 使用clomiphene citrate可恢復月經","(D) 增重對於月經恢復有幫忙"],"answer":2,"image":""},{"id":"md6-107-2-33","subject":"md6","topic":"婦科-腫瘤","meta":"107年第2次第33題","year":107,"session":2,"number":33,"question":"下列何者不是上皮性卵巢癌？","options":["(A) Mucinous adenocarcinoma","(B) Serous adenocarcinoma","(C) Endometrioid adenocarcinoma","(D) Granulosa cell tumor"],"answer":3,"image":""},{"id":"md6-107-2-34","subject":"md6","topic":"婦科-腫瘤","meta":"107年第2次第34題","year":107,"session":2,"number":34,"question":"對於第二型子宮內膜癌（type II endometrial cancer）的特徵之敘述，下列何者較適當？①常與雌激素過度刺激無關 ②多為low grade endometrioid type的病理形態 ③多為停經以後的年長女性 ④預後通常比第一型子宮內膜癌差 ⑤常與子宮內膜增生有關（endometrial hyperplasia）","options":["(A) ①②③⑤","(B) ①③④","(C) ②⑤","(D) ②③⑤"],"answer":1,"image":""},{"id":"md6-107-2-35","subject":"md6","topic":"婦科-腫瘤","meta":"107年第2次第35題","year":107,"session":2,"number":35,"question":"朱女士60歲，食慾不振有1個月之久，曾到腸胃科求治，因超音波檢查發現大量腹水，血中CA-125高達1020 U/mL，於是轉至婦科。陰道超音波檢查發現除腹水外，子宮及卵巢屬正常範圍，經一系列檢查，初步診斷為腹膜癌（peritoneal serous papillary carcinoma）。下列敘述何者錯誤？","options":["(A) 此疾病有Wolffian carcinoma的特徵","(B) 此疾病之組織及免疫化學染色和卵巢癌很類似","(C) 此疾病之卵巢應無侵犯，或僅侵犯卵巢上皮而未達基質，或侵犯卵巢皮層基質而腫瘤小於5×5 mm","(D) 卵巢以外的病灶必須大於任何一邊卵巢的表面病灶，並且在上腹部特別是大網膜有廣泛病灶"],"answer":0,"image":""},{"id":"md6-107-2-36","subject":"md6","topic":"婦科-腫瘤","meta":"107年第2次第36題","year":107,"session":2,"number":36,"question":"Bowen's disease是那一個部位的疾病？","options":["(A) 子宮體","(B) 子宮頸","(C) 陰道","(D) 外陰"],"answer":3,"image":""},{"id":"md6-107-2-37","subject":"md6","topic":"產科-高危險妊娠","meta":"107年第2次第37題","year":107,"session":2,"number":37,"question":"35歲孕婦經轉診至門診，G2P0AA1，無家族病史，目前妊娠22週。該孕婦於產前超音波檢查時，結果如圖所示，該異常特徵（sign）為何？","options":["(A) double bubble sign","(B) banana sign","(C) keyhole sign","(D) lemon sign"],"answer":1,"image":"md6-107-2-37.jpeg"},{"id":"md6-107-2-38","subject":"md6","topic":"產科-高危險妊娠","meta":"107年第2次第38題","year":107,"session":2,"number":38,"question":"40歲孕婦，G5P2AA2，再婚後意外懷孕。本次懷孕尚未接受過任何產檢，無家族病史，過去兩胎皆正常。目前妊娠22週，至門診接受超音波檢查，由於該孕婦此胎並未接受羊膜穿刺及頸部透明帶母血唐氏症篩檢，對於生出唐氏症寶寶相當焦慮。下列何者不是唐氏症產前超音波之特色指標（sonographic markers）？","options":["(A) echogenic bowel","(B) nuchal skinfold thickening","(C) short humerus","(D) short tibia"],"answer":3,"image":""},{"id":"md6-107-2-39","subject":"md6","topic":"產科-一般產科","meta":"107年第2次第39題","year":107,"session":2,"number":39,"question":"根據2013年美國婦產科醫學會（ACOG）的建議，將胎心音監測準則依嚴重程度分為三級，下列何者不是第三級胎心音（category III）異常？","options":["(A) 早發性心搏減速（early variable deceleration）及心搏間變異消失（absent baseline fetal heart rate variability）","(B) 反覆的變異性心搏減速（recurrent variable deceleration）及心搏間變異消失（absent baseline fetal heart rate variability）","(C) 反覆的遲發性心搏減速（recurrent late deceleration）及心搏間變異消失（absent baseline fetal heart rate variability）","(D) 正弦曲線胎心率（sinusoidal fetal heart rate）"],"answer":0,"image":""},{"id":"md6-107-2-40","subject":"md6","topic":"產科-一般產科","meta":"107年第2次第40題","year":107,"session":2,"number":40,"question":"造成產後出血的原因，下列何者最常見？","options":["(A) 子宮收縮不佳（atony）","(B) 羊水栓塞（amniotic fluid embolism）","(C) 胎盤滯留（retained placenta）","(D) 生殖道撕裂傷（injury to birth canal）"],"answer":0,"image":""},{"id":"md6-107-2-41","subject":"md6","topic":"產科-一般產科","meta":"107年第2次第41題","year":107,"session":2,"number":41,"question":"胎心無壓力試驗（non-stress test）20分鐘檢查結果，有二次胎心加速大於基線胎心搏（baseline）15 bpm（beat per minute）以上，且持續15秒以上，可以判讀為：","options":["(A) 正常反應（reactive）","(B) 不正常反應（nonreactive）","(C) 爭議性（equivocal）","(D) 無法判讀（unsatisfactory）"],"answer":0,"image":""},{"id":"md6-107-2-42","subject":"md6","topic":"產科-高危險妊娠","meta":"107年第2次第42題","year":107,"session":2,"number":42,"question":"34歲G2P1孕婦，妊娠25週被診斷為子癇前症（preeclampsia），現妊娠31週主訴近3天來常感呼吸急促（shortness of breath），且無法平躺，經基層診所轉診至醫院急診。理學檢查血壓158/96 mmHg，體重較2週前增加4 kg，尿蛋白4+。此時的最優先處置為：","options":["(A) 胸部聽診及胸部X光（chest X-ray）檢查","(B) 給予安胎治療","(C) 給予利尿劑治療","(D) 安排剖腹生產"],"answer":0,"image":""},{"id":"md6-107-2-43","subject":"md6","topic":"產科-一般產科","meta":"107年第2次第43題","year":107,"session":2,"number":43,"question":"有關流產敘述，下列何者錯誤？","options":["(A) 先兆性流產（threatened abortion），通常最終導致流產","(B) 子宮頸口已開，懷孕組織還未掉出來，稱無可避免的流產（inevitable abortion）","(C) 已有部分懷孕組織排出，稱不完全流產（incomplete abortion）","(D) 若不完全流產病患有發燒現象，應給予抗生素"],"answer":0,"image":""},{"id":"md6-107-2-44","subject":"md6","topic":"婦科-腫瘤","meta":"107年第2次第44題","year":107,"session":2,"number":44,"question":"骨盆腔或後腹腔（pelvic or retroperitoneal space）的淋巴結廓清術或取樣（lymph node dissection or sampling），在婦女生殖道癌症的手術，通常都要常規（routine）執行。下列何種腫瘤在初期時，例如FIGO stage I and II，一般可省略淋巴結廓清術或取樣？","options":["(A) 子宮平滑肌肉瘤（uterine leiomyosarcoma）","(B) 子宮內膜基質癌（endometrial stromal cancer）","(C) 子宮癌肉瘤（uterine carcinosarcoma）","(D) 卵巢癌（ovarian cancer）"],"answer":0,"image":""},{"id":"md6-107-2-45","subject":"md6","topic":"婦科-腫瘤","meta":"107年第2次第45題","year":107,"session":2,"number":45,"question":"妊娠滋養細胞疾病（gestational trophoblastic disease）轉移到腦的治療，在沒有出血及壓迫性症狀的狀況下，下列何者是NETDC（New England Trophoblastic Disease Center [Dana-Farber Cancer Institute]）所建議的優先治療方法？","options":["(A) 全腦放射線治療（whole-brain radiation）","(B) 立體定位放射線手術治療（stereotactic radiosurgery）","(C) 開顱手術（craniotomy）","(D) 結合化療及放射線治療（combination of chemotherapy and brain irradiation）"],"answer":3,"image":""},{"id":"md6-107-2-46","subject":"md6","topic":"婦科-生殖內分泌","meta":"107年第2次第46題","year":107,"session":2,"number":46,"question":"關於排卵前LH surge的生理效應之敘述，下列何者錯誤？","options":["(A) 可以恢復卵子第一次減數分裂（meiosis I）的進行","(B) 促進濾泡中顆粒細胞（granulose cells）的黃體化（luteinization）","(C) 促進濾泡中顆粒細胞（granulose cells）製造及分泌前列腺素（prostaglandins）","(D) 促進濾泡中顆粒細胞（granulose cells）製造及分泌雄性素（androgens）"],"answer":3,"image":""},{"id":"md6-107-2-47","subject":"md6","topic":"婦科-生殖內分泌","meta":"107年第2次第47題","year":107,"session":2,"number":47,"question":"關於胎兒性器官的分化之敘述，下列何者錯誤？","options":["(A) 要有Y染色體並且有SRY基因，胎兒性器官才會發育成睪丸、輸精管、儲精囊與陰莖","(B) Sertoli細胞會製造及分泌AMH（antimüllerian hormone）","(C) AMH會抑制Wolffian管的分化與生長","(D) Leydig細胞會製造及分泌testosterone"],"answer":2,"image":""},{"id":"md6-107-2-48","subject":"md6","topic":"婦科-生殖內分泌","meta":"107年第2次第48題","year":107,"session":2,"number":48,"question":"高泌乳激素血症（hyperprolactinemia）出現的症狀，下列何者相關性最小？","options":["(A) 乳汁分泌","(B) 月經異常","(C) 噁心、嘔吐","(D) 頭痛與視覺障礙"],"answer":2,"image":""},{"id":"md6-107-2-49","subject":"md6","topic":"婦科-生殖內分泌","meta":"107年第2次第49題","year":107,"session":2,"number":49,"question":"有關試管嬰兒療程中，胚胎培養與植入的敘述，下列何者錯誤？","options":["(A) 胚胎培養的初期（pre-compaction），建議培養基需要較多的丙酮酸（pyruvate）來模擬輸卵管的環境","(B) 胚胎培養的後期（post-compaction），建議培養基需要較多非必需胺基酸（non-essential amino acids）來模擬子宮的環境","(C) 當患者條件正常時，囊胚期胚胎植入相較於分裂中的胚胎植入有較高的著床率","(D) 胚胎培養至囊胚期相較於分裂中的胚胎，有較高的機會沒有胚胎可以植入"],"answer":1,"image":""},{"id":"md6-107-2-50","subject":"md6","topic":"婦科-生殖內分泌","meta":"107年第2次第50題","year":107,"session":2,"number":50,"question":"依順序排列出精子成熟至受精的過程： ①頂體反應（acrosomal reaction） ②皮層反應（cortical reaction） ③獲能（capacitation） ④射精（ejaculation）","options":["(A) ①②③④","(B) ④③②①","(C) ④③①②","(D) ①②④③"],"answer":2,"image":""},{"id":"md6-107-2-51","subject":"md6","topic":"婦科-生殖內分泌","meta":"107年第2次第51題","year":107,"session":2,"number":51,"question":"clomiphene通常對下列那一種排卵異常的不孕症患者，誘發排卵的效果較差？","options":["(A) 厭食症","(B) 多囊性卵巢症候群","(C) 泌乳激素過高","(D) 不明原因不孕症"],"answer":0,"image":""},{"id":"md6-107-2-52","subject":"md6","topic":"婦科-生殖內分泌","meta":"107年第2次第52題","year":107,"session":2,"number":52,"question":"卵子生成過程中，胚泡崩解（germinal vesicle breakdown, GVBD）現象出現，代表減數分裂的那一個階段？","options":["(A) 重新啟動減數分裂I（meiosis I）","(B) 完成減數分裂I（meiosis I）","(C) 完成減數分裂II（meiosis II）","(D) 完成受精（fertilization）"],"answer":0,"image":""},{"id":"md6-107-2-53","subject":"md6","topic":"產科-一般產科","meta":"107年第2次第53題","year":107,"session":2,"number":53,"question":"37歲孕婦，G1P0，妊娠36週，血壓180/110 mmHg，接受下列超音波檢查，如圖所示。則該檢查是：","options":["(A) 臍動脈血流速度波形","(B) 臍靜脈血流速度波形","(C) 胎心音加壓性試驗","(D) 胎動檢查"],"answer":0,"image":"md6-107-2-53.jpeg"},{"id":"md6-107-2-54","subject":"md6","topic":"產科-一般產科","meta":"107年第2次第54題","year":107,"session":2,"number":54,"question":"承上題，正確的判讀為下列何者？","options":["(A) 胎兒腦波反應","(B) 胎兒睡眠反應","(C) 胎兒正常","(D) 胎兒窘迫"],"answer":3,"image":""},{"id":"md6-107-2-55","subject":"md6","topic":"婦科-尿失禁與骨盆腔脫垂","meta":"107年第2次第55題","year":107,"session":2,"number":55,"question":"關於下尿路的神經支配，下列敘述何者最為正確？","options":["(A) 交感神經主要為抑制膀胱收縮，關閉膀胱頸及關閉尿道，並不會經由下腹神經（hypogastric nerve）","(B) 副交感神經主要讓逼尿肌收縮，產生排尿功能，主要經由下腹神經（hypogastric nerve）","(C) 體神經主要支配外括約肌和其他骨盆底肌肉，主要經由陰部神經（pudendal nerve）","(D) 感覺神經主要途經骨盆神經及陰部神經"],"answer":2,"image":""},{"id":"md6-107-2-56","subject":"md6","topic":"復健-神經復健","meta":"107年第2次第56題","year":107,"session":2,"number":56,"question":"下列何者是老年人造成頸部脊髓病變（cervical myelopathy）最常見的原因？","options":["(A) 脊椎腫瘤（spinal tumor）","(B) 脊髓炎（myelitis）","(C) 脊椎退化症（spondylosis）","(D) 多發性硬化症（multiple sclerosis）"],"answer":2,"image":""},{"id":"md6-107-2-57","subject":"md6","topic":"復健-心肺復健與運動處方","meta":"107年第2次第57題","year":107,"session":2,"number":57,"question":"依奧林匹克運動委員會規定，下列何者為運動員之禁藥，不宜於運動前處方給運動員使用？","options":["(A) acetaminophen","(B) caffeine","(C) anabolic steroid","(D) creatine"],"answer":2,"image":""},{"id":"md6-107-2-58","subject":"md6","topic":"復健-截肢與義肢輔具","meta":"107年第2次第58題","year":107,"session":2,"number":58,"question":"關於後天性截肢（acquired amputation）的原因，何者錯誤？","options":["(A) 下肢截肢最常見的原因是血管的疾病（vascular disease）","(B) 下肢創傷性截肢（traumatic amputation）的年齡層大多分布在60～70歲","(C) 上肢創傷性截肢的位置大多集中在手腕以下，以手指頭截肢（digital amputation）為大多數","(D) 不論是上肢或下肢的截肢，腫瘤（tumor）是在兒童族群最常見的原因"],"answer":[1,3],"image":"","answer_note":"更正:第58題答Ｂ、Ｄ給分"},{"id":"md6-107-2-59","subject":"md6","topic":"復健-骨骼肌肉損傷與疾患","meta":"107年第2次第59題","year":107,"session":2,"number":59,"question":"關於頸椎椎間盤突出症之敘述，下列何者正確？","options":["(A) 頸椎椎間盤突出症之疼痛不會傳至前胸","(B) 中間型（central）之椎間盤突出症較易導致脊髓的壓迫","(C) 第五、六頸椎間之外側型（lateral）椎間盤突出症較易壓迫到C5神經根","(D) 若懷疑神經根壓迫應儘速（一週內）安排肌電圖檢查"],"answer":1,"image":""},{"id":"md6-107-2-60","subject":"md6","topic":"復健-骨骼肌肉損傷與疾患","meta":"107年第2次第60題","year":107,"session":2,"number":60,"question":"一位籃球選手可以帶球跑步上籃，但在跳投時臏骨（patella）下緣會有疼痛現象，下列那種疾病是最可能的診斷？","options":["(A) 前十字韌帶（anterior cruciate ligament）斷裂","(B) 膝骨性關節炎（osteoarthritis）","(C) 內側半月型軟骨（meniscus）破裂","(D) 膝肌腱炎（patellar tendinitis）"],"answer":3,"image":""},{"id":"md6-107-2-61","subject":"md6","topic":"復健-骨骼肌肉損傷與疾患","meta":"107年第2次第61題","year":107,"session":2,"number":61,"question":"針對第十二節胸椎發生壓迫性骨折（compression fracture）病人處方輔具支架時，下列何者最合適？","options":["(A) 全背架（Knight-Taylor brace）","(B) 短腰背架（Knight brace）","(C) 束腹（lumbar corset）","(D) 米瓦基背架（Milwaukee brace）"],"answer":0,"image":""},{"id":"md6-107-2-62","subject":"md6","topic":"復健-心肺復健與運動處方","meta":"107年第2次第62題","year":107,"session":2,"number":62,"question":"有關肺部復健（pulmonary rehabilitation）的描述，下列何者錯誤？","options":["(A) 治療的對象包括阻塞性肺疾病、限制性肺疾病、神經肌肉病變、脊髓損傷患者等","(B) 主要的目的在逆轉肺部組織的病理變化","(C) 復健內容除了呼吸訓練、排痰外，也包括藥物優化、生理功能的評估和對失能的應對方式（coping skills），教育、營養諮詢及精神社會支持等","(D) 訓練結果常可使患者增加運動耐受力，改善生活功能，增加生活品質，更進一步減少醫療資源的耗用"],"answer":1,"image":""},{"id":"md6-107-2-63","subject":"md6","topic":"復健-心肺復健與運動處方","meta":"107年第2次第63題","year":107,"session":2,"number":63,"question":"關於運動和血糖的關係，下列敘述何者錯誤？","options":["(A) 運動可以協助糖尿病患者血糖的控制","(B) 運動不能促進第II型糖尿病患者的胰島素敏感度","(C) 第Ｉ型糖尿病患者，在運動時容易有低血糖之危險","(D) 對血糖耐受性差之患者，規律運動加上飲食控制，可以降低此類患者變成第II型糖尿病之危險性"],"answer":1,"image":""},{"id":"md6-107-2-64","subject":"md6","topic":"復健-心肺復健與運動處方","meta":"107年第2次第64題","year":107,"session":2,"number":64,"question":"運動測試（exercise testing）的絕對禁忌症（absolute contraindication）不包含下列那一項？","options":["(A) 不穩定心絞痛（unstable angina）","(B) 有症狀且嚴重的主動脈狹窄（aortic stenosis）","(C) 第一度心房心室阻斷（first degree atrioventricular block）","(D) 急性全身性感染症合併發燒、全身酸痛"],"answer":2,"image":""},{"id":"md6-107-2-65","subject":"md6","topic":"復健-兒童與一般復健","meta":"107年第2次第65題","year":107,"session":2,"number":65,"question":"脊椎側彎（scoliosis）在腦性麻痺（cerebral palsy）患者的發生率為21%至76%，若以粗大動作功能評估系統（Gross Motor Function Classification System, GMFCS）來分類腦性麻痺的嚴重度，下列那種嚴重度的腦性麻痺患者有較大的機會產生脊椎側彎的問題？","options":["(A) GMFCS I","(B) GMFCS II","(C) GMFCS III","(D) GMFCS IV"],"answer":3,"image":""},{"id":"md6-107-2-66","subject":"md6","topic":"產科-一般產科","meta":"107年第2次第66題","year":107,"session":2,"number":66,"question":"下列何者不是新生兒臂神經叢受損（neonatal brachial plexus injuries）的危險因子？","options":["(A) 早產（prematurity）","(B) 肩難產（shoulder dystocia）","(C) 多產婦（multiparous mothers）","(D) 高出生體重（大於4,500公克）"],"answer":[0,2,3],"image":"","answer_note":"更正:第66題答Ａ、Ｃ、Ｄ給分"},{"id":"md6-107-2-67","subject":"md6","topic":"復健-神經復健","meta":"107年第2次第67題","year":107,"session":2,"number":67,"question":"若病人中風後，溝通能力受損，而且有明顯聽力理解障礙，覆誦困難，口語表達雖然流利，但有明顯找字困難，以致別人不了解他說的內容，他可能屬於那一種失語症？","options":["(A) 渥尼克氏失語症（Wernicke aphasia）","(B) 經皮質感覺型失語症（transcortical sensory aphasia）","(C) 布洛卡氏失語症（Broca aphasia）","(D) 經皮質運動型失語症（transcortical motor aphasia）"],"answer":0,"image":""},{"id":"md6-107-2-68","subject":"md6","topic":"復健-神經復健","meta":"107年第2次第68題","year":107,"session":2,"number":68,"question":"做吞嚥功能檢查時，請病人說 ”la—la—la” 是在檢測：","options":["(A) 口唇功能","(B) 舌頭功能","(C) 聲帶功能","(D) 軟腭功能"],"answer":1,"image":""},{"id":"md6-107-2-69","subject":"md6","topic":"復健-物理因子治療與評估","meta":"107年第2次第69題","year":107,"session":2,"number":69,"question":"下列那一種情況發生時是採用牽引療法（cervical traction）治療頸部疼痛的絕對禁忌症？","options":["(A) Spurling測試陽性","(B) Lhermitte徵兆陽性","(C) 頸椎退化性關節炎（degenerative arthritis of cervical spine）","(D) 頸神經根病變（cervical radiculopathy）"],"answer":1,"image":""},{"id":"md6-107-2-70","subject":"md6","topic":"復健-神經復健","meta":"107年第2次第70題","year":107,"session":2,"number":70,"question":"一個病人因為跌倒撞到手肘，2個月後來就診，發現在內收拇肌（adductor pollicis）及骨間肌（interossei）有萎縮現象，最有可能是那一條神經病變？","options":["(A) 正中神經","(B) 橈神經","(C) 尺神經","(D) 肌皮神經"],"answer":2,"image":""},{"id":"md6-107-2-71","subject":"md6","topic":"復健-兒童與一般復健","meta":"107年第2次第71題","year":107,"session":2,"number":71,"question":"承上題，為防止這類病人的肌肉萎縮，下列何種復健治療最合適？","options":["(A) 功能性電刺激（functional electrical stimulation）","(B) 經皮神經電刺激（transcutaneous electrical nerve stimulation）","(C) 低能量雷射治療（low level laser therapy）","(D) 超音波熱療法（ultrasound diathermy）"],"answer":0,"image":""},{"id":"md6-107-2-72","subject":"md6","topic":"復健-骨骼肌肉損傷與疾患","meta":"107年第2次第72題","year":107,"session":2,"number":72,"question":"57歲女士主訴下樓梯時，突然左腳後跟劇烈疼痛，隔天至骨科門診，接受腳後跟超音波檢查矢狀切面如圖，最可能之診斷為何？","options":["(A) Achilles tendinitis","(B) Achilles tendon fibroma","(C) Achilles tendon rupture","(D) retro-calcaneal bursitis"],"answer":2,"image":"md6-107-2-72.jpeg"},{"id":"md6-107-2-73","subject":"md6","topic":"復健-兒童與一般復健","meta":"107年第2次第73題","year":107,"session":2,"number":73,"question":"電腦斷層檢查發現廣泛頭骨增厚（diffuse skull thickening），下列何者最不會發生？","options":["(A) 肢端肥大症（acromegaly）","(B) 地中海型貧血（thalassemia）","(C) 水腦症（hydrocephalus）","(D) 小腦症（microcephaly）"],"answer":2,"image":""},{"id":"md6-107-2-74","subject":"md6","topic":"婦科-生殖道感染與先天異常","meta":"107年第2次第74題","year":107,"session":2,"number":74,"question":"28歲女性主訴發燒和下腹疼痛，電腦斷層檢查呈現如圖，箭號所指之敘述何者最正確？","options":["(A) 子宮內膜炎","(B) 輸卵管卵巢膿瘍","(C) 子宮（輸卵管）外孕","(D) 子宮頸癌"],"answer":1,"image":"md6-107-2-74.jpeg"},{"id":"md6-107-2-75","subject":"md6","topic":"婦科-腫瘤","meta":"107年第2次第75題","year":107,"session":2,"number":75,"question":"43歲女性病人，健檢時發現CA-199升高，接受腹部影像檢查，上圖為骨盆處橫切超音波，下圖為CT最可能之診斷為何？","options":["(A) 卵巢癌（ovarian cancer）","(B) 卵巢畸胎瘤（ovarian teratoma）","(C) 子宮內膜異位（endometriosis）","(D) 卵巢濾泡囊腫（ovarian follicular cyst）"],"answer":1,"image":"md6-107-2-75.jpeg"},{"id":"md6-107-2-76","subject":"md6","topic":"眼科-水晶體青光眼","meta":"107年第2次第76題","year":107,"session":2,"number":76,"question":"60歲女性病人，主訴突發左眼劇烈疼痛，視力模糊併有光暈，噁心嘔吐，瞳孔散大，血壓140/80 mmHg，照會眼科後，建議處置，下列何者最為適當：","options":["(A) 治療高血壓","(B) 靜注或口服acetazolamide","(C) 使用局部止痛劑及眼球肌肉鬆弛劑","(D) 使用局部類固醇"],"answer":1,"image":""},{"id":"md6-107-2-77","subject":"md6","topic":"產科-高危險妊娠","meta":"107年第2次第77題","year":107,"session":2,"number":77,"question":"一位25歲女性，今早開始下腹疼痛逐漸加劇，並有陰道出血的情形，來急診就診時，生命徵象如下：血壓80/40 mmHg，脈搏130次/分鐘，呼吸22次/分鐘，體溫36.5℃。過去並無特殊病史，最後一次正常月經約7週以前，下列處置何者較不適當？","options":["(A) 安排懷孕檢測","(B) 病人可以清楚表達不適，依照急救處理原則，給予O2、IV、Monitor","(C) 可能是低血容性休克，給予大量輸液，並考慮予以輸血","(D) 心電圖監視器顯示竇性頻脈（sinus tachycardia），病人血壓低有休克現象，可考慮給予100焦耳的同步電擊"],"answer":3,"image":""},{"id":"md6-107-2-78","subject":"md6","topic":"產科-高危險妊娠","meta":"107年第2次第78題","year":107,"session":2,"number":78,"question":"一位25歲懷孕22週婦女，被家人發現意識改變，送至急診時，已無呼吸、無脈搏，下列敘述及處置，何者錯誤？","options":["(A) 懷孕婦女急救時，必須予以左側躺（右側墊高），以減少子宮對下腔靜脈（inferior vena cava）的壓迫","(B) 由於懷孕的子宮會將橫膈往上推，所以心臟按摩壓胸位置在胸骨中央偏上方處","(C) 如使用電擊器去顫（Defibrillation），位置與劑量和一般成人急救是一樣的","(D) 緊急剖腹產，對於22週的胎兒有存活的機會，同時也可以提升母親救活的機會"],"answer":[0,1],"image":"","answer_note":"更正:第78題答Ａ、Ｂ給分。"},{"id":"md6-107-2-79","subject":"md6","topic":"醫學倫理與法規","meta":"107年第2次第79題","year":107,"session":2,"number":79,"question":"30歲男性病患，診斷為顱內出血，經治療後病患仍意識不清，病情不樂觀，家屬考量正統西醫療效停滯不前，故另尋其他有機會改善病況之方法。由於病家有虔誠之民間宗教信仰，在請示神明後，向醫護人員要求灌食符水，在此種情況下，下列處置何者最為適當？","options":["(A) 醫護人員應該無條件協助灌食","(B) 醫護人員應禁止家屬自行灌食","(C) 醫護人員應主動指導家屬如何灌食","(D) 醫護人員可要求家屬簽立切結書，容許家屬自行灌食"],"answer":3,"image":""},{"id":"md6-107-2-80","subject":"md6","topic":"醫學倫理與法規","meta":"107年第2次第80題","year":107,"session":2,"number":80,"question":"安排病人手術前，需要跟病人詳細說明手術的內容及其效益風險，確認病人了解及同意後，再請病人簽署手術知情同意書（informed consent），這種的作法是在確保：","options":["(A) 尊重自主原則（respect for autonomy）","(B) 行善原則（beneficence）","(C) 不傷害原則（non-maleficence）","(D) 正義原則（justice）"],"answer":0,"image":""},{"id":"md6-108-1-1","subject":"md6","topic":"麻醉-呼吸道與監視","meta":"108年第1次第1題","year":108,"session":1,"number":1,"question":"喉頭痙攣（laryngospasm）是臨床上相當重要的急性症狀，必須緊急處置。下列關於喉頭痙攣的敘述，何者錯誤？","options":["(A) 喉頭痙攣指的是聲帶（vocal cords）反射性的關閉，有時也會伴隨有假聲帶（false cords）的神經反射性閉鎖","(B) 喉頭痙攣的原因多半是因為在⿇醉深度不⾜的情況下，發⽣⼿術或咽喉局部刺激所引發的神經性過度反應","(C) 喉頭痙攣持續時間通常很短暫，只要誘發的刺激獲得緩解，喉頭痙攣⼀定可以很快⾃⾏消失痊癒","(D) 負壓肺⽔腫（negative-pressure pulmonary edema）是喉頭痙攣嚴重的併發症之⼀，除了肺間質（interstitia）有組織液滲漏外，也有可能因為⼩⾎管爆裂導致肺泡內出⾎（hemorrhage into alveoli）"],"answer":2,"image":""},{"id":"md6-108-1-2","subject":"md6","topic":"麻醉-呼吸道與監視","meta":"108年第1次第2題","year":108,"session":1,"number":2,"question":"在⼼臟無異常的病⼈置放flow-directed pulmonary artery catheter記錄肺動脈楔壓（wedge pressure）時，其肺動脈楔壓最接近下列何種⾎壓？","options":["(A) aortic diastolic pressure","(B) central venous pressure","(C) left ventricular end-diastolic pressure","(D) pulmonary artery systolic pressure"],"answer":2,"image":""},{"id":"md6-108-1-3","subject":"md6","topic":"麻醉-麻醉藥理","meta":"108年第1次第3題","year":108,"session":1,"number":3,"question":"下列何者可增加吸入性⿇醉劑之最低肺泡濃度（minimum alveolar concentration）值？","options":["(A) 年紀⼤於七⼗歲","(B) 嚴重低⾎壓","(C) 懷孕","(D) 甲狀腺亢進"],"answer":3,"image":""},{"id":"md6-108-1-4","subject":"md6","topic":"麻醉-特殊麻醉與疼痛","meta":"108年第1次第4題","year":108,"session":1,"number":4,"question":"神經阻斷術可⽤於⿇醉與⽌痛作⽤，下列有關神經阻斷術的敘述，何者錯誤？","options":["(A) 神經位置的確定可⽤超⾳波、神經刺激器或依病⼈感覺","(B) 病患不同意為絶對禁忌之⼀","(C) 使⽤的局部⿇醉藥不會造成全⾝毒性","(D) 使⽤的針有可能傷到神經"],"answer":2,"image":""},{"id":"md6-108-1-5","subject":"md6","topic":"麻醉-呼吸道與監視","meta":"108年第1次第5題","year":108,"session":1,"number":5,"question":"下列有關老⼈的⿇醉敘述，何者錯誤？","options":["(A) 術前評估應綜合考量許多風險因⼦，若僅考慮年齡本⾝，不考慮其他風險預測因⼦，則年齡為⼀次要因⼦ （minor factor）","(B) 老⼈的⿇醉藥蛋⽩結合度下降，故⿇醉藥效⼒減少","(C) ⽬前並無證據顯⽰在⼿術週期（perioperative），老⼈實施半⾝⿇醉比全⾝⿇醉發⽣的併發症較少","(D) 術後認知功能障礙（postoperative cognitive dysfunction）發⽣率在老⼈較⾼"],"answer":1,"image":""},{"id":"md6-108-1-6","subject":"md6","topic":"麻醉-特殊麻醉與疼痛","meta":"108年第1次第6題","year":108,"session":1,"number":6,"question":"Allodynia是形容疼痛的那⼀種感覺？","options":["(A) 沒有刺激下，也會感到異常感覺","(B) 對於無害（nonnoxious）的刺激，也會感覺到疼痛","(C) 對於有害（noxious）的刺激，感覺越來越強烈","(D) 對於有害（noxious）的刺激，感覺越來越減弱"],"answer":1,"image":""},{"id":"md6-108-1-7","subject":"md6","topic":"麻醉-特殊麻醉與疼痛","meta":"108年第1次第7題","year":108,"session":1,"number":7,"question":"使⽤病⼈⾃控式⽌痛術（patient-controlled analgesia）控制⼿術後疼痛和傳統肌⾁注射比較，其優點包括下列各項，除了：","options":["(A) 提供較佳的⽌痛效果","(B) 病患滿意度較⾼","(C) 任何病患皆可使⽤","(D) 病⼈可依疼痛強度調整⽌痛藥劑量"],"answer":2,"image":""},{"id":"md6-108-1-8","subject":"md6","topic":"麻醉-呼吸道與監視","meta":"108年第1次第8題","year":108,"session":1,"number":8,"question":"急性呼吸窘迫症候群（acute respiratory distress syndrome；ARDS）以呼吸機進⾏呼吸⽀持治療過程，理想潮氣量（tidal volume）之設定建議為多少ml/kg？","options":["(A) 6","(B) 10","(C) 12","(D) 15"],"answer":0,"image":""},{"id":"md6-108-1-9","subject":"md6","topic":"眼科-視網膜葡萄膜","meta":"108年第1次第9題","year":108,"session":1,"number":9,"question":"下列有關⾼度近視造成之視網膜病變的敘述，何者錯誤？","options":["(A) 視網膜後極部漆裂紋（lacquer cracks）","(B) 視網膜後極部葡萄腫（staphyloma）","(C) 周邊視網膜格⼦狀變性（lattice degeneration）","(D) 視網膜⾊素上⽪肥厚（hypertrophy of the retinal pigment epithelium）"],"answer":3,"image":""},{"id":"md6-108-1-10","subject":"md6","topic":"眼科-角膜結膜眼瞼眼窩","meta":"108年第1次第10題","year":108,"session":1,"number":10,"question":"在因全⾝性免疫疾病造成的⾓膜邊緣潰瘍（marginal ulcer）病患中，最常⾒的全⾝性免疫疾病是：","options":["(A) 全⾝性紅斑性狼瘡（systemic lupus erythematosus）","(B) 類風濕性關節炎（rheumatoid arthritis）","(C) 結節性多動脈炎（polyarteritis nodosa）","(D) Wegener⽒⾁芽腫（Wegener granulomatosis）"],"answer":1,"image":""},{"id":"md6-108-1-11","subject":"md6","topic":"眼科-水晶體青光眼","meta":"108年第1次第11題","year":108,"session":1,"number":11,"question":"周邊雷射虹膜穿孔術（peripheral laser iridotomy）主要⽤來治療何種青光眼（glaucoma）？","options":["(A) 隅⾓開放性青光眼（open angle glaucoma）","(B) 隅⾓閉鎖性青光眼（angle closure glaucoma）","(C) 正常眼壓性青光眼（normal tension glaucoma）","(D) ⾎管增⽣性青光眼（neovascular glaucoma）"],"answer":1,"image":""},{"id":"md6-108-1-12","subject":"md6","topic":"眼科-水晶體青光眼","meta":"108年第1次第12題","year":108,"session":1,"number":12,"question":"下列何種視神經盤凹杯與視神經盤直徑比例（cup-disk ratio），比較不會被懷疑有青光眼：","options":["(A) 0.2","(B) 0.5","(C) 0.8","(D) 兩眼視神經盤凹杯與視神經盤直徑比例（cup-disk ratio）極不對稱"],"answer":0,"image":""},{"id":"md6-108-1-13","subject":"md6","topic":"眼科-屈光斜弱視","meta":"108年第1次第13題","year":108,"session":1,"number":13,"question":"眼球欲往內下（nasal lower）⽅向看時，須靠下列何組眼外肌共同作⽤？","options":["(A) 內直肌（medial rectus muscle）和下直肌（inferior rectus muscle）","(B) 內直肌（meeial rectus muscle）和下斜肌（inferior oblique muscle）","(C) 內直肌（medial rectus muscle）和上斜肌（superior obique muscle）","(D) 內直肌（medial rectus muscle）和上直肌（superior rectus muscle）"],"answer":2,"image":""},{"id":"md6-108-1-14","subject":"md6","topic":"眼科-屈光斜弱視","meta":"108年第1次第14題","year":108,"session":1,"number":14,"question":"做視⼒檢測時，只能看到藍道爾（Landolt）⽒視⼒表上的0.4視標，表⽰：","options":["(A) 要向前⾛到距離視⼒表四公尺處，才能看到1.0的視標","(B) 對應之最⼩視⾓（minimal angle of resolution）為五分之⼆分⾓（minute of arc）","(C) 該眼只剩下40%的視覺效能（visual efficiency）","(D) 相當於史奈倫（Snellen）⽒視⼒表檢查的20/50視⼒"],"answer":3,"image":""},{"id":"md6-108-1-15","subject":"md6","topic":"眼科-角膜結膜眼瞼眼窩","meta":"108年第1次第15題","year":108,"session":1,"number":15,"question":"下列關於淚液（tear）的敘述，何者錯誤？","options":["(A) 淚液層由外（空氣）到內（眼表⾯）可分為油脂層（lipid layer）、⽔液層（aqueous layer）、黏液層（mucous layer）","(B) 油脂層主要由眼瞼板的瞼板腺（meibomian gland）分泌","(C) 黏液層的作⽤為避免⽔分的蒸散","(D) ⽔液層的基礎分泌量在睡眠時最少"],"answer":2,"image":""},{"id":"md6-108-1-16","subject":"md6","topic":"眼科-角膜結膜眼瞼眼窩","meta":"108年第1次第16題","year":108,"session":1,"number":16,"question":"關於眼瞼惡性腫瘤的敘述，下列何者錯誤？","options":["(A) 基底細胞癌（basal cell carcinoma）發⽣率最⾼","(B) 鱗狀細胞癌（squamous cell carcinoma）⼀般預後較基底細胞癌差","(C) ⽪脂腺癌（sebaceous gland carcinoma）臨床上易被誤診為慢性眼瞼炎或霰粒腫（chalazion）","(D) ⽪脂腺癌⼀般好發在下眼瞼"],"answer":3,"image":""},{"id":"md6-108-1-17","subject":"md6","topic":"耳科學","meta":"108年第1次第17題","year":108,"session":1,"number":17,"question":"⼈⼯⽿蝸（cochlear implants）是利⽤電極，刺激極重度聽損病⼈內⽿中之何種細胞？","options":["(A) 外⽑細胞（outer hair cells）","(B) 內⽑細胞（inner hair cells）","(C) ⾎管紋細胞（striae vascularis cells）","(D) 螺旋神經節細胞（spiral ganglion cells）"],"answer":3,"image":""},{"id":"md6-108-1-18","subject":"md6","topic":"耳科學","meta":"108年第1次第18題","year":108,"session":1,"number":18,"question":"根據美國對兒童積液性中⽿炎（otitis media with effusion）的處理指引，在無併發症的病例，積液性中⽿炎病⼈在診斷後應密切觀察多久，才做進⼀步的聽⼒測試或⼿術治療？","options":["(A) 1個⽉","(B) 2個⽉","(C) 3個⽉","(D) 6個⽉"],"answer":2,"image":""},{"id":"md6-108-1-19","subject":"md6","topic":"喉科學與頭頸腫瘤","meta":"108年第1次第19題","year":108,"session":1,"number":19,"question":"聲帶結節最容易發⽣於下列何處？","options":["(A) 聲帶前聯合處（anterior commissure）","(B) 聲帶之前、中三分之⼀交界處","(C) 聲帶之後聯合處（posterior commissure）","(D) 聲帶之後三分之⼀"],"answer":1,"image":""},{"id":"md6-108-1-20","subject":"md6","topic":"喉科學與頭頸腫瘤","meta":"108年第1次第20題","year":108,"session":1,"number":20,"question":"有關⼝腔癌⼿術後接受輔助性放化療（chemoradiation）之敘述，下列何者錯誤？","options":["(A) 輔助性放化療最好在術後超過6週才開始，避免影響傷⼝癒合","(B) 有淋巴結膜外擴散之病⼈是輔助性放化療的適應症","(C) 切緣（section margin）有腫瘤細胞，輔助性放化療仍有助於病情的控制","(D) 第四期病⼈⼿術即使切除完整，也建議給予輔助性放化療"],"answer":0,"image":""},{"id":"md6-108-1-21","subject":"md6","topic":"喉科學與頭頸腫瘤","meta":"108年第1次第21題","year":108,"session":1,"number":21,"question":"3個⽉⼤⾜⽉產嬰兒，出⽣3週後家⻑注意到呼吸不順有雜⾳，經⽿⿐喉科醫師評估後安排喉內視鏡檢查，結果如下圖，下列敘述何者正確？","options":["(A) 嬰兒為女性之機會較⾼","(B) 嬰兒之症狀於6個⽉內多可逐漸改善","(C) 嬰兒於平躺時症狀較輕微","(D) 嬰兒於喝奶時症狀較嚴重"],"answer":3,"image":"md6-108-1-21.jpeg"},{"id":"md6-108-1-22","subject":"md6","topic":"喉科學與頭頸腫瘤","meta":"108年第1次第22題","year":108,"session":1,"number":22,"question":"⿐咽癌的⾎液測試中，下列何者⽬前被認為準確度最好？","options":["(A) EBV anti-VCA IgG","(B) EBV anti-VCA IgA","(C) EBV anti-EA IgA","(D) Serum/Plasma free EBV DNA copies"],"answer":3,"image":""},{"id":"md6-108-1-23","subject":"md6","topic":"鼻科學","meta":"108年第1次第23題","year":108,"session":1,"number":23,"question":"⼀位57歲男性病⼈因經常性流⿐⾎⾄急診處，無⾼⾎壓、糖尿病等病史，但有多次⿊便及腸胃道出⾎，⾎液檢查⾎紅素偏低，其它凝⾎因⼦、⾎⼩板等均正常，⽿⿐喉理學檢查發現⿐與舌部有多處似⾎管擴張之紅點。此病⼈之最可能診斷為何？","options":["(A) ⿐過敏","(B) Osler-Weber-Rendu syndrome","(C) Sipple’s syndrome","(D) ⿐咽癌"],"answer":1,"image":""},{"id":"md6-108-1-24","subject":"md6","topic":"鼻科學","meta":"108年第1次第24題","year":108,"session":1,"number":24,"question":"承上題，對此經常、反覆性⿐出⾎之病⼈，⿐部之處置，下列何者最佳？","options":["(A) ⾎管結紮","(B) ⾎管攝影及栓塞","(C) 下⿐甲切除術","(D) ⽪瓣移植⼿術"],"answer":3,"image":""},{"id":"md6-108-1-25","subject":"md6","topic":"產科-一般產科","meta":"108年第1次第25題","year":108,"session":1,"number":25,"question":"下列那個妊娠週數，最易觀察到胎兒有濃稠胎糞（meconium）排出的情況？","options":["(A) ⼩於24週","(B) ⼤於42週","(C) ⼩於37週","(D) 介於38～41週之間"],"answer":1,"image":""},{"id":"md6-108-1-26","subject":"md6","topic":"產科-一般產科","meta":"108年第1次第26題","year":108,"session":1,"number":26,"question":"26歲孕婦，G5P3A1，妊娠32週，接受超⾳波檢查，結果如圖所⽰，下列何者為最可能的診斷？","options":["(A) anencephaly","(B) Down syndrome","(C) cleft lip","(D) duodenal atresia"],"answer":2,"image":"md6-108-1-26.jpeg"},{"id":"md6-108-1-27","subject":"md6","topic":"產科-一般產科","meta":"108年第1次第27題","year":108,"session":1,"number":27,"question":"孕婦在妊娠第⼀期腹痛⾄⾨診，經檢查後發現⼦宮頸已經開了3公分，此時最可能的診斷是：","options":["(A) 不完全流產（incomplete abortion）","(B) 無法避免的流產（inevitable abortion）","(C) 過期流產（missed abortion）","(D) 敗⾎性流產（septic abortion）"],"answer":1,"image":""},{"id":"md6-108-1-28","subject":"md6","topic":"婦科-手術學與診斷技術","meta":"108年第1次第28題","year":108,"session":1,"number":28,"question":"在腹腔鏡⼿術置入側邊套管（trocar）時，常因為套管位置太接近⾝體中線⽽傷到⾎管，⽽造成腹壁出⾎和 ⾎腫，則最有可能傷到的⾎管是：","options":["(A) 表淺迴旋動脈（superficial circumflex artery）","(B) 胃左動脈（left gastric artery）","(C) 表淺外陰部動脈（superficial external pudendal artery）","(D) 下腹壁動脈（inferior epigastric artery）"],"answer":3,"image":""},{"id":"md6-108-1-29","subject":"md6","topic":"婦科-尿失禁與骨盆腔脫垂","meta":"108年第1次第29題","year":108,"session":1,"number":29,"question":"32歲未婚年輕女性，因⼀年多來頻尿、夜尿、尿急及漲尿後下腹痛所困擾⽽就醫。理學檢查並無⼦宮、膀胱脫垂之現象，尿液分析無菌尿或尿路感染之情形。解尿⽇記發現⽩天解尿次數超過⼗次以上，晚上夜尿（nocturia）情形超過3⾄5次以上。膀胱尿動⼒學檢查無逼尿肌不穩定（detrusor overactivity）之情形，但是初次解尿感覺（first desire to void）容積為86 c.c.、膀胱最⼤容積（maximum bladder capacity）為180 c.c.。於靜脈注射⿇醉下接受膀胱鏡檢查，膀胱在灌注400 c.c.食鹽⽔5分鐘後，開始引流膀胱內食鹽⽔，膀胱鏡下呈現下圖之變化（其變化順序依次為a→b→c→d），此患者最適合之診斷為：","options":["(A) 膀胱結⽯（bladder stone）","(B) 膀胱腫瘤（bladder tumor）","(C) 間質性膀胱炎（interstitial cystitis）","(D) 膀胱憩室（bladder diverticulum）"],"answer":2,"image":"md6-108-1-29.jpeg"},{"id":"md6-108-1-30","subject":"md6","topic":"婦科-尿失禁與骨盆腔脫垂","meta":"108年第1次第30題","year":108,"session":1,"number":30,"question":"若將骨盆底部的levator ani muscle比喻為吊床（hammock），下列何種解剖構造所扮演的功能類似吊床兩端的橫⽊（吊床兩端主要的附著構造）？","options":["(A) arcus tendineus levator ani（ATLA）","(B) arcus tendineus fascia pelvis（ATFP）","(C) obturator internus muscle","(D) endopelvic fasciae"],"answer":0,"image":""},{"id":"md6-108-1-31","subject":"md6","topic":"婦科-生殖內分泌","meta":"108年第1次第31題","year":108,"session":1,"number":31,"question":"20歲女性，第⼆性徵發育正常，有性經驗，來⾨診求診，主訴⽉經週期不規則，上次⽉經是兩個⽉前，最先安排什麼檢驗或檢查，可以得到最關鍵的訊息？","options":["(A) 尿液懷孕試驗","(B) ⾎液荷爾蒙檢查","(C) 骨盆腔超⾳波檢查","(D) ⼦宮鏡"],"answer":0,"image":""},{"id":"md6-108-1-32","subject":"md6","topic":"婦科-生殖內分泌","meta":"108年第1次第32題","year":108,"session":1,"number":32,"question":"腦下垂體泌乳激素瘤（prolactinoma）1.8公分併視野缺損，下列敘述何者最正確？","options":["(A) 藥物治療⼀定有效","(B) ⼿術切除後不會再發","(C) 術後須定期追蹤","(D) ⼿術後遺症為diabetes mellitus"],"answer":2,"image":""},{"id":"md6-108-1-33","subject":"md6","topic":"婦科-腫瘤","meta":"108年第1次第33題","year":108,"session":1,"number":33,"question":"35歲女性，下列何種情況比較有可能得⼦宮內膜癌？","options":["(A) 使⽤⼝服避孕藥的性⼯作者","(B) 有多囊性卵巢症及糖尿病的已婚婦女","(C) 規則⽉經的運動選⼿","(D) 裝有⼦宮內避孕器的婦女"],"answer":1,"image":""},{"id":"md6-108-1-34","subject":"md6","topic":"婦科-腫瘤","meta":"108年第1次第34題","year":108,"session":1,"number":34,"question":"下列何者為雙側發⽣機率最⾼的卵巢⽣殖細胞腫瘤？","options":["(A) Dysgerminoma","(B) Choriocarcinoma","(C) Yolk sac tumor","(D) Embryonal carcinoma"],"answer":0,"image":""},{"id":"md6-108-1-35","subject":"md6","topic":"產科-一般產科","meta":"108年第1次第35題","year":108,"session":1,"number":35,"question":"關於懷孕時期的敘述，下列何者正確？","options":["(A) ⾎⾊素（hemoglobin）上升","(B) 到⾜⽉時總⾎量上升40%","(C) 紅⾎球體積（red cell volume）⼀直到懷孕20週後才開始上升","(D) ⾎比容積上升是由於紅⾎球體積上升多過於⾎漿體積⽽造成"],"answer":1,"image":""},{"id":"md6-108-1-36","subject":"md6","topic":"婦科-手術學與診斷技術","meta":"108年第1次第36題","year":108,"session":1,"number":36,"question":"⼦宮外孕病患選擇內科單⼀化學藥物methotrexate（葉酸拮抗劑）治療後，第4天⾄第7天抽⾎檢驗⾎清⼈類絨⽑膜性腺激素值（human chorionic gonadotropin），根據美國⽣殖醫學會2013年建議，若下降幅度沒有達到多少百分比，可以考慮接受追加第⼆劑methotrexate治療？","options":["(A) 45%","(B) 35%","(C) 25%","(D) 15%"],"answer":3,"image":""},{"id":"md6-108-1-37","subject":"md6","topic":"產科-高危險妊娠","meta":"108年第1次第37題","year":108,"session":1,"number":37,"question":"有關孕婦併有主動脈狹窄（aortic stenosis）的敘述，下列何者錯誤？","options":["(A) 懷孕時因為⼼⾎管的前負荷（preload）下降，孕婦症狀會變嚴重","(B) 對於沒有症狀的孕婦，不需要做任何治療","(C) 對於有症狀的孕婦，建議以氣球擴張術（balloon valvotomy）治療","(D) 若是嘗試陰道⽣產時，待產時建議注意輸液量不能過少，⽣產時建議使⽤產鉗或真空吸幫助⽣產"],"answer":2,"image":""},{"id":"md6-108-1-38","subject":"md6","topic":"產科-一般產科","meta":"108年第1次第38題","year":108,"session":1,"number":38,"question":"第⼀孕期唐⽒症及其他非整倍體（aneuploidy）染⾊體異常，最常⽤的篩檢策略為超⾳波檢查及⺟⾎⾎清分析，下列檢查何者不屬之？","options":["(A) 頸部透明帶厚度（nuchal translucency）檢測","(B) ⺟⾎胎兒甲型蛋⽩（maternal serum AFP）","(C) ⼈類絨⽑膜性腺激素（human chorionic gonadotropin）","(D) 懷孕相關蛋⽩A（pegnancy-associated protein A）"],"answer":1,"image":""},{"id":"md6-108-1-39","subject":"md6","topic":"產科-高危險妊娠","meta":"108年第1次第39題","year":108,"session":1,"number":39,"question":"29歲孕婦，妊娠11週，B型肝炎帶原者篩檢結果為HBsAg（+），HBeAg（+）；妊娠24週B型肝炎病毒8（HBV）DNA檢驗結果為10 copies/mL。孕婦於妊娠28週開始⼝服抗HBV藥物Tenofovir治療⾄妊娠38週，經陰道⾃然分娩出3,480公克女嬰。為預防嬰兒感染B型肝炎的最適當處置為：","options":["(A) 新⽣兒出⽣後立即給與B型肝炎免疫球蛋⽩治療，同時安排B型肝炎疫苗預防接種","(B) 新⽣兒出⽣後立即給與B型肝炎免疫球蛋⽩治療，不必安排B型肝炎疫苗預防接種","(C) 新⽣兒出⽣後不必給與B型肝炎免疫球蛋⽩治療，只需安排B型肝炎疫苗預防接種","(D) 新⽣兒出⽣後不必給與B型肝炎免疫球蛋⽩治療，也不必安排B型肝炎疫苗預防接種"],"answer":0,"image":""},{"id":"md6-108-1-40","subject":"md6","topic":"產科-高危險妊娠","meta":"108年第1次第40題","year":108,"session":1,"number":40,"question":"下列那⼀種狀況發⽣胎盤早期剝離（plancental abruption）的風險最⾼？","options":["(A) 前⼀胎發⽣胎盤早期剝離","(B) 合併⼦癇前症（preeclampsia）","(C) 絨⽑膜⽺膜炎（chorioamnionitis）","(D) 胎膜早破（premature rupture of membranes）"],"answer":0,"image":""},{"id":"md6-108-1-41","subject":"md6","topic":"婦科-尿失禁與骨盆腔脫垂","meta":"108年第1次第41題","year":108,"session":1,"number":41,"question":"棉墊試驗（pad test）常被廣泛應⽤於以病患主導的研究，來了解尿失禁治療成效，在24⼩時的棉墊試驗（24-hour pad test）棉墊重量增加⼤於多少公克以上才算是異常？","options":["(A) 0","(B) 1","(C) 2","(D) 4"],"answer":3,"image":""},{"id":"md6-108-1-42","subject":"md6","topic":"婦科-尿失禁與骨盆腔脫垂","meta":"108年第1次第42題","year":108,"session":1,"number":42,"question":"為了解患者主觀敘述之頻尿是否為真實，須採⽤下列何種測試或⼯具來作為評估，是否有頻尿的證據？","options":["(A) 膀胱紀錄／排尿⽇記（bladder chart/ voiding diary）","(B) ⼀⼩時的護墊試驗（1-hour pad test）","(C) 填充期膀胱內壓測量法（filling phase cystometry）","(D) 無壓⼒尿流測量法（free uroflowmetry）"],"answer":0,"image":""},{"id":"md6-108-1-43","subject":"md6","topic":"婦科-尿失禁與骨盆腔脫垂","meta":"108年第1次第43題","year":108,"session":1,"number":43,"question":"對於正常女性尿動⼒學檢查數值，下列何者錯誤？","options":["(A) 殘餘尿量（residual urine）< 50 mL","(B) 初感尿意（first desire to void）發⽣介於150 and 250 mL灌注液量","(C) 強烈尿意（strong desire to void）發⽣在⼩於250 mL灌注液量","(D) 膀胱容量（cystometric capacity）介於400 and 600 mL灌注液量"],"answer":2,"image":""},{"id":"md6-108-1-44","subject":"md6","topic":"婦科-腫瘤","meta":"108年第1次第44題","year":108,"session":1,"number":44,"question":"有關⼦宮內膜異位症的敘述，下列何者錯誤？","options":["(A) 可能引起骨盆疼痛或不孕","(B) 診斷主要靠組織切片，切片若未發現⼦宮內膜異位組織，也不能排除⼦宮內膜異位症","(C) 美國⽣殖醫學會（ASRM）將⼦宮內膜異位，依疼痛的嚴重程度分為第⼀期到第四期","(D) ⼦宮內膜異位症與卵巢癌有關"],"answer":2,"image":""},{"id":"md6-108-1-45","subject":"md6","topic":"婦科-腫瘤","meta":"108年第1次第45題","year":108,"session":1,"number":45,"question":"51歲婦女，因為偶發性右腰痛（colic pain），到泌尿科⾨診接受腎盂輸尿管的檢查，發現在輸尿管中段有 ⼀顯影劑缺損（filling defect），造成右邊輸尿管⽔腫以及輕微腎⽔腫。此時醫院廣播，⿎勵四癌篩檢的衛教，所以這位婦女也接受⼦宮頸抹片的檢查。但是⼀週後，抹片報告為鱗狀上⽪癌（squamous cell carcinoma）。這位婦女接下來的，應優先考慮下列何步驟？","options":["(A) 抹片可能是偽陽性，可以不管，3個⽉後再做⼀次抹片或⼈類乳突病毒檢查","(B) 初期的⼦宮頸癌，要接受全⼦宮根除性⼿術治療","(C) 晚期的⼦宮頸癌，建議去放射腫瘤科接受化療同步的放射線治療","(D) 接受陰道鏡輔助的⼦宮頸切片檢查或直接⼦宮頸切片檢查"],"answer":3,"image":""},{"id":"md6-108-1-46","subject":"md6","topic":"婦科-腫瘤","meta":"108年第1次第46題","year":108,"session":1,"number":46,"question":"有關混合性卵巢惡性⽣殖細胞瘤（mixed germ cell malignancies of the ovary），是兩種或多種⽣殖細胞瘤（germ cell tumor）的混合，最常⾒那兩種型態的組合？","options":["(A) 無性胚胎瘤（dysgerminoma）及卵巢內胚層竇瘤（endodermal sinus tumor）","(B) 無性胚胎瘤（dysgerminoma）及卵巢多胚瘤（polyembryoma）","(C) 卵巢多胚瘤（polyembryoma）及不成熟畸胎瘤（immature teratoma）","(D) 卵巢內胚層竇瘤（endodermal sinus tumor）及不成熟畸胎瘤（immature teratoma）"],"answer":0,"image":""},{"id":"md6-108-1-47","subject":"md6","topic":"婦科-腫瘤","meta":"108年第1次第47題","year":108,"session":1,"number":47,"question":"關於導致⼦宮內膜過度增⽣之敘述，下列何者最不可能？","options":["(A) ⻑期無排卵（chronic anovulation）","(B) ⻑期服⽤黃體素","(C) ⻑期服⽤tamoxifen","(D) 肥胖且無⽉經（amenorrhea）的婦女"],"answer":1,"image":""},{"id":"md6-108-1-48","subject":"md6","topic":"婦科-生殖內分泌","meta":"108年第1次第48題","year":108,"session":1,"number":48,"question":"關於性類固醇激素對⼦宮內膜作⽤之敘述，下列何者錯誤？","options":["(A) 雌激素會刺激⼦宮內膜基質細胞（stroma cells）的增⽣","(B) 黃體素會抑制⼦宮內膜基質細胞（stroma cells）的增⽣","(C) 雌激素會刺激⼦宮內膜中⾎管（blood vessels）與腺體（glands）的增⽣","(D) 黃體素會抑制⼦宮內膜中⾎管（blood vessels）與腺體（glands）的增⽣"],"answer":3,"image":""},{"id":"md6-108-1-49","subject":"md6","topic":"婦科-生殖內分泌","meta":"108年第1次第49題","year":108,"session":1,"number":49,"question":"關於多囊性卵巢症候群（polycystic ovary syndrome, PCOS）的治療敘述，下列何者錯誤？","options":["(A) 使⽤抗雄性激素藥物來治療痤瘡（青春痘，acne）","(B) 可以單獨使⽤胰島素敏感劑（如：Metformin）來刺激排卵","(C) 治療以改變⽣活型態（減肥減重）（=飲食控制+運動）為主，臨床症狀之治療為輔","(D) 以clomiphene citrate來治療不排卵"],"answer":1,"image":""},{"id":"md6-108-1-50","subject":"md6","topic":"婦科-生殖內分泌","meta":"108年第1次第50題","year":108,"session":1,"number":50,"question":"有關抗穆勒⽒賀爾蒙（antimüllerian hormone, AMH）敘述，下列何者錯誤？","options":["(A) ⽤來評估婦女卵⼦庫存量和卵巢刺激反應的檢測⼯具之⼀","(B) 是由較⼩的卵泡例如竇前卵泡或竇卵泡（preantral and small antral follicles）所分泌","(C) AMH的值不受到性腺激素的影響（gonadotropin-independent）","(D) AMH值無法⽤來預測卵巢對於FSH刺激的反應"],"answer":3,"image":""},{"id":"md6-108-1-51","subject":"md6","topic":"婦科-生殖內分泌","meta":"108年第1次第51題","year":108,"session":1,"number":51,"question":"有關評估卵⼦庫存量（ovarian reserve）下降的結果，下列何者正確？","options":["(A) 濾泡刺激素（follicle stimulating hormone, FSH）基礎值下降","(B) 女性的卵⼦庫存量與年齡無關","(C) 抗穆勒⽒賀爾蒙（antimüllerian hormone, AMH）下降","(D) 超⾳波測量竇卵泡計數量（antral follicle count, AFC）上升"],"answer":2,"image":""},{"id":"md6-108-1-52","subject":"md6","topic":"婦科-生殖內分泌","meta":"108年第1次第52題","year":108,"session":1,"number":52,"question":"施⾏⼈⼯輔助⽣殖技術（ART）使⽤促性腺激素藥物刺激後，如何避免卵巢過度刺激症候群（OHSS）的發 ⽣，下列何者正確？","options":["(A) 使⽤⼈類絨⽑促性腺激素（hCG）取代以黃體⽣成激素（LH）刺激排卵","(B) 使⽤促性腺激素釋放激素促進劑（agonist）療程時，以促性腺激素釋放激素拮抗劑（antagonist）刺激排卵","(C) 追蹤測量發現雌激素值過⾼時，不考慮完全停⽌促性腺激素藥物刺激","(D) 取卵後使⽤Cabergoline可能可以抑制⾎管內⽪⽣⻑因⼦（VEGF）產⽣"],"answer":3,"image":""},{"id":"md6-108-1-53","subject":"md6","topic":"產科-高危險妊娠","meta":"108年第1次第53題","year":108,"session":1,"number":53,"question":"曉晴23歲，從⼩體⼒就比較差，爬樓梯很容易喘，也比較容易⽣病感冒，不過不影響⽇常⽣活。1個⽉前⾃ ⼰驗出有懷孕，最近1個⽉，常感到頭暈、噁⼼、嘔吐，有時還會感到胸悶及⼼悸，所以⾄婦產科產檢。曉晴⾝⾼158公分，體重42公⽄，⾎壓112/76 mmHg，⼼跳速率每分鐘92下，超⾳波檢查看到⼦宮內有⼀個正常胚囊，可看到⼀個胚胎頭臀⻑（CRL）為2.1公分。關於曉晴的情況，下列何者錯誤？","options":["(A) 依據胚胎頭臀⻑2.1公分來判斷，曉晴⽬前懷孕（胚胎）週數約9週","(B) ⼀般正常懷孕時，在懷孕前8週，⼼⾎管系統就會開始產⽣明顯的變化，⼼輸出量（cardiac output）會上升，周邊⾎管阻⼒（systemic vascular resistance）會下降，⼼跳（heart rate）會加快","(C) 正常懷孕從受孕到產後的這段期間，側躺休息時的⼼輸出量最⼤的時期在妊娠週數第28⾄32週間","(D) ⼀般妊娠20週後，孕婦側躺時，⼼輸出量及⼼臟打出的容積量（stroke volume）比坐著時⾼，但每分鐘⼼ 跳數則比坐著時低。此外，懷孕時左側躺的收縮壓、舒張壓均較仰臥時低"],"answer":[0,1,2,3],"image":"","answer_note":"送分:第53題一律給分。 (原公告答案 A)"},{"id":"md6-108-1-54","subject":"md6","topic":"產科-高危險妊娠","meta":"108年第1次第54題","year":108,"session":1,"number":54,"question":"承上題，產科醫師發現她懷孕前，如果樓梯爬3層就會喘，不過⼀般⽣活作息並不會造成困擾。但懷孕後，這些情況變的更厲害，有時⾛路久⼀點就會喘，需要停下來休息。檢查曉晴的眼結膜（conjunctiva）是粉紅 ⾊的，沒有貧⾎的跡象，聽診發現有⼼雜⾳，產科醫師懷疑有⼼臟⽅⾯的問題，於是安排⼼臟超⾳波，發現曉晴有⼀個⼼室中膈缺損約1.6平⽅公分。下列給曉晴的諮詢，何者錯誤？","options":["(A) 根據紐約⼼臟協會（NYHA）對⼼臟功能的定義，曉晴懷孕前是屬於第⼆級（functional class II），但懷孕後已惡化為第三級（functional class III）","(B) ⼼室中膈缺損是⼀種先天性⼼臟病，這種是結構的異常並不會遺傳給胎兒","(C) ⼤的⼼室中膈缺損可能會進展為左⼼室衰竭及肺動脈⾼壓，當肺動脈阻⼒（pulmonary vascular resistance）⼤於系統性⾎管阻⼒（systemic vascular resistance），會造成右側到左側的分流（right to left shunt），即Eisenmenger症候群，此時⺟親的死亡率會⾼達30～50%","(D) 沒有修補的⼼室中膈缺損會有感染性⼼內膜炎（infective endocariditis）的風險，在懷疑有菌⾎症時，建議給預防性抗⽣素"],"answer":1,"image":""},{"id":"md6-108-1-55","subject":"md6","topic":"復健-神經復健","meta":"108年第1次第55題","year":108,"session":1,"number":55,"question":"使⽤以下何種食物材質刺激最易促進吞嚥反射？","options":["(A) 較冰的食物","(B) 較甜的食物","(C) 溫度適中的食物","(D) 較為堅硬的食物"],"answer":0,"image":""},{"id":"md6-108-1-56","subject":"md6","topic":"復健-神經復健","meta":"108年第1次第56題","year":108,"session":1,"number":56,"question":"夏柯⾺利疾病（Charcot-Marie-Tooth disease）所產⽣周邊神經病變，容易造成下肢的變形，其中那⼀種神經最容易被侵犯？","options":["(A) 腓神經（peroneal nerve）","(B) 脛骨神經（tibial nerve）","(C) 股神經（femoral nerve）","(D) 隱神經（saphenous nerve）"],"answer":0,"image":""},{"id":"md6-108-1-57","subject":"md6","topic":"復健-神經復健","meta":"108年第1次第57題","year":108,"session":1,"number":57,"question":"脊髓損傷的病⼈可採⽤電極取精之⽅式協助取得精液，電極要置於何處？","options":["(A) 腹部","(B) 會陰","(C) 直腸","(D) 陰莖"],"answer":2,"image":""},{"id":"md6-108-1-58","subject":"md6","topic":"復健-神經復健","meta":"108年第1次第58題","year":108,"session":1,"number":58,"question":"有關脊髓損傷併四肢癱瘓神經功能恢復的敘述，下列何者錯誤？","options":["(A) 上肢功能之恢復多發⽣於受傷後6～9個⽉內","(B) 上肢功能最快之恢復多發⽣於受傷後3個⽉內","(C) 受傷初期之肌⼒與往後之恢復無關","(D) 愈早恢復者，預後愈佳"],"answer":2,"image":""},{"id":"md6-108-1-59","subject":"md6","topic":"復健-神經復健","meta":"108年第1次第59題","year":108,"session":1,"number":59,"question":"下列何者是分辨肌⾁病變與神經病變最有⽤的電學診斷⽅法？","options":["(A) 神經傳導檢查（nerve conduction study）","(B) 肌電圖檢查（EMG study）","(C) 連續電刺激神經檢查（repetitive nerve stimulation test）","(D) 肌⾁激發電刺激檢查（muscle excitability test）"],"answer":1,"image":""},{"id":"md6-108-1-60","subject":"md6","topic":"復健-神經復健","meta":"108年第1次第60題","year":108,"session":1,"number":60,"question":"下列何者是治療多發性肌炎（polymyositis）最常使⽤的藥物？","options":["(A) 傳統改善疾病之抗風濕藥物（disease-modifying anti-rheumatic drug）","(B) ⽣物製劑（biologic agent）","(C) ⽪質類固醇（glucocorticoid）","(D) 非類固醇抗炎⽌痛劑（non-steroidal anti-inflammatory drug）"],"answer":2,"image":""},{"id":"md6-108-1-61","subject":"md6","topic":"復健-截肢與義肢輔具","meta":"108年第1次第61題","year":108,"session":1,"number":61,"question":"助⾏器（ambulation aids）是常⾒的裝具，有關助⾏器的敘述下列何者錯誤？","options":["(A) 使⽤助⾏器的⽬的包括改善使⽤者平衡能⼒，重新分配下肢承重區域，以及減少下肢的疼痛","(B) 助⾏器只可提供⼒量的⽀撐，無法提供感覺的回饋","(C) 要選擇使⽤那⼀種助⾏器，決定於使⽤者所需要的平衡能⼒和承重協助","(D) 可以把助⾏器當成上肢的延伸"],"answer":1,"image":""},{"id":"md6-108-1-62","subject":"md6","topic":"復健-骨骼肌肉損傷與疾患","meta":"108年第1次第62題","year":108,"session":1,"number":62,"question":"臨床上對於關節炎⼿部受損的病⼈常使⽤副⽊（splint）來達到下述⽬的，但何者錯誤？","options":["(A) 可減緩⼿部的變形","(B) 可增進抓握能⼒","(C) 可協助⼿功能","(D) 可延緩疾病的進⾏"],"answer":3,"image":""},{"id":"md6-108-1-63","subject":"md6","topic":"復健-骨骼肌肉損傷與疾患","meta":"108年第1次第63題","year":108,"session":1,"number":63,"question":"張太太為75歲家庭主婦，最近三個⽉來抱怨⾛路⾛個⼗來分鐘兩下肢就會酸痛、⿇⽊，但是坐⼀下⼦症狀立即改善，⼜可繼續⾛下去。下列何種檢查對診斷最有幫助？","options":["(A) 腰椎⼀般X光檢查（plain x-ray）","(B) 肌電圖檢查（EMG）","(C) 神經傳導檢查（NCS）","(D) 磁振造影檢查（MRI）"],"answer":3,"image":""},{"id":"md6-108-1-64","subject":"md6","topic":"復健-骨骼肌肉損傷與疾患","meta":"108年第1次第64題","year":108,"session":1,"number":64,"question":"有關類風濕性關節炎（rheumatoid arthritis）病患的復健治療，下列敘述何者錯誤？","options":["(A) ⽬標是避免關節變形，維持活動功能","(B) 必要時需使⽤輔具矯正變形關節","(C) 物理治療最為重要，⼤多數病⼈不需職能治療","(D) 須配合居家與⼯作環境適應"],"answer":2,"image":""},{"id":"md6-108-1-65","subject":"md6","topic":"復健-心肺復健與運動處方","meta":"108年第1次第65題","year":108,"session":1,"number":65,"question":"在美國運動醫學院訂定的綱要（American College of Sports Medicine's Guideline）中，對正常⼈⼼肺耐⼒ 訓練（cardiorespiratory endurance training）的建議，下列描述何者正確？","options":["(A) 以⼩肌⾁群的靜態運動（static exercise of small muscle groups）為主","(B) 以有不同阻⼒的重⼒訓練機器（variable resistance weight machines）為輔助","(C) 每週進⾏3～5天的訓練","(D) 每次進⾏10～20分鐘"],"answer":2,"image":""},{"id":"md6-108-1-66","subject":"md6","topic":"復健-心肺復健與運動處方","meta":"108年第1次第66題","year":108,"session":1,"number":66,"question":"關於肺部物理治療（chest physical therapy）中的呼吸運動（breathing exercises），下列何者描述錯誤？","options":["(A) 在教導呼吸運動（breathing exercises）前，通常要先學習放鬆技巧（relaxation technique）","(B) 慢性阻塞性肺疾病（COPD）患者的呼吸運動（breathing exercises）包括撅唇呼吸（pursed lip breathing）並強調快⽽淺的呼吸法（fast shallow breathing）","(C) 撅唇呼吸（pursed lip breathing）的作⽤在於維持呼氣期氣道的正壓（maintain positive airway pressure during exhalation）","(D) 慢性阻塞性肺疾病（COPD）患者雖然常被教導橫膈膜式呼吸⽅式（diaphragmatic breathing），但對這群患者⽽⾔，橫膈膜式呼吸⽅式可能比⾃然呼吸⽅式（natural pattern of breathing）消耗更多的呼吸功（increase the work of breathing）"],"answer":1,"image":""},{"id":"md6-108-1-67","subject":"md6","topic":"復健-兒童與一般復健","meta":"108年第1次第67題","year":108,"session":1,"number":67,"question":"下列關於裘馨⽒肌⾁失養症（Duchenne muscular dystrophy）的敘述，何者錯誤？","options":["(A) 屬於X染⾊體性聯隱性遺傳（sex-linked recessive inheritance）","(B) ⾛路不穩搖擺主要是因為臀中肌（gluteus medius）無⼒所致","(C) 典型患者通常於8⾄12歲時會喪失步⾏能⼒","(D) 臨床上⾒到患者會有⾼爾⽒徵象（Gowers' sign）是因為遠端肢體無⼒所致"],"answer":3,"image":""},{"id":"md6-108-1-68","subject":"md6","topic":"復健-兒童與一般復健","meta":"108年第1次第68題","year":108,"session":1,"number":68,"question":"下列何者最不會造成腦性⿇痺？","options":["(A) 胎兒⼼跳過快（fetal tachycardia）","(B) 新⽣兒癲癇發作（neonatal seizure）","(C) 出⽣體重⼩於2,500公克","(D) ⺟親智能障礙"],"answer":0,"image":""},{"id":"md6-108-1-69","subject":"md6","topic":"復健-骨骼肌肉損傷與疾患","meta":"108年第1次第69題","year":108,"session":1,"number":69,"question":"有關⾜底筋膜炎（plantar fasciitis）及其治療的敘述，何者錯誤？","options":["(A) 病患常抱怨早晨第⼀步踏下去時最疼痛","(B) 病灶常在⾜底筋膜接跟骨處","(C) 當晚上使⽤⾜踝部護具（AFO）時，必須將踝關節固定在最⼤蹠屈（plantar flexion）⾓度","(D) 有證據顯⽰，體外震波治療（extracorporeal shockwave therapy）可有效治療⾜底筋膜炎"],"answer":2,"image":""},{"id":"md6-108-1-70","subject":"md6","topic":"復健-神經復健","meta":"108年第1次第70題","year":108,"session":1,"number":70,"question":"病患來⾨診求診時，發現右⼿第四、五指無法完全伸直，張開⼿檢查時，⼩⿂肌（hypothenar muscle）有萎縮現象，被診斷為鷹爪⼿（claw hand），是下列那⼀條神經受損？","options":["(A) 尺神經（ulnar nerve）","(B) 橈神經（radial nerve）","(C) 正中神經（median nerve）","(D) 肌⽪神經（musculocutaneous nerve）"],"answer":0,"image":""},{"id":"md6-108-1-71","subject":"md6","topic":"復健-神經復健","meta":"108年第1次第71題","year":108,"session":1,"number":71,"question":"下列那⼀種失語症其覆誦（repetition）能⼒最佳？","options":["(A) conduction aphasia","(B) anomic aphasia","(C) global aphasia","(D) Wernicke aphasia"],"answer":1,"image":""},{"id":"md6-108-1-72","subject":"md6","topic":"喉科學與頭頸腫瘤","meta":"108年第1次第72題","year":108,"session":1,"number":72,"question":"21歲男性因上頸部硬塊求診，接受對比劑注射後的電腦斷層掃描如圖⽰，則最可能診斷為何？","options":["(A) ⿐咽癌","(B) 淋巴管瘤","(C) 上呼吸道感染","(D) 深頸部感染症"],"answer":0,"image":"md6-108-1-72.jpeg"},{"id":"md6-108-1-73","subject":"md6","topic":"婦科-腫瘤","meta":"108年第1次第73題","year":108,"session":1,"number":73,"question":"68歲女性病患，已停經，主訴不正常陰道出⾎，磁振造影檢查如下圖。其最可能的診斷為何？","options":["(A) ⼦宮肌瘤（uterine myoma）","(B) ⼦宮內膜癌（endometrial cancer）","(C) ⼦宮頸癌（cervical cancer）","(D) ⼦宮內膜息⾁（endometrial polyp）"],"answer":2,"image":"md6-108-1-73.jpeg"},{"id":"md6-108-1-74","subject":"md6","topic":"復健-神經復健","meta":"108年第1次第74題","year":108,"session":1,"number":74,"question":"29歲男性在⾞禍後發現右上肢無⼒與⿇痺，圖為頸椎的磁振造影影像（T2WI），下列敘述何者錯誤？","options":["(A) 臨床病史和影像符合臂神經叢傷害（brachial plexus injury）","(B) 此病患最可能的診斷為假性脊髓膜膨出（pseudomeningocele）","(C) 臂神經叢傷害的磁振造影表現可以是stretching injury、root avulsion等","(D) Root avulsion是指神經根與脊髓（spinal cord）的神經節後分離（post-ganglionic separation）"],"answer":3,"image":"md6-108-1-74.jpeg"},{"id":"md6-108-1-75","subject":"md6","topic":"復健-神經復健","meta":"108年第1次第75題","year":108,"session":1,"number":75,"question":"關於顱外頸動脈剝離（carotid dissection），下列何者錯誤？","options":["(A) 最容易發⽣在顱外內頸動脈之頸部（cervical part），⽽非頸動脈分⽀處（carotid bifurcation）","(B) 可以外科⽅法做內膜切除術（carotid endartectomy）治療","(C) 磁振造影檢查（MRI）可看到動脈壁上的⾎腫訊號","(D) 藥物治療無效者可考慮⽀架置放術（carotid stenting）治療"],"answer":1,"image":""},{"id":"md6-108-1-76","subject":"md6","topic":"眼科-角膜結膜眼瞼眼窩","meta":"108年第1次第76題","year":108,"session":1,"number":76,"question":"30歲男性病⼈，因左眼不適、眼睛紅、合併畏光現象約⼀天，⾄急診就診。下列何者診斷較不可能：","options":["(A) 急性結膜炎（acute conjunctivitis）","(B) 虹膜炎（uveitis）","(C) ⾓膜炎（keratitis）","(D) 急性青光眼（acute glaucoma）"],"answer":0,"image":""},{"id":"md6-108-1-77","subject":"md6","topic":"耳科學","meta":"108年第1次第77題","year":108,"session":1,"number":77,"question":"下列有關急性中⽿炎的治療，何者錯誤？","options":["(A) amoxicillin仍為⾸選之抗⽣素","(B) 若⽤amoxicillin治療72⼩時無效，可考慮改成cefuroxime或amoxicillin-clavulanate治療","(C) 若中⽿積⽔亦可考慮使⽤prednisolone","(D) 成⼈急性中⽿炎常需⼿術治療"],"answer":3,"image":""},{"id":"md6-108-1-78","subject":"md6","topic":"產科-一般產科","meta":"108年第1次第78題","year":108,"session":1,"number":78,"question":"有關假產痛（false labor pain）和真產痛（true labor pain）的敘述，下列何者為錯誤？","options":["(A) 假產痛通常先由上腹開始疼痛再逐漸痛到下腹，真產痛則通常由下腹開始疼痛","(B) 假產痛的疼痛頻率通常不規則，真產痛則通常是規則的疼痛","(C) 假產痛⼦宮頸沒擴張，真產痛⼦宮頸則會逐漸擴張","(D) 假產痛通常會持續數天，真產痛預期⼀天內⼩孩會⽣下來"],"answer":0,"image":""},{"id":"md6-108-1-79","subject":"md6","topic":"醫學倫理與法規","meta":"108年第1次第79題","year":108,"session":1,"number":79,"question":"⼀位13歲女學⽣前來婦產科看診，要求醫師開給她避孕藥，這位女學⽣表⽰已經有性⾏為，且是出於⾃願，並要求醫師絕對不能告訴其家⼈或學校，醫師應該如何處理？","options":["(A) 給予性衛教與輔導即可","(B) 報告⽗⺟／監護⼈或社會局","(C) 報告學校當局","(D) 尊重病⼈的隱私權不予揭露"],"answer":1,"image":""},{"id":"md6-108-1-80","subject":"md6","topic":"醫學倫理與法規","meta":"108年第1次第80題","year":108,"session":1,"number":80,"question":"某些醫療處置可在未取得病⼈同意之下進⾏，但何者除外？","options":["(A) 在緊急情況下，延遲治療將導致病患死亡","(B) 思覺失調症病患有⾃傷或傷⼈的情況，需住院治療","(C) 疑似伊波拉病毒感染，需隔離治療","(D) 唐⽒症病患，需住院治療"],"answer":3,"image":""},{"id":"md6-108-2-1","subject":"md6","topic":"麻醉-呼吸道與監視","meta":"108年第2次第1題","year":108,"session":2,"number":1,"question":"有關麻醉中病人之體溫監測敘述，下列何者錯誤？","options":["(A) 核心溫度（core temperature）比較穩定，常用的測量部位包括nasopharynx","(B) 麻醉中常見的體溫異常，hypothermia多於hyperthermia","(C) rectal temperature在施行體外循環時，反應速度比核心溫度慢","(D) 全身麻醉都應監測病人體溫，但區域麻醉（regional anesthesia）可不必監測"],"answer":3,"image":""},{"id":"md6-108-2-2","subject":"md6","topic":"麻醉-呼吸道與監視","meta":"108年第2次第2題","year":108,"session":2,"number":2,"question":"下列那些是美國麻醉醫學會於1994年所公佈之對手術室外麻醉的臨床指引（Guidelines for non-operating room anesthetizing locations）？①足夠的麻醉照護空間②可靠的氧氣供應設備③適合的生理監測儀器④勿需準備電擊器（defibrillator）","options":["(A) 僅①②③","(B) ①②③④","(C) 僅①④","(D) 僅②③④"],"answer":0,"image":""},{"id":"md6-108-2-3","subject":"md6","topic":"麻醉-麻醉藥理","meta":"108年第2次第3題","year":108,"session":2,"number":3,"question":"Lidocaine加入epinephrine時，下列有關浸潤周邊臂神經叢時產生的麻醉作用之敘述，何者錯誤？","options":["(A) epinephrine可延長lidocaine麻醉的作用時間","(B) epinephrine可增強lidocaine神經阻斷的作用","(C) epinephrine可減低lidocaine藥物全身性的吸收","(D) epinephrine因作用於α-adrenergic receptor，有直接止痛效果2"],"answer":3,"image":""},{"id":"md6-108-2-4","subject":"md6","topic":"麻醉-麻醉藥理","meta":"108年第2次第4題","year":108,"session":2,"number":4,"question":"下列何種靜脈類麻醉藥物，具有支氣管擴張效果？","options":["(A) thiopental","(B) ketamine","(C) propofol","(D) midazolam"],"answer":[1,2],"image":"","answer_note":"更正:第4題答Ｂ、Ｃ給分"},{"id":"md6-108-2-5","subject":"md6","topic":"麻醉-麻醉藥理","meta":"108年第2次第5題","year":108,"session":2,"number":5,"question":"非去極化的肌肉鬆弛劑的給予，可幫助氣管內管置放。下列何藥物屬於benzyl-isoquinolinium compounds且沒有histamine的釋放，較不會產生藥物給予後的血壓下降？","options":["(A) mivacurium","(B) cis-atracurium","(C) d-tubocurarine","(D) pancuronium"],"answer":1,"image":""},{"id":"md6-108-2-6","subject":"md6","topic":"麻醉-呼吸道與監視","meta":"108年第2次第6題","year":108,"session":2,"number":6,"question":"有關肥胖病患（BMI>30）的生理變化與手術前評估敘述，下列何者錯誤？","options":["(A) 肥胖病患循環血量增加，心搏輸出增加，耗氧量亦增加，心臟易缺血","(B) 肥胖病患的每分鐘呼吸次數與通氣量不變","(C) 在腸胃道方面，肥胖病患易有胃食道逆流","(D) 肥胖病患通常困難插管的機會較高"],"answer":1,"image":""},{"id":"md6-108-2-7","subject":"md6","topic":"麻醉-特殊麻醉與疼痛","meta":"108年第2次第7題","year":108,"session":2,"number":7,"question":"糖尿病（DM）為國人常見疾病之一，下列有關糖尿病患的麻醉考量，何者錯誤？","options":["(A) 糖尿病患的糖尿病相關器官傷害，常因症狀不明顯而被病患所忽略","(B) 高血壓、無痛心肌梗塞、姿態性低血壓為糖尿病交感神經病變徵候之一","(C) 手術引起高血糖為正常生理變化，血糖控制在250 mg/dL左右即可","(D) 術前若有在使用胰島素，且沒有靜脈給予葡萄糖液，則一般手術當天應暫時停止使用胰島素"],"answer":2,"image":""},{"id":"md6-108-2-8","subject":"md6","topic":"麻醉-特殊麻醉與疼痛","meta":"108年第2次第8題","year":108,"session":2,"number":8,"question":"下列有關止痛治療藥物的敘述，何者錯誤？","options":["(A) 類鴉片止痛藥物可用於術後止痛與非術後止痛","(B) 類固醇藥物可用於止痛治療","(C) 神經肌肉阻斷劑也具有止痛作用","(D) 抗癲癇藥物可用於止痛治療"],"answer":2,"image":""},{"id":"md6-108-2-9","subject":"md6","topic":"麻醉-特殊麻醉與疼痛","meta":"108年第2次第9題","year":108,"session":2,"number":9,"question":"下列有關急性肝衰竭病人重症照顧處置之敘述，何者錯誤？","options":["(A) 歐美國家最常見病因為acetaminophen引發肝毒性","(B) 預防性抗生素已證明可有效減低感染率","(C) 腦水腫與腦壓增高，是不良預後的指標","(D) 高血鈉（>150 mmol/L）列為換肝之禁忌"],"answer":3,"image":""},{"id":"md6-108-2-10","subject":"md6","topic":"眼科-角膜結膜眼瞼眼窩","meta":"108年第2次第10題","year":108,"session":2,"number":10,"question":"下列何種疾病較不易併發周邊潰瘍性角膜炎（peripheral ulcerative keratitis）？","options":["(A) 類風溼性關節炎（rheumatoid arthritis）","(B) 全身性紅斑性狼瘡（systemic lupus erythematosus）","(C) 韋格納肉芽腫（Wegener granulomatosis）","(D) 多發性硬化症（multiple sclerosis）"],"answer":3,"image":""},{"id":"md6-108-2-11","subject":"md6","topic":"眼科-角膜結膜眼瞼眼窩","meta":"108年第2次第11題","year":108,"session":2,"number":11,"question":"有關砂眼（trachoma）的病徵，下列何者最具有診斷上的意義？","options":["(A) 輪部濾泡（limbal follicles）和Herbert pits","(B) 巨型乳頭狀突起（giant papillae）","(C) Horner-Trantas dots","(D) 結膜結石（lithiasis）"],"answer":0,"image":""},{"id":"md6-108-2-12","subject":"md6","topic":"眼科-屈光斜弱視","meta":"108年第2次第12題","year":108,"session":2,"number":12,"question":"上斜肌（superior oblique muscle）本身的作用，並不會使眼球做下列何種運動？","options":["(A) 看下（depression）","(B) 內旋（intorsion）","(C) 內轉（adduction）","(D) 外轉（abduction）"],"answer":2,"image":""},{"id":"md6-108-2-13","subject":"md6","topic":"眼科-水晶體青光眼","meta":"108年第2次第13題","year":108,"session":2,"number":13,"question":"在急性隅角閉鎖性青光眼（acute angle-closure glaucoma），下列那一種情形較不可能發生？","options":["(A) 結膜充血","(B) 角膜水腫","(C) 半放大之瞳孔","(D) 視神經盤凹陷（cup/disc ratio）擴大"],"answer":3,"image":""},{"id":"md6-108-2-14","subject":"md6","topic":"眼科-屈光斜弱視","meta":"108年第2次第14題","year":108,"session":2,"number":14,"question":"下列何者不是「假性內斜視」（pseudoesotropia）的原因？","options":["(A) 兩眼瞳孔間距太短","(B) 顯著的內眥上皮皺摺（epicanthal folds）","(C) 高度近視伴隨negative kappa angle","(D) 早產兒網膜症造成黃斑部異位（ectopic macula）"],"answer":3,"image":""},{"id":"md6-108-2-15","subject":"md6","topic":"眼科-屈光斜弱視","meta":"108年第2次第15題","year":108,"session":2,"number":15,"question":"隱斜視（heterophoria）的診斷一般須靠下列何種檢查，才能確定？","options":["(A) cover-uncover test","(B) alternate cover test","(C) prism cover test","(D) prism reflex test（krimsky）"],"answer":0,"image":""},{"id":"md6-108-2-16","subject":"md6","topic":"眼科-角膜結膜眼瞼眼窩","meta":"108年第2次第16題","year":108,"session":2,"number":16,"question":"關於眼瞼痙攣（essential blepharospasm）的敘述，下列何者錯誤？","options":["(A) 大多數為單眼發作","(B) 好發於中老年女性","(C) 臨床表現需和乾眼症做鑑別診斷","(D) 可以用注射肉毒桿菌素（botulinum toxin）改善症狀"],"answer":0,"image":""},{"id":"md6-108-2-17","subject":"md6","topic":"眼科-視網膜葡萄膜","meta":"108年第2次第17題","year":108,"session":2,"number":17,"question":"如眼底視網膜照片所示，此位患者最可能之診斷為何？","options":["(A) 裂孔型視網膜剝離（rhegmatogenous retinal detachment）","(B) 牽引型視網膜剝離（tractional retinal detachment）","(C) 出血型視網膜剝離（hemorrhagic retinal detachment）","(D) 滲漏型視網膜剝離（exudative retinal detachment）"],"answer":0,"image":"md6-108-2-17.jpeg"},{"id":"md6-108-2-18","subject":"md6","topic":"眼科-視網膜葡萄膜","meta":"108年第2次第18題","year":108,"session":2,"number":18,"question":"承上題，患者較不適當之處置為何？","options":["(A) 視網膜冷凍固定術（cryopexy）","(B) 鞏膜扣環術（scleral buckling）","(C) 於門診施行視網膜雷射治療（laser photocoagulation）","(D) 玻璃體切除術（vitrectomy）"],"answer":2,"image":""},{"id":"md6-108-2-19","subject":"md6","topic":"耳科學","meta":"108年第2次第19題","year":108,"session":2,"number":19,"question":"下列何者所接收的訊息，是由前庭神經下分支（inferior division of vestibular nerve）傳入中樞？","options":["(A) 上半規管（superior semicircular canal）","(B) 側半規管（lateral semicircular canal）","(C) 後半規管（posterior semicircular canal）","(D) 橢圓囊（utricle）"],"answer":2,"image":""},{"id":"md6-108-2-20","subject":"md6","topic":"耳科學","meta":"108年第2次第20題","year":108,"session":2,"number":20,"question":"下列何種疾病，耳鏡檢查可見Schwartze徵象？","options":["(A) 聽神經瘤（acoustic neuroma）","(B) 膽固醇肉芽腫（cholesterol granuloma）","(C) 膽脂瘤（cholesteatoma）","(D) 耳硬化症（otosclerosis）"],"answer":3,"image":""},{"id":"md6-108-2-21","subject":"md6","topic":"眼科-角膜結膜眼瞼眼窩","meta":"108年第2次第21題","year":108,"session":2,"number":21,"question":"下列構造何者不經過superior orbital fissure？","options":["(A) trochlear nerve","(B) abducens nerve","(C) superior ophthalmic vein","(D) maxillary branch of trigeminal nerve"],"answer":3,"image":""},{"id":"md6-108-2-22","subject":"md6","topic":"鼻科學","meta":"108年第2次第22題","year":108,"session":2,"number":22,"question":"有關hereditary hemorrhagic telangiectasia的治療方式，下列何者不恰當？","options":["(A) regular nasal mucosal care with nasal saline","(B) endonasal lasering or bipolar diathermy","(C) septodermoplasty","(D) vascular embolization"],"answer":[0,1,2,3],"image":"","answer_note":"送分:第22題一律給分。 (原公告答案 D)"},{"id":"md6-108-2-23","subject":"md6","topic":"喉科學與頭頸腫瘤","meta":"108年第2次第23題","year":108,"session":2,"number":23,"question":"40歲男性，因發燒、咽喉疼痛、吞嚥困難、呼吸急促等症狀至急診就診，會診耳鼻喉科進行咽喉內視鏡檢查如下圖，下列敘述何者正確？","options":["(A) 箭頭所指為甲狀軟骨（thyroid cartilage）發炎腫脹","(B) 常見之病原為病毒感染","(C) 此病人可能發生急性呼吸道阻塞","(D) 側頸部X光可見尖塔徵象（steeple sign）"],"answer":2,"image":"md6-108-2-23.jpeg"},{"id":"md6-108-2-24","subject":"md6","topic":"喉科學與頭頸腫瘤","meta":"108年第2次第24題","year":108,"session":2,"number":24,"question":"有關單側或雙側聲帶麻痺（vocal fold paralysis）之敘述，下列何者正確？","options":["(A) 造成聲帶麻痺之主因為上喉神經（superior laryngeal nerve）受損","(B) 呼吸困難較常見於單側聲帶麻痺","(C) 單側聲帶麻痺以左側較為常見","(D) 發聲障礙較常見於雙側聲帶麻痺"],"answer":2,"image":""},{"id":"md6-108-2-25","subject":"md6","topic":"喉科學與頭頸腫瘤","meta":"108年第2次第25題","year":108,"session":2,"number":25,"question":"有關甲狀舌管囊腫（thyroglossal duct cyst）之敘述，下列何者錯誤？","options":["(A) 通常發生在頸部中線，是最常見的先天性頸部腫塊","(B) 惡性轉化率極低，最常見的惡性細胞型態是鱗狀上皮細胞癌（squamous cell carcinoma）","(C) 標準的治療方式是Sistrunk手術","(D) 先前發生過囊腫感染者，手術後較易復發"],"answer":1,"image":""},{"id":"md6-108-2-26","subject":"md6","topic":"喉科學與頭頸腫瘤","meta":"108年第2次第26題","year":108,"session":2,"number":26,"question":"有關人類乳突瘤病毒（human papilloma virus, HPV）與頭頸癌相關性的敘述，下列何者錯誤？","options":["(A) 在各個頭頸次部位中，與HPV相關性最高的是口咽癌（oropharyngeal cancer）","(B) 在所有的HPV亞型中，以第16型與頭頸癌的關係最為密切","(C) HPV產生的E6蛋白質會抑制p53的功能，E7蛋白質則會抑制pRb的功能","(D) HPV陽性的口咽癌對化學治療及放射治療的反應及預後較差"],"answer":3,"image":""},{"id":"md6-108-2-27","subject":"md6","topic":"喉科學與頭頸腫瘤","meta":"108年第2次第27題","year":108,"session":2,"number":27,"question":"有關口腔黏膜變化的敘述，下列何者正確？","options":["(A) 口腔白斑（leukoplakia）主要變化是口腔黏膜上皮層萎縮","(B) 口腔白斑惡性變化的可能性較口腔紅斑（erythroplakia）為高","(C) 扁平苔蘚（lichen planus）雖然是一種自體免疫病灶，也有惡性變化的可能","(D) 口腔黏膜下纖維化（submucosal fibrosis）是一種發炎性病灶，不會產生惡性變化"],"answer":2,"image":""},{"id":"md6-108-2-28","subject":"md6","topic":"產科-一般產科","meta":"108年第2次第28題","year":108,"session":2,"number":28,"question":"與一般均衡飲食的孕婦相較，全素（strict vegetarians）的妊娠婦女，最可能缺乏下列何種維生素？","options":["(A) 維生素A","(B) 維生素B 12","(C) 維生素C","(D) 維生素K"],"answer":1,"image":""},{"id":"md6-108-2-29","subject":"md6","topic":"產科-一般產科","meta":"108年第2次第29題","year":108,"session":2,"number":29,"question":"2以真空吸引娩出胎兒，較適合的壓力大約是多少kg/cm？","options":["(A) 2 0.2 kg/cm","(B) 2 0.6 kg/cm","(C) 2 1.0 kg/cm","(D) 2 2.0 kg/cm"],"answer":1,"image":""},{"id":"md6-108-2-30","subject":"md6","topic":"產科-高危險妊娠","meta":"108年第2次第30題","year":108,"session":2,"number":30,"question":"Trisomy 13（Patau syndrome）不會合併下列何種異常？","options":["(A) 唇顎裂（cleft lip/palate）","(B) 臍膨出（omphalocele）","(C) 大頭畸形（macrocephaly）","(D) 橈骨發育不良（radial bone aplasia）"],"answer":2,"image":""},{"id":"md6-108-2-31","subject":"md6","topic":"產科-一般產科","meta":"108年第2次第31題","year":108,"session":2,"number":31,"question":"母乳缺乏下列何種維他命？","options":["(A) Vit.A","(B) Vit.D","(C) Vit.E","(D) Vit.K"],"answer":3,"image":""},{"id":"md6-108-2-32","subject":"md6","topic":"產科-一般產科","meta":"108年第2次第32題","year":108,"session":2,"number":32,"question":"45歲孕婦，G5P4，妊娠週數不明，接受產科超音波檢查，正在測量標的的名稱（雙十字之間）為何？","options":["(A) BPD（biparietal diameter）","(B) AC（abdominal circumference）","(C) FL（femur length）","(D) NT（nuchal translucency）"],"answer":2,"image":"md6-108-2-32.jpeg"},{"id":"md6-108-2-33","subject":"md6","topic":"婦科-良性腫瘤與內膜異位","meta":"108年第2次第33題","year":108,"session":2,"number":33,"question":"23歲女性於近兩個月常感覺右下腹疼痛，此疼痛有時改變姿勢可改善症狀，今日則因疼痛加劇且合併有噁心嘔吐之情形就醫。理學檢查發現右下腹有壓痛及反彈痛之情形，經陰道指診發現子宮大小正常，但有觸壓疼痛的情形，同時子宮右邊有腫塊如鵝蛋大小，亦有觸壓疼痛的情形。超音波掃描發現右邊子宮附屬物有腫塊，大小約7×8公分。由於右下腹痛加劇，因此接受腹腔鏡檢查，腹腔鏡檢查發現有下圖之情形，依據圖示此患者最適合之診斷為：","options":["(A) 卵巢腫瘤合併扭轉（ovarian tumor with torsion）","(B) 輸卵管外孕（tubal pregnancy）","(C) 急性盲腸炎（appendicitis）","(D) 子宮肌瘤紅色變性（red degeneration of myoma）"],"answer":0,"image":"md6-108-2-33.jpeg"},{"id":"md6-108-2-34","subject":"md6","topic":"婦科-腫瘤","meta":"108年第2次第34題","year":108,"session":2,"number":34,"question":"21歲女性因為左下腹痛求診，內診發現左側卵巢腫大，超音波檢查顯示左側卵巢實質腫瘤，而內含物似乎是骨頭及牙齒。這類腫瘤約有多少百分比是雙側性？","options":["(A) 小於1%","(B) 2%～3%","(C) 10%～15%","(D) 50%"],"answer":2,"image":""},{"id":"md6-108-2-35","subject":"md6","topic":"婦科-生殖內分泌","meta":"108年第2次第35題","year":108,"session":2,"number":35,"question":"30歲女性，已有連續4次懷孕都在第一孕期就自然流產，醫師建議做夫妻的染色體檢查，結果夫妻中一方有異常，最有可能的異常是：","options":["(A) trisomy 18","(B) balanced translocation","(C) Turner syndrome","(D) Klinefelter syndrome"],"answer":1,"image":""},{"id":"md6-108-2-36","subject":"md6","topic":"婦科-腫瘤","meta":"108年第2次第36題","year":108,"session":2,"number":36,"question":"目前治療晚期（advanced）上皮性卵巢癌化學療法的第一線藥物為何？","options":["(A) cisplatin＋5FU","(B) carboplatin＋paclitaxel","(C) cisplatin＋cyclophosphamide","(D) carboplatin＋cyclophosphamide"],"answer":1,"image":""},{"id":"md6-108-2-37","subject":"md6","topic":"婦科-腫瘤","meta":"108年第2次第37題","year":108,"session":2,"number":37,"question":"20歲懷孕38週婦女，G1P0，因胎位不正接受剖腹產手術，手術中意外發現左側有一約10公分左右的卵巢腫瘤，右側卵巢外觀正常，術中無腹水，於是行剖腹產後接著行卵巢囊腫摘除術（ovarian cystectomy），術中不慎發生囊腫破裂。術中冰凍切片病理報告為yolk sac tumor。接下來處置以何者為佳？","options":["(A) 作完月子後再視當時情況而定","(B) 不宜餵奶並行骨盆腔放射線治療","(C) 保留另一側卵巢及子宮以保留生育能力，並在術後行化學治療","(D) 由於生殖細胞癌預後差，應即刻切除子宮及雙側卵巢輸卵管"],"answer":2,"image":""},{"id":"md6-108-2-38","subject":"md6","topic":"婦科-腫瘤","meta":"108年第2次第38題","year":108,"session":2,"number":38,"question":"醫師值班接到一緊急轉診的病患：一位60歲婦女，因卵巢水瘤於診所接受手術，術中發現為一高度懷疑之右側卵巢惡性腫瘤，並已擴散至腹腔中，形成網膜硬塊（omentum cake），但是並無橫膈下或肝臟轉移。該診所未做任何切除手術，將傷口簡單關閉而立刻轉送本院。送至本院時，神智清醒，感覺傷口疼痛，生命徵象穩定，血壓138/86 mmHg，心搏86 bpm，傷口只有五針縫合，微滲血。接下來的處置，何者最適當？","options":["(A) 立刻送至開刀房行剖腹減積手術（debulking surgery）","(B) 暫時給予化學治療1次，視病患情況，再行減積手術","(C) 先行緊急電腦斷層檢查，評估腹內狀況，再行減積手術","(D) 同步實施化學及放射線治療（concurrent chemoradiation），待腫瘤減小後再行減積手術"],"answer":0,"image":""},{"id":"md6-108-2-39","subject":"md6","topic":"婦科-腫瘤","meta":"108年第2次第39題","year":108,"session":2,"number":39,"question":"下列何者不是邊緣惡性卵巢腫瘤（borderline tumors）的診斷條件（criteria）？","options":["(A) 上皮細胞呈現乳突狀構造（papillary formation）及偽多層（pseudostratification）","(B) 細胞核異常（atypia）","(C) 細胞有絲分裂增加","(D) 可見基質侵犯（stromal invasion）"],"answer":3,"image":""},{"id":"md6-108-2-40","subject":"md6","topic":"產科-一般產科","meta":"108年第2次第40題","year":108,"session":2,"number":40,"question":"30歲女性，月經周期規則，根據她最後一次月經來計算，目前懷孕10週，關於胎兒生長發育的敘述，下列何者最不符合？","options":["(A) 手肘可彎曲","(B) 頭臀徑（crown-rump length）7公分","(C) 橫膈膜已形成","(D) 心臟結構已形成"],"answer":1,"image":""},{"id":"md6-108-2-41","subject":"md6","topic":"產科-一般產科","meta":"108年第2次第41題","year":108,"session":2,"number":41,"question":"如圖所示之生產方式，為何種肩難產輔助方法？","options":["(A) Rubin maneuver","(B) McRoberts maneuver","(C) Fundal pressure","(D) Woods corkscrew maneuver"],"answer":1,"image":"md6-108-2-41.jpeg"},{"id":"md6-108-2-42","subject":"md6","topic":"產科-一般產科","meta":"108年第2次第42題","year":108,"session":2,"number":42,"question":"產婦生產會陰部裂傷（perineal laceration）共分四度，第四度裂傷最為嚴重。第四度裂傷代表深度到達下列何種解剖位置？","options":["(A) 陰道黏膜層（vaginal mucosa）","(B) 外層肛門括約肌（external anal sphincter）","(C) 內層肛門括約肌（internal anal sphincter）","(D) 直腸黏膜層（rectal mucosa）"],"answer":3,"image":""},{"id":"md6-108-2-43","subject":"md6","topic":"產科-高危險妊娠","meta":"108年第2次第43題","year":108,"session":2,"number":43,"question":"36歲G2P1孕婦，接受規律產前檢查，並無妊娠相關合併症，主訴已超過預產期2天，自覺胎動頻次稍為減少至門診求診。安排胎心搏監測呈現良好反應（reactive），無規律性子宮收縮；超音波檢查最大羊水池垂直深度（maximum vertical pocket depth）3.6 cm，預估胎兒體重3,600公克，陰道內診子宮頸未開，破水測試呈現陰性反應。此時的最適當處置為：","options":["(A) 安排產前檢查門診追蹤觀察","(B) 安排住院引產","(C) 安排剖腹生產","(D) 給予抗生素治療"],"answer":0,"image":""},{"id":"md6-108-2-44","subject":"md6","topic":"產科-高危險妊娠","meta":"108年第2次第44題","year":108,"session":2,"number":44,"question":"不建議孕婦於懷孕期間，接受下列那一項預防性疫苗接種？","options":["(A) 流行性感冒（influenza）","(B) 狂犬病（rabies）","(C) 水痘（varicella）","(D) 破傷風（tetanus）"],"answer":2,"image":""},{"id":"md6-108-2-45","subject":"md6","topic":"婦科-尿失禁與骨盆腔脫垂","meta":"108年第2次第45題","year":108,"session":2,"number":45,"question":"臨床上測量有無尿道過度移動（urethral hypermobility），常會作cotton swab test並使用測角器（goniometer）來測量尿道靜止及移動角度變化，下列何者為診斷尿道過度移動的準則（criteria）？","options":["(A) a resting urethral angle > 30 degrees or a maximal straining angle > 30 degrees","(B) a resting urethral angle > 30 degrees and a maximal straining angle > 30 degrees","(C) a resting urethral angle > 30 degrees or a maximal straining angle > 45 degrees","(D) a resting urethral angle > 30 degrees and a maximal straining angle > 45 degrees"],"answer":0,"image":""},{"id":"md6-108-2-46","subject":"md6","topic":"婦科-腫瘤","meta":"108年第2次第46題","year":108,"session":2,"number":46,"question":"有關人類乳突病毒（HPV）的敘述，下列何者錯誤？","options":["(A) 病理切片上，koilocytosis是HPV感染的特徵","(B) 第6及第11型屬高危險型","(C) 第16型是子宮頸癌與癌前病變最常見的型別","(D) HPV的E6與E7屬致癌蛋白"],"answer":1,"image":""},{"id":"md6-108-2-47","subject":"md6","topic":"婦科-腫瘤","meta":"108年第2次第47題","year":108,"session":2,"number":47,"question":"有關處置外陰癌（vulvar cancer），最近的處置原則，不包括下列何者？","options":["(A) 對所有的病患都應該根據其狀況，做個別式（individualization）的治療","(B) 不必一定要執行常規（routine）的骨盆腔淋巴結去除手術（pelvic lymph node dissection）","(C) 針對腹股溝淋巴有轉移（multiple positive groin nodes）的病患，手術後的放射線治療是必須的。目的要降低腹股溝（groin）處的復發。因為這類病患一旦有腹股溝處的復發，幾乎均會死亡","(D) 因爲外陰癌（vulvar cancer）的病患，淋巴的轉移，是沿著腹股溝的淋巴結轉移，應常規執行外陰癌根除術及雙側的腹股溝淋巴結去除手術（groin lymph nodes dissection）"],"answer":3,"image":""},{"id":"md6-108-2-48","subject":"md6","topic":"婦科-腫瘤","meta":"108年第2次第48題","year":108,"session":2,"number":48,"question":"下列那一種妊娠滋養細胞腫瘤（gestational trophoblastic neoplasia, GTN），對化療的反應最差？","options":["(A) 絨毛腺癌（choriocarcinoma）","(B) 胎盤處滋養細胞腫瘤（placental-site trophoblastic tumor）","(C) 侵襲性（invasive）GTN","(D) 轉移性（metastatic）GTN"],"answer":1,"image":""},{"id":"md6-108-2-49","subject":"md6","topic":"婦科-腫瘤","meta":"108年第2次第49題","year":108,"session":2,"number":49,"question":"因為卵巢生殖細胞瘤（germ cell tumors of the ovary）大多都是單側生長，下列那一種最可能會同時發現兩側都有腫瘤？","options":["(A) 無性胚胎瘤（dysgerminoma）","(B) 卵巢內胚層竇瘤（endodermal sinus tumor）","(C) 卵巢多胚瘤（polyembryoma）","(D) 混合性生殖細胞腫瘤（mixed germ cell tumor）"],"answer":0,"image":""},{"id":"md6-108-2-50","subject":"md6","topic":"婦科-生殖內分泌","meta":"108年第2次第50題","year":108,"session":2,"number":50,"question":"關於多毛症（hirsutism）治療之敘述，下列何者錯誤？","options":["(A) 使用medroxyprogesterone acetate治療","(B) 使用flutamide治療","(C) 使用spironolactone治療","(D) 使用cyproterone acetate治療"],"answer":0,"image":""},{"id":"md6-108-2-51","subject":"md6","topic":"婦科-生殖內分泌","meta":"108年第2次第51題","year":108,"session":2,"number":51,"question":"關於高泌乳激素血症（hyperprolactinemia）與泌乳激素腺瘤（prolactin adenoma）之敘述，下列何者錯誤？","options":["(A) bromocriptine是短效的dopamine-like藥物，須每日服用","(B) cabergoline是長效的dopamine-like藥物，每週服用2次","(C) 服用bromocriptine與cabergoline，無法有效地縮小腫瘤","(D) 服用bromocriptine與cabergoline，若泌乳激素（prolactin）的血中濃度降至正常範圍內達2年以上，可考慮停藥追蹤"],"answer":2,"image":""},{"id":"md6-108-2-52","subject":"md6","topic":"婦科-生殖內分泌","meta":"108年第2次第52題","year":108,"session":2,"number":52,"question":"25歲何小姐到院初診，身高156 cm、體重75 Kg、BMI=30.8，臉上有許多青春痘，以前曾經發生過2次長期而量多的出血，上一次月經是3個月前，這3個月，都在每月的15日前後，有1天的微量出血，下列何者為非必要之檢查？","options":["(A) 測定血中estradiol（E2）、FSH及LH之濃度","(B) 尿液懷孕試驗","(C) 染色體檢查","(D) 婦產科超音波檢查"],"answer":2,"image":""},{"id":"md6-108-2-53","subject":"md6","topic":"婦科-生殖內分泌","meta":"108年第2次第53題","year":108,"session":2,"number":53,"question":"試管嬰兒療程中以controlled ovarian stimulation得以同時使多顆濾泡成熟至排卵前的階段，最主要是因為額外給予下列那一種荷爾蒙？","options":["(A) Estradiol，因為高雌性素的環境，能持續支持長大中的濾泡","(B) FSH，因為高濃度的FSH，能持續支持長大中的濾泡","(C) LH，因為LH會增加steroid製造，讓較小的濾泡持續有生成雌性素的原料","(D) Estradiol，因為高濃度的雌性素會負回饋抑制下視丘，進而延遲LH surge讓更多濾泡可以生長"],"answer":1,"image":""},{"id":"md6-108-2-54","subject":"md6","topic":"婦科-生殖內分泌","meta":"108年第2次第54題","year":108,"session":2,"number":54,"question":"有關胚胎植入前基因診斷（preimplantation genetic diagnosis）技術的敘述，下列何者錯誤？","options":["(A) 須要配合試管嬰兒療程施行","(B) 當結果是正常女性（46, XX）時，最有可能是培養處理時，母親細胞污染所造成","(C) 可排除染色體異常的胚胎","(D) 當婦女有習慣性流產的病史，可減少流產的機會"],"answer":1,"image":""},{"id":"md6-108-2-55","subject":"md6","topic":"婦科-生殖內分泌","meta":"108年第2次第55題","year":108,"session":2,"number":55,"question":"15歲就讀國三的女生因為至今仍無初經，由媽媽陪同前來看診。她身高140公分，體重35公斤。理學檢查發現無第二性徵，有明顯的蹼狀頸（webbed neck）。媽媽回憶女兒小時候因為先天性心臟病有接受過手術，也帶來過去做的染色體檢查報告，如圖所示。關於這名患者的狀況，下列敘述何者正確？","options":["(A) 抽血驗FSH/LH/Estradiol的數值應是三者皆低","(B) 應建議病患立即手術切除性腺，因有癌變的風險","(C) 此疾病患者全無子宮發育","(D) 此疾病患者若為鑲嵌染色體型（mosaicism）仍可能有正常月經"],"answer":3,"image":"md6-108-2-55.jpeg"},{"id":"md6-108-2-56","subject":"md6","topic":"婦科-生殖內分泌","meta":"108年第2次第56題","year":108,"session":2,"number":56,"question":"30歲已婚女性，因為男性因素不孕症的原因，接受試管嬰兒療程（in vitro fertilization）。接受超音波導引取卵手術的隔天，因為噁心、腹漲、呼吸喘等不適回到醫院，診斷是卵巢過度刺激症候群（ovarian hyperstimulation syndrome）。下列何項作法可以降低這項疾病的發生機會？","options":["(A) 增加療程中gonadotropin的劑量","(B) 選用GnRH agonist誘發排卵（ovulation trigger）接著冷凍胚胎（cryopreservation）於下次植入","(C) 選用GnRH agonist的長療程（long protocol）","(D) 於取卵後的黃體期支持（luteal support）中施打human chorionic gonadotropin（hCG）"],"answer":1,"image":""},{"id":"md6-108-2-57","subject":"md6","topic":"婦科-生殖內分泌","meta":"108年第2次第57題","year":108,"session":2,"number":57,"question":"卵細胞何時完成第一次減數分裂（meiosis I）？","options":["(A) 性成熟時（puberty）","(B) 黃體化激素潮放（LH surge）時","(C) 精子進入卵子之時","(D) 受精後（fertilization）"],"answer":1,"image":""},{"id":"md6-108-2-58","subject":"md6","topic":"復健-神經復健","meta":"108年第2次第58題","year":108,"session":2,"number":58,"question":"下列那一條神經常在穿過鼠蹊韌帶（inguinal ligament）時受到壓迫，造成病患大腿外側感覺麻痛？","options":["(A) 股神經（femoral nerve）","(B) 股骨側皮表神經（lateral femoral cutaneous nerve）","(C) 閉孔神經（obturator nerve）","(D) 陰部神經（pudendal nerve）"],"answer":1,"image":""},{"id":"md6-108-2-59","subject":"md6","topic":"復健-神經復健","meta":"108年第2次第59題","year":108,"session":2,"number":59,"question":"下列何種神經病變，病人的上肢會呈現如「侍者小費（waiter tip）」的表現？","options":["(A) 臂神經叢","(B) 正中神經","(C) 尺神經","(D) 橈神經"],"answer":0,"image":""},{"id":"md6-108-2-60","subject":"md6","topic":"復健-神經復健","meta":"108年第2次第60題","year":108,"session":2,"number":60,"question":"動脈瘤（arterial aneurysm）常會導致下列何種形式的腦中風？","options":["(A) 視丘（thalamus）出血","(B) 大腦皮層下（subcortical）出血","(C) 蜘蛛網膜下（subarachnoid）出血","(D) 小腦（cerebellum）出血"],"answer":2,"image":""},{"id":"md6-108-2-61","subject":"md6","topic":"復健-神經復健","meta":"108年第2次第61題","year":108,"session":2,"number":61,"question":"對「鎖入症候群（lock-in syndrome）」的敘述，下列何項明顯錯誤？","options":["(A) 四肢無力","(B) 兩側橋腦（pons）病變引起","(C) 眼球左右共軛注視（conjugate gaze）功能正常","(D) 皮質延髓徑（corticobular tract）部分受損"],"answer":2,"image":""},{"id":"md6-108-2-62","subject":"md6","topic":"復健-骨骼肌肉損傷與疾患","meta":"108年第2次第62題","year":108,"session":2,"number":62,"question":"65歲的張太太罹患右膝退化性關節炎有五年之久，前天朋友邀約去爬七星山，回家後感覺右膝疼痛、腫脹。醫師診察發現張太太的右膝腫脹，很可能有積水；把她的右膝彎到100度就會引起嚴重的疼痛，且右膝內側有壓痛點，則下列處置何者最不適宜？","options":["(A) 投予非類固醇抗發炎藥","(B) 在右膝上使用經皮神經電刺激","(C) 立即把她的右膝牽拉到正常的角度","(D) 右膝可做等長運動"],"answer":2,"image":""},{"id":"md6-108-2-63","subject":"md6","topic":"復健-骨骼肌肉損傷與疾患","meta":"108年第2次第63題","year":108,"session":2,"number":63,"question":"臨床上下列何處之病變因超音波檢查不易檢測而最需使用磁振造影（MRI）檢查？","options":["(A) 脊上肌（supraspinatus）肌腱","(B) 脊下肌（infraspinatus）肌腱","(C) 三角肌下滑液囊（subdeltoid bursa）","(D) 肩關節之盂唇（labrum）"],"answer":3,"image":""},{"id":"md6-108-2-64","subject":"md6","topic":"復健-骨骼肌肉損傷與疾患","meta":"108年第2次第64題","year":108,"session":2,"number":64,"question":"下列何者不是非發炎性關節液（non-inflammatory synovial fluid）的特徵？","options":["(A) 黏蛋白凝固（mucin clot）佳","(B) 多形核白血球之比率＜25%","(C) 3白血球數目高於2000/mm","(D) 黏綢度（viscosity）高"],"answer":2,"image":""},{"id":"md6-108-2-65","subject":"md6","topic":"復健-骨骼肌肉損傷與疾患","meta":"108年第2次第65題","year":108,"session":2,"number":65,"question":"有關人類骨折（fracture）復健的原則，下列何者錯誤？","options":["(A) 對於骨折病人，未加固定的關節應儘早運動","(B) 對老年人而言，步態訓練時先使用助行器（walker）","(C) 急性期骨折處局部熱療可減緩疼痛，降低肌肉痙攣（spasm）","(D) 對於骨折病人，適當增加負重（weight bearing）可促進骨折癒合"],"answer":2,"image":""},{"id":"md6-108-2-66","subject":"md6","topic":"復健-骨骼肌肉損傷與疾患","meta":"108年第2次第66題","year":108,"session":2,"number":66,"question":"下圖中的背架，最適合用於下列何種病患？","options":["(A) 第七頸椎骨折","(B) 突向右側頂點在第六胸椎的脊椎側彎","(C) 第十胸椎壓迫性骨折","(D) 第一腰椎骨折脫位"],"answer":1,"image":"md6-108-2-66.jpeg"},{"id":"md6-108-2-67","subject":"md6","topic":"復健-骨骼肌肉損傷與疾患","meta":"108年第2次第67題","year":108,"session":2,"number":67,"question":"關於肌力訓練的描述，下列何者錯誤？","options":["(A) 阻力訓練是借重高阻力之訓練，通常是一種等長性之肌肉收縮（isometric contraction）","(B) 等長阻力訓練肌肉維持在等長狀態對抗阻力作收縮訓練，其關節並不產生動作","(C) 等張性運動（isotonic exercise）就是等角速度運動（isokinetic exercise）","(D) 阻力訓練對心臟的負荷較大，一般對心臟病患或老年人較不建議"],"answer":2,"image":""},{"id":"md6-108-2-68","subject":"md6","topic":"復健-兒童與一般復健","meta":"108年第2次第68題","year":108,"session":2,"number":68,"question":"關於symmetric tonic neck reflex的敘述，下列何者正確？","options":["(A) 屈曲頭部時，上肢會彎曲，下肢也會彎曲","(B) 屈曲頭部時，上肢會彎曲，下肢也會伸直","(C) 伸直頭部時，上肢會伸直，下肢也會伸直","(D) 伸直頭部時，上肢會彎曲，下肢也會伸直"],"answer":1,"image":""},{"id":"md6-108-2-69","subject":"md6","topic":"復健-神經復健","meta":"108年第2次第69題","year":108,"session":2,"number":69,"question":"中風剛住院的病患，在語言評估時，發現他說話時雖常出現語誤，但聽理解能力與語言表達流暢度尚佳，只不過在單詞覆述、聽寫單詞與朗誦文字會出現困難，這最可能是以下那一種語言障礙？","options":["(A) 渥尼克氏失語症（Wernicke aphasia）","(B) 傳導型失語症（conduction aphasia）","(C) 經皮質混合型失語症（transcortical mixed aphasia）","(D) 運動失調型吶吃（ataxic dysarthria）"],"answer":1,"image":""},{"id":"md6-108-2-70","subject":"md6","topic":"復健-骨骼肌肉損傷與疾患","meta":"108年第2次第70題","year":108,"session":2,"number":70,"question":"老太太跌倒後因劇烈疼痛被送到急診，檢查後發現疼痛部位為兩側腹股溝，但因兩側大腿前屈角度正常，懷疑是脊椎壓迫性骨折，下列那一節脊椎最可能有壓迫性骨折？","options":["(A) C7","(B) T8","(C) L1","(D) L5"],"answer":2,"image":""},{"id":"md6-108-2-71","subject":"md6","topic":"復健-兒童與一般復健","meta":"108年第2次第71題","year":108,"session":2,"number":71,"question":"下列何者是現今評估吞嚥功能的黃金標準（gold standard）檢查？","options":["(A) 壓力測定儀（manometry）","(B) 超音波檢查（ultrasound）","(C) 錄影螢光吞嚥檢查（videofluorographic swallowing study）","(D) 電腦斷層咽喉掃描（CT scan of pharynx）"],"answer":2,"image":""},{"id":"md6-108-2-72","subject":"md6","topic":"眼科-角膜結膜眼瞼眼窩","meta":"108年第2次第72題","year":108,"session":2,"number":72,"question":"40歲女性患者，主訴幾個月來左眼視力逐漸減退，接受磁振造影檢查，圖為注射顯影劑後並且經過抑制脂肪處理的T1加權影像，圖中箭號所指最可能的病變是：","options":["(A) 視神經膠質瘤（optic nerve glioma）","(B) 視神經鞘腦膜瘤（optic nerve sheath meningioma）","(C) 視神經炎（optic neuritis）","(D) 眼窩假性腫瘤（orbital pseudotumor）"],"answer":1,"image":"md6-108-2-72.jpeg"},{"id":"md6-108-2-73","subject":"md6","topic":"復健-神經復健","meta":"108年第2次第73題","year":108,"session":2,"number":73,"question":"關於腦部動脈瘤的蜘蛛網膜下腔出血（SAH），下列何者錯誤？","options":["(A) 蜘蛛網膜下腔出血較集中處常與動脈瘤的位置有關","(B) 蜘蛛網膜下腔出血所造成的腦血管收縮（vasospasm），通常在前三天最嚴重","(C) 電腦斷層血管影像（CTA）在診斷大於2 mm的腦動脈瘤有超過90%的敏感度","(D) 蜘蛛網膜下腔出血可造成交通性水腦（communicating hydrocephalus）"],"answer":1,"image":""},{"id":"md6-108-2-74","subject":"md6","topic":"婦科-生殖道感染與先天異常","meta":"108年第2次第74題","year":108,"session":2,"number":74,"question":"一位年輕女性磁振造影檢查呈現如圖，箭號所指之敘述何者最正確？","options":["(A) 雙角子宮","(B) 雙子宮","(C) 子宮經血滯留","(D) 單角子宮"],"answer":0,"image":"md6-108-2-74.jpeg"},{"id":"md6-108-2-75","subject":"md6","topic":"眼科-角膜結膜眼瞼眼窩","meta":"108年第2次第75題","year":108,"session":2,"number":75,"question":"一位25歲男性，摩托車騎士，因酒後不慎撞上安全島，顏面挫傷送至急診時，病人抱怨眼眶周圍疼痛、眼瞼有瘀血且浮腫。下列有關Blowout fracture的敘述，何者錯誤？","options":["(A) Waters' view及Caldwell view檢查可助於評估眼底骨折","(B) frontal sinus比maxillary sinus更容易積血","(C) Blowout fracture主要因orbital floor太薄弱導致","(D) 常伴隨有複視現象（diplopia）"],"answer":1,"image":""},{"id":"md6-108-2-76","subject":"md6","topic":"耳科學","meta":"108年第2次第76題","year":108,"session":2,"number":76,"question":"一位38歲男性病人，因突然左耳聽不到任何聲音至急診求診，經診斷為突發性耳聾（sudden hearing loss）。關於此病之敘述下列何者正確？","options":["(A) 定義為一個月內發生之聽力喪失","(B) 發生機率和年紀無關","(C) 大部分突發性耳聾的原因為原發性（idiopathic）","(D) 腮腺炎已證實和造成此病無關"],"answer":2,"image":""},{"id":"md6-108-2-77","subject":"md6","topic":"產科-高危險妊娠","meta":"108年第2次第77題","year":108,"session":2,"number":77,"question":"一位35歲懷孕28週婦女，因血壓過高至急診就診，經評估後懷疑是子癲前症（pre-eclampsia）。下列何者不是此病之臨床表現？","options":["(A) 高血壓（hypertension）","(B) 蛋白尿（proteinuria）","(C) 寡尿（oliguria）","(D) 癲癇（seizure）"],"answer":3,"image":""},{"id":"md6-108-2-78","subject":"md6","topic":"醫學倫理與法規","meta":"108年第2次第78題","year":108,"session":2,"number":78,"question":"安排病人接受白內障手術前，需要跟病人詳細說明手術的內容及其效益與風險，並在確認病人瞭解及同意後，再請病人簽署手術知情同意書（informed consent），這種作法最主要是在確保：","options":["(A) 病人自主","(B) 病人隱私","(C) 資源浪費","(D) 公平正義"],"answer":0,"image":""},{"id":"md6-108-2-79","subject":"md6","topic":"醫學倫理與法規","meta":"108年第2次第79題","year":108,"session":2,"number":79,"question":"一位80歲的老人因顱內血管破裂而住入加護病房，病人此時神智不清、昏迷指數只剩三分。病人有一兒子，兩人沒有住在一起，感情並不親密。病人之前神智清楚時曾書面指定隔壁鄰居為醫療委任代理人，此時面臨拔管的決定，依我國相關法令，下列何者正確？","options":["(A) 兒子為唯一醫療代理人","(B) 隔壁鄰居為唯一醫療代理人","(C) 兒子和隔壁鄰居應為共同代理","(D) 兒子和隔壁鄰居都不得代理決定"],"answer":1,"image":""},{"id":"md6-108-2-80","subject":"md6","topic":"醫學倫理與法規","meta":"108年第2次第80題","year":108,"session":2,"number":80,"question":"病人為51歲男性，一年前開始有忌妒妄想，認為教會中的長者在追求他的太太，並指使她要和病人離婚，因此病人非常的生氣，除了當眾與教會的長者發生衝突外，也會脅迫太太。病人離群索居，沒有工作，日常生活希望他太太儘量不要離開他的視線，也會到她工作的場所偷偷監視，同時每天撰寫著教會長者的「罪行」分送親友。病人除了忌妒妄想外，還有一些怪異的宗教幻想。由於其暴力傾向越來越明顯，他的太太非常害怕回家，唯恐被病人殺害，因此求助於醫師。在此種情況下，下列處置何者最不適當？","options":["(A) 直接開立抗精神病藥滴劑給病人家屬，以便其讓病人服用","(B) 強制病人住院接受治療","(C) 提供家屬可以利用的社會資源及管道","(D) 考慮到病人及家屬安全，通知相關社工或警政單位"],"answer":0,"image":""},{"id":"md6-109-1-1","subject":"md6","topic":"麻醉-呼吸道與監視","meta":"109年第1次第1題","year":109,"session":1,"number":1,"question":"執行全身麻醉誘導前，應評估病人是否有困難通氣之可能，下列何者最不可能是預期困難通氣之病人？","options":["(A) 風濕性心臟病的病人","(B) 唐氏綜合症的病人","(C) 類風濕性關節炎的病人","(D) 阻塞性睡眠呼吸中止症的病人"],"answer":0,"image":""},{"id":"md6-109-1-2","subject":"md6","topic":"麻醉-呼吸道與監視","meta":"109年第1次第2題","year":109,"session":1,"number":2,"question":"Pulse oximetry（SpO）為最普遍的生理監測，關於pulse oximetry的敘述，下列何者正確？2","options":["(A) SpO可以提供一個連續性、非侵入性的監測，且不受指甲顏色的影響2","(B) SpO主要靠oxyhemoglobin（OHb）和deoxyhemoglobin（deOHb）在紅光（波長660nm）與遠紅外線222 infrared（波長940nm）的吸收不同而區分","(C) 一氧化碳中毒時Carboxyhemoglobin（COHb）會使SpO的數值低於SaO，造成誤判22","(D) SpO是預測SaO的方法，SpO大於90%時，代表組織一定無缺氧狀況222"],"answer":1,"image":""},{"id":"md6-109-1-3","subject":"md6","topic":"麻醉-呼吸道與監視","meta":"109年第1次第3題","year":109,"session":1,"number":3,"question":"下列有關使用心臟節律器（pacemaker）的病人，進行麻醉前評估與準備之敘述，何者錯誤？","options":["(A) 進行非心臟常規手術前，應重新檢查心臟節律器的功能","(B) 置放磁鐵於麻醉中的病人之胸前pacemaker上，即可完全避免術中電燒的干擾與危害","(C) 術中應關閉心電圖監視器上filter的功能，以免偵測不到節律放電波形（pacing spikes）","(D) 術中除使用心電圖監視器外，應配合使用脈動式血氧飽和監測儀（pulse oximetry）"],"answer":1,"image":""},{"id":"md6-109-1-4","subject":"md6","topic":"麻醉-麻醉藥理","meta":"109年第1次第4題","year":109,"session":1,"number":4,"question":"下列何藥物對鎮靜劑midazolam具有拮抗作用，會競爭中樞神經系統的受體，以舒緩過量midazolam所造成的呼吸影響？","options":["(A) flumazenil","(B) dexmedetomidine","(C) ketamine","(D) naloxone"],"answer":0,"image":""},{"id":"md6-109-1-5","subject":"md6","topic":"麻醉-麻醉藥理","meta":"109年第1次第5題","year":109,"session":1,"number":5,"question":"下列有關鴉片類藥物（opioids）的敘述，何者錯誤？","options":["(A) 其受體包含mu、kappa、delta與sigma受體","(B) 所有opioid受體與G蛋白（G proteins）結合","(C) 嗎啡引起的呼吸抑制是經由kappa受體","(D) naloxone是一種opioid受體拮抗劑（antagonist）"],"answer":2,"image":""},{"id":"md6-109-1-6","subject":"md6","topic":"麻醉-呼吸道與監視","meta":"109年第1次第6題","year":109,"session":1,"number":6,"question":"下列何者不是美國麻醉醫學會預防手術中周邊神經受損的建議？","options":["(A) 術前確認患者是否可以容忍預期的手術擺位","(B) 側躺的病人使用胸捲軸（chest rolls）可以降低神經受損的風險","(C) 採碎石姿勢（lithotomy）過度拉扯腿後肌群（hamstring muscle group），會增加股神經受損的風險","(D) 手肘屈曲可能會增加尺神經受損的風險"],"answer":2,"image":""},{"id":"md6-109-1-7","subject":"md6","topic":"產科-高危險妊娠","meta":"109年第1次第7題","year":109,"session":1,"number":7,"question":"有關子癲前症（preeclampsia），下列敘述何者錯誤？","options":["(A) 過去血壓正常的婦女，懷孕20週後收縮壓高於140 mmHg或舒張壓高於90 mmHg且合併有蛋白尿，即可診斷為preeclampsia","(B) preeclampsia會增加腦出血（cerebral hemorrhage）、肺水腫（pulmonary edema）及凝血功能異常（coagulopathy）的危險。當收縮壓高於160 mmHg時就應積極控制血壓預防腦出血","(C) magnesium sulfate常用於預防seizure的發生，在插管全身麻醉使用非去極化肌肉鬆弛劑（如：rocuronium）應減少其劑量","(D) 生產後可以照一般常規使用methylergonovine來促進子宮收縮"],"answer":3,"image":""},{"id":"md6-109-1-8","subject":"md6","topic":"麻醉-特殊麻醉與疼痛","meta":"109年第1次第8題","year":109,"session":1,"number":8,"question":"Pregabalin產生止痛作用的相關離子通道為何？","options":["(A) sodium channel","(B) calcium channel","(C) chloride channel","(D) potassium channel"],"answer":1,"image":""},{"id":"md6-109-1-9","subject":"md6","topic":"麻醉-呼吸道與監視","meta":"109年第1次第9題","year":109,"session":1,"number":9,"question":"外科加護病房的術後病人，第二天早上嘗試脫離呼吸機（weaning），下列指標數值，何者最不適合考慮拔管？","options":["(A) 潮氣容積（tidal volume）＞5 mL/kg，肺活量（vital capacity）＞10 mL/kg","(B) 淺快呼吸指標（rapid shallow breathing index）＞105","(C) 最大吸氣壓力（maximal inspiratory pressure）＜-25 cmHO 2","(D) 給與FiO 40～50%且吐氣末正壓（positive end expiratory pressure）＜5 cmHO時，測得動脈血氧飽和度22（SaO）＞90% 2"],"answer":1,"image":""},{"id":"md6-109-1-10","subject":"md6","topic":"眼科-視網膜葡萄膜","meta":"109年第1次第10題","year":109,"session":1,"number":10,"question":"色素性視網膜炎（retinitis pigmentosa）的典型三特徵（classical triad）不包含：","options":["(A) 骨刺狀黑色素沉積（retinal bone-spicule pigmentation）","(B) 視神經蒼白化（waxy pallor of the optic disc）","(C) 小動脈變細（arteriolar attenuation）","(D) 黃斑部水腫（macular edema）"],"answer":3,"image":""},{"id":"md6-109-1-11","subject":"md6","topic":"眼科-角膜結膜眼瞼眼窩","meta":"109年第1次第11題","year":109,"session":1,"number":11,"question":"下列關於角膜之鹼性化學灼傷（alkaline burns）的敘述，何者正確？","options":["(A) 一般而言，與酸性化學灼傷（acid burns）比較，鹼性化學灼傷（alkaline burns）預後較佳","(B) 儘速以酸性水溶液沖洗眼睛，以中和鹼性傷害","(C) 前10天絕對禁止類固醇使用，避免抑制傷口癒合","(D) 角膜輪部缺血（limbal ischaemia）程度是影響視力預後的重要因子"],"answer":3,"image":""},{"id":"md6-109-1-12","subject":"md6","topic":"眼科-角膜結膜眼瞼眼窩","meta":"109年第1次第12題","year":109,"session":1,"number":12,"question":"頸動脈海綿竇瘻管（carotid cavernous fistula）的病人，其結膜可能出現下列何種表徵？","options":["(A) 鮭色斑（salmon patch）","(B) 卡波西氏肉瘤（Kaposi’s sarcoma）","(C) 結膜及上鞏膜血管曲張（corkscrew-like vessels）","(D) 微小動脈瘤（microaneurysm）"],"answer":2,"image":""},{"id":"md6-109-1-13","subject":"md6","topic":"眼科-水晶體青光眼","meta":"109年第1次第13題","year":109,"session":1,"number":13,"question":"下列何者用來治療白內障手術後產生的水晶體後囊混濁（posterior capsular opacity）？","options":["(A) 銣雅鉻雷射（Nd:YAG laser)","(B) 超音波晶體乳化術（phacoemulsification)","(C) 人工水晶體","(D) 人工玻璃體"],"answer":0,"image":""},{"id":"md6-109-1-14","subject":"md6","topic":"眼科-屈光斜弱視","meta":"109年第1次第14題","year":109,"session":1,"number":14,"question":"眼球要往外上方（temporal upper）看時，須靠外直肌（lateral rectus muscle）和下列何條眼外肌共同作用？","options":["(A) 上直肌（superior rectus muscle）","(B) 上斜肌（superior oblique muscle）","(C) 下直肌（inferior rectus muscle）","(D) 下斜肌（inferior oblique muscle）"],"answer":0,"image":""},{"id":"md6-109-1-15","subject":"md6","topic":"眼科-屈光斜弱視","meta":"109年第1次第15題","year":109,"session":1,"number":15,"question":"下列有關眼球運動的敘述，何者錯誤？","options":["(A) duction是指單眼的運動，包括眼球的內旋（intorsion）和外旋（exotorsion）","(B) version是指雙眼的同向運動，包括看右上（dextro-elevation）或左下（levo-depression）等","(C) vergence是指雙眼的異向運動，包括會聚（convergence）或散開（divergence）等","(D) 調節性會聚（accommodative convergence）屬於一種強直性會聚（tonic convergence）"],"answer":3,"image":""},{"id":"md6-109-1-16","subject":"md6","topic":"眼科-視網膜葡萄膜","meta":"109年第1次第16題","year":109,"session":1,"number":16,"question":"脈絡膜先天性缺損（coloboma of the uveal tract）通常發生在眼球的幾點鐘部位？","options":["(A) 3點鐘","(B) 6點鐘","(C) 9點鐘","(D) 12點鐘"],"answer":1,"image":""},{"id":"md6-109-1-17","subject":"md6","topic":"眼科-角膜結膜眼瞼眼窩","meta":"109年第1次第17題","year":109,"session":1,"number":17,"question":"關於砂眼（trachoma）的敘述，下列何者錯誤？","options":["(A) 病原菌為披衣菌（Chlamydia）","(B) 瘢痕性砂眼（cicatricial trachoma）可在上眼瞼結膜（superior palpebral conjunctiva）看見Arlt line","(C) 結膜細胞的細胞核內有嗜伊紅性包涵體（eosinophilic inclusion bodies）","(D) 藥物治療可以口服四環黴素和局部四環黴素合併治療為選項之一"],"answer":2,"image":""},{"id":"md6-109-1-18","subject":"md6","topic":"眼科-角膜結膜眼瞼眼窩","meta":"109年第1次第18題","year":109,"session":1,"number":18,"question":"下列關於新生兒淋病性結膜炎（neonatal gonococcal conjunctivitis）的敘述，何者錯誤？","options":["(A) 常是由母親經產道感染給新生兒","(B) 須同時給予局部及全身抗生素治療","(C) 膿狀分泌物大約在出生後第三周至第四周間開始出現","(D) 最好要對其分泌物作抹片及細菌培養等檢查"],"answer":2,"image":""},{"id":"md6-109-1-19","subject":"md6","topic":"耳科學","meta":"109年第1次第19題","year":109,"session":1,"number":19,"question":"耳蝸中階（scala media）含內淋巴液（endolymph），其內耳蝸電位（endocochlear potential）為+80 mV，係來自下列何構造？","options":["(A) 血管紋（stria vascularis）","(B) 瑞氏膜（Reissner membrane）","(C) 基底膜（basilar membrane）","(D) 柯蒂氏器（organ of Corti）"],"answer":0,"image":""},{"id":"md6-109-1-20","subject":"md6","topic":"耳科學","meta":"109年第1次第20題","year":109,"session":1,"number":20,"question":"病人耳鏡檢查所見如下圖，最可能之診斷為：","options":["(A) 先天性膽脂瘤（congenital cholesteatoma）","(B) 原發性後天性膽脂瘤（primary acquired cholesteatoma）","(C) 繼發性後天性膽脂瘤（secondary acquired cholesteatoma）","(D) 耳道膽脂瘤（ear canal cholesteatoma）"],"answer":1,"image":"md6-109-1-20.jpeg"},{"id":"md6-109-1-21","subject":"md6","topic":"耳科學","meta":"109年第1次第21題","year":109,"session":1,"number":21,"question":"下列何者為最常見之急性顏面神經麻痺原因？","options":["(A) Ramsay Hunt症候群","(B) 貝爾氏麻痺（Bell palsy）","(C) 顱底骨髓炎（skull base osteomyelitis）","(D) 顳骨骨折（temporal bone fracture）"],"answer":1,"image":""},{"id":"md6-109-1-22","subject":"md6","topic":"鼻科學","meta":"109年第1次第22題","year":109,"session":1,"number":22,"question":"有關過敏原皮膚測試的優點，不包含下列那一項？","options":["(A) 高敏感度","(B) 可迅速得到結果","(C) 費用低廉","(D) 受試者使用藥物不影響測試結果"],"answer":3,"image":""},{"id":"md6-109-1-23","subject":"md6","topic":"喉科學與頭頸腫瘤","meta":"109年第1次第23題","year":109,"session":1,"number":23,"question":"關於阻塞性睡眠呼吸中止症（obstructive sleep apnea syndrome）之檢查與治療，下列何者正確？","options":["(A) 多項睡眠檢查（polysomnography）之異常標準為：每小時出現10次以上，每次超過5秒以上之呼吸中斷或減弱","(B) 呼吸道阻塞位置最常發生在舌根","(C) 鼻部連續陽壓呼吸（nasal continuous positive airway pressure）可作為大部分病人之標準治療","(D) 扁桃腺與腺樣體切除（adenotonsillectomy）為成年病人治療之首選"],"answer":2,"image":""},{"id":"md6-109-1-24","subject":"md6","topic":"喉科學與頭頸腫瘤","meta":"109年第1次第24題","year":109,"session":1,"number":24,"question":"56歲男性，因聲音沙啞就診，經咽喉內視鏡檢查發現一腫塊如下圖所示，下列敘述何者正確？","options":["(A) 與長期嚼檳榔密切相關","(B) 箭頭所指腫瘤位於上聲門區（supraglottis）","(C) 此類之喉部腫瘤常伴隨頸部淋巴結轉移","(D) 如經切片證實為鱗狀上皮細胞癌，則可考慮手術切除或放射線治療"],"answer":3,"image":"md6-109-1-24.jpeg"},{"id":"md6-109-1-25","subject":"md6","topic":"喉科學與頭頸腫瘤","meta":"109年第1次第25題","year":109,"session":1,"number":25,"question":"一中年男性晚飯後出現喉痛、吞嚥困難等症狀就診，頸部X光如下圖，下列敘述何者正確？","options":["(A) 頸部X光可見異物位於會厭軟骨處","(B) 可於局部麻醉下以硬式食道鏡移除異物","(C) 硬式食道鏡術後發生併發症之機率與軟式食道鏡相近","(D) 食道鏡術中如發現疑似食道破裂，應立即放置鼻胃管並囑咐病人不得經口進食"],"answer":3,"image":"md6-109-1-25.jpeg"},{"id":"md6-109-1-26","subject":"md6","topic":"喉科學與頭頸腫瘤","meta":"109年第1次第26題","year":109,"session":1,"number":26,"question":"一舌癌病人，腫瘤大小為4.5 × 2.5公分，舌部活動正常且未侵犯鄰近構造。同側頸部有一4公分的轉移淋巴結，但無明顯淋巴結外侵犯（extranodal extension）情形。依據AJCC第7版（或第8版）的癌症分期系統，其臨床分期應為：","options":["(A) T2N1，stage III","(B) T2N2a，stage IVA","(C) T3N1，stage III","(D) T3N2a，stage IVA"],"answer":3,"image":""},{"id":"md6-109-1-27","subject":"md6","topic":"喉科學與頭頸腫瘤","meta":"109年第1次第27題","year":109,"session":1,"number":27,"question":"一70歲男性，有長期菸酒檳榔的使用習慣，因最近常常有間歇性的右耳疼痛情形，但耳部檢查完全正常。在未進行下一步檢查之前，若此症狀與頭頸癌相關，最有可能是下列那個部位的癌症？","options":["(A) 舌癌","(B) 聲門癌","(C) 扁桃腺癌","(D) 頰黏膜癌"],"answer":2,"image":""},{"id":"md6-109-1-28","subject":"md6","topic":"產科-一般產科","meta":"109年第1次第28題","year":109,"session":1,"number":28,"question":"經由病史詢問得知某女性患者曾懷孕過兩次，但這兩次懷孕都因為自然流產而終止妊娠。下列何者最適合用於描繪她的情況？","options":["(A) Multipara","(B) Nulligravida","(C) Nullipara","(D) Primipara"],"answer":2,"image":""},{"id":"md6-109-1-29","subject":"md6","topic":"產科-一般產科","meta":"109年第1次第29題","year":109,"session":1,"number":29,"question":"羊水的酸鹼值（pH）最常介於那個酸鹼值（pH）區段？","options":["(A) 4.5～5.5","(B) 5.6～6.5","(C) 7.0～7.5","(D) 8.0～8.5"],"answer":2,"image":""},{"id":"md6-109-1-30","subject":"md6","topic":"產科-一般產科","meta":"109年第1次第30題","year":109,"session":1,"number":30,"question":"下列那一種方式不是處理肩難產的方法？","options":["(A) Woods corkscrew maneuver","(B) Fundal pressure","(C) McRoberts maneuver","(D) Delivery of the posterior shoulder"],"answer":1,"image":""},{"id":"md6-109-1-31","subject":"md6","topic":"產科-一般產科","meta":"109年第1次第31題","year":109,"session":1,"number":31,"question":"產後噴乳反射（milk ejection）是因何者引起？","options":["(A) 泌乳素（prolactin）","(B) 催產素（oxytocin）","(C) 前列腺素（prostaglandin）","(D) 多巴胺（dopamine）"],"answer":1,"image":""},{"id":"md6-109-1-32","subject":"md6","topic":"產科-高危險妊娠","meta":"109年第1次第32題","year":109,"session":1,"number":32,"question":"35歲孕婦，G2P1，妊娠42週，催生前接受NST檢查（nonstress test），結果如圖所示：其判讀為何？（提示：FM為胎動）","options":["(A) Early deceleration","(B) Late deceleration","(C) Reactive","(D) Nonreactive"],"answer":3,"image":"md6-109-1-32.jpeg"},{"id":"md6-109-1-33","subject":"md6","topic":"產科-高危險妊娠","meta":"109年第1次第33題","year":109,"session":1,"number":33,"question":"30歲女性，G1P0，妊娠36週，胎兒呼吸次數於30分鐘超音波監視下有五次，每次持續30秒以上，依胎兒生物生理計分法（biophysical profile），於胎兒呼吸分項下得分為何？","options":["(A) 0","(B) 1","(C) 2","(D) 3"],"answer":2,"image":""},{"id":"md6-109-1-34","subject":"md6","topic":"婦科-尿失禁與骨盆腔脫垂","meta":"109年第1次第34題","year":109,"session":1,"number":34,"question":"下列那一種urinary incontinence於女性最常見？","options":["(A) 急迫性尿失禁（urge urinary incontinence）","(B) 應力性尿失禁（stress urinary incontinence）","(C) 混合型尿失禁（mixed incontinence）","(D) 溢流型尿失禁（overflow incontinence）"],"answer":1,"image":""},{"id":"md6-109-1-35","subject":"md6","topic":"婦科-手術學與診斷技術","meta":"109年第1次第35題","year":109,"session":1,"number":35,"question":"婦科手術後，若有敗血症（septicemia）引起alveolar-capillary membrane的微血管側受損，使肺部微血管通透性增加，而造成肺部的併發症，稱為：","options":["(A) Pulmonary edema","(B) Pulmonary hypertension","(C) Respiratory permeability defect","(D) Acute respiratory distress syndrome"],"answer":3,"image":""},{"id":"md6-109-1-36","subject":"md6","topic":"婦科-生殖內分泌","meta":"109年第1次第36題","year":109,"session":1,"number":36,"question":"無精蟲症是男性不孕症原因之一，如精液檢驗發現無精蟲症時，下列何者為最佳做法？","options":["(A) 解釋無精蟲症可能原因之後，休息數星期後再次檢驗精液或抽血檢查","(B) 安排睪丸切片，用以分析阻塞性或非阻塞性無精蟲症","(C) 安排單一精蟲注射試管嬰兒","(D) 告知領養小孩是唯一選擇"],"answer":0,"image":""},{"id":"md6-109-1-37","subject":"md6","topic":"婦科-生殖內分泌","meta":"109年第1次第37題","year":109,"session":1,"number":37,"question":"有關無月經（amenorrhea）的敘述，下列何者錯誤？","options":["(A) 定義為2個月月經沒來","(B) 須要先排除懷孕的可能性","(C) 解剖結構上的異常造成無月經的比例相對較少","(D) 高泌乳血症（hyperprolactinemia）有可能造成無月經"],"answer":0,"image":""},{"id":"md6-109-1-38","subject":"md6","topic":"婦科-生殖內分泌","meta":"109年第1次第38題","year":109,"session":1,"number":38,"question":"口服排卵藥clomiphene citrate，對下列何者一定無效？","options":["(A) Hypothalamic-pituitary dysfunction","(B) Hypothalamic-pituitary failure","(C) 多囊性卵巢症候群","(D) 子宮內膜異位症"],"answer":1,"image":""},{"id":"md6-109-1-39","subject":"md6","topic":"婦科-腫瘤","meta":"109年第1次第39題","year":109,"session":1,"number":39,"question":"王女士，48歲，過去除自然生產兩次外無特殊疾病史，因陰道大量出血至急診求診，經內診發現子宮頸有一7公分腫瘤，切片證實為子宮頸鱗狀上皮癌，腫瘤範圍至下1/3陰道後壁，子宮旁組織柔軟無侵犯跡象，胸部X光正常，腎盂攝影並無顯示腎盂或輸尿管水腫，電腦斷層未見淋巴結腫大，依據目前國際婦產科聯盟（International Federation of Gynecology and Obstetrics, FIGO）分期，王女士子宮頸癌臨床期別為何？","options":["(A) Ib3","(B) IIa2","(C) IIb","(D) IIIa"],"answer":3,"image":""},{"id":"md6-109-1-40","subject":"md6","topic":"產科-高危險妊娠","meta":"109年第1次第40題","year":109,"session":1,"number":40,"question":"28歲孕婦，G1P0，無家族病史，目前懷孕12週，經與婦產科醫師諮詢後，決定接受第一孕期母血唐氏症篩檢（first-trimester maternal serum Down screen），因而接受抽血檢驗及超音波檢查。下列何者不是第一孕期母血唐氏症篩檢所包含之項目？","options":["(A) Human chorionic gonadotropin（hCG）or free β-hCG（free β-subunit hCG）","(B) Nuchal translucency（NT）","(C) Unconjugated estriol（uE3）","(D) Pregnancy-associated plasma protein-A（PAPP-A）"],"answer":2,"image":""},{"id":"md6-109-1-41","subject":"md6","topic":"產科-高危險妊娠","meta":"109年第1次第41題","year":109,"session":1,"number":41,"question":"妊娠28週的雙胞胎，常規超音波檢查發現，雙胞胎A預估體重1,200公克，雙胞胎B預估體重750公克；雙胞胎A為羊水過多（polyhydramnios），雙胞胎B則為羊水稀少（oligohydramnios）。關於此一雙胞胎妊娠的超音波影像敘述，下列何者正確？","options":["(A) 雙胞胎之捐贈者（donor twin）發生羊水過多的機率高於雙胞胎之受贈者（recipient twin）","(B) 雙胞胎之捐贈者往往會發生溶血性貧血症（hemolytic anemia）","(C) 雙胞胎之捐贈者往往會發生紅血球增多症（polycythemia）","(D) 超音波可觀察出雙胞胎之捐贈者與雙胞胎之受贈者之間的表徵（phenotype）差異"],"answer":3,"image":""},{"id":"md6-109-1-42","subject":"md6","topic":"產科-高危險妊娠","meta":"109年第1次第42題","year":109,"session":1,"number":42,"question":"32歲G1P0孕婦，妊娠29週被診斷為子癇前症（preeclampsia），現妊娠35週主訴近3天來常感頭暈前來求診。理學檢查，血壓172/116 mmHg，體重較兩週前增加3 kg，尿蛋白3+；超音波檢查預估胎兒體重1,900公克，有不規則子宮收縮。此時的最佳處置為：","options":["(A) 積極治療高血壓並安排門診追蹤","(B) 積極進行胎兒健康評估並安排門診追蹤","(C) 同時治療高血壓及進行胎兒健康評估並安排門診追蹤","(D) 建議立即住院接受治療"],"answer":3,"image":""},{"id":"md6-109-1-43","subject":"md6","topic":"婦科-手術學與診斷技術","meta":"109年第1次第43題","year":109,"session":1,"number":43,"question":"如圖所示，為laparoscopic Burch colposuspension雙側陰道旁筋膜（paravaginal fascia）懸吊後之腹腔鏡手術圖片，iliopectineal ligament（Cooper's ligament）為圖中下列何者文字標示之處？","options":["(A) A","(B) B","(C) C","(D) D"],"answer":2,"image":"md6-109-1-43.jpeg"},{"id":"md6-109-1-44","subject":"md6","topic":"婦科-手術學與診斷技術","meta":"109年第1次第44題","year":109,"session":1,"number":44,"question":"有關早期懷孕的敘述，下列何者錯誤？","options":["(A) 骨盆腔發炎是子宮外孕的危險因子","(B) 輸卵管子宮外孕接受methotrexate（MTX）治療的病患，比接受輸卵管造口術（salpingostomy）治療的病患再次外孕的風險尤高","(C) 正常6週內子宮內懷孕，血中hCG 48小時至少要增加66%以上","(D) 當血中hCG超過2,000 mIU/mL，隔48小時增加不到50%，胚胎存活的機會低"],"answer":1,"image":""},{"id":"md6-109-1-45","subject":"md6","topic":"婦科-良性腫瘤與內膜異位","meta":"109年第1次第45題","year":109,"session":1,"number":45,"question":"31歲女性，長期為經痛所苦，疑似子宮內膜異位症（endometriosis），下列何者為確定診斷的方式？","options":["(A) 超音波影像","(B) 理學檢查（內診）判定","(C) 測血中CA-125值高","(D) 腹腔鏡下切片"],"answer":3,"image":""},{"id":"md6-109-1-46","subject":"md6","topic":"婦科-腫瘤","meta":"109年第1次第46題","year":109,"session":1,"number":46,"question":"關於卵巢上皮癌（epithelial ovarian cancer）的敘述，下列何者最不適當？","options":["(A) 病理診斷卵巢亦有子宮內膜異位（endometriosis）時，如果亦有卵巢上皮癌的診斷，一般常見的型態為清亮細胞（clear cell）或者類子宮內膜亞型（endometrioid subtype）","(B) 類子宮內膜型（endometrioid type）的卵巢上皮癌，與其他形態卵巢上皮癌比較，有較多的機會同時伴隨子宮內膜癌的發生","(C) 所有的清亮細胞卵巢上皮癌（clear cell）的細胞分化，都歸類為最差的分化（grade 3）","(D) 漿液性（serous）卵巢上皮癌中，如見到大量沙狀瘤體（psammoma body），代表預後極差"],"answer":3,"image":""},{"id":"md6-109-1-47","subject":"md6","topic":"婦科-腫瘤","meta":"109年第1次第47題","year":109,"session":1,"number":47,"question":"有關非上皮性卵巢癌的病理敘述如下：The large round, ovoid, or polygonal cell have abundant, clear, vary-pale- staining cytoplasm, large and irregular nuclei, and prominent nucleoli，為那種腫瘤的診斷？","options":["(A) 卵巢支持間質細胞瘤（Sertoli-Leydig cell tumor）","(B) 無性胚胎瘤（dysgerminoma）","(C) 成人型卵巢顆粒性細胞瘤（adult-type granulosa cell tumor）","(D) 卵巢內胚層竇瘤（endodermal sinus tumor）"],"answer":1,"image":""},{"id":"md6-109-1-48","subject":"md6","topic":"婦科-生殖內分泌","meta":"109年第1次第48題","year":109,"session":1,"number":48,"question":"關於卵巢週期與子宮內膜週期之敘述，下列何者錯誤？","options":["(A) 卵巢的濾泡期（follicular phase）相當於子宮內膜的增生期（proliferative phase）","(B) 卵巢的黃體期（luteal phase）相當於子宮內膜的增生期（proliferative phase）","(C) 卵巢的黃體期（luteal phase）相當於子宮內膜的分泌期（secretary phase）","(D) 排卵後之黃體化顆粒細胞會製造及分泌黃體素"],"answer":1,"image":""},{"id":"md6-109-1-49","subject":"md6","topic":"婦科-生殖內分泌","meta":"109年第1次第49題","year":109,"session":1,"number":49,"question":"關於性激素（sex hormones）的類固醇合成（steroidogenesis）之敘述，下列何者錯誤？","options":["(A) 雌激素（estrogens）、雄性素（androgens）與黃體素（progesterone）都是由膽固醇（cholesterol）轉化而來","(B) 濾泡周圍的卵囊膜細胞（theca cells）製造雄性素（androgens）是經由FSH的刺激","(C) 雌激素（estrogens）是由雄性素（androgens）在芳香環轉化酶（aromatase）的作用下轉化而來","(D) 黃體素（progesterone）是含有21個碳原子的類固醇，雄性素（androgens）是含有19個碳原子的類固醇，而雌激素（estrogens）是含有18個碳原子的分子"],"answer":1,"image":""},{"id":"md6-109-1-50","subject":"md6","topic":"婦科-生殖內分泌","meta":"109年第1次第50題","year":109,"session":1,"number":50,"question":"激素（hormones）的激發生理功能，必須先作用於受體（receptor）上，關於激素與受體之敘述，下列何者錯誤？","options":["(A) 類固醇激素（steroid hormones）的受體存在於細胞核中","(B) 蛋白質性激素（peptide hormones）的受體存在於細胞膜上","(C) 人類絨毛膜性腺刺激素（hCG）的受體存在於細胞核中","(D) 甲狀腺激素（thyroid hormone）的受體存在於細胞核中"],"answer":2,"image":""},{"id":"md6-109-1-51","subject":"md6","topic":"婦科-生殖內分泌","meta":"109年第1次第51題","year":109,"session":1,"number":51,"question":"關於GnRH（gonadotropin releasing hormone）之敘述，下列何者錯誤？","options":["(A) GnRH無法刺激腦下垂體分泌FSH，只能刺激腦下垂體分泌LH","(B) GnRH的分泌是脈衝性的方式（pulsatile fashion），也就是每隔一段時間才會分泌一次","(C) GnRH是含有10個胺基酸的蛋白質分子","(D) GnRH在體內代謝的半衰期很短，只有2～4分鐘"],"answer":0,"image":""},{"id":"md6-109-1-52","subject":"md6","topic":"婦科-生殖內分泌","meta":"109年第1次第52題","year":109,"session":1,"number":52,"question":"造成不孕症的原因，下列何者相對上發生不孕症狀的比率較少？","options":["(A) 排卵障礙","(B) 輸卵管阻塞","(C) 子宮肌瘤","(D) 男性因素"],"answer":2,"image":""},{"id":"md6-109-1-53","subject":"md6","topic":"婦科-生殖內分泌","meta":"109年第1次第53題","year":109,"session":1,"number":53,"question":"22歲尚未有性經驗的女生，因為近一年內體重不斷增加而求診。身高150公分，目前體重80公斤，過去的一年月經都延遲相當久才來，最長的一次達3個月。經腹部超音波量測竇室濾泡數（antral follicle count）為20，子宮內膜厚度為15 mm，目前沒有交往對象也尚無生育考量。下列建議何者最不合適？","options":["(A) 給予排卵藥","(B) 給予黃體素","(C) 建議積極減重和調整生活及飲食習慣","(D) 建議做糖尿病及胰島素抗性篩檢"],"answer":0,"image":""},{"id":"md6-109-1-54","subject":"md6","topic":"婦科-生殖內分泌","meta":"109年第1次第54題","year":109,"session":1,"number":54,"question":"當女性處於月經週期的濾泡期（follicular phase），hormone X的增加會負回饋抑制FSH的分泌；持續高濃度的hormone Y可誘發LH surge；hormone Z促使primary oocyte轉變成secondary oocyte。下列敘述何者正確？","options":["(A) Hormone X即是hormone Y","(B) Hormone Y即是hormone Z","(C) Hormone X即是hormone Z","(D) Hormone X是inhibin-A"],"answer":0,"image":""},{"id":"md6-109-1-55","subject":"md6","topic":"婦科-生殖內分泌","meta":"109年第1次第55題","year":109,"session":1,"number":55,"question":"下列何者為不需取卵的人工輔助生殖技術？","options":["(A) 人工授精（intrauterine insemination）","(B) 試管嬰兒（in vitro fertilization）","(C) 卵細胞質內精蟲注射（intracytoplasmic sperm injection）","(D) 胚胎著床前基因診斷（preimplantation genetic diagnosis）"],"answer":0,"image":""},{"id":"md6-109-1-56","subject":"md6","topic":"產科-高危險妊娠","meta":"109年第1次第56題","year":109,"session":1,"number":56,"question":"24歲孕婦，G3P0，妊娠38週，接受胎兒杜卜勒超音波檢查，結果如圖所示，檢查名稱為何？","options":["(A) 臍動脈血流速度波形","(B) 臍靜脈血流速度波形","(C) 胎兒中大腦動脈血流速度波形","(D) 胎兒下行主動脈血流速度波形"],"answer":0,"image":"md6-109-1-56.jpeg"},{"id":"md6-109-1-57","subject":"md6","topic":"產科-高危險妊娠","meta":"109年第1次第57題","year":109,"session":1,"number":57,"question":"承上題，最可能的檢查結果為下列何者？","options":["(A) Absence of end-diastolic velocity","(B) Reversed end-diastolic velocity","(C) Positive","(D) Negative"],"answer":1,"image":""},{"id":"md6-109-1-58","subject":"md6","topic":"復健-神經復健","meta":"109年第1次第58題","year":109,"session":1,"number":58,"question":"關於中風後產生之複雜區域疼痛症候群第一型（complex regional pain syndrome, Type 1），下列身體部位中，何處被影響程度相對較少？","options":["(A) 肩膀","(B) 肘部","(C) 手腕","(D) 手指"],"answer":1,"image":""},{"id":"md6-109-1-59","subject":"md6","topic":"復健-神經復健","meta":"109年第1次第59題","year":109,"session":1,"number":59,"question":"自主神經反射異常（autonomic dysreflexia）為脊髓損傷病人常見之病症，下列敘述何者錯誤？","options":["(A) 較常發生在受傷後一個月內","(B) 主要發生在胸椎第六節以上的完全脊髓損傷患者","(C) 膀胱脹尿是常見的誘因","(D) 發作時，處置方法初步為去除刺激來源"],"answer":0,"image":""},{"id":"md6-109-1-60","subject":"md6","topic":"復健-神經復健","meta":"109年第1次第60題","year":109,"session":1,"number":60,"question":"男性之反射性勃起（reflexogenic erection），是指男性外陰部受外感性刺激所引起，其由何者控制？","options":["(A) 交感神經系統，源自T11-12下腹神經（hypogastric nerve）","(B) 副交感神經系統，源自S2-4骨盆神經（pelvic nerve）","(C) 交感神經系統，源自S2-4骨盆神經（pelvic nerve）","(D) 副交感神經系統，源自T11-12下腹神經（hypogastric nerve）"],"answer":1,"image":""},{"id":"md6-109-1-61","subject":"md6","topic":"復健-神經復健","meta":"109年第1次第61題","year":109,"session":1,"number":61,"question":"一位病人因車禍，3個月後來就診，發現有鷹爪手（claw hand），他最有可能是那條神經病變？","options":["(A) 尺神經","(B) 橈神經","(C) 正中神經","(D) 肌皮神經"],"answer":0,"image":""},{"id":"md6-109-1-62","subject":"md6","topic":"復健-骨骼肌肉損傷與疾患","meta":"109年第1次第62題","year":109,"session":1,"number":62,"question":"在下背痛的篩選中，下列何種症狀代表病人可能是罹患一種嚴重的病變（所謂red flag），須轉介至相關科別做進一步的檢查與處置？","options":["(A) 夜間疼痛且愈來愈嚴重","(B) 病人身體質量指數（BMI）高","(C) 合併下肢疼痛","(D) 曾有腰椎手術病史"],"answer":0,"image":""},{"id":"md6-109-1-63","subject":"md6","topic":"復健-兒童與一般復健","meta":"109年第1次第63題","year":109,"session":1,"number":63,"question":"關於歐氏症（Osgood-Schlatter disease）的敘述，下列何者正確？","options":["(A) 病變處之骨頭可能會有碎裂（fragmentation）現象","(B) 病變處常位於髕骨與髕骨肌腱交接處","(C) 不可使用非類固醇消炎止痛劑","(D) 通常需手術治療"],"answer":0,"image":""},{"id":"md6-109-1-64","subject":"md6","topic":"復健-骨骼肌肉損傷與疾患","meta":"109年第1次第64題","year":109,"session":1,"number":64,"question":"下列何者不是類風濕性關節炎（rheumatoid arthritis）的好發部位？","options":["(A) 腕關節","(B) 肩關節","(C) 腰椎關節","(D) 踝關節"],"answer":2,"image":""},{"id":"md6-109-1-65","subject":"md6","topic":"復健-心肺復健與運動處方","meta":"109年第1次第65題","year":109,"session":1,"number":65,"question":"患者接受心臟復健的絕對禁忌，下列何者正確？","options":["(A) 急性心肌梗塞","(B) 冠狀動脈繞道手術後","(C) 急性心包膜炎或心肌炎","(D) 心臟移植及心肺移植"],"answer":2,"image":""},{"id":"md6-109-1-66","subject":"md6","topic":"復健-心肺復健與運動處方","meta":"109年第1次第66題","year":109,"session":1,"number":66,"question":"心肌的耗氧量（myocardial oxygen consumption）與下列那兩個數值之乘積最具相關性？","options":["(A) 每分鐘心跳數與平均血壓","(B) 每分鐘心跳數與收縮壓","(C) 每分鐘心跳數與舒張壓","(D) 收縮壓與舒張壓"],"answer":1,"image":""},{"id":"md6-109-1-67","subject":"md6","topic":"產科-一般產科","meta":"109年第1次第67題","year":109,"session":1,"number":67,"question":"婦女懷孕時補充攝取以下那一種維生素，已被証實可有效降低生下的小孩罹患神經管缺損（neural tube defects）之機率？","options":["(A) 維生素B（thiamine）1","(B) 維生素B（pyridoxine）6","(C) 維生素B（folic acid）9","(D) 維生素B（cobalamin）12"],"answer":2,"image":""},{"id":"md6-109-1-68","subject":"md6","topic":"復健-兒童與一般復健","meta":"109年第1次第68題","year":109,"session":1,"number":68,"question":"神經管缺損（neural tube defect）的兒童患者，最常影響下列那一個部位的脊椎？","options":["(A) 頸椎（cervical level）","(B) 胸椎（thoracic level）","(C) 胸腰椎（thoracic-lumbar level）","(D) 腰薦椎（lumbar-sacral level）"],"answer":3,"image":""},{"id":"md6-109-1-69","subject":"md6","topic":"復健-神經復健","meta":"109年第1次第69題","year":109,"session":1,"number":69,"question":"舌癌病人接受全舌切除後，在吞嚥時容易有口中食物後送功能不足，下列何種方法對他最恰當？","options":["(A) 進食時，進行孟德森吞嚥手法（Mendelsohn maneuver）","(B) 平時進行Shaker運動（Shaker exercise）","(C) 進食時抬下巴（chin-up）","(D) 平時進行Masako運動（Masako exercise）"],"answer":2,"image":""},{"id":"md6-109-1-70","subject":"md6","topic":"復健-物理因子治療與評估","meta":"109年第1次第70題","year":109,"session":1,"number":70,"question":"病患在接受物理治療後發生如圖的病變，下列那一種治療儀最有可能是原因？","options":["(A) 短波治療儀（short wave diathermy）","(B) 熱敷包（hot packs）","(C) 干擾波（interferential current）","(D) 低能量雷射（low energy laser therapy）"],"answer":1,"image":"md6-109-1-70.jpeg"},{"id":"md6-109-1-71","subject":"md6","topic":"復健-神經復健","meta":"109年第1次第71題","year":109,"session":1,"number":71,"question":"在下列四種神經元受損情況下，那一種最容易產生痙攣型構音障礙（spastic dysarthria）？","options":["(A) 單側上運動神經元（unilateral upper motor neuron）","(B) 單側下運動神經元（unilateral lower motor neuron）","(C) 雙側上運動神經元（bilateral upper motor neuron）","(D) 雙側下運動神經元（bilateral lower motor neuron）"],"answer":2,"image":""},{"id":"md6-109-1-72","subject":"md6","topic":"鼻科學","meta":"109年第1次第72題","year":109,"session":1,"number":72,"question":"關於鼻竇炎（paranasal sinusitis）的影像診斷，下列何者錯誤？","options":["(A) 電腦斷層（CT scan）較X光清楚，但輻射劑量較高","(B) 慢性鼻竇炎且抗生素治療數週無效者，應考慮做電腦斷層檢查","(C) 急性鼻竇炎合併意識不清，以X光的Water's view就足以診斷病灶影響範圍，不必接受電腦斷層檢查","(D) 注射對比劑後之電腦斷層影像有助於排除鼻竇炎合併有腫瘤的可能性"],"answer":2,"image":""},{"id":"md6-109-1-73","subject":"md6","topic":"復健-骨骼肌肉損傷與疾患","meta":"109年第1次第73題","year":109,"session":1,"number":73,"question":"59歲女性病人意外跌倒後，主訴左肩疼痛，X光檢查如圖，最可能之診斷為何？","options":["(A) calcified tendinosis","(B) avulsion fracture of greater tuberosity","(C) bone metastasis","(D) primary osteoblastic bone tumor"],"answer":[0,1,2,3],"image":"md6-109-1-73.jpeg","answer_note":"送分:第73題一律給分。 (原公告答案 A)"},{"id":"md6-109-1-74","subject":"md6","topic":"婦科-腫瘤","meta":"109年第1次第74題","year":109,"session":1,"number":74,"question":"80歲女性，下腹部磁振造影檢查（T2WI）呈現如圖，箭號所指之敘述何者最正確？","options":["(A) 子宮頸癌","(B) 卵巢癌","(C) 陰道癌","(D) 子宮內膜癌"],"answer":3,"image":"md6-109-1-74.jpeg"},{"id":"md6-109-1-75","subject":"md6","topic":"麻醉-呼吸道與監視","meta":"109年第1次第75題","year":109,"session":1,"number":75,"question":"一位5歲兒童，發生Ventricular fibrillation，使用defibrillation時之劑量為何？","options":["(A) 起初defibrillation劑量為4J/kg","(B) 再次defibrillation劑量為6J/kg","(C) 再次defibrillation劑量為8J/kg","(D) 第三次defibrillation劑量為4J/kg"],"answer":3,"image":""},{"id":"md6-109-1-76","subject":"md6","topic":"眼科-視網膜葡萄膜","meta":"109年第1次第76題","year":109,"session":1,"number":76,"question":"30歲男性病人，主訴有急性視力下降，合併眼睛疼痛至急診就診。下列何者診斷最有可能？","options":["(A) 視神經炎（optic neuritis）","(B) 中央視網膜動脈阻塞（central retinal artery occlusion）","(C) 中央視網膜靜脈阻塞（central retinal vein occlusion）","(D) 顳動脈炎（temporal arteritis）"],"answer":0,"image":""},{"id":"md6-109-1-77","subject":"md6","topic":"產科-高危險妊娠","meta":"109年第1次第77題","year":109,"session":1,"number":77,"question":"下列何者非子癲前症（pre-eclampsia）典型的臨床徵候？","options":["(A) 妊娠高血壓","(B) 蛋白尿","(C) 血糖上升","(D) 下肢水腫"],"answer":2,"image":""},{"id":"md6-109-1-78","subject":"md6","topic":"醫學倫理與法規","meta":"109年第1次第78題","year":109,"session":1,"number":78,"question":"醫學研究中對於以兒童、孕婦、囚犯、精神病患為受試者的研究皆有比較嚴格的規範，主要是基於何種考量？","options":["(A) 這類受試者人數有限","(B) 代理同意須嚴格把關","(C) 對易受傷害受試族群的保護","(D) 這些人參與試驗的風險過高"],"answer":2,"image":""},{"id":"md6-109-1-79","subject":"md6","topic":"醫學倫理與法規","meta":"109年第1次第79題","year":109,"session":1,"number":79,"question":"69歲男病患無特殊病史，因嗜睡2天意識不清由女兒帶至急診，經檢查發現有心臟衰竭及二氧化碳堆積情況。其家屬（兩位女兒）表示不希望給予插管、電擊、壓胸等侵入性治療增加病患痛苦，且當場要簽署「選擇安寧緩和醫療同意書」，表示希望給予病患緩和醫療於醫院善終。下列敘述何者最正確？","options":["(A) 此病患是末期病人，因此家屬簽署「選擇安寧緩和醫療同意書」是合法的","(B) 醫師應以病人最大利益為第一考量，先急救再說","(C) 病人意識不清，醫師應以家屬的意願為第一考量","(D) 先問醫學倫理委員會再決定"],"answer":1,"image":""},{"id":"md6-109-1-80","subject":"md6","topic":"醫學倫理與法規","meta":"109年第1次第80題","year":109,"session":1,"number":80,"question":"有一位40歲罹患思覺失調症的女性，需接受盲腸切除手術，外科醫師跟她解釋手術內容，精神科醫師評估病人完全可以理解，因此有關同意書的簽署，下列何者正確？","options":["(A) 此病人沒有簽署同意書的能力，因此需請朋友代簽","(B) 此病人沒有簽署同意書的能力，因此需請家屬代簽","(C) 此病人沒有簽署同意書的能力，因此需請精神科醫師代簽","(D) 此病人尚有簽署同意書的能力，因此病人自己簽即可"],"answer":3,"image":""},{"id":"md6-109-2-1","subject":"md6","topic":"麻醉-呼吸道與監視","meta":"109年第2次第1題","year":109,"session":2,"number":1,"question":"全身麻醉甦醒拔管時期，下列何者不是可能之相關併發症？","options":["(A) 正壓性肺水腫","(B) 上呼吸道阻塞","(C) 吸入性肺炎","(D) 支氣管痙攣"],"answer":0,"image":""},{"id":"md6-109-2-2","subject":"md6","topic":"麻醉-呼吸道與監視","meta":"109年第2次第2題","year":109,"session":2,"number":2,"question":"關於術中使用神經監測（neurologic monitors）的功用，下列敘述何者錯誤？","options":["(A) 神經監測（neurologic monitors）可以及早獲知可能的神經傷害，甚至及早處置","(B) 麻醉中維持良好的生理恆定（physiological homeostasis）與麻醉深度，可以增加神經監測的效度（efficacy）","(C) 靜脈藥物中，ketamine與barbiturates對腦波的影響類似","(D) somatosensory-evoked potentials（SSEP）、motor-evoked potentials（MEP）與electromyogram（EMG）都可以使用在spinal column及spinal cord手術中的神經監測"],"answer":2,"image":""},{"id":"md6-109-2-3","subject":"md6","topic":"麻醉-呼吸道與監視","meta":"109年第2次第3題","year":109,"session":2,"number":3,"question":"麻醉手術中常有手術出血等各種情況，有關維護氧氣輸送（oxygen delivery）防止組織缺氧，下列敘述何者正確？","options":["(A) 血氧飽和度（如以Pulse oximetry, SpO2監測）大於90%，器官就不會有缺氧風險","(B) 大手術中肺動脈測得的血氧飽和度（SvO2, mixed venous oxygen saturation）可監測全身血氧供應是否足夠，術中SvO2降低與術後後遺症相關","(C) 發燒會導致SvO2升高","(D) 疼痛控制不佳會導致SvO2升高"],"answer":1,"image":""},{"id":"md6-109-2-4","subject":"md6","topic":"麻醉-麻醉藥理","meta":"109年第2次第4題","year":109,"session":2,"number":4,"question":"下列有關吸入性麻醉劑的敘述，何者錯誤？","options":["(A) 其最低肺泡濃度（minimum alveolar concentration）是指預防50%患者在手術劃刀刺激下，產生動作（movement）的麻醉劑濃度","(B) desflurane在血液和身體組織中的低溶解度，導致其麻醉的快速誘導","(C) 迅速增加desflurane的濃度，常導致心率下降","(D) sevoflurane的無刺激性和肺泡濃度的迅速增加，使其成為平穩和快速誘導的絕佳選擇"],"answer":2,"image":""},{"id":"md6-109-2-5","subject":"md6","topic":"麻醉-麻醉藥理","meta":"109年第2次第5題","year":109,"session":2,"number":5,"question":"下列有關靜脈麻醉劑（intravenous anesthetics）的敘述，何者錯誤？","options":["(A) flumazenil是benzodiazepine受體拮抗劑","(B) benzodiazepine抑制呼吸中樞對CO2的敏感性","(C) benzodiazepine增加腦耗氧量","(D) ketamine抑制NMDA通道"],"answer":2,"image":""},{"id":"md6-109-2-6","subject":"md6","topic":"麻醉-呼吸道與監視","meta":"109年第2次第6題","year":109,"session":2,"number":6,"question":"下列何項指標較能評估由非去極性肌肉鬆弛劑（nondepolarizing muscle relaxant）作用中恢復的程度？","options":["(A) 潮氣容積（tidal volume）","(B) 呼吸速率（respiratory rate）","(C) 吸氣負壓（inspiratory negative pressure）","(D) 四聯刺激（train-of-four, TOF）"],"answer":3,"image":""},{"id":"md6-109-2-7","subject":"md6","topic":"麻醉-特殊麻醉與疼痛","meta":"109年第2次第7題","year":109,"session":2,"number":7,"question":"有關門診手術麻醉（ambulatory anesthesia）的敘述，下列何者錯誤？","options":["(A) 術前評估不一定需要常規的實驗室檢查","(B) 早產兒或嬰幼兒是否適合門診手術，通常須考量受孕後週數（post-conceptional age）","(C) 抽菸患者屬於術後噁心嘔吐的高風險族群","(D) 採用多模式止痛方式（multimodal analgesia），如：合併使用局部麻醉或區域麻醉止痛（local or regional anesthesia），可減少opioids使用"],"answer":2,"image":""},{"id":"md6-109-2-8","subject":"md6","topic":"麻醉-特殊麻醉與疼痛","meta":"109年第2次第8題","year":109,"session":2,"number":8,"question":"下列有關以病患自控式止痛治療手術後疼痛的敘述，何者錯誤？","options":["(A) 可提供更有效率更即時的止痛","(B) 可降低止痛藥物的總劑量","(C) 不宜使用嗎啡以外的藥物","(D) 是一種negative-feedback loop，病患感覺疼痛就會按壓止痛藥物按鈕；若病患疼痛降低，則不會自主按壓止痛藥按鈕"],"answer":2,"image":""},{"id":"md6-109-2-9","subject":"md6","topic":"麻醉-特殊麻醉與疼痛","meta":"109年第2次第9題","year":109,"session":2,"number":9,"question":"重症病人應該儘早給與適當的營養支持，下列處置何者錯誤？","options":["(A) 一般營養狀況良好的病人，術後給與適當的水分及電解質，可容許禁食達7天","(B) 腸胃道手術的病人，亦可考慮及早開始腸胃道灌食","(C) 敗血性休克的病人，越早給與營養支持，預後越好","(D) 對於胃排空較差的病人，可考慮放置十二指腸管灌食，以減少吸入（aspiration）的風險"],"answer":2,"image":""},{"id":"md6-109-2-10","subject":"md6","topic":"眼科-視網膜葡萄膜","meta":"109年第2次第10題","year":109,"session":2,"number":10,"question":"有關年齡相關黃斑部退化（age-related macular degeneration）危險因子之敘述，下列何者錯誤？","options":["(A) 年齡是主要危險因子，年齡越大盛行率越高","(B) 種族是危險因子，黑人較容易發生視力喪失","(C) 家族史很重要，遺傳也是危險因子","(D) 抽菸是危險因子，會增加發病機會"],"answer":1,"image":""},{"id":"md6-109-2-11","subject":"md6","topic":"眼科-視網膜葡萄膜","meta":"109年第2次第11題","year":109,"session":2,"number":11,"question":"有關高度近視的敘述，下列何者錯誤？","options":["(A) 可能產生視網膜格子狀退化（lattice degeneration）或視網膜破洞，進而造成裂孔性視網膜剝離","(B) 可能產生黃斑部脈絡膜新生血管（choroidal neovascularization），永久影響視力","(C) 高度近視產生併發症的風險，無法因為接受角膜近視雷射手術而降低，只有利用白內障水晶體置換手術才能將風險去除","(D) 高度近視可能會產生黃斑部視網膜分裂症（retinoschisis），玻璃體內注射抗血管內皮生長因子（anti- vascular endothelial growth factor）通常是沒用的"],"answer":2,"image":""},{"id":"md6-109-2-12","subject":"md6","topic":"眼科-角膜結膜眼瞼眼窩","meta":"109年第2次第12題","year":109,"session":2,"number":12,"question":"下列角膜之病變何者與角膜弧度之變化有關？①圓錐角膜（keratoconus）②球狀角膜（keratoglobus） ③清澈型角膜邊緣變性（pellucid marginal degeneration）④角膜內皮細胞失養症（endothelial dystrophy）","options":["(A) ①③④","(B) ②③④","(C) ①②④","(D) ①②③"],"answer":3,"image":""},{"id":"md6-109-2-13","subject":"md6","topic":"眼科-角膜結膜眼瞼眼窩","meta":"109年第2次第13題","year":109,"session":2,"number":13,"question":"有關上鞏膜炎（episcleritis）之敘述，下列何者正確？","options":["(A) 好發於老年人","(B) 常會轉變成真正的鞏膜炎（scleritis）","(C) 不會復發","(D) 有可能合併免疫風濕性疾病"],"answer":3,"image":""},{"id":"md6-109-2-14","subject":"md6","topic":"眼科-水晶體青光眼","meta":"109年第2次第14題","year":109,"session":2,"number":14,"question":"陳先生，74歲，右眼白內障術後一切順利，但是一年之後又開始感到視力漸漸模糊，最常見的原因為何？","options":["(A) 後發性白內障","(B) 黃斑部水腫","(C) 眼瞼下垂","(D) 眼內炎"],"answer":0,"image":""},{"id":"md6-109-2-15","subject":"md6","topic":"眼科-水晶體青光眼","meta":"109年第2次第15題","year":109,"session":2,"number":15,"question":"關於治療原發性隅角開放性青光眼（primary open angle glaucoma）的敘述，下列何項最不適當？","options":["(A) 治療的目標是維持病人於有生之年有足夠使用的視覺功能","(B) 將眼壓控制在21 mmHg以下就不會惡化","(C) 眼壓的波動（intraocular pressure fluctuation）也是造成青光眼惡化的原因之一","(D) 治療失敗常與病患的順從性（patient compliance）不佳有關"],"answer":1,"image":""},{"id":"md6-109-2-16","subject":"md6","topic":"眼科-屈光斜弱視","meta":"109年第2次第16題","year":109,"session":2,"number":16,"question":"有關弱視之敘述，下列何者錯誤？","options":["(A) 遠視400度的小朋友比近視400度的小朋友容易有弱視，是因為小孩子的調節力（accommodation power）比成人弱","(B) 近視400度的眼球，其遠點（不戴矯正眼鏡、不作調節的狀況下能清楚視物的最遠距離）位在眼前25公分","(C) 弱視的人視物會有crowding phenomenon，用單一視標測量的視力會比較好","(D) 弱視的治療包括光學矯正、遮蔽好眼、或是用藥物模糊好眼（penalization）"],"answer":0,"image":""},{"id":"md6-109-2-17","subject":"md6","topic":"眼科-屈光斜弱視","meta":"109年第2次第17題","year":109,"session":2,"number":17,"question":"有關外展神經麻痺（abducens palsy）之敘述，下列何者錯誤？","options":["(A) 要檢查聽力損失或角膜敏感性，以排除聽神經瘤的可能","(B) 檢查鼻咽部病變和其他鼻部症狀以排除鼻咽癌的可能","(C) 要檢查視神經盤形態以排除腦壓升高造成的視乳突水腫","(D) 兒童須比照有糖尿病病史的老年人，先觀察三個月是否自行恢復，再進行積極的調查"],"answer":3,"image":""},{"id":"md6-109-2-18","subject":"md6","topic":"眼科-視網膜葡萄膜","meta":"109年第2次第18題","year":109,"session":2,"number":18,"question":"惡性脈絡膜黑色素瘤（choroidal melanoma）最容易轉移到身體何處？","options":["(A) 胰臟","(B) 肝臟","(C) 肺臟","(D) 皮膚"],"answer":1,"image":""},{"id":"md6-109-2-19","subject":"md6","topic":"喉科學與頭頸腫瘤","meta":"109年第2次第19題","year":109,"session":2,"number":19,"question":"41歲男性，左下側牙齦無痛性潰瘍約四個多月，一個月前開始左側頸部摸到迅速腫大的硬塊，視診發現該橢圓形潰瘍病灶位於牙齦，最長徑約3公分，觸診左頸發現3顆各約2乘2乘2公分，堅硬、表面不規則、無法移動的腫塊。經牙齦切片病理檢查，確定診斷為分化良好的鱗狀上皮癌，在無遠端移轉的狀況下，下列何種治療最適當？","options":["(A) 進行廣泛性切除口內病灶及左側頸部淋巴腺廓清手術","(B) 放射線治療及化學治療","(C) 先進行廣泛性切除口內病灶及左側頸部淋巴腺廓清手術，再進行放射線治療或放化療","(D) 先進行化學藥物治療，再進行廣泛性切除口內病灶及左側頸部淋巴腺廓清手術"],"answer":2,"image":""},{"id":"md6-109-2-20","subject":"md6","topic":"鼻科學","meta":"109年第2次第20題","year":109,"session":2,"number":20,"question":"下列何者最能區分急性病毒性鼻竇炎或急性細菌性鼻竇炎？","options":["(A) 病程長短","(B) 分泌物濃稠度及總量","(C) 發燒與否","(D) 影像學檢查的發現"],"answer":0,"image":""},{"id":"md6-109-2-21","subject":"md6","topic":"鼻科學","meta":"109年第2次第21題","year":109,"session":2,"number":21,"question":"關於鼻閥（nasal valve），下列敘述何者錯誤？","options":["(A) 外鼻閥（external nasal valve）由鼻小柱（columella）、鼻翼邊緣（alar rim）與鼻檻（nasal sill）所構成","(B) 外鼻閥（external nasal valve）是整個鼻道最狹窄的地方","(C) 內鼻閥（internal nasal valve）位於鼻前庭（vestibule）後約1.3公分處","(D) 內鼻閥（internal nasal valve）狹窄所造成的鼻塞，可以透過modified Cottle maneuver來評估"],"answer":1,"image":""},{"id":"md6-109-2-22","subject":"md6","topic":"喉科學與頭頸腫瘤","meta":"109年第2次第22題","year":109,"session":2,"number":22,"question":"有關後天性（acquired）喉氣管狹窄（laryngotracheal stenosis），下列敘述何者正確？","options":["(A) 常見之病因包括氣管內插管、外傷、頭頸部放射治療等","(B) 以聲門區狹窄（glottic stenosis）最為常見","(C) 聲門上狹窄（supraglottic stenosis）常伴隨吐氣期喘鳴聲（expiratory stridor）","(D) 磁振造影為影像學檢查之首選"],"answer":0,"image":""},{"id":"md6-109-2-23","subject":"md6","topic":"喉科學與頭頸腫瘤","meta":"109年第2次第23題","year":109,"session":2,"number":23,"question":"35歲女性國小老師，近年來聲音品質逐漸變差，說話吃力，咽喉常有乾、緊、痛等症狀，經喉內視鏡檢查如下圖，後續治療下列何者最適當？","options":["(A) 上消化道內視鏡檢查以排除胃食道逆流之可能","(B) 口服抗生素1週後回診追蹤","(C) 安排語言治療以改善說話方式","(D) 顯微手術切除，並將檢體送病理檢驗以排除惡性腫瘤之可能"],"answer":2,"image":"md6-109-2-23.jpeg"},{"id":"md6-109-2-24","subject":"md6","topic":"喉科學與頭頸腫瘤","meta":"109年第2次第24題","year":109,"session":2,"number":24,"question":"有關下咽部的淋巴引流，下列敘述何者正確？","options":["(A) 梨狀窩（pyriform sinus）內側壁的引流主要是經過甲狀舌骨膜（thyrohyoid membrane）而到頸部第V區","(B) 梨狀窩下端的引流主要是經過環甲膜（cricothyroid membrane）而到頸部第V區","(C) 下咽後壁區（posterior pharyngeal wall）的引流不會到後咽淋巴結","(D) 環狀軟骨後區（post-cricoid area）的引流主要是經過環甲膜而到氣管旁淋巴結"],"answer":3,"image":""},{"id":"md6-109-2-25","subject":"md6","topic":"耳科學","meta":"109年第2次第25題","year":109,"session":2,"number":25,"question":"小珍今年6歲，去年在醫院做的純音聽力檢查正常。前天感冒發燒，覺得一耳聽力變差，而且疼痛有悶脹感，耳鏡檢查所見如下。請依序回答下列三題。最可能診斷為何？","options":["(A) 右側急性中耳炎","(B) 右側慢性中耳炎","(C) 左側急性中耳炎","(D) 左側慢性中耳炎"],"answer":2,"image":"md6-109-2-25.jpeg"},{"id":"md6-109-2-26","subject":"md6","topic":"耳科學","meta":"109年第2次第26題","year":109,"session":2,"number":26,"question":"其右耳鼓室圖（tympanogram），最可能為下列何者？","options":["(A) ","(B) ","(C) ","(D) "],"answer":3,"image":"md6-109-2-26.jpeg"},{"id":"md6-109-2-27","subject":"md6","topic":"耳科學","meta":"109年第2次第27題","year":109,"session":2,"number":27,"question":"左耳鼓室圖（tympanogram），最可能為下列何者？","options":["(A) ","(B) ","(C) ","(D) "],"answer":0,"image":"md6-109-2-27.jpeg"},{"id":"md6-109-2-28","subject":"md6","topic":"產科-一般產科","meta":"109年第2次第28題","year":109,"session":2,"number":28,"question":"某產婦於陰道分娩後發現會陰部有裂傷，此傷口涵蓋了皮膚、陰道黏膜、會陰體（perineal body）、肛門括約肌（anal sphincter）。這屬於第幾度裂傷？","options":["(A) 第一度","(B) 第二度","(C) 第三度","(D) 第四度"],"answer":2,"image":""},{"id":"md6-109-2-29","subject":"md6","topic":"產科-高危險妊娠","meta":"109年第2次第29題","year":109,"session":2,"number":29,"question":"下列何者不是重度子癇前症（preeclampsia）的症狀？","options":["(A) 血壓＞160/110 mmHg","(B) 24小時尿液中尿蛋白100 mg","(C) 肝功能異常","(D) 胎兒生長遲滯（fetal growth restriction）"],"answer":1,"image":""},{"id":"md6-109-2-30","subject":"md6","topic":"產科-一般產科","meta":"109年第2次第30題","year":109,"session":2,"number":30,"question":"子宮底（fundus）到達肚臍水平時大約是正常懷孕幾週？","options":["(A) 16","(B) 20","(C) 24","(D) 28"],"answer":1,"image":""},{"id":"md6-109-2-31","subject":"md6","topic":"婦科-手術學與診斷技術","meta":"109年第2次第31題","year":109,"session":2,"number":31,"question":"一位年輕婦女，因慢性下腹痛而接受腹腔鏡進一步檢查於插管麻醉後，置放導尿管（Foley's catheter）排空膀胱內尿液。腹腔鏡初步骨盆腔診視之情形如圖所示，標示＊處之解剖名稱為：","options":["(A) 子宮薦椎韌帶（uterosacral ligament）","(B) 圓韌帶（round ligament）","(C) 闊韌帶（broad ligament）","(D) 卵巢懸吊韌帶（suspensory ovarian ligament）"],"answer":0,"image":"md6-109-2-31.jpeg"},{"id":"md6-109-2-32","subject":"md6","topic":"婦科-手術學與診斷技術","meta":"109年第2次第32題","year":109,"session":2,"number":32,"question":"在做腹腔鏡卵巢切除時，下列何種截斷骨盆漏斗韌帶（infundibulopelvic ligament）的方式最不恰當？","options":["(A) 以體外打結的方式綁住","(B) 以內視鏡血管夾夾住","(C) 利用雙極電刀切割（cutting）","(D) 利用單極電刀凝結（coagulation）"],"answer":3,"image":""},{"id":"md6-109-2-33","subject":"md6","topic":"婦科-生殖內分泌","meta":"109年第2次第33題","year":109,"session":2,"number":33,"question":"女性毛髮生長，下列何者對男性素（androgen）濃度反應最敏感？","options":["(A) 眉毛","(B) 睫毛","(C) 腳毛","(D) 陰毛"],"answer":3,"image":""},{"id":"md6-109-2-34","subject":"md6","topic":"婦科-生殖內分泌","meta":"109年第2次第34題","year":109,"session":2,"number":34,"question":"15歲女性，第二性徵發育正常，但未有初經並有週期性腹痛，超音波如圖所示，下列處置何者最不適當？","options":["(A) 手術治療","(B) 黃體素催經（progesterone challenge test）","(C) 腎臟攝影術（intravenous pyelography）","(D) 詳細內診診查（pelvic examination）"],"answer":1,"image":"md6-109-2-34.jpeg"},{"id":"md6-109-2-35","subject":"md6","topic":"婦科-腫瘤","meta":"109年第2次第35題","year":109,"session":2,"number":35,"question":"58歲女性，主訴最近三天有陰道少量鮮紅色出血，在51歲時已經停經。下列處理何者最適當？","options":["(A) 建議切除子宮（hysterectomy），以排除子宮內膜癌（endometrial cancer）的可能","(B) 詳問病史、做內診、安排超音波檢查，並建議子宮內膜採樣（endometrial tissue sampling）","(C) 給予雌激素（estrogen）荷爾蒙補充","(D) 建議減重即可，因為肥胖婦女會有較多雌激素（estrogen）產生"],"answer":1,"image":""},{"id":"md6-109-2-36","subject":"md6","topic":"婦科-腫瘤","meta":"109年第2次第36題","year":109,"session":2,"number":36,"question":"40歲的病患，子宮頸切片是cervical intraepithelial neoplasia 2（CIN 2）時，下一步處置何者最適當？","options":["(A) 半年抹片追蹤一次","(B) 全子宮切除","(C) 施打HPV疫苗","(D) 子宮頸錐狀切除（conization）"],"answer":3,"image":""},{"id":"md6-109-2-37","subject":"md6","topic":"婦科-腫瘤","meta":"109年第2次第37題","year":109,"session":2,"number":37,"question":"有關絨毛膜癌（choriocarcinoma）之敘述，下列何者正確？","options":["(A) 治療時依據病理組織中具備幾個危險因素而定","(B) 單一轉移而言，腸道轉移之預後與肺臟轉移同級","(C) 若屬高危險群，應該一開始就用methotrexate或actinomycin-D","(D) 脊髓液和血清比（CSF：serum）之hCG比值為1：100時，表示腦部轉移之機會小"],"answer":3,"image":""},{"id":"md6-109-2-38","subject":"md6","topic":"婦科-腫瘤","meta":"109年第2次第38題","year":109,"session":2,"number":38,"question":"下列何者不是子宮內膜癌的危險因子？","options":["(A) 肥胖，糖尿病和高血壓","(B) 很晚才停經","(C) 多產次","(D) 長期單獨使用雌激素（estrogen）"],"answer":2,"image":""},{"id":"md6-109-2-39","subject":"md6","topic":"產科-一般產科","meta":"109年第2次第39題","year":109,"session":2,"number":39,"question":"婦產科醫學中，有一種檢查利用胎兒紅血球含有胎兒血紅素（hemoglobin F），而胎兒血紅素對酸性染劑有較高的抗性（acid elution test），而能夠與母血紅血球做出區別；使得胎兒紅血球被染為紅色，而母血紅血球成為透明如鬼魅般（ghosts）的存在，這樣的檢查被稱作Kleihauer–Betke test（K-B test），結果如圖所示。這種檢查通常是檢驗何種疾病？","options":["(A) 雙胞胎輸血症候群（twin-twin transfusion syndrome）","(B) 羊水栓塞（amniotic fluid embolism）","(C) 胎兒母體間出血（fetomaternal hemorrhage）","(D) 胎兒水腫（hydrops fetalis）"],"answer":2,"image":"md6-109-2-39.jpeg"},{"id":"md6-109-2-40","subject":"md6","topic":"產科-高危險妊娠","meta":"109年第2次第40題","year":109,"session":2,"number":40,"question":"33歲王小姐，G3P2、第一胎於5年前足月陰道生產，第二胎於2年前因前置胎盤接受剖腹生產，目前懷孕第三胎，胎位為正常頭位。關於本次生產方式的諮詢，下列何者錯誤？","options":["(A) 曾經陰道生產過，這胎嘗試陰道生產的成功率明顯提高","(B) 若考慮陰道生產，因有子宮破裂的風險，建議到有完整急救設備並可隨時緊急剖婦產的醫院待產","(C) 若考慮陰道生產，前次手術為子宮下段橫切術比傳統直切術造成子宮破裂的發生率低，較為安全","(D) 若考慮陰道生產，不建議施打減痛分娩，因產婦對疼痛不敏感可能延誤子宮破裂的診斷"],"answer":3,"image":""},{"id":"md6-109-2-41","subject":"md6","topic":"產科-一般產科","meta":"109年第2次第41題","year":109,"session":2,"number":41,"question":"關於唐氏症（Down syndrome; trisomy 21）敘述，下列何者錯誤？","options":["(A) 一種致死性三合體症（lethal trisomy）","(B) 75%發生於減數分裂第一期（meiosis I）","(C) 發生率與母親懷孕年齡有相關","(D) 是最常見智能障礙原因"],"answer":0,"image":""},{"id":"md6-109-2-42","subject":"md6","topic":"產科-一般產科","meta":"109年第2次第42題","year":109,"session":2,"number":42,"question":"第一胎足月的孕婦於產房待產中，下列何種情況出現時，可考慮真空吸引生產？","options":["(A) 潛伏期（latent phase）時家屬表示，因時辰良好應儘快讓胎兒娩出","(B) 第一產程中產婦疼痛難忍大聲哀嚎","(C) 第一產程中破水，內診發現臍帶掉落於陰道下半部","(D) 第二產程中出現胎心音異常減速，胎頭低位已呈現著冠（crowning）"],"answer":3,"image":""},{"id":"md6-109-2-43","subject":"md6","topic":"產科-高危險妊娠","meta":"109年第2次第43題","year":109,"session":2,"number":43,"question":"36歲G3P1孕婦，第一胎曾經因產前乙型鏈球菌（group-B streptococcus, GBS）篩檢呈現菌落反應（colonization），而於待產時接受抗生素預防性治療（intrapartum antibiotic prophylaxis），新生兒出生後並未發生乙型鏈球菌感染症。此次懷孕最適當的處置為：","options":["(A) 妊娠初期（first trimester）進行生殖道GBS篩檢","(B) 妊娠初期進行尿液的GBS培養檢驗","(C) 妊娠35～37週進行生殖道GBS篩檢","(D) 因為沒有生殖道GBS篩檢，待產時不需要給與抗生素預防性治療"],"answer":2,"image":""},{"id":"md6-109-2-44","subject":"md6","topic":"產科-高危險妊娠","meta":"109年第2次第44題","year":109,"session":2,"number":44,"question":"雙胞胎妊娠合併子宮內單一胎兒死亡（twins with death of one fetus）狀況時；下列何者不是影響存活胎兒罹病狀況（morbidity）發生與否或嚴重度的因素？","options":["(A) 死胎發生胎兒死亡的懷孕週數","(B) 導致死胎之胎兒死亡的原因","(C) 孕婦年齡","(D) 雙胞胎之絨毛膜性（chorionicity）"],"answer":2,"image":""},{"id":"md6-109-2-45","subject":"md6","topic":"產科-高危險妊娠","meta":"109年第2次第45題","year":109,"session":2,"number":45,"question":"27歲G1P0懷孕38週孕婦，因下腹部疼痛合併子宮收縮前來求診，到院時血壓160/110 mmHg，尿蛋白4+，血清穀草轉氨酶AST 308 U/L，血小板數60,000/uL，經診斷為重度子癇前症。醫師建議此位孕婦住院並給予硫酸鎂（magnesium sulfate，MgSO4）治療。對此一疾病，給予硫酸鎂處方的主要目的是：","options":["(A) 預防痙攣","(B) 控制高血壓","(C) 抑制子宮收縮","(D) 保護胎兒中樞神經"],"answer":0,"image":""},{"id":"md6-109-2-46","subject":"md6","topic":"產科-高危險妊娠","meta":"109年第2次第46題","year":109,"session":2,"number":46,"question":"25歲G2P1孕婦，妊娠13週，因外陰搔癢求診。尿液細菌培養檢驗出現100,000 cfu/mL大腸桿菌（E. Coli），並無其他性傳染疾病徵候。此孕婦並無解尿困難、解尿疼痛、頻尿及漏尿症狀；亦無下腹部及腰部壓痛、疼痛症狀，體溫正常，此時的最適當處置為：","options":["(A) 不需治療","(B) 出現泌尿道感染症狀時開始治療","(C) 立即給予抗生素治療","(D) 目前不需治療，待產時給與抗生素治療"],"answer":2,"image":""},{"id":"md6-109-2-47","subject":"md6","topic":"婦科-尿失禁與骨盆腔脫垂","meta":"109年第2次第47題","year":109,"session":2,"number":47,"question":"依照International Continence Society所提出Pelvic Organ Prolapse Quantification system（POP- Q）Point Aa點大概與何解剖構造位置相當？","options":["(A) 尿道口（urethral os）","(B) 膀胱頸（bladder neck）","(C) 子宮頸內口（cervical internal os）","(D) 坐骨棘（ischial spine）"],"answer":1,"image":""},{"id":"md6-109-2-48","subject":"md6","topic":"婦科-尿失禁與骨盆腔脫垂","meta":"109年第2次第48題","year":109,"session":2,"number":48,"question":"骨盆陰道檢查時，將ring forceps以45度角度伸入陰道，並將兩圓孔端張開置放於lateral fornix，可作為何種骨盆缺陷之區分？","options":["(A) 直腸膨出（rectocele）","(B) 尿道膨出（urethrocele）","(C) 膀胱膨出（cystocele）","(D) 小腸膨出（enterocele）"],"answer":2,"image":""},{"id":"md6-109-2-49","subject":"md6","topic":"婦科-腫瘤","meta":"109年第2次第49題","year":109,"session":2,"number":49,"question":"35歲女性，抹片檢查結果為子宮頸非典型鱗狀細胞（ASC-US），下列處置何者最不恰當？","options":["(A) 6個月追蹤一次抹片，連續兩次正常抹片後，回歸年度篩檢","(B) 立刻進行陰道鏡檢查","(C) 檢測高危險型人類乳突病毒","(D) 立即安排子宮頸錐狀切除（conization）"],"answer":3,"image":""},{"id":"md6-109-2-50","subject":"md6","topic":"產科-一般產科","meta":"109年第2次第50題","year":109,"session":2,"number":50,"question":"有關自然流產的敘述，下列何者錯誤？","options":["(A) 約有8～20%的懷孕會自然流產","(B) 自然流產的病史，也是再次流產的危險因子","(C) 年齡是流產的重要危險因子","(D) 產後3～6個月內再懷孕，並不增加流產的風險"],"answer":3,"image":""},{"id":"md6-109-2-51","subject":"md6","topic":"婦科-腫瘤","meta":"109年第2次第51題","year":109,"session":2,"number":51,"question":"原發性的陰道癌（vaginal cancer），並不多見，最常發生在陰道的那個部位？","options":["(A) 上三分之一的陰道後壁（upper one-third of the vagina on the posterior wall）","(B) 上三分之一的陰道前壁（upper one-third of the vagina on the anterior wall）","(C) 下三分之一的陰道後壁（lower one-third of the vagina on the posterior wall）","(D) 下三分之一的陰道前壁（lower one-third of the vagina on the anterior wall）"],"answer":0,"image":""},{"id":"md6-109-2-52","subject":"md6","topic":"婦科-腫瘤","meta":"109年第2次第52題","year":109,"session":2,"number":52,"question":"下列那一種卵巢癌只有單側生長，不建議做另一側非病灶卵巢的切片取樣？","options":["(A) 無性胚胎瘤（dysgerminoma）","(B) 卵巢內胚層竇瘤（endodermal sinus tumor）","(C) 漿液性卵巢癌（serous carcinoma）","(D) 混合性生殖細胞腫瘤（mixed germ cell tumor）"],"answer":1,"image":""},{"id":"md6-109-2-53","subject":"md6","topic":"婦科-良性腫瘤與內膜異位","meta":"109年第2次第53題","year":109,"session":2,"number":53,"question":"關於子宮內膜異位症（endometriosis）致病機制之敘述，下列何者錯誤？","options":["(A) 卵巢的巧克力囊腫（ovarian endometrioma, chocolate cyst）與月經逆流有關","(B) 與局部免疫機能缺失有關","(C) 與雌激素刺激有關","(D) 長期無排卵（chronic anovulation）會加重子宮內膜異位症之症狀與病程"],"answer":3,"image":""},{"id":"md6-109-2-54","subject":"md6","topic":"婦科-良性腫瘤與內膜異位","meta":"109年第2次第54題","year":109,"session":2,"number":54,"question":"關於治療子宮內膜異位症（endometriosis）的藥物之敘述，下列何者錯誤？","options":["(A) 以danazol治療，效果佳且幾乎沒有副作用","(B) 以GnRH analogue（GnRHa）治療，容易出現熱潮紅及骨質流失情形","(C) 以口服避孕藥治療，效果不錯且服藥容易","(D) 以高劑量黃體素治療，可以改善痛經與月經血量過多"],"answer":0,"image":""},{"id":"md6-109-2-55","subject":"md6","topic":"婦科-生殖內分泌","meta":"109年第2次第55題","year":109,"session":2,"number":55,"question":"在以clomiphene藥物誘發排卵的不孕症治療過程中，若發現有抗性仍然無法順利排卵時，下列何種處理不列入考慮？","options":["(A) 配合metformin治療","(B) 以aromatase inhibitors治療","(C) 以gonadotropins治療","(D) 以dopamine antagonist治療"],"answer":3,"image":""},{"id":"md6-109-2-56","subject":"md6","topic":"婦科-生殖內分泌","meta":"109年第2次第56題","year":109,"session":2,"number":56,"question":"停經婦女的血中FSH、estradiol（E2）會呈現下列何項組合？","options":["(A) FSH<40 mIU/mL，E2<30 pg/mL","(B) FSH>40 mIU/mL，E2>30 pg/mL","(C) FSH<40 mIU/mL，E2>30 pg/mL","(D) FSH>40 mIU/mL，E2<30 pg/mL"],"answer":3,"image":""},{"id":"md6-109-2-57","subject":"md6","topic":"婦科-生殖內分泌","meta":"109年第2次第57題","year":109,"session":2,"number":57,"question":"卵細胞何時完成第二次減數分裂（meiosis II）？","options":["(A) 性成熟時（puberty）","(B) 月經來潮時（menstruation）","(C) 排卵前（ovulation）","(D) 受精後（fertilization）"],"answer":3,"image":""},{"id":"md6-109-2-58","subject":"md6","topic":"復健-神經復健","meta":"109年第2次第58題","year":109,"session":2,"number":58,"question":"一位脊髓損傷患者，四肢都沒有任何動作，進行肛門指診時發現有自主性收縮，且第四及第五薦髓皮節是有感覺的，根據美國脊髓損傷協會（Americian spinal injury association, ASIA）的分類標準，其等級應為？","options":["(A) ASIA A","(B) ASIA B","(C) ASIA C","(D) ASIA D"],"answer":2,"image":""},{"id":"md6-109-2-59","subject":"md6","topic":"復健-神經復健","meta":"109年第2次第59題","year":109,"session":2,"number":59,"question":"關於多發性硬化症患者（multiple sclerosis）之併發症，下列敘述何者錯誤？","options":["(A) 膀胱逼尿肌過動為最常見的膀胱異常表現","(B) 便秘為最常見的腸道異常表現","(C) 認知功能缺損非常少見","(D) 可能會有視覺功能缺損"],"answer":2,"image":""},{"id":"md6-109-2-60","subject":"md6","topic":"復健-神經復健","meta":"109年第2次第60題","year":109,"session":2,"number":60,"question":"下列何者是篩檢人類神經肌肉交接處疾病（neuromuscular junction disorders），最常用的電學診斷方法？","options":["(A) 神經傳導（nerve conduction）檢查","(B) 肌肉激發電刺激（muscle excitability）檢查","(C) 連續電刺激神經（repetitive nerve stimulation）檢查","(D) 肌電圖（electromyography）檢查"],"answer":2,"image":""},{"id":"md6-109-2-61","subject":"md6","topic":"復健-神經復健","meta":"109年第2次第61題","year":109,"session":2,"number":61,"question":"下列何者為脊髓損傷病人泌尿系統最常見的併發症？","options":["(A) 腎衰竭（renal failure）","(B) 泌尿道感染（infection）","(C) 泌尿道瘻管（fistula）","(D) 泌尿道結石（urolith）"],"answer":1,"image":""},{"id":"md6-109-2-62","subject":"md6","topic":"復健-骨骼肌肉損傷與疾患","meta":"109年第2次第62題","year":109,"session":2,"number":62,"question":"類風濕性關節炎的晚期手指常有種種變形，關於鈕扣孔變形（buttonhole deformity），下列敘述何者正確？","options":["(A) 與手指伸肌肌腱之中央腱（central tendon）斷裂有關","(B) 近端指間關節呈現伸直（extension）狀態","(C) 遠端指間關節呈現屈曲（flexion）狀態","(D) 與手指伸肌肌腱之側腱（lateral tendon）無關"],"answer":0,"image":""},{"id":"md6-109-2-63","subject":"md6","topic":"復健-截肢與義肢輔具","meta":"109年第2次第63題","year":109,"session":2,"number":63,"question":"下列四種頸部裝具（cervical orthosis），對於頸部側彎（lateral bending）及轉動（rotation）的限制程度有最好的效果？","options":["(A) 海綿頸圈（soft collar）","(B) 費城頸圈（Philadelphia collar）","(C) 硬式頸圈（hard collar）","(D) 胸枕下頷固定架（sternal occipital mandibular immobilization brace）"],"answer":3,"image":""},{"id":"md6-109-2-64","subject":"md6","topic":"復健-骨骼肌肉損傷與疾患","meta":"109年第2次第64題","year":109,"session":2,"number":64,"question":"人類頸部頸間盤疼痛模式（discogenic pain pattern）引起上肢疼痛最常發生於那兩節間？","options":["(A) 第二、三節間","(B) 第三、四節間","(C) 第五、六節間","(D) 第六、七節間"],"answer":2,"image":""},{"id":"md6-109-2-65","subject":"md6","topic":"復健-心肺復健與運動處方","meta":"109年第2次第65題","year":109,"session":2,"number":65,"question":"關於肺部復健（pulmonary rehabilitation）中的運動處方（exercise prescription）的描述，下列何者錯誤？","options":["(A) 有氧運動訓練（aerobic exercise）是肺部復健中重要的一環","(B) 在接受肺部復健前可接受完整的心肺運動測試（cardiopulmonary exercise testing）","(C) 有任何影響運動的相關疾病都應先被適當的評估及控制","(D) 活動性呼吸窘迫（exertional dyspnea）是肺部復健的絕對禁忌"],"answer":3,"image":""},{"id":"md6-109-2-66","subject":"md6","topic":"復健-心肺復健與運動處方","meta":"109年第2次第66題","year":109,"session":2,"number":66,"question":"有關過度訓練症候群（overtraining syndrome）以下敘述那一項錯誤？","options":["(A) 常見的症狀是運動員不明原因的成績下滑或無法進步，容易疲倦，情緒容易失控，睡眠品質不好","(B) 診斷的定義為，運動員休息24小時後，這些症狀仍然存在","(C) 治療方式就是讓運動員休息，可能從數週到數個月，並讓運動員慢慢地重拾他的運動訓練","(D) 最好的治療方式為預防，也就是讓運動員在規律的訓練課程中有適度的休息"],"answer":1,"image":""},{"id":"md6-109-2-67","subject":"md6","topic":"復健-神經復健","meta":"109年第2次第67題","year":109,"session":2,"number":67,"question":"下列關於腦性麻痺（cerebral palsy）患者的神經系統合併症之敘述，何者錯誤？","options":["(A) 半邊癱瘓型（hemiplegic）腦性麻痺患者容易有癲癇（seizure）","(B) 四肢癱瘓型（quadriplegic）腦性麻痺患者容易有智力障礙（intellectual disability）","(C) 運動困難型（dyskinetic）腦性麻痺患者容易有新生兒黃疸（neonatal jaundice）的過去病史","(D) 雙邊癱瘓型（diplegic）腦性麻痺患者容易有聽力異常（hearing loss）"],"answer":3,"image":""},{"id":"md6-109-2-68","subject":"md6","topic":"復健-兒童與一般復健","meta":"109年第2次第68題","year":109,"session":2,"number":68,"question":"下列何者不是罕見疾病兒童的復健治療目的？","options":["(A) 各種生活功能的提昇","(B) 生理功能回復正常","(C) 預防及限制肢體變形","(D) 能參與社會活動"],"answer":1,"image":""},{"id":"md6-109-2-69","subject":"md6","topic":"復健-神經復健","meta":"109年第2次第69題","year":109,"session":2,"number":69,"question":"李先生中風後，語言表達流暢性與覆誦能力嚴重受損，但理解能力尚好，他可能屬於那一種失語症？","options":["(A) 渥尼克氏失語症（Wernicke aphasia）","(B) 經皮質感覺型失語症（transcortical sensory aphasia）","(C) 布洛卡氏失語症（Broca aphasia）","(D) 經皮質運動型失語症（transcortical motor aphasia）"],"answer":2,"image":""},{"id":"md6-109-2-70","subject":"md6","topic":"復健-骨骼肌肉損傷與疾患","meta":"109年第2次第70題","year":109,"session":2,"number":70,"question":"下列何者不是纖維肌痛症（fibromyalgia）常見的臨床表現？","options":["(A) 腸激躁症","(B) 憂鬱","(C) 認知障礙","(D) 多發性關節炎"],"answer":3,"image":""},{"id":"md6-109-2-71","subject":"md6","topic":"復健-兒童與一般復健","meta":"109年第2次第71題","year":109,"session":2,"number":71,"question":"巴氏量表（Barthel index）是用來評估日常生活功能（activities of daily living）的量表，其內容不包含：","options":["(A) 移位（transfer）","(B) 上下樓梯（stair climbing）","(C) 服藥（taking medication）","(D) 大便控制（bowel control）"],"answer":2,"image":""},{"id":"md6-109-2-72","subject":"md6","topic":"復健-骨骼肌肉損傷與疾患","meta":"109年第2次第72題","year":109,"session":2,"number":72,"question":"47歲男性主訴受傷後右肩痛，右肩X光正位及內旋影像顯示如圖，下列敘述何者錯誤？","options":["(A) 無法評估有無旋轉肌斷裂（rotator cuff tear）","(B) 没有bony Bankart症灶","(C) 病人可能有肩關節不穩定的問題","(D) 可以看到Hill-Sachs病灶"],"answer":1,"image":"md6-109-2-72.jpeg"},{"id":"md6-109-2-73","subject":"md6","topic":"復健-骨骼肌肉損傷與疾患","meta":"109年第2次第73題","year":109,"session":2,"number":73,"question":"49歲男性病人，主訴左肘關節疼痛，尤其在橈側（radial side），灰階及彩色杜卜勒超音波檢查如圖，最可能診斷為何？","options":["(A) 高爾夫球肘（golfer's elbow）","(B) 網球肘（tennis elbow）","(C) 橈側側副韌帶部分斷裂（partial tear of radial collateral ligament）","(D) 臂橈肌部分斷裂（partial tear of brachioradialis muscle）"],"answer":1,"image":"md6-109-2-73.jpeg"},{"id":"md6-109-2-74","subject":"md6","topic":"婦科-生殖內分泌","meta":"109年第2次第74題","year":109,"session":2,"number":74,"question":"下列何者是不孕症婦女最需要接受的影像檢查項目之一？","options":["(A) 膀胱攝影檢查","(B) 子宮輸卵管攝影檢查","(C) 下消化道鋇劑攝影檢查","(D) 電腦斷層檢查"],"answer":1,"image":""},{"id":"md6-109-2-75","subject":"md6","topic":"產科-一般產科","meta":"109年第2次第75題","year":109,"session":2,"number":75,"question":"關於懷孕時生理上的變化，下列敘述何者最正確？","options":["(A) 心輸出量會增加","(B) 周邊血管阻力會增加","(C) 橫膈膜位置會下降","(D) 血液容積會減少"],"answer":0,"image":""},{"id":"md6-109-2-76","subject":"md6","topic":"眼科-視網膜葡萄膜","meta":"109年第2次第76題","year":109,"session":2,"number":76,"question":"15歲女性，因右眼開始視力模糊看不清楚至急診。檢查發現右眼轉動時有明顯疼痛現象，右眼視力為0.4，且有視乳突水腫，左眼檢查均正常。下列何者是最可能診斷？","options":["(A) 視神經炎（optic neuritis）","(B) 巨細胞病毒視網膜炎（cytomegalovirus retinitis）","(C) 中心視網膜靜脈阻塞（central retinal vein occlusion）","(D) 葡萄膜炎（uveitis）"],"answer":0,"image":""},{"id":"md6-109-2-77","subject":"md6","topic":"鼻科學","meta":"109年第2次第77題","year":109,"session":2,"number":77,"question":"對於急性鼻竇炎的敘述，下列何者最不適當？","options":["(A) 大部分是由病毒感染引起","(B) 使用局部皮質類固醇鼻內噴劑可縮短病程","(C) 對於急性細菌性鼻竇炎的首選抗生素為amoxicillin","(D) 眼眶蜂窩性組織炎最容易由蝶鼻竇（sphenoid sinus）的感染蔓延造成"],"answer":3,"image":""},{"id":"md6-109-2-78","subject":"md6","topic":"醫學倫理與法規","meta":"109年第2次第78題","year":109,"session":2,"number":78,"question":"28歲的佳華已有一個3歲的女兒，健康活潑，佳華的公婆一直希望她能再生一個兒子。佳華於6個月前懷孕，身體狀況及胎兒情形均很好，但她仍然擔心孩子是否正常。懷孕24週時要求婦產科醫師為她做羊水穿刺及染色體檢查，一週後染色體檢查結果顯示為XY，但有三個第21對染色體（trisomy 21），佳華和她先生討論後決定要墮胎。以下作法何者最不恰當？","options":["(A) 立刻依法進行墮胎手術","(B) 向他們說明此時期胎兒出生後已有存活的機會及墮胎手術的步驟有那些","(C) 照會小兒科醫師向他們說明唐氏症的罹病及心智狀況等","(D) 轉介給社工師了解他們的想法，給予需要的協助"],"answer":0,"image":""},{"id":"md6-109-2-79","subject":"md6","topic":"醫學倫理與法規","meta":"109年第2次第79題","year":109,"session":2,"number":79,"question":"王醫師是第二年的住院醫師，相當優秀而認真，主治醫師楊醫師指導他寫了一篇論文。當王醫師論文已經完稿，正準備投稿時，同科的陳主任要求王醫師將該篇論文原本的通訊作者楊醫師，改為陳主任自己。王醫師剛好將來想選擇該科做為次專科，因此對於陳主任的要求覺得很困擾。王醫師應該怎麼做較合適？","options":["(A) 按照陳主任的指示，將通訊作者改為陳主任，因為陳主任本來就是該科的主任，擔任指導作者理所當然","(B) 按照陳主任的指示，將通訊作者改為陳主任，因為陳主任對於王醫師將來的選科相當重要，絕對不能得罪陳主任","(C) 仍然將原本指導論文寫作的楊醫師列為通訊作者，因為楊醫師的相關學術領域人脈較好，論文比較容易被接受","(D) 仍然將原本指導論文寫作的楊醫師列為通訊作者，因為論文本來就是楊醫師指導而寫成"],"answer":3,"image":""},{"id":"md6-109-2-80","subject":"md6","topic":"醫學倫理與法規","meta":"109年第2次第80題","year":109,"session":2,"number":80,"question":"有一位耳鼻喉科醫師最近被診斷出罹患愛滋病，下列敘述何者正確？","options":["(A) 為了病人的最大利益，醫師須立即辭職","(B) 只要做好防護措施，醫師仍然可以從事醫療行為","(C) 醫師需跟病人坦承自己罹患愛滋病","(D) 醫師需跟同事坦承自己罹患愛滋病"],"answer":1,"image":""},{"id":"md6-110-1-1","subject":"md6","topic":"麻醉-呼吸道與監視","meta":"110年第1次第1題","year":110,"session":1,"number":1,"question":"按modified Mallampati classification進行氣道評估，請病人做最大張口、舌頭盡力伸出的動作，若只可看見hard palate，而不能看見soft palate，則分類屬於何等級？","options":["(A) class IV","(B) class II","(C) class I","(D) class III"],"answer":0,"image":""},{"id":"md6-110-1-2","subject":"md6","topic":"麻醉-呼吸道與監視","meta":"110年第1次第2題","year":110,"session":1,"number":2,"question":"全身麻醉中，潮氣末二氧化碳（end-tidal CO2）數值突然降低之原因，不包括下列那一項？","options":["(A) 氣管內管彎折","(B) 呼吸迴路鬆脫","(C) 病人發燒","(D) 急性肺栓塞"],"answer":2,"image":""},{"id":"md6-110-1-3","subject":"md6","topic":"麻醉-呼吸道與監視","meta":"110年第1次第3題","year":110,"session":1,"number":3,"question":"基本麻醉監測中，體溫監測的概念與敘述，下列何者錯誤？","options":["(A) 術後低體溫會引起發抖（shivering）反應，在成人可增加代謝產熱50%到100%，此反應可能增加心血管病人的風險","(B) 30分鐘以上的全身麻醉，體溫監測應為常規監測，核心體溫（core temperature）應維持攝氏36度以上","(C) 區域麻醉（regional anesthesia）只會影響周邊溫度控制，不易引發惡性高熱，不須體溫監測","(D) 老年人的血管收縮的閾值（vasoconstrictive threshold）低於年輕人，導致老年人更容易失溫"],"answer":2,"image":""},{"id":"md6-110-1-4","subject":"md6","topic":"麻醉-麻醉藥理","meta":"110年第1次第4題","year":110,"session":1,"number":4,"question":"下列有關局部麻醉劑（local anesthetics）的敘述，何者錯誤？","options":["(A) 局部麻醉劑主要阻斷電位門控型（voltage-gated）鈣離子通道","(B) 神經纖維對局部麻醉劑的敏感性會受軸突直徑（axonal diameter）和髓鞘（myelination）的影響","(C) 若過量會造成心血管的抑制","(D) 高脂溶性局部麻醉劑之作用時間較長"],"answer":0,"image":""},{"id":"md6-110-1-5","subject":"md6","topic":"麻醉-麻醉藥理","meta":"110年第1次第5題","year":110,"session":1,"number":5,"question":"下列有關remifentanil的敘述，何者錯誤？","options":["(A) remifentanil的代謝是經由紅血球和組織中的esterase水解","(B) remifentanil其終端排除半衰期（terminal elimination half-life）不到10分鐘","(C) remifentanil較其他鴉片類藥物不易累積於體內","(D) pseudocholinesterase缺乏者不可使用remifentanil"],"answer":3,"image":""},{"id":"md6-110-1-6","subject":"md6","topic":"麻醉-呼吸道與監視","meta":"110年第1次第6題","year":110,"session":1,"number":6,"question":"有關手術採頭低腳高姿勢（trendelenburg position），下列敘述何者錯誤？","options":["(A) 採頭低腳高姿勢過久，可能會因喉頭水腫導致上呼吸道阻塞","(B) 上腹部的手術通常採用此姿勢","(C) 會增加中央靜脈壓、顱內壓及眼內壓","(D) 因病患的肺功能儲備容量（functional residual capacity）下降，會增加肺塌陷的風險"],"answer":1,"image":""},{"id":"md6-110-1-7","subject":"md6","topic":"麻醉-特殊麻醉與疼痛","meta":"110年第1次第7題","year":110,"session":1,"number":7,"question":"病患因上肢骨折進行手術，麻醉方式採用注射bupivacaine的鎖骨上臂神經叢阻斷（supraclavicular nerve block），過程中發生心室性心搏過速（ventricular tachycardia），下列那一項處置最不恰當？","options":["(A) 給與intralipid（lipid emulsion）","(B) 給與lidocaine","(C) 立即停止注射bupivacaine","(D) 注意可能發生seizure，必要時給與midazolam"],"answer":1,"image":""},{"id":"md6-110-1-8","subject":"md6","topic":"麻醉-特殊麻醉與疼痛","meta":"110年第1次第8題","year":110,"session":1,"number":8,"question":"針對膝蓋人工關節置換手術（total knee arthroplasty），下列何種術後止痛技術之止痛效果最差？","options":["(A) epidural analgesia","(B) femoral nerve block","(C) sciatic nerve block","(D) adductor canal block"],"answer":2,"image":""},{"id":"md6-110-1-9","subject":"md6","topic":"麻醉-特殊麻醉與疼痛","meta":"110年第1次第9題","year":110,"session":1,"number":9,"question":"處理敗血性休克的心血管用藥，下列何者為第一優先考量？","options":["(A) dopamine","(B) epinephrine","(C) norepinephrine","(D) vasopressin"],"answer":2,"image":""},{"id":"md6-110-1-10","subject":"md6","topic":"眼科-視網膜葡萄膜","meta":"110年第1次第10題","year":110,"session":1,"number":10,"question":"有關高度近視患者視網膜及黃斑部常見的病理變化，下列敘述何者錯誤？","options":["(A) 後葡萄腫（posterior staphyloma）","(B) Fuchs斑點（Fuchs spot）","(C) 脈絡膜視網膜萎縮（chorioretinal atrophy）","(D) 血管樣紋（angioid streaks）"],"answer":3,"image":""},{"id":"md6-110-1-11","subject":"md6","topic":"眼科-視網膜葡萄膜","meta":"110年第1次第11題","year":110,"session":1,"number":11,"question":"4歲男孩，右眼可見前房蓄膿（hypopyon），下列何者為最不可能的疾病？","options":["(A) HLA-B27相關急性前葡萄膜炎（acute anterior uveitis）","(B) 白血病（leukemia）","(C) 犬蛔蟲症（toxocariasis）","(D) 網膜芽細胞瘤（retinoblastoma）"],"answer":0,"image":""},{"id":"md6-110-1-12","subject":"md6","topic":"眼科-角膜結膜眼瞼眼窩","meta":"110年第1次第12題","year":110,"session":1,"number":12,"question":"有關微生物角膜潰瘍的敘述，下列何者錯誤？","options":["(A) 中央較大的角膜感染應刮角膜病灶取得檢體，進行微生物培養及玻片染色","(B) 嚴重及無法控制的角膜感染可導致角膜溶解或穿孔","(C) 除了局部點抗生素外，在還未確定感染的微生物種類前，可合併點類固醇","(D) 在還未培養證實為何種菌種感染前，可採用經驗性抗生素療法"],"answer":2,"image":""},{"id":"md6-110-1-13","subject":"md6","topic":"眼科-角膜結膜眼瞼眼窩","meta":"110年第1次第13題","year":110,"session":1,"number":13,"question":"有關角膜結構之敘述，下列何者錯誤？","options":["(A) 鮑曼氏膜（Bowman membrane）係由角膜表皮細胞分泌而成","(B) 角膜表皮之幹細胞絕大多數位於輪部（limbus）","(C) 角膜基質之膠原蛋白纖維，係由蛋白聚醣（proteoglycan）維持其適當間距，以利光線穿過","(D) 出生後，人類角膜內皮細胞即不再分裂（mitosis），故其數目逐年減少"],"answer":0,"image":""},{"id":"md6-110-1-14","subject":"md6","topic":"眼科-水晶體青光眼","meta":"110年第1次第14題","year":110,"session":1,"number":14,"question":"下列何者不是白內障的症狀？","options":["(A) 視力減退（reduced vision）","(B) 單眼複視（monocular diplopia）","(C) 眩光（glare）","(D) 眼睛乾澀（dryness）"],"answer":3,"image":""},{"id":"md6-110-1-15","subject":"md6","topic":"眼科-角膜結膜眼瞼眼窩","meta":"110年第1次第15題","year":110,"session":1,"number":15,"question":"有關重症肌無力（myasthenia gravis, MG）之敘述，下列何者錯誤？","options":["(A) 可能同時存在甲狀腺疾病","(B) 表現皆為雙眼眼球運動障礙，若只有單眼眼皮下垂即可排除MG的診斷","(C) 可能和腫瘤有關","(D) 冰敷眼瞼可以當成一種快篩診斷工具"],"answer":1,"image":""},{"id":"md6-110-1-16","subject":"md6","topic":"眼科-屈光斜弱視","meta":"110年第1次第16題","year":110,"session":1,"number":16,"question":"下列何者為治療調節性內斜視（accommodative esotropia）之第一道步驟？","options":["(A) 斜視手術","(B) 配戴遠視眼鏡","(C) 配戴稜鏡（prism）眼鏡","(D) 使用弱視貼布遮眼"],"answer":1,"image":""},{"id":"md6-110-1-17","subject":"md6","topic":"眼科-角膜結膜眼瞼眼窩","meta":"110年第1次第17題","year":110,"session":1,"number":17,"question":"下列何者是甲狀腺眼疾（thyroid eye disease）最常見的示病性（pathognomonic）臨床徵候？","options":["(A) 眼外肌活動受阻","(B) 眼球突出（proptosis）","(C) 眼瞼下垂（ptosis）","(D) 眼瞼退縮（lid retraction）"],"answer":3,"image":""},{"id":"md6-110-1-18","subject":"md6","topic":"眼科-角膜結膜眼瞼眼窩","meta":"110年第1次第18題","year":110,"session":1,"number":18,"question":"有關眼瞼裂狹小症候群（blepharophimosis）的病徵敘述，下列何者錯誤？","options":["(A) 眼瞼提肌功能差","(B) 眥距過寬（telecanthus）","(C) 眼瞼內翻","(D) 反向內眥贅皮（epicanthus inversus）"],"answer":2,"image":""},{"id":"md6-110-1-19","subject":"md6","topic":"鼻科學","meta":"110年第1次第19題","year":110,"session":1,"number":19,"question":"一位80歲男性病人，患多年之糖尿病但控制不佳，3天前開始右鼻孔腫脹，視力模糊、複視，鼻涕為暗棕色伴血絲；檢查發現右鼻甲變黑，口腔之硬腭中央也稍轉暗黑色。最可能診斷為鼻腔之何種感染？","options":["(A) 綠膿桿菌（Pseudomonas aeruginosa）","(B) 流行感冒嗜血桿菌（Haemophilus influenzae）","(C) 白黴菌（Mucoraceae）","(D) 葡萄球菌（Staphylococcus）"],"answer":2,"image":""},{"id":"md6-110-1-20","subject":"md6","topic":"喉科學與頭頸腫瘤","meta":"110年第1次第20題","year":110,"session":1,"number":20,"question":"某病人經檢查發現左鼻咽部及頸部有腫塊，鼻咽部切片檢查報告為未分化癌（undifferentiated carcinoma），接下來之處理，下列何者最不恰當？","options":["(A) 頭頸部影像學檢查","(B) 腹部超音波","(C) 頸部腫塊切片檢查","(D) 胸部X光"],"answer":2,"image":""},{"id":"md6-110-1-21","subject":"md6","topic":"耳科學","meta":"110年第1次第21題","year":110,"session":1,"number":21,"question":"關於實施眼震電圖（electronystagmography）的溫差試驗（bithermal caloric test）時，下列敘述何者正確？","options":["(A) 右耳灌入30度冷水，左眼眼震快相（rapid phase）向右","(B) 左耳灌入44度溫水，右眼眼震快相（rapid phase）向左","(C) 右耳灌入24度冷空氣，左眼眼震慢相（slow phase）向左","(D) 左耳灌入50度溫空氣，右眼眼震慢相（slow phase）向左"],"answer":1,"image":""},{"id":"md6-110-1-22","subject":"md6","topic":"喉科學與頭頸腫瘤","meta":"110年第1次第22題","year":110,"session":1,"number":22,"question":"下列何種顱底腫瘤於磁振造影檢查時可見鹽及胡椒徵象（salt and pepper sign）？","options":["(A) 聽神經瘤（acoustic neuroma）","(B) 腺樣囊狀癌（adenoid cystic carcinoma）","(C) 膽固醇肉芽腫（cholesterol granuloma）","(D) 副神經節瘤（paraganglioma）"],"answer":3,"image":""},{"id":"md6-110-1-23","subject":"md6","topic":"耳科學","meta":"110年第1次第23題","year":110,"session":1,"number":23,"question":"膽脂瘤（cholesteatoma）手術最不可能包括下列何項術式？","options":["(A) 乳突切除術（mastoidectomy）","(B) 聽小骨鏈成型術（ossiculoplasty）","(C) 上鼓室鑿開術（atticotomy）","(D) 鐙骨切除術（stapedectomy）"],"answer":3,"image":""},{"id":"md6-110-1-24","subject":"md6","topic":"喉科學與頭頸腫瘤","meta":"110年第1次第24題","year":110,"session":1,"number":24,"question":"有關使用外科手術建立呼吸繞道，下列敘述何者正確？","options":["(A) 環甲膜切開術（cricothyrotomy）與氣管切開造口術（tracheostomy）皆為建立長期呼吸繞道之選項","(B) 頸部皮膚橫向切開可避免於術中傷及前頸靜脈（anterior jugular vein）","(C) 氣管切開造口術（tracheostomy）適當位置為圖中處","(D) 氣切手術後如氣管內持續滲血，則可能是傷及外頸動脈之徵兆"],"answer":2,"image":"md6-110-1-24.jpeg"},{"id":"md6-110-1-25","subject":"md6","topic":"喉科學與頭頸腫瘤","meta":"110年第1次第25題","year":110,"session":1,"number":25,"question":"下列手術何者於術後出現聲帶麻痺之機率最低？","options":["(A) 肺局部或全葉切除手術（pneumonectomy or pulmonary lobectomy）","(B) 食道切除手術（esophagectomy）","(C) 心臟繞道手術（coronary artery bypass graft）","(D) 扁桃腺切除手術（tonsillectomy）"],"answer":3,"image":""},{"id":"md6-110-1-26","subject":"md6","topic":"喉科學與頭頸腫瘤","meta":"110年第1次第26題","year":110,"session":1,"number":26,"question":"有關唾液腺結石症（sialolithiasis），下列敘述何者正確？","options":["(A) 結石主要是由hydroxyapatite [Ca5(PO4)3(OH)]組成，通常不含有機物質","(B) 最常發生於腮腺","(C) 腮腺結石大部分是radiolucent，不易僅以X光片診斷","(D) 在無其他輔助方式下，唾液腺內視鏡術（sialoendoscopy）可以移除1公分以上的結石"],"answer":2,"image":""},{"id":"md6-110-1-27","subject":"md6","topic":"喉科學與頭頸腫瘤","meta":"110年第1次第27題","year":110,"session":1,"number":27,"question":"有關唾液腺惡性腫瘤，下列敘述何者正確？","options":["(A) 腮腺及下頷腺最常見的惡性腫瘤均是黏液上皮癌（mucoepidermoid carcinoma）","(B) 黏液上皮癌病理組織中，若黏液細胞（mucinous cell）愈多，則惡性度愈高","(C) 腺樣囊狀癌（adenoid cystic carcinoma）是生長速度較慢的癌症，且易有神經旁侵犯（perineural invasion）","(D) 腺樣囊狀癌最常見治療失敗的原因為遠端轉移，且均在治療後3年內發生"],"answer":2,"image":""},{"id":"md6-110-1-28","subject":"md6","topic":"復健-兒童與一般復健","meta":"110年第1次第28題","year":110,"session":1,"number":28,"question":"下列何者為全球最常見的單基因疾病（single-gene disorder）？","options":["(A) 囊性纖維化（cystic fibrosis）","(B) X染色體脆折症（fragile X syndrome）","(C) 苯酮尿症（PKU，phenylketonuria）","(D) 地中海貧血（海洋性貧血）（thalassemia）"],"answer":3,"image":""},{"id":"md6-110-1-29","subject":"md6","topic":"產科-一般產科","meta":"110年第1次第29題","year":110,"session":1,"number":29,"question":"32歲女性，G3P2，妊娠32週，超音波掃瞄下，羊水最大垂直徑只有1公分，依胎兒生物生理計分法（biophysical profile），於羊水量分項下得分為何？","options":["(A) 3","(B) 2","(C) 1","(D) 0"],"answer":3,"image":""},{"id":"md6-110-1-30","subject":"md6","topic":"婦科-尿失禁與骨盆腔脫垂","meta":"110年第1次第30題","year":110,"session":1,"number":30,"question":"53歲的停經婦女，生過3個小孩，主訴急迫性尿失禁已經1週，下列何項檢查是比較合適的處置？","options":["(A) 尿液檢查及培養","(B) 尿道壓力測量（urethral pressure profile）","(C) 靜脈腎盂造影（IVP）","(D) 膀胱尿道鏡檢查"],"answer":0,"image":""},{"id":"md6-110-1-31","subject":"md6","topic":"產科-一般產科","meta":"110年第1次第31題","year":110,"session":1,"number":31,"question":"婦產科急診有一位20歲女性，主訴月經過期，有陰道點狀出血，左下腹疼痛，下列何種檢查為第一優先？","options":["(A) 腹部超音波檢查","(B) 腹部電腦斷層檢查","(C) 懷孕試驗","(D) 抹片檢查"],"answer":2,"image":""},{"id":"md6-110-1-32","subject":"md6","topic":"婦科-生殖內分泌","meta":"110年第1次第32題","year":110,"session":1,"number":32,"question":"22歲女性，診斷為子宮內膜異位，經2個月danazol藥物治療後，抱怨體重上升，熱潮紅及聲音變低沈。她詢問是否應繼續服藥，最適當的回答是：","options":["(A) danazol是最有效的藥物，繼續觀察","(B) 可能不是藥物引起，可繼續觀察","(C) 配合女性荷爾蒙使用，症狀即可改善","(D) 還有其他有效藥物，應考慮換藥"],"answer":3,"image":""},{"id":"md6-110-1-33","subject":"md6","topic":"婦科-腫瘤","meta":"110年第1次第33題","year":110,"session":1,"number":33,"question":"60歲女性，罹患子宮頸鱗狀上皮細胞癌Ib期，接受子宮根除術（radical hysterectomy）及骨盆腔淋巴摘除術（pelvic lymph node dissection），術後恢復情形良好，依據病理報告可以判斷病患之預後。下列何者並非病患重要之預後因子？","options":["(A) 淋巴有無轉移（status of the lymph node）","(B) 腫瘤體積（size of the primary tumor）","(C) 腫瘤侵犯深度（depth of stromal invasion）","(D) 腫瘤細胞的人類乳突病毒型（HPV types in the tumor cells）"],"answer":3,"image":""},{"id":"md6-110-1-34","subject":"md6","topic":"婦科-腫瘤","meta":"110年第1次第34題","year":110,"session":1,"number":34,"question":"微侵襲性子宮頸癌（microinvasion）是指基質（stroma）侵犯深度不超過多少mm？","options":["(A) 1","(B) 3","(C) 5","(D) 7"],"answer":1,"image":""},{"id":"md6-110-1-35","subject":"md6","topic":"產科-一般產科","meta":"110年第1次第35題","year":110,"session":1,"number":35,"question":"關於孕期疫苗的接種，下列何者正確？","options":["(A) 百日咳疫苗建議在懷孕16至20週就施打","(B) 懷孕婦女在流行季節應接受流感疫苗的接種","(C) 在懷孕時都應該接種水痘疫苗","(D) 對於德國麻疹沒有免疫力的孕婦，在孕期都應該接種Measles-mumps-rubella（MMR）疫苗"],"answer":1,"image":""},{"id":"md6-110-1-36","subject":"md6","topic":"產科-高危險妊娠","meta":"110年第1次第36題","year":110,"session":1,"number":36,"question":"下列懷孕的併發症，發生在過胖孕婦（BMI > 30）的機率比正常體重孕婦的發生率，何者增加最多？","options":["(A) 子癇前症（pre-eclampsia）","(B) 妊娠糖尿病（gestational diabetes）","(C) 死胎（stillbirth）","(D) 產後大出血（postpartum hemorrhage）"],"answer":1,"image":""},{"id":"md6-110-1-37","subject":"md6","topic":"產科-一般產科","meta":"110年第1次第37題","year":110,"session":1,"number":37,"question":"正常陰道生產後，第三產程主動處理方法（active management of the third stage of labor）被證實可減少產後出血。下列何項行為不包括在內？","options":["(A) 由腹部按摩子宮","(B) 適度牽引臍帶（controlled cord traction）","(C) 將手或器械伸入子宮取出／夾出胎盤","(D) 給予促進子宮收縮的藥物（如oxytocin）"],"answer":2,"image":""},{"id":"md6-110-1-38","subject":"md6","topic":"產科-一般產科","meta":"110年第1次第38題","year":110,"session":1,"number":38,"question":"子宮頸之成熟度（cervical favorability）往往與產程進展有密切關連，1964年Dr. Bishop提出Bishop scoring system進行評估，內容共有五項指標，除子宮頸擴張（dilatation）外，尚有四項，下列何項不屬之？","options":["(A) 子宮頸薄度（effacement）","(B) 子宮頸軟硬度（consistency）","(C) 待產時間長短（labour course length）","(D) 胎頭高低（station）"],"answer":2,"image":""},{"id":"md6-110-1-39","subject":"md6","topic":"產科-一般產科","meta":"110年第1次第39題","year":110,"session":1,"number":39,"question":"利用產前超音波評估胎兒狀況（fetal well-being），在日常門診十分普遍，除了估計胎兒大小及胎兒心跳外，常可利用生物物理指標（biophysical profile）進行有效監測，下列何項超音波指標不包括在biophysical profile內？","options":["(A) 羊水量（amniotic fluid volume）","(B) 胎兒呼吸運動（fetal breathing）","(C) 臍帶血流變化（umbilical velocimetry）","(D) 胎兒活動性（fetal movement）及胎兒張力（fetal tone）"],"answer":2,"image":""},{"id":"md6-110-1-40","subject":"md6","topic":"產科-高危險妊娠","meta":"110年第1次第40題","year":110,"session":1,"number":40,"question":"妊娠合併肺水腫（pulmonary edema complicating pregnancy）是懷孕期間相當危急的併發症。下列何者不是發生妊娠合併肺水腫的危險因子？","options":["(A) 妊娠糖尿病（gestational diabetes mellitus）","(B) 子癇前症（preeclampsia）","(C) 敗血症（sepsis syndrome）","(D) 子宮收縮抑制劑（beta-mimetics tocolytic agents）"],"answer":0,"image":""},{"id":"md6-110-1-41","subject":"md6","topic":"產科-一般產科","meta":"110年第1次第41題","year":110,"session":1,"number":41,"question":"32歲G1P0孕婦，妊娠34週因規律性下腹陣痛，前來產房就診。孕婦主訴3小時前有大量清澈液體自陰道流出。產房檢查胎心博呈現良好反應（reactive），子宮每4分鐘規律收縮；內診檢查子宮頸未開，破水測試呈陽性反應；超音波檢查呈羊水稀少（oligohydramnios）現象，胎兒預估體重2,560公克，胎兒呈頭位產式。孕3婦體溫38.6℃，心搏率102 bpm，血壓112/68 mmHg。血液檢驗，WBC 19,000/mm。接下來最適當處置為：","options":["(A) 給與促胎兒肺成熟劑（betamethasone）治療","(B) 給與子宮鬆弛劑（tocolytic agents）治療","(C) 給與抗生素（antibiotics）治療","(D) 立即剖腹生產"],"answer":2,"image":""},{"id":"md6-110-1-42","subject":"md6","topic":"婦科-手術學與診斷技術","meta":"110年第1次第42題","year":110,"session":1,"number":42,"question":"陰部神經電氣學檢測測試pudendal nerve terminal motor latency，可間接測量陰部神經終端神經完整性、神經肌肉的交接處（neuromuscular junction）及其支配之肌肉。測試時須使用指套電極片如St. Mark電極片，經陰道或直腸刺激位於腸骨脊（ischial spine）之陰部神經，並測量何處肌肉之反應？","options":["(A) 肛門括約肌（anal sphincter）","(B) 尿道括約肌（urethral sphincter）","(C) 逼尿肌（detrusor muscle）","(D) 提肛肌（levator ani muscle）"],"answer":0,"image":""},{"id":"md6-110-1-43","subject":"md6","topic":"婦科-生殖道感染與先天異常","meta":"110年第1次第43題","year":110,"session":1,"number":43,"question":"25歲女性，主訴外陰部疼痛三天，檢查發現外陰部有成群的小水泡及表淺性潰瘍，下列何者是最有可能的診斷？","options":["(A) 梅毒（syphilis）","(B) 疱疹（herpes）","(C) 軟性下疳（chancroid）","(D) 病毒疣（genital warts）"],"answer":1,"image":""},{"id":"md6-110-1-44","subject":"md6","topic":"麻醉-呼吸道與監視","meta":"110年第1次第44題","year":110,"session":1,"number":44,"question":"腹腔鏡手術時，腹腔內的二氧化碳長時間壓力過高，可能產生的併發症，下列何者錯誤？","options":["(A) 氣體栓塞","(B) 心律不整","(C) 高血壓","(D) 胃酸逆流"],"answer":2,"image":""},{"id":"md6-110-1-45","subject":"md6","topic":"婦科-腫瘤","meta":"110年第1次第45題","year":110,"session":1,"number":45,"question":"已經生育過的56歲婦女，非常焦慮其是否會有子宮內膜癌的風險，下列情形何者風險較低？","options":["(A) 停經過晚（late menopause）","(B) 有家族Lynch II syndrome","(C) 吸菸（smoking）","(D) 糖尿病（diabetes mellitus）"],"answer":2,"image":""},{"id":"md6-110-1-46","subject":"md6","topic":"婦科-腫瘤","meta":"110年第1次第46題","year":110,"session":1,"number":46,"question":"下列那種子宮肉瘤，因為對賀爾蒙的反應最好，可以考慮在手術治療後，用高劑量黃體素治療？","options":["(A) 子宮肌肉瘤（uterine leiomyosarcoma）","(B) 低惡性子宮內膜間質肉瘤（low-grade endometrial stromal sarcoma）","(C) 癌肉瘤（carcinosarcoma）","(D) 未分化子宮內膜間質肉瘤（undifferentiated endometrial stromal sarcoma）"],"answer":1,"image":""},{"id":"md6-110-1-47","subject":"md6","topic":"婦科-腫瘤","meta":"110年第1次第47題","year":110,"session":1,"number":47,"question":"關於卵巢上皮癌的分期，雖然卵巢癌並無侵犯到腹腔的其他組織，但是卻有骨盆腔淋巴結的轉移（pelvic lymph node metastases），應該歸類在2014-FIGO的那一個期別？","options":["(A) IIB","(B) IIIC","(C) IIIB","(D) IIIA1"],"answer":3,"image":""},{"id":"md6-110-1-48","subject":"md6","topic":"婦科-生殖內分泌","meta":"110年第1次第48題","year":110,"session":1,"number":48,"question":"關於次發性無月經症（secondary amenorrhea）之敘述，下列何者錯誤？","options":["(A) 泌乳激素過高血症（hyperprolactinemia）會導致次發性無月經症","(B) Asherman's syndrome（intrauterine synechia）會導致次發性無月經症","(C) Kallmann's syndrome會導致次發性無月經症，常合併嗅覺喪失或障礙","(D) 懷孕是一種次發性無月經症"],"answer":2,"image":""},{"id":"md6-110-1-49","subject":"md6","topic":"婦科-生殖內分泌","meta":"110年第1次第49題","year":110,"session":1,"number":49,"question":"有關誘發排卵前LH surge所需的性激素血中濃度之敘述，下列何者正確？","options":["(A) Progesterone血中濃度要高於15 ng/mL，而且維持此高濃度的時間必須超過50小時","(B) Progesterone血中濃度要高於5 ng/mL，而且維持此高濃度的時間必須超過50小時","(C) E2（estradiol）血中濃度要高於200 pg/mL，而且維持此高濃度的時間必須超過50小時","(D) E2（estradiol）血中濃度要高於100 pg/mL，而且維持此高濃度的時間必須超過50小時"],"answer":2,"image":""},{"id":"md6-110-1-50","subject":"md6","topic":"婦科-生殖內分泌","meta":"110年第1次第50題","year":110,"session":1,"number":50,"question":"關於多囊性卵巢症候群（polycystic ovary syndrome, PCOS）的診斷標準（criteria of diagnosis）之敘述，下列何者不是診斷標準之一？","options":["(A) 超音波有多囊性卵巢（polycystic ovary, PCO）之影像","(B) 有雄性激素過多（hyperandrogenism）之臨床症狀","(C) 有排卵寡少（oligoovulation）或長期無排卵（chronic anovulation）之情形","(D) 體重過重或肥胖"],"answer":3,"image":""},{"id":"md6-110-1-51","subject":"md6","topic":"婦科-生殖內分泌","meta":"110年第1次第51題","year":110,"session":1,"number":51,"question":"24歲男性接受不孕症檢查時，發現患者精液中沒有精蟲，同時伴隨兩側輸精管有先天性缺少（CBAVD）時，常與下列何種疾病相關？","options":["(A) Cystic fibrosis","(B) Kallmann's syndrome","(C) Kartagener's syndrome","(D) Klinefelter syndrome"],"answer":0,"image":""},{"id":"md6-110-1-52","subject":"md6","topic":"婦科-生殖內分泌","meta":"110年第1次第52題","year":110,"session":1,"number":52,"question":"37歲G0P0的已婚女性，因為不孕症而求診，自述月經已經2年沒來，且驗孕呈陰性反應。抽血檢查發現血中FSH濃度為42 mIU/mL，Estradiol<20 pg/mL。其母親在36歲時即已停經，家中有個哥哥智能不足，應建議下列那一項基因檢查？","options":["(A) FMR gene","(B) SMN1 gene","(C) CYP21 gene","(D) PKD1 gene"],"answer":0,"image":""},{"id":"md6-110-1-53","subject":"md6","topic":"婦科-生殖內分泌","meta":"110年第1次第53題","year":110,"session":1,"number":53,"question":"有關評估子宮輸卵管攝影檢查（hysterosalpingography HSG）的結果，下列何者正確？","options":["(A) 通常需另外藉助超音波的幫助，來區別中膈（septate）或雙角（bicornuate）子宮異常","(B) 若診斷確定為中膈子宮異常合併習慣性流產時，可以藉由腹腔鏡中膈切除來改善預後","(C) 有遠端輸卵管阻塞時，不建議使用抗生素預防子宮輸卵管攝影檢查時所產生的感染","(D) 當子宮輸卵管攝影檢查發現有近端輸卵管阻塞時，就可以確定診斷，直接接受手術或試管嬰兒治療"],"answer":0,"image":""},{"id":"md6-110-1-54","subject":"md6","topic":"產科-高危險妊娠","meta":"110年第1次第54題","year":110,"session":1,"number":54,"question":"29歲有甲狀腺低下合併習慣性流產的不孕症婦女，接受不孕症治療後目前妊娠5週，下列何種狀況，在懷孕初期最須要考慮補充甲狀腺素？","options":["(A) 甲狀腺刺激激素（TSH）4.5 mIU/L以及抗甲狀腺抗體陽性","(B) 甲狀腺刺激激素（TSH）2.0 mIU/L以及抗甲狀腺抗體陽性","(C) 甲狀腺刺激激素（TSH）4.5 mIU/L以及抗甲狀腺抗體陰性","(D) 甲狀腺刺激激素（TSH）2.0 mIU/L以及抗甲狀腺抗體陰性"],"answer":0,"image":""},{"id":"md6-110-1-55","subject":"md6","topic":"婦科-生殖內分泌","meta":"110年第1次第55題","year":110,"session":1,"number":55,"question":"施行人工輔助生殖技術（ART）時，當使用人類絨毛促性腺激素（hCG）來幫助卵子最後成熟，下列敘述何者正確？","options":["(A) 因為人類絨毛促性腺激素和黃體化激素（LH）同源性高，可以與其接受器交叉反應，但是人類絨毛促性腺激素半衰期較短","(B) 當卵巢濾泡大小至少兩顆到達17～ 18 mm時，施打人類絨毛促性腺激素來誘發排卵","(C) 取卵會在人類絨毛促性腺激素施打後12～14小時手術","(D) 使用促性腺激素釋放激素拮抗劑（antagonist）療程時，當卵子很多的時候，使用人類絨毛促性腺激素來幫助卵子最後成熟，可以減少產生卵巢過度刺激的危險"],"answer":1,"image":""},{"id":"md6-110-1-56","subject":"md6","topic":"產科-一般產科","meta":"110年第1次第56題","year":110,"session":1,"number":56,"question":"36歲孕婦，G5P2SA1AA1，妊娠16週，接受超音波檢查，結果如圖所示：則胎兒異常器官名稱與特徵（sign）為何？","options":["(A) head，frog sign","(B) cerebellum，banana sign","(C) pons，lemon sign","(D) ventricle，keyhole sign"],"answer":0,"image":"md6-110-1-56.jpeg"},{"id":"md6-110-1-57","subject":"md6","topic":"產科-一般產科","meta":"110年第1次第57題","year":110,"session":1,"number":57,"question":"承上題，最可能的診斷為下列何者？","options":["(A) Down syndrome","(B) trisomy 18","(C) trisomy 13","(D) anencephaly"],"answer":3,"image":""},{"id":"md6-110-1-58","subject":"md6","topic":"復健-神經復健","meta":"110年第1次第58題","year":110,"session":1,"number":58,"question":"一個病人因疝氣手術後，大腿外側有感覺麻痛（meralgia paresthetica），他最有可能是那一條神經受傷？","options":["(A) 股外側皮神經（lateral femoral cutaneous nerve）","(B) 隱神經（saphenous nerve）","(C) 下臀神經（inferior gluteal nerve）","(D) 閉孔神經（obturator nerve）"],"answer":0,"image":""},{"id":"md6-110-1-59","subject":"md6","topic":"復健-神經復健","meta":"110年第1次第59題","year":110,"session":1,"number":59,"question":"關於脊髓損傷後之異位性骨化症（heterotopic ossification），下列敘述何者錯誤？","options":["(A) 常發生在髖關節","(B) 常發生在受傷後1至6個月","(C) 可用三相式骨掃描（three phase bone scan）檢測","(D) 在骨化初期可採用手術切除，以避免其惡化"],"answer":3,"image":""},{"id":"md6-110-1-60","subject":"md6","topic":"復健-神經復健","meta":"110年第1次第60題","year":110,"session":1,"number":60,"question":"某病患的脊髓損傷被診斷為Brown-Séquard症候群，下列何者為其典型症狀？","options":["(A) 肢體肌力、痛覺與溫度感覺喪失，但本體感覺則是完好的","(B) 本體感覺喪失，但肢體肌力、痛覺與溫度感覺則是完好的","(C) 四肢肌力喪失，上肢喪失的程度比下肢嚴重","(D) 脊髓受傷對側的下肢痛覺與溫度感覺喪失，同側的下肢肌力喪失"],"answer":3,"image":""},{"id":"md6-110-1-61","subject":"md6","topic":"復健-神經復健","meta":"110年第1次第61題","year":110,"session":1,"number":61,"question":"對一位罹患慢性髓鞘病變（chronic demyelination）的病人實施肌電診斷檢查時，最不常出現下列那一種結果？","options":["(A) 遠端潛期（distal latency）變長","(B) 複合肌肉動作電位（compound muscle action potential）振幅（amplitude）增加","(C) 感覺神經傳導速度（sensory nerve conduction velocity）變慢","(D) 運動單元電位波（motor unit action potential）的多相波（polyphasic wave）比率增加"],"answer":1,"image":""},{"id":"md6-110-1-62","subject":"md6","topic":"復健-骨骼肌肉損傷與疾患","meta":"110年第1次第62題","year":110,"session":1,"number":62,"question":"下列何者不是造成足底筋膜炎的致病因素？","options":["(A) 高弓足（high-arched foot）","(B) 距下關節旋後（subtalar joint supination）","(C) 蹠屈（plantar flexion）活動度變差","(D) 第一蹠趾關節僵硬（hallux limitus）"],"answer":1,"image":""},{"id":"md6-110-1-63","subject":"md6","topic":"復健-骨骼肌肉損傷與疾患","meta":"110年第1次第63題","year":110,"session":1,"number":63,"question":"王先生在足球賽時，被他隊球員由右膝外側撞擊，聽到「POP」一聲，立即不支倒地。身體檢查發現右膝十分腫脹，關節活動度只能彎曲約10至90度，下列處置何者最正確？","options":["(A) 可能有重要韌帶受傷，宜緊急開刀","(B) 後十字韌帶受損的可能性最高","(C) 先抽取關節積液或積血","(D) 立即安排右膝的電腦斷層掃描"],"answer":2,"image":""},{"id":"md6-110-1-64","subject":"md6","topic":"復健-神經復健","meta":"110年第1次第64題","year":110,"session":1,"number":64,"question":"1965年Melzack及Wall兩位學者提出的門閾學說（gate control theory）是刺激X神經纖維，以抑制Y神經纖維的傳遞。下列敘述何者正確？","options":["(A) X = A型（神經纖維），Y = B型（神經纖維）","(B) X = A型（神經纖維），Y = C型（神經纖維）","(C) X = B型（神經纖維），Y = A型（神經纖維）","(D) X = C型（神經纖維），Y = A型（神經纖維）"],"answer":1,"image":""},{"id":"md6-110-1-65","subject":"md6","topic":"復健-兒童與一般復健","meta":"110年第1次第65題","year":110,"session":1,"number":65,"question":"關於脊柱側彎之敘述，下列何者正確？","options":["(A) 側彎測量器（scoliometer）主要是測量額平面（frontal plane）的角度","(B) 脊柱側彎與睡姿有關","(C) 電刺激對於脊柱側彎有明確的療效","(D) 背架主要的目的是避免脊柱側彎的惡化"],"answer":3,"image":""},{"id":"md6-110-1-66","subject":"md6","topic":"復健-截肢與義肢輔具","meta":"110年第1次第66題","year":110,"session":1,"number":66,"question":"有關燒燙傷後使用的輔具（orthoses for burns），以下敘述何者錯誤？","options":["(A) 患者在燒燙傷後，肢體喜歡擺位在屈曲（flexed）的舒適姿勢","(B) 燒燙傷輔具（orthoses for burns）的目的在避免關節攣縮和變形","(C) 為了避免燒燙傷後的皮膚組織及疤痕增生（hypertrophic scarring），可以選擇使用壓力衣（compression garments）等輔具","(D) 如果怕腋下的燒燙傷後造成肩膀的攣縮，可以使用飛機副木（airplane splint）來維持內收（adduction）的姿勢"],"answer":3,"image":""},{"id":"md6-110-1-67","subject":"md6","topic":"復健-心肺復健與運動處方","meta":"110年第1次第67題","year":110,"session":1,"number":67,"question":"下列那種疾病不是常造成運動選手在劇烈運動中猝死的原因？","options":["(A) 肥厚性心肌症（hypertrophic cardiomyopathy）","(B) 動脈瘤（aortic aneurysms）破裂","(C) 冠狀動脈異常（coronary artery anomalies）","(D) 二尖瓣脫垂（mitral valve prolapse）"],"answer":3,"image":""},{"id":"md6-110-1-68","subject":"md6","topic":"復健-心肺復健與運動處方","meta":"110年第1次第68題","year":110,"session":1,"number":68,"question":"對於清除呼吸道中的蓄痰，下列描述何者錯誤？","options":["(A) 常使用姿勢引流（postural drainage）","(B) 可減少呼吸時消耗的能量，改善氣體交換","(C) 應儘量避免使用袪痰藥物（mucoactive medications）","(D) 可減少肺泡塌陷和減少感染機率"],"answer":2,"image":""},{"id":"md6-110-1-69","subject":"md6","topic":"復健-兒童與一般復健","meta":"110年第1次第69題","year":110,"session":1,"number":69,"question":"下列那一種兒童疾病，最常合併有水腦症（hydrocephalus）？","options":["(A) 脊髓脊膜膨出症（myelomeningocele）","(B) 腦性麻痺（cerebral palsy）","(C) 脊髓性肌肉萎縮症（spinal muscular atrophy）","(D) 肌肉失養症（muscular dystrophy）"],"answer":0,"image":""},{"id":"md6-110-1-70","subject":"md6","topic":"復健-神經復健","meta":"110年第1次第70題","year":110,"session":1,"number":70,"question":"小腦損傷最有可能造成下列那一種語言的障礙？","options":["(A) 運動失調型吶吃（ataxic dysarthria）","(B) 弛緩型吶吃（flaccid dysarthria）","(C) 布洛卡氏失語症（Broca aphasia）","(D) 經皮質感覺型失語症（transcortical sensory aphasia）"],"answer":0,"image":""},{"id":"md6-110-1-71","subject":"md6","topic":"復健-骨骼肌肉損傷與疾患","meta":"110年第1次第71題","year":110,"session":1,"number":71,"question":"腋網症候群（axillary web syndrome）為下列那一癌症手術後最常見之疼痛症狀？","options":["(A) 頭頸癌","(B) 肺癌","(C) 乳癌","(D) 口腔癌"],"answer":2,"image":""},{"id":"md6-110-1-72","subject":"md6","topic":"婦科-良性腫瘤與內膜異位","meta":"110年第1次第72題","year":110,"session":1,"number":72,"question":"35歲女性病患，主訴下腹痛，磁振造影檢查發現骨盆腔有囊狀病灶（星號），在T2加權影像（左圖）呈稍低訊號，T1加權影像（右圖）呈高訊號。其診斷為何？","options":["(A) 巧克力囊腫（chocolate cyst）","(B) 卵巢癌（ovarian cancer）","(C) 輸卵管卵巢膿瘍（tubo-ovarian abscess）","(D) 畸胎瘤（teratoma）"],"answer":0,"image":"md6-110-1-72.jpeg"},{"id":"md6-110-1-73","subject":"md6","topic":"復健-骨骼肌肉損傷與疾患","meta":"110年第1次第73題","year":110,"session":1,"number":73,"question":"20歲男性病患膝關節受傷，接受膝部X光及磁振造影檢查如圖，下列何者診斷為錯誤？","options":["(A) 病人有anterior cruciate ligament tear","(B) 病人有bone contusion","(C) 病人有lateral meniscal tear","(D) X光可看到Segond fracture"],"answer":2,"image":"md6-110-1-73.jpeg"},{"id":"md6-110-1-74","subject":"md6","topic":"復健-神經復健","meta":"110年第1次第74題","year":110,"session":1,"number":74,"question":"關於動脈硬化之頸動脈狹窄（carotid stenosis）及其治療，下列何者錯誤？","options":["(A) 有症狀的頸動脈狹窄，如大於60%，可考慮外科手術或支架置放治療","(B) 無症狀的狹窄，無論其嚴重程度，均以內科治療即可，不必接受手術或支架置放治療","(C) 頸動脈狹窄，最好發於頸動脈分支處（carotid bifurcation）","(D) 頸部磁振血管影像（MRA）有助於診斷頸動脈狹窄"],"answer":1,"image":""},{"id":"md6-110-1-75","subject":"md6","topic":"產科-一般產科","meta":"110年第1次第75題","year":110,"session":1,"number":75,"question":"關於產後出血的敘述，下列何者最正確？","options":["(A) 造成產後出血最常見的原因是子宮內翻（uterine inversion）","(B) 因應懷孕的生理變化，低血壓是產後出血最早出現的徵兆","(C) 急診治療的第一步驟是立即會診婦產科找出產後出血原因","(D) 麥角生物鹼（ergot alkaloids）會升高血壓，不適用於子癲前症病人的產後出血"],"answer":3,"image":""},{"id":"md6-110-1-76","subject":"md6","topic":"耳科學","meta":"110年第1次第76題","year":110,"session":1,"number":76,"question":"有關外耳道異物以清水沖洗的敘述，下列何者最不適當？","options":["(A) 用耳鏡確認耳膜沒有破裂才能沖洗","(B) 使用冰水沖洗","(C) 須確認異物不會吸水膨脹","(D) 取出異物後，應用耳鏡檢查有無造成耳膜、聽小骨及外耳道傷害"],"answer":1,"image":""},{"id":"md6-110-1-77","subject":"md6","topic":"麻醉-麻醉藥理","meta":"110年第1次第77題","year":110,"session":1,"number":77,"question":"一位體重約72公斤男性，因工作不慎臉部受傷，在急診室進行縫合手術時，使用lidocaine合併epinephrine局部麻醉時，lidocaine之最高劑量為多少mg？","options":["(A) 100","(B) 250","(C) 500","(D) 700"],"answer":2,"image":""},{"id":"md6-110-1-78","subject":"md6","topic":"醫學倫理與法規","meta":"110年第1次第78題","year":110,"session":1,"number":78,"question":"一位耳鼻喉科醫師在幫病人拿耳朵中的異物時，同時發現病人有中耳腔積水的情形，醫師並未徵求病人的同意，就直接放置引流管。這位醫師的作法違反了一些倫理面向，但不包括下列那一個？","options":["(A) 告知義務","(B) 知情同意","(C) 守密","(D) 自主決定"],"answer":2,"image":""},{"id":"md6-110-1-79","subject":"md6","topic":"醫學倫理與法規","meta":"110年第1次第79題","year":110,"session":1,"number":79,"question":"某醫院內已婚的甲醫師與其診治的病人發生婚外情，院方應採取的最佳處置原則為何？","options":["(A) 應該立即中止這位醫師與病人間的醫療關係","(B) 應該立即告知其配偶","(C) 此行為屬於個人隱私，由各人自己負責","(D) 應該立即中止這位醫師的醫療職務"],"answer":0,"image":""},{"id":"md6-110-1-80","subject":"md6","topic":"醫學倫理與法規","meta":"110年第1次第80題","year":110,"session":1,"number":80,"question":"依據赫爾辛基宣言（Declaration of Helsinki），關於醫學研究與醫療照護之結合，下列何者正確？","options":["(A) 當醫師有充足的理由相信參與研究不會對其病人的健康有不良的影響時，醫師就可以結合醫學研究與醫療照護","(B) 為確保責任清楚，醫學研究不應與醫療照護結合","(C) 醫師可以結合醫學研究與醫療照護，但此情況僅止於此研究有潛在的預防、診斷或治療的價值。且醫師有充足的理由相信參與研究不會對其病人的健康有不良的影響","(D) 醫師要結合醫學研究與醫療照護，只需經過主管機關核准即可"],"answer":2,"image":""},{"id":"md6-110-2-1","subject":"md6","topic":"麻醉-呼吸道與監視","meta":"110年第2次第1題","year":110,"session":2,"number":1,"question":"下列何者不能作為施行正壓呼吸的工具？","options":["(A) 凡德里面罩（Venturi mask）","(B) 喉頭罩（laryngeal mask airway）","(C) 氣管內管（endotracheal tube）","(D) 麻醉面罩（anesthetic mask）"],"answer":0,"image":""},{"id":"md6-110-2-2","subject":"md6","topic":"麻醉-呼吸道與監視","meta":"110年第2次第2題","year":110,"session":2,"number":2,"question":"術後急性腎損傷（acute kidney injury, AKI）影響手術死亡率，有關麻醉與手術中腎功能監測的描述，下列何者正確？","options":["(A) 術中尿液輸出量（urine output）減少與術後急性腎損傷息息相關，但術後尿液輸出量減少為正常現象，不影響腎功能","(B) 對腎功能變化的監測，腎絲球過濾率（glomerular filtration rate, GFR）測量較術後血漿肌酸酐濃度（creatinine concentration）變化，更有敏感性（sensitivity）與專一性（specificity）","(C) 術後血漿肌酸酐濃度（creatinine concentration）的增加與術後GFR的降低，彼此無關聯性","(D) 血中Neutrophil gelatinase-associated lipocalin（NGAL）可做為AKI的早期生物指標（biomarker），最早在術後24小時內就可測得"],"answer":1,"image":""},{"id":"md6-110-2-3","subject":"md6","topic":"麻醉-呼吸道與監視","meta":"110年第2次第3題","year":110,"session":2,"number":3,"question":"關於麻醉深度的監測，下列敘述何者正確？","options":["(A) 腦部為高代謝率的器官，約使用15%的心輸出量（cardiac output），腦血氧監測（cerebral oximeter）為良好的麻醉深度監測指標","(B) 以腦電圖（EEG）為基礎的監測（包含bispectral index (BIS), entropy等），無助於減少術中awareness的風險","(C) 腦電圖（EEG）的分析，對鎮靜程度及全身麻醉深度之監測很有助益","(D) 研究結果顯示，麻醉中若BIS數值越低，術後的後遺症越少"],"answer":2,"image":""},{"id":"md6-110-2-4","subject":"md6","topic":"麻醉-麻醉藥理","meta":"110年第2次第4題","year":110,"session":2,"number":4,"question":"下列有關吸入性麻醉劑的敘述，何者錯誤？","options":["(A) desflurane在血液和身體組織中的低溶解度導致其麻醉的快速甦醒","(B) sevoflurane與desflurane皆為氯化物","(C) desflurane可以被乾燥的二氧化碳吸收劑降解為一氧化碳","(D) sevoflurane可以被乾燥的二氧化碳吸收劑降解為compound A"],"answer":1,"image":""},{"id":"md6-110-2-5","subject":"md6","topic":"麻醉-麻醉藥理","meta":"110年第2次第5題","year":110,"session":2,"number":5,"question":"下列何者不是局部麻醉劑（local anesthetics）引起的中樞神經症狀？","options":["(A) 口邊麻木（circumoral numbness）","(B) 舌頭感覺異常（tongue paresthesia）","(C) 眩暈（dizziness）","(D) 幻覺（hallucination）"],"answer":3,"image":""},{"id":"md6-110-2-6","subject":"md6","topic":"麻醉-特殊麻醉與疼痛","meta":"110年第2次第6題","year":110,"session":2,"number":6,"question":"執行硬脊膜外麻醉（epidural anesthesia）時，當穿刺針具抵達硬脊膜外腔（epidural space）時，會有sudden loss of resistance，這是因為穿刺針具通過了下列何項解剖構造？","options":["(A) erector spinal muscle豎脊肌","(B) interspinous ligament棘間韌帶","(C) ligamentum flavum黃韌帶","(D) dura mater硬脊膜"],"answer":2,"image":""},{"id":"md6-110-2-7","subject":"md6","topic":"麻醉-特殊麻醉與疼痛","meta":"110年第2次第7題","year":110,"session":2,"number":7,"question":"顱內血腫（intracerebral hematoma）接受急診手術，有關其麻醉處置，下列何者錯誤？","options":["(A) 麻醉誘導宜避免使用具腦血管舒張作用的藥物","(B) ketamine是理想的麻醉誘導選擇藥物","(C) 術後若須維持氣管插管到加護病房照護，以narcotics-based麻醉輔以肌肉鬆弛劑是良好的麻醉維持選擇","(D) 若腦部灌注壓（cerebral perfusion pressure）小於60 mmHg，則腦部有再度受損的風險"],"answer":1,"image":""},{"id":"md6-110-2-8","subject":"md6","topic":"麻醉-特殊麻醉與疼痛","meta":"110年第2次第8題","year":110,"session":2,"number":8,"question":"針對傳統的open thoracotomy開胸手術進行之全肺切除，下列何種手術後止痛方式的止痛效果可能最好？","options":["(A) 硬膜外止痛（epidural analgesia）","(B) 靜脈病患自控式止痛（intravenous patient-controlled analgesia, IVPCA）","(C) 腋下神經叢阻斷（axillary nerve block）","(D) 口服NSAID類止痛藥"],"answer":0,"image":""},{"id":"md6-110-2-9","subject":"md6","topic":"麻醉-特殊麻醉與疼痛","meta":"110年第2次第9題","year":110,"session":2,"number":9,"question":"關於重症病人營養支持的併發症，下列何者錯誤？","options":["(A) 腸道營養（enteral nutrition）常併發腹瀉，亦可能增加胃脹而逆流的風險","(B) 周邊靜脈營養（peripheral parenteral nutrition）會增加靜脈炎的危險","(C) 將全靜脈營養（total parenteral nutrition）減量至停用時，須注意胰島素劑量與低血糖的監測，若是腸道營養減量時，則不需特別注意","(D) 接受靜脈營養的重症病人若出現敗血症，應考慮周邊或中央靜脈管路造成的血行性感染（bloodstream infection）"],"answer":2,"image":""},{"id":"md6-110-2-10","subject":"md6","topic":"眼科-視網膜葡萄膜","meta":"110年第2次第10題","year":110,"session":2,"number":10,"question":"關於Vogt-Koyanagi-Harada氏病，疾病初期最不可能看到的臨床徵候為：","options":["(A) 視力減退","(B) 聽力減退","(C) 皮膚白斑（vitiligo）","(D) 腦脊髓液（CSF）的單核白血球增多（pleocytosis）"],"answer":2,"image":""},{"id":"md6-110-2-11","subject":"md6","topic":"眼科-視網膜葡萄膜","meta":"110年第2次第11題","year":110,"session":2,"number":11,"question":"裂孔性網膜剝離（rhegmatogenous retinal detachment）不會出現下列何種表現？","options":["(A) 相對性傳入性瞳孔反射障礙（relative afferent pupillary defect）","(B) 低眼壓（hypotony）","(C) 視物變大（macropsia）","(D) 虹彩炎（iritis）"],"answer":2,"image":""},{"id":"md6-110-2-12","subject":"md6","topic":"眼科-角膜結膜眼瞼眼窩","meta":"110年第2次第12題","year":110,"session":2,"number":12,"question":"有關細菌性角膜潰瘍的敘述，下列何者錯誤？","options":["(A) 常出現的臨床表徵包含上皮破損、角膜水腫及浸潤物","(B) 治療完整後角膜通常可維持透明","(C) 外傷是危險因子之一","(D) 綠膿桿菌的感染常與配戴隱形眼鏡有關"],"answer":1,"image":""},{"id":"md6-110-2-13","subject":"md6","topic":"眼科-角膜結膜眼瞼眼窩","meta":"110年第2次第13題","year":110,"session":2,"number":13,"question":"輪部（limbus）上的Horner-Trantas dots會出現於下列那一種疾病？","options":["(A) 砂眼（trachoma）","(B) 春季角結膜炎（vernal keratoconjunctivitis）","(C) 圓錐角膜（keratoconus）","(D) 威爾遜氏疾病（Wilson disease）"],"answer":1,"image":""},{"id":"md6-110-2-14","subject":"md6","topic":"眼科-水晶體青光眼","meta":"110年第2次第14題","year":110,"session":2,"number":14,"question":"一個急性隅角閉鎖性青光眼（acute angle-closure glaucoma）的病人來急診就診，檢查發現眼壓50 mmHg、角膜水腫、前房有些許細胞漂浮，下列何項急診處置最不適當？","options":["(A) 給與20% mannitol靜脈注射治療","(B) 給與口服碳酸酐酶抑制劑（carbonic anhydrase inhibitor）","(C) 給與眼用藥物2% pilocarpine及0.1% dexamethasone","(D) 立即安排雷射小樑網整形術（laser trabeculoplasty）"],"answer":3,"image":""},{"id":"md6-110-2-15","subject":"md6","topic":"眼科-屈光斜弱視","meta":"110年第2次第15題","year":110,"session":2,"number":15,"question":"下列何種治療方式對弱視較無效？","options":["(A) 遮閉（occlusion）療法","(B) 禁制（penalization）療法","(C) 屈光配鏡（optical devices）","(D) 手術療法（surgery）"],"answer":3,"image":""},{"id":"md6-110-2-16","subject":"md6","topic":"眼科-角膜結膜眼瞼眼窩","meta":"110年第2次第16題","year":110,"session":2,"number":16,"question":"動眼神經（oculomotor nerve）並不支配下列何條眼肌？","options":["(A) 內直肌（medial rectus muscle）","(B) 外直肌（lateral rectus muscle）","(C) 上直肌（superior rectus muscle）","(D) 下直肌（inferior rectus muscle）"],"answer":1,"image":""},{"id":"md6-110-2-17","subject":"md6","topic":"眼科-角膜結膜眼瞼眼窩","meta":"110年第2次第17題","year":110,"session":2,"number":17,"question":"有關甲狀腺眼疾（thyroid eye disease）的敘述，下列何者錯誤？","options":["(A) 眼病變之程度與甲狀腺功能成正相關","(B) 此種眼疾發生於女性較男性為多","(C) 臨床徵候包括眼瞼退縮（lid retraction）、限制性眼肌病變（restrictive myopathy）及突眼（proptosis）","(D) 嚴重突眼會造成暴露性角膜病變（exposure keratopathy）"],"answer":0,"image":""},{"id":"md6-110-2-18","subject":"md6","topic":"眼科-角膜結膜眼瞼眼窩","meta":"110年第2次第18題","year":110,"session":2,"number":18,"question":"Jones氏試驗（Jones test）用於評估那項功能？","options":["(A) 淚液分泌功能","(B) 淚液排流功能","(C) 淚液成分","(D) 淚囊功能"],"answer":1,"image":""},{"id":"md6-110-2-19","subject":"md6","topic":"耳科學","meta":"110年第2次第19題","year":110,"session":2,"number":19,"question":"有關突發性耳聾（sudden deafness, or idiopathic sudden sensorineural hearing loss）臨床特徵，下列敘述何者錯誤？","options":["(A) 3天內聽力惡化致純音聽力檢查顯示連續3個頻率有超過30 dB以上的感音型聽力損失","(B) 大部分病人都會同時有耳鳴","(C) 無論治療或不治療，部分病人會恢復","(D) 高頻聽力損失比低頻聽力損失之預後較佳"],"answer":3,"image":""},{"id":"md6-110-2-20","subject":"md6","topic":"喉科學與頭頸腫瘤","meta":"110年第2次第20題","year":110,"session":2,"number":20,"question":"需長期氣道繞道照護的病人，下列何種方式最恰當？","options":["(A) 氣管內插管","(B) 氣管切開術","(C) 環甲膜切開術","(D) 高壓噴氣換氣術"],"answer":1,"image":""},{"id":"md6-110-2-21","subject":"md6","topic":"喉科學與頭頸腫瘤","meta":"110年第2次第21題","year":110,"session":2,"number":21,"question":"口腔癌大多屬於何種組織學形態？","options":["(A) 鱗狀細胞癌（squamous cell carcinoma）","(B) 未分化癌（undifferentiated carcinoma）","(C) 疣樣癌（verrucous carcinoma）","(D) 腺癌（adenocarcinoma）"],"answer":0,"image":""},{"id":"md6-110-2-22","subject":"md6","topic":"喉科學與頭頸腫瘤","meta":"110年第2次第22題","year":110,"session":2,"number":22,"question":"最常見的急性細菌性唾液腺炎，是何種細菌之感染？","options":["(A) 肺炎鏈球菌（Streptococcus pneumoniae）","(B) 金黃色葡萄球菌（Staphylococcus aureus）","(C) 大腸桿菌（Escherichia coli）","(D) 綠膿桿菌（Pseudomonas aeruginosa）"],"answer":1,"image":""},{"id":"md6-110-2-23","subject":"md6","topic":"耳科學","meta":"110年第2次第23題","year":110,"session":2,"number":23,"question":"有關前庭神經炎（vestibular neuritis），下列敘述何者正確？","options":["(A) 大部分發生在前庭神經下支（inferior division of vestibular nerve）","(B) 有部分病人會轉變成良性姿勢性陣發性眩暈（benign positional paroxysmal vertigo）","(C) 急性期自發性眼震（spontaneous nystagmus）快相（rapid phase）向疾病側","(D) 治療的藥物以抗病毒藥物效果最佳"],"answer":1,"image":""},{"id":"md6-110-2-24","subject":"md6","topic":"鼻科學","meta":"110年第2次第24題","year":110,"session":2,"number":24,"question":"下列那一項不是鼻竇內視鏡手術的絕對適應症（absolute indications）？","options":["(A) 鼻竇炎併發眼眶膿瘍及視力損傷","(B) 鼻竇炎併有急性加重的症狀","(C) 鼻竇炎併發腦膜炎","(D) 急性侵犯型黴菌性鼻竇炎"],"answer":1,"image":""},{"id":"md6-110-2-25","subject":"md6","topic":"鼻科學","meta":"110年第2次第25題","year":110,"session":2,"number":25,"question":"有關鼻及鼻竇倒生性乳突瘤（inverted papilloma），下列敘述何者錯誤？","options":["(A) 因血管豐富不適合在術前做切片檢查","(B) 有合併惡性鱗狀細胞癌的可能性","(C) 影像學檢查常見腫瘤起源處有局部骨質增生","(D) 與人類乳突病毒第6、11型可能有關"],"answer":0,"image":""},{"id":"md6-110-2-26","subject":"md6","topic":"喉科學與頭頸腫瘤","meta":"110年第2次第26題","year":110,"session":2,"number":26,"question":"某病人因吞食不明液體輕生，家人發現後緊急送至急診室，下列敘述何者正確？","options":["(A) 鹼性溶液腐蝕性較酸性溶液強，造成深層組織受損之機率較高","(B) 如家屬查明吞食之液體屬強酸或強鹼時，則可用對應之鹼或酸性溶液中和之","(C) 應於12小時內儘快安排食道內視鏡檢查，以確定組織受損之範圍與深度","(D) 內視鏡檢查時不可放置鼻胃管，以免造成日後食道攣縮狹窄"],"answer":0,"image":""},{"id":"md6-110-2-27","subject":"md6","topic":"喉科學與頭頸腫瘤","meta":"110年第2次第27題","year":110,"session":2,"number":27,"question":"有關鰓器畸型（branchial apparatus anomaly），下列敘述何者正確？","options":["(A) 第一鰓器畸型較第二鰓器畸型常見","(B) 第二鰓器畸型又可以分成兩型，兩型均可能通至扁桃窩（tonsillar fossa）","(C) 第二鰓器畸型以反覆化膿性甲狀腺炎（suppurative thyroiditis）為主要臨床症狀","(D) 第三、四鰓器畸型可能會有瘻管通至梨狀窩（pyriform sinus）"],"answer":3,"image":""},{"id":"md6-110-2-28","subject":"md6","topic":"產科-一般產科","meta":"110年第2次第28題","year":110,"session":2,"number":28,"question":"懷孕時陰道以何種菌株為優勢菌株？","options":["(A) Streptococcus agalactiae","(B) Peptostreptococcus","(C) Lactobacillus acidophilus","(D) Staphylococcus aureus"],"answer":2,"image":""},{"id":"md6-110-2-29","subject":"md6","topic":"產科-一般產科","meta":"110年第2次第29題","year":110,"session":2,"number":29,"question":"懷孕期間血色素（hemoglobin）會生理性降低，主要原因為：","options":["(A) 孕婦身體的鐵儲存量減少","(B) 母體部分的血液流動到胎盤及胎兒身上","(C) Reticulocytosis的速度降低","(D) 血漿的容量（plasma volume）增加"],"answer":3,"image":""},{"id":"md6-110-2-30","subject":"md6","topic":"產科-一般產科","meta":"110年第2次第30題","year":110,"session":2,"number":30,"question":"33歲女性，G2P0A1，最後一次月經開始日為9週前，因自行驗孕呈陽性反應而來門診作第一次產檢，她上一胎是早期懷孕合併自然流產，這一胎是計畫性懷孕；來門診時母親的體溫、心跳速率、呼吸速率、血壓均正常，內診時發現：子宮大小約為懷孕7～8週且雙側子宮附屬器無異常發現、子宮頸緊閉且無陰道出血，在門診時幫她做了超音波檢查發現：正常子宮內懷孕、胎兒頭臀徑（crown-rump length）0.7公分、根據胎兒頭臀徑所預估的懷孕週數為7.2週，超音波確定測不到胎心音。下列何者為最適當的診斷？","options":["(A) 不完全流產（incomplete abortion）","(B) 子宮外孕（ectopic pregnancy）","(C) 過期流產（missed abortion）","(D) 先兆性流產（threatened abortion）"],"answer":2,"image":""},{"id":"md6-110-2-31","subject":"md6","topic":"產科-一般產科","meta":"110年第2次第31題","year":110,"session":2,"number":31,"question":"就胎兒循環而言，下列何者之循環血液含氧量最高？","options":["(A) 動脈導管（ductus arteriosus）","(B) 靜脈導管（ductus venosus）","(C) 升主動脈（ascending aorta）","(D) 上腔靜脈（superior vena cava）"],"answer":1,"image":""},{"id":"md6-110-2-32","subject":"md6","topic":"產科-高危險妊娠","meta":"110年第2次第32題","year":110,"session":2,"number":32,"question":"關於地中海貧血（thalassemia），下列敘述何者正確？","options":["(A) 若夫妻二人為同型地中海貧血帶因者，則胎兒為重型地中海貧血的機率為35%","(B) 乙型地中海型貧血大多數是β-globin deletion而來","(C) 若母親平均紅血球體積（MCV）＜ 80 fl，就可診斷為地中海貧血帶因者","(D) 甲型地中海型貧血無法由血紅素電泳的結果偵測出來"],"answer":3,"image":""},{"id":"md6-110-2-33","subject":"md6","topic":"產科-高危險妊娠","meta":"110年第2次第33題","year":110,"session":2,"number":33,"question":"母血中胎兒游離性基因（cell-free fetal DNA）篩檢，無法檢驗出下列何種胎兒異常？","options":["(A) 基因單點突變（point mutation）","(B) 染色體三倍體症（trisomy）","(C) 性染色體數目異常","(D) 染色體微小片段缺失（microdeletion）"],"answer":0,"image":""},{"id":"md6-110-2-34","subject":"md6","topic":"產科-高危險妊娠","meta":"110年第2次第34題","year":110,"session":2,"number":34,"question":"下列何者為產後子宮收縮無力最常見的原因（uterine atony）？","options":["(A) 多胞胎（multiple fetuses）","(B) 前置胎盤（placenta previa）","(C) 胎盤早期剝離（placental abruption）","(D) 母體肥胖（obesity）"],"answer":0,"image":""},{"id":"md6-110-2-35","subject":"md6","topic":"產科-一般產科","meta":"110年第2次第35題","year":110,"session":2,"number":35,"question":"關於胎頭對於母親骨盆腔的相關位置如附圖，下列何者正確？","options":["(A) LOA","(B) LOP","(C) ROA","(D) ROP"],"answer":1,"image":"md6-110-2-35.jpeg"},{"id":"md6-110-2-36","subject":"md6","topic":"產科-高危險妊娠","meta":"110年第2次第36題","year":110,"session":2,"number":36,"question":"34歲孕婦，G1P0，本次懷孕接受一般健保給付之產檢項目，產檢結果發現先天性橫膈膜疝氣（congenital diaphragmatic hernia），經與主治醫師討論後，由於橫膈膜疝氣合併肝臟脫疝（liver herniation），且肺部頭部比率（lung-to-head ratio）小於1.4，而決定進行胎兒鏡氣管阻塞術（fetal endoscopic tracheal occlusion, FETO），手術順利，並於34週平安生產，下列何種疾病不宜考慮胎兒鏡手術？","options":["(A) 雙胞胎輸血症候群（twin-twin transfusion syndrome）","(B) 後尿道瓣膜（posterior urethral valve）","(C) 羊膜帶釋放（amnionic band release）","(D) 薦尾椎畸胎瘤（sacrococcygeal teratoma）"],"answer":3,"image":""},{"id":"md6-110-2-37","subject":"md6","topic":"產科-高危險妊娠","meta":"110年第2次第37題","year":110,"session":2,"number":37,"question":"20歲林小姐，沒有任何過去病史且第一次懷孕。當懷孕26週時被告知有妊娠糖尿病，經過飲食控制後再回來門診追蹤時發現空腹血糖168 mg/dL，此時醫生應該建議她如何控制接下來孕期的血糖？","options":["(A) 只需要飲食控制","(B) 只需口服的降血糖藥物","(C) 胰島素和飲食控制","(D) 產檢時追蹤血糖值即可，不用特別控制"],"answer":2,"image":""},{"id":"md6-110-2-38","subject":"md6","topic":"產科-高危險妊娠","meta":"110年第2次第38題","year":110,"session":2,"number":38,"question":"38歲孕婦，為一B型肝炎（hepatitis B）感染者，懷孕26週血清檢驗結果：B型肝炎表面抗原陽性HBsAg(+)，B型肝炎e抗原陽性HBeAg(+)，B型肝炎病毒量HBV viral load超過10,000,000 copies/mL；孕婦未接受抗B型肝炎病毒藥物治療，新生兒出生後接受免疫預防性治療（immunoprophylaxis）及兒童完整的B型肝炎疫苗接種。此一新生兒感染B型肝炎的風險為：","options":["(A) 1%","(B) 10%","(C) 50%","(D) 90%"],"answer":1,"image":""},{"id":"md6-110-2-39","subject":"md6","topic":"產科-高危險妊娠","meta":"110年第2次第39題","year":110,"session":2,"number":39,"question":"懷孕期間，母胎感染症經垂直傳播可引致子宮內胎兒感染（intrauterine fetal infection）導致胎兒缺陷。下列那一項胎兒超音波表徵不符合母胎感染病源的致畸型效應（teratogens effects）？","options":["(A) 胎兒水腫（hydrops fetalis）－微小病毒（parvovirus B19）","(B) 顱內鈣化（intracranial calcifications）－巨細胞病毒（cytomegalovirus, CMV）","(C) 先天性心臟缺陷（congenital heart defects）－弓形蟲（toxoplasmosis）","(D) 小頭症（microcephaly）－德國麻疹（rubella）"],"answer":2,"image":""},{"id":"md6-110-2-40","subject":"md6","topic":"婦科-手術學與診斷技術","meta":"110年第2次第40題","year":110,"session":2,"number":40,"question":"下列關於診斷性子宮鏡敘述，何者較不適當？","options":["(A) 常建議不孕症病人接受檢查","(B) 對於不明原因子宮出血有診斷幫助","(C) 不可於門診使用","(D) 對於子宮腔的檢查，診斷性子宮鏡優於子宮輸卵管攝影（HSG）"],"answer":2,"image":""},{"id":"md6-110-2-41","subject":"md6","topic":"產科-一般產科","meta":"110年第2次第41題","year":110,"session":2,"number":41,"question":"子宮肌瘤與懷孕的關係，下列敘述何者較不適當？","options":["(A) 大部分的子宮肌瘤在懷孕期間不會變大","(B) 子宮肌瘤在懷孕期間，經常導致不好的預後（outcome）","(C) 子宮肌瘤手術後採取陰道生產時，其發生子宮破裂的機率為0.47%","(D) 子宮黏膜下肌瘤會降低生育率（fertility rates）"],"answer":1,"image":""},{"id":"md6-110-2-42","subject":"md6","topic":"婦科-良性腫瘤與內膜異位","meta":"110年第2次第42題","year":110,"session":2,"number":42,"question":"有關子宮肌瘤，下列敘述何者最不適當？","options":["(A) 多產婦容易長子宮肌瘤","(B) 吸菸減少了子宮肌瘤的發生率","(C) 大部分停經後荷爾蒙療法不會刺激肌瘤生長","(D) 性傳染病不會增加子宮肌瘤發生率"],"answer":0,"image":""},{"id":"md6-110-2-43","subject":"md6","topic":"產科-高危險妊娠","meta":"110年第2次第43題","year":110,"session":2,"number":43,"question":"關於Turner syndrome，下列敘述何者最適當？","options":["(A) 約25,000名女新生兒中有1名","(B) 患者可能在懷孕期間因主動脈破裂而猝死的風險增加","(C) 生長激素（growth hormone）治療建議從青春期開始","(D) 性腺類固醇應該從9歲或10歲開始"],"answer":1,"image":""},{"id":"md6-110-2-44","subject":"md6","topic":"婦科-腫瘤","meta":"110年第2次第44題","year":110,"session":2,"number":44,"question":"Psammoma bodies最常見於何種卵巢瘤？","options":["(A) 子宮內膜異位瘤（endometrioma）","(B) 漿液性瘤（serous cystadenoma）","(C) 黏液性瘤（mucinous cystadenoma）","(D) 畸胎瘤（teratoma）"],"answer":1,"image":""},{"id":"md6-110-2-45","subject":"md6","topic":"婦科-手術學與診斷技術","meta":"110年第2次第45題","year":110,"session":2,"number":45,"question":"下列何者不是腹腔鏡子宮切除的併發症？","options":["(A) 皮下氣腫（subcutaneous emphysema）","(B) 腸穿孔（bowel perforation）","(C) 外髂動脈損傷（external iliac artery injury）","(D) 子宮穿孔（uterine perforation）"],"answer":3,"image":""},{"id":"md6-110-2-46","subject":"md6","topic":"婦科-生殖道感染與先天異常","meta":"110年第2次第46題","year":110,"session":2,"number":46,"question":"下列何者不是診斷Human Immunodeficiency Virus（HIV）感染的檢測方法？","options":["(A) Enzyme-linked immunosorbent assay（ELISA）test","(B) rapid HIV test","(C) Southern blot","(D) Western blot"],"answer":2,"image":""},{"id":"md6-110-2-47","subject":"md6","topic":"婦科-良性腫瘤與內膜異位","meta":"110年第2次第47題","year":110,"session":2,"number":47,"question":"一個25歲有過性經驗女性來到急診，她主訴為腹痛併有噁心想吐，她的最後一次月經是27天前。手術中發現闌尾為正常，但子宮附件（adnexum）有腫塊，腫塊組織切除後圖像如下，下列何者是最有可能的診斷？","options":["(A) 輸卵管卵巢膿瘍（tubo-ovarian abscess）","(B) 卵巢子宮內膜異位瘤（ovarian endometrioma）","(C) 輸卵管子宮外孕（tubal pregnancy）","(D) 卵巢畸胎瘤（ovarian teratoma）"],"answer":3,"image":"md6-110-2-47.jpeg"},{"id":"md6-110-2-48","subject":"md6","topic":"婦科-生殖道感染與先天異常","meta":"110年第2次第48題","year":110,"session":2,"number":48,"question":"關於骨盆腔發炎的敘述，下列何者最不適當？","options":["(A) 不一定有明顯的症狀","(B) 感染的病菌，經常是由內子宮頸往子宮內膜以及輸卵管上行性感染造成","(C) 經常是多種病菌混合感染","(D) 確診後皆要住院接受抗生素治療"],"answer":3,"image":""},{"id":"md6-110-2-49","subject":"md6","topic":"婦科-腫瘤","meta":"110年第2次第49題","year":110,"session":2,"number":49,"question":"42歲女性，子宮頸抹片報告的診斷是atypical squamous cells of undetermined significance（ASC-US），接下來何種處置較為適當？","options":["(A) 應立即接受手術","(B) 可以置之不理，3年後再追蹤抹片","(C) 應接受陰道鏡檢查或3～6個月後追蹤抹片","(D) 可能是暫時性HPV感染，可以維持1年一次抹片"],"answer":2,"image":""},{"id":"md6-110-2-50","subject":"md6","topic":"婦科-腫瘤","meta":"110年第2次第50題","year":110,"session":2,"number":50,"question":"39歲婦女，經診斷為子宮頸鱗狀上皮細胞癌，接受子宮根除術及骨盆腔淋巴結廓清術（radical hysterectomy and bilateral pelvic lymph node dissection），下列何者不屬於復發有關的高風險因子？","options":["(A) 靠近邊緣，或切端邊緣有腫瘤（positive or close margins）","(B) 大腫瘤（large tumor size）","(C) 淋巴結有轉移（positive lymph nodes）","(D) 顯微鏡檢下有子宮旁結締組織侵犯（microscopic parametrial involvement）"],"answer":1,"image":""},{"id":"md6-110-2-51","subject":"md6","topic":"婦科-腫瘤","meta":"110年第2次第51題","year":110,"session":2,"number":51,"question":"關於罹患卵巢癌的危險因子，下列敘述何者較相關？","options":["(A) 多產","(B) 服用避孕藥超過5年","(C) 不孕","(D) 曾經接受輸卵管結紮"],"answer":2,"image":""},{"id":"md6-110-2-52","subject":"md6","topic":"婦科-腫瘤","meta":"110年第2次第52題","year":110,"session":2,"number":52,"question":"有關子宮內膜癌之敘述，下列何項正確？","options":["(A) 相對於第一型（type I）子宮內膜癌病人，第二型（type II）子宮內膜癌病人有較好的預後","(B) 第二型（type II）子宮內膜癌與Lynch syndrome有相關","(C) 大部分第二型（type II）子宮內膜癌病人具有遺傳性的PTEN基因突變","(D) 大部分的子宮內膜癌可歸類為第一型（type I）"],"answer":3,"image":""},{"id":"md6-110-2-53","subject":"md6","topic":"婦科-腫瘤","meta":"110年第2次第53題","year":110,"session":2,"number":53,"question":"外陰癌（vulvar cancer）最常見的細胞型態為：","options":["(A) adenocarcinoma","(B) squamous cell carcinoma","(C) basal cell carcinoma","(D) Paget disease"],"answer":1,"image":""},{"id":"md6-110-2-54","subject":"md6","topic":"婦科-生殖內分泌","meta":"110年第2次第54題","year":110,"session":2,"number":54,"question":"受精（fertilization）的過程依序為何？①capacitation ②acrosome reaction ③cortical reaction","options":["(A) ①②③","(B) ②①③","(C) ③①②","(D) ①③②"],"answer":0,"image":""},{"id":"md6-110-2-55","subject":"md6","topic":"婦科-生殖內分泌","meta":"110年第2次第55題","year":110,"session":2,"number":55,"question":"有關卵巢過度刺激症候群，下列敘述何者錯誤？","options":["(A) 是醫源性造成","(B) 用長療程刺激排卵可抑制其發生","(C) 當週期不植入胚胎，可降低其發生機會","(D) 病因與微血管通透性增加有關"],"answer":1,"image":""},{"id":"md6-110-2-56","subject":"md6","topic":"婦科-生殖內分泌","meta":"110年第2次第56題","year":110,"session":2,"number":56,"question":"57歲女性，G2P2，年輕時因為子宮肌瘤併貧血之故已切除子宮，乳房超音波發現有纖維腺囊腫。近來因為有熱潮紅和夜汗等症狀，影響睡眠，情緒和記憶力，故求診。下列那項治療是最不建議的？","options":["(A) transdermal estradiol","(B) oral estradiol","(C) oral estradiol + medroxyprogesterone","(D) hypothalamus neurokinin receptor B antagonist"],"answer":2,"image":""},{"id":"md6-110-2-57","subject":"md6","topic":"婦科-尿失禁與骨盆腔脫垂","meta":"110年第2次第57題","year":110,"session":2,"number":57,"question":"女性急性尿滯留（acute urinary retention）最常見的原因為何？","options":["(A) 陰道生產後","(B) 骨盆腔手術或尿失禁手術之後","(C) 尿道感染","(D) 逼尿肌收縮不良（detrusor underactivity）"],"answer":1,"image":""},{"id":"md6-110-2-58","subject":"md6","topic":"復健-神經復健","meta":"110年第2次第58題","year":110,"session":2,"number":58,"question":"當這個病人雙手推牆時，發現他右側肩胛骨鼓起並往外移動，他最有可能是那一條神經病變？","options":["(A) 長胸神經（long thoracic nerve）","(B) 背肩胛神經（dorsal scapular nerve）","(C) 腋下神經（axillary nerve）","(D) 副脊椎神經（spinal accessory nerve）"],"answer":0,"image":"md6-110-2-58.jpeg"},{"id":"md6-110-2-59","subject":"md6","topic":"復健-神經復健","meta":"110年第2次第59題","year":110,"session":2,"number":59,"question":"關於人類腦中風的併發症（stroke complication），下列敘述何者錯誤？","options":["(A) 適當的擺位可預防患側肢水腫","(B) 腦中風病人常發生患側肩痛","(C) 吸入性肺炎（aspiration pneumonia）是腦中風早期常見的感染症","(D) 病患經診斷有急性下肢靜脈栓塞（venous thrombosis），應臥床至少一週以上"],"answer":3,"image":""},{"id":"md6-110-2-60","subject":"md6","topic":"復健-骨骼肌肉損傷與疾患","meta":"110年第2次第60題","year":110,"session":2,"number":60,"question":"下列何種治療骨質疏鬆的藥物可促進骨合成的活性？","options":["(A) 雙磷酸鹽類（bisphosphonate）","(B) 抑鈣激素（calcitonin）","(C) 副甲狀腺衍生物（teriparatide）","(D) 選擇性雌激素調節劑（selective estrogen receptor modulator）"],"answer":2,"image":""},{"id":"md6-110-2-61","subject":"md6","topic":"復健-截肢與義肢輔具","meta":"110年第2次第61題","year":110,"session":2,"number":61,"question":"有關截肢患者的復健，下列那一個描述不恰當？","options":["(A) 創傷性截肢（traumatic amputation）的患者對義肢裝配必須是傷口癒合後才可開始","(B) 手術後的殘肢照護（postoperative care）包括要處理殘肢傷口問題，肌肉力量的訓練，與教育患者及看護對殘肢的照護","(C) 義肢裝配及訓練（prosthetic fitting and training）的好壞，將會決定截肢患者未來繼續使用義肢的意願","(D) 對義肢的長期追蹤及照護（long-term follow-up care）包括評估殘肢的狀況，義肢的狀況，患者的步態，以及是否有達到當初預期的功能"],"answer":0,"image":""},{"id":"md6-110-2-62","subject":"md6","topic":"復健-骨骼肌肉損傷與疾患","meta":"110年第2次第62題","year":110,"session":2,"number":62,"question":"下列關於僵直性脊椎炎之敘述，何者正確？","options":["(A) 發生肌腱接骨點病變（enthesopathy）的比率高於類風濕性關節炎","(B) HLA-B27之陽性率為100%","(C) 復健運動須強調脊椎前屈運動","(D) 症狀發作初期，薦腸關節（sacroiliac joint）X光影像即可見到骨頭被侵蝕"],"answer":0,"image":""},{"id":"md6-110-2-63","subject":"md6","topic":"復健-骨骼肌肉損傷與疾患","meta":"110年第2次第63題","year":110,"session":2,"number":63,"question":"某65歲女性，因長時間走路後引發雙膝疼痛並有早晨雙膝僵硬不適。X-ray發現膝內側關節腔（medial compartment）狹窄及軟骨下囊腫（subchondral cyst）。下列何者為最正確之診斷？","options":["(A) 類風濕性關節炎（rheumatoid arthritis）","(B) 痛風性關節炎（gouty arthritis）","(C) 退化性骨關節炎（osteoarthritis）","(D) 感染性關節炎（infectious arthritis）"],"answer":2,"image":""},{"id":"md6-110-2-64","subject":"md6","topic":"復健-物理因子治療與評估","meta":"110年第2次第64題","year":110,"session":2,"number":64,"question":"下列何者不是退化性關節炎病人接受熱敷的目的？","options":["(A) 改善局部血流循環","(B) 減低疼痛","(C) 促進關節面軟骨再生","(D) 使關節周邊肌肉韌帶放鬆"],"answer":2,"image":""},{"id":"md6-110-2-65","subject":"md6","topic":"復健-心肺復健與運動處方","meta":"110年第2次第65題","year":110,"session":2,"number":65,"question":"有關患者接受手術前後的肺部復健之敘述，下列何者錯誤？","options":["(A) 對於胸腔或腹部手術後之肺部併發症以肺泡塌陷及肺炎最常見","(B) 預防性的胸腔照護可以降低術後的罹病率和死亡","(C) 術後的擺位是讓患者在輕鬆的位置，可以改善呼吸的方式，一般是把好的肺葉放在上方","(D) 對於準備接受胸腹部手術的患者，應該在手術前就接受整體性的胸腔照護"],"answer":2,"image":""},{"id":"md6-110-2-66","subject":"md6","topic":"復健-心肺復健與運動處方","meta":"110年第2次第66題","year":110,"session":2,"number":66,"question":"在運動選手的訓練中，有所謂超負荷訓練的原則（overload principle of sports training），以下那一項是超負荷訓練原則最不重要的？","options":["(A) 訓練的頻率（frequency of training）","(B) 訓練的強度（intensity of training）","(C) 訓練的場所（place of training）","(D) 運動模式的種類（type of exercise mode）"],"answer":2,"image":""},{"id":"md6-110-2-67","subject":"md6","topic":"復健-兒童與一般復健","meta":"110年第2次第67題","year":110,"session":2,"number":67,"question":"早期療育（early intervention）介入模式的特性，下列那一項錯誤？","options":["(A) 強調跨專業的科際整合式（multidisciplinary）的團隊合作方式","(B) 以醫院為主的治療模式","(C) 建議父母接受相關訓練以補強家庭能力","(D) 研究顯示發展遲緩兒童愈早接受治療效果愈好"],"answer":1,"image":""},{"id":"md6-110-2-68","subject":"md6","topic":"復健-兒童與一般復健","meta":"110年第2次第68題","year":110,"session":2,"number":68,"question":"一位5歲兒童接受學齡前兒童魏氏智力測驗（平均值為100分，標準差為15分），分數為35分，認知功能遲緩程度為下列何者？","options":["(A) 輕度","(B) 中度","(C) 重度","(D) 極重度"],"answer":2,"image":""},{"id":"md6-110-2-69","subject":"md6","topic":"復健-神經復健","meta":"110年第2次第69題","year":110,"session":2,"number":69,"question":"病人有小指與無名指的麻木感、刺痛，肘關節內側的酸痛以及手部無力，被懷疑有肘隧道症候群（cubital tunnel syndrome），這是那條神經受到傷害？","options":["(A) 正中神經（median nerve）","(B) 尺神經（ulnar nerve）","(C) 橈神經（radial nerve）","(D) 肌皮神經（musculocutaneous nerve）"],"answer":1,"image":""},{"id":"md6-110-2-70","subject":"md6","topic":"復健-神經復健","meta":"110年第2次第70題","year":110,"session":2,"number":70,"question":"吞嚥治療時常使用之方法的描述，以下何者錯誤？","options":["(A) 頭轉向健側以減少食物在梨狀竇（pyriformis sinus）滯留","(B) 低頭姿勢（chin-tuck）以保護氣道","(C) 頭傾向（tilt）健側以利用較有力的一側進食","(D) 使用食物增稠劑（thickener）"],"answer":0,"image":""},{"id":"md6-110-2-71","subject":"md6","topic":"復健-骨骼肌肉損傷與疾患","meta":"110年第2次第71題","year":110,"session":2,"number":71,"question":"病患肩膀活動角度正常，但在進行空罐測驗（empty can test）時呈陽性反應，下列那一條肌腱最可能受傷？","options":["(A) 肱二頭肌（biceps brachialis）","(B) 棘上肌（supraspinatus）","(C) 棘下肌（infraspinatus）","(D) 肩胛下肌（subscapularis）"],"answer":1,"image":""},{"id":"md6-110-2-72","subject":"md6","topic":"鼻科學","meta":"110年第2次第72題","year":110,"session":2,"number":72,"question":"16歲男孩，主訴鼻塞、濃稠鼻涕已經超過一年。根據此張X光片，最可能的診斷是：","options":["(A) chronic rhinitis","(B) chronic paranasal sinusitis","(C) traumatic fracture of facial bone","(D) tumors in the paranasal sinus"],"answer":1,"image":"md6-110-2-72.jpeg"},{"id":"md6-110-2-73","subject":"md6","topic":"眼科-角膜結膜眼瞼眼窩","meta":"110年第2次第73題","year":110,"session":2,"number":73,"question":"35歲病人車禍顏面骨折，合併有複視（右眼異常），接受電腦斷層檢查，下列敘述何者錯誤？","options":["(A) 眼眶的爆裂性骨折（blowout fracture）是可能的診斷","(B) 眼眶爆裂性骨折可合併眼球凹陷","(C) 傳統的X光檢查無法診斷眼眶的爆裂性骨折","(D) 在眼眶的內側及下方是這種骨折最常發生的位置"],"answer":2,"image":"md6-110-2-73.jpeg"},{"id":"md6-110-2-74","subject":"md6","topic":"婦科-腫瘤","meta":"110年第2次第74題","year":110,"session":2,"number":74,"question":"37歲女性，下腹部電腦斷層檢查呈現如圖，箭號所指之敘述何者最為可能？","options":["(A) 囊腺瘤（cystadenoma）","(B) 子宮肌瘤（myoma）","(C) 畸胎瘤（teratoma）","(D) 膀胱瘤（bladder tumor）"],"answer":0,"image":"md6-110-2-74.jpeg"},{"id":"md6-110-2-75","subject":"md6","topic":"復健-神經復健","meta":"110年第2次第75題","year":110,"session":2,"number":75,"question":"下列何者屬於周邊神經麻痺之病徵？","options":["(A) 無力伴隨疼痛","(B) 臉部半邊下垂","(C) 神經反射出現過度反射","(D) 無力突然發生"],"answer":0,"image":""},{"id":"md6-110-2-76","subject":"md6","topic":"醫學倫理與法規","meta":"110年第2次第76題","year":110,"session":2,"number":76,"question":"關於親密伴侶暴力（intimate partner violence）的敘述，下列何者最不適當？","options":["(A) 親密伴侶暴力的發生常有其週而復始的循環現象","(B) 受暴者最危險的時期是在揭露受到暴力侵犯到試圖離開施暴者的時候","(C) 接觸受暴者時應避免問及是否有自殺或殺人意圖","(D) 多處傷口且傷痕癒合狀況不一，應考慮親密伴侶暴力的可能性"],"answer":2,"image":""},{"id":"md6-110-2-77","subject":"md6","topic":"麻醉-呼吸道與監視","meta":"110年第2次第77題","year":110,"session":2,"number":77,"question":"關於孕婦在急救的處置與一般成人相較，下列敘述何者最正確？","options":["(A) 氣管插管時最好選用尺寸較小號的氣管內管","(B) 若使用快速順序氣管內管插管（rapid-sequence intubation），使用誘導藥物的劑量要減半","(C) 若使用電擊去顫（defibrillation），所需的電擊劑量要減半","(D) 若子宮位置高過肚臍，在急救過程中須把子宮推往右側"],"answer":0,"image":""},{"id":"md6-110-2-78","subject":"md6","topic":"醫學倫理與法規","meta":"110年第2次第78題","year":110,"session":2,"number":78,"question":"有一位35歲女性，先生為獨子，已有二女目前懷孕第三胎，經超音波檢查後，想問醫師胎兒的性別，下列何者較為正確？","options":["(A) 醫師不能跟她說，因她可能會去把小孩拿掉","(B) 醫師可以跟她說，因為這是病患的權利","(C) 醫師可以跟她說，但病人須簽署不去墮胎的同意書","(D) 醫師可以跟她說，但須向衛生局通報"],"answer":1,"image":""},{"id":"md6-110-2-79","subject":"md6","topic":"醫學倫理與法規","meta":"110年第2次第79題","year":110,"session":2,"number":79,"question":"知情同意的過程中，所謂的「自願（voluntariness）」是指病人在做醫療決定時，不受到他人的不當影響。所謂的不當影響，不包括下列那一項？","options":["(A) 強迫（coercion）","(B) 操控（manipulation）","(C) 說服（persuasion）","(D) 限制（constraint）"],"answer":2,"image":""},{"id":"md6-110-2-80","subject":"md6","topic":"醫學倫理與法規","meta":"110年第2次第80題","year":110,"session":2,"number":80,"question":"有一位30歲男性，近期剛被診斷出有愛滋病，病人請醫師勿告訴任何人，下列何者正確？","options":["(A) 醫師需為病人守密、因此醫師不應再有任何下一動作","(B) 醫師雖需為病人守密、但愛滋病例外","(C) 依法通報衛生主管機關","(D) 立即告訴家屬，但答應不告訴其他人也不會通報"],"answer":2,"image":""},{"id":"md6-111-1-1","subject":"md6","topic":"麻醉-呼吸道與監視","meta":"111年第1次第1題","year":111,"session":1,"number":1,"question":"執行全身麻醉誘導後，完成置放氣管內管，病人生命徵象穩定。確認氣管內管位置在氣管內的正確方法，下列何者錯誤？","options":["(A) 後頸部超音波掃描影像，確認氣管內管位置","(B) 通氣時聽診胸部、腹部呼吸音，發現兩側胸部呼吸音強，上腹部聽不到呼吸音","(C) 呼氣末二氧化碳監測儀，可見呼氣時呈現二氧化碳方波連續出現","(D) 光纖支氣管鏡檢查，確認氣管內管位置"],"answer":0,"image":""},{"id":"md6-111-1-2","subject":"md6","topic":"麻醉-呼吸道與監視","meta":"111年第1次第2題","year":111,"session":1,"number":2,"question":"關於侵入性心血管監測，下列敘述何者正確？","options":["(A) 在橈動脈（radial artery）置入動脈導管，先做Allen test可預防動脈導管後遺症","(B) 使用肺動脈導管監測，被證實會改善臨床結果（clinical outcomes），在重症病人建議使用","(C) 若要監測心臟前負荷（cardiac preload），動態測量（如stroke volume variation）較靜態測量（如central venous pressure）更能預測血管內容積的反應性（intravascular volume responsiveness）","(D) CVP（central venous pressure）數值與循環血量成正比"],"answer":2,"image":""},{"id":"md6-111-1-3","subject":"md6","topic":"麻醉-呼吸道與監視","meta":"111年第1次第3題","year":111,"session":1,"number":3,"question":"麻醉中體溫的監測與維護非常重要，有關麻醉中體溫變化與處置，下列敘述何者正確？","options":["(A) 麻醉開始後的體溫降低很常見，核心體溫（core temperature）降低0.5°C到1.5°C，原因是重分布低體溫（redistribution hypothermia）","(B) 體表加溫（surface warming）可有效預防麻醉開始後第1小時的低體溫","(C) 呼吸道保溫與保濕（airway heating and humidification）對成人比對小兒有效","(D) 區域麻醉（regional anesthesia）不影響中樞溫度控制，比起全身麻醉，較不會有低體溫狀況"],"answer":0,"image":""},{"id":"md6-111-1-4","subject":"md6","topic":"麻醉-麻醉藥理","meta":"111年第1次第4題","year":111,"session":1,"number":4,"question":"下列有關局部麻醉劑（local anesthetics）的敘述，何者錯誤？","options":["(A) 電位門控型（voltage-gated）鈉離子通道至少存在三種狀態：resting、activated和inactivated","(B) 局部麻醉劑過量通常先表現的是神經系統的症狀","(C) 在局部麻醉劑中加入epinephrine會導致施打部位血管擴張","(D) 中樞神經系統可受局部麻醉劑毒性影響"],"answer":2,"image":""},{"id":"md6-111-1-5","subject":"md6","topic":"麻醉-麻醉藥理","meta":"111年第1次第5題","year":111,"session":1,"number":5,"question":"使用下列何種藥物，可以預防性降低手術後噁心嘔吐的發生率？","options":["(A) dexamethasone","(B) edrophonium","(C) fentanyl","(D) atracurium"],"answer":0,"image":""},{"id":"md6-111-1-6","subject":"md6","topic":"麻醉-呼吸道與監視","meta":"111年第1次第6題","year":111,"session":1,"number":6,"question":"利用經食道心臟超音波測量主動脈瓣狹窄病人，其通過主動脈瓣的最高流速為每秒3.5公尺，則該病人主動脈瓣狹窄的壓力差較接近下列何者？","options":["(A) 20 mmHg","(B) 30 mmHg","(C) 40 mmHg","(D) 50 mmHg"],"answer":3,"image":""},{"id":"md6-111-1-7","subject":"md6","topic":"麻醉-呼吸道與監視","meta":"111年第1次第7題","year":111,"session":1,"number":7,"question":"有關手術麻醉後送到麻醉恢復室（PACU：postanesthetic care unit）觀察麻醉恢復之敘述，下列何者錯誤？","options":["(A) 噁心及嘔吐為常見的問題","(B) 幾乎都是高血壓狀況，不會有低血壓情形","(C) 標準監測須包含呼吸、循環、體溫及清醒度","(D) 須注意部分抗生素可能延長肌肉鬆弛劑作用的時間"],"answer":1,"image":""},{"id":"md6-111-1-8","subject":"md6","topic":"麻醉-特殊麻醉與疼痛","meta":"111年第1次第8題","year":111,"session":1,"number":8,"question":"下列何者不是epidural analgesia硬膜外止痛運用於手術後疼痛處置的可能優點？","options":["(A) 降低全身性opioid的使用","(B) 增加sympathetic outflow，提升病患自我防禦能力","(C) 降低手術後的腸胃道併發症gastrointestinal complication","(D) 降低手術後的肺部併發症pulmonary complication"],"answer":1,"image":""},{"id":"md6-111-1-9","subject":"md6","topic":"麻醉-呼吸道與監視","meta":"111年第1次第9題","year":111,"session":1,"number":9,"question":"使用呼吸道正壓治療（positive pressure therapy），壓力過高時會產生過度擴張肺泡的副作用，其可能影響的生理表現，下列何者錯誤？","options":["(A) 增加死腔（dead space），減少有效通氣（hypoventilation）","(B) 增加肺血管阻力及右心室後負荷（afterload）","(C) 減少血液回流及左心室前負荷（preload），因此降低心輸出量","(D) 壓力達10 cmH2O即可能明顯增加肺壓力性創傷（barotrauma）的危險"],"answer":3,"image":""},{"id":"md6-111-1-10","subject":"md6","topic":"眼科-視網膜葡萄膜","meta":"111年第1次第10題","year":111,"session":1,"number":10,"question":"有關高度近視合併黃斑部脈絡膜新生血管之敘述，下列何者錯誤？","options":["(A) 高度近視產生黃斑部脈絡膜新生血管的風險，不會因近視雷射手術減少","(B) 若影響到患者視力，玻璃體內注射抗血管內皮生長因子（anti-vascular endothelial growth factor）是目前臨床上最有效的治療","(C) 年輕患者的預後較老年患者好","(D) 文獻指出每天攝取10 mg的葉黃素將有助預防此併發症的發生"],"answer":3,"image":""},{"id":"md6-111-1-11","subject":"md6","topic":"眼科-視網膜葡萄膜","meta":"111年第1次第11題","year":111,"session":1,"number":11,"question":"下列疾病併發葡萄膜炎發作時，何者多以單眼發作為主？","options":["(A) 貝西氏症（Behçet disease）","(B) 類肉瘤症（Sarcoidosis）","(C) 原田氏症（Vogt-Koyanagi-Harada syndrome）","(D) 僵直性脊椎炎（Ankylosing spondylitis）"],"answer":3,"image":""},{"id":"md6-111-1-12","subject":"md6","topic":"眼科-角膜結膜眼瞼眼窩","meta":"111年第1次第12題","year":111,"session":1,"number":12,"question":"有關結膜炎的敘述，下列何者錯誤？","options":["(A) 流行性角結膜炎主要因腺病毒感染所致","(B) 過敏性結膜炎可見結膜乳凸（papillae）","(C) 病毒性結膜炎較常出現結膜濾泡（follicles）","(D) 新生兒結膜炎主要發生在出生3個月之後"],"answer":3,"image":""},{"id":"md6-111-1-13","subject":"md6","topic":"眼科-屈光斜弱視","meta":"111年第1次第13題","year":111,"session":1,"number":13,"question":"下列何者非屈光不正所造成的視覺障礙？","options":["(A) 近視","(B) 遠視","(C) 斜視","(D) 老花"],"answer":2,"image":""},{"id":"md6-111-1-14","subject":"md6","topic":"眼科-水晶體青光眼","meta":"111年第1次第14題","year":111,"session":1,"number":14,"question":"八個月大的嬰兒因溢淚、畏光、眼瞼痙攣就診，在執行眼科檢查時較不會有下列何種發現？","options":["(A) 眼壓過高","(B) 角膜水腫","(C) 虹膜變色","(D) 眼球變大"],"answer":2,"image":""},{"id":"md6-111-1-15","subject":"md6","topic":"眼科-水晶體青光眼","meta":"111年第1次第15題","year":111,"session":1,"number":15,"question":"下列何種水晶體異常導致隅角閉鎖性青光眼？","options":["(A) phacolytic glaucoma","(B) phacogenic glaucoma","(C) phacomorphic glaucoma","(D) phacoanaphylactic glaucoma"],"answer":2,"image":""},{"id":"md6-111-1-16","subject":"md6","topic":"眼科-屈光斜弱視","meta":"111年第1次第16題","year":111,"session":1,"number":16,"question":"有關弱視的治療，下列敘述何者錯誤？","options":["(A) 屈調異常性的（兩眼遠視、近視、散光）弱視可以用戴眼鏡矯正來治療","(B) 不等視性的弱視可以用戴眼鏡加上遮蔽（occlusion/patch）好眼來治療","(C) 斜視性的弱視可以單純用斜視手術治療","(D) 單眼白內障造成的遮蔽性弱視，治療包括手術、光學矯正及遮蔽（occlusion/patch）治療"],"answer":2,"image":""},{"id":"md6-111-1-17","subject":"md6","topic":"眼科-角膜結膜眼瞼眼窩","meta":"111年第1次第17題","year":111,"session":1,"number":17,"question":"有關眼窩腫瘤（orbital tumor）的敘述，下列何者錯誤？","options":["(A) 微血管瘤（capillary hemangioma）是兒童最常見的良性眼窩腫瘤","(B) 兒童最常見的原發性惡性眼窩腫瘤是橫紋肌肉瘤（rhabdomyosarcoma）","(C) 成人最常見的良性眼窩腫瘤是海綿狀血管瘤（cavernous hemangioma）","(D) 眼窩裡的海綿狀血管瘤大部分會隨著年紀的增加而逐漸自然變小"],"answer":3,"image":""},{"id":"md6-111-1-18","subject":"md6","topic":"眼科-角膜結膜眼瞼眼窩","meta":"111年第1次第18題","year":111,"session":1,"number":18,"question":"一位50歲女性，抱怨最近會不自主地眨眼，眼睛有乾澀感，視力並無明顯減退；病人焦慮，睡眠不好。下列敘述何者錯誤？","options":["(A) 最可能診斷為良性的眼瞼痙攣（benign essential blepharospasm）","(B) 局部眼瞼及眼眶施打肉毒桿菌可緩解症狀（botulinum toxin injection）","(C) 常見誘發原因為壓力（stress）及亮光（bright light）","(D) 施打肉毒桿菌治療眼瞼痙攣，病人的眼瞼內翻（entropion）和下眼瞼下垂（lower eyelid sagging）也會獲得改善"],"answer":3,"image":""},{"id":"md6-111-1-19","subject":"md6","topic":"耳科學","meta":"111年第1次第19題","year":111,"session":1,"number":19,"question":"病人左耳耳鏡檢查所見如下圖，最可能之診斷為：","options":["(A) 先天性膽脂瘤（congenital cholesteatoma）","(B) 原發性後天性膽脂瘤（primary acquired cholesteatoma）","(C) 繼發性後天性膽脂瘤（secondary acquired cholesteatoma）","(D) 耳道膽脂瘤（ear canal cholesteatoma）"],"answer":3,"image":"md6-111-1-19.jpeg"},{"id":"md6-111-1-20","subject":"md6","topic":"耳科學","meta":"111年第1次第20題","year":111,"session":1,"number":20,"question":"慢性中耳炎病人接受鼓室成型術時，發現砧骨長突（long process of incus）侵蝕損壞。將剩下的砧骨體（body of incus）雕刻後，置放於重建之耳膜及完整之鐙骨頭（head of stapes）間，此種鼓室成型術屬於第幾型？","options":["(A) I","(B) II","(C) III","(D) IV"],"answer":2,"image":""},{"id":"md6-111-1-21","subject":"md6","topic":"耳科學","meta":"111年第1次第21題","year":111,"session":1,"number":21,"question":"噪音引起的永久性聽力損失，以下列何頻率最明顯？","options":["(A) 0.25～0.5 kHz","(B) 1～2 kHz","(C) 3～6 kHz","(D) 大於8 kHz"],"answer":2,"image":""},{"id":"md6-111-1-22","subject":"md6","topic":"鼻科學","meta":"111年第1次第22題","year":111,"session":1,"number":22,"question":"有關鼻功能評估方法，下列敘述何者錯誤？","options":["(A) acoustic rhinometry可評估鼻腔空間大小","(B) rhinomanometry可評估鼻腔阻力","(C) nasal peak flowmetry可評估鼻腔氣流量","(D) nasometry可評估鼻腔之立體構造"],"answer":3,"image":""},{"id":"md6-111-1-23","subject":"md6","topic":"耳科學","meta":"111年第1次第23題","year":111,"session":1,"number":23,"question":"下列那一種細菌不是急性中耳炎和急性鼻竇炎常見的致病菌種？","options":["(A) Streptococcus pneumoniae","(B) Haemophilus influenzae","(C) Moraxella catarrhalis","(D) Staphylococcus aureus"],"answer":[0,1,2,3],"image":"","answer_note":"送分:第23題，一律給分 (原公告答案 D)"},{"id":"md6-111-1-24","subject":"md6","topic":"喉科學與頭頸腫瘤","meta":"111年第1次第24題","year":111,"session":1,"number":24,"question":"66歲女性糖尿病病人，近幾個月來使用吸入式類固醇（inhaled corticosteroid）控制氣喘，因喉嚨疼痛、吞嚥不適而前來就診，經內視鏡檢查咽喉部如下圖，最可能之診斷為何？","options":["(A) 白斑（leukoplakia）","(B) 乳突瘤病（papillomatosis）","(C) 白喉（diphtheria）","(D) 念珠菌感染（candidiasis）"],"answer":3,"image":"md6-111-1-24.jpeg"},{"id":"md6-111-1-25","subject":"md6","topic":"喉科學與頭頸腫瘤","meta":"111年第1次第25題","year":111,"session":1,"number":25,"question":"嗓音障礙病人的喉內視鏡影像之臨床診斷，下列何者正確？","options":["(A) 圖一：聲帶白斑（leukoplakia）","(B) 圖二：聲帶息肉（vocal polyp）","(C) 圖三：聲帶結節（vocal nodule）","(D) 圖四：聲帶水腫（Reinke edema）"],"answer":1,"image":"md6-111-1-25.jpeg"},{"id":"md6-111-1-26","subject":"md6","topic":"喉科學與頭頸腫瘤","meta":"111年第1次第26題","year":111,"session":1,"number":26,"question":"有關第二期鼻咽癌的治療，下列敘述何者最適當？","options":["(A) 單獨放射治療（radiotherapy）","(B) 同步放化療（concurrent chemoradiotherapy）","(C) 需先施行前導性化療，之後再加上同步放化療（concurrent chemoradiotherapy）","(D) 需先施行同步放化療，再追加輔助性化療（adjuvant chemotherapy）"],"answer":1,"image":""},{"id":"md6-111-1-27","subject":"md6","topic":"喉科學與頭頸腫瘤","meta":"111年第1次第27題","year":111,"session":1,"number":27,"question":"下列何種頭頸部鱗狀上皮細胞癌最不容易轉移至咽後淋巴結（retropharyngeal lymph node）？","options":["(A) 鼻咽癌","(B) 舌癌","(C) 扁桃腺癌","(D) 咽後壁（posterior pharyngeal wall）癌"],"answer":1,"image":""},{"id":"md6-111-1-28","subject":"md6","topic":"產科-一般產科","meta":"111年第1次第28題","year":111,"session":1,"number":28,"question":"25歲女性，G1P0，已12週無月經來潮卻於今日出現陰道大量出血而來急診就醫，尿液檢查發現懷孕試驗呈陽性，抽血檢驗發現血清β-人類絨毛膜刺激激素（β-subunit human chorionic gonadotropin, β-hCG）值為14,500 mIU/mL，內診及超音波發現已擴張的子宮頸口上可看到少數妊娠組織、大部分妊娠組織還留在子宮內，下列何種診斷及處理方式最為適當？","options":["(A) 完全性流產（complete abortion），可於48小時後再追蹤血清β-hCG值","(B) 先兆性流產（threatened abortion），建議多休息","(C) 不完全性流產（incomplete abortion），可行子宮內膜搔刮手術（dilatation and curettage, D&C）","(D) 輸卵管子宮外孕（tubal pregnancy），可行腹腔鏡手術切除輸卵管子宮外孕"],"answer":2,"image":""},{"id":"md6-111-1-29","subject":"md6","topic":"婦科-手術學與診斷技術","meta":"111年第1次第29題","year":111,"session":1,"number":29,"question":"下列何者不是子宮外孕使用methotrexate治療的禁忌症（contraindications）？","options":["(A) 糖尿病（diabetes）","(B) 哺乳（breastfeeding）","(C) 血小板低下症（thrombocytopenia）","(D) 腹內出血（intra-abdominal hemorrhage）"],"answer":0,"image":""},{"id":"md6-111-1-30","subject":"md6","topic":"婦科-手術學與診斷技術","meta":"111年第1次第30題","year":111,"session":1,"number":30,"question":"32歲女性，G4P0，因少量陰道出血、左下腹微痛、自行驗孕呈陽性反應而來門診就醫，最後一次月經開始日為5週前，這位女性在本次懷孕之前已有兩次早期懷孕合併流產病史、最近的一次懷孕為子宮外孕並接受藥物methotrexate注射治療，她從去年即開始準備懷孕且對這次的懷孕相當重視，非常擔心又會重複子宮外孕；在門診時，其血壓為120/82 mmHg、心跳每分鐘85下，腹部理學檢查正常、無異常疼痛，骨盆腔內診檢查亦無疼痛或腫塊發現，陰道超音波檢查結果：子宮腔內很乾淨、無妊娠囊、子宮內膜厚度2公分、雙側卵巢正常、亦無子宮附屬器腫瘤或積液發現，第一次抽血檢驗結果：血清β-人類絨毛膜刺激激素（β-subunit human chorionic gonadotropin, β-hCG）值為647 mIU/mL、血型Rh陽性，48小時後重複抽血檢驗結果：β-hCG值為873 mIU/mL。綜合這位女性病患的狀況，最適合她的下一步處置應為下列何者？","options":["(A) 48小時後再次重複抽血檢驗β-hCG值","(B) 抽血檢驗progesterone值","(C) 施行腹腔鏡檢查","(D) 抽血檢測血清aspartate aminotransferase、creatinine以及hemoglobin值"],"answer":0,"image":""},{"id":"md6-111-1-31","subject":"md6","topic":"產科-高危險妊娠","meta":"111年第1次第31題","year":111,"session":1,"number":31,"question":"一位38歲孕婦妊娠35週產檢時發現有妊娠高血壓，做胎兒生理評估（fetal biophysical profile）檢查為10分，臨床上應如何處置？","options":["(A) 繼續觀察，每週做一次胎兒生理評估（fetal biophysical profile）檢查","(B) 繼續觀察，每天做一次胎兒生理評估（fetal biophysical profile）檢查","(C) 準備催生引產（induction），避免早產及可能發生胎兒窘迫（fetal distress）","(D) 安排當日剖腹生產，避免胎兒窘迫（fetal distress）"],"answer":0,"image":""},{"id":"md6-111-1-32","subject":"md6","topic":"產科-一般產科","meta":"111年第1次第32題","year":111,"session":1,"number":32,"question":"下列何者不是剖腹產的適應症？","options":["(A) 胎兒窘迫","(B) 產程遲滯","(C) 陰道乙型鏈球菌篩檢呈陽性","(D) 前置胎盤"],"answer":2,"image":""},{"id":"md6-111-1-33","subject":"md6","topic":"產科-一般產科","meta":"111年第1次第33題","year":111,"session":1,"number":33,"question":"根據2017年American College of Obstetricians and Gynecologists（ACOG），產後大出血的定義為：","options":["(A) 產後出血超過500 mL","(B) 產後出血超過1000 mL","(C) 血比容（hematocrit）掉3%","(D) 心跳增加20 bpm以上"],"answer":1,"image":""},{"id":"md6-111-1-34","subject":"md6","topic":"產科-一般產科","meta":"111年第1次第34題","year":111,"session":1,"number":34,"question":"有關誘發產後大出血的子宮相關因素（uterine factor），下列敘述何者錯誤？","options":["(A) 多胞胎或羊水過多造成子宮過度擴張（uterine overdistention）","(B) 產程遲滯","(C) 雙角子宮","(D) 鹵化劑（halogenated agents）等吸入性麻醉藥物誘發"],"answer":2,"image":""},{"id":"md6-111-1-35","subject":"md6","topic":"產科-高危險妊娠","meta":"111年第1次第35題","year":111,"session":1,"number":35,"question":"關於絨毛膜取樣，下列敘述何者錯誤？","options":["(A) 夫妻如有家族遺傳性疾病者，選擇絨毛膜取樣，可較早得到診斷","(B) 可經由陰道或腹部執行","(C) 術後總流產率較羊膜穿刺高，但去除自然流產因素後，兩者術後的流產率相當","(D) 懷孕10週之前施行絨毛膜穿刺，有較高之準確率及較低之併發症"],"answer":3,"image":""},{"id":"md6-111-1-36","subject":"md6","topic":"產科-一般產科","meta":"111年第1次第36題","year":111,"session":1,"number":36,"question":"有關單胞胎臀位陰道產之敘述，下列何者錯誤？","options":["(A) 足月時，臀位之機率為3～4%","(B) 最適合臀位陰道產的胎兒姿勢為frank breech","(C) 羊水量異常為臀位危險因子之一","(D) 前胎剖腹產為臀位陰道產之絕對禁忌症"],"answer":3,"image":""},{"id":"md6-111-1-37","subject":"md6","topic":"產科-高危險妊娠","meta":"111年第1次第37題","year":111,"session":1,"number":37,"question":"依據The Hyperglycemia and Adverse Pregnancy Outcome Study（HAPO study），母體血糖值越高，與母體及新生兒的預後不佳有關，依上述研究下列何敘述錯誤？","options":["(A) 出生體重超過90個百分位","(B) 剖腹生產（primary cesarean delivery）","(C) 新生兒高血糖（neonatal hyperglycemia）","(D) 臍帶血C-peptide值超過90個百分位"],"answer":2,"image":""},{"id":"md6-111-1-38","subject":"md6","topic":"產科-高危險妊娠","meta":"111年第1次第38題","year":111,"session":1,"number":38,"question":"一位診斷為嚴重型子癇前症的孕婦採用硫酸鎂（magnesium sulfate）溶液預防痙攣，其肝功能異常（較正常值上升3倍），腎功能正常且尿量每小時多達50毫升，下列處置何者最適當？","options":["(A) 初始劑量（loading dose）4克應減半","(B) 維持劑量（maintenance dose）每小時2克應減半","(C) 使用至生產後24小時後停止","(D) 鎂離子在治療濃度下具心毒性"],"answer":2,"image":""},{"id":"md6-111-1-39","subject":"md6","topic":"產科-高危險妊娠","meta":"111年第1次第39題","year":111,"session":1,"number":39,"question":"導致雙胞胎輸血症（Twin-Twin Transfusion Syndrome, TTTS）的最主要胎盤血管異常為：","options":["(A) 帆狀臍帶插入（velamentous cord insertion）","(B) 臍動脈－臍動脈吻合（arterioarterial anastomosis）","(C) 臍靜脈－臍靜脈吻合（venovenous anastomosis）","(D) 臍動脈－臍靜脈吻合（arteriovenous anastomosis）"],"answer":3,"image":""},{"id":"md6-111-1-40","subject":"md6","topic":"麻醉-呼吸道與監視","meta":"111年第1次第40題","year":111,"session":1,"number":40,"question":"當執行腹腔鏡手術時，腹內氣壓大於20毫米汞柱的手術併發症中，下列何種情況最不容易發生？","options":["(A) hypotension","(B) hypercarbia","(C) carbon dioxide embolus","(D) hyperglycemia"],"answer":3,"image":""},{"id":"md6-111-1-41","subject":"md6","topic":"婦科-良性腫瘤與內膜異位","meta":"111年第1次第41題","year":111,"session":1,"number":41,"question":"40歲女性，月經經血量多導致貧血，經檢查發現患有子宮肌瘤，關於此病患的藥物治療選擇，下列何種藥物使用，比較不符合常規的治療？","options":["(A) Gonadotropin-Releasing Hormone Agonist","(B) Progesterone-Releasing Intrauterine Device","(C) Tranexamic Acid","(D) Danazole"],"answer":3,"image":""},{"id":"md6-111-1-42","subject":"md6","topic":"婦科-腫瘤","meta":"111年第1次第42題","year":111,"session":1,"number":42,"question":"有關兒童和青少女出現的卵巢腫瘤，下列敘述何者最不適當？","options":["(A) 惡性的可能性很低","(B) 生殖細胞腫瘤約占一半以上","(C) 超音波檢查是診斷卵巢腫瘤的有效方法","(D) 上皮細胞腫瘤不常見"],"answer":0,"image":""},{"id":"md6-111-1-43","subject":"md6","topic":"婦科-良性腫瘤與內膜異位","meta":"111年第1次第43題","year":111,"session":1,"number":43,"question":"根據FIGO子宮肌瘤分類系統，何種類型最適合用子宮鏡切除？","options":["(A) Type 0","(B) Type 1","(C) Type 2","(D) Type 3"],"answer":0,"image":""},{"id":"md6-111-1-44","subject":"md6","topic":"婦科-生殖道感染與先天異常","meta":"111年第1次第44題","year":111,"session":1,"number":44,"question":"有關女性生殖道器官先天性異常（Müllerian anomalies），下列敘述何者最不適當？","options":["(A) 約占原發性閉經（primary amenorrhea）20%的病例","(B) 大多數患者第二性徵發育遲緩","(C) 包含處女膜閉鎖（imperforate hymen）、陰道隔膜（transverse vaginal septum）、子宮頸或陰道無發育（absence of the cervix or vagina）","(D) 可能造成青少女無月經但週期性下腹痛"],"answer":1,"image":""},{"id":"md6-111-1-45","subject":"md6","topic":"婦科-良性腫瘤與內膜異位","meta":"111年第1次第45題","year":111,"session":1,"number":45,"question":"一個30歲無性經驗女性來到門診，她主訴經痛已持續5年，長期使用止痛藥緩解症狀，此外她並無經血過多或頻尿之現象。她的經期剛結束，經安排婦科超音波檢查發現左側卵巢有一直徑約8x7公分的卵巢囊腫（如圖），下列何者為最可能的診斷？","options":["(A) 卵巢濾泡囊腫（ovarian follicular cyst）","(B) 卵巢子宮內膜異位瘤（ovarian endometrioma）","(C) 卵巢纖維瘤（ovarian fibroma）","(D) 卵巢癌（ovarian cancer）"],"answer":1,"image":"md6-111-1-45.jpeg"},{"id":"md6-111-1-46","subject":"md6","topic":"婦科-生殖道感染與先天異常","meta":"111年第1次第46題","year":111,"session":1,"number":46,"question":"有穆勒氏管（Müllerian ducts）相關異常的女性，應進行下列那個系統的檢查？","options":["(A) 上消化道","(B) 下消化道","(C) 腎臟泌尿道","(D) 骨盆腔底部支持系統"],"answer":2,"image":""},{"id":"md6-111-1-47","subject":"md6","topic":"婦科-生殖道感染與先天異常","meta":"111年第1次第47題","year":111,"session":1,"number":47,"question":"關於細菌性陰道炎（bacterial vaginosis）的敘述，下列何者最適當？","options":["(A) 需氧菌（aerobes）過度增生的結果","(B) 陰道乳酸菌（lactobacilli）過度生長","(C) 是陰道炎中最常見的一種","(D) 跟性行為沒有關係"],"answer":2,"image":""},{"id":"md6-111-1-48","subject":"md6","topic":"婦科-手術學與診斷技術","meta":"111年第1次第48題","year":111,"session":1,"number":48,"question":"對於沒有服用荷爾蒙的停經後婦女，下列何者為子宮異常出血最常見的原因？","options":["(A) 子宮內膜癌","(B) 子宮肌瘤","(C) 子宮內膜增生","(D) 萎縮性子宮內膜炎"],"answer":3,"image":""},{"id":"md6-111-1-49","subject":"md6","topic":"婦科-腫瘤","meta":"111年第1次第49題","year":111,"session":1,"number":49,"question":"30歲婦女，已結婚但未生小孩，抹片異常，內診僅發現子宮頸1 cm腫瘤，切片檢查結果為侵襲性鱗狀細胞癌（invasive squamous cell carcinoma），基質侵襲深度為5 mm，骨盆腔電腦斷層及膀胱鏡檢查正常。依照FIGO staging（2018）該病人的子宮頸癌分期為：","options":["(A) stage IB1","(B) stage IIA1","(C) stage IIB","(D) stage IIIB"],"answer":0,"image":""},{"id":"md6-111-1-50","subject":"md6","topic":"婦科-腫瘤","meta":"111年第1次第50題","year":111,"session":1,"number":50,"question":"關於卵巢癌治療，何時會使用neoadjuvant化學治療？","options":["(A) 預期腫瘤無法切除乾淨或手術併發症過高，先進行化學治療","(B) 腫瘤已經切除乾淨，進行後續化學治療","(C) 手術後腫瘤無法切除乾淨，進行化學治療","(D) 腫瘤復發後直接進行化學治療"],"answer":0,"image":""},{"id":"md6-111-1-51","subject":"md6","topic":"婦科-腫瘤","meta":"111年第1次第51題","year":111,"session":1,"number":51,"question":"關於懷孕期間罹患子宮頸癌之敘述，下列何者正確？","options":["(A) 懷孕時併有侵襲性子宮頸癌的發生率約10萬分之5","(B) 第一妊娠期進行子宮頸錐狀切除術（conizaiton）的流產率低於10%","(C) 對於子宮頸錐狀切除術發現侵犯深度（depth of invasion）為3～5mm，但併有淋巴血管浸潤（lymph-vascular space invasion）者，不論胎兒週數或肺部成熟狀況，必須終止懷孕立即接受子宮根除手術及骨盆腔淋巴結切除手術（radical hysterectomy and pelvic lymphadenectomy）","(D) 臨床分期是懷孕期間罹患子宮頸癌最重要的預後因子"],"answer":3,"image":""},{"id":"md6-111-1-52","subject":"md6","topic":"婦科-腫瘤","meta":"111年第1次第52題","year":111,"session":1,"number":52,"question":"有關type I及type II之子宮內膜癌，下列敘述何者錯誤？","options":["(A) type I子宮內膜癌的細胞型態主要為endometrioid adenocarcinoma，type II子宮內膜癌的細胞型態則包含serous carcinoma, clear cell carcinoma","(B) 大多數子宮內膜癌病患之腫瘤細胞型態為type I","(C) 血液中高雌激素濃度（hyperestrogenism）與type I子宮內膜癌較相關，為其重要之危險因子","(D) type I子宮內膜癌之預後較type II差，且腫瘤較易侵犯到子宮以外的器官"],"answer":3,"image":""},{"id":"md6-111-1-53","subject":"md6","topic":"婦科-腫瘤","meta":"111年第1次第53題","year":111,"session":1,"number":53,"question":"Choriocarcinoma轉移部位最常見在何處？","options":["(A) 肺","(B) 陰道","(C) 腦部","(D) 骨盆"],"answer":0,"image":""},{"id":"md6-111-1-54","subject":"md6","topic":"婦科-生殖內分泌","meta":"111年第1次第54題","year":111,"session":1,"number":54,"question":"有關卵巢功能（ovarian reserve）的敘述，下列何者錯誤？","options":["(A) 月經任何一天抽血檢驗Anti-Müllerian Hormone（AMH），可以了解卵巢功能","(B) 血清Anti-Müllerian Hormone（AMH）濃度2 ng/mL代表卵巢功能不佳","(C) 月經第三天超音波測量竇卵泡數目（Antral Follicle Count, AFC），可以了解卵巢功能","(D) 月經第三天超音波測量竇卵泡數目（Antral Follicle Count, AFC）3顆代表卵巢功能不佳"],"answer":1,"image":""},{"id":"md6-111-1-55","subject":"md6","topic":"婦科-生殖內分泌","meta":"111年第1次第55題","year":111,"session":1,"number":55,"question":"雄性素（androgen）及雌激素（estrogen）是影響生育功能的重要激素，下列關於性激素的敘述何者錯誤？","options":["(A) 雄性素是雌激素的前驅物","(B) 女性體內的雄性素並非全部由卵巢所分泌的","(C) 停經婦女體內雄性素仍維持不減","(D) 女性外生殖器發育是受到雌激素刺激而形成的"],"answer":[2,3],"image":"","answer_note":"更正:第55題，答Ｃ或Ｄ或CD者均給分。。"},{"id":"md6-111-1-56","subject":"md6","topic":"婦科-生殖內分泌","meta":"111年第1次第56題","year":111,"session":1,"number":56,"question":"下列何種方式，不適合用來判斷病患是否有排卵？","options":["(A) 請患者每天測量基礎體溫並記錄","(B) 在預期月經來之前一週測量血中黃體素濃度","(C) 在月經週期第五天進行陰道超音波檢查，測量濾泡的大小與數量","(D) 在月經結束後每天檢測尿液中的黃體激素（luteinizing hormone, LH）"],"answer":2,"image":""},{"id":"md6-111-1-57","subject":"md6","topic":"婦科-尿失禁與骨盆腔脫垂","meta":"111年第1次第57題","year":111,"session":1,"number":57,"question":"目前臨床上應力性尿失禁的無張力吊帶手術，如：經閉孔吊帶手術（transobturator tape, TOT）或無張力陰道吊帶手術（tension-free vaginal tape, TVT）等，是將吊帶（polypropylene tape）置放在尿道下方何位置？","options":["(A) 尿道膀胱頸處","(B) 尿道近端","(C) 尿道中段處","(D) 尿道遠端處"],"answer":2,"image":""},{"id":"md6-111-1-58","subject":"md6","topic":"復健-神經復健","meta":"111年第1次第58題","year":111,"session":1,"number":58,"question":"關於中風復健常見之傳統治療技術，何者主要強調抑制不正常的姿勢與動作，並且誘發獨立的肌肉控制（isolated muscle control）？","options":["(A) Brunnstrom動作治療介入（Brunnstrom's movement therapy approach）","(B) 神經發展技術（neurodevelopmental technique）","(C) 本體神經誘發技術（sensorimotor approach）","(D) 工作導向動作訓練（task-oriented motor training）"],"answer":1,"image":""},{"id":"md6-111-1-59","subject":"md6","topic":"復健-骨骼肌肉損傷與疾患","meta":"111年第1次第59題","year":111,"session":1,"number":59,"question":"一位病人因跌倒，發現肱骨螺旋溝（spinal groove）處有骨折，且有手腕下垂（dropped wrist）無法背屈，這可能是以下那一條神經受傷？","options":["(A) 尺神經","(B) 橈神經","(C) 正中神經","(D) 肌皮神經"],"answer":1,"image":""},{"id":"md6-111-1-60","subject":"md6","topic":"復健-兒童與一般復健","meta":"111年第1次第60題","year":111,"session":1,"number":60,"question":"人類神經肌肉系統的構造中，運動單元（motor unit）大小差異甚大，下列何者有最大的運動單元？","options":["(A) 喉頭（laryngeal）肌","(B) 股四頭（quadriceps）肌","(C) 咀嚼（masseter）肌","(D) 眼內直（medial rectus）肌"],"answer":1,"image":""},{"id":"md6-111-1-61","subject":"md6","topic":"復健-神經復健","meta":"111年第1次第61題","year":111,"session":1,"number":61,"question":"一位病人在吃飯時，突然發生頭痛，隨即有嘔吐現象，送到醫院時發現其右側上下肢無力，左側顏面神經麻痺，經臨床診斷為腦中風，其最可能的病變位置在下列何處？","options":["(A) 基底核（basal nuclei）","(B) 視丘（thalamus）","(C) 橋腦（pons）","(D) 小腦（cerebellum）"],"answer":2,"image":""},{"id":"md6-111-1-62","subject":"md6","topic":"復健-骨骼肌肉損傷與疾患","meta":"111年第1次第62題","year":111,"session":1,"number":62,"question":"下列何種運動方式最適合骨折初期的病人？","options":["(A) 等長運動（isometric exercise）","(B) 等張運動（isotonic exercise）","(C) 延長運動（eccentric exercise）","(D) 等速運動（isokinetic exercise）"],"answer":0,"image":""},{"id":"md6-111-1-63","subject":"md6","topic":"復健-兒童與一般復健","meta":"111年第1次第63題","year":111,"session":1,"number":63,"question":"小明是3個月的男嬰，因頭部不正而求診。醫師發現小明頸部轉（rotation）向右側，後腦傾（tilt）向左側，醫師診斷是先天性肌肉斜頸，下列敘述何者正確？","options":["(A) 小明最可能的原因是右側胸鎖乳突肌（sternocleidomastoid muscle）短縮所致","(B) 小明髖關節發育不良的可能性較高","(C) 此症通常需手術治療","(D) 頸圈為治療之首選"],"answer":1,"image":""},{"id":"md6-111-1-64","subject":"md6","topic":"復健-截肢與義肢輔具","meta":"111年第1次第64題","year":111,"session":1,"number":64,"question":"關於踝足輔具（ankle-foot orthoses, AFO），以下敘述何者不適當？","options":["(A) 常被用來控制足踝的活動（control ankle motion）","(B) 是最常被使用的下肢輔具（lower limbs orthoses）","(C) 在行走時，不會影響距骨下關節（subtalar joint）的活動","(D) 可穩定行走時的膝關節"],"answer":2,"image":""},{"id":"md6-111-1-65","subject":"md6","topic":"復健-心肺復健與運動處方","meta":"111年第1次第65題","year":111,"session":1,"number":65,"question":"有關自覺用力係數（Rating of Perceived Exertion, Borg Scale，簡稱RPE）的描述，下列何者錯誤？","options":["(A) 雖然是病人自覺分數，但對運動強度推估仍有一定的可靠性","(B) 在運動訓練時，由參與者指出自覺運動困難之分數","(C) 分數愈低，代表運動強度愈困難","(D) 是一種測量運動強度的指標"],"answer":2,"image":""},{"id":"md6-111-1-66","subject":"md6","topic":"復健-心肺復健與運動處方","meta":"111年第1次第66題","year":111,"session":1,"number":66,"question":"下列何者是心臟復健之訓練效果？","options":["(A) 增加最大攝氧量","(B) 降低血紅素","(C) 減少動脈含氧量差（A-V O2 difference）","(D) 增加休息心跳率"],"answer":0,"image":""},{"id":"md6-111-1-67","subject":"md6","topic":"復健-兒童與一般復健","meta":"111年第1次第67題","year":111,"session":1,"number":67,"question":"關於年齡12個月大的兒童發展里程碑（developmental milestones），下列那一項是較不可能達到的？","options":["(A) 雙手扶著傢俱走幾步","(B) 拍手","(C) 以揮手表示再見","(D) 可以重疊2塊積木"],"answer":3,"image":""},{"id":"md6-111-1-68","subject":"md6","topic":"復健-神經復健","meta":"111年第1次第68題","year":111,"session":1,"number":68,"question":"關於腦性麻痺（cerebral palsy）患者下肢手術的進行時間點，目前共識（consensus）的一般建議是7歲以後才執行手術介入，但是下列那個部位的手術除外？","options":["(A) 髖關節（hip joint）","(B) 膝關節（knee joint）","(C) 踝關節（ankle joint）","(D) 脊椎（spine）"],"answer":0,"image":""},{"id":"md6-111-1-69","subject":"md6","topic":"喉科學與頭頸腫瘤","meta":"111年第1次第69題","year":111,"session":1,"number":69,"question":"吞嚥時為防止食物進入氣道，發生嗆咳或吸入，喉部（larynx）會進行一些保護性的動作，以下何者錯誤？","options":["(A) 暫時停止呼吸","(B) 聲帶（vocal cord）閉合","(C) 會厭軟骨（epiglottis）後傾下壓","(D) 舌骨（hyoid bone）往上往後拉"],"answer":3,"image":""},{"id":"md6-111-1-70","subject":"md6","topic":"復健-兒童與一般復健","meta":"111年第1次第70題","year":111,"session":1,"number":70,"question":"手動輪椅具有後輪外傾角度（camber angle）時（如附圖左），下列何者不是其優點？","options":["(A) 可避免輪胎不均勻磨損","(B) 輪椅通過窄門時，可保護操作者之雙手免於擦傷","(C) 操作輪椅時，可以減少患者雙肩之外展角度（shoulder abduction）","(D) 可以增加輪椅的側向穩定度（lateral stability）"],"answer":0,"image":"md6-111-1-70.jpeg"},{"id":"md6-111-1-71","subject":"md6","topic":"復健-神經復健","meta":"111年第1次第71題","year":111,"session":1,"number":71,"question":"下列有關失用症（apraxia）的敘述，何者錯誤？","options":["(A) 大多是指原先已會的功能變得異常或喪失","(B) 大多發生在左大腦半球的病變之病人","(C) 較為常見的症狀是動作順序失常","(D) 常因聽覺認知受損所造成"],"answer":3,"image":""},{"id":"md6-111-1-72","subject":"md6","topic":"喉科學與頭頸腫瘤","meta":"111年第1次第72題","year":111,"session":1,"number":72,"question":"41歲男性患者，主訴左頸部摸到腫塊，接受電腦斷層檢查，2張圖分別是注射顯影劑的不同切面影像，下列何者是最可能的診斷？","options":["(A) 囊狀水囊（cystic hygroma）","(B) 血管瘤（hemangioma）","(C) 壞死淋巴結（necrotic lymph node）","(D) 腮裂囊腫（branchial cleft cyst）"],"answer":3,"image":"md6-111-1-72.jpeg"},{"id":"md6-111-1-73","subject":"md6","topic":"復健-神經復健","meta":"111年第1次第73題","year":111,"session":1,"number":73,"question":"一位50歲女性，突發性劇烈頭痛被送到急診，電腦斷層發現蜘蛛網膜下腔出血（SAH），下列敘述何者最正確？","options":["(A) 可安排電腦斷層血管影像檢查（CTA），以找出出血的病因","(B) 可進行腰椎穿刺，以確定出血的原因","(C) 惡性腫瘤出血是最常見的原因","(D) 病患不會有水腦等症狀"],"answer":0,"image":"md6-111-1-73.jpeg"},{"id":"md6-111-1-74","subject":"md6","topic":"復健-骨骼肌肉損傷與疾患","meta":"111年第1次第74題","year":111,"session":1,"number":74,"question":"43歲男性病人，6個月前中風合併右半側癱瘓，4個月前右側髖部開始腫脹，杜卜勒檢查無深層靜脈栓塞，最近的骨盆X光片如圖，最可能的診斷為何？","options":["(A) 惡性骨肉瘤（osteogenic sarcoma）","(B) 異位性骨化病（heterotopic ossification）","(C) 惡性軟骨肉瘤（chondrosarcoma）","(D) 結核性肉芽腫（tuberculous granuloma）"],"answer":1,"image":"md6-111-1-74.jpeg"},{"id":"md6-111-1-75","subject":"md6","topic":"復健-神經復健","meta":"111年第1次第75題","year":111,"session":1,"number":75,"question":"典型的Guillain-Barré症候群之診斷，下列何者是必要的條件？","options":["(A) 在幾天內惡化","(B) 自律神經功能異常","(C) 肌電圖或神經傳導檢查呈現典型表徵","(D) 無神經反射"],"answer":3,"image":""},{"id":"md6-111-1-76","subject":"md6","topic":"麻醉-呼吸道與監視","meta":"111年第1次第76題","year":111,"session":1,"number":76,"question":"下列何種狀況可能會導致氣道內管插管困難？","options":["(A) Mallampati分級：Class Ⅲ","(B) 下巴離舌骨超過三指幅寬","(C) 嘴巴打開超過三指幅寬","(D) 配戴活動式假牙"],"answer":0,"image":""},{"id":"md6-111-1-77","subject":"md6","topic":"產科-一般產科","meta":"111年第1次第77題","year":111,"session":1,"number":77,"question":"一位34歲女性，在生產結束後18小時開始大量出血，迅速被轉送至附近的醫學中心緊急處置。關於產後出血，下列何者最正確？","options":["(A) 此病人屬於次發性產後出血","(B) 血液中血紅素的數值若沒有下降，顯示出血量一定很少","(C) oxytocin為無張力性子宮（uterine atony）的第一線用藥","(D) 超音波檢查對於此病人並無幫助"],"answer":2,"image":""},{"id":"md6-111-1-78","subject":"md6","topic":"醫學倫理與法規","meta":"111年第1次第78題","year":111,"session":1,"number":78,"question":"李小姐是某大學的大一學生，聖誕節過後發現自己不小心懷孕了，到醫院希望醫師幫她進行人工流產。因為李小姐未滿20歲，醫師希望她能夠取得爸媽的同意書後才為她進行人工流產。李小姐偽造爸媽簽名的同意書給醫師，醫師發現李小姐有些緊張，詢問此爸媽的同意書是誰簽的，李小姐很誠實的告訴醫師同意書是她自己簽的。如果你是她的醫師，如何處理最適當？","options":["(A) 幫李小姐進行人工流產，因為她在大學念書，已經具有相當的理解及判斷能力","(B) 幫李小姐進行人工流產，否則她可能跑到小診所接受人工流產，危險性反而更高","(C) 先不幫她進行人工流產，請她去找別的醫師","(D) 先不幫她進行人工流產，請她取得爸媽同意後，再進行人工流產"],"answer":3,"image":""},{"id":"md6-111-1-79","subject":"md6","topic":"醫學倫理與法規","meta":"111年第1次第79題","year":111,"session":1,"number":79,"question":"對特定疾病有多種治療方法時，醫師應向病人詳細解釋，讓病人可以自由選擇，但因病人不易在複雜的醫學技術間做選擇，多半會要求醫師推薦，醫師在進行較積極的建議時，常依最大利益原則為考量，所謂最大利益原則是指：","options":["(A) 健保的最大利益","(B) 病人的最大利益","(C) 醫師的最大利益","(D) 醫院的最大利益"],"answer":1,"image":""},{"id":"md6-111-1-80","subject":"md6","topic":"醫學倫理與法規","meta":"111年第1次第80題","year":111,"session":1,"number":80,"question":"復健科醫師於臨床發現女病患疑似遭受家庭暴力情事，病患坦承其丈夫偶會暴力相向，但擔心事件曝光將影響家庭關係，請求醫師不要通報相關單位，在此種情況下，下列處置何者為宜？","options":["(A) 考慮到病人隱私，醫師不得通報","(B) 考慮到病人安全，醫師應立即通報","(C) 為兼顧病人隱私與安全，醫師可請別人通報","(D) 叫病人先生來，曉以大義"],"answer":1,"image":""},{"id":"md6-111-2-1","subject":"md6","topic":"麻醉-呼吸道與監視","meta":"111年第2次第1題","year":111,"session":2,"number":1,"question":"氣道的輔助工具包括鼻咽人工氣道（nasopharyngeal airway）與口咽人工氣道（oropharyngeal airway），下列敘述何者錯誤？","options":["(A) 清醒的病人優先使用口咽人工氣道","(B) 誘發嘔吐是口咽人工氣道的潛在性風險","(C) 顱骨底骨折是鼻咽人工氣道的禁忌","(D) 鼻出血是鼻咽人工氣道的潛在性併發症"],"answer":0,"image":""},{"id":"md6-111-2-2","subject":"md6","topic":"麻醉-呼吸道與監視","meta":"111年第2次第2題","year":111,"session":2,"number":2,"question":"關於心血管監測在麻醉或重症病人的臨床運用，下列敘述何者錯誤？","options":["(A) 在肺動脈導管（pulmonary artery catheter）監測mixed venous hemoglobin oxygen saturation（SvO2），目的是測量心輸出量與全身血氧供應量是否足夠。正常的SvO2數值約30%～50%","(B) 經食道超音波（transesophageal echocardiography）對心臟功能、瓣膜功能、心室內血量、導管位置都有良好的監測效果，也可以使用在非開心手術的病人監測","(C) 若要監測心臟前負荷（cardiac preload），動態測量（如pulse pressure variation）較靜態測量（如pulmonary capillary wedge pressure）更能預測血管內容積的反應性（intravascular volume responsiveness）","(D) 使用CVP（central venous pressure）和肺動脈導管監測最常見的後遺症是對數值的誤用與誤判"],"answer":0,"image":""},{"id":"md6-111-2-3","subject":"md6","topic":"麻醉-呼吸道與監視","meta":"111年第2次第3題","year":111,"session":2,"number":3,"question":"麻醉中關於腎臟功能的監測與處理，下列敘述何者正確？","options":["(A) 術中尿排出量（urine output）為術中最常用的監測，可以監測腎絲球過濾（glomerular filtration）與腎功能","(B) creatinine升高與GFR（glomerular filtration rate）降低成線性正比關係","(C) 麻醉中為確保腎功能，最有效的方式是監測及維持hemodynamics，確保心臟功能、血管內血量及足夠的組織灌流","(D) 腎功能受損的biomarker介白素（interleukin-18）與腎小管壓力反應並無相關"],"answer":2,"image":""},{"id":"md6-111-2-4","subject":"md6","topic":"麻醉-麻醉藥理","meta":"111年第2次第4題","year":111,"session":2,"number":4,"question":"臨床上使用鴉片類藥物為手術後止痛，下列何者具鴉片類藥物受體專一性拮抗作用，競爭中樞神經的受體，可以拮抗過量鴉片類藥物所造成的呼吸抑制？","options":["(A) naloxone","(B) flumazenil","(C) dexmedetomidine","(D) ketamine"],"answer":0,"image":""},{"id":"md6-111-2-5","subject":"md6","topic":"麻醉-麻醉藥理","meta":"111年第2次第5題","year":111,"session":2,"number":5,"question":"下列有關靜脈麻醉劑（intravenous anesthetics）的敘述，何者錯誤？","options":["(A) benzodiazepine可能導致呼吸暫停（apnea）","(B) propofol製劑有助於細菌的生長","(C) barbiturate抑制腦幹中的reticular activating system","(D) barbiturate經由與NMDA受體結合而起作用"],"answer":3,"image":""},{"id":"md6-111-2-6","subject":"md6","topic":"麻醉-呼吸道與監視","meta":"111年第2次第6題","year":111,"session":2,"number":6,"question":"麻醉誘導進行面罩通氣時發現通氣困難，下列那一項措施的改善效果最差？","options":["(A) 用力往下壓緊面罩","(B) 放置口咽呼吸道（oral airway）","(C) 放置鼻咽呼吸道（nasal airway）","(D) 壓額抬下巴（head tilt and chin lift）"],"answer":0,"image":""},{"id":"md6-111-2-7","subject":"md6","topic":"麻醉-呼吸道與監視","meta":"111年第2次第7題","year":111,"session":2,"number":7,"question":"下列何者不是經食道超音波能獲得的資訊？","options":["(A) 左心室舒張功能","(B) 心輸出量（cardiac output）","(C) 主動脈瓣膜狹窄程度","(D) 冠狀動脈狹窄程度"],"answer":3,"image":""},{"id":"md6-111-2-8","subject":"md6","topic":"麻醉-特殊麻醉與疼痛","meta":"111年第2次第8題","year":111,"session":2,"number":8,"question":"下列有關epidural injection for chronic pain的敘述，何者錯誤？","options":["(A) 適用於治療輕度神經根壓迫（nerve root compression）所造成的radicular pain","(B) 通常需要有影像的導引（image guidance），最常用的是X光透視導引（fluoroscopic guidance）","(C) 合併使用類固醇加局部麻醉藥較單獨使用局部麻醉藥注射效果好","(D) 頸椎epidural injection的風險太高，臨床上並未使用"],"answer":3,"image":""},{"id":"md6-111-2-9","subject":"md6","topic":"麻醉-呼吸道與監視","meta":"111年第2次第9題","year":111,"session":2,"number":9,"question":"敗血性休克常併發多重器官的問題，下列敘述何者錯誤？","options":["(A) 產生胰島素抗性（insulin resistance），常導致低血糖","(B) 因為血小板的活化與凝集，常導致血小板低下，是敗血症的早期病徵之一","(C) 常併發瀰漫性血管內凝血（disseminated intravascular coagulation）","(D) 因為胃黏膜的壓力性潰瘍，常導致上消化道出血"],"answer":0,"image":""},{"id":"md6-111-2-10","subject":"md6","topic":"眼科-視網膜葡萄膜","meta":"111年第2次第10題","year":111,"session":2,"number":10,"question":"病患有下列何種年齡相關黃斑部退化（age-related macular degeneration）時，最適合使用抗血管內皮生長因子製劑（anti-VEGF agents）治療？","options":["(A) 隱結（drusen）","(B) 視網膜色素細胞萎縮（RPE atrophy）","(C) 脈絡膜新生血管（choroidal neovascularization）","(D) 纖維性盤狀結疤（disciform scarring）"],"answer":2,"image":""},{"id":"md6-111-2-11","subject":"md6","topic":"眼科-視網膜葡萄膜","meta":"111年第2次第11題","year":111,"session":2,"number":11,"question":"下列何者不是造成牽引性視網膜剝離（tractional retinal detachment）之常見原因？","options":["(A) 增殖性糖尿病視網膜病變（proliferative diabetic retinopathy）","(B) 嚴重的早產兒視網膜病變（retinopathy of prematurity）","(C) 穿透性眼後部外傷（penetrating posterior segment trauma）","(D) 急性後玻璃體剝離（acute posterior vitreous detachment）"],"answer":3,"image":""},{"id":"md6-111-2-12","subject":"md6","topic":"眼科-角膜結膜眼瞼眼窩","meta":"111年第2次第12題","year":111,"session":2,"number":12,"question":"有關結膜炎的敘述，下列何者錯誤？","options":["(A) 披衣菌感染可造成黏液膿狀（mucopurulent）分泌物","(B) 淋病感染可造成嚴重膿狀（severe purulent）分泌物","(C) 黏液（mucoid）分泌物與急性過敏較有關","(D) 水性（watery）分泌物與病毒感染較有關"],"answer":2,"image":""},{"id":"md6-111-2-13","subject":"md6","topic":"眼科-屈光斜弱視","meta":"111年第2次第13題","year":111,"session":2,"number":13,"question":"下列對遠距視力表檢查結果的敘述，何者較為正確？","options":["(A) 裸視1.5：表示該眼是遠視眼","(B) 裸視1.5：表示該眼不太會是近視眼","(C) 裸視0.5：表示該眼是遠視眼","(D) 裸視0.5：表示該眼不會是遠視眼"],"answer":1,"image":""},{"id":"md6-111-2-14","subject":"md6","topic":"眼科-水晶體青光眼","meta":"111年第2次第14題","year":111,"session":2,"number":14,"question":"有關先天性白內障的敘述，下列何者錯誤？","options":["(A) 必須列為白瞳（leukocoria）鑑別診斷之一","(B) 雙眼輕微白內障可以等待一段時間再手術","(C) 雙側性白內障較單側性白內障容易產生弱視","(D) 手術後容易有續發性青光眼"],"answer":2,"image":""},{"id":"md6-111-2-15","subject":"md6","topic":"眼科-屈光斜弱視","meta":"111年第2次第15題","year":111,"session":2,"number":15,"question":"有關弱視的敘述，下列何者正確？","options":["(A) 弱視為兩眼在視覺發育關鍵期（critical period）時，兩眼競爭、抑制（interocular suppression）導致對應之視皮質發育異常，所以不可能兩眼同時弱視","(B) 內斜視會引起弱視，外斜視不會引起弱視","(C) 老年人因白內障遮蔽致使矯正視力不佳，也屬於弱視的一種","(D) 弱視在關鍵期（critical period）內及早發現，治療效果較好；因此學齡前的兒童應做視力和立體感的篩檢以及早發現與治療"],"answer":3,"image":""},{"id":"md6-111-2-16","subject":"md6","topic":"眼科-視網膜葡萄膜","meta":"111年第2次第16題","year":111,"session":2,"number":16,"question":"視神經盤水腫（optic disc swelling）的鑑別診斷與下列何者不相關？","options":["(A) 高血糖或高血壓的視神經合併症","(B) 因腦壓高所造成的papilledema","(C) 正常眼壓性青光眼","(D) 輕微或初期性中心視網膜靜脈阻塞（central retinal vein occlusion）"],"answer":2,"image":""},{"id":"md6-111-2-17","subject":"md6","topic":"眼科-角膜結膜眼瞼眼窩","meta":"111年第2次第17題","year":111,"session":2,"number":17,"question":"侵犯眼睛的病毒中，下列何者不屬於疱疹病毒科（herpes viruses）？","options":["(A) 水痘帶狀疱疹病毒（varicella-zoster virus）","(B) EB病毒（Epstein-Barr virus）","(C) 人類免疫缺乏病毒（human immunodeficiency virus）","(D) 巨細胞病毒（Cytomegalovirus）"],"answer":2,"image":""},{"id":"md6-111-2-18","subject":"md6","topic":"眼科-角膜結膜眼瞼眼窩","meta":"111年第2次第18題","year":111,"session":2,"number":18,"question":"有關甲狀腺眼病變（Graves' ophthalmopathy）患者眼瞼攣縮（lid retraction）的敘述，下列何者錯誤？","options":["(A) 可以單側或雙側表現","(B) 可發生在上眼瞼或下眼瞼","(C) 可能原因包括張眼肌肉群（lid retractors）的纖維化","(D) 其特徵為眼球往下看時上眼瞼隨之下落時間延遲"],"answer":3,"image":""},{"id":"md6-111-2-19","subject":"md6","topic":"耳科學","meta":"111年第2次第19題","year":111,"session":2,"number":19,"question":"50歲病人，因左耳聽力損失及偶爾流膿前來就診，耳鏡檢查如圖，下列何者為最可能之診斷？","options":["(A) 急性中耳炎","(B) 積液性中耳炎","(C) 慢性中耳炎","(D) 膽脂瘤"],"answer":2,"image":"md6-111-2-19.jpeg"},{"id":"md6-111-2-20","subject":"md6","topic":"耳科學","meta":"111年第2次第20題","year":111,"session":2,"number":20,"question":"關於老年型聽力退化，下列敘述何者最不適當？","options":["(A) 一般而言，同年齡男性比女性退化嚴重","(B) 噪音傷害會使聽力退化加劇","(C) 會造成語音辨識度變差","(D) 通常從低頻處先開始退化"],"answer":3,"image":""},{"id":"md6-111-2-21","subject":"md6","topic":"鼻科學","meta":"111年第2次第21題","year":111,"session":2,"number":21,"question":"有關巴特氏額頭膨腫（Pott puffy tumor），下列敘述何者正確？","options":["(A) 病因是篩骨（ethmoid bone）的骨膜下膿瘍（subperiosteal abscess）及骨髓炎（osteomyelitis）","(B) 常侵犯老年人","(C) 常侵犯具有自體免疫性疾病（autoimmune disease）的病人","(D) 早期症狀可能只有輕微的局部軟組織硬化（induration）"],"answer":3,"image":""},{"id":"md6-111-2-22","subject":"md6","topic":"鼻科學","meta":"111年第2次第22題","year":111,"session":2,"number":22,"question":"有關過敏性鼻炎（allergic rhinitis）的治療，下列何者不屬於第一線選項？","options":["(A) 抗組織胺（antihistamine）","(B) 去充血劑（decongestant）","(C) 類固醇鼻噴劑（intranasal steroid）","(D) 免疫治療（immunotherapy）"],"answer":3,"image":""},{"id":"md6-111-2-23","subject":"md6","topic":"鼻科學","meta":"111年第2次第23題","year":111,"session":2,"number":23,"question":"有關流鼻血（epistaxis）的治療，下列敘述何者最適當？","options":["(A) 加壓鼻骨（nasal bone）處10～15分鐘","(B) 膠原蛋白凝膠基質（collagen gel matrix）或氧化纖維素（oxidized cellulose）敷料對控制出血無效益","(C) 加壓前鼻中隔（anterior nasal septum）或鼻填塞（nasal packing）","(D) 前篩動脈結紮（anterior ethmoidal artery ligation）"],"answer":2,"image":""},{"id":"md6-111-2-24","subject":"md6","topic":"喉科學與頭頸腫瘤","meta":"111年第2次第24題","year":111,"session":2,"number":24,"question":"有關成人原因不明之聲門下狹窄（idiopathic subglottic stenosis），下列敘述何者最不適當？","options":["(A) 多發生於生育年齡層之女性","(B) 與女性荷爾蒙相關，在聲門下檢體中可發現有較多的雌激素受體（estrogen receptor）","(C) 與逆流性咽喉炎（laryngopharyngeal reflux）相關","(D) 在病人的聲門下瘢痕組織中有可能檢出胃蛋白酶（pepsin）"],"answer":[0,1,2,3],"image":"","answer_note":"送分:第24題，一律給分 (原公告答案 B)"},{"id":"md6-111-2-25","subject":"md6","topic":"喉科學與頭頸腫瘤","meta":"111年第2次第25題","year":111,"session":2,"number":25,"question":"有關早期喉癌（T1, T2）的手術與放射線治療之比較，下列何者錯誤？","options":["(A) 放射線治療所需要的時間較長，成本也較手術治療為高","(B) 就局部腫瘤的控制，或治癒率、存活率而言，兩種治療方式不相上下","(C) 就長期的喉保存（laryngeal preservation）而言，手術的結果較差","(D) 某些腫瘤因生長部位，不易以內視鏡方式切除，可考慮以經口機器人手術（transoral robotic surgery）或放射線治療"],"answer":2,"image":""},{"id":"md6-111-2-26","subject":"md6","topic":"喉科學與頭頸腫瘤","meta":"111年第2次第26題","year":111,"session":2,"number":26,"question":"唾液腺結石（sialolithiasis）最常出現於下列何者？","options":["(A) 下頷腺（submandibular gland）","(B) 腮腺（parotid gland）","(C) 舌下腺（sublingual gland）","(D) 小唾液腺（minor salivary gland）"],"answer":0,"image":""},{"id":"md6-111-2-27","subject":"md6","topic":"喉科學與頭頸腫瘤","meta":"111年第2次第27題","year":111,"session":2,"number":27,"question":"關於甲狀腺髓質癌（medullary carcinoma），下列敘述何者錯誤？","options":["(A) 腫瘤細胞起源於parafollicular C cell","(B) 大部分為家族遺傳型（familial），少部分為偶發型（sporadic）","(C) 頸部淋巴轉移相當常見","(D) 血液中calcitonin可做為追蹤的有效腫瘤標記"],"answer":1,"image":""},{"id":"md6-111-2-28","subject":"md6","topic":"產科-一般產科","meta":"111年第2次第28題","year":111,"session":2,"number":28,"question":"關於android型骨盆的敘述，下列何者錯誤？","options":["(A) 會聚的側壁（convergent sidewalls）","(B) 明顯的坐骨棘（ischial spines）","(C) 狹窄的恥骨弓（pubic arch）","(D) 骨盆出口的橫徑（transverse diameter of pelvic outlet）＞10 cm"],"answer":3,"image":""},{"id":"md6-111-2-29","subject":"md6","topic":"產科-一般產科","meta":"111年第2次第29題","year":111,"session":2,"number":29,"question":"在懷孕全程，母親血液中的下列何種荷爾蒙濃度並不會隨著妊娠週數增加而持續增加？","options":["(A) 雌二醇（estradiol）","(B) 雌三醇（estriol）","(C) 人類絨毛膜刺激激素（human chorionic gonadotropin）","(D) 人類胎盤催乳激素（human placental lactogen）"],"answer":2,"image":""},{"id":"md6-111-2-30","subject":"md6","topic":"產科-一般產科","meta":"111年第2次第30題","year":111,"session":2,"number":30,"question":"胎兒羊水（amnionic fluid）體積的調控除胎兒尿液（fetal urination）外，以下列何者最多？","options":["(A) 胎兒吞嚥（fetal swallowing）","(B) 胎兒肺部分泌（fetal lung fluid secretion）","(C) 胎盤表面經膜內胎兒血管流入（intramembranous flow across fetal vessels on the placental surface）","(D) 母體循環經羊膜流入（transmembranous flow across amnionic membrane）"],"answer":[0,1,2,3],"image":"","answer_note":"送分:第30題，一律給分 (原公告答案 A)"},{"id":"md6-111-2-31","subject":"md6","topic":"產科-一般產科","meta":"111年第2次第31題","year":111,"session":2,"number":31,"question":"關於以超音波杜卜勒（Doppler）檢查足月胎兒臍動脈的血流速度測量（umbilical artery Doppler velocimetry）之敘述，下列何者屬正常？","options":["(A) 臍動脈的血流速度測量收縮－舒張值比率（systolic-diastolic [S/D] ratio）大於該妊娠週數之95th percentile","(B) 臍動脈的血流速度測量收縮－舒張值比率（systolic-diastolic [S/D] ratio）小於3","(C) 臍動脈的血流速度測量顯示終端血管舒張時血流消失（absent end-diastolic flow）","(D) 臍動脈的血流速度測量顯示終端血管舒張時血流逆行（reversed end-diastolic flow）"],"answer":1,"image":""},{"id":"md6-111-2-32","subject":"md6","topic":"產科-一般產科","meta":"111年第2次第32題","year":111,"session":2,"number":32,"question":"難產（dystocia）的定義為產程進展異常的緩慢，一般有三個因素可造成。下列何者錯誤？","options":["(A) pubis：symphysis shape異常","(B) power：uterine contractility不夠好","(C) passenger：fetus過大","(D) passage：pelvis太窄或軟組織過多"],"answer":0,"image":""},{"id":"md6-111-2-33","subject":"md6","topic":"產科-高危險妊娠","meta":"111年第2次第33題","year":111,"session":2,"number":33,"question":"導致胎兒水腫（hydrops fetalis）常見的原因，下列敘述何者錯誤？","options":["(A) 透納氏症（Turner syndrome）","(B) 巨細胞病毒（cytomegalovirus）感染","(C) 雙胞胎輸血症候群（twin-twin transfusion syndrome）","(D) 無腦症（anencephaly）"],"answer":3,"image":""},{"id":"md6-111-2-34","subject":"md6","topic":"產科-高危險妊娠","meta":"111年第2次第34題","year":111,"session":2,"number":34,"question":"胎兒生理評估（biophysical profile）包含無壓力測試（nonstress test）、胎兒呼吸（fetal breathing）、胎兒張力（fetal tone）、胎動（fetal movement）、羊水量（amnionic fluid volume）五項指標，下列敘述何者錯誤？","options":["(A) 得分6分，且羊水量過少者建議生產","(B) 得分6分，羊水量正常且週數大於36週建議生產","(C) 得分4分，應該隔日再次評估，若小於等於6分建議生產","(D) 得分2分者建議生產"],"answer":2,"image":""},{"id":"md6-111-2-35","subject":"md6","topic":"產科-高危險妊娠","meta":"111年第2次第35題","year":111,"session":2,"number":35,"question":"下列那一項是導致絨毛膜羊膜炎（chorioamnionitis）最主要的原因？","options":["(A) 母親抽菸（maternal smoking）","(B) 破水時間延長（prolonged rupture of membranes）","(C) 母體免疫抑制（maternal immunosuppression）","(D) 合併妊娠糖尿病（pregnancy complicated by gestational diabetes）"],"answer":1,"image":""},{"id":"md6-111-2-36","subject":"md6","topic":"產科-高危險妊娠","meta":"111年第2次第36題","year":111,"session":2,"number":36,"question":"幾乎一半的胎兒死亡（fetal death），是由下列那一項懷孕併發症（pregnancy complication）造成的？","options":["(A) 子癇前症（preeclampsia）","(B) 羊水過少（oligohydramnios）","(C) 胎兒畸形（fetal malformations）","(D) 胎兒生長受限（fetal growth restriction）"],"answer":3,"image":""},{"id":"md6-111-2-37","subject":"md6","topic":"產科-高危險妊娠","meta":"111年第2次第37題","year":111,"session":2,"number":37,"question":"於正常懷孕期間，葡萄糖代謝會產生生理變化，下列何者不是懷孕時的現象？","options":["(A) 輕微的空腹低血糖","(B) 飯後高血糖更為明顯","(C) 飯後高胰島素血症（hyperinsulinemia）","(D) 飯後升糖激素（glucagon）更不受抑制"],"answer":3,"image":""},{"id":"md6-111-2-38","subject":"md6","topic":"產科-高危險妊娠","meta":"111年第2次第38題","year":111,"session":2,"number":38,"question":"孕婦妊娠30週發生重度子癇前症，依病情因素必須終止繼續懷孕時，通常會給與孕婦肌肉注射類固醇而延後48小時生產，但如發生下列何種情形時，則建議立即生產？","options":["(A) 無法控制的高血壓急症","(B) 早期破水","(C) 羊水過少","(D) 肝功能高於正常值上限的兩倍"],"answer":0,"image":""},{"id":"md6-111-2-39","subject":"md6","topic":"產科-高危險妊娠","meta":"111年第2次第39題","year":111,"session":2,"number":39,"question":"子癇前症症候群的疾病特徵為系統性血管內皮損傷，其後續變化不包括下列何者？","options":["(A) 血管痙攣","(B) 血漿外洩","(C) 血栓性病變","(D) 充血性病變"],"answer":3,"image":""},{"id":"md6-111-2-40","subject":"md6","topic":"婦科-生殖內分泌","meta":"111年第2次第40題","year":111,"session":2,"number":40,"question":"關於先天性腎上腺增生（congenital adrenal hyperplasia）的診治，下列敘述何者最不適當？","options":["(A) 患者外陰性別不明（ambiguous genitalia）","(B) 患者常合併子宮畸形","(C) 檢驗血中17α-羥基丙酮（17α-hydroxyprogesterone）濃度有助於診斷","(D) 治療需補充類固醇（如hydrocortisone）"],"answer":1,"image":""},{"id":"md6-111-2-41","subject":"md6","topic":"婦科-良性腫瘤與內膜異位","meta":"111年第2次第41題","year":111,"session":2,"number":41,"question":"生育年齡婦女發現骨盆腔腫塊，下列敘述何者最不適當？","options":["(A) 先確定有無懷孕","(B) 子宮肌瘤是最常見的良性子宮腫瘤，大部分會引起症狀","(C) 這個年齡層常見的卵巢瘤通常是良性的","(D) 最常見的卵巢腫瘤是畸胎瘤或子宮內膜異位瘤"],"answer":1,"image":""},{"id":"md6-111-2-42","subject":"md6","topic":"婦科-生殖道感染與先天異常","meta":"111年第2次第42題","year":111,"session":2,"number":42,"question":"梅毒（syphilis）最常使用的治療藥物為下列何者？","options":["(A) penicillin G","(B) interferon","(C) azithromycin","(D) doxycycline"],"answer":0,"image":""},{"id":"md6-111-2-43","subject":"md6","topic":"婦科-良性腫瘤與內膜異位","meta":"111年第2次第43題","year":111,"session":2,"number":43,"question":"一個7歲女孩，初經尚未來潮，由媽媽陪同來到門診。主訴肚子脹脹的但不會痛，於別科檢查時發現有卵巢囊腫而轉診。你安排婦科超音波發現單側卵巢有一直徑約6x6公分的卵巢囊腫，囊腫為單一腔室（unilocular），內部並無回音或固態組織，腹腔內部並無腹水，另一側卵巢為正常。下列何者為最適當的處理方法？","options":["(A) 密切觀察（observation）","(B) 卵巢囊腫抽吸（cyst aspiration）","(C) 單側卵巢囊腫切除手術（unilateral oophorocystectomy）","(D) 單側卵巢全切除手術（unilateral oophorectomy）"],"answer":0,"image":""},{"id":"md6-111-2-44","subject":"md6","topic":"婦科-手術學與診斷技術","meta":"111年第2次第44題","year":111,"session":2,"number":44,"question":"不正常子宮出血（abnormal uterine bleeding）可能的原因，通常不包括下列何項？","options":["(A) 懷孕（pregnancy）","(B) 甲狀腺功能失調（thyroid dysfunction）","(C) 輸卵管積水（hydrosalpinx）","(D) 子宮內膜腫瘤（endometrial tumors）"],"answer":2,"image":""},{"id":"md6-111-2-45","subject":"md6","topic":"婦科-腫瘤","meta":"111年第2次第45題","year":111,"session":2,"number":45,"question":"下列有關子宮內膜息肉（endometrial polyp）的敘述，何者錯誤？","options":["(A) 子宮內膜息肉形成與使用tamoxifen有關","(B) 大部分的子宮內膜息肉是沒有症狀的","(C) 子宮內膜息肉常見的症狀是不規則子宮出血","(D) 子宮內膜息肉不會造成經痛"],"answer":3,"image":""},{"id":"md6-111-2-46","subject":"md6","topic":"婦科-腫瘤","meta":"111年第2次第46題","year":111,"session":2,"number":46,"question":"下列有關子宮平滑肌瘤（uterine leiomyoma）的敘述，何者錯誤？","options":["(A) 子宮平滑肌瘤是最常見的良性婦科腫瘤","(B) 漿膜下子宮平滑肌瘤（subserosal uterine leiomyoma）常常造成經血量增多（hypermenorrhea）的症狀","(C) gonadotropin-releasing hormone（GnRH）agonist類藥物可使用於子宮平滑肌瘤治療","(D) 移除黏膜下子宮平滑肌瘤（submucosal uterine leiomyoma）可增加受孕率"],"answer":1,"image":""},{"id":"md6-111-2-47","subject":"md6","topic":"婦科-生殖道感染與先天異常","meta":"111年第2次第47題","year":111,"session":2,"number":47,"question":"女性胎兒的雙側穆勒氏管（Müllerian ducts）彼此將交會融合，其間的隔層將吸收消失。這過程若發生失誤，所可能發生的先天性異常當中，並不包括下列的那一項？","options":["(A) 無子宮","(B) 雙角子宮（bicornuate uterus）","(C) 中膈子宮（septate uteri）","(D) 多卵巢症（supernumerary ovary）"],"answer":3,"image":""},{"id":"md6-111-2-48","subject":"md6","topic":"婦科-生殖道感染與先天異常","meta":"111年第2次第48題","year":111,"session":2,"number":48,"question":"下列何者最常引起細菌性陰道炎（bacterial vaginosis）？","options":["(A) 乳酸菌（lactobacilli）","(B) 陰道加德納菌（Gardnerella vaginalis）","(C) 乙型鏈球菌（group B Streptococcus）","(D) 披衣菌（Chlamydia trachomatis）"],"answer":1,"image":""},{"id":"md6-111-2-49","subject":"md6","topic":"婦科-腫瘤","meta":"111年第2次第49題","year":111,"session":2,"number":49,"question":"關於卵巢癌的轉移路徑，下列敘述何者正確？","options":["(A) 早期常見經由血液轉移","(B) 常經由腹膜轉移","(C) 末期的卵巢癌較少經由淋巴轉移","(D) 能經由皮膚轉移"],"answer":1,"image":""},{"id":"md6-111-2-50","subject":"md6","topic":"婦科-腫瘤","meta":"111年第2次第50題","year":111,"session":2,"number":50,"question":"下列何者不是vulvar cancer的risk factors之一？","options":["(A) human papillomavirus（HPV）infection","(B) lichen sclerosus","(C) nulliparity","(D) history of cervical cancer"],"answer":2,"image":""},{"id":"md6-111-2-51","subject":"md6","topic":"婦科-腫瘤","meta":"111年第2次第51題","year":111,"session":2,"number":51,"question":"下列何者不是子宮頸陰道鏡檢查下侵犯性病灶的特徵？","options":["(A) 異常網狀血管","(B) 不規則表面合併上皮潰爛","(C) 醋酸塗抹後上皮白化","(D) 因血管增生或表皮壞死造成的顏色改變"],"answer":2,"image":""},{"id":"md6-111-2-52","subject":"md6","topic":"婦科-腫瘤","meta":"111年第2次第52題","year":111,"session":2,"number":52,"question":"關於gestational trophoblastic disease（GTD）的敘述，下列何者錯誤？","options":["(A) GTD是一種胎盤內細胞滋養層不正常增生的疾病","(B) GTD的病人血中human chorionic gonadotropin（hCG）都會異常上升","(C) gestational trophoblastic neoplasia（GTN）化療治癒後仍有機會正常懷孕","(D) gestational trophoblastic neoplasia（GTN）在低風險未轉移前，使用化療反應率不錯（high remission rate）"],"answer":1,"image":""},{"id":"md6-111-2-53","subject":"md6","topic":"婦科-腫瘤","meta":"111年第2次第53題","year":111,"session":2,"number":53,"question":"子宮內膜癌，通常可分為兩種型態，type I與type II，有關此兩種型態腫瘤的敘述，下列何者不恰當？","options":["(A) type I一般與荷爾蒙有關，而type II與荷爾蒙較無直接相關","(B) type I發生的年紀一般較輕，而type II發生的族群年紀較大","(C) type II較type I容易同時併發原發性的卵巢上皮癌","(D) PTEN突變（mutation）可在type I中常見到，而HER2/neu則常在type II中發現"],"answer":2,"image":""},{"id":"md6-111-2-54","subject":"md6","topic":"婦科-生殖內分泌","meta":"111年第2次第54題","year":111,"session":2,"number":54,"question":"下列何者最能表示卵巢中卵泡的庫存量下降？","options":["(A) 月經第三天FSH下降","(B) 月經第三天雌二醇（estradiol）下降","(C) 兩側卵巢竇濾泡（antral follicle）總數小於4","(D) 抗穆勒氏管激素（anti-Müllerian hormone）上升"],"answer":2,"image":""},{"id":"md6-111-2-55","subject":"md6","topic":"婦科-生殖內分泌","meta":"111年第2次第55題","year":111,"session":2,"number":55,"question":"多囊性卵巢症候群（polycystic ovary syndrome）患者會有雄性素過高的症狀，下列何者不是造成雄性素過高的原因？","options":["(A) 腎上腺分泌過多的硫酸－脫氫異雄固酮（dehydroepiandrosterone sulfate, DHEAS）","(B) 卵巢分泌過多的睪固酮（testosterone）","(C) 肝臟分泌過多的性激素結合球蛋白（sex hormone-binding globulin, SHBG）","(D) 胰臟分泌過多的胰島素（insulin）"],"answer":2,"image":""},{"id":"md6-111-2-56","subject":"md6","topic":"婦科-生殖內分泌","meta":"111年第2次第56題","year":111,"session":2,"number":56,"question":"試管嬰兒療程中，取卵的時機點必須搭配黃體化激素潮放（LH surge）的時間以利卵細胞成熟，正常女性生理週期在LH surge開始之後多久會排卵（ovulation）？","options":["(A) 10～12小時","(B) 22～24小時","(C) 34～36小時","(D) 46～48小時"],"answer":2,"image":""},{"id":"md6-111-2-57","subject":"md6","topic":"婦科-尿失禁與骨盆腔脫垂","meta":"111年第2次第57題","year":111,"session":2,"number":57,"question":"關於尿失禁（urinary incontinence）的手術治療，下列敘述何者錯誤？","options":["(A) 恥骨後陰道懸吊手術（retropubic colposuspension surgery, Burch procedure）：縫線固定到Cooper ligament","(B) 無張力陰道吊帶手術（tension-free vaginal tape, TVT）：以無張力下，將吊帶放置在膀胱頸處","(C) 經閉孔吊帶手術（transobturator tape, TOT）比無張力陰道吊帶手術（tension-free vaginal tape, TVT），較無腸道及血管的損傷","(D) 無張力陰道吊帶手術（tension-free vaginal tape, TVT）比經閉孔吊帶手術（transobturator tape, TOT），較常發生膀胱穿孔"],"answer":1,"image":""},{"id":"md6-111-2-58","subject":"md6","topic":"復健-神經復健","meta":"111年第2次第58題","year":111,"session":2,"number":58,"question":"下列何者不是中大腦動脈（middle cerebral artery）中風之常見症狀？","options":["(A) 忽略症候群（neglect syndrome）","(B) 失用症（apraxia）","(C) 情感失認症（affective agnosia）","(D) 動作不能性緘默（akinetic mutism）"],"answer":[2,3],"image":"","answer_note":"更正:第58題，答Ｃ或Ｄ或CD者均給分"},{"id":"md6-111-2-59","subject":"md6","topic":"復健-神經復健","meta":"111年第2次第59題","year":111,"session":2,"number":59,"question":"關於周邊神經病變的復健及治療，下列何者錯誤？","options":["(A) 復健初期可利用支架、被動關節運動來避免關節攣縮","(B) 完全去神經的肌肉可用直流電刺激來減慢肌肉萎縮和纖維化","(C) 神經截斷（neurotmesis）下，一定要先接受復健3個月，若沒有進步再考慮手術治療","(D) 神經失用（neuropraxia）的預後很好，一般在3個月內可恢復大部分功能"],"answer":2,"image":""},{"id":"md6-111-2-60","subject":"md6","topic":"復健-神經復健","meta":"111年第2次第60題","year":111,"session":2,"number":60,"question":"所謂的Formet's sign是因那一條神經病變導致手指肌肉萎縮？","options":["(A) 尺神經","(B) 橈神經","(C) 正中神經","(D) 肌皮神經"],"answer":[0,1,2,3],"image":"","answer_note":"送分:第60題，一律給分。。 (原公告答案 A)"},{"id":"md6-111-2-61","subject":"md6","topic":"復健-神經復健","meta":"111年第2次第61題","year":111,"session":2,"number":61,"question":"肌電圖（electromyography）檢查中，下列何種疾病最容易出現肌肉顫動（fasciculation）現象？","options":["(A) 糖尿病神經病變（diabetic neuropathy）","(B) 運動神經元疾病（motor neuron disease）","(C) 急性發炎性脫髓鞘多發性神經病變症候群（Guillain-Barré syndrome）","(D) 脊椎神經根病變（radiculopathy）"],"answer":1,"image":""},{"id":"md6-111-2-62","subject":"md6","topic":"復健-骨骼肌肉損傷與疾患","meta":"111年第2次第62題","year":111,"session":2,"number":62,"question":"下列關於網球肘（tennis elbow）之敘述，何者正確？","options":["(A) 其病理變化以炎性（inflammation）為主","(B) 通常病變的部位在肌肉、肌腱交接處（musculotendinous junction）","(C) 通常肘關節的活動度（range of motion）會變差","(D) 最常侵犯的是橈側伸腕短肌（extensor carpi radialis brevis）肌腱"],"answer":3,"image":""},{"id":"md6-111-2-63","subject":"md6","topic":"復健-骨骼肌肉損傷與疾患","meta":"111年第2次第63題","year":111,"session":2,"number":63,"question":"人類第三與第四節腰椎間板（intervertebral disc）的內部壓力，在下列何種姿勢時最高？","options":["(A) 平躺","(B) 站立","(C) 坐姿上半身前傾20度","(D) 坐姿上半身直立不前傾"],"answer":2,"image":""},{"id":"md6-111-2-64","subject":"md6","topic":"復健-截肢與義肢輔具","meta":"111年第2次第64題","year":111,"session":2,"number":64,"question":"膝下截肢型義肢（below knee, B/K prosthesis）在製做髕骨肌腱承重（patella tendon-bearing, PTB）承筒（socket）的時候，下列那一個部位是可以承受壓力的區域（pressure-tolerant area）？","options":["(A) 腓骨頭（fibular head）","(B) 脛骨嵴（tibial crest）","(C) 股骨內髁（medial femoral condyle）","(D) 膕肌肌腱（hamstring tendon）"],"answer":2,"image":""},{"id":"md6-111-2-65","subject":"md6","topic":"復健-心肺復健與運動處方","meta":"111年第2次第65題","year":111,"session":2,"number":65,"question":"關於有氧運動（aerobic exercise）的描述，何者正確？","options":["(A) 在無氧閾值（anaerobic threshold，簡稱AT）以上的強度進行運動時，就是有氧運動","(B) 雖然將運動按氧氣之介入與否，來分類為有氧或是無氧，但有些運動卻是難予劃分的","(C) 一般而言，心率達到最大心率的30%～35%，就可認定是在進行有氧運動","(D) 比較科學的認定是指短時間、有節奏、會令心率上升的小肌肉運動"],"answer":1,"image":""},{"id":"md6-111-2-66","subject":"md6","topic":"復健-心肺復健與運動處方","meta":"111年第2次第66題","year":111,"session":2,"number":66,"question":"在冠狀動脈心臟病病人的危險分級中，下列何者屬於高危險性？","options":["(A) 急性心肌梗塞後沒有明顯併發症","(B) 左心室排血分數（ejection fraction）低於30%","(C) 冠狀動脈繞道手術後","(D) 65歲以上的老年人"],"answer":1,"image":""},{"id":"md6-111-2-67","subject":"md6","topic":"復健-兒童與一般復健","meta":"111年第2次第67題","year":111,"session":2,"number":67,"question":"下列關於先天性臂神經叢受損（congenital brachial plexus injuries）的敘述，何者正確？","options":["(A) Erb氏麻痺（Erb's palsy）是指損傷發生於臂神經叢的下半部（lower plexus）","(B) Klumpke氏麻痺（Klumpke's palsy）是指損傷發生於臂神經叢上半部（upper plexus）","(C) Erb氏麻痺較Klumpke氏麻痺少見","(D) 不管是Erb氏麻痺或Klumpke氏麻痺，大多數患者日後皆復原良好"],"answer":3,"image":""},{"id":"md6-111-2-68","subject":"md6","topic":"復健-兒童與一般復健","meta":"111年第2次第68題","year":111,"session":2,"number":68,"question":"高膽紅質血症（hyperbilirubinemia）與那一類型的腦性麻痺（cerebral palsy）關聯性最高？","options":["(A) 痙攣型（spastic type）","(B) 徐動型（athetoid type）","(C) 低張型（hypotonic type）","(D) 失調型（ataxic type）"],"answer":1,"image":""},{"id":"md6-111-2-69","subject":"md6","topic":"復健-神經復健","meta":"111年第2次第69題","year":111,"session":2,"number":69,"question":"垂足患者接受功能性電刺激（FES或functional electrical stimulation）時，主要刺激以下那條神經？","options":["(A) 脛神經（tibial nerve）","(B) 深腓神經（deep peroneal nerve）","(C) 股神經（femoral nerve）","(D) 蹠神經（plantar nerve）"],"answer":1,"image":""},{"id":"md6-111-2-70","subject":"md6","topic":"復健-神經復健","meta":"111年第2次第70題","year":111,"session":2,"number":70,"question":"王先生初次中風後，肌力接近正常，但不會穿衣服，被診斷為失用症（apraxia），他最有可能的中風位置在：","options":["(A) 頂葉（parietal lobe）","(B) 前葉（frontal lobe）","(C) 枕葉（occipital lobe）","(D) 顳葉（temporal lobe）"],"answer":0,"image":""},{"id":"md6-111-2-71","subject":"md6","topic":"復健-骨骼肌肉損傷與疾患","meta":"111年第2次第71題","year":111,"session":2,"number":71,"question":"De Quervain's肌腱腱鞘炎常見以下那兩條肌腱的發炎？ћ伸拇短肌（extensor pollicis brevis） ќ伸拇長肌（extensor pollicis longus） ѝ外展拇短肌（abductor pollicis brevis） ў外展拇長肌（abductor pollicis longus）","options":["(A) ћѝ","(B) ќў","(C) ћў","(D) ќѝ"],"answer":2,"image":""},{"id":"md6-111-2-72","subject":"md6","topic":"眼科-角膜結膜眼瞼眼窩","meta":"111年第2次第72題","year":111,"session":2,"number":72,"question":"關於眼部影像診斷的敘述，下列何者者錯誤？","options":["(A) 造成眼眶內腫塊的原因包括腫瘤，例例如淋巴瘤和視神經腫瘤，以及血管性疾病","(B) 眼眶外疾病也常造成凸眼，例如鼻竇竇炎","(C) 甲狀腺眼病（thyroid eye disease）造造成的眼外肌變大常常是雙側的","(D) 甲狀腺眼病（thyroid eye disease）不不會造成眼眶內脂肪變大或水腫"],"answer":3,"image":""},{"id":"md6-111-2-73","subject":"md6","topic":"復健-骨骼肌肉損傷與疾患","meta":"111年第2次第73題","year":111,"session":2,"number":73,"question":"60歲男性病患因長期頸部疼痛接受電電腦斷層檢查，發現第3至第4頸椎有一鈣化病病灶如圖。其診斷為何？","options":["(A) old vertebral fracture","(B) ossification of the posterior longitudinall ligament","(C) ankylosing spondylitis","(D) tuberculous spondylodiskitis"],"answer":1,"image":"md6-111-2-73.jpeg"},{"id":"md6-111-2-74","subject":"md6","topic":"婦科-良性腫瘤與內膜異位","meta":"111年第2次第74題","year":111,"session":2,"number":74,"question":"18歲女性，因急性下腹痛就醫，腹部部Ｘ光影像如圖，最可能的診斷為何？","options":["(A) 右髂內動脈瘤（right internal iliac artery aneurysm）","(B) 骨盆腔發炎性疾病（pelvic inflammatory disease）","(C) 畸胎瘤（teratoma）","(D) 薦骨骨折（sacral bone fracture）"],"answer":2,"image":"md6-111-2-74.jpeg"},{"id":"md6-111-2-75","subject":"md6","topic":"眼科-視網膜葡萄膜","meta":"111年第2次第75題","year":111,"session":2,"number":75,"question":"有關眼睛鈍傷（blunt eye trauma）的敘述，下列何者最正確？","options":["(A) 檢查眼球的移動功能，如果不能向上看可能是第三對腦神經受傷","(B) 如有前房出血（hyphema），可能會造成眼壓上升","(C) 隔前出血（preseptal hemorrhage）容易造成眼眶腔室症候群，必須立即減壓","(D) 病人如眼球破裂（ruptured globe），一般都有明顯視力受損"],"answer":1,"image":""},{"id":"md6-111-2-76","subject":"md6","topic":"喉科學與頭頸腫瘤","meta":"111年第2次第76題","year":111,"session":2,"number":76,"question":"成年人頸部側面有腫塊，造成腫塊的原因下列何者最罕見？","options":["(A) 淋巴瘤","(B) 唾液腺腫瘤","(C) 甲狀舌管囊腫","(D) 消化道癌轉移"],"answer":2,"image":""},{"id":"md6-111-2-77","subject":"md6","topic":"麻醉-呼吸道與監視","meta":"111年第2次第77題","year":111,"session":2,"number":77,"question":"25歲男性病人有頭部外傷，至急診時昏迷指數（Glasgow Coma Scale）7分，血壓220/116 mmHg，瞳孔不等大，要實施快速順序插管（rapid-sequence intubation），下列藥物何者使用須特別小心？","options":["(A) lidocaine","(B) ketamine","(C) etomidate","(D) propofol"],"answer":1,"image":""},{"id":"md6-111-2-78","subject":"md6","topic":"醫學倫理與法規","meta":"111年第2次第78題","year":111,"session":2,"number":78,"question":"林太太剛結婚，她先生不知道林太太以前結過婚且已有兩個小孩，林太太要醫師承諾不得將此事告知其丈夫，且病歷上不能記載，因為她的丈夫若得知此事，可能會和她離婚。醫師如何應對較為適當？","options":["(A) 承諾林太太會保密，但病歷必須詳實記載","(B) 承諾林太太會保密，且病歷也不記載","(C) 不承諾林太太保密，因為誠實是醫事人員的倫理義務","(D) 不承諾林太太保密，因為對此資訊，她先生有重大的知的權利"],"answer":0,"image":""},{"id":"md6-111-2-79","subject":"md6","topic":"醫學倫理與法規","meta":"111年第2次第79題","year":111,"session":2,"number":79,"question":"病人的兒子要求醫師不要將癌症切片報告告訴病人，以免讓病人承受不了衝擊，醫師本想依家屬要求含糊告訴病人，但最後婉拒家屬的要求，這是考量那一項倫理原則所做的決定？","options":["(A) 行善原則（beneficence）","(B) 尊重自主原則（respect for autonomy）","(C) 不傷害原則（non-maleficence）","(D) 正義原則（justice）"],"answer":1,"image":""},{"id":"md6-111-2-80","subject":"md6","topic":"醫學倫理與法規","meta":"111年第2次第80題","year":111,"session":2,"number":80,"question":"林先生為口腔癌症末期病人，因呼吸困難被家人送到醫院急診室，林先生意識不清，醫護人員認為病人死亡已經無法避免，不應再施以急救，下列作法的優先次序為何？ћ查詢病人是否已簽署DNR意願書 ќ徵求家屬同意並簽署同意書 ѝ查詢病人有無醫療委任代理人","options":["(A) ћ→ѝ→ќ","(B) ћ→ќ→ѝ","(C) ѝ→ћ→ќ","(D) ѝ→ќ→ћ"],"answer":0,"image":""},{"id":"md6-112-1-1","subject":"md6","topic":"麻醉-呼吸道與監視","meta":"112年第1次第1題","year":112,"session":1,"number":1,"question":"執行全身麻醉誘導後，遇到非預期的困難呼吸道，並發生無法通氣及插管（cannot ventilate, cannot intubate）的情況，麻醉醫師立即施行環甲膜切開術（surgical cricothyrotomy），下列敘述何者錯誤？","options":["(A) 環甲膜切開術亦適用於六歲以下兒童施行","(B) 讓病人平躺，觸摸頸部甲狀軟骨下緣，以環狀軟骨與甲狀軟骨之間的距離來定位","(C) 環甲膜切開術之併發症，包括出血與感染","(D) 環甲膜切開術不應作為將來病人之永久性通氣道（permanent airway）"],"answer":0,"image":""},{"id":"md6-112-1-2","subject":"md6","topic":"麻醉-呼吸道與監視","meta":"112年第1次第2題","year":112,"session":1,"number":2,"question":"有關病患於手術麻醉期間發生體溫過低（hypothermia）的現象，下列敘述何者錯誤？","options":["(A) 全身麻醉劑會降低身體啟動血管收縮及寒顫（shivering）等保溫機轉的閾值（thresholds）","(B) 開刀房內較低的氣溫也會導致手術麻醉期間發生的體溫過低","(C) 絕大部分的初始體溫散失（initial cause of hypothermia），都是導因於中樞至周邊的體熱再分布作用（redistribution of body heat）","(D) 神經軸麻醉（neuraxial anesthesia）不會發生體溫過低的現象"],"answer":3,"image":""},{"id":"md6-112-1-3","subject":"md6","topic":"麻醉-呼吸道與監視","meta":"112年第1次第3題","year":112,"session":1,"number":3,"question":"對一正常人直接測量其下列各血管之systolic blood pressure，測得結果由高至低排列順序為何？①femoral artery ②dorsalis pedis artery ③brachial artery ④subclavian artery","options":["(A) ①②③④","(B) ②①③④","(C) ②③①④","(D) ④②①③"],"answer":1,"image":""},{"id":"md6-112-1-4","subject":"md6","topic":"麻醉-麻醉藥理","meta":"112年第1次第4題","year":112,"session":1,"number":4,"question":"下列有關鴉片類藥物（opioids）的敘述，何者錯誤？","options":["(A) opioids會導致細胞膜過極化（hyperpolarization）","(B) opioids啟動鈣離子通道，並抑制鉀離子通道","(C) endorphins是結合opioid受體的內源性肽（endogenous peptides）","(D) fentanyl的低分子量和高脂溶性有利其經皮吸收（transdermal absorption）"],"answer":1,"image":""},{"id":"md6-112-1-5","subject":"md6","topic":"麻醉-麻醉藥理","meta":"112年第1次第5題","year":112,"session":1,"number":5,"question":"下列有關靜脈麻醉劑（intravenous anesthetics）的敘述，何者錯誤？","options":["(A) barbiturates可收縮腦血管，使腦血流減少","(B) benzodiazepine可能導致呼吸停止","(C) ketamine可降低動脈血壓和心率","(D) etomidate會抑制腎上腺皮質"],"answer":2,"image":""},{"id":"md6-112-1-6","subject":"md6","topic":"麻醉-麻醉藥理","meta":"112年第1次第6題","year":112,"session":1,"number":6,"question":"下列那一種藥物對呼吸的抑制最少？","options":["(A) thiopental","(B) fentanyl","(C) ketamine","(D) propofol"],"answer":2,"image":""},{"id":"md6-112-1-7","subject":"md6","topic":"麻醉-特殊麻醉與疼痛","meta":"112年第1次第7題","year":112,"session":1,"number":7,"question":"有關脊椎麻醉阻斷皮節高度的影響因素，下列何者錯誤？","options":["(A) 局部麻醉藥劑之比重為影響因素之一","(B) 局部麻醉藥之劑量與體積為影響因素之一","(C) 病人姿勢為影響因素之一","(D) 肥胖病患對脊椎麻醉阻斷皮節高度無影響"],"answer":3,"image":""},{"id":"md6-112-1-8","subject":"md6","topic":"麻醉-特殊麻醉與疼痛","meta":"112年第1次第8題","year":112,"session":1,"number":8,"question":"下列有關enhanced recovery after surgery（ERAS）多模式止痛（multimodal analgesia）的敘述，何者錯誤？","options":["(A) 合併使用nonsteroidal antiinflammatory drugs（NSAIDs）可能造成腎功能損害","(B) 使用patient-controlled analgesia可提高病患滿意度","(C) 儘量不使用peripheral nerve blockade，以加速病患恢復及提早出院","(D) 即使是腸胃道手術，也儘可能不置放鼻胃管"],"answer":2,"image":""},{"id":"md6-112-1-9","subject":"md6","topic":"麻醉-特殊麻醉與疼痛","meta":"112年第1次第9題","year":112,"session":1,"number":9,"question":"70歲男性，體重70公斤，經急診診斷肺炎，在下午時段住進加護病房時意識改變，血壓80/40 mmHg，心跳110次／分鐘，體溫38.4℃。白班的醫師已經給與靜脈輸液3000毫升，銜接夜班時病人的血壓為90/45 mmHg，心跳95次／分鐘，夜班醫師正在考慮是否給與升血壓藥物。此時病人的狀態，應診斷為下列何者？","options":["(A) 全身性炎症反應症候群（systemic inflammatory response syndrome）","(B) 敗血症（sepsis）","(C) 嚴重敗血症（severe sepsis）","(D) 敗血性休克（septic shock）"],"answer":3,"image":""},{"id":"md6-112-1-10","subject":"md6","topic":"眼科-視網膜葡萄膜","meta":"112年第1次第10題","year":112,"session":1,"number":10,"question":"有關僵直性脊椎炎（ankylosing spondylitis）相關的葡萄膜炎，下列敘述何者錯誤？","options":["(A) 多以全葡萄膜炎呈現，患者會有紅眼、畏光、不適等症狀","(B) 常見於男性","(C) 患者human leukocyte antigen（HLA）-B27的基因檢查通常為陽性","(D) 雖然與系統疾病相關，發作時通常以單眼發作為主"],"answer":0,"image":""},{"id":"md6-112-1-11","subject":"md6","topic":"眼科-視網膜葡萄膜","meta":"112年第1次第11題","year":112,"session":1,"number":11,"question":"依此眼底照片顯示，病人最有可能是下列何種診斷？","options":["(A) 增殖性糖尿病視網膜病變（proliferative diabetic retinopathy）","(B) 重度非增殖性糖尿病視網膜病變（severe nonproliferative diabetic retinopathy）","(C) 中度非增殖性糖尿病視網膜病變（moderate nonproliferative diabetic retinopathy）","(D) 輕度非增殖性糖尿病視網膜病變（mild nonproliferative diabetic retinopathy）"],"answer":0,"image":"md6-112-1-11.jpeg"},{"id":"md6-112-1-12","subject":"md6","topic":"眼科-屈光斜弱視","meta":"112年第1次第12題","year":112,"session":1,"number":12,"question":"有關矯正與治療近視的方法，下列何者錯誤？","options":["(A) 以縮瞳劑治療假性近視","(B) 配戴眼鏡","(C) 近視雷射手術","(D) 若合併不規則散光，可配戴硬式隱形眼鏡矯正"],"answer":0,"image":""},{"id":"md6-112-1-13","subject":"md6","topic":"眼科-角膜結膜眼瞼眼窩","meta":"112年第1次第13題","year":112,"session":1,"number":13,"question":"有關造成角膜緣幹細胞缺乏症（limbal stem cell deficiency, LSCD）的原因，下列何者錯誤？","options":["(A) 化學藥物灼傷（chemical injury）","(B) 謝格連氏症候群（Sjögren syndrome）","(C) 史蒂芬斯－強森症候群（Stevens-Johnson syndrome）","(D) 長期配戴隱形眼鏡"],"answer":1,"image":""},{"id":"md6-112-1-14","subject":"md6","topic":"眼科-水晶體青光眼","meta":"112年第1次第14題","year":112,"session":1,"number":14,"question":"隅角鏡檢（gonioscopy）是分辨青光眼種類的重要檢查，下列何種房角的結構一定不會出現在隅角閉鎖性青光眼（angle-closure glaucoma）的患者的隅角鏡檢？","options":["(A) 施瓦布線（Schwalbe line）","(B) 小樑網組織（trabeculum）","(C) 周邊前沾黏（peripheral anterior synechiae）","(D) 睫狀體（ciliary body）"],"answer":3,"image":""},{"id":"md6-112-1-15","subject":"md6","topic":"眼科-水晶體青光眼","meta":"112年第1次第15題","year":112,"session":1,"number":15,"question":"眼壓（intraocular pressure）的高低和房水（aqueous humor）的形成及排出有關，下列敘述何者錯誤？","options":["(A) 房水的成分和血漿相近，但有較高濃度的維生素C及較低濃度的蛋白質","(B) 房水由睫狀體產生，經過後房、瞳孔邊緣，最後至前房角排出","(C) 睫狀肌的收縮與否會與房水排出的效能相關","(D) 房水排出後，最後會由淋巴系統回收"],"answer":3,"image":""},{"id":"md6-112-1-16","subject":"md6","topic":"眼科-角膜結膜眼瞼眼窩","meta":"112年第1次第16題","year":112,"session":1,"number":16,"question":"下列眼部病變何者不會同時出現複視與眼球突出的情況？","options":["(A) 急性眼窩外傷性血腫","(B) 重症肌無力","(C) 甲狀腺相關眼疾","(D) 眼窩尖端症候群（orbital apex syndrome）"],"answer":1,"image":""},{"id":"md6-112-1-17","subject":"md6","topic":"眼科-視網膜葡萄膜","meta":"112年第1次第17題","year":112,"session":1,"number":17,"question":"成人男性最常見轉移到眼內脈絡膜（choroid）的惡性腫瘤為何？","options":["(A) 肝癌","(B) 肺癌","(C) 胰臟癌","(D) 大腸癌"],"answer":1,"image":""},{"id":"md6-112-1-18","subject":"md6","topic":"眼科-角膜結膜眼瞼眼窩","meta":"112年第1次第18題","year":112,"session":1,"number":18,"question":"剛出生週歲前的嬰兒，淚水多且伴隨黃色黏稠分泌物，多積在內側眼角，下列敘述何者錯誤？","options":["(A) 最可能的診斷為先天性淚管阻塞","(B) 可以按摩小病人眼角內側的淚囊","(C) 必須立即進行鼻淚管手術","(D) 在一歲前進行淚管通條疏通未打開的淚管瓣膜"],"answer":2,"image":""},{"id":"md6-112-1-19","subject":"md6","topic":"耳科學","meta":"112年第1次第19題","year":112,"session":1,"number":19,"question":"有關內聽道（internal auditory canal）之敘述，下列何者正確？","options":["(A) 面神經位於內聽道之前上方","(B) 內聽道內有三條腦神經經過","(C) 聽神經位於內聽道之後下方","(D) 下前庭神經位於內聽道之前下方"],"answer":0,"image":""},{"id":"md6-112-1-20","subject":"md6","topic":"耳科學","meta":"112年第1次第20題","year":112,"session":1,"number":20,"question":"第一型鼓室成型術（Tympanoplasty type I）指的是：","options":["(A) 僅修補耳膜缺損而沒有改變聽小骨鏈","(B) 將修補的耳膜放在incus上","(C) 將修補的耳膜放在stapes上","(D) 將修補的耳膜放在stapes footplate上"],"answer":0,"image":""},{"id":"md6-112-1-21","subject":"md6","topic":"鼻科學","meta":"112年第1次第21題","year":112,"session":1,"number":21,"question":"下列何者不是急性細菌性鼻竇炎（acute bacterial rhinosinusitis）常見的致病菌？","options":["(A) 肺炎鏈球菌（Streptococcus pneumoniae）","(B) 綠膿桿菌（Pseudomonas aeruginosa）","(C) 流行性感冒嗜血桿菌（Haemophilus influenzae）","(D) 卡他莫拉菌（Moraxella catarrhalis）"],"answer":1,"image":""},{"id":"md6-112-1-22","subject":"md6","topic":"鼻科學","meta":"112年第1次第22題","year":112,"session":1,"number":22,"question":"有關慢性鼻竇炎無合併鼻息肉（chronic rhinosinusitis without nasal polyps）的致病原因，下列敘述何者錯誤？","options":["(A) 耳咽管功能異常（Eustachian tube dysfunction）","(B) 解剖問題（anatomic factors）","(C) 黏液纖毛功能障礙（mucociliary dysfunction）","(D) 骨性發炎（bone inflammation）"],"answer":0,"image":""},{"id":"md6-112-1-23","subject":"md6","topic":"喉科學與頭頸腫瘤","meta":"112年第1次第23題","year":112,"session":1,"number":23,"question":"有關食道異物的敘述，下列何者錯誤？","options":["(A) 側頸部X光影像，最可能有異物存在的徵象是linear opacity","(B) 根據案例的流行病學統計，食道異物最容易卡在中段食道（胸腔部位主動脈繞過食道處）","(C) 食道異物經軟式或硬式內視鏡取出後，都必須再進行第二次探查（second look）","(D) 誤食鈕扣電池（button battery）必須緊急進行食道鏡手術移除，因短時間內，食道黏膜就會受損，可能導致食道穿孔"],"answer":1,"image":""},{"id":"md6-112-1-24","subject":"md6","topic":"喉科學與頭頸腫瘤","meta":"112年第1次第24題","year":112,"session":1,"number":24,"question":"有關兒童甲狀腺癌，下列敘述何者錯誤？","options":["(A) 女性比例較高","(B) 與放射性物質暴露有關","(C) 兒童甲狀腺腫瘤之惡性比例較成人為高","(D) 最常見的惡性腫瘤病理為濾泡性腺癌（follicular adenocarcinoma）"],"answer":3,"image":""},{"id":"md6-112-1-25","subject":"md6","topic":"喉科學與頭頸腫瘤","meta":"112年第1次第25題","year":112,"session":1,"number":25,"question":"關於惡性唾液腺腺樣囊狀癌（adenoid cystic carcinoma），下列敘述何者錯誤？","options":["(A) 有cribriform、tubular或solid三種不同類型，以cribriform型預後最差","(B) 有強烈的親神經性（neurotropism），容易沿著神經擴散","(C) 遠端轉移是治療失敗常見的原因","(D) 出現遠端轉移後，部分病人疾病進程緩慢，仍可存活數年"],"answer":0,"image":""},{"id":"md6-112-1-26","subject":"md6","topic":"喉科學與頭頸腫瘤","meta":"112年第1次第26題","year":112,"session":1,"number":26,"question":"有關Warthin tumor（papillary cystadenoma lymphomatosum），下列敘述何者正確？","options":["(A) 多發生於女性","(B) 多發生於年輕者","(C) 多發生於腮腺尾端","(D) 是惡性腫瘤"],"answer":2,"image":""},{"id":"md6-112-1-27","subject":"md6","topic":"喉科學與頭頸腫瘤","meta":"112年第1次第27題","year":112,"session":1,"number":27,"question":"下列何者是鼻咽癌最常見的症狀？","options":["(A) 單側性流鼻血","(B) 聽力損失及耳鳴","(C) 面神經麻痺","(D) 頸部腫塊"],"answer":3,"image":""},{"id":"md6-112-1-28","subject":"md6","topic":"產科-一般產科","meta":"112年第1次第28題","year":112,"session":1,"number":28,"question":"懷孕期間下列何者的變化視為正常的生理現象？","options":["(A) serum creatinine上升","(B) thyroid-binding globulin上升","(C) hematocrit上升","(D) hair loss增加"],"answer":1,"image":""},{"id":"md6-112-1-29","subject":"md6","topic":"產科-一般產科","meta":"112年第1次第29題","year":112,"session":1,"number":29,"question":"關於妊娠組織之抗張強度（tensile strength），下列何組織表現最強？","options":["(A) 蛻膜（decidua）","(B) 羊膜（amnion）","(C) 絨毛膜（chorion）","(D) 合體滋養層（syncytiotrophoblast layer）"],"answer":1,"image":""},{"id":"md6-112-1-30","subject":"md6","topic":"產科-一般產科","meta":"112年第1次第30題","year":112,"session":1,"number":30,"question":"臨床上一般孕婦產檢時，最早大約在妊娠幾週後可由下腹部以杜卜勒（Doppler）胎心音監測器聽到胎兒心跳聲？","options":["(A) 4～5週","(B) 7～8週","(C) 11～12週","(D) 15～16週"],"answer":2,"image":""},{"id":"md6-112-1-31","subject":"md6","topic":"產科-一般產科","meta":"112年第1次第31題","year":112,"session":1,"number":31,"question":"懷孕時補充葉酸（folic acid）來預防胎兒神經管缺損最好在胚胎神經管關閉之前效果較好，因此最好在以最後月經日期（LMP）計算之妊娠週數幾週之前？","options":["(A) 6週","(B) 11週","(C) 15週","(D) 18週"],"answer":0,"image":""},{"id":"md6-112-1-32","subject":"md6","topic":"產科-一般產科","meta":"112年第1次第32題","year":112,"session":1,"number":32,"question":"關於胎兒呼吸（respiration）之敘述，下列何者錯誤？","options":["(A) 胎兒呼吸於吸氣（inspiration）時胸壁會下塌（collapses），腹部膨出（protrudes）","(B) 胎兒呼吸頻率缺氧（hypoxia）時會下降","(C) 胎兒呼吸頻率隨妊娠週數（gestational age）胎兒成熟而降低","(D) 胎兒呼吸頻率不會受母親進食（meal）影響"],"answer":3,"image":""},{"id":"md6-112-1-33","subject":"md6","topic":"產科-一般產科","meta":"112年第1次第33題","year":112,"session":1,"number":33,"question":"陰道內診時評估胎兒station為0的基準點是下列何者？","options":["(A) ischial spine","(B) iliac spine","(C) pubic symphysis","(D) acetabulum"],"answer":0,"image":""},{"id":"md6-112-1-34","subject":"md6","topic":"產科-一般產科","meta":"112年第1次第34題","year":112,"session":1,"number":34,"question":"有關產後發生子宮感染（uterine infection），下列那一項是最可能的風險因子（risk factor）？","options":["(A) 生產方式（route of delivery）","(B) 使用子宮內胎心音監視器（use of internal fetal monitors）","(C) 人工破水（artificial rupture of membranes）","(D) 乙型鏈球菌定植（group B streptococcus colonization）"],"answer":0,"image":""},{"id":"md6-112-1-35","subject":"md6","topic":"產科-高危險妊娠","meta":"112年第1次第35題","year":112,"session":1,"number":35,"question":"有關過期妊娠（postterm pregnancy）對母體產生的風險（maternal risks），下列何者較不可能出現？","options":["(A) 子癇前症（preeclampsia）","(B) 病態附著的胎盤（morbidly adherent placenta）","(C) 產後出血（postpartum hemorrhage）","(D) 會陰裂傷（perineal lacerations）"],"answer":1,"image":""},{"id":"md6-112-1-36","subject":"md6","topic":"產科-一般產科","meta":"112年第1次第36題","year":112,"session":1,"number":36,"question":"關於分娩時期的presentation，下圖為何？","options":["(A) complicated presentation","(B) neglected presentation","(C) brow presentation","(D) compound presentation"],"answer":3,"image":"md6-112-1-36.jpeg"},{"id":"md6-112-1-37","subject":"md6","topic":"產科-高危險妊娠","meta":"112年第1次第37題","year":112,"session":1,"number":37,"question":"嚴重子癇前症孕婦相較於正常孕婦，下列何者不是其特點？","options":["(A) 高血容量（hypervolemia）","(B) 血液濃縮（hemoconcentration）","(C) 血管收縮（vasospasm）","(D) 血管內皮損傷（endothelial damage）"],"answer":0,"image":""},{"id":"md6-112-1-38","subject":"md6","topic":"產科-高危險妊娠","meta":"112年第1次第38題","year":112,"session":1,"number":38,"question":"懷孕期間，孕婦感染巨細胞病毒（cytomegalovirus, CMV），在此次懷孕的那段時期最容易透過垂直傳播（vertical transmission）途徑導致子宮內胎兒CMV感染？","options":["(A) 早孕期（first trimester）","(B) 中孕期（second trimester）","(C) 晚孕期（third trimester）","(D) 三個孕期有相同的傳播率"],"answer":2,"image":""},{"id":"md6-112-1-39","subject":"md6","topic":"產科-高危險妊娠","meta":"112年第1次第39題","year":112,"session":1,"number":39,"question":"妊娠期合併全身性紅斑性狼瘡（systemic lupus erythematosus, SLE）導致新生兒狼瘡（neonatal lupus syndrome）的最主要相關性自體免疫抗體為：","options":["(A) 抗Ro抗體（Anti-Ro (SS-A)）","(B) 抗血小板抗體（Antiplatelet）","(C) 抗Sm抗體（Anti-Sm (Smith)）","(D) 抗磷脂抗體（Antiphospholipid）"],"answer":0,"image":""},{"id":"md6-112-1-40","subject":"md6","topic":"麻醉-呼吸道與監視","meta":"112年第1次第40題","year":112,"session":1,"number":40,"question":"腹腔鏡手術過程中，需於患者腹腔內充入二氧化碳（carbon dioxide）以提供手術中之操作空間，下列何者不是二氧化碳氣體栓塞（carbon dioxide embolus）併發症之症狀？","options":["(A) hypertension","(B) cardiac arrhythmia","(C) pulmonary edema","(D) heart murmurs"],"answer":0,"image":""},{"id":"md6-112-1-41","subject":"md6","topic":"婦科-良性腫瘤與內膜異位","meta":"112年第1次第41題","year":112,"session":1,"number":41,"question":"下列何者是腹骨盆腔子宮內膜異位症的確診方法？","options":["(A) 腹腔鏡檢查","(B) 臨床症狀","(C) 婦科超音波","(D) 核磁共振"],"answer":0,"image":""},{"id":"md6-112-1-42","subject":"md6","topic":"婦科-腫瘤","meta":"112年第1次第42題","year":112,"session":1,"number":42,"question":"Turner syndrome患者的染色體核型（karyotype）發現有Y染色體認為與生殖母細胞瘤（gonadoblastoma）的風險增加有關，下列敘述何者最不適當？","options":["(A) 屬於不具轉移潛力的良性腫瘤","(B) 此類生殖母細胞瘤可能自具有部分Y染色體的性腺中生成","(C) 此類生殖母細胞瘤可能是無性胚胎瘤（dysgerminomas）、胚胎性癌（embryonal carcinomas）或內胚竇層瘤（endodermal sinus tumors）的前兆","(D) 若發現存在Y染色體，建議在成年後進行預防性性腺切除，以減低惡性腫瘤的風險"],"answer":3,"image":""},{"id":"md6-112-1-43","subject":"md6","topic":"婦科-腫瘤","meta":"112年第1次第43題","year":112,"session":1,"number":43,"question":"關於骨盆腔腫瘤的處置原則，下列敘述何者最不適當？","options":["(A) 30歲婦女發現5公分的卵巢囊腫，建議定期超音波追蹤","(B) 30歲婦女發現10公分的卵巢囊腫，建議進行手術處置","(C) 60歲婦女發現5公分的卵巢囊腫，建議定期超音波追蹤","(D) 60歲婦女發現10公分的卵巢囊腫，建議進行手術處置"],"answer":2,"image":""},{"id":"md6-112-1-44","subject":"md6","topic":"婦科-手術學與診斷技術","meta":"112年第1次第44題","year":112,"session":1,"number":44,"question":"對於腹腔鏡在婦科手術的應用，下列敘述何者最不適當？","options":["(A) 與剖腹手術相比，腹腔鏡手術有住院天期短，疼痛較輕，恢復較快的優勢","(B) 大部分輸卵管上的子宮外孕，都可以用腹腔鏡手術處理","(C) 卵巢腫瘤使用腹腔鏡手術，應謹慎評估其惡性風險，必要時將腫瘤於腹腔中完整置入標本袋後再取出","(D) 子宮肌瘤因有惡性肉瘤的風險，宜用剖腹手術，不適合用腹腔鏡手術"],"answer":3,"image":""},{"id":"md6-112-1-45","subject":"md6","topic":"婦科-手術學與診斷技術","meta":"112年第1次第45題","year":112,"session":1,"number":45,"question":"有關腹腔鏡手術的準備，確認導氣針（insufflation needle; Veress needle）安全進入腹膜腔，下列何者錯誤？","options":["(A) 比較瘦的病人，進針角度應比較斜，與脊椎水平約成45度，減少傷及後腹腔血管的風險","(B) 如使用Veress needle，有“click”的聲響，通常表示進入腹膜腔","(C) 進入腹膜腔的壓力顯示，一般在10～15 mmHg","(D) 輕壓劍突軟骨，可見腹內壓力增加可以作為進入腹膜腔的檢測方式"],"answer":2,"image":""},{"id":"md6-112-1-46","subject":"md6","topic":"婦科-生殖內分泌","meta":"112年第1次第46題","year":112,"session":1,"number":46,"question":"關於真性陰陽人（true hermaphroditism），下列何者錯誤？","options":["(A) 同時具有卵巢組織與睪丸組織","(B) 如果有單側卵巢，則會有該側的單角子宮與輸卵管","(C) 有Y染色體","(D) 不可能有卵巢組織與睪丸組織混雜在一起的狀況"],"answer":3,"image":""},{"id":"md6-112-1-47","subject":"md6","topic":"婦科-生殖道感染與先天異常","meta":"112年第1次第47題","year":112,"session":1,"number":47,"question":"複雜性外陰陰道念珠菌（complicated vulvovaginal candidiasis）感染，通常不具有下列那一個特徵？","options":["(A) 反覆出現不適的症狀","(B) 症狀嚴重","(C) 大多為白色念珠菌（Candida albicans）感染","(D) 免疫功能不全"],"answer":2,"image":""},{"id":"md6-112-1-48","subject":"md6","topic":"婦科-腫瘤","meta":"112年第1次第48題","year":112,"session":1,"number":48,"question":"有關子宮肌瘤的敘述，下列何者錯誤？","options":["(A) 口服避孕藥與子宮肌瘤的產生有密不可分的關係","(B) 有子宮肌瘤的病人，一等親罹患子宮肌瘤的機會比較高","(C) 生長快速的子宮肌瘤，在停經前的婦女，未必就是惡性肉瘤（sarcoma）","(D) 黏膜下的肌瘤（submucosal myoma）較會影響生育"],"answer":0,"image":""},{"id":"md6-112-1-49","subject":"md6","topic":"婦科-腫瘤","meta":"112年第1次第49題","year":112,"session":1,"number":49,"question":"有關卵巢畸胎瘤（teratoma）的敘述，下列何者正確？","options":["(A) 通常發生在青少年期，未成熟畸胎瘤（immature teratoma）若發生在孩童，預後會較差","(B) 成熟畸胎瘤（mature teratoma）是良性腫瘤，但偶而會出現體細胞惡性變化，其中以adenocarcinoma最常見","(C) 單純的未成熟畸胎瘤（immature teratoma）沒有適當的血清腫瘤指標，除非是mixed germ cell tumor出現","(D) 卵巢未成熟畸胎瘤（immature teratoma）有時會出現腹腔神經膠質瘤病（gliomatosis peritonei），這是惡性度高的轉移病灶，預後差"],"answer":2,"image":""},{"id":"md6-112-1-50","subject":"md6","topic":"婦科-腫瘤","meta":"112年第1次第50題","year":112,"session":1,"number":50,"question":"關於子宮內膜癌，下列敘述何者最正確？","options":["(A) 子宮內膜複雜性增生會增加癌症的發生率","(B) 黃體素治療是目前子宮內膜癌標準治療","(C) 子宮內膜癌患者接受腹腔鏡分期手術治療後，預後較傳統手術好","(D) 臨床上病人因子宮異常出血利用子宮鏡檢查是標準流程"],"answer":0,"image":""},{"id":"md6-112-1-51","subject":"md6","topic":"婦科-腫瘤","meta":"112年第1次第51題","year":112,"session":1,"number":51,"question":"早期子宮頸癌病患（IA2-IIA）接受子宮根除術及骨盆腔淋巴結切除術（radical hysterectomy and pelvic lymphadenectomy），依據病理檢查結果將復發之風險因子分為中度風險因子（intermediate risk factors）及高度風險因子（high risk factors），下列何者屬於高度風險因子？","options":["(A) 子宮旁組織顯微侵犯（microscopic parametrial involvement）","(B) 大腫瘤（large tumor size）","(C) 子宮頸間質侵犯深度到達外三分之一（stromal invasion to the deep one-third）","(D) 淋巴血管浸潤（lymph-vascular space invasion）"],"answer":0,"image":""},{"id":"md6-112-1-52","subject":"md6","topic":"婦科-腫瘤","meta":"112年第1次第52題","year":112,"session":1,"number":52,"question":"下列何者不是子宮內膜癌復發的高危險因子？","options":["(A) 子宮肌肉層侵犯深度＞1/2","(B) 細胞分化程度為grade 1","(C) 有淋巴血管侵襲（lymph-vascular space invasion）","(D) 骨盆淋巴結轉移（pelvic lymph node metastasis）"],"answer":1,"image":""},{"id":"md6-112-1-53","subject":"md6","topic":"婦科-腫瘤","meta":"112年第1次第53題","year":112,"session":1,"number":53,"question":"關於子宮頸癌前病變，下列敘述何者錯誤？","options":["(A) cervical intraepithelial neoplasia（CIN）最常見發生在子宮頸squamocolumnar junction","(B) 大部分CIN1子宮頸癌前病變不治療也會自行痊癒","(C) 人類乳突病毒感染為子宮頸癌前病變最重要的危險因子","(D) 施打子宮頸癌疫苗後，可以不用再做子宮頸抹片檢查"],"answer":3,"image":""},{"id":"md6-112-1-54","subject":"md6","topic":"婦科-生殖內分泌","meta":"112年第1次第54題","year":112,"session":1,"number":54,"question":"關於青春期之陰道異常出血，下列敘述何者錯誤？","options":["(A) 月經來潮之間隔在21～45天算是正常的","(B) 初經來潮後的第一年，月經間隔超過三個月仍可算是正常的","(C) 除了不排卵之外，鑑别診斷的項目包括懷孕相關之出血及使用避孕藥物造成之出血","(D) 異常出血也有可能是披衣菌等造成性傳染疾病所導致"],"answer":1,"image":""},{"id":"md6-112-1-55","subject":"md6","topic":"婦科-生殖內分泌","meta":"112年第1次第55題","year":112,"session":1,"number":55,"question":"有關卵巢濾泡生長的敘述，下列何者正確？","options":["(A) 卵巢濾泡生長至1公分後顆粒細胞分泌抗穆勒氏管荷爾蒙（AMH）抑制成熟濾泡的生長","(B) 在黃體期卵巢濾泡主要生成抑制素B（inhibin B），抑制腦下垂體分泌濾泡刺激素（FSH）","(C) 臨床上會使用人類絨毛膜刺激激素（hCG）在卵巢濾泡生長至1.3公分時代替促黃體激素（LH）高峰誘發排卵","(D) 臨床上會在人類絨毛膜刺激激素（hCG）注射後約36小時取卵"],"answer":3,"image":""},{"id":"md6-112-1-56","subject":"md6","topic":"婦科-生殖內分泌","meta":"112年第1次第56題","year":112,"session":1,"number":56,"question":"下列何項檢查不適合用來評估育齡女性之卵巢庫存量（ovarian reserve）？","options":["(A) serum day 3 FSH","(B) serum day 3 LH","(C) serum anti-Müllerian hormone（AMH）","(D) antral follicle count（AFC）"],"answer":1,"image":""},{"id":"md6-112-1-57","subject":"md6","topic":"婦科-尿失禁與骨盆腔脫垂","meta":"112年第1次第57題","year":112,"session":1,"number":57,"question":"有關治療尿失禁的藥物，下列敘述何者正確？","options":["(A) 尿道和膀胱頸的張力受muscarinic receptor調控","(B) 根據WHI的研究，口服女性荷爾蒙及黃體素有助於尿失禁的改善","(C) 用DDAVP（arginine vasopressin）治療nocturnal enuresis有可能造成致命的hypernatremia","(D) 抗毒蕈鹼類的藥物是副交感神經的拮抗劑，可以用來治療急迫性尿失禁"],"answer":3,"image":""},{"id":"md6-112-1-58","subject":"md6","topic":"復健-神經復健","meta":"112年第1次第58題","year":112,"session":1,"number":58,"question":"病人會自創新詞（neologism），以致他人無法理解其言語內容，最有可能是下列那一類型的失語症？","options":["(A) 渥尼克失語症（Wernicke's aphasia）","(B) 布洛卡氏失語症（Broca's aphasia）","(C) 經皮質運動型失語症（transcortical motor aphasia）","(D) 經皮質感覺型失語症（transcortical sensory aphasia）"],"answer":0,"image":""},{"id":"md6-112-1-59","subject":"md6","topic":"復健-神經復健","meta":"112年第1次第59題","year":112,"session":1,"number":59,"question":"腦幹中風病人吞嚥反射消失，下列何種治療最合宜？","options":["(A) 溫度刺激（thermal stimulation）","(B) Shaker運動","(C) 曼德森手法（Mendelsohn maneuver）","(D) 環咽肌切開（myotomy）"],"answer":0,"image":""},{"id":"md6-112-1-60","subject":"md6","topic":"復健-神經復健","meta":"112年第1次第60題","year":112,"session":1,"number":60,"question":"有關頸脊髓損傷患者之睡眠呼吸障礙，下列敘述何者最不適當？","options":["(A) 病人夜眠經常中斷","(B) 以中樞性睡眠呼吸中止（central sleep apnea）為主要表現","(C) 2 BMI大於30 kg/m可能為致病因素之一","(D) 阻抗性吸氣肌訓練可改善四肢癱瘓者睡眠呼吸障礙"],"answer":1,"image":""},{"id":"md6-112-1-61","subject":"md6","topic":"復健-神經復健","meta":"112年第1次第61題","year":112,"session":1,"number":61,"question":"某病人因車禍就診，走路有足部下垂情形，最有可能是下列那一條神經受損？","options":["(A) 腓神經（peroneal nerve）","(B) 脛骨神經（tibial nerve）","(C) 股神經（femoral nerve）","(D) 隱神經（saphenous nerve）"],"answer":0,"image":""},{"id":"md6-112-1-62","subject":"md6","topic":"復健-骨骼肌肉損傷與疾患","meta":"112年第1次第62題","year":112,"session":1,"number":62,"question":"有關退化性關節炎（degenerative joint disease），下列敘述何者最不適當？","options":["(A) 致病因素包括高齡、長期負重、外傷、基因、肥胖等","(B) 臨床上可見下肢單一負重關節之骨性關節炎","(C) 髖關節之骨性關節炎機率遠高於膝關節炎","(D) 上肢多發性骨性關節炎，以大拇指之腕掌關節最會造成疼痛及影響手功能"],"answer":2,"image":""},{"id":"md6-112-1-63","subject":"md6","topic":"復健-骨骼肌肉損傷與疾患","meta":"112年第1次第63題","year":112,"session":1,"number":63,"question":"有關骨質疏鬆症（osteoporosis），下列敘述何者最不適當？","options":["(A) WHO依照骨質密度（bone mineral density, BMD）與骨折風險的關係，以Z值（Z-score）作為臨床診斷標準。Z值小於2.5即可診斷為骨質疏鬆症","(B) 骨骼的再塑（remodeling）過程主要由合成骨骼的造骨細胞（osteoblast）及溶蝕骨骼的蝕骨細胞（osteoclast）來達成","(C) 骨質疏鬆症本身並無症狀，但發生劇烈疼痛時要懷疑有骨折","(D) 骨鬆性骨折因病人對跌倒採用不同的防禦機轉而有不同的好發位置，常見部位為髖部（近端股骨）、脊椎及手腕"],"answer":0,"image":""},{"id":"md6-112-1-64","subject":"md6","topic":"復健-骨骼肌肉損傷與疾患","meta":"112年第1次第64題","year":112,"session":1,"number":64,"question":"膝關節前十字韌帶損傷為常見的運動傷害之一，下列敘述何者最適當？","options":["(A) 前十字韌帶的作用之一為限制脛骨相對於股骨之外旋","(B) 前十字韌帶損傷不一定需要手術治療","(C) 建議用超音波檢測前十字韌帶是否受傷","(D) 若需手術，一般建議受傷後一週內執行較適宜"],"answer":1,"image":""},{"id":"md6-112-1-65","subject":"md6","topic":"復健-心肺復健與運動處方","meta":"112年第1次第65題","year":112,"session":1,"number":65,"question":"針對心臟衰竭病人參加運動訓練的敘述，下列何者最為適當？","options":["(A) 心臟衰竭病人運動時，運動強度應設為最大攝氧量之80%較佳","(B) 經過運動訓練的心臟衰竭病人，左心室射出率往往可以有效提升10%以上","(C) 心臟衰竭病人接受8週的運動訓練期間，常常會發生嚴重併發症，甚至需要住院接受治療","(D) 接受運動訓練的心臟衰竭病人，可能可以改善運動功能，也可以減少死亡或住院"],"answer":3,"image":""},{"id":"md6-112-1-66","subject":"md6","topic":"復健-兒童與一般復健","meta":"112年第1次第66題","year":112,"session":1,"number":66,"question":"關於新生兒臂神經叢麻痺（neonatal brachial plexus palsy），下列敘述何者錯誤？","options":["(A) 典型的Erb's palsy常造成肩膀內轉（shoulder internally rotated）及手肘伸直（elbow extension）的姿態","(B) Klumpke's palsy是C8到T1脊髓神經所組成的臂神經叢傷害所造成","(C) Horner's syndrome常發生於Erb's palsy","(D) Erb's palsy之後可能發生肩盂肱骨關節發育不良（glenohumeral dysplasia）"],"answer":2,"image":""},{"id":"md6-112-1-67","subject":"md6","topic":"復健-兒童與一般復健","meta":"112年第1次第67題","year":112,"session":1,"number":67,"question":"關於各類型腦性麻痺（cerebral palsy），下列敘述何者最不適當？","options":["(A) 半邊麻痺型（hemiplegic type）通常發生於足月產嬰兒（term infants）","(B) 四肢麻痺型（quadriplegic type）通常有廣泛的腦病變（diffuse brain pathology）","(C) 雙邊麻痺型（diplegic type）通常有腦室周圍白質軟化症（periventricular leukomalacia）","(D) 相較於半邊麻痺型（hemiplegic type），癲癇（seizure）較常發生於雙邊麻痺型（diplegic type）"],"answer":3,"image":""},{"id":"md6-112-1-68","subject":"md6","topic":"復健-兒童與一般復健","meta":"112年第1次第68題","year":112,"session":1,"number":68,"question":"有關老化的特徵中，下列敘述何者最不適當？","options":["(A) 身體器官儲備能力降低","(B) 對於環境的反應力不良","(C) 體內穩定狀態不易改變","(D) 對於壓力的適應性變差"],"answer":2,"image":""},{"id":"md6-112-1-69","subject":"md6","topic":"復健-兒童與一般復健","meta":"112年第1次第69題","year":112,"session":1,"number":69,"question":"有關疼痛復健的敘述，下列何者最不適當？","options":["(A) 疼痛復健的原則如同一般復健，屬團隊合作模式","(B) 疼痛控制包含保守療法、針刺療法與手術療法等","(C) 若病人深受嚴重疼痛帶來的困擾，應優先選擇手術療法","(D) 適當的運動可增加體內的腦啡、解除內心壓力、減低疼痛"],"answer":2,"image":""},{"id":"md6-112-1-70","subject":"md6","topic":"復健-兒童與一般復健","meta":"112年第1次第70題","year":112,"session":1,"number":70,"question":"有關住家無障礙環境評估與介入之敘述，下列何者最不適當？","options":["(A) 需辨識在住宅中，妨礙或支持病人執行日常活動的環境因素","(B) 預防病人在住宅中意外的發生","(C) 增進病人、照護者的安全性、舒適性及生活品質","(D) 只有復健科醫師方可進行無障礙空間的評估"],"answer":3,"image":""},{"id":"md6-112-1-71","subject":"md6","topic":"復健-兒童與一般復健","meta":"112年第1次第71題","year":112,"session":1,"number":71,"question":"有關癌症本身造成失能的敘述，下列何者最適當？","options":["(A) 腫瘤伴生神經系統異常（paraneoplastic neurological disorders），被認為常與腫瘤誘發的內分泌異常相關","(B) 癌症轉移所造成的功能喪失，很少會出現心肺功能下降、肌力減弱等現象","(C) 功能儲備不佳的器官癌症，在早期就會出現失能症狀","(D) 肝癌早期很容易就造成身體功能嚴重失能"],"answer":2,"image":""},{"id":"md6-112-1-72","subject":"md6","topic":"婦科-生殖內分泌","meta":"112年第1次第72題","year":112,"session":1,"number":72,"question":"30歲已婚婦女在無避孕措施的性生活之下，想懷孕但經過18個月無懷孕跡象，下列相關影像檢查之敘述，何者最不恰當？","options":["(A) 應優先施行電腦斷層檢查","(B) 未注射顯影劑之經陰道超音波無法觀察輸卵管是否通暢","(C) 輸卵管攝影可觀察輸卵管是否通暢","(D) 磁振造影大多不適合做為篩檢工具"],"answer":0,"image":""},{"id":"md6-112-1-73","subject":"md6","topic":"耳科學","meta":"112年第1次第73題","year":112,"session":1,"number":73,"question":"48歲男性病人主訴最近二個月左側耳鳴，根據附圖MRI之影像，箭號所指最恰當的診斷為何？","options":["(A) acoustic neuroma","(B) 咽喉細菌感染引發acute mastoiditis","(C) nasopharyngeal carcinoma（NPC）with acute mastoiditis","(D) chronic otitis media（COM）"],"answer":2,"image":"md6-112-1-73.jpeg"},{"id":"md6-112-1-74","subject":"md6","topic":"喉科學與頭頸腫瘤","meta":"112年第1次第74題","year":112,"session":1,"number":74,"question":"65歲男性病人主訴右臉耳下部位無痛硬塊約2年，耳下腺超音波檢查如圖，最可能的診斷為何？","options":["(A) 耳下腺膿瘍（abscess）","(B) 耳下腺多形性腺瘤（pleomorphic adenoma）","(C) 耳下腺血管瘤（hemangioma）","(D) 耳下腺腺癌（adenocarcinoma）"],"answer":1,"image":"md6-112-1-74.jpeg"},{"id":"md6-112-1-75","subject":"md6","topic":"婦科-良性腫瘤與內膜異位","meta":"112年第1次第75題","year":112,"session":1,"number":75,"question":"24歲的女性，最後一次月經約5週前，今天因左下腹痛至急診，生命徵象穩定。實驗室檢查發現尿液妊娠定性試驗陽性、血球比容值測定（hematocrit）29%。骨盆超音波顯示子宮內無妊娠囊（gestational sac）、左側輸卵管腫塊、子宮直腸凹窩有中量積液。觀察中病人突然頭暈冒冷汗，血壓80/52 mmHg、心跳104/min。這位病人最合適的下一步治療為何？","options":["(A) 出院併安排三日後婦產科門診追蹤","(B) 口服葉酸拮抗藥物（methotrexate）","(C) 擇期安排腹腔鏡輸卵管造口術（laparoscopic salpingostomy）","(D) 輸血、安排緊急剖腹手術和輸卵管切除術（laparotomy and salpingectomy）"],"answer":3,"image":""},{"id":"md6-112-1-76","subject":"md6","topic":"麻醉-呼吸道與監視","meta":"112年第1次第76題","year":112,"session":1,"number":76,"question":"關於急診快速階段性氣管內管置放（rapid-sequence intubation）時藥物的使用，下列何者最不適當？","options":["(A) ketamine用於重積性氣喘（refractory status asthmaticus）的病人","(B) rocuronium用於重症肌無力的病人","(C) succinylcholine用於蜘蛛膜下腔出血的病人","(D) propofol用於低血容性休克的病人"],"answer":3,"image":""},{"id":"md6-112-1-77","subject":"md6","topic":"鼻科學","meta":"112年第1次第77題","year":112,"session":1,"number":77,"question":"有關流鼻血的敘述，下列何者最不適當？","options":["(A) 較常發生於乾燥的季節","(B) 前鼻腔出血較後鼻腔多","(C) 前鼻腔出血常來自sphenopalatine artery","(D) 較常發生於小於10歲的小孩或大於70歲的老年人"],"answer":2,"image":""},{"id":"md6-112-1-78","subject":"md6","topic":"婦科-良性腫瘤與內膜異位","meta":"112年第1次第78題","year":112,"session":1,"number":78,"question":"46歲病人育有兩子，近年來因為經血過多，多次到醫院急診室接受輸血治療，其超音波檢查發現有一個2公分的type 1子宮內膜下肌瘤，下列臨床建議何者最適宜？","options":["(A) 因接近更年期，考量繼續保守治療及鐵劑補充","(B) 因育有兩子可建議作全子宮切除","(C) 可以執行子宮腔鏡子宮肌瘤切除手術改善貧血問題","(D) 可以執行腹腔鏡式子宮肌瘤切除手術改善貧血問題"],"answer":2,"image":""},{"id":"md6-112-1-79","subject":"md6","topic":"醫學倫理與法規","meta":"112年第1次第79題","year":112,"session":1,"number":79,"question":"下列那一個行為違反了醫療人員應有的保密義務或無故侵犯病人的隱私？①一位年輕女性進入急診室並聲稱其剛遭受強姦，要求進行骨盆檢查並要求給事後避孕丸，但她卻堅持不要報警。醫療人員仍然通報這個事件 ②一位年輕的父親抱著他的小孩進入急診室並要求醫師為小孩治療受傷的手臂。這個小孩是醫院的常客，對於這樣的傷口父親總是說是她騎腳踏車跌倒受傷的。小孩並沒有露出害怕父親的表情，也同意父親的說法。醫療人員通報為疑似兒童虐待案件 ③小兒科實習醫師，注意到鄰居住進外科病房，在探望她之前看了她的病歷 ④住院醫師巡房時發現同教區的教友剛完成墮胎手術，便將此事告訴教區牧師","options":["(A) ①②","(B) 僅①④","(C) ①③④","(D) 僅③④"],"answer":3,"image":""},{"id":"md6-112-1-80","subject":"md6","topic":"醫學倫理與法規","meta":"112年第1次第80題","year":112,"session":1,"number":80,"question":"中風長期坐輪椅的72歲老爺爺因嗆到食物造成窒息被送到急診，老爺爺除了高血壓外，還有糖尿病，孫女要求急診醫師不要對爺爺施予急救，因為爺爺先前在A醫院簽署過DNR，醫師適當的處置為何？","options":["(A) 應逕行進行急救，因未經判定屬末期病人","(B) 同意孫女所請，請孫女填寫切結書後，放棄急救病人","(C) 聯絡A醫院，請其傳真病人的DNR意願書，以決定是否該施予急救","(D) 因病人長期有慢性病並行動困難，應考慮不予急救"],"answer":0,"image":""},{"id":"md6-112-2-1","subject":"md6","topic":"麻醉-呼吸道與監視","meta":"112年第2次第1題","year":112,"session":2,"number":1,"question":"下列何者為麻醉誘導後施行面罩通氣困難（difficult mask ventilation）最可能之預測因子？","options":["(A) 有大量鬍鬚之男性","(B) 青少年","(C) 2身體質量指數（Body Mass Index）小於20 kg/m","(D) Mallampati classification II"],"answer":0,"image":""},{"id":"md6-112-2-2","subject":"md6","topic":"麻醉-呼吸道與監視","meta":"112年第2次第2題","year":112,"session":2,"number":2,"question":"要抽血檢測混合靜脈氧飽和度（mixed venous blood oxygen saturation, SvO2），應從何處抽取較精確？","options":["(A) 外頸靜脈（external jugular vein）","(B) 橈動脈導管（radial artery catheter）","(C) 中央靜脈導管（central venous catheter）","(D) 肺動脈導管（pulmonary artery catheter）"],"answer":3,"image":""},{"id":"md6-112-2-3","subject":"md6","topic":"麻醉-呼吸道與監視","meta":"112年第2次第3題","year":112,"session":2,"number":3,"question":"關於手術中麻醉呼吸功能的基礎監測，下列敘述何者錯誤？","options":["(A) 呼吸監測必須包含氧合（oxygenation）與換氣（ventilation）","(B) Pulse oximetry是必要的呼吸監測項目","(C) Capnography可以監測ventilation，包含確認氣管內管（endotracheal tube）的位置","(D) 潮氣末二氧化碳（end-tidal CO2）與動脈血CO2分壓有固定的差距，其可以完全反應動脈血CO2分壓的變化"],"answer":3,"image":""},{"id":"md6-112-2-4","subject":"md6","topic":"麻醉-麻醉藥理","meta":"112年第2次第4題","year":112,"session":2,"number":4,"question":"下列有關局部麻醉劑（local anesthetics）的敘述，何者錯誤？","options":["(A) amide類局部麻醉劑主要經由血液中偽膽鹼酯酶（pseudocholinesterase）代謝","(B) 其全身吸收率（systemic absorption）與注射部位的血管豐富性（vascularity）有關","(C) 非離子化（nonionized）局部麻醉劑的相對濃度可能會影響其起始作用（onset）的快慢","(D) 意外注射bupivacaine於血管中，可導致嚴重心臟毒性"],"answer":0,"image":""},{"id":"md6-112-2-5","subject":"md6","topic":"麻醉-麻醉藥理","meta":"112年第2次第5題","year":112,"session":2,"number":5,"question":"下列有關鴉片類藥物（opioids）的敘述，何者錯誤？","options":["(A) 在肝衰竭患者中，嗎啡代謝物的積累可能導致昏迷和呼吸抑制","(B) 快速施打大劑量opioids可引起胸壁僵硬（chest wall rigidity）","(C) opioids的長期使用可能產生痛覺減退（hypoalgesia）","(D) 大劑量的opioids可以抑制手術引起的catecholamine上升"],"answer":2,"image":""},{"id":"md6-112-2-6","subject":"md6","topic":"產科-高危險妊娠","meta":"112年第2次第6題","year":112,"session":2,"number":6,"question":"懷孕25週婦女因闌尾炎須進行腹腔鏡手術，下列有關手術與全身麻醉處置之敘述，何者錯誤？","options":["(A) 術中可以用permissive hypercapnia原則來維持麻醉","(B) 腹腔鏡手術的氣腹（pneumoperitoneum）壓力盡量不要太高","(C) 避免過度頭低腳高或頭高腳低的姿勢","(D) 術中宜監測胎心音（monitor fetal heart rate）"],"answer":0,"image":""},{"id":"md6-112-2-7","subject":"md6","topic":"產科-一般產科","meta":"112年第2次第7題","year":112,"session":2,"number":7,"question":"有關產婦硬脊膜外止痛（labor epidural analgesia），下列敘述何者錯誤？","options":["(A) 硬脊膜外止痛（epidural analgesia）在第一產程階段，主要是作用於T10-L1 level","(B) epidural analgesia是常用有效的方式，必須等到子宮頸口開3cm以上才能施打，以免造成第一產程延長或增加剖腹產率","(C) 持續使用於第二產程可能會延長第二產程","(D) 完成硬脊膜外導管（epidural catheter）置放後，可先給予test dose，以確認導管沒有移位至脊髓腔內"],"answer":1,"image":""},{"id":"md6-112-2-8","subject":"md6","topic":"麻醉-特殊麻醉與疼痛","meta":"112年第2次第8題","year":112,"session":2,"number":8,"question":"下列何種鴉片類藥物與給藥途徑並不適合作為癌症疼痛的長期用藥方式？","options":["(A) transdermal fentanyl","(B) oral morphine","(C) intravenous meperidine","(D) oral oxycodone"],"answer":2,"image":""},{"id":"md6-112-2-9","subject":"md6","topic":"麻醉-呼吸道與監視","meta":"112年第2次第9題","year":112,"session":2,"number":9,"question":"急性呼吸窘迫症候群（acute respiratory distress syndrome, ARDS）之診斷條件，根據柏林定義（Berlin definition），下列何者正確？","options":["(A) 一週內發生的臨床事件或新的／惡化的呼吸症狀","(B) PaO2/FiO2 ≤300，屬於重度ARDS","(C) 初期常合併有左心室衰竭及擴大","(D) 胸部X光通常呈現單側肺浸潤，尤其是左側，因心臟擴大而受到壓迫"],"answer":0,"image":""},{"id":"md6-112-2-10","subject":"md6","topic":"眼科-視網膜葡萄膜","meta":"112年第2次第10題","year":112,"session":2,"number":10,"question":"光學共軛掃描儀（optical coherence tomography, OCT）臨床上主要用來檢查高度近視的許多視網膜併發症，下列何者除外？","options":["(A) 黃斑裂孔（macular hole）","(B) 格子狀退化（lattice degeneration）","(C) 脈絡膜新生血管（choroidal neovascularization）","(D) 葡萄腫（staphyloma）"],"answer":1,"image":""},{"id":"md6-112-2-11","subject":"md6","topic":"眼科-視網膜葡萄膜","meta":"112年第2次第11題","year":112,"session":2,"number":11,"question":"有關貝西氏症（Behçet disease）引起葡萄膜炎之敘述，下列何者錯誤？","options":["(A) 診斷標準為具雙眼葡萄膜炎，且合併human leukocyte antigen（HLA）-B51基因檢查陽性","(B) 可能合併的全身症狀包括口腔潰瘍、生殖器潰瘍及血管病灶（vascular lesions）等","(C) 產生的血管炎可以影響動脈或靜脈，眼底螢光血管攝影是一項有用的檢查工具","(D) 治療選項包括類固醇、免疫調節劑及生物製劑"],"answer":0,"image":""},{"id":"md6-112-2-12","subject":"md6","topic":"眼科-角膜結膜眼瞼眼窩","meta":"112年第2次第12題","year":112,"session":2,"number":12,"question":"一位三十餘歲男性主訴視力模糊及眩光，細隙燈檢查可見中間角膜基質之晶狀沉積物及角膜環（arcus）角膜病變（如下圖）。此類病患最可能懷疑血中何物質濃度增高？","options":["(A) 膽固醇","(B) 鈣離子","(C) 銅離子","(D) 同半胱胺酸（homocysteine）"],"answer":0,"image":"md6-112-2-12.jpeg"},{"id":"md6-112-2-13","subject":"md6","topic":"眼科-角膜結膜眼瞼眼窩","meta":"112年第2次第13題","year":112,"session":2,"number":13,"question":"有關角膜的內皮細胞層，下列敘述何者錯誤？","options":["(A) 內皮細胞具有適度的再生能力","(B) 內皮細胞具有屏障（barrier）及脫水（pumping）功能，以維持角膜約78%的含水量","(C) 當外傷或手術造成內皮細胞傷害過度時，將可能造成角膜不可逆之水腫","(D) 不可逆之角膜水腫造成病人視力衰退時，可考慮以角膜移植治療"],"answer":[0,1,2,3],"image":"","answer_note":"送分:第13題一律給分 (原公告答案 A)"},{"id":"md6-112-2-14","subject":"md6","topic":"眼科-水晶體青光眼","meta":"112年第2次第14題","year":112,"session":2,"number":14,"question":"下列何種全身性疾病較不會合併白內障產生？","options":["(A) 糖尿病","(B) 強直性肌肉失養症（myotonic dystrophy）","(C) 異位性皮膚炎（atopic dermatitis）","(D) 葛瑞夫茲病（Graves' disease）"],"answer":3,"image":""},{"id":"md6-112-2-15","subject":"md6","topic":"眼科-視網膜葡萄膜","meta":"112年第2次第15題","year":112,"session":2,"number":15,"question":"三歲以下的小朋友，兩眼視網膜出血，沒有明顯的頭部外傷，要懷疑下列那一個疾病？","options":["(A) 第一型糖尿病（type I DM）","(B) 嬰兒搖晃症（shaken baby syndrome）","(C) 頑固型癲癇（intractable epilepsy）","(D) 幼年特發性關節炎合併之葡萄膜炎（juvenile idiopathic arthritis associated uveitis）"],"answer":1,"image":""},{"id":"md6-112-2-16","subject":"md6","topic":"眼科-屈光斜弱視","meta":"112年第2次第16題","year":112,"session":2,"number":16,"question":"幾個小病童第一次到眼科門診檢查，發現有下述的眼睛問題，則那一種眼疾造成弱視的可能性較小？","options":["(A) 間歇性交替性外斜視","(B) 單眼先天性白內障","(C) 兩眼視差五百度","(D) 兩眼遠視四百度"],"answer":0,"image":""},{"id":"md6-112-2-17","subject":"md6","topic":"眼科-水晶體青光眼","meta":"112年第2次第17題","year":112,"session":2,"number":17,"question":"長期口服或局部眼用類固醇藥物，可能在眼睛產生的副作用包括下列那些？①白內障（cataract） ②眼壓升高（elevation of intraocular pressure） ③中心性漿液性脈絡膜視網膜病變（central serous chorioretinopathy） ④視神經炎（optic neuritis）","options":["(A) ①②④","(B) ②③④","(C) ①③④","(D) ①②③"],"answer":3,"image":""},{"id":"md6-112-2-18","subject":"md6","topic":"眼科-角膜結膜眼瞼眼窩","meta":"112年第2次第18題","year":112,"session":2,"number":18,"question":"一位葛雷夫氏症（Graves' disease）患者，主訴有雙眼複視現象，下列敘述何者錯誤？","options":["(A) 造成複視最可能的原因為眼外肌增厚（hypertrophy）","(B) 最容易被侵犯的眼外肌為下直肌（inferior rectus muscle）","(C) 電腦斷層下的典型表現可見眼外肌腹（belly）和肌腱（tendon）處均呈現肥大變化","(D) 手術矯正斜視，須等待甲狀腺指數正常及斜視角度穩定至少半年"],"answer":2,"image":""},{"id":"md6-112-2-19","subject":"md6","topic":"耳科學","meta":"112年第2次第19題","year":112,"session":2,"number":19,"question":"有關聽神經瘤（acoustic neuroma）之症狀及聽力檢查結果，下列敘述何者最不適當？","options":["(A) 純音聽力檢查患側聽力變差","(B) 患側常有耳鳴","(C) 患側語音辨識度和健側相同","(D) 患側耳聽性腦幹反應（auditory brainstem response）第五波潛時（latency）會延長"],"answer":2,"image":""},{"id":"md6-112-2-20","subject":"md6","topic":"耳科學","meta":"112年第2次第20題","year":112,"session":2,"number":20,"question":"眩暈疾病中，下列何者最常合併聽力損失？","options":["(A) 良性陣發性姿勢性眩暈（BPPV）","(B) 前庭神經炎（vestibular neuritis）","(C) 梅尼爾氏症（Meniere's disease）","(D) 前庭性偏頭痛（vestibular migraine）"],"answer":2,"image":""},{"id":"md6-112-2-21","subject":"md6","topic":"鼻科學","meta":"112年第2次第21題","year":112,"session":2,"number":21,"question":"關於鼻竇的發育，下列敘述何者正確？","options":["(A) 額竇（frontal sinus）是最早開始氣化的鼻竇","(B) 出生後，篩竇小室（ethmoid cells）的數量就不再增加","(C) 上頜竇（maxillary sinus）的快速增長約在青春期","(D) 蝶竇（sphenoid sinus）是最晚開始發育且最晚完成的鼻竇"],"answer":[0,1,2,3],"image":"","answer_note":"送分:第21題一律給分 (原公告答案 B)"},{"id":"md6-112-2-22","subject":"md6","topic":"鼻科學","meta":"112年第2次第22題","year":112,"session":2,"number":22,"question":"有關過敏性鼻炎（allergic rhinitis）的理學檢查，下列現象何者正確？","options":["(A) 下眼瞼顏色反白","(B) 鼻尖上橫紋（transverse supratip nasal crease）","(C) 縮短的眼睫毛（shortened eyelashes）","(D) 上眼瞼出現皺褶（Dennie-Morgan folds）"],"answer":1,"image":""},{"id":"md6-112-2-23","subject":"md6","topic":"喉科學與頭頸腫瘤","meta":"112年第2次第23題","year":112,"session":2,"number":23,"question":"有關軟式及硬式喉內視鏡檢查，下列敘述何者錯誤？","options":["(A) 軟式喉內視鏡屬於間接（indirect）喉鏡檢查；硬式喉內視鏡則為直接（direct）喉鏡檢查","(B) 硬式喉內視鏡檢查大多需要在全身麻醉下於開刀房中進行；軟式喉內視鏡則可於局部麻醉或不需麻醉下在門診進行","(C) 軟式喉內視鏡僅能局限於臨床診斷用途；硬式喉內視鏡則可進行治療性手術","(D) 以目前的光學技術及醫療影像而言，兩者均可呈現高解析度影像畫質"],"answer":[0,2],"image":"","answer_note":"更正:第23題答Ａ或Ｃ或AC者均給分"},{"id":"md6-112-2-24","subject":"md6","topic":"麻醉-呼吸道與監視","meta":"112年第2次第24題","year":112,"session":2,"number":24,"question":"在人工呼吸道（artificial airway）的照護上，下列何者不是氣管切開術的優點？","options":["(A) 增加呼吸道的無效腔（dead space）","(B) 減少加護病房及住院時程","(C) 降低對聲帶、聲門下及氣管的傷害","(D) 可放置較大管徑的人工呼吸管路"],"answer":0,"image":""},{"id":"md6-112-2-25","subject":"md6","topic":"喉科學與頭頸腫瘤","meta":"112年第2次第25題","year":112,"session":2,"number":25,"question":"甲狀腺手術後，若造成上喉神經外支（external branch of superior laryngeal nerve）傷害，對下列那一喉內肌影響最大？","options":["(A) vocalis muscle","(B) cricothyroid muscle","(C) posterior cricoarytenoid muscle","(D) lateral cricoarytenoid muscle"],"answer":1,"image":""},{"id":"md6-112-2-26","subject":"md6","topic":"喉科學與頭頸腫瘤","meta":"112年第2次第26題","year":112,"session":2,"number":26,"question":"口腔癌手術後出現下列何項危險因子，會建議接受術後輔助化學放射治療（postoperative chemoradiotherapy）？","options":["(A) 陽性腫瘤切緣（positive margins）","(B) 晚期T3、T4口腔癌","(C) 原發腫瘤周圍出現神經侵犯（perineural invasion）","(D) 原發腫瘤周圍出現淋巴血管侵犯（lymphovascular invasion）"],"answer":0,"image":""},{"id":"md6-112-2-27","subject":"md6","topic":"喉科學與頭頸腫瘤","meta":"112年第2次第27題","year":112,"session":2,"number":27,"question":"有關唾液腺之良性腫瘤，下列敘述何者正確？","options":["(A) 多形性腺瘤（pleomorphic adenoma）最為常見，主要的治療方式是腫瘤摘除（enucleation）","(B) 多形性腺瘤（pleomorphic adenoma）惡性轉化率極低，故年輕成人首選的治療策略是觀察","(C) Warthin氏腫瘤常見於有抽菸習慣的男性，治療方式以腫瘤摘除（enucleation）為主","(D) Warthin氏腫瘤的另一個名稱是papillary cystadenoma lymphomatosum"],"answer":3,"image":""},{"id":"md6-112-2-28","subject":"md6","topic":"婦科-手術學與診斷技術","meta":"112年第2次第28題","year":112,"session":2,"number":28,"question":"28歲女性，G3P2，目前子宮腔內懷孕7週，來到門診作藥物終止懷孕的諮詢。關於第一孕期終止妊娠的藥物使用，下列何種藥物組合在實務上不會建議病患使用？","options":["(A) misoprostol alone","(B) mifepristone and misoprostol","(C) methotrexate and misoprostol","(D) mifepristone and methotrexate"],"answer":3,"image":""},{"id":"md6-112-2-29","subject":"md6","topic":"婦科-手術學與診斷技術","meta":"112年第2次第29題","year":112,"session":2,"number":29,"question":"對於生命徵象穩定、尚無異常陰道出血或下腹痛的子宮頸懷孕（cervical pregnancy）病患，在臨床上多數會建議及優先採用下列何種處理方式？","options":["(A) 藥物methotrexate注射","(B) 子宮切除手術（hysterectomy）","(C) 子宮頸環紮及子宮內膜搔刮手術（cerclage followed by D&C）","(D) 子宮動脈栓塞（uterine artery embolization）"],"answer":0,"image":""},{"id":"md6-112-2-30","subject":"md6","topic":"產科-一般產科","meta":"112年第2次第30題","year":112,"session":2,"number":30,"question":"早期懷孕之蛻膜（decidua）組織中何種免疫細胞最多，以調控胎盤滋養細胞（cytotrophoblast）之侵襲（invasion）和螺旋動脈重塑（spiral artery remodeling）？","options":["(A) 巨噬細胞（macrophage）","(B) 嗜中性顆粒白血球（neutrophil）","(C) 樹突狀細胞（dendritic cell）","(D) 自然殺手細胞（natural killer cell）"],"answer":3,"image":""},{"id":"md6-112-2-31","subject":"md6","topic":"產科-一般產科","meta":"112年第2次第31題","year":112,"session":2,"number":31,"question":"有關會陰裂傷分級，下列敘述何者錯誤？","options":["(A) 第1度僅傷及vaginal epithelium或perineal skin","(B) 第2度傷及perineal muscles，但anal sphincter complex是完整的","(C) 第3度裂傷可分為3a, 3b, 3c，其中3a裂傷是指小於1/3的external anal sphincter有撕裂","(D) 第4度裂傷係指裂傷範圍包括perineal body、anal sphincter complex和anorectal mucosa"],"answer":2,"image":""},{"id":"md6-112-2-32","subject":"md6","topic":"產科-一般產科","meta":"112年第2次第32題","year":112,"session":2,"number":32,"question":"有關剖腹生產的潛在合併症，下列敘述何者錯誤？","options":["(A) 出血較自然生產多","(B) 靜脈血栓發生機率較高","(C) 對特殊的孕婦，必須考慮術前術後胰島素、抗凝血劑的銜接","(D) 骨盆底部肌肉受損機會較高"],"answer":3,"image":""},{"id":"md6-112-2-33","subject":"md6","topic":"產科-一般產科","meta":"112年第2次第33題","year":112,"session":2,"number":33,"question":"有關產褥熱（puerperal fever）的敘述，下列何者錯誤？","options":["(A) 定義為產後體溫超過攝氏38度","(B) 自然生產產後第一天發生的產褥熱，原因超過一半為骨盆腔細菌感染","(C) 超過攝氏39度且伴隨spiking fever，多半為A型鏈球菌感染造成","(D) 脹奶可為產褥熱的原因之一"],"answer":1,"image":""},{"id":"md6-112-2-34","subject":"md6","topic":"復健-兒童與一般復健","meta":"112年第2次第34題","year":112,"session":2,"number":34,"question":"有關脊髓性肌肉萎縮症（spinal muscular atrophy, SMA）的敘述，下列何者正確？","options":["(A) 大多數患者是由染色體5q13.2上survival motor neuron（SMN1）基因突變所造成","(B) 多數患有此疾病的胎兒在第三孕期時會胎死腹中","(C) 因其發生率低，若孕婦有肌肉無力症狀才建議檢驗","(D) 胎兒患有此疾病，超音波下特徵為股骨（femoral length）過短"],"answer":0,"image":""},{"id":"md6-112-2-35","subject":"md6","topic":"產科-一般產科","meta":"112年第2次第35題","year":112,"session":2,"number":35,"question":"關於剖腹產時的傷口預防感染，若前胎剖腹的產婦身高161公分，孕前體重60公斤，產前體重70公斤，無內外科合併症且表皮清潔乾淨，產婦對盤尼西林過敏，則下列處置何者最適當？","options":["(A) 1.5 mg cefazolin每8小時給與注射","(B) 120 mg gentamycin單次給與注射","(C) 600 mg clindamycin併gentamycin 80 mg單次給與注射","(D) 1.0 gm ceftriaxone每12小時給與注射"],"answer":2,"image":""},{"id":"md6-112-2-36","subject":"md6","topic":"產科-一般產科","meta":"112年第2次第36題","year":112,"session":2,"number":36,"question":"下列何者並非產後哺乳之禁忌症？","options":["(A) 產婦正在接受化學治療","(B) C型肝炎病毒（hepatitis C virus）感染","(C) 人類免疫缺陷病毒（human immunodeficiency virus）感染","(D) 未治療之開放性肺結核菌（pulmonary tuberculosis）感染"],"answer":1,"image":""},{"id":"md6-112-2-37","subject":"md6","topic":"產科-高危險妊娠","meta":"112年第2次第37題","year":112,"session":2,"number":37,"question":"一位無過去病史，在懷孕時才初次被診斷妊娠糖尿病之孕婦，目前為飲食控制，其空腹血糖值為95 mg/dL，飯後2小時之血糖值為115 mg/dL，該孕婦屬於White classification的那一分類？","options":["(A) A1","(B) A2","(C) B","(D) C"],"answer":0,"image":""},{"id":"md6-112-2-38","subject":"md6","topic":"產科-高危險妊娠","meta":"112年第2次第38題","year":112,"session":2,"number":38,"question":"孕婦感染茲卡病毒（Zika virus）垂直傳播（vertical transmission）給胎兒後導致的先天性茲卡症（congenital Zika syndrome），最嚴重的胎兒異常在下列那個器官系統？","options":["(A) 腦部","(B) 肺臟","(C) 心臟","(D) 骨骼系統"],"answer":0,"image":""},{"id":"md6-112-2-39","subject":"md6","topic":"產科-高危險妊娠","meta":"112年第2次第39題","year":112,"session":2,"number":39,"question":"32歲月經28天週期規則的單胞胎初孕婦，於妊娠32週5日因早產性羊膜早破（preterm premature rupture of membranes），未出現羊膜腔內感染（intra-amniotic infection）住院，最不建議下列那一種治療？","options":["(A) 乙型鏈球菌預防性（group B streptococcal prophylaxis）治療","(B) 宮縮抑制劑（tocolytics）治療","(C) 皮質類固醇（corticosteroid）治療","(D) 抗生素（antimicrobials）治療"],"answer":1,"image":""},{"id":"md6-112-2-40","subject":"md6","topic":"婦科-良性腫瘤與內膜異位","meta":"112年第2次第40題","year":112,"session":2,"number":40,"question":"關於腹腔鏡在卵巢子宮內膜異位（endometriosis）的手術，下列敘述何者最不適當？","options":["(A) 子宮內膜異位瘤（endometrioma）常沾黏至骨盆側壁","(B) excisional surgery增加復發機率","(C) 腹腔鏡手術可能會傷到輸尿管（ureter）","(D) excisional surgery增加病人後續懷孕機會"],"answer":1,"image":""},{"id":"md6-112-2-41","subject":"md6","topic":"麻醉-呼吸道與監視","meta":"112年第2次第41題","year":112,"session":2,"number":41,"question":"腹腔鏡手術時，如發生二氧化碳氣體栓塞（carbon dioxide embolus）之併發症，下列處置何者較少考慮使用？","options":["(A) 將二氧化碳從患者腹腔體內抽吸出來","(B) 將病患擺位為右側躺（right lateral decubitus position）","(C) 置入大孔徑中央靜脈導管（large-bore central venous line）將氣體抽吸出來","(D) 將病患擺位為頭部低於右心房的水平面（head below the level of the right atrium）"],"answer":1,"image":""},{"id":"md6-112-2-42","subject":"md6","topic":"婦科-腫瘤","meta":"112年第2次第42題","year":112,"session":2,"number":42,"question":"有關子宮肌瘤，下列敘述何者最不適當？","options":["(A) 子宮肌瘤會癌化成平滑肌肉癌（leiomyosarcoma）","(B) 子宮肌瘤是平滑肌細胞的單株（monoclonal）腫瘤，有些有染色體異常","(C) 雌激素和黃體素可以促進肌瘤生長","(D) 由平滑肌細胞和纖維母細胞（fibroblasts）分泌的生長因子，蛋白質或多肽（polypeptides），主要通過增加細胞外基質（extracellular matrix）來刺激肌瘤生長"],"answer":0,"image":""},{"id":"md6-112-2-43","subject":"md6","topic":"婦科-生殖道感染與先天異常","meta":"112年第2次第43題","year":112,"session":2,"number":43,"question":"Mayer-Rokitansky-Küster-Hauser syndrome會有陰道子宮發育不全，有些患者還可能伴隨著下列何種器官系統的異常？","options":["(A) 視覺","(B) 味覺","(C) 嗅覺","(D) 聽覺"],"answer":3,"image":""},{"id":"md6-112-2-44","subject":"md6","topic":"婦科-手術學與診斷技術","meta":"112年第2次第44題","year":112,"session":2,"number":44,"question":"有關腹腔鏡子宮切除手術時，下列何者不是輸尿管容易受傷的位置？","options":["(A) 跨過骨盆上緣的位置","(B) 穿過子宮動脈下緣的位置","(C) 靠近子宮頸的位置","(D) 在psoas muscle上的位置"],"answer":3,"image":""},{"id":"md6-112-2-45","subject":"md6","topic":"婦科-生殖道感染與先天異常","meta":"112年第2次第45題","year":112,"session":2,"number":45,"question":"下列何者不是骨盆腔發炎（pelvic inflammatory disease）常見的症狀？","options":["(A) 骨盆腔疼痛（pelvic pain）","(B) 發燒（fever）","(C) 子宮頸位移痛（cervix lifting pain）","(D) 血尿（hematuria）"],"answer":3,"image":""},{"id":"md6-112-2-46","subject":"md6","topic":"產科-一般產科","meta":"112年第2次第46題","year":112,"session":2,"number":46,"question":"於早期懷孕發生流產的孕婦，約有多少比率會有先天性子宮異常？","options":["(A) 1～5%","(B) 5～10%","(C) 20～30%","(D) 35～40%"],"answer":1,"image":""},{"id":"md6-112-2-47","subject":"md6","topic":"婦科-生殖內分泌","meta":"112年第2次第47題","year":112,"session":2,"number":47,"question":"關於假性陰陽人（pseudohermaphroditism），下列何者錯誤？","options":["(A) 其外生殖器的樣子，與其染色體性別（chromosomal sex）不同","(B) 男性假性陰陽人（46,XY）常有尿道下裂（hypospadias）","(C) 女性假性陰陽人（46,XX）的卵巢反而比一般正常女性更大","(D) 發生原因為性荷爾蒙濃度異常或是性荷爾蒙受體異常"],"answer":2,"image":""},{"id":"md6-112-2-48","subject":"md6","topic":"婦科-生殖道感染與先天異常","meta":"112年第2次第48題","year":112,"session":2,"number":48,"question":"外陰部反覆發作的多處疼痛性潰瘍，最可能的診斷是下列何者？","options":["(A) 梅毒（syphilis）","(B) 單純性疱疹（herpes simplex）","(C) 帶狀疱疹（herpes zoster）","(D) 花柳性淋巴肉芽腫（lymphogranuloma venereum）"],"answer":1,"image":""},{"id":"md6-112-2-49","subject":"md6","topic":"婦科-腫瘤","meta":"112年第2次第49題","year":112,"session":2,"number":49,"question":"子宮內膜癌（endometrial cancer）大致分成type I和type II，下列有關兩者的描述何者錯誤？","options":["(A) type I多為endometrioid type","(B) type I預後較好","(C) type II的precursor lesion常為atypical hyperplasia","(D) type II通常分化較差"],"answer":2,"image":""},{"id":"md6-112-2-50","subject":"md6","topic":"婦科-腫瘤","meta":"112年第2次第50題","year":112,"session":2,"number":50,"question":"下列何者腫瘤與其特定的腫瘤標記（tumor marker）之配對正確？","options":["(A) choriocarcinoma；LDH","(B) yolk sac tumor；β-hCG","(C) granulosa cell tumor；AMH","(D) epithelial ovarian cancer；SCC"],"answer":2,"image":""},{"id":"md6-112-2-51","subject":"md6","topic":"婦科-腫瘤","meta":"112年第2次第51題","year":112,"session":2,"number":51,"question":"依據2008 International Federation of Gynecology and Obstetrics（FIGO）手術分期方式，下列何項不會影響子宮內膜癌手術後之期別？","options":["(A) no or less than half myometrium invasion","(B) positive peritoneal cytology","(C) positive pelvic lymph nodes","(D) bladder invasion"],"answer":1,"image":""},{"id":"md6-112-2-52","subject":"md6","topic":"婦科-腫瘤","meta":"112年第2次第52題","year":112,"session":2,"number":52,"question":"有關子宮頸癌的分期，下列敘述何者錯誤？","options":["(A) 2018年FIGO的新分期也參考影像學的檢查結果","(B) 主要以手術分期為依據","(C) 正子攝影（positron emission tomography）常用於骨盆腔外轉移的偵測","(D) 若有骨盆腔淋巴轉移屬於第三期"],"answer":1,"image":""},{"id":"md6-112-2-53","subject":"md6","topic":"婦科-腫瘤","meta":"112年第2次第53題","year":112,"session":2,"number":53,"question":"關於子宮頸小細胞癌（small cell carcinoma）之敘述，下列何者正確？","options":["(A) 60%是由肺部小細胞癌轉移過來","(B) 通常要合併carboplatin及paclitaxel配方的化學治療","(C) 遠端轉移的百分比高於鱗狀上皮癌","(D) 其發生與肥胖或不當使用雌激素有關"],"answer":2,"image":""},{"id":"md6-112-2-54","subject":"md6","topic":"婦科-生殖內分泌","meta":"112年第2次第54題","year":112,"session":2,"number":54,"question":"試管嬰兒療程中，下列何者不是預防卵巢過度刺激症候群（ovarian hyperstimulation syndrome, OHSS）的方法？","options":["(A) 減少促性腺激素（gonadotropin）注射劑量","(B) 若使用GnRH拮抗劑（GnRH antagonist）療程，破卵針（ovulation trigger）不用hCG，改用GnRH促效劑（GnRH agonist）","(C) 植入二個胚胎","(D) 從注射hCG當天開始，給與cabergoline每天0.5 mg，連續8天"],"answer":2,"image":""},{"id":"md6-112-2-55","subject":"md6","topic":"婦科-生殖內分泌","meta":"112年第2次第55題","year":112,"session":2,"number":55,"question":"下列關於人類卵細胞的敘述，何者正確？","options":["(A) 卵原細胞（oogonium）在女嬰出生前就全部成為初級卵母細胞（primary oocyte）","(B) 在懷孕18～20週時，初級卵母細胞（primary oocyte）會與顆粒細胞組合成初級濾泡（primary follicle）","(C) 在青春期時，初級濾泡（primary follicle）受到濾泡刺激素（follicle-stimulating hormone, FSH）刺激，發育成二級濾泡（secondary follicle）","(D) 在排卵時，初級卵母細胞（primary oocyte）會完成兩次減數分裂，成為卵子（ovum）"],"answer":0,"image":""},{"id":"md6-112-2-56","subject":"md6","topic":"婦科-生殖內分泌","meta":"112年第2次第56題","year":112,"session":2,"number":56,"question":"多囊性卵巢症候群（polycystic ovary syndrome, PCOS）是造成排卵功能異常的常見內分泌疾病，根據2003年的鹿特丹共識會議，下列何者不是多囊性卵巢症候群的診斷條件？","options":["(A) 寡經或無月經","(B) 血中雄性素過高或有雄性素過高的臨床表現","(C) 胰島素阻抗","(D) 超音波顯示多囊性卵巢"],"answer":2,"image":""},{"id":"md6-112-2-57","subject":"md6","topic":"婦科-尿失禁與骨盆腔脫垂","meta":"112年第2次第57題","year":112,"session":2,"number":57,"question":"下列有關Pelvic Organ Prolapse Quantification（POP-Q）的敘述何者正確？","options":["(A) 包含對A、B、C、D點、genital hiatus、perineal body、和vagina長度的描述","(B) 對突出hymen外的點，記錄為〝-〞（負號）","(C) 子宮頸下垂的程度（stage）是以Aa點決定","(D) 膀胱下垂的程度（stage）是以C點決定"],"answer":0,"image":""},{"id":"md6-112-2-58","subject":"md6","topic":"復健-神經復健","meta":"112年第2次第58題","year":112,"session":2,"number":58,"question":"有關腦中風復健的布朗斯壯（Brunnstrom）分期，「開始有獨立動作，肌肉張力也開始下降」是屬於第幾個分期（stage）？","options":["(A) II","(B) III","(C) IV","(D) V"],"answer":2,"image":""},{"id":"md6-112-2-59","subject":"md6","topic":"復健-骨骼肌肉損傷與疾患","meta":"112年第2次第59題","year":112,"session":2,"number":59,"question":"有關老年人肌肉（aging muscle）的生理與結構變化，下列何者最不適當？","options":["(A) 肌力（muscle power）減少，上肢比下肢明顯","(B) 肌肉體積量（muscle mass）減少","(C) 肌力（muscle power）減少，肢體近端比遠端明顯","(D) 第二型（type II）肌肉細胞較易萎縮"],"answer":0,"image":""},{"id":"md6-112-2-60","subject":"md6","topic":"復健-神經復健","meta":"112年第2次第60題","year":112,"session":2,"number":60,"question":"有關人類脊髓損傷造成的中髓症候群（central cord syndrome），下列敘述何者最不適當？","options":["(A) 最常發生於頸部脊髓","(B) 常因為脊椎骨折脫位所造成","(C) 常發生於老年人跌倒","(D) 患者的下肢功能一般恢復比上肢好"],"answer":1,"image":""},{"id":"md6-112-2-61","subject":"md6","topic":"喉科學與頭頸腫瘤","meta":"112年第2次第61題","year":112,"session":2,"number":61,"question":"有關正常人吞嚥時，咽部期（pharyngeal phase）的描述，下列何者錯誤？","options":["(A) 由腦幹所控制","(B) 通常小於1秒鐘","(C) 喉部（larynx）會下壓","(D) 懸雍垂（uvula）後縮上舉"],"answer":2,"image":""},{"id":"md6-112-2-62","subject":"md6","topic":"復健-物理因子治療與評估","meta":"112年第2次第62題","year":112,"session":2,"number":62,"question":"關於物理因子（physical modality），下列敘述何者最不適當？","options":["(A) 物理因子包括了動力、聲（震動）能、光（電磁）能、電能、熱（包括冷）能以及水療等","(B) 物理因子只應用在復健（物理）醫學領域中，作為治療患者的工具","(C) 利用增大熱能來治療患者稱為熱療（thermotherapy），而利用降低熱能來治療患者稱為冷療（cryotherapy）","(D) 熱能傳遞的方式可分為傳導（conduction）、對流（convection）、輻射（radiation）、蒸發（evaporation）及轉換（conversion）"],"answer":1,"image":""},{"id":"md6-112-2-63","subject":"md6","topic":"復健-截肢與義肢輔具","meta":"112年第2次第63題","year":112,"session":2,"number":63,"question":"有關截肢復健，下列敘述何者最不適當？","options":["(A) 造成殘肢痛的原因包括結構損傷造成的疼痛、感染、缺血、神經瘤等","(B) 裝配義肢必須等傷口完全癒合後，再開始進行","(C) 幻肢痛一般認為屬於神經性疼痛","(D) 幻肢痛是指被截除的肢體雖已不存在，但仍感到肢體疼痛"],"answer":1,"image":""},{"id":"md6-112-2-64","subject":"md6","topic":"復健-骨骼肌肉損傷與疾患","meta":"112年第2次第64題","year":112,"session":2,"number":64,"question":"有關僵直性脊椎炎（Ankylosing Spondylitis），下列敘述何者錯誤？","options":["(A) 屬於血清陰性關節病變（seronegative spondyloarthropathy）","(B) 其特徵為類風濕因子呈現陰性反應，人類白血球組織抗原HLA-B27大多為陽性反應","(C) 是一種以侵犯脊椎為主的慢性關節炎，男女比率相近，發作的年齡以35歲以上居多","(D) 僵直性脊椎炎的診斷以1984年修正版之紐約診斷標準（Modified New York Criteria）為主，HLA-B27之陽性反應並不是必備的條件之一"],"answer":2,"image":""},{"id":"md6-112-2-65","subject":"md6","topic":"復健-心肺復健與運動處方","meta":"112年第2次第65題","year":112,"session":2,"number":65,"question":"有關胸腔復健，下列敘述何者最適當？","options":["(A) 胸腔復健最主要是由物理治療師來主導，其他專業人員有需要的時候再配合","(B) 病人有可能因為呼吸窘迫而無法進行一般的日常生活活動，可接受上肢肌力的強化、日常生活簡化及訓練、甚至特殊裝置的職能治療","(C) 肺部疾病病人因為長期呼吸困難造成心理的退縮、憂鬱而給予心理治療，不算在胸腔復健的治療項目","(D) 當一位慢性阻塞性肺病的病人，接受呼吸運動與姿勢引流等治療項目，算是完整的胸腔復健治療"],"answer":1,"image":""},{"id":"md6-112-2-66","subject":"md6","topic":"產科-一般產科","meta":"112年第2次第66題","year":112,"session":2,"number":66,"question":"懷孕婦女的飲食中加入葉酸（folic acid），已有研究證實有助於降低胎兒罹患下列何種疾病的發生機率？","options":["(A) 腦性麻痺（cerebral palsy）","(B) 神經管缺損（neural tube defects）","(C) 脊髓性肌肉萎縮症（spinal muscular atrophy）","(D) 唐氏症（Down syndrome）"],"answer":1,"image":""},{"id":"md6-112-2-67","subject":"md6","topic":"復健-神經復健","meta":"112年第2次第67題","year":112,"session":2,"number":67,"question":"關於腦性麻痺（cerebral palsy）患者之合併症，下列敘述何者錯誤？","options":["(A) 腦性麻痺患者常有認知缺損（cognitive impairment）","(B) 核黃疸（kernicterus）造成的腦性麻痺患者，要檢查有無聽力受損（hearing loss）","(C) 腦性麻痺通常與遺傳性疾病相關","(D) 抗癲癇藥物（anticonvulsants）可能導致腦性麻痺患者的骨質缺乏（osteopenia）"],"answer":2,"image":""},{"id":"md6-112-2-68","subject":"md6","topic":"復健-兒童與一般復健","meta":"112年第2次第68題","year":112,"session":2,"number":68,"question":"下列有關巴氏量表（Barthel index）之敘述，何者錯誤？","options":["(A) 總分為0至100分","(B) 為評估病患日常生活功能之量表","(C) 分數越低者，在日常生活中越不需要他人協助","(D) 評估項目共10項"],"answer":2,"image":""},{"id":"md6-112-2-69","subject":"md6","topic":"復健-神經復健","meta":"112年第2次第69題","year":112,"session":2,"number":69,"question":"對於頸椎脊髓完全損傷的病人而言，經過一年訓練之後，有可能獨立操作手動輪椅的最高位損傷為何？","options":["(A) neurological level為C4的病人","(B) neurological level為C5的病人","(C) neurological level為C6的病人","(D) neurological level為C7的病人"],"answer":1,"image":""},{"id":"md6-112-2-70","subject":"md6","topic":"復健-骨骼肌肉損傷與疾患","meta":"112年第2次第70題","year":112,"session":2,"number":70,"question":"關於老年人肌少症（sarcopenia），下列敘述何者最為適當？","options":["(A) 是指肌肉總量、肌肉力量和活動功能隨著年齡減少的一個症候群","(B) 會增加老年人失能的風險，尤其是男性","(C) 對於住院的病人而言，會增加感染、壓力性潰瘍（stress ulcer）率，但不會增加死亡率","(D) 發生率與年齡沒有直接的相關，但是與失用（deconditioning）或是沒有活動（immobility）有關"],"answer":0,"image":""},{"id":"md6-112-2-71","subject":"md6","topic":"復健-截肢與義肢輔具","meta":"112年第2次第71題","year":112,"session":2,"number":71,"question":"有關輪椅扶手的敘述，下列何者最不適當？","options":["(A) 扶手高度（armrest height）指的是手肘彎曲90度時，座椅與前臂間的距離","(B) 扶手的高度與患者推動輪椅時的施力難易與否無關","(C) 由於患者推動輪椅時手臂必須越過扶手，這可能使患者肩膀過度外展，而導致肩關節受傷","(D) 若扶手高度太低，將無法提供上肢與肩膀適當的支撐"],"answer":1,"image":""},{"id":"md6-112-2-72","subject":"md6","topic":"婦科-生殖道感染與先天異常","meta":"112年第2次第72題","year":112,"session":2,"number":72,"question":"26歲女性病人，因下腹痛及發燒接受電腦斷層檢查（如附圖）。最可能之診斷為何？","options":["(A) 巧克力囊腫（chocolate cyst）","(B) 卵巢癌（ovarian cancer）","(C) 畸胎瘤（teratoma）","(D) 輸卵管卵巢膿瘍（tubo-ovarian abscess）"],"answer":3,"image":"md6-112-2-72.jpeg"},{"id":"md6-112-2-73","subject":"md6","topic":"眼科-角膜結膜眼瞼眼窩","meta":"112年第2次第73題","year":112,"session":2,"number":73,"question":"25歲病人，車禍頭部受創一天後，左眼紅腫凸出，左邊頭側上聽診可聽見脈動雜音，合併視力快速喪失。下列關於這個病況的敘述及診斷，何者最不恰當？","options":["(A) 直接型頸動脈–海綿竇瘻管（direct carotid-cavernous fistula），以放射治療即可痊癒","(B) 可考慮以血管攝影檢查或電腦斷層血管影像（CTA）確認診斷","(C) 電腦斷層檢查可見上眼靜脈（superior ophthalmic vein）擴張","(D) 可能合併顱底骨折"],"answer":0,"image":"md6-112-2-73.jpeg"},{"id":"md6-112-2-74","subject":"md6","topic":"復健-骨骼肌肉損傷與疾患","meta":"112年第2次第74題","year":112,"session":2,"number":74,"question":"63歲女性病人，主訴右足底疼痛，於起床著地時特別明顯。超音波檢查如圖，上圖為右側足底筋膜連結至跟骨處，下圖為左側足底筋膜連結至跟骨處，最可能診斷為何？","options":["(A) 跟骨骨髓炎（calcaneal osteomyelitis）","(B) 腱鞘囊腫（ganglion）","(C) 足底筋膜炎（plantar fasciitis）","(D) 足底筋膜斷裂（tear of plantar fascia）"],"answer":2,"image":"md6-112-2-74.jpeg"},{"id":"md6-112-2-75","subject":"md6","topic":"麻醉-麻醉藥理","meta":"112年第2次第75題","year":112,"session":2,"number":75,"question":"70歲男性有氣喘病史，因呼吸窘迫送到急診，到院時生命徵象：心跳120/min，呼吸40/min，血壓86/54 mmHg，血氧濃度70%。胸部X光發現右側大片肺炎。擬執行氣管內管置放時，下列藥物何者最適合？","options":["(A) midazolam","(B) ketamine","(C) propofol","(D) barbiturate"],"answer":1,"image":""},{"id":"md6-112-2-76","subject":"md6","topic":"眼科-角膜結膜眼瞼眼窩","meta":"112年第2次第76題","year":112,"session":2,"number":76,"question":"有關帶狀疱疹眼病（herpes zoster ophthalmicus）的敘述，下列何者最正確？","options":["(A) 是因為病毒侵犯顏面神經所導致","(B) 病人的鼻頭如有水泡，有可能會產生帶狀疱疹眼病","(C) 會產生角膜炎、葡萄膜炎、網膜炎，但不會產生視神經炎","(D) 治療以給局部類固醇及抗生素藥膏為主"],"answer":1,"image":""},{"id":"md6-112-2-77","subject":"md6","topic":"復健-骨骼肌肉損傷與疾患","meta":"112年第2次第77題","year":112,"session":2,"number":77,"question":"一位47歲男性，最近因工作較多，導致右肩疼痛加劇而來求診。病人自述平常肩膀活動還好，無明顯外傷，肩部外展時疼痛加劇，晚上休息時也會痛。身體檢查發現：右肩外觀沒有紅腫變形，手向前伸直後向上抬舉會有疼痛，但被動式外展時並不會疼痛，背斜方肌亦沒有壓痛點，最有可能的診斷為：","options":["(A) 纖維肌痛（fibromyalgia）","(B) 肩軸轉肌損傷（rotator cuff injury）","(C) 沾黏性肩關節囊炎（adhesive capsulitis）","(D) 肩關節炎（shoulder osteoarthritis）"],"answer":1,"image":""},{"id":"md6-112-2-78","subject":"md6","topic":"醫學倫理與法規","meta":"112年第2次第78題","year":112,"session":2,"number":78,"question":"關於病歷之所有權及使用權，下列敘述何者最適當？","options":["(A) 醫師及醫院具病歷之所有權但不具使用權，僅病人具使用權","(B) 醫師及醫院具病歷之所有權，醫師、醫院及病人皆具使用權","(C) 病人具病歷之所有權但不具使用權，僅醫師及醫院具使用權","(D) 病人具病歷之所有權，醫師、醫院及病人皆具使用權"],"answer":1,"image":""},{"id":"md6-112-2-79","subject":"md6","topic":"醫學倫理與法規","meta":"112年第2次第79題","year":112,"session":2,"number":79,"question":"小明為7歲男童，因罹患骨癌接受Ａ化療藥物之臨床試驗，依我國現行醫療法規定，該治療過程之病歷應保存至何時？","options":["(A) 治療後7年","(B) 小明成年","(C) 小明成年後7年","(D) 永久保存"],"answer":3,"image":""},{"id":"md6-112-2-80","subject":"md6","topic":"醫學倫理與法規","meta":"112年第2次第80題","year":112,"session":2,"number":80,"question":"28歲女性懷孕18週，接受第二孕期母血唐氏症篩檢，結果顯示胎兒得唐氏症的機率是1/30，孕婦要求進行人工流產，下列處置何者最適宜？","options":["(A) 符合優生保健法規定，依照病人要求，安排人工流產","(B) 說明母血唐氏症篩檢為風險評估，建議羊膜穿刺確認胎兒是否為唐氏症","(C) 考量篩檢準確度，應再進行一次母血唐氏症篩檢","(D) 安排高層次超音波，來確認胎兒是否為唐氏症"],"answer":1,"image":""},{"id":"md6-113-1-1","subject":"md6","topic":"麻醉-呼吸道與監視","meta":"113年第1次第1題","year":113,"session":1,"number":1,"question":"使用軟式光纖支氣管鏡（flexible fiberoptic bronchoscope）置放氣管內管，下列敘述何者正確？","options":["(A) 只能經鼻插管，不能經口插管","(B) 可用於不穩定頸椎骨折病人之氣管插管","(C) 不適用於清醒的病人","(D) 不適用於已麻醉的病人"],"answer":1,"image":""},{"id":"md6-113-1-2","subject":"md6","topic":"麻醉-呼吸道與監視","meta":"113年第1次第2題","year":113,"session":1,"number":2,"question":"關於脈衝動脈血氧飽和度（pulse oximeter, SpO2）在臨床麻醉的應用，下列敘述何者最不適當？","options":["(A) 藉由波形可以發現是否有心律不整","(B) 波形振幅（amplitude）偏低，代表組織可能灌流不足","(C) 不能當作氣管插管位置正確與否的早期診斷工具","(D) 氣管插管若過深而進入右側支氣管，則血氧飽和度（SpO2）會快速下降"],"answer":3,"image":""},{"id":"md6-113-1-3","subject":"md6","topic":"麻醉-麻醉藥理","meta":"113年第1次第3題","year":113,"session":1,"number":3,"question":"神經肌肉阻斷劑（neuromuscular blocking drugs, NMBDs）常運用於氣管插管或手術麻醉，有關於NMBDs的使用與監測，下列敘述何者正確？","options":["(A) 在恢復室若測得內收拇肌TOF（adductor pollicis train-of-four）大於0.9，會增加缺氧、呼吸道阻塞、延長住院的風險","(B) neostigmine可增加神經肌肉交界（neuromuscular junction）處的acetylcholine，最好在病人已有恢復自主呼吸跡象時再給與","(C) sugammadex可與steroidal NMBDs充分結合，臨床上用以除去cisatracurium的作用，可用於氣管插管通氣失敗時緊急reversal","(D) 使用靜脈麻醉比使用氣體麻醉容易增加術後殘留肌肉神經阻斷（residual neuromuscular blockade）的風險，尤其在高齡者容易有無力的現象"],"answer":1,"image":""},{"id":"md6-113-1-4","subject":"md6","topic":"麻醉-麻醉藥理","meta":"113年第1次第4題","year":113,"session":1,"number":4,"question":"在外科手術中搭配麻醉藥品使用之神經肌肉阻斷劑，下列何者不以肝作為主要代謝器官，適合使用在肝功能嚴重異常的病人？","options":["(A) cisatracurium","(B) vecuronium","(C) rocuronium","(D) succinylcholine"],"answer":0,"image":""},{"id":"md6-113-1-5","subject":"md6","topic":"麻醉-特殊麻醉與疼痛","meta":"113年第1次第5題","year":113,"session":1,"number":5,"question":"下列有關脊椎麻醉（spinal anesthesia）的敘述，何者錯誤？","options":["(A) lidocaine的作用時間（duration）較bupivacaine長","(B) morphine的作用時間（duration）較fentanyl長","(C) 脊椎腔內注射opioid可導致尿滯留","(D) 脊椎麻醉最常見的併發症為低血壓"],"answer":0,"image":""},{"id":"md6-113-1-6","subject":"md6","topic":"麻醉-呼吸道與監視","meta":"113年第1次第6題","year":113,"session":1,"number":6,"question":"有關手術中採趴臥姿勢，下列敘述何者正確？","options":["(A) 恰當的趴臥擺位，肺功能可能會優於正躺與側躺姿勢","(B) 上臂絕對不能外展","(C) 病患靜脈回流增加，不易形成靜脈血栓","(D) 眼睛若無受壓則完全不會有視力喪失可能"],"answer":0,"image":""},{"id":"md6-113-1-7","subject":"md6","topic":"產科-一般產科","meta":"113年第1次第7題","year":113,"session":1,"number":7,"question":"常規剖腹生產（elective Cesarean section）若是在插管全身麻醉下進行手術，有關麻醉處置下列敘述何者錯誤？","options":["(A) 足月生產的孕婦皆應視為空腹不足（full stomach），可給與不含顆粒口服制酸劑（nonparticulate oral antacid）預防吸入性肺炎","(B) 不宜使用肌肉鬆弛劑succinylcholine，以避免影響出生嬰兒呼吸","(C) 胎兒娩出後，再給與opioids","(D) 胎兒娩出後，若使用麻醉氣體維持麻醉，建議維持0.5MAC即可"],"answer":1,"image":""},{"id":"md6-113-1-8","subject":"md6","topic":"麻醉-特殊麻醉與疼痛","meta":"113年第1次第8題","year":113,"session":1,"number":8,"question":"下列何項藥物是治療典型三叉神經痛（Trigeminal Neuralgia）的首選藥物？","options":["(A) pregabalin","(B) fluoxetine","(C) tramadol","(D) carbamazepine"],"answer":3,"image":""},{"id":"md6-113-1-9","subject":"md6","topic":"麻醉-麻醉藥理","meta":"113年第1次第9題","year":113,"session":1,"number":9,"question":"急性呼吸窘迫症候群（acute respiratory distress syndrome）病人使用一氧化氮（nitric oxide）吸入治療，其作用機轉為何？","options":["(A) 全身性的血管擴張","(B) 全身性的血管收縮","(C) 選擇性肺血管擴張","(D) 選擇性肺血管收縮"],"answer":2,"image":""},{"id":"md6-113-1-10","subject":"md6","topic":"眼科-視網膜葡萄膜","meta":"113年第1次第10題","year":113,"session":1,"number":10,"question":"下列何種方法適合用來治療濕性年齡相關黃斑部退化（wet-type age-related macular degeneration）？","options":["(A) 格子狀視網膜雷射光凝固術（grid retinal photocoagulation）","(B) 全網膜雷射光凝固術（panretinal photocoagulation）","(C) 鞏膜扣壓術（scleral buckling）","(D) 玻璃體內注射抗血管內皮生長因子製劑（anti-VEGF agent）"],"answer":3,"image":""},{"id":"md6-113-1-11","subject":"md6","topic":"眼科-視網膜葡萄膜","meta":"113年第1次第11題","year":113,"session":1,"number":11,"question":"下列何種方法並不適合用來治療裂孔性視網膜剝離？","options":["(A) 鞏膜扣壓術（scleral buckling）","(B) 光動力治療（photodynamic therapy）","(C) 經坦部玻璃體切除術（pars plana vitrectomy）","(D) 氣體視網膜固定術（pneumatic retinopexy）"],"answer":1,"image":""},{"id":"md6-113-1-12","subject":"md6","topic":"眼科-角膜結膜眼瞼眼窩","meta":"113年第1次第12題","year":113,"session":1,"number":12,"question":"下列那一項器官或組織，被認定有所謂的「免疫特權區（immuno-privileged zone）」？","options":["(A) 肝臟","(B) 心臟","(C) 角膜","(D) 腎臟"],"answer":2,"image":""},{"id":"md6-113-1-13","subject":"md6","topic":"眼科-屈光斜弱視","meta":"113年第1次第13題","year":113,"session":1,"number":13,"question":"下列敘述，何者較正確？","options":["(A) 網膜鏡檢（retinoscopy）主要是為檢查視網膜用的","(B) 七、八歲小朋友眼睛經睫狀肌麻痺後檢查，發現有近視50度（即驗光結果為-0.5D），表示患了假性近視","(C) 小朋友經醫師診療暫不必戴眼鏡，先給與散瞳劑回家點眼，表示得到的是假性近視","(D) 近視成因的光學因素，眼軸長度比角膜屈折率重要"],"answer":3,"image":""},{"id":"md6-113-1-14","subject":"md6","topic":"眼科-水晶體青光眼","meta":"113年第1次第14題","year":113,"session":1,"number":14,"question":"Marfan syndrome常會合併下列何種晶體異常？","options":["(A) ","(B) ","(C) ","(D) "],"answer":0,"image":"md6-113-1-14.jpeg"},{"id":"md6-113-1-15","subject":"md6","topic":"眼科-角膜結膜眼瞼眼窩","meta":"113年第1次第15題","year":113,"session":1,"number":15,"question":"可能同時影響多條腦神經（例如：II、III、IV、VI等）與交感神經，造成麻痺的症狀，不包含下列何者？","options":["(A) superior orbital fissure syndrome","(B) orbital apex syndrome","(C) Fisher's syndrome","(D) Horner syndrome"],"answer":3,"image":""},{"id":"md6-113-1-16","subject":"md6","topic":"眼科-屈光斜弱視","meta":"113年第1次第16題","year":113,"session":1,"number":16,"question":"兒童調視性內斜視（refractive accommodative esotropia）的診治，下列敘述何者較正確？","options":["(A) 有斜視應儘早開刀，以免造成弱視","(B) 兩、三歲幼童接受肉毒桿菌素（botulinum toxin）眼肌注射，最有療效","(C) 儘早戴上遠視眼鏡矯正，可以治好內斜視","(D) 若會輪流偏斜，表示沒弱視，則不需作任何矯治"],"answer":2,"image":""},{"id":"md6-113-1-17","subject":"md6","topic":"眼科-角膜結膜眼瞼眼窩","meta":"113年第1次第17題","year":113,"session":1,"number":17,"question":"有些藥物可能引起角膜沉積物（corneal deposits）的副作用，下列何種藥物較不可能？","options":["(A) amiodarone","(B) hydroxychloroquine","(C) chlorpromazine","(D) isoniazid"],"answer":3,"image":""},{"id":"md6-113-1-18","subject":"md6","topic":"眼科-角膜結膜眼瞼眼窩","meta":"113年第1次第18題","year":113,"session":1,"number":18,"question":"有關淚腺腫瘤之敘述，下列何者錯誤？","options":["(A) 腫瘤長大，可能將眼球往前方下方擠壓","(B) 若腫瘤形狀接近圓形，周邊完整，可以先做部分活組織切片（incision biopsy）來確診","(C) 淋巴腫瘤是最多的病理診斷","(D) 腺樣囊狀癌（adenoid cystic carcinoma）會造成病人極度疼痛"],"answer":2,"image":""},{"id":"md6-113-1-19","subject":"md6","topic":"耳科學","meta":"113年第1次第19題","year":113,"session":1,"number":19,"question":"目前國內人工電子耳用於下列那一類病人之個案數最多？","options":["(A) 雙側重度感音性聽力損失之嬰幼兒","(B) 單側重度感音性聽力損失之嬰幼兒","(C) 雙側重度感音性聽力損失之成人","(D) 雙側重度傳導性聽力損失之成人"],"answer":0,"image":""},{"id":"md6-113-1-20","subject":"md6","topic":"耳科學","meta":"113年第1次第20題","year":113,"session":1,"number":20,"question":"一中年男性長年四季晨泳，耳鏡檢查發現如圖，下列何者為最可能之診斷？","options":["(A) otomycosis","(B) exostosis","(C) chronic otitis externa","(D) acute otitis externa"],"answer":1,"image":"md6-113-1-20.jpeg"},{"id":"md6-113-1-21","subject":"md6","topic":"喉科學與頭頸腫瘤","meta":"113年第1次第21題","year":113,"session":1,"number":21,"question":"有關支配味覺功能的神經，下列敘述何者錯誤？","options":["(A) 舌前2/3的味覺由顏面神經（facial nerve, CN VII）支配","(B) 味覺是由多條腦神經（CN VII, IX, X）共同支配","(C) 舌後1/3的味覺由舌咽神經（glossopharyngeal nerve, CN IX）支配","(D) 會厭區域的味覺由舌下神經（hypoglossal nerve, CN XII）支配"],"answer":3,"image":""},{"id":"md6-113-1-22","subject":"md6","topic":"鼻科學","meta":"113年第1次第22題","year":113,"session":1,"number":22,"question":"有關過敏性鼻炎（allergic rhinitis）病生理的機轉，下列敘述何者正確？","options":["(A) 第一次接觸過敏原時產生早期發炎反應（early inflammation）","(B) 再次接觸過敏原時產生致敏化（sensitization）反應","(C) 反覆接觸過敏原後出現晚期發炎反應（late inflammation）","(D) 長久接觸過敏原後，必然產生各種併發症或後遺症（sequelae）"],"answer":2,"image":""},{"id":"md6-113-1-23","subject":"md6","topic":"鼻科學","meta":"113年第1次第23題","year":113,"session":1,"number":23,"question":"急性鼻竇炎（acute rhinosinusitis）之眼部併發症，依據Chandler分類，圖中的病例屬於那一類？","options":["(A) group I：隔膜前眼眶蜂窩組織炎（preseptal orbital cellulitis）","(B) group II：眼眶蜂窩組織炎（orbital cellulitis）","(C) group III：眼眶骨膜下膿瘍（subperiosteal abscess）","(D) group IV：眼眶膿瘍（orbital abscess）"],"answer":2,"image":"md6-113-1-23.jpeg"},{"id":"md6-113-1-24","subject":"md6","topic":"喉科學與頭頸腫瘤","meta":"113年第1次第24題","year":113,"session":1,"number":24,"question":"有關小兒氣管切開術，下列敘述何者錯誤？","options":["(A) 近年來最常見的適應症是長期插管需要呼吸器輔助的案例","(B) 在執行小兒氣管切開手術進入呼吸道之前，必須要先做氣管的stay sutures","(C) 多在開刀房內執行，但手術後已經建立呼吸道，轉送一般病房觀察即可","(D) 氣切造口maturation步驟並不一定要做"],"answer":2,"image":""},{"id":"md6-113-1-25","subject":"md6","topic":"耳科學","meta":"113年第1次第25題","year":113,"session":1,"number":25,"question":"下列何者不是造成鼻咽癌病人治療後聽力受損的常見原因？","options":["(A) 放射線治療對於聽力器官的直接傷害","(B) 治療後耳咽管功能不佳，引起的反覆中耳積液","(C) 鉑金類（platinum）化療藥物治療所引起的耳毒性副作用","(D) 標靶類藥物治療所引起的耳毒性副作用"],"answer":3,"image":""},{"id":"md6-113-1-26","subject":"md6","topic":"喉科學與頭頸腫瘤","meta":"113年第1次第26題","year":113,"session":1,"number":26,"question":"單側下咽癌（hypopharyngeal cancer），頸部那個區域的淋巴轉移風險最高 ?","options":["(A) 同側第一、二、三區淋巴結","(B) 同側第二、三、四區淋巴結","(C) 同側第三、四、五區淋巴結","(D) 第六、七區淋巴結"],"answer":1,"image":""},{"id":"md6-113-1-27","subject":"md6","topic":"喉科學與頭頸腫瘤","meta":"113年第1次第27題","year":113,"session":1,"number":27,"question":"目前在頭頸癌較常被使用的標靶藥物為cetuximab，其針對的腫瘤細胞分子為何？","options":["(A) EGFR","(B) Ras","(C) VEGFR","(D) Notch1"],"answer":0,"image":""},{"id":"md6-113-1-28","subject":"md6","topic":"產科-高危險妊娠","meta":"113年第1次第28題","year":113,"session":1,"number":28,"question":"一位30歲孕婦妊娠12週，產檢時超音波發現胎兒頸部透明帶厚度3.3 mm，下列敘述何者正確？","options":["(A) 胎兒預後極差，建議立即終止妊娠","(B) 胎兒可能有染色體異常，以Down syndrome最常見","(C) 胎兒患有先天性心臟病的機率高達15%","(D) 如孕婦懷孕16週時羊膜穿刺術的染色體報告正常，則正常產檢即可"],"answer":1,"image":""},{"id":"md6-113-1-29","subject":"md6","topic":"產科-高危險妊娠","meta":"113年第1次第29題","year":113,"session":1,"number":29,"question":"25歲女性因最近一天內出現大量陰道出血而來到急診就診，這位女性自述：最近一週出現嚴重噁心感、最後一次月經開始日為6週前、自行驗孕尿液懷孕試驗呈陽性反應，到急診時，其血壓為140/90 mmHg、心跳每分鐘120下，身體理學檢查發現其子宮大小約為懷孕12週、子宮頸長度正常且子宮頸口關閉未開，抽血檢驗發現血清β-人類絨毛膜刺激激素（β-subunit human chorionic gonadotropin, β-hCG）值為400,000 mIU/mL，骨盆腔超音波檢查發現如圖所示：在子宮腔內充滿雜回音性的（mixed echogenic）組織且伴隨很多的低回音性的囊狀間隙（anechoic cystic spaces）、似暴風雪狀（snowstorm appearance）、看不到羊膜囊或胎兒發育。下列何者為最正確的診斷？","options":["(A) 早期懷孕流產（early pregnancy loss）","(B) 子宮外孕（ectopic pregnancy）","(C) 妊娠滋養層細胞疾病（gestational trophoblastic disease）","(D) 雙胞胎妊娠（twin pregnancy）"],"answer":2,"image":"md6-113-1-29.jpeg"},{"id":"md6-113-1-30","subject":"md6","topic":"產科-一般產科","meta":"113年第1次第30題","year":113,"session":1,"number":30,"question":"妊娠8週以後，母親血液中之黃體素（progesterone）主要來自下列何種組織分泌？","options":["(A) 母親卵巢黃體（corpus luteum of maternal ovary）","(B) 母親腎上腺（maternal adrenal gland）","(C) 胎兒腎上腺（fetal adrenal gland）","(D) 胎盤（placenta）"],"answer":3,"image":""},{"id":"md6-113-1-31","subject":"md6","topic":"產科-一般產科","meta":"113年第1次第31題","year":113,"session":1,"number":31,"question":"關於使用產鉗生產的先決條件，下列敘述何者最不適當？","options":["(A) 破水後方能使用","(B) 胎頭不需要engage到骨盆","(C) 子宮頸須開全","(D) 胎兒無已知的凝血功能病變"],"answer":1,"image":""},{"id":"md6-113-1-32","subject":"md6","topic":"產科-一般產科","meta":"113年第1次第32題","year":113,"session":1,"number":32,"question":"異常產程（產程遲滯）的處置，下列何者錯誤？","options":["(A) 當初胎的latent phase超過20小時，定義為prolonged latent phase","(B) 在非緊急狀況下，prolonged latent phase的處理方式，一般而言應考慮加oxytocin催生","(C) 初胎出現第一產程protraction disorders（子宮頸擴張＜1.2 cm/hr）時，應考慮觀察產程並給予支持","(D) 當第二產程出現arrest disorders超過兩小時，應評估是否有胎頭骨盆不對稱。若無，可給與oxytocin繼續催生"],"answer":1,"image":""},{"id":"md6-113-1-33","subject":"md6","topic":"產科-高危險妊娠","meta":"113年第1次第33題","year":113,"session":1,"number":33,"question":"有關胎盤早期剝離的臨床診斷，下列敘述何者錯誤？","options":["(A) 無痛性的陰道大量出血","(B) 胎心音減速","(C) 子宮明顯觸痛（uterine tenderness）","(D) 不到四分之一的產婦在超音波下，可見胎盤後方血塊"],"answer":0,"image":""},{"id":"md6-113-1-34","subject":"md6","topic":"產科-一般產科","meta":"113年第1次第34題","year":113,"session":1,"number":34,"question":"一位36歲G3P2之經產婦，懷孕38週住院待產，自訴一小時前開始規則宮縮，住院時子宮頸擴張約7公分，一小時後產下一名女嬰，下列何者是這位產婦最可能發生之風險？","options":["(A) 神經受傷（nerve injury）","(B) 子宮收縮無力（uterine atony）","(C) 滯留性胎盤（retained placenta）","(D) 膀胱功能異常（bladder dysfunction）"],"answer":1,"image":""},{"id":"md6-113-1-35","subject":"md6","topic":"產科-高危險妊娠","meta":"113年第1次第35題","year":113,"session":1,"number":35,"question":"一位31歲懷孕22週G2P1的孕婦，來產檢時超音波檢查發現如附圖。她前一胎於懷孕33週時自發性早產（spontaneous preterm），依她目前的狀況，下列何者是最適合的處置？","options":["(A) 子宮頸環紮術（cerclage placement）","(B) 每天給與aspirin 81 mg","(C) 給與陰道黃體素（vaginal progesterone）","(D) 給與安胎藥物"],"answer":0,"image":"md6-113-1-35.jpeg"},{"id":"md6-113-1-36","subject":"md6","topic":"產科-一般產科","meta":"113年第1次第36題","year":113,"session":1,"number":36,"question":"有一位35歲懷孕38週G2P1的孕婦，三年前因胎位不正接受剖腹生產，此胎她想要嘗試剖腹產後陰道分娩（trial of labor after cesareann delivery, TOLAC）。若與選擇性重複剖腹生生產（elective repeat cesarean delivery）比較，下列何者於TOLAC時對母體之風險（maternal complication）較不會增加？","options":["(A) 輸血（transfusion）","(B) 子宮切除（hysterectomy）","(C) 子宮感染（uterine infection）","(D) 子宮裂開（uterine dehiscence）"],"answer":1,"image":""},{"id":"md6-113-1-37","subject":"md6","topic":"產科-高危險妊娠","meta":"113年第1次第37題","year":113,"session":1,"number":37,"question":"孕婦患有妊娠糖尿病且需要使用胰島島素治療的相關敘述，下列何者最不適宜？","options":["(A) 胰島素起始劑量是0.7～1.0單位／／公斤／天","(B) 全部的胰島素都應該選擇長效的劑型，才能減少孕婦的負擔","(C) 飯後血糖值比飯前血糖值更有臨床意義","(D) 每天自我監控血糖值的孕婦產下巨嬰的比率明顯較低"],"answer":1,"image":""},{"id":"md6-113-1-38","subject":"md6","topic":"產科-高危險妊娠","meta":"113年第1次第38題","year":113,"session":1,"number":38,"question":"懷孕期間的高血壓用藥最不建議使用用下列何者？","options":["(A) 腎上腺素受體阻斷劑（adrenergic-receptor blocking agents）","(B) 血管擴張劑（vasodilators）","(C) 鈣離子通道阻斷劑（calcium-channel blocking agents）","(D) 血管張力素轉化酶抑制劑（angiotensin-converting enzyme inhibitors）"],"answer":3,"image":""},{"id":"md6-113-1-39","subject":"md6","topic":"產科-高危險妊娠","meta":"113年第1次第39題","year":113,"session":1,"number":39,"question":"關於妊娠肝內膽汁淤積症（intrahepatic cholestasis of pregnancy, ICP），最直接導致胎兒不良預後的孕婦血清異常為：","options":["(A) 膽汁酸（bile acids）","(B) 膽紅素（bilirubin）","(C) 鹼性磷酸酶（alkaline phosphatase）","(D) 丙胺酸轉胺酶（alanine aminotransferase, ALT）"],"answer":0,"image":""},{"id":"md6-113-1-40","subject":"md6","topic":"婦科-腫瘤","meta":"113年第1次第40題","year":113,"session":1,"number":40,"question":"下列選項何者較不適用於腹腔鏡微創手術？","options":["(A) 6公分漿液層下子宮肌瘤（subserosal myoma）","(B) 子宮外孕","(C) 不孕症手術","(D) 第二期子宮頸癌"],"answer":3,"image":""},{"id":"md6-113-1-41","subject":"md6","topic":"婦科-良性腫瘤與內膜異位","meta":"113年第1次第41題","year":113,"session":1,"number":41,"question":"43歲女性，G2P2，主訴平時月經來有經痛情形、經血量正常，近日未有不正常分泌物，CA125為67 U/mL，超音波檢查發現右側卵巢一均質低迴音之5公分囊腫；下列何者為最可能之診斷？","options":["(A) 輸卵管卵巢膿瘍（tubo-ovarian abscess）","(B) 卵巢之子宮內膜異位囊腫（endometrioma of ovary）","(C) 卵巢畸胎瘤（teratoma of ovary）","(D) 輸卵管之子宮外孕（tubal pregnancy）"],"answer":1,"image":""},{"id":"md6-113-1-42","subject":"md6","topic":"婦科-手術學與診斷技術","meta":"113年第1次第42題","year":113,"session":1,"number":42,"question":"子宮鏡可以用來診斷子宮腔內病灶，下列何者較少考慮使用子宮鏡來診斷？","options":["(A) 停經後不正常出血（postmenopausal bleeding）","(B) 習慣性流產（recurrent pregnancy loss）","(C) 輸卵管水腫（hydrosalpinx）","(D) 試管嬰兒胚胎植入的事前評估（assessment prior to embryo transfer）"],"answer":2,"image":""},{"id":"md6-113-1-43","subject":"md6","topic":"婦科-生殖道感染與先天異常","meta":"113年第1次第43題","year":113,"session":1,"number":43,"question":"外陰生殖器尖形濕疣（genital warts），最常導因於下列何種病毒的感染？","options":["(A) HPV 16, 18","(B) HPV 52, 58","(C) HPV 6, 11","(D) HPV 31, 45"],"answer":2,"image":""},{"id":"md6-113-1-44","subject":"md6","topic":"婦科-生殖道感染與先天異常","meta":"113年第1次第44題","year":113,"session":1,"number":44,"question":"對於細菌性陰道炎（bacterial vaginosis），下列何種治療較為有效？","options":["(A) metronidazole / clindamycin","(B) penicillin G","(C) gentamicin","(D) amoxicillin"],"answer":0,"image":""},{"id":"md6-113-1-45","subject":"md6","topic":"婦科-腫瘤","meta":"113年第1次第45題","year":113,"session":1,"number":45,"question":"自成熟的卵巢畸胎瘤（mature ovarian teratoma）中長出的惡性腫瘤，其中最常見的是：","options":["(A) serous cystadenocarcinoma","(B) clear cell carcinoma","(C) squamous cell carcinoma","(D) mucinous cystadenocarcinoma"],"answer":2,"image":""},{"id":"md6-113-1-46","subject":"md6","topic":"婦科-生殖道感染與先天異常","meta":"113年第1次第46題","year":113,"session":1,"number":46,"question":"下列何者是盛行率（prevalence rate）最高的婦女生殖道傳染病？","options":["(A) 人類乳突病毒（human papillomavirus, HPV）感染","(B) 單純性疱疹病毒（herpes simplex virus, HSV）感染","(C) 人類免疫缺乏病毒（human immunodeficiency virus, HIV）感染","(D) 梅毒（syphilis）"],"answer":0,"image":""},{"id":"md6-113-1-47","subject":"md6","topic":"婦科-良性腫瘤與內膜異位","meta":"113年第1次第47題","year":113,"session":1,"number":47,"question":"關於子宮內膜異位瘤（endometrioma）術後復發的敘述，下列何者錯誤？","options":["(A) 術後2年的復發率4～25%","(B) 術後使用口服避孕藥可以減少復發率","(C) 術後5年的復發率大於40%","(D) 右側骨盆有子宮內膜異位者，復發率較高"],"answer":3,"image":""},{"id":"md6-113-1-48","subject":"md6","topic":"婦科-腫瘤","meta":"113年第1次第48題","year":113,"session":1,"number":48,"question":"關於子宮頸內皮贅瘤（cervical intraepithelial neoplasia, CIN）及人類乳突病毒（HPV）的敘述，下列何者錯誤？","options":["(A) CIN 1在2年內消退為正常的機率大約在30%","(B) 子宮頸錐狀切片手術可以治療CIN 3或adenocarcinoma in situ","(C) CIN 2、CIN 3和invasive cervical cancer中最常見的人類乳突病毒是16型","(D) 大部分人類乳突病毒感染是暫時性感染，會在1年左右消失"],"answer":0,"image":""},{"id":"md6-113-1-49","subject":"md6","topic":"婦科-腫瘤","meta":"113年第1次第49題","year":113,"session":1,"number":49,"question":"有關卵巢生殖細胞腫瘤及其分泌的標記物質，下列何者錯誤？","options":["(A) dysgerminoma：AFP (-), hCG (-)","(B) immature teratoma：AFP (+), hCG (+)","(C) choriocarcinoma：AFP (-), hCG (+)","(D) endodermal sinus tumor：AFP (+), hCG (-)"],"answer":1,"image":""},{"id":"md6-113-1-50","subject":"md6","topic":"婦科-腫瘤","meta":"113年第1次第50題","year":113,"session":1,"number":50,"question":"30歲婦女，已結婚但未生小孩，抹片異常，內診發現子宮頸1 cm腫瘤，切片檢查結果為侵襲性鱗狀細胞癌（invasive squamous cell carcinoma），基質侵襲深度為5 mm，骨盆腔電腦斷層及膀胱鏡檢查正常。病人詢問可否保留生育能力，你的回答是：","options":["(A) 不可，不管有無淋巴腺或淋巴血管轉移，須接受子宮根除術（radical hysterectomy）","(B) 不可，不管有無淋巴腺或淋巴血管轉移，須接受放射線治療","(C) 可以，但須無淋巴腺或淋巴血管轉移，可行子宮頸部根除術（radical trachelectomy），保留子宮","(D) 可以，但須無淋巴腺或淋巴血管轉移，可行子宮頸圓錐切片，保留子宮"],"answer":2,"image":""},{"id":"md6-113-1-51","subject":"md6","topic":"婦科-腫瘤","meta":"113年第1次第51題","year":113,"session":1,"number":51,"question":"下列何者不是子宮內膜癌（endometrial carcinoma）的危險因子？","options":["(A) 肥胖","(B) 使用tamoxifen治療乳癌","(C) 單獨使用estrogen來治療停經後症候群","(D) 經產婦"],"answer":3,"image":""},{"id":"md6-113-1-52","subject":"md6","topic":"婦科-腫瘤","meta":"113年第1次第52題","year":113,"session":1,"number":52,"question":"感染人類乳突病毒（HPV）會導致子宮頸癌，機轉是因為HPV的病毒蛋白會經由和腫瘤抑制基因之相互作用而影響了細胞的生長和分化，下列何者是引發此致癌機轉的HPV病毒蛋白？","options":["(A) E1、E2","(B) E4、E5","(C) E6、E7","(D) L1、L2"],"answer":2,"image":""},{"id":"md6-113-1-53","subject":"md6","topic":"婦科-腫瘤","meta":"113年第1次第53題","year":113,"session":1,"number":53,"question":"關於上皮性卵巢癌的敘述，下列何者正確？","options":["(A) serous adenocarcinoma是最常見的細胞型態","(B) Type I是因雌激素過度刺激而誘發的癌症","(C) 大約25%的mucinous adenocarcinoma有BRCA 1/2的mutation","(D) 對所有的卵巢癌病人而言，化學治療都可以提高存活率"],"answer":0,"image":""},{"id":"md6-113-1-54","subject":"md6","topic":"婦科-生殖內分泌","meta":"113年第1次第54題","year":113,"session":1,"number":54,"question":"下列何者不屬於輔助生殖科技（assisted reproductive technology, ART）？","options":["(A) 體外受精（in vitro fertilization, IVF）","(B) 配子輸卵管內植入（gamete intrafallopian transfer, GIFT）","(C) 人工授精（intrauterine insemination, IUI）","(D) 胚胎著床前遺傳檢驗（pre-implantation genetic testing, PGT）"],"answer":2,"image":""},{"id":"md6-113-1-55","subject":"md6","topic":"婦科-生殖內分泌","meta":"113年第1次第55題","year":113,"session":1,"number":55,"question":"有關青春期之前的陰道出血，下列敘述何者錯誤？","options":["(A) 出血來源必須同時考慮泌尿道及腸胃道的病因","(B) 出血若要區別是否為性早熟所致，可以先檢查乳房或恥毛是否有發育，若無發育，則可排除此診斷","(C) 陰道內發現置入異物，或是外陰部有受傷，均須考量是否為性侵害所造成","(D) 陰道口發現有紅色易出血凸出腫塊，有可能是尿道口脫垂或是陰道內橫紋肌惡性肉瘤"],"answer":1,"image":""},{"id":"md6-113-1-56","subject":"md6","topic":"婦科-生殖內分泌","meta":"113年第1次第56題","year":113,"session":1,"number":56,"question":"有關泌乳激素分泌的敘述，下列何者正確？","options":["(A) 高泌乳激素的成因可能是受到甲狀腺的分泌增加所影響","(B) 泌乳激素分泌主要是由下視丘分泌多巴胺所控制","(C) 一般懷孕過程會造成泌乳激素分泌上升，因此需要持續監測泌乳激素","(D) 當高泌乳激素伴隨腦下垂體腺瘤時，不建議產後授乳"],"answer":1,"image":""},{"id":"md6-113-1-57","subject":"md6","topic":"婦科-尿失禁與骨盆腔脫垂","meta":"113年第1次第57題","year":113,"session":1,"number":57,"question":"關於婦女尿失禁之敘述，下列何者錯誤？","options":["(A) 白種人有較高的應力性尿失禁（stress urinary incontinence）盛行率","(B) 胎次（parity）對急迫性尿失禁（urgency urinary incontinence）的影響較小，並非其危險因子","(C) 應力性尿失禁（stress urinary incontinence）最高的盛行率是在50歲左右","(D) 隨著年齡增長，年紀愈大，應力性尿失禁（stress urinary incontinence）發生率也愈高"],"answer":3,"image":""},{"id":"md6-113-1-58","subject":"md6","topic":"喉科學與頭頸腫瘤","meta":"113年第1次第58題","year":113,"session":1,"number":58,"question":"有關正常的吞嚥咽部期（pharyngeal phase），下列敘述何者最不適當？","options":["(A) 吞嚥反射約一秒內完成","(B) 食團接觸咽門弓或後咽壁即開啟吞嚥反射","(C) 軟腭（soft palate）後縮","(D) 環咽肌於吞嚥反射發生時應關閉"],"answer":3,"image":""},{"id":"md6-113-1-59","subject":"md6","topic":"復健-神經復健","meta":"113年第1次第59題","year":113,"session":1,"number":59,"question":"有關脊髓損傷的布朗－斯夸氏症候群（Brown-Séquard syndrome），下列敘述何者最適當？","options":["(A) 受傷同側溫、痛覺會有所喪失","(B) 受傷對側的本體感覺受損","(C) 大部分病人可恢復獨立行走","(D) 受傷對側運動功能受損較嚴重"],"answer":2,"image":""},{"id":"md6-113-1-60","subject":"md6","topic":"復健-兒童與一般復健","meta":"113年第1次第60題","year":113,"session":1,"number":60,"question":"根據2016年美國國家壓瘡諮詢委員會的分級，當病人的全皮層缺損，在潰爛處可以看見脂肪組織且有肉芽形成，但肌腱及軟骨沒有暴露應屬於下列何分級？","options":["(A) 第二級","(B) 第三級","(C) 第四級","(D) 第五級"],"answer":1,"image":""},{"id":"md6-113-1-61","subject":"md6","topic":"復健-神經復健","meta":"113年第1次第61題","year":113,"session":1,"number":61,"question":"下列何者不是「前大腦動脈中風」常見之臨床症狀？","options":["(A) 伸展性僵硬（paratonic rigidity）","(B) 尿失禁（urinary incontinence）","(C) 行為改變（behavioral changes）","(D) 失讀症（alexia）"],"answer":3,"image":""},{"id":"md6-113-1-62","subject":"md6","topic":"復健-骨骼肌肉損傷與疾患","meta":"113年第1次第62題","year":113,"session":1,"number":62,"question":"有關肘外側上髁炎，下列敘述何者最不適當？","options":["(A) 最常見的原因為橈側屈腕肌和總伸指肌病變","(B) 應避免患部的重複性過度使用","(C) 在軟組織超音波檢查，可能發現在病灶處有肌腱低回音成像","(D) 可使用口服抗發炎藥物治療"],"answer":0,"image":""},{"id":"md6-113-1-63","subject":"md6","topic":"復健-骨骼肌肉損傷與疾患","meta":"113年第1次第63題","year":113,"session":1,"number":63,"question":"有關用「和平（PEACE）」面對軟組織損傷新原則的敘述，下列何者錯誤？","options":["(A) P：protect","(B) E：elevate","(C) A：avoid movement","(D) C：compression"],"answer":2,"image":""},{"id":"md6-113-1-64","subject":"md6","topic":"復健-截肢與義肢輔具","meta":"113年第1次第64題","year":113,"session":1,"number":64,"question":"義肢配置及訓練（prosthetic fitting and training）成功與否受多項因素影響。有關義肢配置之不良因子，不包括下列何者？","options":["(A) 高位截肢（higher levels of limb amputation）","(B) 年齡小於60歲（＜60 years old）","(C) 失智或合併認知問題（dementia or cognitive disorders）","(D) 傷口延遲癒合（delay in wound healing）"],"answer":1,"image":""},{"id":"md6-113-1-65","subject":"md6","topic":"復健-心肺復健與運動處方","meta":"113年第1次第65題","year":113,"session":1,"number":65,"question":"使用6分鐘行走測試來評估肺部功能障礙的病人，下列敘述何者最恰當？","options":["(A) 主要是運用在功能性活動的評估，常被使用在心肺疾病患者的運動耐力評估","(B) 本測試可以反映病人心肺功能的變化，較不適用於評估肌肉骨骼系統與心血管疾病之間交互作用的效果","(C) 執行的過程容易、安全，測試的流程與細節通常因人而異，沒有硬性的規範","(D) 測試的場所長度要30公尺，軟性地板的走廊為佳，以免對於膝關節造成傷害"],"answer":0,"image":""},{"id":"md6-113-1-66","subject":"md6","topic":"復健-兒童與一般復健","meta":"113年第1次第66題","year":113,"session":1,"number":66,"question":"下列何種反射（reflex）在正常兒童持續最久？","options":["(A) 降落傘反射（parachute reflex）","(B) 手掌抓握反射（palmar grasp reflex）","(C) 不對稱張力頸部反射（asymmetric tonic neck reflex）","(D) 莫洛氏反射（Moro reflex）"],"answer":0,"image":""},{"id":"md6-113-1-67","subject":"md6","topic":"復健-兒童與一般復健","meta":"113年第1次第67題","year":113,"session":1,"number":67,"question":"關於腦性麻痺（cerebral palsy），下列敘述何者錯誤？","options":["(A) 痙攣型（spastic type）腦性麻痺為最常見的型態","(B) 半邊麻痺型（hemiplegic type）幾乎都可以獨立行走","(C) 早產（prematurity）最常導致的腦性麻痺型態為四肢麻痺型（quadriplegic type）","(D) 腦性麻痺常出現肌肉骨骼系統（musculoskeletal system）的提早老化"],"answer":2,"image":""},{"id":"md6-113-1-68","subject":"md6","topic":"復健-兒童與一般復健","meta":"113年第1次第68題","year":113,"session":1,"number":68,"question":"根據世界衛生組織的定義，大於65歲以上人口占全人口多少百分比稱為「高齡社會」？","options":["(A) 7%","(B) 14%","(C) 20%","(D) 30%"],"answer":1,"image":""},{"id":"md6-113-1-69","subject":"md6","topic":"復健-兒童與一般復健","meta":"113年第1次第69題","year":113,"session":1,"number":69,"question":"對於老年復健目標的敘述，下列何者最適當？","options":["(A) 老年人在職業因素上的考量較重要，重視就業訓練問題","(B) 不論短期或長期，要維持功能、增加生活品質及減少依賴與被照顧","(C) 較不需偏重於獨立生活、社交與娛樂","(D) 在長期方面，才需要考量精神、疾病以及體能因素的影響"],"answer":1,"image":""},{"id":"md6-113-1-70","subject":"md6","topic":"復健-骨骼肌肉損傷與疾患","meta":"113年第1次第70題","year":113,"session":1,"number":70,"question":"乳癌病人接受手術治療後最常見的肩部失能，最容易受限的是肩關節的那一個角度？","options":["(A) 外展（abduction）","(B) 內收（adduction）","(C) 內旋（internal rotation）","(D) 外旋（external rotation）"],"answer":0,"image":""},{"id":"md6-113-1-71","subject":"md6","topic":"復健-物理因子治療與評估","meta":"113年第1次第71題","year":113,"session":1,"number":71,"question":"有關軟組織疼痛之處置，下列何者最不恰當？","options":["(A) 冷敷（cold pack）可防止繼續出血及過度之炎性反應，因此適用於急性與慢性發炎時期","(B) 熱敷（hot pack）可促進局部循環及癒合作用，並可使肌肉放鬆","(C) 熱敷（hot pack）不可使用於出血時、急性發炎、急性感染、惡性腫瘤時","(D) 非類固醇類消炎止痛藥（NSAIDs）一般對於慢性發炎的效果不如急性期來的好"],"answer":0,"image":""},{"id":"md6-113-1-72","subject":"md6","topic":"復健-兒童與一般復健","meta":"113年第1次第72題","year":113,"session":1,"number":72,"question":"下列何者最需要安排吞嚥影像檢查？","options":["(A) 80歲女性偶發吞嚥不順，無明顯惡化","(B) 60歲男性吞嚥固體食物時容易卡住，且症狀逐漸加劇","(C) 新生兒溢奶","(D) 20歲女性突發胸悶灼熱感"],"answer":1,"image":""},{"id":"md6-113-1-73","subject":"md6","topic":"復健-神經復健","meta":"113年第1次第73題","year":113,"session":1,"number":73,"question":"關於肌纖維發育不全（fibromuscular dysplasia）的敘述，下列何者最恰當？","options":["(A) 頸動脈較腎動脈更常見","(B) 頸動脈病灶易發生在頸動脈分支處（carotid bifurcation）","(C) 血管攝影檢查可發現串珠狀（string of beads）擴張及狹窄","(D) 男性較女性多"],"answer":2,"image":""},{"id":"md6-113-1-74","subject":"md6","topic":"婦科-腫瘤","meta":"113年第1次第74題","year":113,"session":1,"number":74,"question":"37歲女性病人經電腦斷層檢查，發現現影像中箭號所指處有結腸肝彎處腫瘤阻塞，合併右側卵巢多囊性腫瘤，下列有關卵巢的診斷何者最恰當？","options":["(A) cystadenoma","(B) Krukenberg tumor","(C) endometrioma","(D) dermoid cyst"],"answer":1,"image":"md6-113-1-74.jpeg"},{"id":"md6-113-1-75","subject":"md6","topic":"耳科學","meta":"113年第1次第75題","year":113,"session":1,"number":75,"question":"惡性外耳炎（malignant external otitis）會造成顱底骨髓炎（skull base osteomyelitis），下列敘述何者最適當？","options":["(A) 大部分個案使用抗生素治療即可","(B) 最常引發的致病菌是肺炎雙球菌","(C) C反應蛋白（C reactive protein））指數上升可確診","(D) 最常造成第八對腦神經病變"],"answer":0,"image":""},{"id":"md6-113-1-76","subject":"md6","topic":"鼻科學","meta":"113年第1次第76題","year":113,"session":1,"number":76,"question":"關於鼻腔內異物，下列敘述何者最不不適當？","options":["(A) 好發於兒童，也可發生於智能不足或罹患精神疾病的成人","(B) 兒童的鼻腔內異物，大部分是無症狀","(C) 鼻腔內之鈕扣電池卡住鼻通道，應使用鼻滴劑潤滑，並儘快取出電池","(D) 鼻腔內之鈕扣電池常不易經由目視發現，如懷疑可考慮照X光輔助診斷"],"answer":2,"image":""},{"id":"md6-113-1-77","subject":"md6","topic":"眼科-角膜結膜眼瞼眼窩","meta":"113年第1次第77題","year":113,"session":1,"number":77,"question":"關於眼科急症，下列敘述何者最正確確？","options":["(A) 最常發生眼窩骨折（orbital bloww-out fracture）的位置是在眼窩的上壁（uppper wall）部位","(B) 紫外線角膜炎（ultraviolet keratitis）造成的角膜傷害，可使用局部睫狀肌麻麻痺劑（cycloplegics）及抗生素治療","(C) 戴隱形眼鏡後出現眼瞼紅且有黏液膿性分泌物時，使用紅黴素是最適合的眼藥膏膏","(D) 甲醇中毒病人，除造成急性視力減損或喪失外，會引發嚴重眼睛疼痛"],"answer":1,"image":""},{"id":"md6-113-1-78","subject":"md6","topic":"婦科-腫瘤","meta":"113年第1次第78題","year":113,"session":1,"number":78,"question":"33歲已婚女性未育有兒女，因異常抹片進一步檢查後，診斷為子宮頸鱗狀上皮細胞癌IA1期，病人仍有生育考量，惟考慮影響後續治療，下列臨床建議何者最適當？","options":["(A) 建議立即懷孕，生產時同時進行子宮切除，避免癌症擴散","(B) 癌症為重大疾病，應立即進行子宮切除","(C) 建議切除子宮，然後以代理孕母孕育下一代","(D) 考量為初期子宮頸癌，建議做子宮頸圓錐狀切除及密集追蹤"],"answer":3,"image":""},{"id":"md6-113-1-79","subject":"md6","topic":"醫學倫理與法規","meta":"113年第1次第79題","year":113,"session":1,"number":79,"question":"一般醫學研究中所指的易受傷害族群，下列何者最不符合？","options":["(A) 兒童","(B) 孕婦","(C) 老人","(D) 末期患者"],"answer":2,"image":""},{"id":"md6-113-1-80","subject":"md6","topic":"醫學倫理與法規","meta":"113年第1次第80題","year":113,"session":1,"number":80,"question":"臨床發現女病患疑似多次遭受家庭暴力情事，病患坦承其丈夫偶會暴力相向，但擔心事件曝光將影響家庭關係，請求醫師不要通報相關單位，在此種情況下，下列處置何者最適宜？","options":["(A) 考慮到病人隱私，醫師不得通報","(B) 考慮到病人安全，醫師應立即通報","(C) 為兼顧病人隱私與安全，醫師可請病患朋友通報","(D) 暫時不進行通報，將病人收住院以避免進一步傷害"],"answer":1,"image":""},{"id":"md6-113-2-1","subject":"md6","topic":"麻醉-呼吸道與監視","meta":"113年第2次第1題","year":113,"session":2,"number":1,"question":"呼吸道的處置中，有些情況風險性特別高，應該要有預先的警覺。下列關於這些情況的描述，何者錯誤？","options":["(A) 以發生機率而言，全身麻醉過程中，手術拔管後與恢復期發生吸入性肺炎的機率高於麻醉誘導期（induction of anesthesia）","(B) 對於預期性困難插管的病患，可採取局部麻醉（topical anesthesia）之下進行清醒插管（awake intubation）","(C) 儘管已經進行過麻醉前呼吸道評估，麻醉誘導期發生非預期性困難插管的情況仍在所難免，因此必須事先備妥困難插管應變流程（algorithms for the management of unanticipated difficult intubation）","(D) 「無法插管，且無法通氣（cannot intubate, cannot ventilate）」是指無法以非侵入性方法進行通氣，而又無法進行插管的緊急情況"],"answer":0,"image":""},{"id":"md6-113-2-2","subject":"md6","topic":"麻醉-呼吸道與監視","meta":"113年第2次第2題","year":113,"session":2,"number":2,"question":"以腦電圖（electroencephalogram, EEG）為基礎的監測，有關bispectral index（BIS）監測，其結果代表之意義，下列何者錯誤？","options":["(A) BIS 100代表清醒","(B) BIS 40～60時，產生回憶（recall）的機率低，可減少術中awareness的風險","(C) 腦波burst suppresion時，BIS的數值通常呈現為40","(D) BIS是consciousness level的監測，不能完全代表麻醉深度"],"answer":2,"image":""},{"id":"md6-113-2-3","subject":"md6","topic":"麻醉-呼吸道與監視","meta":"113年第2次第3題","year":113,"session":2,"number":3,"question":"麻醉誘導並執行氣管插管後，Pulse oximetry顯示97%，接上潮氣末二氧化碳（end-tidal CO2）監測，出現圖形如下，下列後續處置何項最適宜？","options":["(A) 懷疑氣管內管阻塞，準備抽吸","(B) 懷疑食道內插管，準備再重新插管","(C) 換新的soda lime，以利吸收二氧化碳","(D) 懷疑插管位置過深，造成單肺通氣，準備外移氣管內管"],"answer":1,"image":"md6-113-2-3.jpeg"},{"id":"md6-113-2-4","subject":"md6","topic":"麻醉-麻醉藥理","meta":"113年第2次第4題","year":113,"session":2,"number":4,"question":"Sugammadex是肌肉鬆弛劑專用的拮抗劑，其對下列何種非去極化神經肌肉阻斷劑具有專一性？","options":["(A) rocuronium","(B) cisatracurium","(C) mivacurium","(D) pancuronium"],"answer":0,"image":""},{"id":"md6-113-2-5","subject":"md6","topic":"麻醉-麻醉藥理","meta":"113年第2次第5題","year":113,"session":2,"number":5,"question":"下列有關吸入性麻醉劑的敘述，何者錯誤？","options":["(A) 其效力（potency）與其脂溶性之間有良好相關性","(B) 大多具有血管舒張的效用","(C) desflurane可用於低流量麻醉","(D) 其最低肺泡濃度（minimum alveolar concentration）不受年齡影響"],"answer":3,"image":""},{"id":"md6-113-2-6","subject":"md6","topic":"麻醉-特殊麻醉與疼痛","meta":"113年第2次第6題","year":113,"session":2,"number":6,"question":"執行脊椎麻醉（spinal anesthesia），也就是一般所謂的半身麻醉，當穿刺針最後穿過那一層結構時，才會見到腦脊髓液（cerebrospinal fluid）流出？","options":["(A) dura mater硬脊膜","(B) arachnoid mater蜘蛛網膜","(C) pia mater軟腦膜","(D) ligamentum flavum黃韌帶"],"answer":1,"image":""},{"id":"md6-113-2-7","subject":"md6","topic":"麻醉-特殊麻醉與疼痛","meta":"113年第2次第7題","year":113,"session":2,"number":7,"question":"95歲高齡病患因手腕骨折，骨科醫師預計進行骨折復位手術（open reduction and internal fixation），麻醉醫師準備進行區域麻醉（regional anesthesia）以降低全身麻醉（general anesthesia）可能之風險，下列有關區域麻醉的敘述何者正確？","options":["(A) 應優先考慮進行interscalene brachial plexus block","(B) 若手術時間預計為45分鐘，則可以考慮使用作用時間較短的bupivacaine，以便於手術後評估神經學功能","(C) brachial plexus block若是以注射lidocaine執行，約可在5分鐘以內達到麻醉效果開始手術","(D) brachial plexus block使用lidocaine與少量sodium bicarbonate混和鹼化，可以加速onset"],"answer":3,"image":""},{"id":"md6-113-2-8","subject":"md6","topic":"麻醉-特殊麻醉與疼痛","meta":"113年第2次第8題","year":113,"session":2,"number":8,"question":"下列有關慢性疼痛的相關名詞定義，何者錯誤？","options":["(A) allodynia：對非傷害性（nonnoxious）的刺激感受為疼痛","(B) hyperalgisia：對傷害性（noxious）的刺激反應加劇","(C) analgesia：對所有知覺皆無反應","(D) paresthesia：無明顯刺激狀態下卻感受異樣知覺"],"answer":2,"image":""},{"id":"md6-113-2-9","subject":"md6","topic":"麻醉-特殊麻醉與疼痛","meta":"113年第2次第9題","year":113,"session":2,"number":9,"question":"目前關於敗血症（sepsis）的治療方法，下列何者在實證上對預後有幫助？","options":["(A) 以「早期目標引導治療法（early goal-directed therapy）」，優先給與足夠的輸液，來維持平均血壓＞ 90 mmHg","(B) 以「加強胰島素治療（intensive insulin therapy）」，來控制血糖低於180 mg/dL","(C) 給與高劑量類固醇，可抑制全身性發炎反應，降低90天死亡率","(D) 給與腎性劑量（renal-dose）的dopamine，可增加尿量，減少住院洗腎率"],"answer":1,"image":""},{"id":"md6-113-2-10","subject":"md6","topic":"眼科-視網膜葡萄膜","meta":"113年第2次第10題","year":113,"session":2,"number":10,"question":"有關年齡相關黃斑部退化（age-related macular degeneration）之敘述，下列何者錯誤？","options":["(A) 乾性（dry type）較濕性（wet type）常見","(B) 濕性（wet type）較乾性（dry type）容易造成視力損失","(C) 盛行率隨著年齡增加，很少發生於70歲以下病患","(D) 是已開發國家造成不可逆視力喪失最常見的原因"],"answer":2,"image":""},{"id":"md6-113-2-11","subject":"md6","topic":"眼科-視網膜葡萄膜","meta":"113年第2次第11題","year":113,"session":2,"number":11,"question":"有關裂孔性視網膜剝離徵候之敘述，下列何者錯誤？","options":["(A) 和正常眼睛相比，眼壓通常會高大約5毫米汞柱（mmHg）","(B) 廣泛性的視網膜剝離會出現馬格恩氏瞳孔（Marcus Gunn pupil）","(C) 輕微的虹彩炎（iritis）是非常普遍的","(D) 在前玻璃體經常可見類似菸草灰（tobacco dust）的色素細胞"],"answer":0,"image":""},{"id":"md6-113-2-12","subject":"md6","topic":"眼科-角膜結膜眼瞼眼窩","meta":"113年第2次第12題","year":113,"session":2,"number":12,"question":"有關疱疹病毒所造成的眼球表面感染，下列敘述何者錯誤？","options":["(A) 可由單純性疱疹病毒1或2型所造成","(B) 可影響虹彩及小樑導致眼壓升高","(C) 可出現上皮樹枝狀角膜炎","(D) 感染治癒後，不再復發"],"answer":3,"image":""},{"id":"md6-113-2-13","subject":"md6","topic":"眼科-水晶體青光眼","meta":"113年第2次第13題","year":113,"session":2,"number":13,"question":"手術前為正視眼（emmetropia）的病人，取出白內障若不置入人工水晶體，病人術後會有：","options":["(A) 高度近視","(B) 高度遠視","(C) 高度散光","(D) 仍為正視眼"],"answer":1,"image":""},{"id":"md6-113-2-14","subject":"md6","topic":"眼科-水晶體青光眼","meta":"113年第2次第14題","year":113,"session":2,"number":14,"question":"口服碳酸酐酶抑制劑（carbonic anhydrase inhibitor）是一種常用於快速降眼壓的藥物，關於其敘述何者錯誤？","options":["(A) 容易在肢體末端產生針刺感（paraesthesia）","(B) 容易造成高血鉀症","(C) 使用前須注意病患是否對磺胺類藥物過敏","(D) 目前已有局部眼用的碳酸酐酶抑制劑眼藥水可以使用，但降眼壓效果較差"],"answer":1,"image":""},{"id":"md6-113-2-15","subject":"md6","topic":"眼科-角膜結膜眼瞼眼窩","meta":"113年第2次第15題","year":113,"session":2,"number":15,"question":"四個月大的女嬰，媽媽注意到她有溢淚的情況，內眼角常有黃綠色的黏稠分泌物，尤其是按摩內眼角與鼻骨之間的部位，會有更多的分泌物出現。下列敘述何者正確？","options":["(A) 最有可能的診斷是先天性青光眼","(B) 淚小管（canaliculus）進入淚囊（lacrimal sac）的部分（valve of Rosenmüller）是最常見的阻塞位置","(C) 一歲前靠按摩自行痊癒的機會是50%","(D) 鼻淚管在鼻內的出口位於下鼻道（inferior nasal meatus）"],"answer":3,"image":""},{"id":"md6-113-2-16","subject":"md6","topic":"眼科-屈光斜弱視","meta":"113年第2次第16題","year":113,"session":2,"number":16,"question":"下列何者不是造成遮蔽性弱視（deprivation amblyopia）的可能原因？","options":["(A) 雙眼眼瞼下垂（ptosis）","(B) 右眼內斜視（esotropia）","(C) 單眼白內障（cataract）","(D) 左眼上眼瞼毛細血管瘤（capillary hemangioma）"],"answer":1,"image":""},{"id":"md6-113-2-17","subject":"md6","topic":"眼科-角膜結膜眼瞼眼窩","meta":"113年第2次第17題","year":113,"session":2,"number":17,"question":"有關甲狀腺眼病變（Graves' ophthalmopathy）的敘述，下列何者錯誤？","options":["(A) 將甲狀腺功能指數控制到甲狀腺功能低下（hypothyroidism），有助於甲狀腺眼病變的預防與治療","(B) 是成年人單側或雙側凸眼（proptosis）的主要成因","(C) 患者若產生眼瞼下垂（ptosis），要懷疑是否合併有重症肌無力（myasthenia gravis）","(D) 接受放射碘（radioactive iodine）治療甲狀腺功能亢進（hyperthyroidism）的患者，其原本活性期眼病變（active Graves' ophthalmopathy）可能會加重"],"answer":0,"image":""},{"id":"md6-113-2-18","subject":"md6","topic":"眼科-視網膜葡萄膜","meta":"113年第2次第18題","year":113,"session":2,"number":18,"question":"六個月男嬰右眼瞳孔區呈現白色反光，看來像貓眼一樣，結膜紅腫，流淚哭鬧。下列何項檢查最不需要？","options":["(A) 眼球超音波","(B) 眼窩電腦斷層","(C) 間接眼底鏡檢查","(D) 視網膜光學斷層掃描儀（optical coherence tomography, OCT）"],"answer":3,"image":""},{"id":"md6-113-2-19","subject":"md6","topic":"耳科學","meta":"113年第2次第19題","year":113,"session":2,"number":19,"question":"某夏日一病人主訴耳朵癢痛，檢查發現如圖，最可能診斷為下列何者？","options":["(A) 急性中耳炎","(B) 黴菌性外耳炎","(C) 慢性中耳炎","(D) 積液性中耳炎"],"answer":1,"image":"md6-113-2-19.jpeg"},{"id":"md6-113-2-20","subject":"md6","topic":"耳科學","meta":"113年第2次第20題","year":113,"session":2,"number":20,"question":"下列那一類病人植入人工電子耳及復健後，語音辨識度最差？","options":["(A) 習語前失聰之小孩","(B) 習語前失聰之成人","(C) 習語後失聰之小孩","(D) 習語後失聰之成人"],"answer":1,"image":""},{"id":"md6-113-2-21","subject":"md6","topic":"耳科學","meta":"113年第2次第21題","year":113,"session":2,"number":21,"question":"關於上半規管裂隙症（superior semicircular canal dehiscence syndrome）的Tullio phenomenon，係指下列何項敘述？","options":["(A) 內耳產生第三個活動窗（third window）","(B) 外耳道音壓變化可引發眼震（nystagmus）","(C) 病人對聽覺敏感（hyperacusis）","(D) 在低頻率產生一個氣骨導差"],"answer":1,"image":""},{"id":"md6-113-2-22","subject":"md6","topic":"鼻科學","meta":"113年第2次第22題","year":113,"session":2,"number":22,"question":"有關嗅覺異常（olfactory dysfunction）的原因，下列何者最不常見？","options":["(A) 病毒性上呼吸道感染","(B) 頭部外傷","(C) 鼻竇疾病","(D) 中樞神經腫瘤"],"answer":3,"image":""},{"id":"md6-113-2-23","subject":"md6","topic":"鼻科學","meta":"113年第2次第23題","year":113,"session":2,"number":23,"question":"有關過敏性黴菌性鼻竇炎（allergic fungal rhinosinusitis）之特徵，下列敘述何者錯誤？","options":["(A) 組織病理的特徵是嗜中性球浸潤（infiltration of neutrophil）","(B) 電腦斷層影像會出現病灶中有hyperattenuation現象","(C) 常出現骨重塑（bone remodeling）現象","(D) 常出現骨侵蝕（bone erosion）現象"],"answer":0,"image":""},{"id":"md6-113-2-24","subject":"md6","topic":"喉科學與頭頸腫瘤","meta":"113年第2次第24題","year":113,"session":2,"number":24,"question":"臨床上常以改良式鋇劑吞嚥檢查（modified barium swallow, MBS）及軟式內視鏡吞嚥檢查（fiberoptic endoscopic evaluation of swallowing, FEES）測試吞嚥功能。有關FEES優於MBS的特點，不包括下列何項？","options":["(A) 無放射線暴露且隨處可以執行","(B) 可以測試各種不同黏稠度的食物","(C) 可以合併感覺測試（sensory testing）","(D) 對於判斷是否有腭咽閉鎖不全（velopharyngeal incompetence）較為準確"],"answer":1,"image":""},{"id":"md6-113-2-25","subject":"md6","topic":"喉科學與頭頸腫瘤","meta":"113年第2次第25題","year":113,"session":2,"number":25,"question":"32歲女性，無抽菸喝酒病史，主訴1個月前曾接受全身麻醉手術，之後出現咽喉疼痛、異物感、發聲不適等症狀。就診檢查時咽喉內視鏡之影像顯示如下圖，下列敘述何者正確？","options":["(A) 圖中異常部位在環狀軟骨（cricoid cartilage）","(B) 可能的成因為氣管內插管時所造成之傷害","(C) 口服抗生素適合作為第一線之治療","(D) 藥物反應不佳時，可安排外科手術切除，復發率低"],"answer":1,"image":"md6-113-2-25.jpeg"},{"id":"md6-113-2-26","subject":"md6","topic":"喉科學與頭頸腫瘤","meta":"113年第2次第26題","year":113,"session":2,"number":26,"question":"關於多發性內分泌腫瘤（multiple endocrine neoplasia, MEN），下列敘述何者錯誤？","options":["(A) MEN 1包含腦下腺、副甲狀腺及胰島素瘤","(B) MEN 2A與MEN 2B之共同特徵是甲狀腺髓質癌（medullary thyroid cancer）及副甲狀腺瘤","(C) MEN 2A與MEN 2B都是RET致癌基因之突變所致","(D) 甲狀腺髓質癌（medullary thyroid cancer）手術至少應包括全甲狀腺切除與中央淋巴結群廓清術"],"answer":1,"image":""},{"id":"md6-113-2-27","subject":"md6","topic":"喉科學與頭頸腫瘤","meta":"113年第2次第27題","year":113,"session":2,"number":27,"question":"上副甲狀腺（superior parathyroid gland）與下副甲狀腺（inferior parathyroid gland）之胚胎發育分別源自於第幾咽囊（pharyngeal pouch）？","options":["(A) 第一（superior parathyroid gland）；第二（inferior parathyroid gland）咽囊","(B) 第二（superior parathyroid gland）；第三（inferior parathyroid gland）咽囊","(C) 第三（superior parathyroid gland）；第四（inferior parathyroid gland）咽囊","(D) 第四（superior parathyroid gland）；第三（inferior parathyroid gland）咽囊"],"answer":3,"image":""},{"id":"md6-113-2-28","subject":"md6","topic":"產科-一般產科","meta":"113年第2次第28題","year":113,"session":2,"number":28,"question":"35歲女性第一次懷孕即在早期發生流產，下列何者是與第一孕期流產最相關的母體因素及胎兒染色體異常？","options":["(A) 子宮頸閉鎖不全／單染色體症X（monosomy X）","(B) 母親年齡／三染色體症（trisomy）","(C) 妊娠巨吐症（hyperemesis gravidarum）／三倍體（triploid）","(D) 子宮內感染／性染色體異常"],"answer":1,"image":""},{"id":"md6-113-2-29","subject":"md6","topic":"產科-一般產科","meta":"113年第2次第29題","year":113,"session":2,"number":29,"question":"28歲女性到門診作孕前諮商，她於一年前第一次懷孕，卻在妊娠18週時出現子宮頸閉鎖不全進而發生流產，她想瞭解預防性子宮頸環紮術，下列何者為這位女性接受預防性子宮頸環紮術的理想時間點以及施行預防性子宮頸環紮術的禁忌症？","options":["(A) 子宮頸一開始無痛性擴張時／之前接受過子宮頸圓錐狀切除手術","(B) 受孕之前／母親有糖尿病","(C) 於妊娠6～12週／高齡產婦","(D) 於妊娠12～16週／早期破水"],"answer":3,"image":""},{"id":"md6-113-2-30","subject":"md6","topic":"產科-一般產科","meta":"113年第2次第30題","year":113,"session":2,"number":30,"question":"下列何種情形不會造成懷孕時母親雌激素（estrogen）濃度降低？","options":["(A) 胎兒死亡（fetal demise）","(B) 胎兒胎盤硫酸酯酶缺乏（fetal-placental sulfatase deficiency）","(C) 唐氏症（Down syndrome）","(D) 胎兒骨髓成紅血細胞增多症（fetal erythroblastosis）"],"answer":3,"image":""},{"id":"md6-113-2-31","subject":"md6","topic":"產科-一般產科","meta":"113年第2次第31題","year":113,"session":2,"number":31,"question":"有關整體分娩（parturition）和產程（clinical stages of labor）的敘述，下列何者錯誤？","options":["(A) 第一產程指的是子宮收縮合併子宮頸擴張至子宮頸開全","(B) 第二產程指的是子宮頸開全到胎兒娩出","(C) 整體分娩始於孕後的靜止期（quiescence）","(D) 產程屬於整體分娩的活動期（activation phase）"],"answer":3,"image":""},{"id":"md6-113-2-32","subject":"md6","topic":"產科-一般產科","meta":"113年第2次第32題","year":113,"session":2,"number":32,"question":"一位35歲懷孕39週G2P1的經產婦，產檢時超音波檢查預估胎兒體重約4,050公克，下列敘述何者正確？","options":["(A) 巨嬰（fetal macrosomia）是導致肩難產之風險因子","(B) 儘快安排催生（elective induction）","(C) 超音波預估的胎兒體重，可以準確的預防肩難產","(D) 施行計畫性之剖腹生產（planned cesarean delivery）"],"answer":0,"image":""},{"id":"md6-113-2-33","subject":"md6","topic":"產科-一般產科","meta":"113年第2次第33題","year":113,"session":2,"number":33,"question":"不正常產程（abnormal labor patterns）中的產程拖延（protraction disorders）是指下列何者？","options":["(A) 活動期延長（prolonged active phase）","(B) 活動期擴張拖延（protracted active-phase dilation）","(C) 減速期延長（prolonged deceleration phase）","(D) 潛伏期拖延（protracted latent phase）"],"answer":1,"image":""},{"id":"md6-113-2-34","subject":"md6","topic":"產科-一般產科","meta":"113年第2次第34題","year":113,"session":2,"number":34,"question":"下列何者不屬於待產時的胎心音監測分類category III-abnormal？","options":["(A) marked baseline variability","(B) sinusoidal pattern","(C) recurrent late decelerations","(D) recurrent variable decelerations"],"answer":0,"image":""},{"id":"md6-113-2-35","subject":"md6","topic":"產科-一般產科","meta":"113年第2次第35題","year":113,"session":2,"number":35,"question":"許多可能造成胎兒心搏過速（tachycardia）的原因中，最常見的為下列何者？","options":["(A) 藥物造成（drug-induced）","(B) 甲狀腺風暴（thyroid storm）","(C) 母親發燒（maternal fever）","(D) 胎兒心律不整（fetal cardiac arrhythmia）"],"answer":2,"image":""},{"id":"md6-113-2-36","subject":"md6","topic":"產科-高危險妊娠","meta":"113年第2次第36題","year":113,"session":2,"number":36,"question":"22歲孕婦，G4P1SA2，妊娠32週，接受杜卜勒（Doppler）超音波檢查，結果如圖所示，檢查名稱為何？","options":["(A) 臍動脈血流杜卜勒超音波","(B) 胎兒下腔靜脈血流杜卜勒超音波","(C) 胎兒中大腦動脈血流杜卜勒超音波","(D) 胎兒下行主動脈血流杜卜勒超音波"],"answer":2,"image":"md6-113-2-36.jpeg"},{"id":"md6-113-2-37","subject":"md6","topic":"產科-高危險妊娠","meta":"113年第2次第37題","year":113,"session":2,"number":37,"question":"有關患有妊娠糖尿病孕婦的產後追蹤，下列敘述何者最適宜？","options":["(A) 美國婦產科醫學會（ACOG）建議，在產後4～12週時，應再做一次空腹血糖或75克口服葡萄糖耐量試驗（OGTT）","(B) 曾患有妊娠糖尿病的孕婦在懷孕後的未來20年內罹有糖尿病的機率跟一般正常的孕婦是一樣的","(C) 產後第一次追蹤的血糖值若正常，未來就不用再做任何血糖的檢測","(D) 有妊娠糖尿病的孕婦在未來因心血管疾病住院的風險跟一般孕婦相比是一樣的"],"answer":0,"image":""},{"id":"md6-113-2-38","subject":"md6","topic":"產科-高危險妊娠","meta":"113年第2次第38題","year":113,"session":2,"number":38,"question":"導致產科敗血症（sepsis syndrome in obstetrics）的病原菌（pathogens）中，最罕見的為：","options":["(A) 大腸桿菌（Escherichia coli）","(B) 糞腸球菌（Enterococcus faecalis）","(C) 肺炎克雷伯菌（Klebsiella pneumoniae）","(D) 李斯特菌（Listeria monocytogenes）"],"answer":3,"image":""},{"id":"md6-113-2-39","subject":"md6","topic":"產科-高危險妊娠","meta":"113年第2次第39題","year":113,"session":2,"number":39,"question":"30歲懷孕16週婦女，接受唐氏症母血篩檢，檢測結果唐氏症預估機率為1：820，母血α-胎兒蛋白（AFP）值為中位值（multiples of median, MoM）之3.8倍，下一步最合理的做法是：","options":["(A) 接受羊膜穿刺檢驗胎兒染色體","(B) 接受詳細胎兒超音波檢查","(C) 接受婦女骨盆腔超音波檢查以排除卵巢腫瘤","(D) 重複唐氏症母血篩檢以確認檢驗結果"],"answer":1,"image":""},{"id":"md6-113-2-40","subject":"md6","topic":"婦科-手術學與診斷技術","meta":"113年第2次第40題","year":113,"session":2,"number":40,"question":"關於腹腔鏡手術所使用的導氣針（insufflation needle），下列敘述何者最不適當？","options":["(A) 導氣針（insufflation needle）穿過腹壁時會有觸聽回饋感覺","(B) 瘦的病人以45度角插入","(C) 胖的病人以30度角插入","(D) 正確的針頭位置判斷的方法是由insufflator測得的初始腹膜內壓力小於8～10 mmHg"],"answer":2,"image":""},{"id":"md6-113-2-41","subject":"md6","topic":"婦科-手術學與診斷技術","meta":"113年第2次第41題","year":113,"session":2,"number":41,"question":"子宮鏡手術時，如果以生理食鹽水作為介質，其壓力最好不可高於患者的：","options":["(A) 平均動脈壓","(B) 收縮壓","(C) 舒張壓","(D) 顱內壓"],"answer":0,"image":""},{"id":"md6-113-2-42","subject":"md6","topic":"婦科-生殖內分泌","meta":"113年第2次第42題","year":113,"session":2,"number":42,"question":"有關先天性雄性素不敏感症（congenital androgen insensitivity）診斷，下列敘述何者最不適當？","options":["(A) 性別染色體為XY","(B) 因先天缺陷影響正常雄性素受體功能所引起","(C) 診斷主要依據身體理學檢查、血清睪固酮（testosterone）濃度和染色體核型（karyotype）","(D) 在身體理學檢查中，青春期患者會有乳房發育，短小陰莖，稀疏或缺乏腋毛及陰毛"],"answer":3,"image":""},{"id":"md6-113-2-43","subject":"md6","topic":"婦科-生殖道感染與先天異常","meta":"113年第2次第43題","year":113,"session":2,"number":43,"question":"有關骨盆腔發炎（pelvic inflammatory disease）門診病人的治療，下列何者為較不適宜的治療選項？","options":["(A) doxycycline","(B) azithromycin","(C) cephalosporin","(D) clotrimazole"],"answer":3,"image":""},{"id":"md6-113-2-44","subject":"md6","topic":"婦科-腫瘤","meta":"113年第2次第44題","year":113,"session":2,"number":44,"question":"下列有關子宮平滑肌瘤（uterine leiomyoma）的敘述，何者錯誤？","options":["(A) 漿膜下子宮平滑肌瘤（subserosal uterine leiomyoma）是造成不孕很常見的原因","(B) 子宮動脈栓塞（uterine artery embolization）可用於治療子宮平滑肌瘤","(C) 懷孕中發生子宮平滑肌瘤變性（red degeneration）多半不需要手術處理","(D) 黏膜下子宮平滑肌瘤（submucosal uterine leiomyoma）常常造成經血量增多（hypermenorrhea）的症狀"],"answer":0,"image":""},{"id":"md6-113-2-45","subject":"md6","topic":"婦科-良性腫瘤與內膜異位","meta":"113年第2次第45題","year":113,"session":2,"number":45,"question":"下列有關子宮內膜異位症藥物治療的敘述，何者錯誤？","options":["(A) progestins類藥物的副作用會造成體重增加及不規則子宮出血","(B) 持續使用口服避孕藥（oral contraceptives）會增加子宮內膜癌和卵巢癌之風險","(C) danazol藥物的副作用主要是多毛症和聲音低沉","(D) 長期使用gonadotropin-releasing hormone（GnRH）agonists會增加骨質疏鬆症之風險"],"answer":1,"image":""},{"id":"md6-113-2-46","subject":"md6","topic":"婦科-腫瘤","meta":"113年第2次第46題","year":113,"session":2,"number":46,"question":"下列何種卵巢腫瘤會造成體內雄性激素上升，而產生男性化症狀？","options":["(A) serous cystadenoma","(B) Sertoli-Leydig tumor","(C) ovarian endometrioma","(D) mature ovarian teratoma"],"answer":1,"image":""},{"id":"md6-113-2-47","subject":"md6","topic":"婦科-生殖道感染與先天異常","meta":"113年第2次第47題","year":113,"session":2,"number":47,"question":"細菌性陰道炎（bacterial vaginosis）的臨床診斷標準（Amsel Diagnostic Criteria），下列何者最不適當？","options":["(A) 陰道分泌物的細菌培養","(B) 魚腥樣的臭味","(C) 陰道的酸鹼度超過4.5","(D) 顯微鏡檢視之下可以看到被細菌黏附的陰道上皮細胞"],"answer":0,"image":""},{"id":"md6-113-2-48","subject":"md6","topic":"婦科-腫瘤","meta":"113年第2次第48題","year":113,"session":2,"number":48,"question":"關於子宮肌瘤的敘述，下列何者最正確？","options":["(A) 服用口服避孕藥的時間越長，子宮肌瘤的發生率越高","(B) 子宮肌瘤明顯地提高經痛的發生率","(C) 停經前女性子宮肌瘤快速長大（1年內長大相當於懷孕6週大小），顯著地增加子宮惡性肉瘤的可能性","(D) 切除intramural myoma並不會提高受孕率"],"answer":3,"image":""},{"id":"md6-113-2-49","subject":"md6","topic":"婦科-腫瘤","meta":"113年第2次第49題","year":113,"session":2,"number":49,"question":"有關卵巢內胚層竇瘤（endodermal sinus tumors）的敘述，下列何者正確？","options":["(A) 大多數患者屬尚未有初經的兒童","(B) 與上皮性卵巢癌類似，內胚層竇瘤生長緩慢，大多無臨床症狀","(C) 內胚層竇瘤影響單側卵巢，手術時不建議實施對側卵巢切片","(D) 內胚層竇瘤對輔助性化療或治療性化療反應不佳，通常不建議實施"],"answer":2,"image":""},{"id":"md6-113-2-50","subject":"md6","topic":"婦科-腫瘤","meta":"113年第2次第50題","year":113,"session":2,"number":50,"question":"46歲陳小姐，G3P2SA1，過去曾接受卵巢巧克力囊腫切除手術，因下腹疼痛到婦科門診就診，超音波發現15公分骨盆腔複雜性腫瘤，手術中病理冷凍切片證實為亮細胞卵巢癌（clear cell carcinoma），並發現腫瘤與一段小腸沾黏並有大腸侵犯，肝臟表面及橫膈膜下並沒有腫瘤轉移，有關患者的治療，下列何者正確？","options":["(A) 患者為第IV期卵巢癌","(B) 應向家屬說明腫瘤已向外擴散，無法再做手術切除，只能靠術後化學治療","(C) 患者應接受減積手術（包括部分小腸及大腸切除），術後應接受化學治療","(D) 患者應接受骨盆腔臟器剜除手術（包括膀胱、子宮及直腸全切除）"],"answer":2,"image":""},{"id":"md6-113-2-51","subject":"md6","topic":"婦科-腫瘤","meta":"113年第2次第51題","year":113,"session":2,"number":51,"question":"子宮內膜癌依照組織學型態可以區分為Type I及Type II，下列敘述何者正確？","options":["(A) Type I病人多是與多囊性卵巢囊腫疾病無關","(B) Type I病人大多預後較差","(C) Type I病人的基因表現多與p53有關","(D) Type I病人臨床的表徵以異常出血為多"],"answer":3,"image":""},{"id":"md6-113-2-52","subject":"md6","topic":"婦科-腫瘤","meta":"113年第2次第52題","year":113,"session":2,"number":52,"question":"關於partial hydatidiform mole的敘述，下列何者錯誤？","options":["(A) 染色體以三倍體（triploid）表現，多出的一套來自父親","(B) 相較於complete hydatidiform mole，更容易進展成侵襲性癌症","(C) 病理特徵可以看到胎兒組織","(D) 相較於complete hydatidiform mole，通常β-hCG level較低"],"answer":1,"image":""},{"id":"md6-113-2-53","subject":"md6","topic":"婦科-腫瘤","meta":"113年第2次第53題","year":113,"session":2,"number":53,"question":"關於IA2–IIA的早期子宮頸癌接受子宮根除手術後，下列何者不是復發的風險因子？","options":["(A) 子宮旁組織（parametrial）的顯微侵犯（microinvasion）","(B) 骨盆腔的淋巴轉移","(C) 子宮頸腫瘤細胞的壞死程度","(D) 子宮頸間質的侵犯深度（depth of stromal invasion）"],"answer":2,"image":""},{"id":"md6-113-2-54","subject":"md6","topic":"婦科-生殖內分泌","meta":"113年第2次第54題","year":113,"session":2,"number":54,"question":"關於人工生殖技術的敘述，下列何者錯誤？","options":["(A) 刺激排卵療程長療程可預防早發性LH surge","(B) 癌症病患欲保留生育機會，可治療前冷凍卵子或精子","(C) 習慣性流產的夫妻，無已知的染色體異常，可用著床前基因診斷（Preimplantation Genetic Diagnosis, PGD）以增加著床率","(D) 單一囊胚植入可降低多胞胎機率"],"answer":2,"image":""},{"id":"md6-113-2-55","subject":"md6","topic":"婦科-生殖內分泌","meta":"113年第2次第55題","year":113,"session":2,"number":55,"question":"關於使用藥物治療罹患多囊性卵巢婦女的描述，下列何者錯誤？","options":["(A) 單獨使用口服避孕藥就可以改善多毛症（hirsutism），成功機會高達八成","(B) cyproterone acetate可降低血雄性荷爾蒙，但有影響肝功能指數和增加罹患肝腫瘤的可能性","(C) gonadotropin-releasing hormone agonist及dexamethasone均有改善多毛與青春痘的作用","(D) 卵巢部分切除可以改善部分多囊性卵巢婦女的排卵功能"],"answer":0,"image":""},{"id":"md6-113-2-56","subject":"md6","topic":"婦科-生殖內分泌","meta":"113年第2次第56題","year":113,"session":2,"number":56,"question":"18歲門診患者在青春期一直沒有月經來潮，懷孕試驗為陰性，身體檢查發現有乳房發育，但是沒有腋毛或恥毛生成時，推測可能是下列何種診斷？","options":["(A) Mayer-Rokitansky-Küster-Hauser syndrome","(B) Androgen insensitivity syndrome","(C) 5α-reductase deficiency syndrome","(D) Kallmann syndrome"],"answer":1,"image":""},{"id":"md6-113-2-57","subject":"md6","topic":"婦科-尿失禁與骨盆腔脫垂","meta":"113年第2次第57題","year":113,"session":2,"number":57,"question":"關於尿失禁（urinary incontinence）的敘述，下列何者最不適當？","options":["(A) 年紀、肥胖、慢性咳嗽、曾骨盆腔手術為其危險因子","(B) 可以病史詢問、理學檢查、咳嗽測試及解尿後餘尿量測試來診斷","(C) 小便日記、尿液檢查、棉墊測試及尿路動力學檢查是簡單的診斷工具","(D) Q-tip測試已不再建議使用"],"answer":2,"image":""},{"id":"md6-113-2-58","subject":"md6","topic":"復健-神經復健","meta":"113年第2次第58題","year":113,"session":2,"number":58,"question":"有關脊髓損傷病人出現自主神經反射異常（autonomic dysreflexia）的臨床症狀，下列何者最不適切？","options":["(A) 血壓降低","(B) 冒汗","(C) 起雞皮疙瘩","(D) 頭痛"],"answer":0,"image":""},{"id":"md6-113-2-59","subject":"md6","topic":"復健-神經復健","meta":"113年第2次第59題","year":113,"session":2,"number":59,"question":"下列那一塊肌肉的高張力痙攣（spasticity）可能造成踝關節蹠屈（ankle plantarflexion）？","options":["(A) 腓長肌（peroneus longus）","(B) 脛前肌（tibialis anterior）","(C) 伸趾長肌（extensor hallucis longus）","(D) 腓腸肌（gastrocnemius）"],"answer":3,"image":""},{"id":"md6-113-2-60","subject":"md6","topic":"復健-神經復健","meta":"113年第2次第60題","year":113,"session":2,"number":60,"question":"有關椎底動脈基動脈症候群（vertebrobasilar syndromes），下列何者不是常見症狀？","options":["(A) 吞嚥困難（dysphagia）","(B) 構音障礙（dysarthria）","(C) 失語症（aphasia）","(D) 平衡困難（disequilibrium）"],"answer":2,"image":""},{"id":"md6-113-2-61","subject":"md6","topic":"復健-神經復健","meta":"113年第2次第61題","year":113,"session":2,"number":61,"question":"關於脊髓損傷之復健，不同部位之完全性脊髓損傷患者，經復健後有可能達到之最佳運動功能程度並不相同，下列敘述何者最不適當？","options":["(A) 第三頸髓損傷患者：通常需外加呼吸器以協助其呼吸","(B) 第五頸髓損傷患者：可使用屈肘肌矯具進行活動","(C) 第六頸髓損傷患者：可進行肱三頭肌之相關動作","(D) 第六胸髓損傷患者：可使用前臂枴杖或助行器"],"answer":2,"image":""},{"id":"md6-113-2-62","subject":"md6","topic":"復健-骨骼肌肉損傷與疾患","meta":"113年第2次第62題","year":113,"session":2,"number":62,"question":"關於肌少症（sarcopenia），下列敘述何者最不適當？","options":["(A) 男性肌肉量在50歲之後每十年降低約12～15%","(B) 女性的肌力衰退較晚發生，但速度較快","(C) 癌症，心、肺、肝及腎末期病變等疾病也會造成肌少症","(D) 肌少症會造成生活品質下降並增加死亡的機會"],"answer":1,"image":""},{"id":"md6-113-2-63","subject":"md6","topic":"復健-骨骼肌肉損傷與疾患","meta":"113年第2次第63題","year":113,"session":2,"number":63,"question":"有關梨狀肌症候群（piriformis syndrome），下列敘述何者最不適當？","options":["(A) 臨床表現為臀部深層的疼痛，有時合併腰痛或傳動放射麻痛感至腿腳","(B) 在臀部坐姿或站立姿勢不對時也會發作","(C) 理學檢查常發現臀部有局部痛點","(D) 在梨狀肌緊繃測試，將患側下肢屈曲、外展、外旋並施加壓力，即可誘發臀部及下肢的疼痛感"],"answer":3,"image":""},{"id":"md6-113-2-64","subject":"md6","topic":"復健-骨骼肌肉損傷與疾患","meta":"113年第2次第64題","year":113,"session":2,"number":64,"question":"下列何種變形最不常見於類風濕性關節炎（rheumatoid arthritis）的患者？","options":["(A) 鵝頸變形（swan-neck deformity）","(B) 鈕扣孔變形（boutonnière deformity）","(C) 赫伯登結（Heberden nodes）","(D) 手腕出現尺側偏斜（ulnar deviation）"],"answer":2,"image":""},{"id":"md6-113-2-65","subject":"md6","topic":"復健-心肺復健與運動處方","meta":"113年第2次第65題","year":113,"session":2,"number":65,"question":"冠狀動脈繞道手術（coronary artery bypass grafting）患者，接受心臟復健（cardiac rehabilitation）後可能獲得的好處，下列何者正確？","options":["(A) 降低缺血閾值（decreased ischemic threshold）","(B) 改善右心室功能（improved right ventricular function）","(C) 改善血清中的脂質（ameliorated serum lipids）","(D) 增加血漿中之兒茶酚胺（increased serum catecholamines）"],"answer":2,"image":""},{"id":"md6-113-2-66","subject":"md6","topic":"復健-神經復健","meta":"113年第2次第66題","year":113,"session":2,"number":66,"question":"關於裘馨氏肌肉失養症（Duchenne muscular dystrophy），下列敘述何者最不適當？","options":["(A) X染色體隱性遺傳（X-linked recessive inheritance）","(B) 肌肉無力通常會影響骨盆鄰近（pelvic girdle）肌肉","(C) 不建議使用最大強度運動（maximal exercise）的運動量訓練","(D) 心肌（cardiac muscle）通常不受影響"],"answer":3,"image":""},{"id":"md6-113-2-67","subject":"md6","topic":"復健-神經復健","meta":"113年第2次第67題","year":113,"session":2,"number":67,"question":"下列關於嬰兒型脊髓性肌肉萎縮症（infantile spinal muscular atrophy）的敘述，何者最為適當？","options":["(A) 屬於體染色體顯性遺傳（autosomal dominant inheritance）","(B) 通常於10歲以後才會變得全身無力","(C) 產前DNA檢測（prenatal DNA testing）可作為臨床診斷上的參考","(D) 肌電圖（electromyography）的檢查完全正常"],"answer":2,"image":""},{"id":"md6-113-2-68","subject":"md6","topic":"復健-兒童與一般復健","meta":"113年第2次第68題","year":113,"session":2,"number":68,"question":"關於老年人復健訓練的風險，下列敘述何者最適當？","options":["(A) 復健訓練不會帶來跌倒、扭傷、酸痛的傷害","(B) 比起不活動或臥床的併發症而言，復健訓練的風險傷害相對較小","(C) 即使選擇適合的運動及強度，在復健過程中有監督者（supervisor），仍不易減少風險的產生","(D) 復健運動最重大的風險就是發生肌肉骨骼傷害"],"answer":1,"image":""},{"id":"md6-113-2-69","subject":"md6","topic":"復健-兒童與一般復健","meta":"113年第2次第69題","year":113,"session":2,"number":69,"question":"有關無障礙環境的評估，下列敘述何者最不適當？","options":["(A) 無障礙環境的評估需在病患出院返家後進行，並依據評估的結果調整病患的居住或工作環境","(B) 病患的身高、體重、身體寬度、手腳長度等都是評估項目之一","(C) 評估過程必須考慮病患的經濟能力","(D) 評估時應充分了解病患或其家屬對於生活與照顧之期待"],"answer":0,"image":""},{"id":"md6-113-2-70","subject":"md6","topic":"復健-兒童與一般復健","meta":"113年第2次第70題","year":113,"session":2,"number":70,"question":"有關輪椅訂製時應考慮的項目，下列何者最不適當？","options":["(A) 使用者的心肺功能非評估項目之一","(B) 對於神經性疾病之病患，應觀察病患之皮膚狀況","(C) 對於手部協調性差的病患，可考慮使用頭部操控的輪椅","(D) 髖部、膝蓋與腳踝的關節活動度為評估項目之一"],"answer":0,"image":""},{"id":"md6-113-2-71","subject":"md6","topic":"復健-兒童與一般復健","meta":"113年第2次第71題","year":113,"session":2,"number":71,"question":"有關巴氏量表（Barthel index）的敘述，下列何者最不適當？","options":["(A) 目的在評估病患的日常生活活動（activities of daily living, ADLs）能力","(B) 滿分是100分","(C) 包含大小便能力","(D) 包含溝通能力及社會認知的評量"],"answer":3,"image":""},{"id":"md6-113-2-72","subject":"md6","topic":"眼科-角膜結膜眼瞼眼窩","meta":"113年第2次第72題","year":113,"session":2,"number":72,"question":"37歲女性病人，因左上眼瞼下垂與複視而求診，靜脈注射顯影劑磁振造影（如圖），下列何者為最可能之診斷？","options":["(A) 左側頸動脈海綿竇瘻管（carotid-cavernous sinus fistula）","(B) 左側視神經鞘腦膜瘤（optic nerve sheath meningioma）","(C) 左側鼻竇癌","(D) 鼻咽癌併局部侵犯"],"answer":3,"image":"md6-113-2-72.jpeg"},{"id":"md6-113-2-73","subject":"md6","topic":"婦科-良性腫瘤與內膜異位","meta":"113年第2次第73題","year":113,"session":2,"number":73,"question":"45歲女性病人到醫院做健康檢查，腹部X光片顯示骨盆腔病變如圖示；進一步進行經陰道超音波檢查，結果發現異常如圖示。最可能的診斷為何？","options":["(A) 骨盆腔發炎性疾病（pelvic inflammatory disease）","(B) 子宮內避孕器（intrauterine contraceptive device）","(C) 子宮類纖維瘤（uterine fibroid or leiomyoma）","(D) 子宮內膜癌（endometrial carcinoma）"],"answer":2,"image":"md6-113-2-73.jpeg"},{"id":"md6-113-2-74","subject":"md6","topic":"復健-骨骼肌肉損傷與疾患","meta":"113年第2次第74題","year":113,"session":2,"number":74,"question":"下列有關分離性骨軟骨炎（osteochondritis dissecans）的敘述，何者最不適當？","options":["(A) 常見於70歲以上的男性，且合併股骨頭部缺血性壞死","(B) 可出現關節囊內骨小塊游離","(C) 磁振造影可協助診斷","(D) 常見於中學生且侵犯踝關節"],"answer":0,"image":""},{"id":"md6-113-2-75","subject":"md6","topic":"產科-高危險妊娠","meta":"113年第2次第75題","year":113,"session":2,"number":75,"question":"25歲女性無過去病史，懷孕28週因下肢疼痛至急診求診，經檢查後發現是下肢靜脈栓塞。針對此病人的治療，下列何者最不適合？","options":["(A) warfarin","(B) unfractionated heparin","(C) low-molecular-weight heparin","(D) 若anticoagulation效果不好，可考慮放置inferior vena cava filter"],"answer":0,"image":""},{"id":"md6-113-2-76","subject":"md6","topic":"喉科學與頭頸腫瘤","meta":"113年第2次第76題","year":113,"session":2,"number":76,"question":"關於急性會厭炎（acute epiglottitis），下列敘述何者最正確？","options":["(A) 大部分病人具有典型的3D症狀：流口水（drooling）、吞嚥困難（dysphagia）、呼吸窘迫（distress）","(B) 身體診察時吸氣可以聽到喘鳴聲（stridor）","(C) 呼吸窘迫時應安排頸部電腦斷層掃描進一步確定診斷","(D) 清醒病人呼吸窘迫時，建議使用鎮靜藥物及肌肉鬆弛劑執行氣管內管插管"],"answer":1,"image":""},{"id":"md6-113-2-77","subject":"md6","topic":"復健-骨骼肌肉損傷與疾患","meta":"113年第2次第77題","year":113,"session":2,"number":77,"question":"50歲老師，最近在上課中感到背痛，休息一下症狀就比較好，但站太久又會疼痛，他因疼痛加劇至急診求診，醫師說他的背痛是緊急情況要馬上處理。病人最不可能是下列何種診斷？","options":["(A) aortic dissection","(B) cauda equina syndrome","(C) spinal stenosis","(D) epidural abscess"],"answer":2,"image":""},{"id":"md6-113-2-78","subject":"md6","topic":"醫學倫理與法規","meta":"113年第2次第78題","year":113,"session":2,"number":78,"question":"根據生命倫理四原則的作者Beauchamp和Childress之見解，四個原則的重要性依序為何？①尊重自主原則（respect for autonomy） ②不傷害原則（nonmaleficence） ③行善原則（beneficence） ④正義原則（justice）","options":["(A) ①＝②＝③＝④","(B) ②＞①＞③＞④","(C) ①＞②＞③＞④","(D) ①＝④＞②＝③"],"answer":0,"image":""},{"id":"md6-113-2-79","subject":"md6","topic":"醫學倫理與法規","meta":"113年第2次第79題","year":113,"session":2,"number":79,"question":"由於父母信仰的關係，一位出生後才被診斷出染色體異常（trisomy 18）的新生兒，在出生後完全無法自己呼吸，目前裝著呼吸器，新生兒同時也被發現包含有心臟與食道氣管瘻管等多項先天性異常，即使開刀預後也很差，經過商量，嬰兒父母希望醫師不再積極治療。下列處置何者最適當？","options":["(A) 為符合病人最大利益，立即為其手術","(B) 父母無權決定，持續目前所有治療","(C) 尊重父母決定，給予緩和醫療","(D) 為符合人道精神不讓病人痛苦，直接讓病人安樂死亡"],"answer":2,"image":""},{"id":"md6-113-2-80","subject":"md6","topic":"醫學倫理與法規","meta":"113年第2次第80題","year":113,"session":2,"number":80,"question":"關於醫療隱私之維護，下列敘述何者錯誤？","options":["(A) 病人就診時，應確實隔離其他不相關人員","(B) 於診療過程，醫病雙方如需錄音或錄影，應先徵得對方之同意","(C) 門診診間及諮詢會談場所應為單診間，且有適當之隔音","(D) 教學醫院以醫學教育為使命，實習學生在旁學習無需事先告知病人"],"answer":3,"image":""},{"id":"md6-114-1-1","subject":"md6","topic":"麻醉-呼吸道與監視","meta":"114年第1次第1題","year":114,"session":1,"number":1,"question":"麻醉醫師對病人作氣道評估後，認為必須採取清醒下插氣管內管，此時最常施行之神經阻斷技術輔助，不包括下列何者？","options":["(A) glossopharyngeal nerve block","(B) superior laryngeal nerve block","(C) translaryngeal block","(D) recurrent laryngeal nerve block"],"answer":3,"image":""},{"id":"md6-114-1-2","subject":"md6","topic":"麻醉-呼吸道與監視","meta":"114年第1次第2題","year":114,"session":1,"number":2,"question":"關於bispectral index（BIS）於術中麻醉深度的監測（monitoring of the depth of anesthesia），下列敘述何者錯誤？","options":["(A) 當BIS值為90～100時，表示病人處於清醒的狀態","(B) 當BIS值為0時，表示病人處於深度昏迷或無意識的狀態","(C) 鎮靜麻醉藥物中，ketamine與propofol對腦電圖（EEG）的影響類似","(D) 使用propofol達到意識失去（unconsciousness）狀態時，腦電圖（EEG）會趨於顯示低頻率（lower- frequency）與高振幅（higher-amplitude）的波形"],"answer":2,"image":""},{"id":"md6-114-1-3","subject":"md6","topic":"麻醉-呼吸道與監視","meta":"114年第1次第3題","year":114,"session":1,"number":3,"question":"關於脈搏血氧飽和度（SpO2），下列敘述何者正確？","options":["(A) 原理是oxyhemoglobin（O2Hb）與deoxyhemoglobin（deO2Hb）對不同波長的光，有不同吸收比值","(B) 可以幫助我們監測通氣和體內酸鹼平衡狀態","(C) 主要測量對象是靜脈血","(D) 和動脈血氧分壓（PaO2）呈線性關係"],"answer":0,"image":""},{"id":"md6-114-1-4","subject":"md6","topic":"麻醉-特殊麻醉與疼痛","meta":"114年第1次第4題","year":114,"session":1,"number":4,"question":"下列何者最不會影響脊髓麻醉阻斷皮節的高度？","options":["(A) 病人姿勢和擺位","(B) 病人身高","(C) 局部麻醉藥劑之比重","(D) 注射局部麻醉藥時的給藥速度"],"answer":3,"image":""},{"id":"md6-114-1-5","subject":"md6","topic":"產科-一般產科","meta":"114年第1次第5題","year":114,"session":1,"number":5,"question":"有關產婦分娩硬脊膜外止痛（epidural analgesia）用藥注意事項，下列何者最適當？","options":["(A) 不建議局部麻醉藥添加類鴉片藥物，因為會增加低血壓和藥物毒性等不良副作用的發生率","(B) bupivacaine作用時間長，不具心臟毒性","(C) 臨床上很常使用較高濃度的局部麻醉劑，來達到較佳鎮痛","(D) 使用低濃度的bupivacaine較不會產生運動阻滯，可允許下床走動"],"answer":3,"image":""},{"id":"md6-114-1-6","subject":"md6","topic":"麻醉-呼吸道與監視","meta":"114年第1次第6題","year":114,"session":1,"number":6,"question":"病人是否能從恢復室轉回病房，可以用Aldrete score來評估，9分以上（滿分10分）被認為是可以轉出恢復室的標準。下列何者不包含在Aldrete score的項目中？","options":["(A) 意識（consciousness）：完全清醒（fully awake）、可喚醒（arousable）、無反應（not responding）","(B) 血液循環（circulation）：量測到的血壓與麻醉前血壓相差多少","(C) 血氧飽和度（oxygen saturation）：是否需要使用氧氣，以及使用氧氣後血氧飽和度狀況","(D) 疼痛（pain）：疼痛嚴重程度是否可以接受"],"answer":3,"image":""},{"id":"md6-114-1-7","subject":"md6","topic":"麻醉-麻醉藥理","meta":"114年第1次第7題","year":114,"session":1,"number":7,"question":"有關各種狀態的腦波敘述，下列何者最不適當？","options":["(A) 全身麻醉下，可能呈現delta波和alpha波活性到爆發抑制（burst suppression）","(B) 全身麻醉恢復過程alpha跟beta活性會增加","(C) 腦幹死呈現等電位狀態","(D) 植物人的腦波近似正常人睡眠時期的腦波"],"answer":3,"image":""},{"id":"md6-114-1-8","subject":"md6","topic":"麻醉-特殊麻醉與疼痛","meta":"114年第1次第8題","year":114,"session":1,"number":8,"question":"有關癌症止痛的處置，下列何者最不適當？","options":["(A) 若病人已不能經口服用藥物，穿皮貼片（transdermal patch）為合理選擇","(B) 針對末期病人的骨轉移所造成的嚴重疼痛，可以合併給與類固醇（glucocorticoids）","(C) 因化療藥物造成的周邊神經病變性疼痛（neuropathic pain），不算是癌症疼痛","(D) 當病人因癌症惡病質（cancer cachexia）明顯消瘦時，皮下嗎啡注射仍可以提供有效止痛"],"answer":2,"image":""},{"id":"md6-114-1-9","subject":"md6","topic":"麻醉-呼吸道與監視","meta":"114年第1次第9題","year":114,"session":1,"number":9,"question":"關於急性呼吸窘迫症候群（acute respiratory distress syndrome）的診斷，其PaO2/FiO2數值的定義為何？","options":["(A) ＜400","(B) ＜300","(C) ＜200","(D) ＜100"],"answer":[1,2],"image":"","answer_note":"更正:第9題答Ｂ或Ｃ者均給分"},{"id":"md6-114-1-10","subject":"md6","topic":"眼科-視網膜葡萄膜","meta":"114年第1次第10題","year":114,"session":1,"number":10,"question":"下列何種情形一般不會造成裂孔性視網膜剝離？","options":["(A) 後玻璃體剝離（posterior vitreous detachment）","(B) 高度近視（high myopia）","(C) 眼鈍傷（blunt ocular trauma）","(D) 中心視網膜靜脈阻塞（central retinal vein occlusion）"],"answer":3,"image":""},{"id":"md6-114-1-11","subject":"md6","topic":"眼科-視網膜葡萄膜","meta":"114年第1次第11題","year":114,"session":1,"number":11,"question":"有關糖尿病視網膜病變（diabetic retinopathy）危險因子之敘述，下列何者錯誤？","options":["(A) 得到糖尿病時間越久，發生糖尿病視網膜病變機率越大","(B) 糖尿病控制不良是重要的危險因子","(C) 懷孕期間糖尿病視網膜病變較不易惡化","(D) 嚴重的腎臟病也容易伴隨糖尿病視網膜病變惡化"],"answer":2,"image":""},{"id":"md6-114-1-12","subject":"md6","topic":"眼科-屈光斜弱視","meta":"114年第1次第12題","year":114,"session":1,"number":12,"question":"因角膜曲度不平整而造成視網膜物體成像模糊不清，是屬於下列那種屈光不正？","options":["(A) 近視","(B) 遠視","(C) 散光","(D) 斜視"],"answer":2,"image":""},{"id":"md6-114-1-13","subject":"md6","topic":"眼科-角膜結膜眼瞼眼窩","meta":"114年第1次第13題","year":114,"session":1,"number":13,"question":"有關乾眼症的敘述，下列何者錯誤？","options":["(A) 眼球表面淚膜的脂質層主要由麥粒腺體（meibomian gland）所分泌","(B) 黏液層主要由杯狀細胞所製造","(C) 水層由淚腺、Krause及Wolfring腺體共同分泌","(D) 眼球表面的感覺神經主要是第五對腦神經的第2分支所支配"],"answer":3,"image":""},{"id":"md6-114-1-14","subject":"md6","topic":"眼科-水晶體青光眼","meta":"114年第1次第14題","year":114,"session":1,"number":14,"question":"高眼壓症（ocular hypertension）是指病患眼壓大於21 mmHg，但是並沒有青光眼的視神經病變，關於其轉化成青光眼的危險因子，下列敘述何者最不適當？","options":["(A) 眼壓愈高愈容易轉化成青光眼","(B) 中央角膜厚度（central corneal thickness）愈厚愈容易轉化成青光眼","(C) 視神經的杯盤比（cup/disc ratio）愈高愈容易轉化成青光眼","(D) 年紀愈大者愈容易轉化成青光眼"],"answer":1,"image":""},{"id":"md6-114-1-15","subject":"md6","topic":"眼科-水晶體青光眼","meta":"114年第1次第15題","year":114,"session":1,"number":15,"question":"有些人眼睛點類固醇藥水會造成眼壓上升，稱為類固醇反應者（steroid responder），下列敘述何者較不適當？","options":["(A) 類固醇反應者較容易得原發性隅角開放型青光眼","(B) 眼壓上升的程度通常和類固醇的效價（potency）有關","(C) 非眼部使用的類固醇（如皮膚上塗用或口服）不會造成眼壓上升","(D) 主要原因可能是類固醇造成小樑網功能改變而導致"],"answer":2,"image":""},{"id":"md6-114-1-16","subject":"md6","topic":"眼科-屈光斜弱視","meta":"114年第1次第16題","year":114,"session":1,"number":16,"question":"有關先天性上斜肌麻痺（superior oblique muscle palsy）之敘述，下列何者錯誤？","options":["(A) 原因也可能是肌肉筋膜異常","(B) 是常見的兒童垂直性斜視原因","(C) 需要和甲狀腺眼疾與重症肌無力鑑別診斷","(D) 患側眼會呈現下斜視（hypotropia）"],"answer":3,"image":""},{"id":"md6-114-1-17","subject":"md6","topic":"眼科-水晶體青光眼","meta":"114年第1次第17題","year":114,"session":1,"number":17,"question":"有關全身性疾病在眼睛的常見表現，下列敘述何者錯誤？","options":["(A) 馬凡氏症候群（Marfan syndrome）－晶狀體半脫位或脫位（lens subluxation or dislocation）","(B) 威爾森氏症（Wilson disease）－眼角膜周邊部脂質浸潤","(C) 維他命A缺乏－夜盲症","(D) 類肉瘤病（Sarcoidosis）－肉芽腫型葡萄膜炎（granulomatous uveitis）"],"answer":1,"image":""},{"id":"md6-114-1-18","subject":"md6","topic":"眼科-角膜結膜眼瞼眼窩","meta":"114年第1次第18題","year":114,"session":1,"number":18,"question":"有關眼窩外破性骨折（orbital blow out fracture）的敘述，下列何者錯誤？","options":["(A) 網球比小彈珠對眼球的撞擊更容易形成眼窩外破性骨折","(B) 好發的部位在眼窩底（orbital floor）及眼窩外壁（orbital lateral wall）","(C) 若受傷後一週評估時發現病患複視（diplopia）情況逐漸改善，可繼續觀察不用立即手術","(D) 當孩童發生眼窩底外破性骨折（orbital floor blow out fracture），並合併複視（diplopia）、噁心、嘔吐、心跳減慢等oculocardiac反射時，必須進行緊急手術"],"answer":1,"image":""},{"id":"md6-114-1-19","subject":"md6","topic":"耳科學","meta":"114年第1次第19題","year":114,"session":1,"number":19,"question":"中耳三個聽小骨由外至內（lateral to medial）排列依序為：","options":["(A) malleus, incus, stapes","(B) incus, malleus, stapes","(C) incus, stapes, malleus","(D) stapes, malleus, incus"],"answer":0,"image":""},{"id":"md6-114-1-20","subject":"md6","topic":"耳科學","meta":"114年第1次第20題","year":114,"session":1,"number":20,"question":"治療慢性中耳炎時，使用下列何種抗生素耳滴劑最適合？","options":["(A) quinolone","(B) aminoglycoside","(C) chloramphenicol","(D) polymyxin B"],"answer":0,"image":""},{"id":"md6-114-1-21","subject":"md6","topic":"鼻科學","meta":"114年第1次第21題","year":114,"session":1,"number":21,"question":"王先生今年35歲，每天起床鼻子常發癢、打噴嚏、流鼻水。曾接受過敏原IgE抗體測試結果為陽性。請依前述情形，回答下列3題：在臺灣下列何者最有可能是王先生的過敏原？","options":["(A) 動物皮毛（animal dander）","(B) 塵蟎（dust mite）","(C) 蟑螂（cockroach）","(D) 黴菌（mold）"],"answer":1,"image":""},{"id":"md6-114-1-22","subject":"md6","topic":"鼻科學","meta":"114年第1次第22題","year":114,"session":1,"number":22,"question":"若檢測王先生的鼻黏膜組織，下列那一種介白素（interleukin, IL）最不可能增加？","options":["(A) IL-4","(B) IL-5","(C) IL-10","(D) IL-13"],"answer":2,"image":""},{"id":"md6-114-1-23","subject":"md6","topic":"鼻科學","meta":"114年第1次第23題","year":114,"session":1,"number":23,"question":"目前下列那一種藥物未被建議使用來治療此病人？","options":["(A) anti-IgE antibody","(B) leukotriene modifier","(C) topical intranasal corticosteroid","(D) antihistamine"],"answer":0,"image":""},{"id":"md6-114-1-24","subject":"md6","topic":"喉科學與頭頸腫瘤","meta":"114年第1次第24題","year":114,"session":1,"number":24,"question":"有關嬰幼兒喉部解剖構造，下列敘述何者錯誤？","options":["(A) 足月新生兒的聲門高度（glottic level）位於頸椎C2-C3的位置","(B) 嬰幼兒呼吸道立體構造為圓柱形（cylindrical），最狹窄處在聲門下區（subglottic area）","(C) 新生兒的喉部骨架構造，甲狀軟骨較平且與舌骨及環狀軟骨（cricoid cartilage）相重疊","(D) 幼兒的杓狀軟骨（arytenoid cartilage）與上喉部軟組織占聲門的比例較高，會厭軟骨（epiglottis）呈omega shape（Ω）"],"answer":1,"image":""},{"id":"md6-114-1-25","subject":"md6","topic":"喉科學與頭頸腫瘤","meta":"114年第1次第25題","year":114,"session":1,"number":25,"question":"由下列兩張胸部X光片，判斷這位病童呼吸道異物最有可能的位置為何？","options":["(A) 右側主支氣管（right main bronchus）","(B) 左側主支氣管（left main bronchus）","(C) 聲門下（subglottis）","(D) 氣管（trachea）"],"answer":0,"image":"md6-114-1-25.jpeg"},{"id":"md6-114-1-26","subject":"md6","topic":"喉科學與頭頸腫瘤","meta":"114年第1次第26題","year":114,"session":1,"number":26,"question":"副交感神經系統主要藉由下列那條神經支配頷下腺及舌下腺（submandibular and sublingual gland）的唾液分泌？","options":["(A) 舌下神經（sublingual nerve）","(B) 舌咽神經（glossopharyngeal nerve）","(C) 三叉神經（trigeminal nerve）","(D) 迷走神經（vagus nerve）"],"answer":[0,1,2,3],"image":"","answer_note":"送分:第26題一律給分 (原公告答案 C)"},{"id":"md6-114-1-27","subject":"md6","topic":"喉科學與頭頸腫瘤","meta":"114年第1次第27題","year":114,"session":1,"number":27,"question":"甲狀腺手術後，容易發生術後低血鈣。針對高風險病人，可以術中監測甲狀腺腫瘤切除後10～20分鐘內，血液副甲狀腺素濃度對比基值的變化。術中副甲狀腺素下降多少以上，會預期術後有出現低血鈣的風險？","options":["(A) 約25%","(B) 約50%","(C) 約75%","(D) 約10%"],"answer":[1,2],"image":"","answer_note":"更正:第27題答Ｂ或Ｃ者均給分"},{"id":"md6-114-1-28","subject":"md6","topic":"婦科-生殖內分泌","meta":"114年第1次第28題","year":114,"session":1,"number":28,"question":"25歲女性，因月經延遲，自行驗孕發現尿液懷孕試驗呈陽性，在第一孕期抽血檢驗發現血清黃體素值（serum progesterone level）低於5 ng/mL，下列何種狀況與前述發現最為相關？","options":["(A) 生理性黃體衰退（physiologic corpus luteum decline）","(B) 無法存活的懷孕（nonviable pregnancy）","(C) 可存活的子宮內懷孕（viable intrauterine pregnancy）","(D) 可存活的多胞胎妊娠（viable multiple pregnancy）"],"answer":1,"image":""},{"id":"md6-114-1-29","subject":"md6","topic":"婦科-腫瘤","meta":"114年第1次第29題","year":114,"session":1,"number":29,"question":"22歲女性，G1P0，被診斷為早期懷孕合併葡萄胎（molar pregnancy），下列何種處置最適合用於懷孕週數8 ～9週的molar pregnancy？","options":["(A) 觀察（observation）","(B) 抽吸式子宮腔搔刮手術（suction curettage）","(C) 子宮切除術（hysterectomy）","(D) 子宮切開術並移除子宮內組織（hysterotomy and evacuation）"],"answer":1,"image":""},{"id":"md6-114-1-30","subject":"md6","topic":"產科-一般產科","meta":"114年第1次第30題","year":114,"session":1,"number":30,"question":"有關abnormal labor的敘述，下列何者錯誤？","options":["(A) prolonged latent phase係指初產婦子宮頸未開大於14小時","(B) protracted active-phase dilation係指初產婦子宮頸打開速度小於1.2 cm/hr","(C) 若產婦達到abnormal labor時，須評估子宮收縮強度是否足夠，以及是否有cephalopelvic disproportion","(D) 減痛分娩可能會使產程延長"],"answer":0,"image":""},{"id":"md6-114-1-31","subject":"md6","topic":"產科-一般產科","meta":"114年第1次第31題","year":114,"session":1,"number":31,"question":"活動產程（active phase）指子宮頸擴張到幾公分以上的產程？","options":["(A) 2公分","(B) 4公分","(C) 6公分","(D) 8公分"],"answer":2,"image":""},{"id":"md6-114-1-32","subject":"md6","topic":"產科-一般產科","meta":"114年第1次第32題","year":114,"session":1,"number":32,"question":"有關Couvelaire uterus的敘述，下列何者錯誤？","options":["(A) 為胎盤早期剝離的子宮特徵","(B) 原因是因為廣泛的extravasation，導致血液浸潤於子宮肌肉層","(C) 很少造成子宮收縮乏力","(D) 常須切除子宮以幫忙止血"],"answer":3,"image":""},{"id":"md6-114-1-33","subject":"md6","topic":"產科-一般產科","meta":"114年第1次第33題","year":114,"session":1,"number":33,"question":"關於羊膜穿刺，下列敘述何者錯誤？","options":["(A) 最常見造成流產的原因為胎兒刺傷","(B) 羊膜穿刺後流產的機率約為0.1%～0.3%","(C) 通常於15～20週之間執行","(D) 可檢測子宮內胎兒感染或評估胎兒肺部成熟狀況"],"answer":0,"image":""},{"id":"md6-114-1-34","subject":"md6","topic":"產科-一般產科","meta":"114年第1次第34題","year":114,"session":1,"number":34,"question":"關於生產機轉，羊膜分泌激素刺激子宮肌肉層收縮，圖中★為何種激素？","options":["(A) dehyroepiandrosterone sulfate（DHEA-S）","(B) serotonin","(C) prostaglandin E2","(D) hyaluronan"],"answer":2,"image":"md6-114-1-34.jpeg"},{"id":"md6-114-1-35","subject":"md6","topic":"產科-一般產科","meta":"114年第1次第35題","year":114,"session":1,"number":35,"question":"關於剖腹生產的適應症，下列何者錯誤？","options":["(A) 待產時急性胎兒窘迫","(B) 胎盤早期剝離","(C) 胎兒臍帶繞頸","(D) 前胎剖腹且子宮為vertical hysterotomy incision"],"answer":2,"image":""},{"id":"md6-114-1-36","subject":"md6","topic":"產科-高危險妊娠","meta":"114年第1次第36題","year":114,"session":1,"number":36,"question":"下列那一種染色體異常是屬於體染色體顯性（autosomal dominant）遺傳？","options":["(A) 囊性纖維變性（cystic fibrosis）","(B) 高胱胺酸尿症（homocystinuria）","(C) 神經纖維瘤病（neurofibromatosis）","(D) X染色體易碎症候群（fragile X syndrome）"],"answer":2,"image":""},{"id":"md6-114-1-37","subject":"md6","topic":"產科-高危險妊娠","meta":"114年第1次第37題","year":114,"session":1,"number":37,"question":"30歲的盧小姐第一次懷孕，在懷孕過程中被診斷為妊娠糖尿並且接受相關治療；她剛剛經自然產生下了一位4,800公克的足月新生兒，下列有關盧小姐與其新生兒的敘述何者最適宜？","options":["(A) 盧小姐產前血糖一定控制得非常良好","(B) 此新生兒在出生後數小時內很可能會有新生兒高血糖（neonatal hyperglycemia）","(C) 此新生兒很有可能經歷了肩難產","(D) 生產後，此孕婦的妊娠糖尿病就算已經治癒了，往後不用做任何追蹤"],"answer":2,"image":""},{"id":"md6-114-1-38","subject":"md6","topic":"產科-高危險妊娠","meta":"114年第1次第38題","year":114,"session":1,"number":38,"question":"嚴重的子癇前症合併症不包含下列何者？","options":["(A) 上腹痛","(B) 寡尿","(C) 胰臟功能異常","(D) 血小板低下"],"answer":2,"image":""},{"id":"md6-114-1-39","subject":"md6","topic":"產科-高危險妊娠","meta":"114年第1次第39題","year":114,"session":1,"number":39,"question":"24歲初胎孕婦，於懷孕12週接受尿液砂眼披衣菌（Chlamydia trachomatis）核酸NAAT篩檢診斷為砂眼披衣菌感染，首選治療為：","options":["(A) Amoxicillin，500mg，每日三次口服，治療七天","(B) Erythromycin，500mg，每日四次口服，治療七天","(C) Benzathine penicillin G，2.4 million units，單一注射","(D) Azithromycin，1g，單一劑量口服"],"answer":3,"image":""},{"id":"md6-114-1-40","subject":"md6","topic":"婦科-良性腫瘤與內膜異位","meta":"114年第1次第40題","year":114,"session":1,"number":40,"question":"27歲女性，G1P0A1，昨日開始劇烈右下腹痛，合併些微噁心嘔吐症狀，無陰道出血、發燒、腹瀉症狀，驗孕結果為陰性，腹腔鏡手術發現如下圖，下列何者為最可能診斷？","options":["(A) 子宮肌瘤","(B) 黃體破裂","(C) 盲腸炎","(D) 卵巢扭轉"],"answer":3,"image":"md6-114-1-40.jpeg"},{"id":"md6-114-1-41","subject":"md6","topic":"婦科-良性腫瘤與內膜異位","meta":"114年第1次第41題","year":114,"session":1,"number":41,"question":"有關子宮肌瘤，下列敘述何者最不適當？","options":["(A) 手術治療選擇不包括子宮內膜消融（endometrial ablation）","(B) 子宮動脈栓塞術（UAE）雖然對某些子宮肌瘤治療有效，但是對卵巢功能、生育力和懷孕的影響還不清楚","(C) 子宮肌瘤是子宮切除術最常見的適應症","(D) 黏膜下肌瘤可能造成月經增多或不孕"],"answer":0,"image":""},{"id":"md6-114-1-42","subject":"md6","topic":"婦科-生殖道感染與先天異常","meta":"114年第1次第42題","year":114,"session":1,"number":42,"question":"大約多少比例的嬰兒出生時患有生殖泌尿系統異常？","options":["(A) 5%","(B) 10%","(C) 15%","(D) 20%"],"answer":1,"image":""},{"id":"md6-114-1-43","subject":"md6","topic":"婦科-手術學與診斷技術","meta":"114年第1次第43題","year":114,"session":1,"number":43,"question":"下列對於腹腔鏡應用於婦科疾病手術的敘述，何者最不適當？","options":["(A) 子宮肌瘤切除相較於子宮切除，需更多的內視鏡縫合技巧","(B) 對子宮內膜異位症的治療，以電燒破壞為主","(C) 腹腔鏡陰道薦骨前固定術（sacrocolpopexy）效果可以跟開腹手術結果相當","(D) 可以用來進行早期子宮內膜癌的分期手術"],"answer":1,"image":""},{"id":"md6-114-1-44","subject":"md6","topic":"婦科-手術學與診斷技術","meta":"114年第1次第44題","year":114,"session":1,"number":44,"question":"有關診斷式子宮鏡檢查的敘述，下列何者最不適當？","options":["(A) 子宮鏡比子宮輸卵管攝影（HSG）更能清楚評估子宮腔內的狀況","(B) 停經後出血，是使用診斷式子宮鏡檢查的時機","(C) 診斷式子宮鏡檢查，通常須在麻醉下進行","(D) 重複性流產，是使用診斷式子宮鏡檢查的時機"],"answer":2,"image":""},{"id":"md6-114-1-45","subject":"md6","topic":"婦科-手術學與診斷技術","meta":"114年第1次第45題","year":114,"session":1,"number":45,"question":"45歲婦女，因子宮肌瘤接受腹腔鏡輔助子宮切除手術，術後恢復良好，並於術後三日出院。術後二週，因左側腰痛，合併發燒，至急診就診，超音波顯示左側腎臟水腫，最有可能的診斷為何？","options":["(A) 急性腎盂腎炎","(B) 手術導致之輸尿管狹窄","(C) 輸尿管結石","(D) 先天性腎水腫"],"answer":1,"image":""},{"id":"md6-114-1-46","subject":"md6","topic":"婦科-生殖道感染與先天異常","meta":"114年第1次第46題","year":114,"session":1,"number":46,"question":"梅毒（syphilis）有效的治療，其VDRL血清檢測（1：32）在12～24個月間，其濃度至少應下降達下列何種程度？","options":["(A) 1倍","(B) 2倍","(C) 4倍","(D) 8倍"],"answer":2,"image":""},{"id":"md6-114-1-47","subject":"md6","topic":"婦科-良性腫瘤與內膜異位","meta":"114年第1次第47題","year":114,"session":1,"number":47,"question":"一位28歲女性來到急診，她主訴為性行為後腹痛，但並無發燒或陰道出血。她的最後一次月經是25天前，3骨盆觸診下腹部有反彈痛（rebound pain），檢查發現血壓90/60 mmHg，Hb 9.5 g/dL，WBC 8,800/mm，CRP 0.45 mg/dL，尿液妊娠試驗為陰性，超音波發現骨盆腔內有積水。下列何者是最有可能的診斷？","options":["(A) 輸卵管卵巢膿瘍（tubo-ovarian abscess）破裂","(B) 輸卵管子宮外孕（tubal pregnancy）破裂","(C) 卵巢黃體囊腫（ovarian corpus luteum）破裂","(D) 子宮平滑肌瘤（uterine leiomyoma）扭轉"],"answer":2,"image":""},{"id":"md6-114-1-48","subject":"md6","topic":"婦科-生殖道感染與先天異常","meta":"114年第1次第48題","year":114,"session":1,"number":48,"question":"下列關於單純性疱疹（herpes simplex）的治療，那一個觀念最正確？","options":["(A) 可以將病毒根除","(B) 適合在潛伏期的時候使用","(C) 可以改善臨床症狀","(D) 急性期儘快治療，可以減少日後的復發"],"answer":2,"image":""},{"id":"md6-114-1-49","subject":"md6","topic":"婦科-腫瘤","meta":"114年第1次第49題","year":114,"session":1,"number":49,"question":"58歲王太太，因為停經後陰道出血來婦科門診檢查，超音波發現子宮內膜厚度15mm，子宮內膜切片發現endometrioid carcinoma，因此接受婦癌分期手術，術中及病理結果發現子宮內膜癌向下侵犯到子宮頸和部分陰道，骨盆腔淋巴結和其他器官皆沒有轉移，根據FIGO staging，病人屬於第幾期？","options":["(A) Stage IB","(B) Stage II","(C) Stage IIIA","(D) Stage IIIB"],"answer":3,"image":""},{"id":"md6-114-1-50","subject":"md6","topic":"婦科-腫瘤","meta":"114年第1次第50題","year":114,"session":1,"number":50,"question":"下列何者不是常見的上皮性卵巢癌？","options":["(A) 漿液性卵巢癌（serous）","(B) 黏液性卵巢癌（mucinous）","(C) 子宮內膜樣卵巢癌（endometrioid）","(D) 顆粒細胞卵巢癌（granulosa cell）"],"answer":3,"image":""},{"id":"md6-114-1-51","subject":"md6","topic":"婦科-腫瘤","meta":"114年第1次第51題","year":114,"session":1,"number":51,"question":"有關子宮頸癌的敘述，下列何者正確？","options":["(A) 子宮頸癌是無法預防的","(B) 子宮頸癌的形成是由於人類乳突病毒的感染，和其他感染如披衣菌完全無關","(C) 子宮頸癌被認為是後天免疫缺乏症候群的疾病之一","(D) 感染人類乳突病毒後即可獲得免疫，不會再感染同型病毒"],"answer":2,"image":""},{"id":"md6-114-1-52","subject":"md6","topic":"婦科-腫瘤","meta":"114年第1次第52題","year":114,"session":1,"number":52,"question":"經過治療後，子宮頸癌局部復發的處理，下列敘述何者正確？","options":["(A) 腫瘤減積手術是首要考量","(B) 對於初始接受手術的病人，可以考慮使用放射線治療","(C) 骨盆腔臟器摘除手術常用於有淋巴轉移的病人","(D) 化學治療為最主要的治療方式"],"answer":1,"image":""},{"id":"md6-114-1-53","subject":"md6","topic":"婦科-良性腫瘤與內膜異位","meta":"114年第1次第53題","year":114,"session":1,"number":53,"question":"停經後子宮出血最常見的原因為：","options":["(A) 子宮內膜息肉","(B) 子宮內膜萎縮","(C) 子宮內膜癌","(D) 不當的荷爾蒙治療"],"answer":1,"image":""},{"id":"md6-114-1-54","subject":"md6","topic":"婦科-生殖內分泌","meta":"114年第1次第54題","year":114,"session":1,"number":54,"question":"有關人工授精（Intrauterine insemination, IUI），下列敘述何者錯誤？","options":["(A) 若具有活動力的總精蟲數（total motile sperm count）不到1,000萬，則成功機率不高","(B) 清洗後的精蟲濃縮至0.5毫升，再以導管送進子宮腔","(C) 平均而言一次人工授精可達到大約10%的懷孕率","(D) 同一次月經週期做二次人工授精（double IUI），比起單一次人工授精（single IUI）懷孕率更高"],"answer":3,"image":""},{"id":"md6-114-1-55","subject":"md6","topic":"婦科-生殖內分泌","meta":"114年第1次第55題","year":114,"session":1,"number":55,"question":"下列何者可抑制泌乳素（prolactin）分泌？","options":["(A) 雌激素（estrogen）","(B) 多巴胺（dopamine）","(C) 表皮生長激素（epidermal growth factor）","(D) 甲狀腺素釋放激素（thyroxin releasing hormone）"],"answer":1,"image":""},{"id":"md6-114-1-56","subject":"md6","topic":"婦科-生殖內分泌","meta":"114年第1次第56題","year":114,"session":1,"number":56,"question":"關於anti-Müllerian hormone（AMH），下列敘述何者正確？","options":["(A) 胎兒時期的睪丸會分泌AMH，刺激男性生殖系統的發育","(B) AMH主要是由睪丸的萊氏細胞（Leydig cells）所分泌的","(C) 若AMH受體表現異常，則體內會同時出現男性及女性生殖系統","(D) 青春期之後，血液中就無法測得AMH"],"answer":2,"image":""},{"id":"md6-114-1-57","subject":"md6","topic":"婦科-尿失禁與骨盆腔脫垂","meta":"114年第1次第57題","year":114,"session":1,"number":57,"question":"應力性尿失禁（stress urinary incontinence）的病生理學，下列敘述何者錯誤？","options":["(A) 尿道主要支持系統是膀胱頸及尿道近端","(B) 恥骨尿道韌帶（pubourethral ligment）維持尿道支撐張力，防止尿失禁","(C) DeLancey學者主張搖籃理論（Hammock Theory）來解釋尿失禁的機轉","(D) 源自於排尿中樞及膀胱之間傳導的不正常"],"answer":3,"image":""},{"id":"md6-114-1-58","subject":"md6","topic":"婦科-尿失禁與骨盆腔脫垂","meta":"114年第1次第58題","year":114,"session":1,"number":58,"question":"下列何者為主要負責協調排尿時膀胱逼尿肌與尿道括約肌功能的中樞神經？","options":["(A) 大腦外側前額皮質（lateral prefrontal cortex）","(B) 中腦導水管周圍灰質（periaqueductal gray）","(C) 下視丘（hypothalamus）","(D) 橋腦（pons）"],"answer":3,"image":""},{"id":"md6-114-1-59","subject":"md6","topic":"復健-神經復健","meta":"114年第1次第59題","year":114,"session":1,"number":59,"question":"下列何種症狀最不可能於單次左側中腦動脈（left middle cerebral artery）阻塞時出現？","options":["(A) 共濟失調（ataxia）","(B) 失語症（aphasia）","(C) 右側視野缺損（visual field defect）","(D) 右側知覺障礙（sensory impairment）"],"answer":0,"image":""},{"id":"md6-114-1-60","subject":"md6","topic":"復健-神經復健","meta":"114年第1次第60題","year":114,"session":1,"number":60,"question":"下列何者是肌電圖及周邊神經傳導檢查最不可能達到的目的？","options":["(A) 定位神經損傷部位","(B) 確診上運動神經元病變","(C) 幫助定量軸突損傷的程度","(D) 評估神經損傷的預後"],"answer":1,"image":""},{"id":"md6-114-1-61","subject":"md6","topic":"復健-骨骼肌肉損傷與疾患","meta":"114年第1次第61題","year":114,"session":1,"number":61,"question":"一位排球選手發生單側肩痛與肩胛脊上方肌肉萎縮現象，最有可能是下列那一條神經受傷？","options":["(A) 長胸（long thoracic）神經","(B) 腋下（axillary）神經","(C) 背肩胛（dorsal scapular）神經","(D) 上肩胛（suprascapular）神經"],"answer":3,"image":""},{"id":"md6-114-1-62","subject":"md6","topic":"復健-骨骼肌肉損傷與疾患","meta":"114年第1次第62題","year":114,"session":1,"number":62,"question":"有關肌少症（sarcopenia）治療的方式，下列敘述何者最不適當？","options":["(A) 身體活動（physical activity）是肌少症治療方式之一","(B) 營養補充（diet and nutrient supplement）是肌少症治療方式之一","(C) 對於高齡肌少症患者，為避免血壓上升，應不要進行阻力運動（resistance exercise）","(D) 肌少症會增加病患的死亡率"],"answer":2,"image":""},{"id":"md6-114-1-63","subject":"md6","topic":"復健-物理因子治療與評估","meta":"114年第1次第63題","year":114,"session":1,"number":63,"question":"有關冷療（cryotherapy）在物理醫學中的應用，下列敘述何者最不適當？","options":["(A) 冷療可使血管收縮進而降低急性發炎反應、減少腫脹惡化，並有止痛的作用","(B) 冷療在處理慢性疼痛的問題上效果不好，應避免使用","(C) 冷療引起之血管收縮會導致循環障礙","(D) 冷水浴藉由對流來降低肢體溫度，有全面降溫的效果，可以使用在局部燒燙傷之後肢體的快速降溫"],"answer":1,"image":""},{"id":"md6-114-1-64","subject":"md6","topic":"復健-骨骼肌肉損傷與疾患","meta":"114年第1次第64題","year":114,"session":1,"number":64,"question":"有關髂脛束症候群（iliotibial band syndrome），下列敘述何者最不適當？","options":["(A) 常疼痛於大腿外側","(B) 扁平足、膝內翻和脛骨內旋都可能是造成的原因","(C) 冰敷或伸展有助減輕疼痛和炎症","(D) 必須依賴MRI或超音波影像檢查才能確定診斷"],"answer":3,"image":""},{"id":"md6-114-1-65","subject":"md6","topic":"復健-心肺復健與運動處方","meta":"114年第1次第65題","year":114,"session":1,"number":65,"question":"下列何者是最適合開始心臟復健的對象？","options":["(A) 不穩定型心絞痛","(B) 心臟衰竭病人從臥姿變成坐姿，收縮壓下降30 mmHg","(C) 高血壓心臟病人休息時血壓為160/100 mmHg","(D) 未裝置節律器的第三度房室傳導阻斷病人"],"answer":2,"image":""},{"id":"md6-114-1-66","subject":"md6","topic":"復健-兒童與一般復健","meta":"114年第1次第66題","year":114,"session":1,"number":66,"question":"關於兒童發展里程碑（developmental milestones），下列那一項最早達到？","options":["(A) 會自己翻身","(B) 會有意義的叫爸爸、媽媽","(C) 會自己上下樓梯","(D) 會用湯匙吃飯"],"answer":0,"image":""},{"id":"md6-114-1-67","subject":"md6","topic":"復健-兒童與一般復健","meta":"114年第1次第67題","year":114,"session":1,"number":67,"question":"下列何種類型的脊髓脊膜膨出症（myelomeningocele）患者，其神經功能損傷影響程度通常最小？","options":["(A) 頸椎到上胸椎（cervical and upper thoracic spine）","(B) 下胸椎（lower thoracic spine T11-T12）","(C) 上腰椎（upper lumbar spine L1-L2）","(D) 中腰椎（mid-lumbar spine L3-L4）"],"answer":0,"image":""},{"id":"md6-114-1-68","subject":"md6","topic":"復健-兒童與一般復健","meta":"114年第1次第68題","year":114,"session":1,"number":68,"question":"巴氏量表（Barthel index）是一種日常生活功能之評估量表，評估內容不包括下列何者？","options":["(A) 溝通","(B) 進食","(C) 如廁","(D) 盥洗"],"answer":0,"image":""},{"id":"md6-114-1-69","subject":"md6","topic":"復健-神經復健","meta":"114年第1次第69題","year":114,"session":1,"number":69,"question":"有關疼痛傳導的敘述，下列何者錯誤？","options":["(A) 疼痛可分為快速痛覺（fast pain）與慢速痛覺（slow pain）","(B) 快速痛覺主要是由Aδ神經纖維傳導，而慢速痛覺主要是由C神經纖維傳導","(C) Aδ神經纖維可傳達兩個以上的痛受器的訊息，因此無法精準定位傷害部位的正確位置","(D) 經皮神經電刺激（TENS）是藉由門閥理論（gate control theory）的原理來抑制痛覺"],"answer":2,"image":""},{"id":"md6-114-1-70","subject":"md6","topic":"復健-兒童與一般復健","meta":"114年第1次第70題","year":114,"session":1,"number":70,"question":"有關無障礙環境的介入方式，下列何者最不適當？","options":["(A) 常用必需品儘量放在地板上，以方便病人拿取","(B) 可將出入口的門加寬，以方便病人進出","(C) 可於樓梯上添加扶手，以方便病人上下樓梯","(D) 可於馬桶旁的牆壁加裝扶手，以讓下肢肌力不足、平衡能力不好的病人能夠獨立如廁"],"answer":0,"image":""},{"id":"md6-114-1-71","subject":"md6","topic":"復健-神經復健","meta":"114年第1次第71題","year":114,"session":1,"number":71,"question":"有關輪椅的敘述，下列何者最適當？","options":["(A) 第五節頸椎（C5）脊髓損傷的病人無法自己推動手動輪椅","(B) 使用手動輪椅時，要注意造成肩關節的傷害","(C) 腦中風導致肢體偏癱的病人無法自己推動手動輪椅","(D) 後輪附加的手推圈的直徑越小越好"],"answer":1,"image":""},{"id":"md6-114-1-72","subject":"md6","topic":"復健-神經復健","meta":"114年第1次第72題","year":114,"session":1,"number":72,"question":"51歲男性主訴跌倒後數小時開始出現四肢無力且大小便失禁，圖為病人的胸椎磁振造影影像（T2WI），下列敘述何者錯誤？","options":["(A) 臨床表現和影像符合spinal cord infarction","(B) spinal cord infarction在磁振造影中，脊髓可能見到owl's eye表現","(C) 受影響的血管最常是posterior spinal artery","(D) 脊髓的主要血液供應來自一條anterior spinal artery和一對posterior spinal arteries"],"answer":2,"image":"md6-114-1-72.jpeg"},{"id":"md6-114-1-73","subject":"md6","topic":"婦科-良性腫瘤與內膜異位","meta":"114年第1次第73題","year":114,"session":1,"number":73,"question":"28歲女性主訴腹部突然劇痛，注射顯影劑後電腦斷層檢查呈現如圖，箭號所指之病灶，下列何項診斷最不可能？","options":["(A) 異位妊娠破裂","(B) 腹腔血腫","(C) 子宮內膜異位","(D) 急性輸卵管破裂出血"],"answer":2,"image":"md6-114-1-73.jpeg"},{"id":"md6-114-1-74","subject":"md6","topic":"復健-神經復健","meta":"114年第1次第74題","year":114,"session":1,"number":74,"question":"70歲男性病人抽菸50年且長期高血壓，主訴近一週內出現三次右手及右腳突然無力，症狀持續30分鐘才恢復，下列何者是這個疾病最不迫切需要的檢查？","options":["(A) 頸動脈超音波","(B) 頭頸部電腦斷層血管影像（CTA）","(C) 頸部聽診","(D) 腦波檢查（EEG）"],"answer":3,"image":""},{"id":"md6-114-1-75","subject":"md6","topic":"復健-神經復健","meta":"114年第1次第75題","year":114,"session":1,"number":75,"question":"下列何者屬於周圍神經麻痺之徵象？","options":["(A) Babinski's sign","(B) Hoffman's sign","(C) brisk reflexes","(D) areflexia"],"answer":3,"image":""},{"id":"md6-114-1-76","subject":"md6","topic":"產科-高危險妊娠","meta":"114年第1次第76題","year":114,"session":1,"number":76,"question":"25歲女性至急診求診，主訴今日下腹疼痛且陰道有些許出血，平常月經規則，上次月經是7週前，urine β -hCG：(+)，陰道超音波在uterus和adnexa都看不到胚囊（gestational sac），血液β-hCG：1300 mIU/mL，病人生命徵象穩定，下列處置何者最適當？","options":["(A) 病人正常懷孕，告知後續門診規則產檢","(B) 有可能是先兆性流產（threatened abortion），給與黃體素和transamine，後續門診追蹤","(C) 有可能是異位性懷孕（ectopic pregnancy），48小時後須再次追蹤血液β-hCG值","(D) 因找不到胚囊（gestational sac），須進一步安排腹部電腦斷層檢查"],"answer":2,"image":""},{"id":"md6-114-1-77","subject":"md6","topic":"耳科學","meta":"114年第1次第77題","year":114,"session":1,"number":77,"question":"80歲男性，有糖尿病，因外耳紅、腫、熱、痛至急診就診，下列敘述何者最不適當？","options":["(A) 在嚴重的個案，可能會合併腮腺炎（parotitis）","(B) 常見致病菌為葡萄球菌（Staphylococcus）與假單胞菌（Pseudomonas）等","(C) 針對外耳炎合併牙關緊閉的病人，可單獨使用局部耳滴劑","(D) 治療期間注意避免水進入耳內"],"answer":2,"image":""},{"id":"md6-114-1-78","subject":"md6","topic":"醫學倫理與法規","meta":"114年第1次第78題","year":114,"session":1,"number":78,"question":"世界醫師會（The World Medical Association）曾在2005年發表宣言，重申「安樂死（euthanasia）是不合倫理的（unethical）」；又在2015年發表另一項宣言，重申「醫師協助自殺（physician-assisted suicide）與安樂死一樣不合倫理，應受醫療專業譴責。」然而，在2019年的會議中，這兩項宣言都被撤銷，改以新的宣言取代。因此，目前世界醫師會對於此議題的立場宣示，下列何者正確？","options":["(A) 支持安樂死或醫師協助自殺的倫理適當性","(B) 支持各國醫師組織協助推動安樂死及醫師協助自殺的合法化","(C) 在安樂死已經合法的國家，支持醫師參與安樂死或醫師協助自殺","(D) 支持醫師尊重病人的知情拒絕，包括依此中止或撤除維生醫療後，病人會死亡"],"answer":3,"image":""},{"id":"md6-114-1-79","subject":"md6","topic":"醫學倫理與法規","meta":"114年第1次第79題","year":114,"session":1,"number":79,"question":"病人有效的同意，需要符合三個重要的因素：接受告知、有決定能力、自願決定。關於醫師的作法，下列何者錯誤？","options":["(A) 醫師應該用病人可以了解的方式提供相關訊息","(B) 醫師只需說明「接受治療的好處」與「不接受治療的壞處」兩部分，不需說明替代選項","(C) 病人在接受說明時，如果出現強烈情緒，醫師應該注意到病人是否仍能保持決定所需要的能力","(D) 醫師如果說「你不開刀的話，就請你出院！」，讓病人做出接受開刀的決定，就不符合自願的原則"],"answer":1,"image":""},{"id":"md6-114-1-80","subject":"md6","topic":"醫學倫理與法規","meta":"114年第1次第80題","year":114,"session":1,"number":80,"question":"有關易受傷害族群研究的倫理議題，下列敘述何者錯誤？","options":["(A) 胚胎還不是人，因此不算是易受傷害族群","(B) 胎兒和兒童是易受傷害族群","(C) 孕婦是易受傷害族群","(D) 新移民是易受傷害族群"],"answer":0,"image":""},{"id":"md6-114-2-1","subject":"md6","topic":"麻醉-呼吸道與監視","meta":"114年第2次第1題","year":114,"session":2,"number":1,"question":"執行快速插管（rapid sequence intubation）使用的藥物或步驟，下列何者最不適合？","options":["(A) 使用光纖內視鏡輔助插管","(B) 預先給氧","(C) 快速作用的非去極化神經肌肉阻斷劑","(D) 快速作用的去極化神經肌肉阻斷劑"],"answer":0,"image":""},{"id":"md6-114-2-2","subject":"md6","topic":"麻醉-呼吸道與監視","meta":"114年第2次第2題","year":114,"session":2,"number":2,"question":"關於應用四連刺激監測（train-of-four, TOF）於神經肌肉阻斷的恢復（recovery from neuromuscular block），下列敘述何者錯誤？﹝TOF ratio：第四個twitch的幅度除以第一個twitch的幅度﹞","options":["(A) 當第四個肌肉抽動（twitch）反應再次出現時，就進入神經肌肉阻斷恢復的階段","(B) 當TOF ratio小於0.4時，病人通常無法抬頭或舉起手臂","(C) 當TOF ratio為0.7～0.75時，病人通常可以正常咳嗽及抬頭至少5秒","(D) 當TOF ratio達到0.8時，表示病人已完全恢復神經肌肉的功能"],"answer":3,"image":""},{"id":"md6-114-2-3","subject":"md6","topic":"麻醉-呼吸道與監視","meta":"114年第2次第3題","year":114,"session":2,"number":3,"question":"關於潮氣末二氧化碳（end-tidal CO2）的監測，下列敘述何者最不適當？","options":["(A) 可以快速發現是否將氣管內管誤放入食道","(B) 可以快速發現是否將氣管內管置放過深","(C) 可以用來監測復甦品質，確認組織灌流改善","(D) 全身麻醉中潮氣末二氧化碳快速增加可能是malignant hyperthermia的early sign"],"answer":1,"image":""},{"id":"md6-114-2-4","subject":"md6","topic":"麻醉-麻醉藥理","meta":"114年第2次第4題","year":114,"session":2,"number":4,"question":"50歲女性，有重症肌無力（myasthenia gravis）病史，目前規則服用類固醇及乙醯膽素分解酶抑制劑pyridostigmine，安排常規腹腔鏡膽囊切除術及全身麻醉插管。有關麻醉注意事項，下列何者最不適當？","options":["(A) 此病人肌肉無力與自體免疫引起乙醯膽鹼受體（Ach receptor）的破壞有關，導致受體數量減少","(B) 術前需評估乙醯膽素分解酶抑制劑使用劑量","(C) 該病人有術後呼吸衰竭的風險，圍術期可使用周邊神經刺激器（peripheral nerve stimulator）train-of- four監測","(D) 使用短效性的去極化肌肉鬆弛劑（depolarizing muscle relaxants）時，應減少劑量"],"answer":3,"image":""},{"id":"md6-114-2-5","subject":"md6","topic":"麻醉-麻醉藥理","meta":"114年第2次第5題","year":114,"session":2,"number":5,"question":"下列關於succinylcholine之敘述，何者最不適當？","options":["(A) 兒童在使用succinylcholine後，較容易出現嚴重的心搏過緩","(B) 可先施打低劑量的非去極化肌肉鬆弛劑（nondepolarizing muscle relaxant），來避免succinylcholine引起的肌束顫動（fasciculation）","(C) 在燒傷病人使用會引發低血鉀（hypokalemia），應避免使用succinylcholine","(D) 可能引發惡性高熱症（malignant hyperthermia）"],"answer":2,"image":""},{"id":"md6-114-2-6","subject":"md6","topic":"麻醉-呼吸道與監視","meta":"114年第2次第6題","year":114,"session":2,"number":6,"question":"75歲男性，預計經尿道攝護腺切除術，病人的術前心臟超音波報告剛出來，下列數據何者最可能需要暫緩手術？","options":["(A) 主動脈瓣平均跨瓣壓力梯度30 mmHg","(B) 主動脈瓣最大流速2 m/s","(C) 主動脈瓣瓣口面積（AVA）0.9平方公分","(D) 二尖瓣平均跨瓣壓力梯度6 mmHg"],"answer":2,"image":""},{"id":"md6-114-2-7","subject":"md6","topic":"產科-一般產科","meta":"114年第2次第7題","year":114,"session":2,"number":7,"question":"正常懷孕婦女在足月時期產生的生理變化與未懷孕時期相比，下列敘述何者最不適當？","options":["(A) 心輸出量（cardiac output）增加，心搏量（stroke volume）與心跳速率（heart rate）也會增加，而周邊血管阻力（systemic vascular resistance）下降","(B) 每分鐘換氣量（minute ventilation）增加，但功能性肺餘容量（functional residual capacity）降低","(C) 懷孕婦女的血紅素血氧飽和曲線會左移，增加氧氣在胎盤的釋放","(D) 食道下括約肌張力下降，生產時胃排空時間會延長"],"answer":2,"image":""},{"id":"md6-114-2-8","subject":"md6","topic":"麻醉-特殊麻醉與疼痛","meta":"114年第2次第8題","year":114,"session":2,"number":8,"question":"下列何種介入性疼痛治療，最適用於處理上腹部惡性腫瘤造成的臟器性疼痛？","options":["(A) celiac plexus block","(B) superior hypogastric plexus block","(C) stellate ganglion block","(D) Bier block（intravenous regional block）"],"answer":0,"image":""},{"id":"md6-114-2-9","subject":"md6","topic":"麻醉-麻醉藥理","meta":"114年第2次第9題","year":114,"session":2,"number":9,"question":"下列何者最不可能導致病人手術後出現高血糖的病生理變化？","options":["(A) 交感神經亢奮","(B) 活化免疫系統","(C) 加重感染情況","(D) 增加分解代謝率（catabolic rate）"],"answer":1,"image":""},{"id":"md6-114-2-10","subject":"md6","topic":"眼科-視網膜葡萄膜","meta":"114年第2次第10題","year":114,"session":2,"number":10,"question":"下列何者不是濕性年齡相關黃斑部退化（wet-type age-related macular degeneration）常見的症狀？","options":["(A) 視力模糊","(B) 周邊視野缺損","(C) 中央出現盲點（central scotoma）","(D) 視物變形（metamorphopsia）"],"answer":1,"image":""},{"id":"md6-114-2-11","subject":"md6","topic":"眼科-視網膜葡萄膜","meta":"114年第2次第11題","year":114,"session":2,"number":11,"question":"一旦發現病人已經有增殖性糖尿病視網膜病變（proliferative diabetic retinopathy），下列何種治療對病人會有幫助？","options":["(A) 光動力治療（photodynamic therapy）","(B) 氣體視網膜固定術（pneumatic retinopexy）","(C) 全視網膜雷射光凝固術（panretinal photocoagulation）","(D) 鞏膜扣壓術（scleral buckling）"],"answer":2,"image":""},{"id":"md6-114-2-12","subject":"md6","topic":"眼科-角膜結膜眼瞼眼窩","meta":"114年第2次第12題","year":114,"session":2,"number":12,"question":"有關翼狀贅片（pterygium）的敘述，下列何者錯誤？","options":["(A) 結膜下組織向角膜面侵襲的退化性疾病，好發於顳側","(B) 成因不明，可能和紫外線暴露、結膜慢性發炎有關","(C) 臨床表現為三角形的血管纖維膜，眼睛易充血發紅","(D) 可考慮切除，但復發率高，如加上mitomycin C可降低術後復發"],"answer":0,"image":""},{"id":"md6-114-2-13","subject":"md6","topic":"眼科-角膜結膜眼瞼眼窩","meta":"114年第2次第13題","year":114,"session":2,"number":13,"question":"下列那個疾病和圓錐角膜（keratoconus）相關？","options":["(A) 異位性皮膚炎（atopic dermatitis）","(B) 謝格連氏症候群（Sjögren syndrome）","(C) 葛瑞夫茲病（Graves' disease）","(D) 全身性紅斑狼瘡（systemic lupus erythematosus）"],"answer":0,"image":""},{"id":"md6-114-2-14","subject":"md6","topic":"眼科-水晶體青光眼","meta":"114年第2次第14題","year":114,"session":2,"number":14,"question":"下列何種藥物不建議使用在心臟病或氣喘的病人身上？","options":["(A) α作用劑（α agonists）","(B) β拮抗劑（β blockers）","(C) 碳酸酐酶抑制劑（carbonic anhydrase inhibitor）","(D) 類前列腺素製劑（prostaglandin analogue）"],"answer":1,"image":""},{"id":"md6-114-2-15","subject":"md6","topic":"眼科-水晶體青光眼","meta":"114年第2次第15題","year":114,"session":2,"number":15,"question":"關於新生血管性青光眼（Neovascular glaucoma）的形成原因，下列何者最不常見？","options":["(A) 缺血性中央視網膜靜脈阻塞","(B) 糖尿病","(C) 中央視網膜動脈阻塞","(D) 過熟的白內障"],"answer":3,"image":""},{"id":"md6-114-2-16","subject":"md6","topic":"眼科-角膜結膜眼瞼眼窩","meta":"114年第2次第16題","year":114,"session":2,"number":16,"question":"瞳孔不等大且合併眼皮下垂的原因中，下列何者有致命危險？","options":["(A) 腦幹出血（uncal herniation）","(B) 小血管性因素（microvasculopathy）","(C) 顎動性眨眼症候群（Marcus Gunn jaw-winking syndrome）","(D) 重症肌無力"],"answer":0,"image":""},{"id":"md6-114-2-17","subject":"md6","topic":"眼科-屈光斜弱視","meta":"114年第2次第17題","year":114,"session":2,"number":17,"question":"下列何者較不可能是「假性內斜視」的原因？","options":["(A) 兩眼瞳孔間距太短","(B) 內眥上皮皺褶（epicanthic folds）顯著","(C) 高度近視有negative kappa angle","(D) 早產兒網膜症造成黃斑部異位（ectopic macula）"],"answer":3,"image":""},{"id":"md6-114-2-18","subject":"md6","topic":"眼科-屈光斜弱視","meta":"114年第2次第18題","year":114,"session":2,"number":18,"question":"有關單側先天性眼瞼下垂之敘述，下列何者錯誤？","options":["(A) 患眼容易產生弱視","(B) 可以適當遮蔽另一眼來治療弱視","(C) 提眼瞼肌（levator muscle）功能很差的病人，在手術矯正後，必須注意病人睡覺無法闔眼","(D) 手術矯正方式同一般雙眼皮手術"],"answer":3,"image":""},{"id":"md6-114-2-19","subject":"md6","topic":"耳科學","meta":"114年第2次第19題","year":114,"session":2,"number":19,"question":"有關慢性中耳炎之致病細菌，下列何者最不常見？","options":["(A) Streptococcus pneumoniae","(B) Escherichia coli","(C) Staphylococcus aureus","(D) Pseudomonas aeruginosa"],"answer":0,"image":""},{"id":"md6-114-2-20","subject":"md6","topic":"耳科學","meta":"114年第2次第20題","year":114,"session":2,"number":20,"question":"下列藥物何者最不常造成耳毒性？","options":["(A) acetaminophen","(B) aspirin","(C) furosemide","(D) cisplatin"],"answer":0,"image":""},{"id":"md6-114-2-21","subject":"md6","topic":"耳科學","meta":"114年第2次第21題","year":114,"session":2,"number":21,"question":"關於突發性耳聾之敘述，下列何者最不適當？","options":["(A) 在聽力圖上可以看到連續三個頻率聽力下降30分貝以上","(B) 主要用口服或靜脈注射類固醇治療","(C) 一般認為耳內注射類固醇無效","(D) 高壓氧治療可能有效"],"answer":2,"image":""},{"id":"md6-114-2-22","subject":"md6","topic":"鼻科學","meta":"114年第2次第22題","year":114,"session":2,"number":22,"question":"關於篩竇解剖，下列敘述何者錯誤？","options":["(A) 篩竇最前面的一個結構是鼻丘（agger nasi cell）","(B) 前後篩竇、上頜竇及額竇的黏液經由篩竇漏斗（ethmoid infundibulum）引流到鼻腔","(C) 前篩竇最大的一個結構是篩球（ethmoid bulla）","(D) 前篩竇與後篩竇由基底板（basal lamella）分隔"],"answer":1,"image":""},{"id":"md6-114-2-23","subject":"md6","topic":"喉科學與頭頸腫瘤","meta":"114年第2次第23題","year":114,"session":2,"number":23,"question":"有關青少年鼻咽血管纖維瘤（juvenile nasopharyngeal angiofibroma），下列敘述何者錯誤？","options":["(A) 常見症狀為鼻塞及流鼻血","(B) 大部分發生在10～20歲年輕女性","(C) 手術切除及術後若有殘留腫瘤，則以放射線治療為準則","(D) 手術前內上頜動脈（internal maxillary artery）栓塞是常規處理方式"],"answer":1,"image":""},{"id":"md6-114-2-24","subject":"md6","topic":"喉科學與頭頸腫瘤","meta":"114年第2次第24題","year":114,"session":2,"number":24,"question":"有關先天性的氣管食道瘻管（tracheoesophageal fistula），下列敘述何者正確？","options":["(A) 最常見的解剖類型是H-型的氣管食道瘻管","(B) 以鋇劑吞嚥做食道攝影檢查一定可以診斷出來","(C) 一旦產前診斷出此異常，在胎兒出生時，就必須安排ex utero intrapartum treatment（EXIT）以建立呼吸道來挽救胎兒","(D) 經開胸手術治療後若瘻管復發，可以考慮用內視鏡手術方式治療"],"answer":3,"image":""},{"id":"md6-114-2-25","subject":"md6","topic":"喉科學與頭頸腫瘤","meta":"114年第2次第25題","year":114,"session":2,"number":25,"question":"關於胃食道逆流（gastroesophageal reflux disease, GERD）與喉咽逆流（laryngopharyngeal reflux, LPR）之比較及敘述，下列何者正確？","options":["(A) 胃灼熱感（heartburn）較常見於LPR","(B) GERD之症狀好發於夜間平躺時","(C) 咽喉內視鏡為二者診斷之黃金準則","(D) 進行24小時pH值監測時，探頭（probe）應放置於食道中段與胃賁門處"],"answer":1,"image":""},{"id":"md6-114-2-26","subject":"md6","topic":"喉科學與頭頸腫瘤","meta":"114年第2次第26題","year":114,"session":2,"number":26,"question":"關於下咽癌（hypopharyngeal cancer），下列敘述何者錯誤？","options":["(A) 最常發生於後咽壁（posterior pharyngeal wall）","(B) 女性病人可能和Plummer-Vinson syndrome有關","(C) 癌細胞較容易出現黏膜下擴散（submucosal spread）","(D) 容易經由thyrohyoid membrane轉移至第二至四區（level II～IV）側頸部淋巴結"],"answer":0,"image":""},{"id":"md6-114-2-27","subject":"md6","topic":"喉科學與頭頸腫瘤","meta":"114年第2次第27題","year":114,"session":2,"number":27,"question":"關於胸大肌皮瓣（pectoralis major myocutaneous flap）的血管供應來自下列何者？","options":["(A) superior thoracic artery","(B) thoracoacromial artery","(C) lateral thoracic artery","(D) subscapular artery"],"answer":1,"image":""},{"id":"md6-114-2-28","subject":"md6","topic":"婦科-手術學與診斷技術","meta":"114年第2次第28題","year":114,"session":2,"number":28,"question":"子宮由多條韌帶（ligaments）連接，下列何者除外？","options":["(A) Cooper's ligament","(B) broad ligament","(C) round ligament","(D) cardinal ligament"],"answer":0,"image":""},{"id":"md6-114-2-29","subject":"md6","topic":"產科-一般產科","meta":"114年第2次第29題","year":114,"session":2,"number":29,"question":"關於懷孕期間胃腸系統的變化，下列敘述何者正確？","options":["(A) 闌尾（appendix）因子宮的壓迫位置會下移至比正常解剖位置低","(B) 食道蠕動（esophageal peristalsis）的速度及幅度增加","(C) 胃排空時間（gastric emptying time）不變","(D) 血清白蛋白（serum albumin）濃度不變"],"answer":2,"image":""},{"id":"md6-114-2-30","subject":"md6","topic":"產科-高危險妊娠","meta":"114年第2次第30題","year":114,"session":2,"number":30,"question":"急診送來一名下腹痛合併陰道出血的36歲女性，G2P1，上一胎是在三年前懷孕38週經陰道自然生產，目前這一次懷孕的週數依最後一次月經開始日計算約為懷孕8週。病患到急診時臉色蒼白、不論站或坐均感到頭昏眼花，體溫37°C、脈搏每分鐘110下、呼吸每分鐘18次、血壓86/50 mmHg，腹部理學檢查發現：腹部明顯壓痛合併反彈痛，骨盆腔理學檢查發現：少量陰道出血、右側子宮附屬器明顯脹痛，尿液懷孕測試呈陽性反應，骨盆腔超音波檢查發現：右側子宮附屬器子宮外孕、且骨盆腔中已有大量積液，抽血發現血比容（hematocrit）27%，依此病患的狀況，下列何者為在急診最適當的下一步處置？","options":["(A) 等病患空腹時間滿8～10小時後安排手術","(B) 轉入加護病房觀察","(C) 使用methotrexate肌肉注射治療","(D) 安排緊急手術切除子宮外孕處及止血"],"answer":3,"image":""},{"id":"md6-114-2-31","subject":"md6","topic":"產科-一般產科","meta":"114年第2次第31題","year":114,"session":2,"number":31,"question":"懷孕時胎兒腎上腺製造很多類固醇（steroid）以供母體荷爾蒙產生，這些類固醇（steroid）主要之前驅物（precursor）為何？","options":["(A) 低密度脂蛋白膽固醇（low-density lipoprotein cholesterol）","(B) 高密度脂蛋白膽固醇（high-density lipoprotein cholesterol）","(C) 三酸甘油脂（triglyceride）","(D) 雌三醇（estriol）"],"answer":0,"image":""},{"id":"md6-114-2-32","subject":"md6","topic":"產科-高危險妊娠","meta":"114年第2次第32題","year":114,"session":2,"number":32,"question":"造成孕婦母血中α-胎兒蛋白（AFP）上升的原因，下列敘述何者錯誤？","options":["(A) 低估懷孕週數","(B) 胎兒神經管缺損","(C) 胎兒薦尾畸胎瘤","(D) 胎兒唐氏症"],"answer":3,"image":""},{"id":"md6-114-2-33","subject":"md6","topic":"產科-一般產科","meta":"114年第2次第33題","year":114,"session":2,"number":33,"question":"有關胎兒無壓力測試（nonstress test）的敘述，下列何者正確？","options":["(A) 20分鐘內觀察到一次胎動合併胎兒心率上升每分鐘15下以上，即為正常","(B) 胎兒心跳變異性小於5 bpm代表胎兒已成熟","(C) 若測試結果為無反應性（nonreactive），可以增加觀察時間到40分鐘","(D) 若胎心音有早期減速之現象，須在24小時內生產"],"answer":2,"image":""},{"id":"md6-114-2-34","subject":"md6","topic":"產科-高危險妊娠","meta":"114年第2次第34題","year":114,"session":2,"number":34,"question":"與唐氏症相關之第二孕期胎兒超音波軟指標（soft signs）不包含下列何者？","options":["(A) 小腸回音增加（echogenic bowel）","(B) 腹壁裂（gastroschisis）","(C) 頸部皺褶增厚（nuchal fold thickening）","(D) 輕度腎盂擴張（mild renal pelvis dilation）"],"answer":1,"image":""},{"id":"md6-114-2-35","subject":"md6","topic":"產科-一般產科","meta":"114年第2次第35題","year":114,"session":2,"number":35,"question":"一位34歲第二胎產婦到院產房胎心音宮縮監測器顯示不規則陣痛，骨盆腔內診後發現，子宮頸質地柔軟子宮頸開口1～2公分並開口朝前，子宮頸變薄50%，station -2，此時Bishop score為何？","options":["(A) 3分","(B) 5分","(C) 7分","(D) 9分"],"answer":2,"image":""},{"id":"md6-114-2-36","subject":"md6","topic":"產科-一般產科","meta":"114年第2次第36題","year":114,"session":2,"number":36,"question":"關於催生（induction and augmentation of labor）的注意事項，下列敘述何者最不適當？","options":["(A) 人工破水可以加速產程約1～1.5小時","(B) misoprostol（prostaglandin E1）用來催生有子宮破裂風險","(C) 當靜脈注射oxytocin用來刺激子宮收縮時，其半衰期3～5分鐘停藥很快可緩解","(D) 子宮收縮達到150個Montevideo units為有效的催生，多數產婦進入active phase"],"answer":3,"image":""},{"id":"md6-114-2-37","subject":"md6","topic":"產科-高危險妊娠","meta":"114年第2次第37題","year":114,"session":2,"number":37,"question":"妊娠糖尿病常合併羊水過多（hydramnios），下列何者為較有可能之原因？","options":["(A) 因母體高血糖致內皮細胞滲漏","(B) 胎兒腎絲球對葡萄糖的再吸收","(C) 羊水中的高葡萄糖濃度","(D) 因胎兒高血糖導致胎兒腸胃道狹窄或阻塞"],"answer":2,"image":""},{"id":"md6-114-2-38","subject":"md6","topic":"產科-高危險妊娠","meta":"114年第2次第38題","year":114,"session":2,"number":38,"question":"對妊娠糖尿病孕婦的飲食建議，下列敘述何者錯誤？","options":["(A) 平均每天卡路里應攝取30～35 kcal/公斤","(B) 根據美國婦產科醫學會（ACOG）建議，每天攝取的卡路里當中，蛋白質應占約20%","(C) 根據美國婦產科醫學會（ACOG）建議，每天的飲食中碳水化合物的比例要越低越好，以維持適當的血糖值","(D) 根據美國婦產科醫學會（ACOG）建議，每天攝取的卡路里當中，脂肪應占約40%"],"answer":2,"image":""},{"id":"md6-114-2-39","subject":"md6","topic":"產科-高危險妊娠","meta":"114年第2次第39題","year":114,"session":2,"number":39,"question":"過期妊娠（postterm pregnancy）導致不良妊娠結局（adverse pregnant outcome）不包括下列那一情況？","options":["(A) 羊水過多（polyhydramnios）","(B) 子癇前症（preeclampsia）","(C) 肩難產（shoulder dystocia）","(D) 產後出血（postpartum hemorrhage）"],"answer":0,"image":""},{"id":"md6-114-2-40","subject":"md6","topic":"婦科-手術學與診斷技術","meta":"114年第2次第40題","year":114,"session":2,"number":40,"question":"下列何者不是婦產科腹腔鏡手術常見的併發症？","options":["(A) liver injury","(B) bladder injury","(C) great vessel injury","(D) thermal injury"],"answer":0,"image":""},{"id":"md6-114-2-41","subject":"md6","topic":"婦科-手術學與診斷技術","meta":"114年第2次第41題","year":114,"session":2,"number":41,"question":"對於機器人手術（robotic surgery）的手術適應症，下列敘述何者最不適當？","options":["(A) 子宮肌瘤手術","(B) 輸卵管重建手術","(C) 骨盆重建手術","(D) 第二期子宮頸癌"],"answer":3,"image":""},{"id":"md6-114-2-42","subject":"md6","topic":"婦科-手術學與診斷技術","meta":"114年第2次第42題","year":114,"session":2,"number":42,"question":"子宮鏡可提供治療性的手術選擇（operative hysteroscopy）。下列何者較少考慮使用子宮鏡來治療？","options":["(A) FIGO子宮肌瘤分期Type 0","(B) FIGO子宮肌瘤分期Type 1","(C) FIGO子宮肌瘤分期Type 2","(D) FIGO子宮肌瘤分期Type 3"],"answer":3,"image":""},{"id":"md6-114-2-43","subject":"md6","topic":"婦科-生殖內分泌","meta":"114年第2次第43題","year":114,"session":2,"number":43,"question":"有關Kallmann氏症候群（Kallmann syndrome），下列敘述何者最不適當？","options":["(A) 主要症狀為嗅覺缺失（anosmia）、性腺功能低下症（hypogonadism）與色盲（color blindness）","(B) 男性發生率高於女性","(C) 女性患者通常表現原發性閉經（primary amenorrhea）","(D) 女性患者抽血檢驗，通常FSH數值很高，但E2數值很低"],"answer":3,"image":""},{"id":"md6-114-2-44","subject":"md6","topic":"婦科-生殖道感染與先天異常","meta":"114年第2次第44題","year":114,"session":2,"number":44,"question":"下列關於女性生殖道異常的敘述，何者錯誤？","options":["(A) 有先天性生殖道異常的女性患者，常常也併有泌尿系統的異常","(B) 馬蹄腎（horseshoe kidney）的發生率約為1/600","(C) 有先天性生殖道異常的女性成年患者，可能併有單側或雙側的腎發育不全（renal agenesis）狀況","(D) 先天性泌尿道異常，可源自於輸尿管芽（ureteric bud）或後腎母細胞（metanephric blastema）之異常"],"answer":2,"image":""},{"id":"md6-114-2-45","subject":"md6","topic":"婦科-生殖道感染與先天異常","meta":"114年第2次第45題","year":114,"session":2,"number":45,"question":"濕檢視（wet mount smear）最無法辨認下列何者？","options":["(A) 正常陰道表面上皮細胞","(B) 乳酸菌（lactobacilli）","(C) 細菌性陰道炎（bacterial vaginosis）","(D) 淋病雙球菌（Neisseria gonorrhoeae）"],"answer":3,"image":""},{"id":"md6-114-2-46","subject":"md6","topic":"婦科-生殖道感染與先天異常","meta":"114年第2次第46題","year":114,"session":2,"number":46,"question":"下列那兩種型別的人類乳突瘤病毒（human papillomavirus），是造成外陰部生殖疣（genital warts）最常見的原因？","options":["(A) 6、11","(B) 16、18","(C) 52、58","(D) 31、33"],"answer":0,"image":""},{"id":"md6-114-2-47","subject":"md6","topic":"婦科-腫瘤","meta":"114年第2次第47題","year":114,"session":2,"number":47,"question":"一位13歲女生因腹脹就醫，超音波檢查發現骨盆腔有一個12公分複雜性腫瘤；血液檢驗AFP 586 ng/mL，最可能的診斷是：","options":["(A) dysgerminoma","(B) endodermal sinus tumor","(C) non-gestational choriocarcinoma","(D) immature teratoma"],"answer":1,"image":""},{"id":"md6-114-2-48","subject":"md6","topic":"婦科-腫瘤","meta":"114年第2次第48題","year":114,"session":2,"number":48,"question":"30歲女性，在健康檢查時，意外在骨盆超音波下，發現如圖所示之腫塊，最有可能的診斷為何？","options":["(A) 出血性黃體囊腫（hemorrhagic corpus luteum）","(B) 子宮內膜異位瘤（endometrioma）","(C) 畸胎瘤（teratoma）","(D) 功能性囊腫（functional cyst）"],"answer":2,"image":"md6-114-2-48.jpeg"},{"id":"md6-114-2-49","subject":"md6","topic":"婦科-腫瘤","meta":"114年第2次第49題","year":114,"session":2,"number":49,"question":"下列有關卵巢未成熟畸胎瘤（immature teratoma）的處置，何者不適當？","options":["(A) 停經前的患者中，應進行單側卵巢切除術和保留生育能力的分期手術","(B) 未成熟的畸胎瘤通常局限於單側卵巢，對側卵巢無須常規進行楔形切片（wedge biopsy）","(C) 未成熟畸胎瘤最重要的預後因子是細胞分化（grade），因此IA期low-grade的患者，無須接受輔助化學治療","(D) 對於有接受輔助化學治療的患者，進行二次剖腹探查（second-look operation）以確認療效是必要的"],"answer":3,"image":""},{"id":"md6-114-2-50","subject":"md6","topic":"婦科-腫瘤","meta":"114年第2次第50題","year":114,"session":2,"number":50,"question":"一位52歲女性因停經後出血發現子宮內膜癌，回顧其家族史發現有乳癌及大腸癌病史，因此考慮進行遺傳諮詢。此家族最有可能有下列那種遺傳性疾病？","options":["(A) BRCA2基因突變","(B) 遺傳性非息肉大腸直腸癌（Lynch II syndrome）","(C) 考登氏症候群（Cowden syndrome）","(D) 黑斑息肉症候群（Peutz–Jeghers syndrome）"],"answer":1,"image":""},{"id":"md6-114-2-51","subject":"md6","topic":"婦科-腫瘤","meta":"114年第2次第51題","year":114,"session":2,"number":51,"question":"對於子宮頸癌手術後骨盆淋巴結陽性者（positive pelvic lymph nodes），下列有關輔助性放射治療（adjuvant radiation）之敘述何者正確？","options":["(A) 可減少骨盆復發，但未能提高5年存活率","(B) 可減少骨盆復發，亦能提高5年存活率","(C) 可降低遠處轉移，但未能提高5年存活率","(D) 可降低遠處轉移，亦能提高5年存活率"],"answer":0,"image":""},{"id":"md6-114-2-52","subject":"md6","topic":"婦科-腫瘤","meta":"114年第2次第52題","year":114,"session":2,"number":52,"question":"關於子宮內膜癌的不良預後因子，下列敘述何者錯誤？","options":["(A) 年紀大（＞60歲）","(B) 後腹腔淋巴結轉移","(C) 肥胖","(D) 腫瘤基因DNA多倍染色體"],"answer":2,"image":""},{"id":"md6-114-2-53","subject":"md6","topic":"婦科-腫瘤","meta":"114年第2次第53題","year":114,"session":2,"number":53,"question":"關於子宮頸腺癌（adenocarcinoma）的敘述，下列何者正確？","options":["(A) 腺癌的處理原則一般和鱗狀上皮細胞癌類似","(B) 腺癌的比例在抹片篩檢下逐漸減少","(C) 大部分子宮頸腺癌和人類乳突病毒無關","(D) 早期腺癌的病灶程度藉由子宮頸切片就可以確定"],"answer":0,"image":""},{"id":"md6-114-2-54","subject":"md6","topic":"婦科-生殖內分泌","meta":"114年第2次第54題","year":114,"session":2,"number":54,"question":"試管嬰兒療程中，下列何者不是造成卵巢過度刺激症候群（ovarian hyperstimulation syndrome, OHSS）的危險因子？","options":["(A) 多囊性卵巢症候群（polycystic ovarian syndrome）","(B) AMH 2 ng/mL","(C) 注射hCG當天雌二醇（estradiol）濃度3,600 pg/mL","(D) 取24顆卵子"],"answer":1,"image":""},{"id":"md6-114-2-55","subject":"md6","topic":"婦科-生殖內分泌","meta":"114年第2次第55題","year":114,"session":2,"number":55,"question":"關於罹患更年期症候群之停經婦女，為避免荷爾蒙所造成的風險，建議荷爾蒙補充的敘述何者正確？","options":["(A) 60歲以上，或停經時間滿10年以上","(B) 60歲以下，或停經時間未滿10年","(C) 無年齡限制，隨時都可以開始進行荷爾蒙補充","(D) 不論年齡為何，都不建議補充荷爾蒙"],"answer":1,"image":""},{"id":"md6-114-2-56","subject":"md6","topic":"婦科-生殖內分泌","meta":"114年第2次第56題","year":114,"session":2,"number":56,"question":"51歲G3P3的女性，因為月經半年沒來而求診，身體熱潮的情形嚴重，影響睡眠品質，且已經造成日間工作的困擾。又沒有慢性疾病，目前也沒有服用藥物，但有考慮開始接受荷爾蒙療法（hormone therapy）。在分析治療的好處和風險時，應該告知荷爾蒙療法會增加何項疾病的風險？","options":["(A) 大腸癌","(B) 血栓性栓塞","(C) 骨質疏鬆症","(D) 阿茲海默症（Alzheimer disease）"],"answer":1,"image":""},{"id":"md6-114-2-57","subject":"md6","topic":"婦科-尿失禁與骨盆腔脫垂","meta":"114年第2次第57題","year":114,"session":2,"number":57,"question":"陰道生產容易造成骨盆底鬆弛，導致女性生殖道脫垂與應力性尿失禁的發生率比男性高。下列敘述何者正確？","options":["(A) 陰道產次越多，越易產生生殖道脫垂","(B) 胎數越多，發生尿失禁的風險也相對遽增","(C) 生殖道脫垂的程度，早晨起床時最為嚴重","(D) 年齡越大，應力性尿失禁的機率遽增"],"answer":0,"image":""},{"id":"md6-114-2-58","subject":"md6","topic":"復健-神經復健","meta":"114年第2次第58題","year":114,"session":2,"number":58,"question":"關於遺傳性運動感覺神經病變（hereditary motor and sensory neuropathies），下列敘述何者最不恰當？","options":["(A) 常發生對稱進行性的肌肉無力（symmetric progressive weakness）","(B) 第一型（type I）主要是影響髓鞘（myelin）","(C) 以遠端肌肉群（distal musculature）無力較為明顯","(D) 常常有疼痛（pain）的症狀"],"answer":[0,1,2,3],"image":"","answer_note":"送分:第58題一律給分 (原公告答案 D)"},{"id":"md6-114-2-59","subject":"md6","topic":"復健-神經復健","meta":"114年第2次第59題","year":114,"session":2,"number":59,"question":"有關脊髓損傷病人之慢性神經性疼痛（neuropathic pain），下列敘述何者最不適當？","options":["(A) 可能有異態痛感（allodynia）","(B) 受傷部位（at level）神經痛可能源自於脊髓壓迫（cord compression）","(C) 受傷部位以下（below level）神經痛可能和大腦痛覺的重組（reorganization）有關","(D) 受傷部位以下（below level）的疼痛醫學上稱為幻肢痛（phantom pain）"],"answer":3,"image":""},{"id":"md6-114-2-60","subject":"md6","topic":"復健-神經復健","meta":"114年第2次第60題","year":114,"session":2,"number":60,"question":"偵測脊髓損傷病人早期產生異位性骨化（heterotopic ossification）最敏感的影像偵測工具為下列何者？","options":["(A) 三相骨骼掃描","(B) 核磁共振","(C) 電腦斷層","(D) X光"],"answer":0,"image":""},{"id":"md6-114-2-61","subject":"md6","topic":"復健-神經復健","meta":"114年第2次第61題","year":114,"session":2,"number":61,"question":"關於中風之動作評估，若一位病人可將手平舉過頭、手可以從側面伸上來到水平位置、手肘伸直時可以旋後和旋前、拇指可以碰到食指指節，則其布朗斯壯分期（Brunnstrom stage）最可能為那一期？","options":["(A) II","(B) III","(C) IV","(D) V"],"answer":3,"image":""},{"id":"md6-114-2-62","subject":"md6","topic":"復健-物理因子治療與評估","meta":"114年第2次第62題","year":114,"session":2,"number":62,"question":"有關電療（electrotherapy）在物理醫學中的應用，下列敘述何者最不適當？","options":["(A) 電療的生理效應包括抑制疼痛","(B) 電療的生理效應包括增加循環及減少肌肉痙攣","(C) 電刺激有止痛和消腫的作用，對於剛發生未經固定的骨折部位有很大的幫助","(D) 進行干擾波電療時，電極的擺放原則是圍繞著欲治療部位"],"answer":2,"image":""},{"id":"md6-114-2-63","subject":"md6","topic":"復健-截肢與義肢輔具","meta":"114年第2次第63題","year":114,"session":2,"number":63,"question":"有關截肢（amputation），下列敘述何者最不適當？","options":["(A) 截肢（amputation）是指肢體缺損的狀態，可分為先天性肢體缺損與後天性截肢","(B) 先天性肢體缺損，發生在下肢的機率比上肢多；後天性截肢發生於上肢的比例明顯高於下肢","(C) 以截肢部位來看，上肢截肢以外傷為主要原因，其中以手指截肢（finger amputation）最多","(D) 近年來由於重建與再植手術技術的進步，以及職業安全觀念的提升，外傷截肢的比例已逐年下降中"],"answer":1,"image":""},{"id":"md6-114-2-64","subject":"md6","topic":"復健-神經復健","meta":"114年第2次第64題","year":114,"session":2,"number":64,"question":"旋前症候群（pronator syndrome）的主要症狀是前臂的疼痛、無力及麻木，下列那一條神經與此症狀最有關係？","options":["(A) 正中神經（median nerve）","(B) 尺神經（ulnar nerve）","(C) 橈神經（radial nerve）","(D) 肌皮神經（musculocutaneous nerve）"],"answer":0,"image":""},{"id":"md6-114-2-65","subject":"md6","topic":"復健-心肺復健與運動處方","meta":"114年第2次第65題","year":114,"session":2,"number":65,"question":"在呼吸加護病房中，關於早期介入胸腔復健活動之敘述，下列何者最恰當？","options":["(A) 即使是生命現象穩定，三天內介入活動治療，對病人仍然不宜","(B) 當病人意識清楚時，儘量採取被動的四肢關節活動","(C) 當病人意識不清楚時，介入復健治療主要在訓練呼吸肌力","(D) 早期胸腔復健運動介入，可協助改善呼吸器脫離率"],"answer":3,"image":""},{"id":"md6-114-2-66","subject":"md6","topic":"復健-兒童與一般復健","meta":"114年第2次第66題","year":114,"session":2,"number":66,"question":"關於腦性麻痺（cerebral palsy）患者的肌肉骨骼系統（musculoskeletal system），下列敘述何者最不適當？","options":["(A) 肉毒桿菌素注射是改善肌肉張力（muscle tone）的方式之一","(B) 造成髖關節發育不良（hip dysplasia）的其中一個因素是因為患者的髖關節較少承載體重（weight bearing）","(C) 無法行走（nonambulatory）的腦性麻痺患者，髖關節脫位（hip dislocation）的風險較高","(D) 髖部疼痛（hip pain）和髖關節脫位（hip dislocation）的嚴重度直接相關"],"answer":3,"image":""},{"id":"md6-114-2-67","subject":"md6","topic":"復健-兒童與一般復健","meta":"114年第2次第67題","year":114,"session":2,"number":67,"question":"下列關於早期療育（early intervention）與發展遲緩（developmental delay）的敘述，何者最不適當？","options":["(A) 早期療育主要是針對未滿6歲的發展遲緩兒童及其家庭，提供必要之治療、教育與其他服務","(B) 發展遲緩是指出生後的兒童在運動、知覺（perception）、語言、情緒（emotion）、認知（cognition）、心理（psychogenesis）、社會適應性（socio-behavior）等各方面出現一種或數種的發展落後或異常表現","(C) 根據世界衛生組織（WHO）的統計，發展遲緩的發生率約為千分之六至千分之八","(D) 早期療育的精神是希望提供早期發現、早期診斷及早期治療"],"answer":2,"image":""},{"id":"md6-114-2-68","subject":"md6","topic":"復健-骨骼肌肉損傷與疾患","meta":"114年第2次第68題","year":114,"session":2,"number":68,"question":"有關口腔癌病人術後產生牙關緊閉（trismus）的復健評估與治療，下列何者最適當？","options":["(A) 牙關緊閉的診斷標準是門齒間距（inter-incisor distance）小於5公分","(B) 化學治療是造成遲發性牙關緊閉的最大原因","(C) 嚼食檳榔者在手術前不易有牙關緊閉的現象","(D) 牙關緊閉的復健治療最好是在後期病情穩定之後再開始"],"answer":[0,1,2,3],"image":"","answer_note":"送分:第68題一律給分 (原公告答案 A)"},{"id":"md6-114-2-69","subject":"md6","topic":"復健-神經復健","meta":"114年第2次第69題","year":114,"session":2,"number":69,"question":"有關巴氏量表（Barthel index）之敘述，下列何者最不適當？","options":["(A) 為一常用的基本日常生活能力評估量表","(B) 評估項目共有7項","(C) 依現行規定，80歲以上的年長者，總分低於60分方可申請外籍看護","(D) 總分為0分者，代表在日常生活中完全依賴他人的協助"],"answer":[1,2],"image":"","answer_note":"更正:第69題答Ｂ或Ｃ或BC者均給分"},{"id":"md6-114-2-70","subject":"md6","topic":"復健-神經復健","meta":"114年第2次第70題","year":114,"session":2,"number":70,"question":"有關復健醫療照護之敘述，下列何者最不適當？","options":["(A) 疾病的種類（如中風，脊髓損傷等）為界定復健療程或黃金治療期的主要依據","(B) 復健醫療的貢獻是改善病人的生活品質、降低醫療及照顧之社會成本、增進家庭和諧及減少社會問題等","(C) 復健醫療的對象是「全人」，而非只是「病人」","(D) 在急性期時，復健潛能為決定復健醫療層次的主要依據"],"answer":0,"image":""},{"id":"md6-114-2-71","subject":"md6","topic":"復健-神經復健","meta":"114年第2次第71題","year":114,"session":2,"number":71,"question":"林先生因中風導致左側偏癱，能夠自己行走但偶爾會被不平整的地面絆倒；一般基本的日常生活及自我照顧活動都僅需要監督或輕微協助即可自己獨立完成。林先生希望回家後，可以自己洗澡、上廁所，可自行到客廳看電視，且希望中午可用微波爐準備簡單餐點。此外，林先生也希望其太太與女兒可以上班。下列有關治療師根據林先生的需求與能力，給出的建議與環境改造計畫，何者最不適當？","options":["(A) 林先生的家屬不應該讓林先生自行待在家，應該請個看護或離職在家照顧其生活起居","(B) 去除家裡不平整的地毯，減少被絆倒的機會","(C) 在浴室的淋浴與馬桶旁安裝扶手","(D) 在大門前的階梯兩側加裝扶手，且於每一台階的前端漆上白漆，以增加辨識度"],"answer":0,"image":""},{"id":"md6-114-2-72","subject":"md6","topic":"復健-神經復健","meta":"114年第2次第72題","year":114,"session":2,"number":72,"question":"關於腦囊狀動脈瘤（saccular aneurysm）的敘述，下列何者最不恰當？","options":["(A) 前交通動脈（anterior communicating artery）是常見的位置之一","(B) 在電腦斷層上，巨大的腦動脈瘤可能會有鈣化","(C) 蜘蛛網膜下腔出血病患接受血管攝影檢查，若未發現動脈瘤，即可排除動脈瘤破裂","(D) 血管內栓塞術是治療腦動脈瘤的方式之一"],"answer":2,"image":""},{"id":"md6-114-2-73","subject":"md6","topic":"婦科-手術學與診斷技術","meta":"114年第2次第73題","year":114,"session":2,"number":73,"question":"34歲女性子宮輸卵管攝影檢查呈現如圖，箭號所指之病灶，下列何者為最恰當之診斷？","options":["(A) 輸卵管積水（hydrosalpinx）","(B) 子宮（輸卵管）外孕","(C) 輸卵管惡性腫瘤","(D) 子宮內膜異位"],"answer":0,"image":"md6-114-2-73.jpeg"},{"id":"md6-114-2-74","subject":"md6","topic":"婦科-腫瘤","meta":"114年第2次第74題","year":114,"session":2,"number":74,"question":"一位年輕女性接受磁振造影檢查發現卵巢腫瘤如圖，箭號所指之病灶，下列何者為最恰當之診斷？","options":["(A) 畸胎瘤","(B) 血腫","(C) 黃體囊腫","(D) 巧克力囊腫"],"answer":0,"image":"md6-114-2-74.jpeg"},{"id":"md6-114-2-75","subject":"md6","topic":"復健-神經復健","meta":"114年第2次第75題","year":114,"session":2,"number":75,"question":"關於Guillain-Barré症候群的敘述，下列何者最不適當？","options":["(A) 此症候群通常在病毒感染或疫苗注射後發生","(B) 為急性多發神經病變（polyneuropathy），合併神經髓鞘（myelin sheath）受損","(C) 典型症狀為神經麻痺，由軀幹往下沿伸到下肢","(D) 此症候群可能會導致呼吸肌肉麻痺"],"answer":2,"image":""},{"id":"md6-114-2-76","subject":"md6","topic":"產科-一般產科","meta":"114年第2次第76題","year":114,"session":2,"number":76,"question":"關於流產的敘述，下列何者最適當？","options":["(A) 先兆流產（Threatened abortion）：懷孕＜22週子宮頸擴張相關的帶血性陰道分泌物","(B) 不完全流產（Incomplete abortion）：胚胎或胎兒流出而有部分或全胎盤殘留","(C) 化膿性流產（Septic abortion）：常見於流產後發生，電腦斷層是最適合的診斷工具","(D) 過期流產（Missed abortion）：懷孕＜20週胎兒心跳消失，胎兒仍存留於子宮"],"answer":[1,3],"image":"","answer_note":"更正:第76題答Ｂ或Ｄ或BD者均給分"},{"id":"md6-114-2-77","subject":"md6","topic":"麻醉-麻醉藥理","meta":"114年第2次第77題","year":114,"session":2,"number":77,"question":"25歲男性病人有頭部外傷，須實施快速順序插管（rapid-sequence intubation），當使用神經肌肉阻斷劑succinylcholine時，下列有關succinylcholine的敘述，何者最不適當？","options":["(A) 可能會造成橫紋肌溶解","(B) 若該病人合併有燒燙傷，succinylcholine比rocuronium合適","(C) 可能造成顱內壓上升及眼壓上升","(D) 可能造成胃內壓上升"],"answer":1,"image":""},{"id":"md6-114-2-78","subject":"md6","topic":"醫學倫理與法規","meta":"114年第2次第78題","year":114,"session":2,"number":78,"question":"依據赫爾辛基宣言（Declaration of Helsinki），醫師在取得受試同意書時，應特別注意受試者是否對醫師有依賴關係，或受試者是否在脅迫下同意。倘若有上述現象時，應如何處理？","options":["(A) 此醫師取得受試同意書的過程，需在有公正見證人在場的情況下進行","(B) 此醫師取得受試同意書的過程，需在受試者之律師陪同下進行","(C) 無法客觀取得受試同意書，此病患無法參加此研究","(D) 此受試同意書應由一位充分了解此研究，但獨立於此醫病關係外之合格人員取得"],"answer":3,"image":""},{"id":"md6-114-2-79","subject":"md6","topic":"醫學倫理與法規","meta":"114年第2次第79題","year":114,"session":2,"number":79,"question":"有關告知義務，下列何者錯誤？","options":["(A) 醫師履行告知義務時，應鼓勵病人發問","(B) 醫師應說明延誤或拒絕治療之後果","(C) 考慮華人社會中之家庭價值，在告知上應以尊重家屬意見為優先","(D) 醫師履行告知義務時，應給予病人充分的時間考慮"],"answer":2,"image":""},{"id":"md6-114-2-80","subject":"md6","topic":"醫學倫理與法規","meta":"114年第2次第80題","year":114,"session":2,"number":80,"question":"末期病人昏迷使用呼吸器，無法簽署不施行心肺復甦術意願書，依我國法律規定之親屬代理決定權，同意書代理簽署的優先順序為：","options":["(A) 配偶＞成年子女、孫子女＞兄弟姐妹","(B) 父母＞兄弟姐妹＞成年子女、孫子女","(C) 祖父母＞父母＞兄弟姐妹","(D) 曾祖父母＞祖父母＞一親等直系姻親"],"answer":0,"image":""},{"id":"md6-115-1-1","subject":"md6","topic":"麻醉-呼吸道與監視","meta":"115年第1次第1題","year":115,"session":1,"number":1,"question":"麻醉醫師對病人作術前訪視，按modified Mallampati classification進行氣道評估分類。病人嘴張到最大、舌頭伸到最長，不使用壓舌棒下，只能看見soft palate、base of the uvula，不能看見tonsillar pillars、fauces。依據前述，屬於何等級？","options":["(A) class Ⅰ","(B) class Ⅱ","(C) class Ⅳ","(D) class Ⅲ"],"answer":3,"image":""},{"id":"md6-115-1-2","subject":"md6","topic":"麻醉-呼吸道與監視","meta":"115年第1次第2題","year":115,"session":1,"number":2,"question":"關於術中心電圖（ECG）監測，下列何者錯誤？","options":["(A) ECG中的ST segment代表心肌的再極化，對心肌缺血最敏感","(B) 術中發生myocardial ischemia，表現常為ECG ST segment depression","(C) 術中發生的myocardial ischemia大多可以清楚定位缺血區域","(D) 對缺血敏感度最高的lead是V5，次之則是V4"],"answer":[0,2],"image":"","answer_note":"更正:第2題答Ａ或Ｃ或AC者均給分"},{"id":"md6-115-1-3","subject":"md6","topic":"麻醉-呼吸道與監視","meta":"115年第1次第3題","year":115,"session":1,"number":3,"question":"重大手術麻醉與術後常須更密切、甚至侵入性的循環監測，下列有關循環監測的敘述何者最適當？","options":["(A) 設立radial artery catheter之前，先做Allen test已被證實可以減少導管置入之相關後遺症","(B) 在股動脈導管測得的pulse pressure，基於波型反射原理，可以預測比在主動脈測得的pulse pressure數值為低","(C) 中央靜脈壓（central venous pressure）為最準確的循環血量測量，在重大手術監測與處置中扮演重要角色","(D) 潮氣末二氧化碳（end-tidal CO2）可以被轉換利用來監測心輸出量（cardiac output）的變化"],"answer":3,"image":""},{"id":"md6-115-1-4","subject":"md6","topic":"麻醉-特殊麻醉與疼痛","meta":"115年第1次第4題","year":115,"session":1,"number":4,"question":"35歲懷孕女性病人，因剖腹生產接受半身麻醉（spinal anesthesia）後第二天抱怨頭痛，且每當由床上要坐起來時，會加劇疼痛。平躺不久之後會立刻改善，此疼痛的部位在枕部且會擴散至肩部，其他的生命徵象都良好。此時的鑑別診斷最可能是下列何者？","options":["(A) 腦膜炎","(B) 顱內壓增加","(C) 張力性頭痛（tension headache）","(D) 硬脊膜穿刺後頭痛（post-dural puncture headache）"],"answer":3,"image":""},{"id":"md6-115-1-5","subject":"md6","topic":"麻醉-麻醉藥理","meta":"115年第1次第5題","year":115,"session":1,"number":5,"question":"Cisatracurium神經肌肉阻斷劑，具有下列何項作用？①肌肉鬆弛作用 ②意識喪失 ③止痛 ④記憶缺失","options":["(A) 僅①","(B) ①②④","(C) ①②③","(D) ①③④"],"answer":0,"image":""},{"id":"md6-115-1-6","subject":"md6","topic":"產科-一般產科","meta":"115年第1次第6題","year":115,"session":1,"number":6,"question":"作為產房值班的第一線醫師，以下有幾床病人表示希望施打減痛分娩。下列四位孕婦中，那一位最適合施打減痛分娩的硬脊膜外導管（epidural catheter）？6","options":["(A) 36歲王女士當天早上抽血血小板數量較低，僅100,000×10/L","(B) 33歲方女士開過腰椎手術，背部傷口附近有滲液，有感染的可能性","(C) 41歲的林女士罹患風濕性心臟病（rheumatic heart disease），且有重度的主動脈狹窄（aortic stenosis）","(D) 39歲的高女士在懷孕期間發現有腦部腫瘤2"],"answer":0,"image":""},{"id":"md6-115-1-7","subject":"md6","topic":"麻醉-呼吸道與監視","meta":"115年第1次第7題","year":115,"session":1,"number":7,"question":"60歲男性，身體質量指數35 kg/m，因上消化道出血需進行緊急剖腹探查，術前實驗檢查血紅素為8 g/dL，未用氧氣下血氧濃度為94%，以ARISCAT Score評估術後發生肺部併發症為高風險，下列何者不是ARISCAT Score的評估項目？","options":["(A) 身體質量指數","(B) 年齡","(C) 術前血紅素","(D) 緊急手術"],"answer":0,"image":""},{"id":"md6-115-1-8","subject":"md6","topic":"麻醉-特殊麻醉與疼痛","meta":"115年第1次第8題","year":115,"session":1,"number":8,"question":"所謂的caudal block，麻醉藥會分布在下列何處，以達到止痛及麻醉效果？","options":["(A) 硬膜下空間（subdural space）","(B) 硬膜上空間（epidural space）","(C) intrathecal space","(D) epi-sacrococcygeal ligament space"],"answer":1,"image":""},{"id":"md6-115-1-9","subject":"md6","topic":"麻醉-麻醉藥理","meta":"115年第1次第9題","year":115,"session":1,"number":9,"question":"腎臟低灌流（hypoperfusion）是腎前性氮血症（prerenal azotemia）的主因，下列藥物何者不會直接作用在腎血管造成腎臟低灌流？","options":["(A) 使用norepinephrine或vasopressin等血管收縮藥物","(B) 使用ketololac等抑制環氧酶（cyclooxygenase）的止痛藥","(C) 使用抑制血管收縮素轉化酶（angiotensin converting enzyme）的抗高血壓藥物","(D) 使用低劑量硝化甘油輸注（nitroglycerin infusion）"],"answer":[1,2,3],"image":"","answer_note":"更正:第9題答Ｂ或Ｃ或Ｄ或BC或BD或CD或BCD者均給分"},{"id":"md6-115-1-10","subject":"md6","topic":"眼科-視網膜葡萄膜","meta":"115年第1次第10題","year":115,"session":1,"number":10,"question":"大約百分之十高度近視患者會出現黃斑部血管新生（macular neovascularization），下列何種治療最有幫助？","options":["(A) 全視網膜雷射光凝固術（panretinal photocoagulation）","(B) 玻璃體內注射能持續釋出類固醇之植入物（sustained-released steroid implant）","(C) 玻璃體內注射抗血管內皮生長因子製劑（anti-VEGF agent）","(D) 鞏膜扣壓術（scleral buckling）"],"answer":2,"image":""},{"id":"md6-115-1-11","subject":"md6","topic":"眼科-視網膜葡萄膜","meta":"115年第1次第11題","year":115,"session":1,"number":11,"question":"關於葡萄膜炎相關的實驗室檢查與相對應的疾病描述，下列敘述何者最不適當？","options":["(A) 胸腔X-Ray（chest X-ray）可以協助類肉瘤症（sarcoidosis）或結核感染（tuberculosis）之診斷","(B) 抽血檢驗HLA-B27陽性，與急性虹彩炎（acute anterior uveitis, AAU）和僵直性脊椎炎（ankylosing spondylitis）高度相關","(C) 在梅毒（syphilis）的診斷上，rapid plasma reagin（RPR）或是venereal disease research laboratory（VDRL）有重要的角色。兩者在感染後皆終身陽性，在治療後效價不會下降","(D) 在高眼壓性虹彩炎，如懷疑疱疹病毒（herpesviruses）或是巨細胞（cytomegalovirus）病毒引起，可施行前房穿刺（aqueous tap）送檢polymerase chain reaction（PCR）"],"answer":2,"image":""},{"id":"md6-115-1-12","subject":"md6","topic":"眼科-角膜結膜眼瞼眼窩","meta":"115年第1次第12題","year":115,"session":1,"number":12,"question":"有關眼球表面結構之敘述，下列何者錯誤？","options":["(A) 角膜為透明無血管的組織","(B) 結膜是含血管的組織","(C) 角膜占整體眼球屈光度的1/3","(D) 角膜的鮑曼氏層（Bowman layer）是上皮細胞的基質層（basement membrane）"],"answer":[2,3],"image":"","answer_note":"更正:第12題答Ｃ或Ｄ或CD者均給分"},{"id":"md6-115-1-13","subject":"md6","topic":"眼科-水晶體青光眼","meta":"115年第1次第13題","year":115,"session":1,"number":13,"question":"以Van Herick法評估前房深度時，當周邊前房深度對比角膜厚度為多少時，則建議做隅角鏡的檢查？","options":["(A) ＞1","(B) 1～1/2","(C) 1/2～1/3","(D) ≦1/4"],"answer":3,"image":""},{"id":"md6-115-1-14","subject":"md6","topic":"眼科-水晶體青光眼","meta":"115年第1次第14題","year":115,"session":1,"number":14,"question":"關於正常眼壓性青光眼（normal tension glaucoma）和原發性隅角開放性青光眼（primary open angle glaucoma）的不同，下列敘述何者錯誤？","options":["(A) 日本人較歐美人常罹患正常眼壓性青光眼","(B) 正常眼壓性青光眼較常出現視神經盤出血（disc splinter hemorrhage）","(C) 在正常眼壓性青光眼要特別注意是否有因口服降血壓藥造成夜間低血壓","(D) 正常眼壓性青光眼較容易伴隨中央角膜厚度（central corneal thickness）過厚"],"answer":3,"image":""},{"id":"md6-115-1-15","subject":"md6","topic":"眼科-屈光斜弱視","meta":"115年第1次第15題","year":115,"session":1,"number":15,"question":"下圖視野缺損屬於何者病變？","options":["(A) 左側頂葉（parietal lobe）","(B) 右側視覺皮質（occipital lobe）","(C) 右側顳葉（temporal lobe）","(D) 左側視束（optic tract）"],"answer":1,"image":"md6-115-1-15.jpeg"},{"id":"md6-115-1-16","subject":"md6","topic":"眼科-角膜結膜眼瞼眼窩","meta":"115年第1次第16題","year":115,"session":1,"number":16,"question":"注射顯影劑的核磁共振（MRI）對於下列何種腦部病變的顯像能力較差？","options":["(A) 外傷性頸動脈－中心靜脈竇瘻管（carotid-cavernous fistula）","(B) 腦膜瘤的鈣化表現","(C) 視神經脊髓炎造成的視交叉（optic chiasm）發炎","(D) 蝶鞍上的（suprasellar）腦下垂體腫瘤出血"],"answer":1,"image":""},{"id":"md6-115-1-17","subject":"md6","topic":"眼科-角膜結膜眼瞼眼窩","meta":"115年第1次第17題","year":115,"session":1,"number":17,"question":"關於眼窩隔前蜂窩性組織炎（preseptal cellulitis），下列敘述何者錯誤？","options":["(A) 金黃色葡萄球菌為常見之致病菌","(B) 不會造成腦膜炎的嚴重併發症","(C) 可能因蚊蟲叮咬造成","(D) 可能衍生自中耳炎"],"answer":1,"image":""},{"id":"md6-115-1-18","subject":"md6","topic":"眼科-角膜結膜眼瞼眼窩","meta":"115年第1次第18題","year":115,"session":1,"number":18,"question":"病人每早睡醒眼結膜下半部充血紅腫，流淚畏光，眼睛有異物感，則最不可能罹患何種病變？","options":["(A) 甲狀腺凸眼","(B) 顏面神經麻痺","(C) 肉毒桿菌注射下眼瞼之後遺症","(D) 眼瞼痙攣"],"answer":3,"image":""},{"id":"md6-115-1-19","subject":"md6","topic":"耳科學","meta":"115年第1次第19題","year":115,"session":1,"number":19,"question":"有關急性中耳炎之致病菌，下列何者最不常見？","options":["(A) Streptococcus pneumoniae","(B) Haemophilus influenzae","(C) Moraxella catarrhalis","(D) Pseudomonas aeruginosa"],"answer":3,"image":""},{"id":"md6-115-1-20","subject":"md6","topic":"耳科學","meta":"115年第1次第20題","year":115,"session":1,"number":20,"question":"在注視眼震（gaze nystagmus）中，發現以下那一項時需懷疑是中樞病變？","options":["(A) 水平或旋轉（horizontal/rotatory）眼震","(B) 視覺固定（visual fixation）可抑制眼震","(C) 方向變換（direction changing）眼震","(D) 眼球向眼震快速相（fast phase）方向注視時，眼震強度會增加"],"answer":2,"image":""},{"id":"md6-115-1-21","subject":"md6","topic":"鼻科學","meta":"115年第1次第21題","year":115,"session":1,"number":21,"question":"關於蝶竇（sphenoid sinus）的解剖，下列敘述何者正確？","options":["(A) 蝶竇開口位於蝶竇前壁上側","(B) 翼管神經（vidian nerve）位於蝶竇外側壁","(C) 三叉神經的上頜支（maxillary division, V2）位於蝶竇上側壁","(D) 視神經位於蝶竇內上側壁"],"answer":0,"image":""},{"id":"md6-115-1-22","subject":"md6","topic":"鼻科學","meta":"115年第1次第22題","year":115,"session":1,"number":22,"question":"有關內視鏡鼻竇手術（endoscopic sinus surgery）可能產生的併發症，下列何者最不常見？","options":["(A) 馬鞍鼻（saddle nose）","(B) 腦膜炎（meningitis）","(C) 複視或失明（diplopia or blindness）","(D) 腦脊髓液鼻漏（CSF rhinorrhea）"],"answer":0,"image":""},{"id":"md6-115-1-23","subject":"md6","topic":"喉科學與頭頸腫瘤","meta":"115年第1次第23題","year":115,"session":1,"number":23,"question":"下列那一條肌肉最可能遭扁桃腺癌侵犯，造成張口困難（trismus）？","options":["(A) 外翼肌（lateral pterygoid muscle）","(B) 咀嚼肌（masseter muscle）","(C) 內翼肌（medial pterygoid muscle）","(D) 頰肌（buccinator muscle）"],"answer":2,"image":""},{"id":"md6-115-1-24","subject":"md6","topic":"鼻科學","meta":"115年第1次第24題","year":115,"session":1,"number":24,"question":"下列何者不是感冒（common cold）的常見致病原病毒？","options":["(A) 鼻病毒（rhinovirus）","(B) 冠狀病毒（corona virus）","(C) 疱疹病毒（herpes virus）","(D) 流感病毒（influenza virus）"],"answer":2,"image":""},{"id":"md6-115-1-25","subject":"md6","topic":"喉科學與頭頸腫瘤","meta":"115年第1次第25題","year":115,"session":1,"number":25,"question":"有關反常性聲帶運動障礙（paradoxical vocal fold movement disorder），下列敘述何者錯誤？","options":["(A) 常發生於剛睡醒或剛入睡時","(B) 會有吸氣相喘鳴聲（inspiratory stridor）","(C) 可能是梅格氏症候群（Meige syndrome）的表現之一","(D) 可用肉毒桿菌素注射於兩側的甲杓肌（thyroarytenoid muscle）治療"],"answer":0,"image":""},{"id":"md6-115-1-26","subject":"md6","topic":"喉科學與頭頸腫瘤","meta":"115年第1次第26題","year":115,"session":1,"number":26,"question":"有關聲帶麻痺（vocal fold paralysis），下列敘述何者錯誤？","options":["(A) 成人聲帶麻痺多與腫瘤或甲狀腺手術有關","(B) 單側聲帶麻痺左側多於右側","(C) Arnold-Chiari malformation有關的聲帶麻痺，屬於中樞神經病變，可引起雙側麻痺","(D) 神經重建手術（reinnervation）多以ansa cervicalis或spinal accessory nerve的分支做為接枝（graft）"],"answer":3,"image":""},{"id":"md6-115-1-27","subject":"md6","topic":"喉科學與頭頸腫瘤","meta":"115年第1次第27題","year":115,"session":1,"number":27,"question":"有關Graves disease，下列敘述何者錯誤？","options":["(A) 致病原因主要是T淋巴球及B淋巴球，產生甲促素受器抗體（TSH receptor antibody）","(B) 全甲狀腺切除（total thyroidectomy）是建議的手術方式","(C) 術前給與病人抗甲狀腺藥物及碘液（Lugol's iodine）可以降低甲狀腺血流，減少手術過程中出血的風險","(D) 凸眼（exophthalmos）症狀在甲狀腺手術後仍無法有效改善"],"answer":[0,1],"image":"","answer_note":"更正:第27題答Ａ或Ｂ或AB者均給分"},{"id":"md6-115-1-28","subject":"md6","topic":"婦科-手術學與診斷技術","meta":"115年第1次第28題","year":115,"session":1,"number":28,"question":"內髂動脈（internal iliac artery）分枝，下列何者除外？","options":["(A) 內陰動脈（internal pudendal artery）","(B) 卵巢動脈（ovarian artery）","(C) 下膀胱動脈（inferior vesical artery）","(D) 上臀動脈（superior gluteal artery）"],"answer":1,"image":""},{"id":"md6-115-1-29","subject":"md6","topic":"婦科-手術學與診斷技術","meta":"115年第1次第29題","year":115,"session":1,"number":29,"question":"在正常解剖位置中，子宮動脈（uterine artery）與輸尿管（ureter）最常在何處交會？","options":["(A) 子宮頸外側0.5 cm","(B) 子宮頸外側2 cm","(C) 子宮頸外側4 cm","(D) 子宮頸外側5 cm"],"answer":1,"image":""},{"id":"md6-115-1-30","subject":"md6","topic":"婦科-腫瘤","meta":"115年第1次第30題","year":115,"session":1,"number":30,"question":"37歲女性，因診所懷疑絨毛膜癌（choriocarcinoma）而轉至醫學中心就醫，下列關於絨毛膜癌之敘述何者正確？","options":["(A) 常見的臨床症狀為下腹痛","(B) 常發生於正常足月懷孕之後","(C) 常經由淋巴轉移","(D) 根據International Federation of Gynecology and Obstetrics（FIGO 2009）分期，轉移到肝臟為第三期"],"answer":1,"image":""},{"id":"md6-115-1-31","subject":"md6","topic":"產科-一般產科","meta":"115年第1次第31題","year":115,"session":1,"number":31,"question":"剖腹產時，下列何者不列為優先考慮做縱向子宮切開（classical incision）的情況？","options":["(A) 子宮下段有巨大肌瘤阻塞產道","(B) 完全性前置胎盤合併前壁著床","(C) 胎兒過大合併橫位與破水","(D) 前次子宮肌瘤手術病史"],"answer":3,"image":""},{"id":"md6-115-1-32","subject":"md6","topic":"產科-一般產科","meta":"115年第1次第32題","year":115,"session":1,"number":32,"question":"依照圖中胎兒的方向，當肩難產發生時，小明是接生醫師，下列敘述何者最不適當？","options":["(A) 由助手協助在恥骨上方加壓","(B) 由助手協助將孕婦的腳與膝蓋上抬","(C) 小明右手進入下方肩膀後方，將胎兒肩膀做順時針方向旋轉","(D) 旋轉式手法（corkscrew maneuver）的功效較其他方法要來的有效"],"answer":3,"image":"md6-115-1-32.jpeg"},{"id":"md6-115-1-33","subject":"md6","topic":"產科-一般產科","meta":"115年第1次第33題","year":115,"session":1,"number":33,"question":"有關胎兒的敘述，下列何者正確？","options":["(A) 胎兒的心跳正常值為80～100 bpm","(B) 4小時感覺不到胎動仍在正常睡眠時間範圍內","(C) 胎兒在母親體內不會有呼吸動作，若超音波下見到呼吸動作為胎兒窘迫的徵兆","(D) 胎盤機能不足為羊水量過少的原因之一"],"answer":3,"image":""},{"id":"md6-115-1-34","subject":"md6","topic":"產科-高危險妊娠","meta":"115年第1次第34題","year":115,"session":1,"number":34,"question":"有關X染色體脆折症（fragile X syndrome）之敘述，下列何者正確？","options":["(A) 為最常見的遺傳性智力障礙疾病","(B) 女性發生率約為1/3600","(C) 為染色體Xq27.3位置上發生AGG三核苷酸重複超過200次以上導致","(D) 很少伴隨有自閉症的行為表現"],"answer":0,"image":""},{"id":"md6-115-1-35","subject":"md6","topic":"產科-高危險妊娠","meta":"115年第1次第35題","year":115,"session":1,"number":35,"question":"33歲女性，到院做35週產檢，如圖主訴下肢痛，理學檢查有Homans sign positive，下列敘述何者錯誤？","options":["(A) 診斷可使用compression ultrasonography","(B) 若不處理可能會有肺栓塞風險","(C) 此類病症多發生在右下肢，因為右股靜脈常被右股動脈及卵巢動脈壓迫所致","(D) 若無禁忌，考慮使用enoxaparin每12小時皮下注射治療"],"answer":2,"image":"md6-115-1-35.jpeg"},{"id":"md6-115-1-36","subject":"md6","topic":"產科-一般產科","meta":"115年第1次第36題","year":115,"session":1,"number":36,"question":"關於生產中operative vaginal delivery，vacuum使用時機及注意事項，下列敘述何者錯誤？","options":["(A) 使用真空吸引器於產婦兩次子宮收縮間可以考慮減低壓力，減少胎兒頭皮受傷","(B) 當使用真空吸引器輔助生產時，手法及牽引角度與產鉗出力方式角度相似，配合產婦用力及胎頭下降","(C) 產婦氣力用盡而胎頭station為-1，cervical dilatation 9公分時可以考慮使用真空吸引器生產","(D) 真空吸引器建議壓力最大為600 mmHg使用2分鐘以內較不易有併發症"],"answer":2,"image":""},{"id":"md6-115-1-37","subject":"md6","topic":"產科-高危險妊娠","meta":"115年第1次第37題","year":115,"session":1,"number":37,"question":"小玲懷孕16週，第一次量到血壓150/95 mmHg、休息半小時後再量是148/95 mmHg，開始固定服用降血壓藥物，但在28週時血壓突然升高，量到180/110 mmHg並出現蛋白尿4價、血小板低下、肝功能異常，下列最適合的診斷為何？","options":["(A) 子癇症（eclampsia）","(B) 妊娠高血壓（gestational hypertension）","(C) 子癇前症（preeclampsia syndrome）","(D) 慢性高血壓合併子癇前症（preeclampsia superimposed on chronic hypertension）"],"answer":3,"image":""},{"id":"md6-115-1-38","subject":"md6","topic":"產科-高危險妊娠","meta":"115年第1次第38題","year":115,"session":1,"number":38,"question":"衛生福利部國民健康署建議孕婦於第35至37週懷孕期間接受生殖道乙型鏈球菌（group B Streptococcus, GBS）菌落篩檢，針對下列何種情況最不建議進行臨產期抗生素預防性投藥？","options":["(A) 孕婦於此次懷孕期間發生GBS菌尿症（GBS bacteriuria）","(B) 孕婦於前一次懷孕的GBS菌落篩檢為陽性反應","(C) 孕婦前一次分娩之新生兒罹患嚴重GBS感染症","(D) 孕婦未接受GBS菌落篩檢，於第35週孕期因羊膜早破超過24小時，住院待產"],"answer":1,"image":""},{"id":"md6-115-1-39","subject":"md6","topic":"產科-高危險妊娠","meta":"115年第1次第39題","year":115,"session":1,"number":39,"question":"周產期心肌病變（peripartum cardiomyopathy）的診斷準則，不包括下列何者？","options":["(A) 懷孕期最後一個月或生產後五個月內發生心臟衰竭","(B) 無心臟衰竭的確定病因","(C) 懷孕期最後一個月前無確診的心臟病","(D) 右心室收縮功能不良"],"answer":3,"image":""},{"id":"md6-115-1-40","subject":"md6","topic":"婦科-手術學與診斷技術","meta":"115年第1次第40題","year":115,"session":1,"number":40,"question":"關於手術性子宮鏡（operative hysteroscopy）之敘述，下列何者最不適當？","options":["(A) 發生併發症機率與診斷性子宮鏡（diagnostic hysteroscopy）相當","(B) 可執行沾黏去除或肌瘤摘除","(C) 可能發生air embolus","(D) 可能發生uterine perforation"],"answer":0,"image":""},{"id":"md6-115-1-41","subject":"md6","topic":"麻醉-特殊麻醉與疼痛","meta":"115年第1次第41題","year":115,"session":1,"number":41,"question":"行腹腔鏡手術時，如圖手術姿勢稱之為：","options":["(A) supine position","(B) lithotomy position","(C) prone position","(D) Fowler's position"],"answer":1,"image":"md6-115-1-41.jpeg"},{"id":"md6-115-1-42","subject":"md6","topic":"婦科-良性腫瘤與內膜異位","meta":"115年第1次第42題","year":115,"session":1,"number":42,"question":"子宮肌瘤病人希望將來能生育，若希望接受治療，下列何種治療最適當？","options":["(A) 肌瘤切除術（myomectomy）","(B) Magnetic Resonance-Guided Focused Ultrasound（MRgFUS）","(C) 肌瘤溶解術（myolysis）","(D) 子宮動脈栓塞術（uterine artery embolization,UAE）"],"answer":0,"image":""},{"id":"md6-115-1-43","subject":"md6","topic":"婦科-腫瘤","meta":"115年第1次第43題","year":115,"session":1,"number":43,"question":"子宮內膜異位症會增加那些組織學類型的卵巢癌風險？①子宮內膜樣（endometrioid） ②亮細胞（clear cell） ③漿液性（serous） ④黏液性（mucinous）","options":["(A) ①②","(B) ②③","(C) ①③","(D) ②④"],"answer":0,"image":""},{"id":"md6-115-1-44","subject":"md6","topic":"婦科-生殖內分泌","meta":"115年第1次第44題","year":115,"session":1,"number":44,"question":"關於Swyer syndrome，下列敘述何者最不適當？","options":["(A) 患者通常是平均身高和原發性無月經","(B) 患者呈現性腺退化（streak gonads）","(C) 染色體核型（karyotype）主要為46,XX","(D) 患者受益於雌激素療法"],"answer":2,"image":""},{"id":"md6-115-1-45","subject":"md6","topic":"婦科-生殖內分泌","meta":"115年第1次第45題","year":115,"session":1,"number":45,"question":"有關功能性卵巢囊腫，下列敘述何者最不適當？","options":["(A) 主要包括濾泡囊腫（follicular cyst）、黃體囊腫（corpus luteum cyst）和卵囊黃體囊腫（theca lutein cyst）","(B) 都是良性的","(C) 最常見的功能性卵巢囊腫是濾泡囊腫，很少大於8公分","(D) 治療上以腹腔鏡卵巢囊腫切除為主"],"answer":3,"image":""},{"id":"md6-115-1-46","subject":"md6","topic":"婦科-生殖道感染與先天異常","meta":"115年第1次第46題","year":115,"session":1,"number":46,"question":"下列何種藥物對於治療生殖器疱疹（genital herpes）較不適當？","options":["(A) acyclovir","(B) famciclovir","(C) valacyclovir","(D) terconazole"],"answer":3,"image":""},{"id":"md6-115-1-47","subject":"md6","topic":"婦科-良性腫瘤與內膜異位","meta":"115年第1次第47題","year":115,"session":1,"number":47,"question":"一個33歲女性來到門診，她主訴為長期有經期時間過長及間斷性子宮出血之症狀，此外她並無經血量過多或頻尿之現象，3個月前子宮抹片檢查為正常。她的經期剛結束，經婦科超音波檢查發現如圖，下列何者是最有可能的診斷？","options":["(A) 子宮頸糜爛（cervical erosion）","(B) 子宮壁層平滑肌瘤（intramural uterine leiomyoma）","(C) 卵巢畸胎瘤（ovarian teratoma）","(D) 子宮內膜息肉（endometrial polyp）"],"answer":3,"image":"md6-115-1-47.jpeg"},{"id":"md6-115-1-48","subject":"md6","topic":"婦科-生殖道感染與先天異常","meta":"115年第1次第48題","year":115,"session":1,"number":48,"question":"下列何者對正常陰道菌叢（vaginal bacterial flora）的影響最小？","options":["(A) 荷爾蒙狀態","(B) 陰道酸鹼度","(C) 飲食","(D) 年齡"],"answer":2,"image":""},{"id":"md6-115-1-49","subject":"md6","topic":"婦科-腫瘤","meta":"115年第1次第49題","year":115,"session":1,"number":49,"question":"下列何者是子宮根除術（radical hysterectomy）最常見的慢性併發症？","options":["(A) 輸尿管陰道瘻管（ureterovaginal fistula）","(B) 形成淋巴囊腫（lymphocyst formation）","(C) 腸阻塞（bowel obstruction）","(D) 膀胱低張症（bladder hypotonia）"],"answer":3,"image":""},{"id":"md6-115-1-50","subject":"md6","topic":"婦科-腫瘤","meta":"115年第1次第50題","year":115,"session":1,"number":50,"question":"子宮內膜癌大約占停經後出血多少百分比？","options":["(A) 10 %","(B) 30 %","(C) 50 %","(D) 70 %"],"answer":0,"image":""},{"id":"md6-115-1-51","subject":"md6","topic":"婦科-腫瘤","meta":"115年第1次第51題","year":115,"session":1,"number":51,"question":"子宮頸抹片檢查顯示重度子宮頸上皮贅瘤（HSIL），下一步處置何者最不適當？","options":["(A) 陰道鏡檢查＋子宮頸切片（colposcopy + cervical biopsy）","(B) 施打子宮頸癌疫苗","(C) 子宮頸錐狀切除（conization）","(D) loop electrosurgical excision procedure（LEEP）"],"answer":1,"image":""},{"id":"md6-115-1-52","subject":"md6","topic":"婦科-腫瘤","meta":"115年第1次第52題","year":115,"session":1,"number":52,"question":"關於子宮內膜增生（endometrial hyperplasia）的敘述，下列何者錯誤？","options":["(A) 它是造成子宮異常出血的原因之一","(B) 根據Kurman的研究，atypical complex hyperplasia進展為子宮內膜癌的機率為29%","(C) 根據Trimble的研究，經子宮內膜切片或內膜搔刮術診斷為atypical complex hyperplasia而切除子宮，術後發現有合併內膜癌的機率大約10%","(D) atypical hyperplasia的判斷標準包括較大的細胞核、較高的核質比、細胞排列不整齊等特質"],"answer":2,"image":""},{"id":"md6-115-1-53","subject":"md6","topic":"婦科-腫瘤","meta":"115年第1次第53題","year":115,"session":1,"number":53,"question":"55歲女性，因為卵巢腫瘤而接受手術，摘除腫瘤檢視時發現腫瘤內有毛髮、脂肪、皮脂腺等組織。最後病理報告敘述有惡性細胞，最常見下列那一種惡性病變？","options":["(A) 混合癌及肉瘤（mixed carcinoma and sarcoma）","(B) 腺癌（adenocarcinoma）","(C) 鱗狀上皮細胞癌（squamous cell carcinoma）","(D) 黑色素細胞瘤（melanoma）"],"answer":2,"image":""},{"id":"md6-115-1-54","subject":"md6","topic":"婦科-生殖內分泌","meta":"115年第1次第54題","year":115,"session":1,"number":54,"question":"有關原發性卵巢功能不足（或稱早發性卵巢衰竭），下列敘述何者錯誤？","options":["(A) 不到40歲之女性，有4個月以上沒來月經，同時有兩度血清濾泡剌激激素（FSH）值升高到停經婦女的範圍內，即可確診","(B) 可能的原因包括X染色體脆折症（fragile X syndrome）、醫源性、自體免疫疾病、感染等等","(C) 約50%的病患可以找到原因","(D) 帶有FMR1基因準突變（premutation）會發生原發性卵巢功能不足的機率約在13%至26%之間"],"answer":2,"image":""},{"id":"md6-115-1-55","subject":"md6","topic":"婦科-生殖內分泌","meta":"115年第1次第55題","year":115,"session":1,"number":55,"question":"32歲女性，G0P0，繼發性無月經，抽血報告顯示泌乳激素偏高，下列那項診斷是最不可能的原因？","options":["(A) 甲狀腺功能低下","(B) 腦下垂體腺瘤","(C) 使用抗憂鬱藥物（antidepressants）","(D) 乳腺癌"],"answer":3,"image":""},{"id":"md6-115-1-56","subject":"md6","topic":"產科-高危險妊娠","meta":"115年第1次第56題","year":115,"session":1,"number":56,"question":"一對夫妻的頭兩次懷孕，都因為胎兒為甲型地中海貧血重症（alpha thalassemia major）於4個多月時終止妊娠，後續檢查確定夫妻兩人皆為甲型地中海貧血帶因者。他們表示這段期間身心備受煎熬，想了解還有沒有機會正常生育。下列何項建議最能避免因相同原因需要再次終止妊娠的可能性？","options":["(A) 絨毛膜穿刺取樣（chorionic villus sampling, CVS）","(B) 羊水穿刺診斷（amniocentesis）","(C) 試管嬰兒加上胚胎著床前基因診斷（preimplantation genetic diagnosis, PGD）","(D) 非侵入性產前染色體篩檢（noninvasive prenatal screening, NIPS）"],"answer":2,"image":""},{"id":"md6-115-1-57","subject":"md6","topic":"婦科-尿失禁與骨盆腔脫垂","meta":"115年第1次第57題","year":115,"session":1,"number":57,"question":"有關骨盆底部的支持結構，下列敘述何者正確？","options":["(A) 子宮及陰道由提肛肌（levator ani）及梨狀肌（piriformis muscle）支持","(B) 子宮薦韌帶（uterosacral ligament）固定子宮頸，所以能影響陰道的長度和軸向","(C) 膀胱脫垂（cystocele）是puborectalis muscle生產時受傷所導致","(D) 直腸脫垂（rectocele）是一種腹膜疝氣（peritoneum herniation）"],"answer":1,"image":""},{"id":"md6-115-1-58","subject":"md6","topic":"復健-神經復健","meta":"115年第1次第58題","year":115,"session":1,"number":58,"question":"關於腕隧道症候群（carpal tunnel syndrome），下列敘述何者最不適當？","options":["(A) 是常見的壓迫性神經病變（compressive neuropathy）","(B) 女性（women）較常發生","(C) 嚴重的病人可能會有魚際（thenar eminence）部位萎縮","(D) 魚際（thenar eminence）部位會有麻的感覺"],"answer":3,"image":""},{"id":"md6-115-1-59","subject":"md6","topic":"復健-神經復健","meta":"115年第1次第59題","year":115,"session":1,"number":59,"question":"下列何種藥物最常用於脊椎腔內（intrathecal）注射來控制痙攣（spasticity）？","options":["(A) tizanidine","(B) baclofen","(C) diazepam","(D) dantrolene"],"answer":1,"image":""},{"id":"md6-115-1-60","subject":"md6","topic":"復健-物理因子治療與評估","meta":"115年第1次第60題","year":115,"session":1,"number":60,"question":"下列何者不是超音波（ultrasound）的非熱效應（non-thermal effect）？","options":["(A) 空穴效應（cavitation）","(B) 聲射流（acoustic streaming）","(C) 駐波（standing wave）","(D) 都卜勒效應（Doppler effect）"],"answer":3,"image":""},{"id":"md6-115-1-61","subject":"md6","topic":"復健-兒童與一般復健","meta":"115年第1次第61題","year":115,"session":1,"number":61,"question":"有關輪椅的敘述，下列何者最不適當？","options":["(A) 對於肢體偏癱的身障者而言，由於無法以雙手同時抓握兩側手推圈，因此較適合使用單手操控輪子的輪椅","(B) 後輪輪軸偏後的輪椅，推動起來更省力，且更可預防肩關節的損傷","(C) 對於無法以上肢推動輪椅的使用者，可使用足驅動的輪椅","(D) 在各項參數及總重量相同的前提下，後輪附加的手推圈直徑越大，推動輪椅所需的力量越小"],"answer":1,"image":""},{"id":"md6-115-1-62","subject":"md6","topic":"復健-神經復健","meta":"115年第1次第62題","year":115,"session":1,"number":62,"question":"腦中風病人上肢屈曲協同動作（flexion synergy）中，下列何者最不適當？","options":["(A) 前臂旋前（forearm pronation）","(B) 手肘屈曲（elbow flexion）","(C) 肩外展（shoulder abduction）","(D) 肩外轉（shoulder external rotation）"],"answer":0,"image":""},{"id":"md6-115-1-63","subject":"md6","topic":"復健-神經復健","meta":"115年第1次第63題","year":115,"session":1,"number":63,"question":"腦傷病人除了慢性疼痛外，常與下列何者形成「臨床三角」進而導致長期失能？","options":["(A) 創傷後壓力症（posttraumatic stress disorder）","(B) 大便失禁（stool incontinence）","(C) 吞嚥障礙（swallowing disorders）","(D) 肢體失用症（limb apraxia）"],"answer":0,"image":""},{"id":"md6-115-1-64","subject":"md6","topic":"復健-骨骼肌肉損傷與疾患","meta":"115年第1次第64題","year":115,"session":1,"number":64,"question":"有關膝關節十字韌帶損傷，下列敘述何者最不適當？","options":["(A) 前十字韌帶和後十字韌帶在膝關節內交叉，可提供穩定性","(B) Lachman test常用於診斷後十字韌帶損傷","(C) 前十字韌帶損傷可能伴隨內側副韌帶及內側半月板的損傷","(D) 前十字韌帶損傷比後十字韌帶損傷常見"],"answer":1,"image":""},{"id":"md6-115-1-65","subject":"md6","topic":"復健-骨骼肌肉損傷與疾患","meta":"115年第1次第65題","year":115,"session":1,"number":65,"question":"關於骨質疏鬆引起的胸腰椎壓迫性骨折之敘述，下列何者最適當？","options":["(A) 男性、抽菸均是危險因子","(B) 通常疼痛在數週內會愈來愈嚴重","(C) 若損傷處位於脊椎前列（anterior column），通常不需手術固定","(D) 病人一定有疼痛現象"],"answer":2,"image":""},{"id":"md6-115-1-66","subject":"md6","topic":"復健-心肺復健與運動處方","meta":"115年第1次第66題","year":115,"session":1,"number":66,"question":"使用放鬆訓練來治療慢性阻塞性肺病病人，日常生活的擺位及姿勢，下列何者最不適當？","options":["(A) 上肢在活動時懸空","(B) 上肢在側臥時保持彎曲","(C) 下肢在側臥時保持彎曲","(D) 下肢在仰臥時膝蓋彎曲"],"answer":0,"image":""},{"id":"md6-115-1-67","subject":"md6","topic":"復健-兒童與一般復健","meta":"115年第1次第67題","year":115,"session":1,"number":67,"question":"關於腦性麻痺（cerebral palsy）患者相關的脊椎側彎（scoliosis），下列敘述何者最不適當？","options":["(A) 無法行走（nonambulatory）的腦性麻痺患者，比可以行走的腦性麻痺患者脊椎側彎嚴重","(B) 全身影響（total body involvement）的腦性麻痺患者，比不是全身影響的腦性麻痺患者脊椎側彎嚴重","(C) 無法行走（nonambulatory）的腦性麻痺患者容易發生C形狀（C-shape）的脊椎側彎合併骨盆歪斜（pelvic obliquity）","(D) 背架（bracing）可以有效的避免腦性麻痺患者脊椎側彎的惡化"],"answer":3,"image":""},{"id":"md6-115-1-68","subject":"md6","topic":"復健-兒童與一般復健","meta":"115年第1次第68題","year":115,"session":1,"number":68,"question":"下列那一類神經管缺陷（neural tube defects）的患者，最容易出現空凹足（cavus foot）的變形？","options":["(A) 頸椎（cervical）病灶","(B) 胸椎（thoracic）病灶","(C) 腰椎（lumbar）病灶","(D) 薦椎（sacral）病灶"],"answer":3,"image":""},{"id":"md6-115-1-69","subject":"md6","topic":"復健-兒童與一般復健","meta":"115年第1次第69題","year":115,"session":1,"number":69,"question":"有關日常生活活動功能（activities of daily living, ADLs）評估之敘述，下列何者最不適當？","options":["(A) 包括基本日常生活活動（basic ADLs）與工具性日常生活活動（instrumental ADLs）","(B) 基本日常生活活動（basic ADLs）包括進食、穿衣、如廁、大小便控制等例行的自我照顧項目","(C) 工具性日常生活活動（instrumental ADLs）包括烹飪、開車、打電話、園藝等個人化、使用工具或裝置的活動","(D) 巴氏量表評估的項目包含基本日常生活活動（basic ADLs）與工具性日常生活活動（instrumental ADLs）"],"answer":3,"image":""},{"id":"md6-115-1-70","subject":"md6","topic":"復健-兒童與一般復健","meta":"115年第1次第70題","year":115,"session":1,"number":70,"question":"下列何者不是執行無障礙環境介入時的省力及工作簡化原則？","options":["(A) 將物品依照使用頻率放置，將經常需要使用之物品放在離病人較遠的位置，以讓患者多行動來進行復健","(B) 使用槓桿原理及重力以節省體力","(C) 儘量在neutral position的關節活動度姿勢下執行職能活動","(D) 使用機械操控之機器、設備設施、工具來取代人力"],"answer":0,"image":""},{"id":"md6-115-1-71","subject":"md6","topic":"復健-兒童與一般復健","meta":"115年第1次第71題","year":115,"session":1,"number":71,"question":"下列有關輪椅的敘述，何者最不適當？","options":["(A) 對於全身痙攣張力強或軀幹控制不佳的腦性麻痺病人而言，傳統輪椅較為不合適","(B) 對於C5受傷的病人而言，最好在輪環的手推圈上加上橡膠包覆或突出的小握把，以方便他們自行推動","(C) 大輪的尺寸一般為22～26吋，若尺寸太大，對於上肢活動度較差的病人而言較不合適","(D) 椅背的高度最好落在肩胛骨上緣處，有利於病人上身的活動度"],"answer":3,"image":""},{"id":"md6-115-1-72","subject":"md6","topic":"鼻科學","meta":"115年第1次第72題","year":115,"session":1,"number":72,"question":"63歲男性病人因左側耳朵悶悶的不適，到耳鼻喉科看診，根據所附兩張MRI影像判斷，下列何者為最可能的診斷？","options":["(A) 細菌性中耳炎","(B) 淋巴瘤","(C) 鼻咽癌","(D) 中耳的珍珠瘤"],"answer":2,"image":"md6-115-1-72.jpeg"},{"id":"md6-115-1-73","subject":"md6","topic":"婦科-生殖道感染與先天異常","meta":"115年第1次第73題","year":115,"session":1,"number":73,"question":"35歲女性病人主訴不孕，子宮輸卵管攝影檢查發現如附圖。最可能之診斷為何？","options":["(A) 正常的子宮輸卵管影像","(B) 雙側遠端輸卵管阻塞併輸卵管積水（hydrosalpinx）","(C) 輸卵管癌（tubal cancer）","(D) 輸卵管卵巢膿瘍（tubo-ovarian abscess）"],"answer":1,"image":"md6-115-1-73.jpeg"},{"id":"md6-115-1-74","subject":"md6","topic":"婦科-良性腫瘤與內膜異位","meta":"115年第1次第74題","year":115,"session":1,"number":74,"question":"65歲女性病人因腹痛接受腹部Ｘ光檢查如附圖。最可能之診斷為何？","options":["(A) 子宮肌瘤（uterine myoma）","(B) 輸卵管卵巢膿瘍（tubo-ovarian abscess）","(C) 子宮頸癌（cervical cancer）","(D) 卵巢癌（ovarian cancer）"],"answer":0,"image":"md6-115-1-74.jpeg"},{"id":"md6-115-1-75","subject":"md6","topic":"麻醉-呼吸道與監視","meta":"115年第1次第75題","year":115,"session":1,"number":75,"question":"困難氣管插管可用LEMON來評估，下列敘述何者最不適當？","options":["(A) look externally（L）：評估外觀是否短下巴、短脖子、肥胖","(B) evaluation 3-3-2（E）：使用手指評估張口是否達到3個指幅、牙齒到下巴下緣是否達到3個指幅、舌骨到甲狀軟骨是否達到2個指幅","(C) Mallampati分級（M）：請病人張嘴，將舌頭吐出，評估懸壅垂（uvula）與舌根位置","(D) neck mobility（N）：評估脖子活動度是否正常"],"answer":1,"image":""},{"id":"md6-115-1-76","subject":"md6","topic":"麻醉-呼吸道與監視","meta":"115年第1次第76題","year":115,"session":1,"number":76,"question":"病人從密閉火場被救出，臉部燒傷，口鼻處有燻黑炭渣，鼻毛燒焦，聲音沙啞，有喘鳴聲（wheezing），其他皮膚無明顯燒傷，下列那項處置最不適當？","options":["(A) 置放氣管內管以保護呼吸道","(B) 給與100%潮濕氧氣","(C) 給與大量輸液","(D) 檢驗血中一氧化碳濃度"],"answer":2,"image":""},{"id":"md6-115-1-77","subject":"md6","topic":"耳科學","meta":"115年第1次第77題","year":115,"session":1,"number":77,"question":"65歲糖尿病人，主訴右耳疼痛流膿已2週，一天前發燒，右臉腫脹，今天早上右眼瞼下垂。下列敘述何者錯誤？","options":["(A) 有可能是惡性外耳炎（malignant otitis externa）","(B) 有可能是顏面神經受侵犯","(C) 最常見的致病菌是Pseudomonas aeruginosa","(D) 治療以口服抗生素及門診追蹤為主"],"answer":3,"image":""},{"id":"md6-115-1-78","subject":"md6","topic":"醫學倫理與法規","meta":"115年第1次第78題","year":115,"session":1,"number":78,"question":"我國醫療法第63條第1項規定：「醫療機構實施手術，應向病人或其法定代理人、配偶、親屬或關係人說明手術原因、手術成功率或可能發生之併發症及危險，並經其同意，簽具手術同意書及麻醉同意書，始得為之。」主要係為保障病人之何種權利？","options":["(A) 生命權","(B) 健康權","(C) 自主權","(D) 隱私權"],"answer":2,"image":""},{"id":"md6-115-1-79","subject":"md6","topic":"醫學倫理與法規","meta":"115年第1次第79題","year":115,"session":1,"number":79,"question":"孕婦於初次產檢時，告知醫師其過去曾經懷孕生產過一子，但先生不知情，請求醫師隱匿相關病情，下列做法何者最適當？","options":["(A) 病歷上記錄為G1P0，為保護病人，也不告知相關醫護人員其懷孕生產史","(B) 病歷上記錄為G2P1，同時病歷上註明保護病人隱私，不得對外公開","(C) 病歷上記錄為G1P0，但私下告知相關醫護人員，病人為第二胎，生產時注意產程","(D) 病歷上記錄為G2P1，且要求病人應確實告知先生，避免不必要糾紛"],"answer":1,"image":""},{"id":"md6-115-1-80","subject":"md6","topic":"醫學倫理與法規","meta":"115年第1次第80題","year":115,"session":1,"number":80,"question":"王先生，55歲，罹患運動神經元疾病（漸凍人）多年，曾經因為肺炎感染而接受氣管內插管及呼吸器治療，之後病情改善而拔管。出院以後病人在家人見證下簽妥DNR。一個月後，病人已經四肢無力，吞嚥開始出現困難，以鼻胃管進食。現在又出現呼吸喘、痰多，血氧濃度下降，呼吸急促，臨床診斷為肺炎。醫師對病人及家人說明，應該要再次插管；同時說明限時嘗試治療（time-limited trial）的選項：先接受插管治療，如果仍未改善再撤除呼吸器。病人神智清楚，明白表示拒絕，並能夠接受此次因呼吸衰竭離世；家人不捨、猶豫不能決定。有關醫師之處置下列何者最適當？","options":["(A) 反覆勸說病人接受插管，為家人而努力，因為肺炎是可以治療的","(B) 接受病人拒絕插管的選擇，提供症狀治療，並照會另一位專科醫師做末期判斷","(C) 請家人決定，因為病人口齒不清，只能搖頭點頭","(D) 等病人陷入昏迷，再依照緊急救治的需要予以插管"],"answer":1,"image":""},{"id":"md6-115-2-1","subject":"md6","topic":"麻醉-呼吸道與監視","meta":"115年第2次第1題","year":115,"session":2,"number":1,"question":"手術完成後，全身麻醉甦醒拔管（extubation of the trachea）時期，下列何者是最不可能發生之氣道相關併發症？","options":["(A) 上呼吸道阻塞","(B) 支氣管痙攣","(C) 杓狀軟骨脫位（arytenoid dislocation）","(D) 神經性肺水腫"],"answer":3,"image":""},{"id":"md6-115-2-2","subject":"md6","topic":"麻醉-呼吸道與監視","meta":"115年第2次第2題","year":115,"session":2,"number":2,"question":"78歲洗腎病人被公車撞，導致骨盆及大腿骨骨折，經急救復甦後入住加護病房，並使用呼吸器治療。在給與輸液或輸血治療時，下列何者為最合適此病人使用的輸液反應（fluid responsiveness）評估指標？","options":["(A) 量測中央靜脈壓（central venous pressure）","(B) 計算脈壓變異率（pulse pressure variation）","(C) 被動式抬腿測試（passive leg raising test）","(D) 量測血壓（blood pressure）"],"answer":1,"image":""},{"id":"md6-115-2-3","subject":"md6","topic":"麻醉-呼吸道與監視","meta":"115年第2次第3題","year":115,"session":2,"number":3,"question":"關於一氧化碳（carbon monoxide, CO）中毒，下列敘述何者最不適當？","options":["(A) 因一氧化碳較易與血紅素結合，因此氧合血紅素（oxyhemoglobin）變少，會造成脈搏血氧飽和度（SpO2）數值偏低","(B) 中毒的定義為血中一氧化碳血紅素（carboxyhemoglobin）濃度＞15％","(C) 臨床症狀可能出現頭痛、噁心、無力、意識混亂、休克等","(D) 先給與100％之氧氣面罩治療，高壓氧可加速降低體內一氧化碳血紅素（carboxyhemoglobin）"],"answer":[0,1],"image":"","answer_note":"更正:第3題答Ａ或Ｂ或AB者均給分"},{"id":"md6-115-2-4","subject":"md6","topic":"麻醉-呼吸道與監視","meta":"115年第2次第4題","year":115,"session":2,"number":4,"question":"麻醉中呼吸監測與判讀，下列敘述何者最不適當？","options":["(A) pulse oximetry為呼吸監測中重要的工具","(B) end-tidal carbon dioxide和動脈血液CO2分壓（PaCO2）數值不一定相同","(C) 影像檢查如超音波，可幫助床邊呼吸監測，早期診斷pneumothorax、consolidation和pleural effusion等，在手術室與加護病房運用更加廣泛","(D) 胸部X光為肺水腫（pulmonary edema）早期診斷的最佳工具，肺水（lung water）增加5％，就可以顯現變化並判讀"],"answer":3,"image":""},{"id":"md6-115-2-5","subject":"md6","topic":"麻醉-麻醉藥理","meta":"115年第2次第5題","year":115,"session":2,"number":5,"question":"有關於dexmedetomidine的藥理作用，下列敘述何者最適當？","options":["(A) α2作用劑的鎮痛作用通過刺激腹角的α2C和α2A受體介導","(B) 使用dexmedetomidine在手術期間和術後具有減少類鴉片藥物使用的效果","(C) 在全身麻醉期間，dexmedetomidine會提高吸入麻醉劑的最小肺泡濃度（MAC）","(D) 容易產生術後的呼吸抑制，所以不建議術後使用"],"answer":1,"image":""},{"id":"md6-115-2-6","subject":"md6","topic":"麻醉-麻醉藥理","meta":"115年第2次第6題","year":115,"session":2,"number":6,"question":"有關局部麻醉劑（local anesthetics）的藥理特性，下列敘述何者最適當？","options":["(A) 局部麻醉劑從血液中快速移除，主要是由於它們一開始就快速重新分布到肌肉組織","(B) 醯胺類局部麻醉劑（amide local anesthetics）經由肝臟中的膽鹼酯酶（pseudocholinesterase）代謝","(C) cocaine屬於醯胺類局部麻醉劑（amide local anesthetics）","(D) bupivacaine是經由肝臟P-450 enzymes代謝"],"answer":3,"image":""},{"id":"md6-115-2-7","subject":"md6","topic":"麻醉-呼吸道與監視","meta":"115年第2次第7題","year":115,"session":2,"number":7,"question":"下列何者不是聚焦心臟超音波檢查（focused cardiac ultrasound, FoCUS）最主要的視圖（view）？","options":["(A) 心尖長軸視圖（apical long-axis view, ALAX）","(B) 胸骨旁短軸視圖（parasternal short-axis view, PSAX）","(C) 心尖四腔視圖（apical four-chamber view, A4C）","(D) 劍突下四腔視圖（subcostal four-chamber view, SC4）"],"answer":0,"image":""},{"id":"md6-115-2-8","subject":"md6","topic":"麻醉-呼吸道與監視","meta":"115年第2次第8題","year":115,"session":2,"number":8,"question":"鎮靜與全身麻醉是一連續漸進過程，有關鎮靜深度與麻醉的敘述，下列何者錯誤？","options":["(A) minimal sedation：達到緩解焦慮（anxiolysis），仍可正常反應","(B) moderate（conscious）sedation：較為嗜睡（sleepy），對口語叫喚或觸碰刺激有反應","(C) deep sedation：對疼痛刺激有反應，自發呼吸皆足夠，不需呼吸道處置","(D) 當病人失去意識且對疼痛刺激無反應時，已進入全身麻醉"],"answer":2,"image":""},{"id":"md6-115-2-9","subject":"md6","topic":"麻醉-特殊麻醉與疼痛","meta":"115年第2次第9題","year":115,"session":2,"number":9,"question":"術後病人疼痛難耐而使用靜脈注射的類鴉片藥物病人自控式止痛裝置（PCA），有關PCA的敘述，下列何者最不適當？","options":["(A) PCA可設定給與劑量，不反應時間（lockout interval），由電腦控制，絕對安全","(B) PCA可設定基本用量及每次按壓劑量","(C) PCA可提高病人止痛滿意度，並減少類鴉片藥物總用量","(D) PCA可減少類鴉片藥物相關副作用"],"answer":0,"image":""},{"id":"md6-115-2-10","subject":"md6","topic":"眼科-視網膜葡萄膜","meta":"115年第2次第10題","year":115,"session":2,"number":10,"question":"一位高度近視患者最近突然出現明顯之飛蚊症，眼底檢查結果如圖所示，此患者最有可能出現下列何種疾病？","options":["(A) 牽引性視網膜剝離（tractional retinal detachment）","(B) 裂孔性視網膜剝離（rhegmatogenous retinal detachment）","(C) 滲出性視網膜剝離（exudative retinal detachment）","(D) 葡萄腫（staphyloma）"],"answer":1,"image":"md6-115-2-10.jpeg"},{"id":"md6-115-2-11","subject":"md6","topic":"眼科-視網膜葡萄膜","meta":"115年第2次第11題","year":115,"session":2,"number":11,"question":"關於糖尿病視網膜病變（diabetic retinopathy）的危險因子，下列敘述何者與此疾病關聯性最低？","options":["(A) 罹患糖尿病的期間與血糖控制程度","(B) 高血壓","(C) 腎臟病變","(D) 肝臟病變"],"answer":3,"image":""},{"id":"md6-115-2-12","subject":"md6","topic":"眼科-角膜結膜眼瞼眼窩","meta":"115年第2次第12題","year":115,"session":2,"number":12,"question":"有關角膜結構的敘述，下列何者錯誤？","options":["(A) 角膜總共分為五層","(B) 最外層為上皮層（epithelium），在輪狀部（limbus）可分裂再生","(C) 最內層為內皮層（endothelium），主要功能為排水、維持角膜透明","(D) 角膜提供了約15 D（diopter）的屈光度"],"answer":3,"image":""},{"id":"md6-115-2-13","subject":"md6","topic":"眼科-角膜結膜眼瞼眼窩","meta":"115年第2次第13題","year":115,"session":2,"number":13,"question":"有關乾眼症的敘述，下列何者錯誤？","options":["(A) 先點局部麻醉再做Schirmer Test，主要測得基礎淚液分泌量","(B) 正常的淚水彎月帶（tear meniscus）高度介於0.2到0.4 mm之間","(C) 淚膜崩裂時間（tear film break-up time）過短，最有可能是水層有問題","(D) 螢光染色可幫助觀察角膜上皮破損的程度與位置"],"answer":2,"image":""},{"id":"md6-115-2-14","subject":"md6","topic":"眼科-水晶體青光眼","meta":"115年第2次第14題","year":115,"session":2,"number":14,"question":"關於原發性隅角開放青光眼（primary open-angle glaucoma, POAG），下列何者正確？①兩眼眼壓差距4 mmHg以上是危險因子 ②女性較男性多 ③70歲以上之族群，亞洲人之盛行率比白種人高 ④是歐洲人及非洲人最多的青光眼種類","options":["(A) ①③","(B) ②④","(C) ②③","(D) ①④"],"answer":3,"image":""},{"id":"md6-115-2-15","subject":"md6","topic":"眼科-水晶體青光眼","meta":"115年第2次第15題","year":115,"session":2,"number":15,"question":"下列何者不是閉鎖性青光眼的危險因子？","options":["(A) 遠視","(B) 短眼軸（axial length）","(C) 女性","(D) 高度近視"],"answer":3,"image":""},{"id":"md6-115-2-16","subject":"md6","topic":"眼科-視網膜葡萄膜","meta":"115年第2次第16題","year":115,"session":2,"number":16,"question":"有關典型視神經炎（typical optic neuritis）的臨床特徵，下列敘述何者正確？","options":["(A) 視神經炎可能是多發性硬化症（multiple sclerosis）的第一個臨床症狀","(B) 視覺誘發電位的p100脈衝潛伏時間（latency）縮短","(C) 特徵多為無痛性急性失明","(D) 常合併視網膜滲出（retinal exudates）和棉絮斑（cotton-wool spots）"],"answer":0,"image":""},{"id":"md6-115-2-17","subject":"md6","topic":"眼科-角膜結膜眼瞼眼窩","meta":"115年第2次第17題","year":115,"session":2,"number":17,"question":"甲狀腺眼病變患者若同時有眼瞼內縮（lid retraction）、眼球活動困難（decrease of eye movements）以及凸眼（exophthalmos），導致角膜破皮及視力受損，應優先考慮下列何種治療？","options":["(A) 口服硒（selenium）100 μg每天2次","(B) 眼皮矯正手術","(C) 眼肌肉手術","(D) 眼窩減壓手術"],"answer":3,"image":""},{"id":"md6-115-2-18","subject":"md6","topic":"眼科-角膜結膜眼瞼眼窩","meta":"115年第2次第18題","year":115,"session":2,"number":18,"question":"甲狀腺眼病變（thyroid eye disease）的患者，下列那條眼內肌肉較容易受到影響，而造成眼球活動障礙？","options":["(A) 上直肌","(B) 下直肌","(C) 下斜肌","(D) 外直肌"],"answer":1,"image":""},{"id":"md6-115-2-19","subject":"md6","topic":"耳科學","meta":"115年第2次第19題","year":115,"session":2,"number":19,"question":"5歲男童，主訴上呼吸道感染後右耳疼痛，耳鏡檢查如圖，最可能之診斷為何？","options":["(A) 急性中耳炎","(B) 積液性中耳炎","(C) 慢性中耳炎","(D) 膽脂瘤"],"answer":0,"image":"md6-115-2-19.jpeg"},{"id":"md6-115-2-20","subject":"md6","topic":"喉科學與頭頸腫瘤","meta":"115年第2次第20題","year":115,"session":2,"number":20,"question":"鼻咽癌可經由海綿竇（cavernous sinus）侵犯那些腦神經？","options":["(A) 第二、三、四對腦神經","(B) 第二、四、六對腦神經","(C) 第三、四、六對腦神經","(D) 第二、三、六對腦神經"],"answer":2,"image":""},{"id":"md6-115-2-21","subject":"md6","topic":"耳科學","meta":"115年第2次第21題","year":115,"session":2,"number":21,"question":"下列那兩個半規管之夾角是接近相互垂直的？","options":["(A) 右後半規管和右上半規管","(B) 右水平半規管和左水平半規管","(C) 右後半規管和左上半規管","(D) 右上半規管和左後半規管"],"answer":0,"image":""},{"id":"md6-115-2-22","subject":"md6","topic":"鼻科學","meta":"115年第2次第22題","year":115,"session":2,"number":22,"question":"下列那一神經或血管不在翼腭窩（pterygopalatine fossa）內？","options":["(A) 翼腭神經節（pterygopalatine ganglion）","(B) 上頜神經（maxillary nerve, CN V2）","(C) 蝶腭動脈（sphenopalatine artery）","(D) 後篩動脈（posterior ethmoidal artery）"],"answer":3,"image":""},{"id":"md6-115-2-23","subject":"md6","topic":"鼻科學","meta":"115年第2次第23題","year":115,"session":2,"number":23,"question":"慢性鼻竇炎合併鼻息肉（chronic rhinosinusitis with nasal polyps）之致病原因，下列何者錯誤？","options":["(A) 過敏性黴菌性鼻竇炎（allergic fungal rhinosinusitis）","(B) 嗜伊紅性慢性鼻及鼻竇炎（eosinophilic chronic rhinosinusitis）","(C) 免疫球蛋白E依賴性黴菌發炎（IgE dependent fungal inflammation）","(D) 阿斯匹靈敏感性鼻息肉症（aspirin-sensitive nasal polyposis）"],"answer":[0,1,2,3],"image":"","answer_note":"送分:第23題一律給分 (原公告答案 C)"},{"id":"md6-115-2-24","subject":"md6","topic":"喉科學與頭頸腫瘤","meta":"115年第2次第24題","year":115,"session":2,"number":24,"question":"有關環狀軟骨（cricoid cartilage），下列敘述何者錯誤？","options":["(A) 環狀軟骨是呼吸道結構中唯一整圈的軟骨","(B) 連結於環狀軟骨後上方兩側的後環杓肌（posterior cricoarytenoid muscle）是關閉聲帶（vocal fold）的肌肉","(C) 環狀軟骨上方是甲狀軟骨，連結處所形成的環甲膜（cricothyroid membrane）是皮膚離呼吸道最近之處","(D) 杓狀軟骨（arytenoid cartilage）位於環狀軟骨後上方兩側，藉由一個滑液關節（synovial joint）連結"],"answer":1,"image":""},{"id":"md6-115-2-25","subject":"md6","topic":"喉科學與頭頸腫瘤","meta":"115年第2次第25題","year":115,"session":2,"number":25,"question":"30歲男性，無抽菸喝酒病史，因數個月來聲音逐漸變差而就診，經喉內視鏡檢查如下圖，最可能之診斷為何？","options":["(A) 喉部類澱粉沉積症（laryngeal amyloidosis）","(B) 喉乳突瘤病（laryngeal papillomatosis）","(C) Wegener氏肉芽腫（Wegener granulomatosis）","(D) 肺外結核（extrapulmonary tuberculosis）"],"answer":1,"image":"md6-115-2-25.jpeg"},{"id":"md6-115-2-26","subject":"md6","topic":"喉科學與頭頸腫瘤","meta":"115年第2次第26題","year":115,"session":2,"number":26,"question":"針對口咽癌的檢體，驗出下列何項生物標誌時，表示該腫瘤與人類乳突病毒相關？","options":["(A) p16","(B) p21","(C) p53","(D) Rb"],"answer":0,"image":""},{"id":"md6-115-2-27","subject":"md6","topic":"喉科學與頭頸腫瘤","meta":"115年第2次第27題","year":115,"session":2,"number":27,"question":"有關喉癌，下列敘述何者正確？","options":["(A) 聲帶原位癌的治療方式是以器官保存的放射治療為主","(B) 聲帶原位癌若採用手術治療，需一併切除聲帶韌帶（vocal ligament）","(C) 早期的聲門上癌（supraglottic cancer）可考慮合併執行選擇性淋巴廓清術（elective neck dissection）","(D) 對T4喉癌來說，同步放化療（concurrent chemoradiation therapy）與手術治療加術後放化療的存活率相當"],"answer":2,"image":""},{"id":"md6-115-2-28","subject":"md6","topic":"產科-一般產科","meta":"115年第2次第28題","year":115,"session":2,"number":28,"question":"關於自然流產，下列敘述何者正確？","options":["(A) 約80%的自然流產發生在懷孕的前12週","(B) 第一孕期流產中最常見的染色體異常為Trisomy 21","(C) 第一孕期流產中染色體異常的比率約占75%","(D) Antiphospholipid antibody syndrome的孕婦發生自然流產的機率與正常孕婦一樣"],"answer":0,"image":""},{"id":"md6-115-2-29","subject":"md6","topic":"產科-一般產科","meta":"115年第2次第29題","year":115,"session":2,"number":29,"question":"下列何者與子宮外孕methotrexate藥物治療失敗最有關？","options":["(A) 多胎次（multigravida）","(B) 2.5 cm大小的子宮外孕","(C) 之前有子宮外孕病史","(D) 血清β-人類絨毛膜刺激激素（β-subunit human chorionic gonadotropin, β-hCG）值為7,500 mIU/mL"],"answer":3,"image":""},{"id":"md6-115-2-30","subject":"md6","topic":"產科-一般產科","meta":"115年第2次第30題","year":115,"session":2,"number":30,"question":"有關分娩的發生機制，下列敘述何者錯誤？","options":["(A) 子宮肌肉層的oxytocin receptor會明顯增加","(B) 子宮頸hyaluronan synthase isoenzymes的表現增加","(C) 子宮頸collagen fibrils的橫徑變細，其間空隙變小，變更緊密","(D) 子宮頸有許多發炎細胞聚集，引發子宮頸軟化"],"answer":2,"image":""},{"id":"md6-115-2-31","subject":"md6","topic":"產科-一般產科","meta":"115年第2次第31題","year":115,"session":2,"number":31,"question":"下列何者可能增加剖腹產後嘗試陰道生產的成功機率？","options":["(A) 自發分娩（spontaneous labor）","(B) 肥胖（obesity）","(C) 高齡產婦（increased maternal age）","(D) 妊娠大於41週（gestational age ＞41 weeks）"],"answer":0,"image":""},{"id":"md6-115-2-32","subject":"md6","topic":"產科-一般產科","meta":"115年第2次第32題","year":115,"session":2,"number":32,"question":"有關肩難產的新生兒合併症，下列敘述何者錯誤？","options":["(A) hypoxic ischemic encephalopathy（HIE）","(B) cardiac arrest","(C) brachial plexus injury","(D) caput succedaneum"],"answer":3,"image":""},{"id":"md6-115-2-33","subject":"md6","topic":"產科-高危險妊娠","meta":"115年第2次第33題","year":115,"session":2,"number":33,"question":"造成母血中胎兒游離性基因（cell-free fetal DNA）篩檢結果不正確的原因，下列敘述何者錯誤？","options":["(A) 胎盤特異性鑲嵌體（confined placental mosaicism）","(B) 母親罹患癌症","(C) 母血中胎兒游離性基因比率低於4%","(D) 母親年齡高於40歲"],"answer":3,"image":""},{"id":"md6-115-2-34","subject":"md6","topic":"產科-高危險妊娠","meta":"115年第2次第34題","year":115,"session":2,"number":34,"question":"關於唐氏症篩檢，下列敘述何者錯誤？","options":["(A) 若篩檢結果為高風險，不可當做終止妊娠之診斷依據","(B) 第一和第二孕期唐氏症篩檢對於雙胞胎妊娠檢驗效果較差","(C) 胎兒頸部透明帶厚度，如大於3mm則染色體異常的風險增加","(D) 通常第一孕期唐氏症篩檢指標包含胎兒頸部透明帶厚度、母血清α胎兒蛋白（AFP）和β-人類絨毛膜刺激激素（β-hCG）濃度"],"answer":3,"image":""},{"id":"md6-115-2-35","subject":"md6","topic":"產科-高危險妊娠","meta":"115年第2次第35題","year":115,"session":2,"number":35,"question":"29歲女性妊娠32週，主訴僵直性下腹疼痛，自外院轉診至醫學中心緊急剖腹產，手術中情況如圖所示，該病人最可能的診斷為何？","options":["(A) placental abruption","(B) placenta previa with bleeding","(C) vasa previa","(D) uterine inversion"],"answer":0,"image":"md6-115-2-35.jpeg"},{"id":"md6-115-2-36","subject":"md6","topic":"產科-高危險妊娠","meta":"115年第2次第36題","year":115,"session":2,"number":36,"question":"36歲孕婦G1P0，本次懷孕接受一般健保給付之產檢項目，產檢結果皆為正常，無家族病史。目前妊娠34週，該孕婦主訴今日胎動明顯減少，而至門診求診。該孕婦按照安排，依序接受無壓力測試（nonstress test）及超音波檢查，結果如下：①無壓力測試：於20分鐘內出現3次心跳加速（accelerations），心跳加速超過15bpm且持續15秒鐘以上。②超音波檢查：於檢查之30分鐘內，出現兩次持續30秒鐘的呼吸運動，且有一次以上軀幹由伸直再回到彎曲的狀態，胎動共一次，羊水量正常（一個羊水腔直徑超過2公分）。如何解讀目前胎兒生物生理評估（biophysical profile）的結果？","options":["(A) 得分10分，為一正常無窒息的胎兒（normal, nonasphyxiated fetus）","(B) 得分8分，為一正常無窒息的胎兒（normal, nonasphyxiated fetus）","(C) 得分6分，疑似胎兒窒息（possible fetal asphyxia）","(D) 得分2分，強烈懷疑胎兒窒息（almost certain fetal asphyxia）"],"answer":1,"image":""},{"id":"md6-115-2-37","subject":"md6","topic":"產科-高危險妊娠","meta":"115年第2次第37題","year":115,"session":2,"number":37,"question":"關於子癇前症的危險因子，下列何者風險最低？","options":["(A) 孕婦初次妊娠","(B) 抽菸孕婦","(C) 子癇前症病史孕婦","(D) 高齡孕婦（大於35歲）"],"answer":1,"image":""},{"id":"md6-115-2-38","subject":"md6","topic":"產科-高危險妊娠","meta":"115年第2次第38題","year":115,"session":2,"number":38,"question":"關於子癇前症高血壓危象時，緊急控制血壓的藥物使用，下列何者最不適當？","options":["(A) Hydralazine靜脈注射","(B) Labetalol靜脈注射","(C) Nifedipine舌下給與","(D) 治療目標值為收縮壓低於160毫米汞柱（mmHg）、舒張壓維持在90至110毫米汞柱（mmHg）"],"answer":2,"image":""},{"id":"md6-115-2-39","subject":"md6","topic":"產科-高危險妊娠","meta":"115年第2次第39題","year":115,"session":2,"number":39,"question":"關於子癇前症引起腎小球毛細血管內皮病（glomerular capillary endotheliosis）之敘述，下列何者最不適當？","options":["(A) 內皮細胞（endothelial cell）腫脹","(B) 內皮膜孔（endothelial fenestra）變大","(C) 足細胞小足（pedicels）緊靠","(D) 腎小球（glomeruli）變大"],"answer":1,"image":""},{"id":"md6-115-2-40","subject":"md6","topic":"婦科-腫瘤","meta":"115年第2次第40題","year":115,"session":2,"number":40,"question":"下列何者是上皮性（epithelial）的良性卵巢腫瘤？","options":["(A) mucinous cystadenoma","(B) theca lutein","(C) dysgerminoma","(D) benign cystic teratoma"],"answer":0,"image":""},{"id":"md6-115-2-41","subject":"md6","topic":"婦科-手術學與診斷技術","meta":"115年第2次第41題","year":115,"session":2,"number":41,"question":"腹腔鏡手術時，宜避免傷到腹壁血管，如圖★號所指血管為何？","options":["(A) deep inferior epigastric artery","(B) superficial circumflex iliac artery","(C) deep circumflex iliac artery","(D) external iliac artery"],"answer":0,"image":"md6-115-2-41.jpeg"},{"id":"md6-115-2-42","subject":"md6","topic":"婦科-手術學與診斷技術","meta":"115年第2次第42題","year":115,"session":2,"number":42,"question":"子宮鏡手術中發現如圖所示，何者為最可能之診斷？","options":["(A) 子宮中膈","(B) 子宮內膜息肉","(C) 雙角子宮","(D) 子宮肌腺瘤"],"answer":1,"image":"md6-115-2-42.jpeg"},{"id":"md6-115-2-43","subject":"md6","topic":"婦科-良性腫瘤與內膜異位","meta":"115年第2次第43題","year":115,"session":2,"number":43,"question":"深層浸潤性子宮內膜異位症（deeply infiltrative endometriosis），是指浸潤在腹膜下方至少幾毫米的深度？","options":["(A) 1","(B) 3","(C) 5","(D) 10"],"answer":2,"image":""},{"id":"md6-115-2-44","subject":"md6","topic":"婦科-生殖內分泌","meta":"115年第2次第44題","year":115,"session":2,"number":44,"question":"對於先天性雄性素不敏感症（congenital androgen insensitivity）之患者，下列敘述何者最不適當？","options":["(A) 睪丸通常位於鼠蹊部","(B) 睪丸會產生Müllerian-inhibiting substance","(C) 輸卵管與子宮會退化","(D) 罹患睪丸癌的風險增加，故睪丸應在青春期前切除"],"answer":3,"image":""},{"id":"md6-115-2-45","subject":"md6","topic":"婦科-手術學與診斷技術","meta":"115年第2次第45題","year":115,"session":2,"number":45,"question":"有關婦科腹腔鏡手術的準備，下列何者最不適當？","options":["(A) 常用的是頭低腳高的姿勢","(B) 肚臍是最常用的打氣進入點","(C) 腹部的壓力一般設在8～10 mmHg","(D) 置入套管時，腹部的壓力可設在25～30 mmHg"],"answer":2,"image":""},{"id":"md6-115-2-46","subject":"md6","topic":"婦科-生殖道感染與先天異常","meta":"115年第2次第46題","year":115,"session":2,"number":46,"question":"有關外生殖器尖形濕疣（genital warts）的治療，下列何者最不適當？","options":["(A) 雷射燒灼治療","(B) imiquimod","(C) doxycycline","(D) 冷凍治療"],"answer":2,"image":""},{"id":"md6-115-2-47","subject":"md6","topic":"婦科-生殖道感染與先天異常","meta":"115年第2次第47題","year":115,"session":2,"number":47,"question":"細菌性陰道炎（bacterial vaginosis）最不會引起下列那一種併發症？","options":["(A) 骨盆腔發炎","(B) 剖腹產手術後的子宮內膜炎","(C) 懷孕時早期破水","(D) 反覆流產"],"answer":3,"image":""},{"id":"md6-115-2-48","subject":"md6","topic":"婦科-腫瘤","meta":"115年第2次第48題","year":115,"session":2,"number":48,"question":"關於子宮肌瘤的敘述，下列何者最正確？","options":["(A) 25～29歲女性無論是否接受過子宮肌瘤切除手術，子宮肌瘤發生機率都高於40～44歲女性","(B) 10年期間曾經生育過之女性，新診斷之子宮肌瘤的機率較未生育者低","(C) 子宮肌瘤切除手術之前使用過GnRH-a來減少肌瘤體積者，術後再發生子宮肌瘤的機會比術前未使用GnRH-a者來得低","(D) 以超音波追蹤比較曾接受腹腔鏡子宮肌瘤切除術和開腹子宮肌瘤切除之病患，腹腔鏡子宮肌瘤切除術後子宮肌瘤的再發生率較低"],"answer":1,"image":""},{"id":"md6-115-2-49","subject":"md6","topic":"婦科-腫瘤","meta":"115年第2次第49題","year":115,"session":2,"number":49,"question":"關於卵巢癌的期別，下列敘述何者正確？","options":["(A) 單側卵巢癌，開刀時弄破，為IA期","(B) 單側卵巢癌，轉移至腹腔之腫瘤小於2公分，為IIA期","(C) 雙側卵巢癌，轉移至腹腔之腫瘤大於2公分，及肝臟表面為IIIC期","(D) 卵巢癌合併胸水，不需細胞學證明，為IV期"],"answer":2,"image":""},{"id":"md6-115-2-50","subject":"md6","topic":"婦科-腫瘤","meta":"115年第2次第50題","year":115,"session":2,"number":50,"question":"子宮內膜癌最常見復發位置為：","options":["(A) 肺部","(B) 腹腔","(C) 淋巴腺","(D) 陰道"],"answer":3,"image":""},{"id":"md6-115-2-51","subject":"md6","topic":"婦科-腫瘤","meta":"115年第2次第51題","year":115,"session":2,"number":51,"question":"關於complete hydatidiform mole，下列敘述何者錯誤？","options":["(A) 相對於正常妊娠週數，80%呈現懷孕子宮過大","(B) 染色體以雙倍體（diploid）出現","(C) molar chromosomes全部來自於父親","(D) 相較於partial mole更容易進展成侵襲性癌症"],"answer":0,"image":""},{"id":"md6-115-2-52","subject":"md6","topic":"婦科-腫瘤","meta":"115年第2次第52題","year":115,"session":2,"number":52,"question":"有關陰道癌的敘述，下列何者錯誤？","options":["(A) 鱗狀上皮細胞癌是最常見的組織學型態","(B) 陰道癌治療以化學治療為主","(C) 異常陰道出血或分泌物是最常見的症狀","(D) 與人類乳突病毒感染有關"],"answer":1,"image":""},{"id":"md6-115-2-53","subject":"md6","topic":"婦科-腫瘤","meta":"115年第2次第53題","year":115,"session":2,"number":53,"question":"關於子宮頸癌的放射線治療，下列敘述何者錯誤？","options":["(A) 傳統2D放射線治療中的“A”點的位置，在子宮頸外口上2公分，子宮頸管外3公分","(B) “A”點的放射劑量通常達到7,000至8,000 cGy","(C) 術後放射線治療對於骨盆淋巴轉移的病人可以減少骨盆復發率","(D) 放射線治療合併化學治療可以增強其療效"],"answer":0,"image":""},{"id":"md6-115-2-54","subject":"md6","topic":"婦科-生殖內分泌","meta":"115年第2次第54題","year":115,"session":2,"number":54,"question":"有關多囊卵巢症候群，下列敘述何者正確？","options":["(A) 體內的雄性素主要來自腎上腺分泌","(B) 不會增加內膜癌風險","(C) 手術為治療優先選項","(D) 使用避孕藥治療，可降低來自卵巢及腎上腺素分泌的雄性素"],"answer":3,"image":""},{"id":"md6-115-2-55","subject":"md6","topic":"婦科-生殖內分泌","meta":"115年第2次第55題","year":115,"session":2,"number":55,"question":"關於更年期症候群之血管動力變化（vasomotor symptoms）引起之相關熱潮紅（hot flashes）等症狀，下列敘述何者錯誤？","options":["(A) 停經前後發生症狀的時間可以長達十年","(B) 肥胖的女性因為體脂肪較高，所以症狀較正常體重的更年期婦女輕微","(C) 全身性的投予荷爾蒙是最有效的治療","(D) 瑜珈，針灸，戒菸和冷氣有助於減輕症狀"],"answer":1,"image":""},{"id":"md6-115-2-56","subject":"md6","topic":"婦科-生殖內分泌","meta":"115年第2次第56題","year":115,"session":2,"number":56,"question":"有關年齡影響生殖能力的敘述，下列何者錯誤？","options":["(A) 女性生育能力在40歲左右加速下降","(B) 流產的原因可能是因為卵子有絲分裂異常，造成非整數體（aneuploidy）","(C) 女性隨著年齡增加生殖能力下降，可能是因為不正常的卵子比率增加","(D) 男性在50歲以前，對生殖能力的影響相對較小"],"answer":1,"image":""},{"id":"md6-115-2-57","subject":"md6","topic":"婦科-尿失禁與骨盆腔脫垂","meta":"115年第2次第57題","year":115,"session":2,"number":57,"question":"用來治療急迫性尿失禁的mirabegron，屬於β-3 agonist，其主要副作用為何？","options":["(A) 口乾（dry mouth）","(B) 便秘（constipation）","(C) 高血壓（hypertension）","(D) 失智（dementia）"],"answer":2,"image":""},{"id":"md6-115-2-58","subject":"md6","topic":"復健-神經復健","meta":"115年第2次第58題","year":115,"session":2,"number":58,"question":"下列何者是外傷性腦傷之原發性損傷（primary injury）？","options":["(A) 瀰漫性軸突損傷（diffuse axonal injury）","(B) 顱內壓上升（increased intracranial pressure）","(C) 腫塊效應（mass effect）","(D) 腦水腫（brain edema）"],"answer":0,"image":""},{"id":"md6-115-2-59","subject":"md6","topic":"復健-神經復健","meta":"115年第2次第59題","year":115,"session":2,"number":59,"question":"有關深腓神經（deep peroneal nerve）和淺腓神經（superficial peroneal nerve），下列敘述何者錯誤？","options":["(A) 深腓神經支配的感覺範圍分布於足背（dorsum of the foot）的大部分皮膚，除了第一、二腳趾中間（sparing first web space）的皮膚","(B) 淺腓神經支配的感覺範圍分布於小腿外側的下三分之二（lower two-thirds of the lateral leg）的皮膚","(C) 脛前肌（tibialis anterior muscle）由深腓神經所支配","(D) 腓長肌（peroneus longus muscle）由淺腓神經所支配"],"answer":0,"image":""},{"id":"md6-115-2-60","subject":"md6","topic":"復健-兒童與一般復健","meta":"115年第2次第60題","year":115,"session":2,"number":60,"question":"下列脊髓脊膜膨出（myelomeningocele）的併發症中，何者最少見？","options":["(A) 神經性膀胱問題","(B) 水腦症","(C) 脊柱側彎","(D) 阿諾德－希阿里畸形（Arnold-Chiari malformation）"],"answer":2,"image":""},{"id":"md6-115-2-61","subject":"md6","topic":"復健-神經復健","meta":"115年第2次第61題","year":115,"session":2,"number":61,"question":"一位外傷性腦傷病患做復健治療時，為了評估他的記憶力及認知功能損傷情況，最常用的工具為下列何者？","options":["(A) 改良阿修氏量表（Modified Ashworth scale）","(B) 布氏階段（Brunnstrom stage）評估表","(C) 瑞秋洛斯阿米哥斯量表（Rancho Los Amigos levels）","(D) 功能獨立性測量（functional independence measure）"],"answer":2,"image":""},{"id":"md6-115-2-62","subject":"md6","topic":"復健-物理因子治療與評估","meta":"115年第2次第62題","year":115,"session":2,"number":62,"question":"有關急性傷害疼痛處理，下列敘述何者錯誤？","options":["(A) 所謂PRICE，其中I是冰敷（ice）","(B) 所謂POLICE，其中OL是適度負荷（optimal loading）","(C) 所謂PEACE，其中A是避免使用抗發炎治療模式（avoid anti-inflammatory modalities）","(D) 所謂LOVE，其中E是抬高（elevation）"],"answer":3,"image":""},{"id":"md6-115-2-63","subject":"md6","topic":"復健-截肢與義肢輔具","meta":"115年第2次第63題","year":115,"session":2,"number":63,"question":"有關膝下截肢義肢，下列敘述何者錯誤？","options":["(A) 套筒製作時應避免太緊造成疼痛甚至破皮","(B) 膝下義肢都必須有綁帶或吊帶來當作懸吊系統","(C) 義足目的是要提供踝關節與腳掌的功能，可以依據截肢者的需求來選擇類型","(D) 套筒製作時應避免太鬆導致殘肢在套筒內有活塞運動（piston movement）"],"answer":1,"image":""},{"id":"md6-115-2-64","subject":"md6","topic":"復健-骨骼肌肉損傷與疾患","meta":"115年第2次第64題","year":115,"session":2,"number":64,"question":"有關類風濕性關節炎（rheumatoid arthritis, RA），下列敘述何者最不適當？","options":["(A) 是一種自體免疫疾病，特徵是患者免疫系統功能低下","(B) 會造成滑膜的慢性發炎，甚至引起軟骨的侵蝕與骨頭的破壞","(C) 抗瓜胺酸化蛋白抗體（anti-citrullinated protein antibodies, ACPAs）呈現陽性反應的病人，一般病情較嚴重且進行較為快速","(D) 容易造成關節的攣縮及扭曲變形"],"answer":0,"image":""},{"id":"md6-115-2-65","subject":"md6","topic":"復健-心肺復健與運動處方","meta":"115年第2次第65題","year":115,"session":2,"number":65,"question":"有關使用沙包來作為吸氣肌訓練方式的敘述，下列何者最恰當？","options":["(A) 開始重量過重會造成吸氣肌疲勞","(B) 沙包應放在低位肋骨處","(C) 主要在訓練外肋間肌","(D) 能夠承受約5分鐘，即可逐漸增加重量"],"answer":0,"image":""},{"id":"md6-115-2-66","subject":"md6","topic":"復健-兒童與一般復健","meta":"115年第2次第66題","year":115,"session":2,"number":66,"question":"關於兒童肌肉骨骼系統（musculoskeletal system）疾病的敘述，下列何者錯誤？","options":["(A) 髖關節發育不良（developmental dysplasia of the hip）患者以女童較多","(B) 先天性肌肉性斜頸症（congenital muscular torticollis）患者以男童較多","(C) 先天性肌肉性斜頸症（congenital muscular torticollis）患者要評估有無髖關節發育不良（developmental dysplasia of the hip）的發生","(D) 先天性肌肉性斜頸症（congenital muscular torticollis）的發生率較髖關節發育不良（developmental dysplasia of the hip）的發生率為低"],"answer":[0,1,2,3],"image":"","answer_note":"送分:第66題一律給分 (原公告答案 D)"},{"id":"md6-115-2-67","subject":"md6","topic":"復健-神經復健","meta":"115年第2次第67題","year":115,"session":2,"number":67,"question":"關於腦性麻痺（cerebral palsy）患者的行走能力，下列敘述何者最不適當？","options":["(A) 2歲之前可以獨立坐是正向的預測因子（positive predictor）","(B) 4歲時還不會獨立坐是負向的預測因子（negative predictor）","(C) 大部分的腦性麻痺患者都無行走能力","(D) 18～24個月大時，小於3項的原始反射（primitive reflex）是正向的預測因子（positive predictor）"],"answer":2,"image":""},{"id":"md6-115-2-68","subject":"md6","topic":"復健-兒童與一般復健","meta":"115年第2次第68題","year":115,"session":2,"number":68,"question":"下列何者不是巴氏量表的評估內容？","options":["(A) 穿衣","(B) 煮飯","(C) 上下樓梯","(D) 平地走動"],"answer":1,"image":""},{"id":"md6-115-2-69","subject":"md6","topic":"復健-兒童與一般復健","meta":"115年第2次第69題","year":115,"session":2,"number":69,"question":"比起一般的手動輪椅，下列關於電動輪椅（power wheelchair）的好處，何者最適當？","options":["(A) 方便運輸","(B) 減少上肢的累積性傷害","(C) 適合於運動時使用","(D) 方便學習上手"],"answer":1,"image":""},{"id":"md6-115-2-70","subject":"md6","topic":"復健-骨骼肌肉損傷與疾患","meta":"115年第2次第70題","year":115,"session":2,"number":70,"question":"下列何者不常使用於治療乳癌病人之淋巴水腫？","options":["(A) 淋巴引流（manual lymphatic drainage）","(B) 循環治療（intermittent pneumatic compression）","(C) 減壓治療（decompression therapy）","(D) 壓力臂套的使用"],"answer":2,"image":""},{"id":"md6-115-2-71","subject":"md6","topic":"復健-物理因子治療與評估","meta":"115年第2次第71題","year":115,"session":2,"number":71,"question":"電療（electrotherapy）常用於疼痛復健。有關電療之敘述，下列何者錯誤？","options":["(A) 臨床常用之電療，包括經皮神經電刺激（transcutaneous electrical nerve stimulation, TENS）與干擾波（interferential current, IFC）等","(B) 經皮神經電刺激（transcutaneous electrical nerve stimulation, TENS）所使用的原理為門閥理論（gate control theory）","(C) 適應症包括下背痛、退化性關節炎、血栓性靜脈炎、肌腱炎、韌帶扭傷等","(D) 電療禁止使用於頸動脈竇附近，以免引起心律不整"],"answer":2,"image":""},{"id":"md6-115-2-72","subject":"md6","topic":"復健-骨骼肌肉損傷與疾患","meta":"115年第2次第72題","year":115,"session":2,"number":72,"question":"54歲女性病人左肩疼痛約2個月，經左肩關節X光及左肩超音波檢查如附圖，最可能之診斷為何？","options":["(A) 肩旋轉環帶破裂（rotator cuff tear）","(B) 肩旋轉環帶鈣化性肌腱變性（calcific tendinosis）","(C) 肩部退化性關節炎（degenerative arthritis）","(D) 肩旋轉環帶外生骨疣（exostosis）"],"answer":1,"image":"md6-115-2-72.jpeg"},{"id":"md6-115-2-73","subject":"md6","topic":"復健-骨骼肌肉損傷與疾患","meta":"115年第2次第73題","year":115,"session":2,"number":73,"question":"65歲女性病人主訴慢性膝蓋疼痛且最近症狀加劇，X光及磁振造影檢查如圖，最可能之診斷為何？","options":["(A) rheumatoid arthritis（RA）","(B) spontaneous osteonecrosis of knee（SONK）","(C) pigmented villonodular synovitis（PVNS）","(D) osteogenic sarcoma（OGS）"],"answer":1,"image":"md6-115-2-73.jpeg"},{"id":"md6-115-2-74","subject":"md6","topic":"復健-神經復健","meta":"115年第2次第74題","year":115,"session":2,"number":74,"question":"20歲男性病人車禍後2天出現右側肢體無力而被送到急診，頭頸部磁振造影檢查，發現他左中腦動脈區域有小面積急性中風，左內頸動脈則有一半月形管壁增厚及管腔狹窄（T1加權影像合併脂肪抑制），其最可能的診斷為何？","options":["(A) 頸動脈硬化合併血栓剝落","(B) 急性顳動脈炎（temporal arteritis）","(C) 頸動脈剝離（carotid dissection）","(D) 頸動脈體腫瘤（carotid body tumor）"],"answer":2,"image":"md6-115-2-74.jpeg"},{"id":"md6-115-2-75","subject":"md6","topic":"產科-高危險妊娠","meta":"115年第2次第75題","year":115,"session":2,"number":75,"question":"36歲懷孕女性，因陰道出血而求診，到急診時生命徵象為：心跳120/min，呼吸20/min，血壓86/54 mmHg。過去病史曾有子宮外孕導致右側輸卵管切除，此次懷孕是透過體外人工受精（in vitro fertilization）而受孕，下列敘述何者最適當？","options":["(A) 單一的beta-human chorionic gonadotropin（β-hCG）檢驗數值無法有效區別正常懷孕與子宮外孕","(B) 陰道出血如無伴隨腹痛，可排除子宮外孕","(C) 此病人在急診可以給與methotrexate治療","(D) 超音波顯示子宮內妊娠（intrauterine pregnancy），可排除子宮外孕"],"answer":0,"image":""},{"id":"md6-115-2-76","subject":"md6","topic":"喉科學與頭頸腫瘤","meta":"115年第2次第76題","year":115,"session":2,"number":76,"question":"關於咽後膿瘍（retropharyngeal abscess）的敘述，下列何者最不適當？","options":["(A) 魚刺扎傷喉嚨、齒源性感染，皆有可能引起咽後膿瘍","(B) 頸部X光影像的典型表現為在第二頸椎前與氣管間距離變寬（prevertebral widening）","(C) 如病人呼吸困難且無法躺平，應給與鎮靜藥物再做電腦斷層檢查","(D) 大部分病人需要抗生素治療及外科介入"],"answer":2,"image":""},{"id":"md6-115-2-77","subject":"md6","topic":"復健-神經復健","meta":"115年第2次第77題","year":115,"session":2,"number":77,"question":"67歲病人，下背痛兩個月，止痛藥治療無效，由家人帶至急診求診，經病史詢問及身體檢查發現，懷疑為馬尾症候群（cauda equina syndrome），下列敘述何者最不適當？","options":["(A) 下肢會有不等程度運動與感覺喪失","(B) 不常見有尿滯留","(C) 單側或雙側的坐骨神經痛","(D) 在會陰部有感覺異常"],"answer":1,"image":""},{"id":"md6-115-2-78","subject":"md6","topic":"醫學倫理與法規","meta":"115年第2次第78題","year":115,"session":2,"number":78,"question":"關於醫師指導醫學生之臨床學習過程，下列作法何者最適當？","options":["(A) 醫師繁忙時，得由實習醫學生代為取得病人接受治療之知情同意（informed consent）","(B) 當病人已經被麻醉時，醫學生可逕行為病人進行內診（pelvic examination）不需取得同意","(C) 在沒有醫師監督下，醫學生操作簡單的醫療程序，仍需取得病人同意","(D) 若病人已死亡，醫學生可逕行為死者進行內診（pelvic examination）"],"answer":2,"image":""},{"id":"md6-115-2-79","subject":"md6","topic":"醫學倫理與法規","meta":"115年第2次第79題","year":115,"session":2,"number":79,"question":"「知情同意（informed consent）」是在落實生命倫理四原則中的那一個原則？","options":["(A) 尊重自主原則（respect for autonomy）","(B) 行善原則（beneficence）","(C) 不傷害原則（nonmaleficence）","(D) 正義原則（justice）"],"answer":0,"image":""},{"id":"md6-115-2-80","subject":"md6","topic":"醫學倫理與法規","meta":"115年第2次第80題","year":115,"session":2,"number":80,"question":"35歲女性，先生為獨子，已有二女，目前病人正接受試管嬰兒治療，想在胚胎植入前先作胚胎切片，確認染色體是否正常。下列敘述何者最適當？","options":["(A) 醫師不能幫她作胚胎切片，因為她可能會因此刻意選擇植入胚胎的性別","(B) 醫師應幫她作胚胎切片，因為這是病患的權利","(C) 醫師能幫她作胚胎切片，但不能告訴她胚胎性別","(D) 醫師能幫她作胚胎切片，但須向衛生福利部通報"],"answer":1,"image":""}];
